std::wstring FileNameFromPath(const std::wstring& full_path)
{
    const auto separator = full_path.find_last_of(L"\\/");
    if (separator == std::wstring::npos)
    {
        return full_path;
    }

    return full_path.substr(separator + 1);
}

std::wstring NarrowToWide(const std::string& value)
{
    if (value.empty())
    {
        return {};
    }

    const auto count = MultiByteToWideChar(CP_UTF8, 0, value.data(), static_cast<int>(value.size()), nullptr, 0);
    std::wstring output(static_cast<std::size_t>(count), L'\0');
    MultiByteToWideChar(CP_UTF8, 0, value.data(), static_cast<int>(value.size()), output.data(), count);
    return output;
}

std::string NormalizeResourcePath(std::string value)
{
    std::transform(
        value.begin(),
        value.end(),
        value.begin(),
        [](unsigned char ch)
        {
            if (ch == '\\')
            {
                return '/';
            }

            return static_cast<char>(std::tolower(ch));
        });
    return value;
}

std::optional<std::string> TryMapGloveModelPathToSharedArmsResourcePath(std::string model_path)
{
    model_path = NormalizeResourcePath(std::move(model_path));
    if (model_path.empty())
    {
        return std::nullopt;
    }

    const auto is_view_model = model_path.find("/v_") != std::string::npos;
    const auto is_world_model = model_path.find("/w_") != std::string::npos;
    if (!is_view_model && !is_world_model)
    {
        return std::nullopt;
    }

    std::string family;
    if (model_path.find("glove_bloodhound_brokenfang") != std::string::npos)
    {
        family = "glove_brokenfang";
    }
    else if (model_path.find("glove_bloodhound_hydra") != std::string::npos)
    {
        family = "glove_hydra";
    }
    else if (model_path.find("glove_handwrap") != std::string::npos)
    {
        family = "glove_handwrap";
    }
    else if (model_path.find("glove_bloodhound") != std::string::npos)
    {
        family = "glove_bloodhound";
    }
    else if (model_path.find("glove_fingerless") != std::string::npos)
    {
        family = "glove_fingerless";
    }
    else if (model_path.find("glove_hardknuckle") != std::string::npos)
    {
        family = "glove_hardknuckle";
    }
    else if (model_path.find("glove_sporty") != std::string::npos)
    {
        family = "glove_sporty";
    }
    else if (model_path.find("glove_slick") != std::string::npos)
    {
        family = "glove_slick";
    }
    else if (model_path.find("glove_motorcycle") != std::string::npos)
    {
        family = "glove_motorcycle";
    }
    else if (model_path.find("glove_specialist") != std::string::npos)
    {
        family = "glove_specialist";
    }
    else
    {
        return std::nullopt;
    }

    return "characters/models/shared/arms/" + family + "/" +
        (is_world_model ? "w_" : "v_") + family + ".vmdl_c";
}

bool ResourcePathMatches(const std::string& actual_path, const std::string& expected_path)
{
    return !actual_path.empty() &&
        !expected_path.empty() &&
        NormalizeResourcePath(actual_path) == NormalizeResourcePath(expected_path);
}

std::optional<std::string> TryMapModelPathToResourcePath(std::string model_path);

std::optional<std::string> TryCanonicalizeModelIdentityPath(std::string model_path)
{
    if (model_path.empty())
    {
        return std::nullopt;
    }

    if (const auto resource_path = TryMapModelPathToResourcePath(model_path); resource_path.has_value())
    {
        return NormalizeResourcePath(*resource_path);
    }

    return NormalizeResourcePath(std::move(model_path));
}

bool ModelIdentityPathMatches(const std::string& actual_path, const std::string& expected_path)
{
    const auto canonical_actual = TryCanonicalizeModelIdentityPath(actual_path);
    const auto canonical_expected = TryCanonicalizeModelIdentityPath(expected_path);
    if (canonical_actual.has_value() && canonical_expected.has_value())
    {
        return *canonical_actual == *canonical_expected;
    }

    return ResourcePathMatches(actual_path, expected_path);
}

bool EndsWithInsensitive(const std::string& value, const std::string_view suffix)
{
    if (value.size() < suffix.size())
    {
        return false;
    }

    const auto offset = value.size() - suffix.size();
    for (std::size_t index = 0; index < suffix.size(); ++index)
    {
        if (static_cast<char>(std::tolower(static_cast<unsigned char>(value[offset + index]))) !=
            static_cast<char>(std::tolower(static_cast<unsigned char>(suffix[index]))))
        {
            return false;
        }
    }

    return true;
}

std::wstring ResolveCurrentProcessPathForGameContent()
{
    std::wstring buffer(MAX_PATH, L'\0');
    const auto length = GetModuleFileNameW(nullptr, buffer.data(), static_cast<DWORD>(buffer.size()));
    buffer.resize(length);
    return buffer;
}

std::optional<std::filesystem::path> TryResolveGameContentRoot()
{
    static std::optional<std::filesystem::path> cached_root;
    static bool attempted = false;
    if (attempted)
    {
        return cached_root;
    }

    attempted = true;
    auto probe = std::filesystem::path(ResolveCurrentProcessPathForGameContent()).parent_path();
    while (!probe.empty())
    {
        const auto content_root = probe / L"csgo";
        if (std::filesystem::exists(content_root / L"pak01_dir.vpk"))
        {
            cached_root = content_root;
            break;
        }

        const auto parent = probe.parent_path();
        if (parent == probe)
        {
            break;
        }

        probe = parent;
    }

    return cached_root;
}

template <typename T>
bool ReadStreamBinaryValue(std::ifstream& stream, T& value)
{
    stream.read(reinterpret_cast<char*>(&value), sizeof(T));
    return static_cast<bool>(stream);
}

bool ReadNullTerminatedString(std::ifstream& stream, std::string& value)
{
    value.clear();
    while (true)
    {
        char ch = '\0';
        stream.read(&ch, sizeof(ch));
        if (!stream)
        {
            return false;
        }

        if (ch == '\0')
        {
            return true;
        }

        value.push_back(ch);
    }
}

std::optional<VpkHeader> ReadVpkHeader(std::ifstream& stream)
{
    std::uint32_t signature = 0;
    if (!ReadStreamBinaryValue(stream, signature) || signature != kVpkSignature)
    {
        return std::nullopt;
    }

    VpkHeader header {};
    if (!ReadStreamBinaryValue(stream, header.version) || !ReadStreamBinaryValue(stream, header.tree_size))
    {
        return std::nullopt;
    }

    if (header.version >= 2)
    {
        if (!ReadStreamBinaryValue(stream, header.file_data_section_size))
        {
            return std::nullopt;
        }

        std::uint32_t archive_md5_size = 0;
        std::uint32_t other_md5_size = 0;
        std::uint32_t signature_size = 0;
        if (!ReadStreamBinaryValue(stream, archive_md5_size) ||
            !ReadStreamBinaryValue(stream, other_md5_size) ||
            !ReadStreamBinaryValue(stream, signature_size))
        {
            return std::nullopt;
        }

        header.header_size = 28;
    }

    return header;
}

std::filesystem::path BuildVpkArchivePath(
    const std::filesystem::path& directory_vpk_path,
    const std::uint16_t archive_index)
{
    auto archive_path = directory_vpk_path;
    auto stem = directory_vpk_path.stem().wstring();
    if (stem.ends_with(L"_dir"))
    {
        stem.erase(stem.size() - 4);
    }

    std::wstringstream name;
    name << stem << L'_' << std::setw(3) << std::setfill(L'0') << archive_index << directory_vpk_path.extension().wstring();
    archive_path.replace_filename(name.str());
    return archive_path;
}

std::optional<std::vector<std::uint8_t>> ReadBinaryFromVpk(
    const std::filesystem::path& directory_vpk_path,
    const std::string_view requested_entry_path)
{
    std::ifstream directory_stream(directory_vpk_path, std::ios::binary);
    if (!directory_stream.is_open())
    {
        return std::nullopt;
    }

    const auto header = ReadVpkHeader(directory_stream);
    if (!header.has_value())
    {
        return std::nullopt;
    }

    const auto tree_end_offset = header->header_size + header->tree_size;
    std::string extension;
    std::string directory;
    std::string filename;
    std::optional<VpkEntryLocation> match;

    while (ReadNullTerminatedString(directory_stream, extension) && !extension.empty())
    {
        while (ReadNullTerminatedString(directory_stream, directory) && !directory.empty())
        {
            while (ReadNullTerminatedString(directory_stream, filename) && !filename.empty())
            {
                VpkEntryLocation entry {};
                std::uint32_t crc = 0;
                std::uint16_t terminator = 0;
                if (!ReadStreamBinaryValue(directory_stream, crc) ||
                    !ReadStreamBinaryValue(directory_stream, entry.preload_bytes) ||
                    !ReadStreamBinaryValue(directory_stream, entry.archive_index) ||
                    !ReadStreamBinaryValue(directory_stream, entry.offset) ||
                    !ReadStreamBinaryValue(directory_stream, entry.length) ||
                    !ReadStreamBinaryValue(directory_stream, terminator))
                {
                    return std::nullopt;
                }

                if (terminator != 0xFFFF)
                {
                    return std::nullopt;
                }

                entry.preload_offset = static_cast<std::uint64_t>(directory_stream.tellg());
                static_cast<void>(crc);

                std::string full_path;
                if (!directory.empty() && directory != " ")
                {
                    full_path.append(directory);
                    full_path.push_back('/');
                }

                full_path.append(filename);
                if (!extension.empty() && extension != " ")
                {
                    full_path.push_back('.');
                    full_path.append(extension);
                }

                if (NormalizeResourcePath(full_path) == NormalizeResourcePath(std::string(requested_entry_path)))
                {
                    match = entry;
                }

                if (entry.preload_bytes > 0)
                {
                    directory_stream.seekg(entry.preload_bytes, std::ios::cur);
                    if (!directory_stream)
                    {
                        return std::nullopt;
                    }
                }

                if (match.has_value())
                {
                    break;
                }
            }

            if (match.has_value())
            {
                break;
            }
        }

        if (match.has_value())
        {
            break;
        }
    }

    if (!match.has_value())
    {
        return std::nullopt;
    }

    std::vector<std::uint8_t> payload;
    payload.reserve(static_cast<std::size_t>(match->preload_bytes) + static_cast<std::size_t>(match->length));

    if (match->preload_bytes > 0)
    {
        directory_stream.clear();
        directory_stream.seekg(static_cast<std::streamoff>(match->preload_offset), std::ios::beg);
        if (!directory_stream)
        {
            return std::nullopt;
        }

        std::vector<std::uint8_t> preload(static_cast<std::size_t>(match->preload_bytes));
        if (!preload.empty())
        {
            directory_stream.read(reinterpret_cast<char*>(preload.data()), static_cast<std::streamsize>(preload.size()));
            if (!directory_stream)
            {
                return std::nullopt;
            }

            payload.insert(payload.end(), preload.begin(), preload.end());
        }
    }

    if (match->length == 0)
    {
        return payload;
    }

    const auto payload_path = match->archive_index == kVpkDirectoryArchiveIndex
        ? directory_vpk_path
        : BuildVpkArchivePath(directory_vpk_path, match->archive_index);
    std::ifstream payload_stream(payload_path, std::ios::binary);
    if (!payload_stream.is_open())
    {
        return std::nullopt;
    }

    const auto payload_offset = match->archive_index == kVpkDirectoryArchiveIndex
        ? static_cast<std::uint64_t>(tree_end_offset) + header->file_data_section_size + match->offset
        : static_cast<std::uint64_t>(match->offset);
    payload_stream.seekg(static_cast<std::streamoff>(payload_offset), std::ios::beg);
    if (!payload_stream)
    {
        return std::nullopt;
    }

    std::vector<std::uint8_t> archive_payload(static_cast<std::size_t>(match->length));
    payload_stream.read(reinterpret_cast<char*>(archive_payload.data()), static_cast<std::streamsize>(archive_payload.size()));
    if (!payload_stream)
    {
        return std::nullopt;
    }

    payload.insert(payload.end(), archive_payload.begin(), archive_payload.end());
    return payload;
}

std::string HashStringsIdentity(const std::vector<std::string>& values)
{
    std::string flattened;
    for (const auto& value : values)
    {
        flattened.append(value);
        flattened.push_back('\0');
    }
    return flattened;
}

std::uint64_t HashFlattenedIdentity(const std::string& flattened)
{
    std::uint64_t hash = 1469598103934665603ull;
    for (const auto ch : flattened)
    {
        hash ^= static_cast<std::uint8_t>(ch);
        hash *= 1099511628211ull;
    }
    return hash;
}

bool LooksLikeSkeletonBoneName(std::string value)
{
    value = NormalizeResourcePath(std::move(value));
    if (value.size() < 4 || value.size() > 64)
    {
        return false;
    }

    if (!std::all_of(
            value.begin(),
            value.end(),
            [](unsigned char ch)
            {
                return std::isalnum(ch) != 0 || ch == '_' || ch == '.';
            }))
    {
        return false;
    }

    constexpr std::array<std::string_view, 11> prefixes {{
        "hand_",
        "finger_",
        "thumb_",
        "index_",
        "middle",
        "ring",
        "pinky",
        "wrist",
        "forearm",
        "arm_",
        "shoulder",
    }};

    return std::any_of(
        prefixes.begin(),
        prefixes.end(),
        [&value](const std::string_view prefix)
        {
            return value.starts_with(prefix);
        });
}

std::vector<std::string> ExtractPrintableStrings(const std::vector<std::uint8_t>& bytes)
{
    std::vector<std::string> strings;
    std::string current;
    for (const auto byte : bytes)
    {
        if (byte >= 32 && byte <= 126)
        {
            current.push_back(static_cast<char>(byte));
            continue;
        }

        if (current.size() >= 4)
        {
            strings.push_back(current);
        }
        current.clear();
    }

    if (current.size() >= 4)
    {
        strings.push_back(current);
    }

    return strings;
}

ModelResourceMetadata BuildModelResourceMetadata(const std::vector<std::uint8_t>& bytes)
{
    ModelResourceMetadata metadata {};
    const auto strings = ExtractPrintableStrings(bytes);
    std::unordered_set<std::string> unique_materials;
    std::unordered_set<std::string> unique_bones;
    bool saw_skeleton_marker = false;

    for (const auto& raw : strings)
    {
        auto normalized = NormalizeResourcePath(raw);
        if (normalized.find("skeleton") != std::string::npos)
        {
            saw_skeleton_marker = true;
        }

        if (EndsWithInsensitive(normalized, ".vmat") || EndsWithInsensitive(normalized, ".vmat_c"))
        {
            unique_materials.insert(std::move(normalized));
            continue;
        }

        if (LooksLikeSkeletonBoneName(normalized))
        {
            unique_bones.insert(std::move(normalized));
        }
    }

    metadata.material_resources.assign(unique_materials.begin(), unique_materials.end());
    std::sort(metadata.material_resources.begin(), metadata.material_resources.end());
    metadata.material_resource_identity_resolved = !metadata.material_resources.empty();
    if (metadata.material_resource_identity_resolved)
    {
        metadata.material_resource_identity_hash =
            HashFlattenedIdentity(HashStringsIdentity(metadata.material_resources));
    }

    metadata.bone_names.assign(unique_bones.begin(), unique_bones.end());
    std::sort(metadata.bone_names.begin(), metadata.bone_names.end());
    metadata.skeleton_identity_resolved = saw_skeleton_marker && metadata.bone_names.size() >= 8;
    if (metadata.skeleton_identity_resolved)
    {
        metadata.skeleton_identity_hash = HashFlattenedIdentity(HashStringsIdentity(metadata.bone_names));
    }

    return metadata;
}

std::optional<std::string> TryMapModelPathToResourcePath(std::string model_path)
{
    model_path = NormalizeResourcePath(std::move(model_path));
    if (model_path.empty())
    {
        return std::nullopt;
    }

    if (const auto glove_resource_path = TryMapGloveModelPathToSharedArmsResourcePath(model_path);
        glove_resource_path.has_value())
    {
        return glove_resource_path;
    }

    if (EndsWithInsensitive(model_path, ".vmdl_c") || EndsWithInsensitive(model_path, ".vmat_c"))
    {
        return model_path;
    }

    if (EndsWithInsensitive(model_path, ".vmdl"))
    {
        model_path.append("_c");
        return model_path;
    }

    constexpr std::string_view v_prefix = "models/weapons/v_models/arms/";
    constexpr std::string_view w_prefix = "models/weapons/w_models/arms/";
    if (model_path.starts_with(v_prefix))
    {
        model_path = "characters/models/shared/arms/" + model_path.substr(v_prefix.size());
    }
    else if (model_path.starts_with(w_prefix))
    {
        model_path = "characters/models/shared/arms/" + model_path.substr(w_prefix.size());
    }

    if (EndsWithInsensitive(model_path, ".mdl"))
    {
        model_path.erase(model_path.size() - 4);
        model_path.append(".vmdl_c");
        return model_path;
    }

    return std::nullopt;
}

const ModelResourceMetadata* TryResolveModelResourceMetadata(const std::string& model_path)
{
    static std::unordered_map<std::string, ModelResourceMetadata> metadata_cache;

    const auto resource_path = TryMapModelPathToResourcePath(model_path);
    if (!resource_path.has_value())
    {
        return nullptr;
    }

    if (const auto cached = metadata_cache.find(*resource_path); cached != metadata_cache.end())
    {
        return &cached->second;
    }

    const auto content_root = TryResolveGameContentRoot();
    if (!content_root.has_value())
    {
        return nullptr;
    }

    std::optional<std::vector<std::uint8_t>> bytes;
    const auto loose_file_path = *content_root / std::filesystem::path(NarrowToWide(*resource_path));
    if (std::filesystem::exists(loose_file_path))
    {
        std::ifstream stream(loose_file_path, std::ios::binary);
        if (stream.good())
        {
            bytes = std::vector<std::uint8_t>(
                std::istreambuf_iterator<char>(stream),
                std::istreambuf_iterator<char>());
        }
    }

    if (!bytes.has_value())
    {
        bytes = ReadBinaryFromVpk(*content_root / L"pak01_dir.vpk", *resource_path);
    }

    if (!bytes.has_value())
    {
        return nullptr;
    }

    auto [iterator, inserted] = metadata_cache.emplace(*resource_path, BuildModelResourceMetadata(*bytes));
    return inserted || iterator != metadata_cache.end() ? &iterator->second : nullptr;
}

bool IsReadableAscii(const char* value)
{
    if (value == nullptr)
    {
        return false;
    }

    std::size_t length = 0;
    while (length < 128)
    {
        char raw = '\0';
        if (!SafeReadValue(value + length, raw))
        {
            return false;
        }

        const auto ch = static_cast<unsigned char>(raw);
        if (ch == '\0')
        {
            break;
        }

        if (ch < 32 || ch > 126)
        {
            return false;
        }

        ++length;
    }

    return length >= 4 && length < 128;
}

bool PointerInModule(const ModuleSpan& module, const void* pointer)
{
    const auto value = reinterpret_cast<std::uintptr_t>(pointer);
    const auto begin = reinterpret_cast<std::uintptr_t>(module.base);
    const auto end = begin + module.size;
    return begin <= value && value < end;
}

std::optional<ModuleSpan> GetModuleSpan(HMODULE module)
{
    if (module == nullptr)
    {
        return std::nullopt;
    }

    MODULEINFO info {};
    if (!GetModuleInformation(GetCurrentProcess(), module, &info, sizeof(info)))
    {
        const auto* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(module);
        if (!IsReadablePointer(dos) || dos->e_magic != IMAGE_DOS_SIGNATURE)
        {
            return std::nullopt;
        }

        const auto nt_header_address =
            reinterpret_cast<const std::uint8_t*>(module) + static_cast<std::size_t>(dos->e_lfanew);
        const auto* nt = reinterpret_cast<const IMAGE_NT_HEADERS64*>(nt_header_address);
        if (!IsReadablePointer(nt) ||
            nt->Signature != IMAGE_NT_SIGNATURE ||
            nt->OptionalHeader.SizeOfImage == 0)
        {
            return std::nullopt;
        }

        return ModuleSpan {
            reinterpret_cast<std::uint8_t*>(module),
            static_cast<std::size_t>(nt->OptionalHeader.SizeOfImage),
        };
    }

    return ModuleSpan {
        static_cast<std::uint8_t*>(info.lpBaseOfDll),
        static_cast<std::size_t>(info.SizeOfImage),
    };
}

HMODULE GetModuleFromAddress(const void* address)
{
    if (address == nullptr)
    {
        return nullptr;
    }

    HMODULE module = nullptr;
    if (!GetModuleHandleExW(
            GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
            reinterpret_cast<LPCWSTR>(address),
            &module))
    {
        return nullptr;
    }

    return module;
}

std::wstring GetModuleFileNameOnly(HMODULE module)
{
    if (module == nullptr)
    {
        return {};
    }

    std::wstring buffer(MAX_PATH, L'\0');
    const auto length = GetModuleFileNameW(module, buffer.data(), static_cast<DWORD>(buffer.size()));
    buffer.resize(length);
    return FileNameFromPath(buffer);
}

void* FollowJumpStubs(void* address)
{
    auto* current = static_cast<std::uint8_t*>(address);
    for (int depth = 0; depth < 4; ++depth)
    {
        if (current == nullptr)
        {
            return nullptr;
        }

        __try
        {
            if (current[0] == 0xE9)
            {
                const auto rel = *reinterpret_cast<std::int32_t*>(current + 1);
                current = current + 5 + rel;
                continue;
            }

            if (current[0] == 0xEB)
            {
                const auto rel = *reinterpret_cast<std::int8_t*>(current + 1);
                current = current + 2 + rel;
                continue;
            }

            if (current[0] == 0xFF && current[1] == 0x25)
            {
                const auto rel = *reinterpret_cast<std::int32_t*>(current + 2);
                auto** target = reinterpret_cast<void***>(current + 6 + rel);
                void* resolved_target = nullptr;
                return target != nullptr && SafeReadValue(target, resolved_target) ? resolved_target : nullptr;
            }

            if (current[0] == 0x48 && current[1] == 0xB8 &&
                current[10] == 0xFF && current[11] == 0xE0)
            {
                void* resolved_target = nullptr;
                std::memcpy(&resolved_target, current + 2, sizeof(resolved_target));
                current = static_cast<std::uint8_t*>(resolved_target);
                continue;
            }

            if (current[0] == 0x49 && current[1] == 0xBB &&
                current[10] == 0x41 && current[11] == 0xFF && current[12] == 0xE3)
            {
                void* resolved_target = nullptr;
                std::memcpy(&resolved_target, current + 2, sizeof(resolved_target));
                current = static_cast<std::uint8_t*>(resolved_target);
                continue;
            }

            if (current[0] == 0x48 && current[1] == 0xB8 &&
                current[10] == 0x50 && current[11] == 0xC3)
            {
                void* resolved_target = nullptr;
                std::memcpy(&resolved_target, current + 2, sizeof(resolved_target));
                current = static_cast<std::uint8_t*>(resolved_target);
                continue;
            }
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {
            return nullptr;
        }

        break;
    }

    return current;
}

bool LooksLikeInterfaceList(const ModuleSpan& module, InterfaceReg* candidate)
{
    if (candidate == nullptr || !PointerInModule(module, candidate))
    {
        return false;
    }

    int count = 0;
    auto* current = candidate;
    while (current != nullptr && count < 32)
    {
        if (!PointerInModule(module, current))
        {
            return false;
        }

        void* create_fn = nullptr;
        const char* name = nullptr;
        InterfaceReg* next = nullptr;
        if (!SafeReadValue(&current->create_fn, create_fn) ||
            !SafeReadValue(&current->name, name) ||
            !SafeReadValue(&current->next, next))
        {
            return false;
        }

        if (!PointerInModule(module, create_fn) || !PointerInModule(module, name))
        {
            return false;
        }

        if (!IsReadableAscii(name))
        {
            return false;
        }

        current = next;
        ++count;
    }

    return count > 0;
}

std::vector<std::string> EnumerateInterfacesFromModule(HMODULE module, const wchar_t* module_name)
{
    std::vector<std::string> names;

    const auto module_span = GetModuleSpan(module);
    if (!module_span.has_value())
    {
        return names;
    }

    const auto create_interface = reinterpret_cast<std::uint8_t*>(GetProcAddress(module, "CreateInterface"));
    if (create_interface == nullptr)
    {
        return names;
    }

    auto* body = static_cast<std::uint8_t*>(FollowJumpStubs(create_interface));
    if (body == nullptr || !PointerInModule(*module_span, body))
    {
        return names;
    }

    std::set<std::string> unique_names;
    for (std::size_t offset = 0; offset < 0x80; ++offset)
    {
        auto* cursor = body + offset;
        if (!PointerInModule(*module_span, cursor + 7))
        {
            break;
        }

        InterfaceReg* candidate = nullptr;

        if ((cursor[0] == 0x48 && cursor[1] == 0x8B && cursor[2] == 0x0D) ||
            (cursor[0] == 0x48 && cursor[1] == 0x8D && cursor[2] == 0x0D) ||
            (cursor[0] == 0x4C && cursor[1] == 0x8D && cursor[2] == 0x05) ||
            (cursor[0] == 0x4C && cursor[1] == 0x8B && cursor[2] == 0x05))
        {
            const auto rel = *reinterpret_cast<std::int32_t*>(cursor + 3);
            auto** indirect = reinterpret_cast<void***>(cursor + 7 + rel);
            if (PointerInModule(*module_span, indirect))
            {
                void* indirect_value = nullptr;
                if (SafeReadValue(indirect, indirect_value))
                {
                    candidate = reinterpret_cast<InterfaceReg*>(indirect_value);
                }
                if (!LooksLikeInterfaceList(*module_span, candidate))
                {
                    candidate = reinterpret_cast<InterfaceReg*>(indirect);
                }
            }
        }

        if (!LooksLikeInterfaceList(*module_span, candidate))
        {
            continue;
        }

        for (auto* current = candidate; current != nullptr;)
        {
            const char* name = nullptr;
            if (!SafeReadValue(&current->name, name) ||
                !PointerInModule(*module_span, name))
            {
                InterfaceReg* next = nullptr;
                if (!SafeReadValue(&current->next, next))
                {
                    break;
                }
                current = next;
                continue;
            }

            std::string safe_name;
            if (!SafeReadCString(name, safe_name, 128) || !IsReadableAscii(name))
            {
                InterfaceReg* next = nullptr;
                if (!SafeReadValue(&current->next, next))
                {
                    break;
                }
                current = next;
                continue;
            }

            unique_names.emplace(std::move(safe_name));

            InterfaceReg* next = nullptr;
            if (!SafeReadValue(&current->next, next))
            {
                break;
            }
            current = next;
        }

        break;
    }

    names.assign(unique_names.begin(), unique_names.end());
    if (!names.empty())
    {
        std::wstringstream stream;
        stream << L"Enumerated " << names.size() << L" interface names from " << module_name << L".";
        nskinzcs2::Logger::Info(stream.str());
    }

    return names;
}

std::wstring JoinInterfaceSummary(const std::vector<std::string>& names, const std::size_t max_names)
{
    std::wstringstream stream;
    for (std::size_t index = 0; index < names.size() && index < max_names; ++index)
    {
        if (index != 0)
        {
            stream << L", ";
        }
        stream << NarrowToWide(names[index]);
    }

    if (names.size() > max_names)
    {
        stream << L", ...";
    }

    return stream.str();
}

std::wstring FormatPointer(const void* pointer)
{
    std::wstringstream stream;
    stream << L"0x" << std::hex << std::uppercase << reinterpret_cast<std::uintptr_t>(pointer);
    return stream.str();
}

std::wstring FormatModuleOwnerWithOffset(const void* address)
{
    if (address == nullptr)
    {
        return L"<null>";
    }

    const auto module = GetModuleFromAddress(address);
    const auto module_name = GetModuleFileNameOnly(module);
    const auto module_span = GetModuleSpan(module);

    std::wstringstream stream;
    stream << (!module_name.empty() ? module_name : L"<unknown>");
    if (module_span.has_value() && PointerInModule(*module_span, address))
    {
        const auto offset =
            reinterpret_cast<std::uintptr_t>(address) -
            reinterpret_cast<std::uintptr_t>(module_span->base);
        stream << L"+0x" << std::hex << std::uppercase << offset
            << std::dec << std::nouppercase;
    }
    else
    {
        stream << L"@" << FormatPointer(address);
    }

    return stream.str();
}

struct InterfaceOwnerSummary
{
    std::wstring dominant_module;
    std::size_t dominant_count = 0;
    std::size_t slot_count = 0;
};

struct FileSystemInterfaceCandidateGroup
{
    void* address = nullptr;
    std::vector<std::string> versions;
};

CreateInterfaceFn ResolveModuleCreateInterfaceFactory(const wchar_t* module_name)
{
    const auto module = GetModuleHandleW(module_name);
    if (module == nullptr)
    {
        return nullptr;
    }

    return reinterpret_cast<CreateInterfaceFn>(GetProcAddress(module, "CreateInterface"));
}

const std::vector<std::string>& GetFileSystemVersionCandidatesForDiagnostics()
{
    static const std::vector<std::string> s_versions = []()
    {
        auto discovered = EnumerateInterfacesFromModule(GetModuleHandleW(L"filesystem_stdio.dll"), L"filesystem_stdio.dll");
        auto versions = nskinzcs2::RuntimeController::FilterVersionCandidates(discovered, "VFileSystem", 1, 64);
        if (versions.empty())
        {
            versions = nskinzcs2::RuntimeController::BuildVersionCandidates("VFileSystem", 1, 64, {"VFileSystem017"});
        }
        return versions;
    }();
    return s_versions;
}

InterfaceOwnerSummary CollectInterfaceOwnerSummary(
    void* interface_pointer,
    const std::size_t slot_begin,
    const std::size_t slot_end_exclusive)
{
    InterfaceOwnerSummary summary {};
    if (interface_pointer == nullptr || slot_end_exclusive <= slot_begin)
    {
        return summary;
    }

    void** vtable = nullptr;
    if (!SafeReadValue(interface_pointer, vtable) || vtable == nullptr)
    {
        return summary;
    }

    summary.slot_count = slot_end_exclusive - slot_begin;
    std::vector<std::pair<std::wstring, std::size_t>> buckets;
    buckets.reserve(summary.slot_count);

    for (std::size_t slot = slot_begin; slot < slot_end_exclusive; ++slot)
    {
        void* entry = nullptr;
        if (!SafeReadValue(vtable + slot, entry) || entry == nullptr)
        {
            continue;
        }

        const auto* followed = FollowJumpStubs(entry);
        const auto owner = GetModuleFileNameOnly(GetModuleFromAddress(followed != nullptr ? followed : entry));
        auto bucket = std::find_if(
            buckets.begin(),
            buckets.end(),
            [&owner](const auto& candidate)
            {
                return _wcsicmp(candidate.first.c_str(), owner.c_str()) == 0;
            });
        if (bucket == buckets.end())
        {
            buckets.emplace_back(owner, 1);
            bucket = buckets.end() - 1;
        }
        else
        {
            ++bucket->second;
        }

        if (bucket->second > summary.dominant_count)
        {
            summary.dominant_module = bucket->first;
            summary.dominant_count = bucket->second;
        }
    }

    return summary;
}

std::vector<FileSystemInterfaceCandidateGroup> ResolveFileSystemInterfaceCandidates(
    CreateInterfaceFn factory,
    const std::vector<std::string>& versions)
{
    std::vector<FileSystemInterfaceCandidateGroup> groups;
    if (factory == nullptr)
    {
        return groups;
    }

    std::unordered_map<void*, std::size_t> group_index_by_pointer;
    for (const auto& version : versions)
    {
        void* pointer = factory(version.c_str(), nullptr);
        if (pointer == nullptr)
        {
            continue;
        }

        const auto existing = group_index_by_pointer.find(pointer);
        if (existing == group_index_by_pointer.end())
        {
            group_index_by_pointer.emplace(pointer, groups.size());
            groups.push_back(FileSystemInterfaceCandidateGroup {
                pointer,
                {version},
            });
            continue;
        }

        groups[existing->second].versions.push_back(version);
    }

    return groups;
}

void LogFileSystemInterfaceCandidateIdentity(
    const wchar_t* source_label,
    const std::vector<std::string>& versions,
    void* interface_pointer)
{
    if (source_label == nullptr || interface_pointer == nullptr)
    {
        return;
    }

    const auto version_summary = JoinInterfaceSummary(versions, 6);
    const auto dedupe_key =
        std::wstring(source_label) + L"|" + FormatPointer(interface_pointer) + L"|" + version_summary;

    static std::mutex s_dedupe_mutex;
    static std::unordered_set<std::wstring> s_seen_keys;
    {
        std::scoped_lock lock(s_dedupe_mutex);
        if (!s_seen_keys.emplace(dedupe_key).second)
        {
            return;
        }
    }

    void** vtable = nullptr;
    void* slot0_target = nullptr;
    void* slot78_target = nullptr;
    if (!SafeReadValue(interface_pointer, vtable) || vtable == nullptr)
    {
        nskinzcs2::Logger::Warn(
            std::wstring(L"VFileSystem candidate [") + source_label + L"]: iface=" +
            FormatPointer(interface_pointer) + L", vtable unreadable.");
        return;
    }

    SafeReadValue(vtable + 0, slot0_target);
    SafeReadValue(vtable + kFileSystemDiagnosticHotSlotIndex, slot78_target);

    const auto* slot0_body = FollowJumpStubs(slot0_target);
    const auto* slot78_body = FollowJumpStubs(slot78_target);
    const auto vtable_owner = GetModuleFileNameOnly(GetModuleFromAddress(vtable));
    const auto slot0_owner = GetModuleFileNameOnly(GetModuleFromAddress(slot0_target));
    const auto slot0_body_owner = GetModuleFileNameOnly(GetModuleFromAddress(slot0_body != nullptr ? slot0_body : slot0_target));
    const auto slot78_owner = GetModuleFileNameOnly(GetModuleFromAddress(slot78_target));
    const auto slot78_body_owner = GetModuleFileNameOnly(GetModuleFromAddress(slot78_body != nullptr ? slot78_body : slot78_target));
    const auto owner_summary = CollectInterfaceOwnerSummary(
        interface_pointer,
        kFileSystemDiagnosticFirstSlotIndex,
        kFileSystemDiagnosticLastSlotIndex + 1);

    std::wstringstream stream;
    stream << L"VFileSystem candidate [" << source_label << L"]: versions="
           << (version_summary.empty() ? L"<none>" : version_summary)
           << L", iface=" << FormatPointer(interface_pointer)
           << L", vtable=" << FormatPointer(vtable)
           << L", vtable_owner=" << (vtable_owner.empty() ? L"<unknown>" : vtable_owner)
           << L", slot0=" << FormatPointer(slot0_target)
           << L", slot0_owner=" << (slot0_owner.empty() ? L"<unknown>" : slot0_owner)
           << L", slot0_body=" << FormatPointer(slot0_body != nullptr ? slot0_body : slot0_target)
           << L", slot0_body_owner=" << (slot0_body_owner.empty() ? L"<unknown>" : slot0_body_owner)
           << L", slot78=" << FormatPointer(slot78_target)
           << L", slot78_owner=" << (slot78_owner.empty() ? L"<unknown>" : slot78_owner)
           << L", slot78_body=" << FormatPointer(slot78_body != nullptr ? slot78_body : slot78_target)
           << L", slot78_body_owner=" << (slot78_body_owner.empty() ? L"<unknown>" : slot78_body_owner)
           << L", dominant=" << (owner_summary.dominant_module.empty() ? L"<unknown>" : owner_summary.dominant_module)
           << L"(" << owner_summary.dominant_count << L"/" << owner_summary.slot_count << L")";
    nskinzcs2::Logger::Info(stream.str());
}

void LogFileSystemInterfaceCandidatesFromFactory(
    const wchar_t* source_label,
    CreateInterfaceFn factory,
    const std::vector<std::string>& versions)
{
    if (source_label == nullptr)
    {
        return;
    }

    const auto groups = ResolveFileSystemInterfaceCandidates(factory, versions);
    if (groups.empty())
    {
        static std::mutex s_empty_mutex;
        static std::unordered_set<std::wstring> s_empty_sources;
        std::scoped_lock lock(s_empty_mutex);
        if (s_empty_sources.emplace(source_label).second)
        {
            nskinzcs2::Logger::Warn(
                std::wstring(L"VFileSystem candidate radar [") + source_label +
                L"]: no interfaces resolved from this factory.");
        }
        return;
    }

    for (const auto& group : groups)
    {
        LogFileSystemInterfaceCandidateIdentity(source_label, group.versions, group.address);
    }
}

std::wstring FormatByteSequence(const std::uint8_t* bytes, const std::size_t count)
{
    if (bytes == nullptr || count == 0)
    {
        return {};
    }

    std::wstringstream stream;
    for (std::size_t index = 0; index < count; ++index)
    {
        if (index != 0)
        {
            stream << L' ';
        }

        stream << std::hex << std::uppercase << std::setw(2) << std::setfill(L'0')
            << static_cast<unsigned int>(bytes[index]);
    }

    return stream.str();
}

const wchar_t* MemoryTypeToString(const DWORD type) noexcept
{
    switch (type)
    {
    case MEM_IMAGE:
        return L"MEM_IMAGE";
    case MEM_MAPPED:
        return L"MEM_MAPPED";
    case MEM_PRIVATE:
        return L"MEM_PRIVATE";
    default:
        return L"MEM_UNKNOWN";
    }
}

std::wstring DescribeReadableMemoryRegion(const void* pointer, const std::size_t preview_bytes = 24)
{
    if (pointer == nullptr)
    {
        return L"region={pointer=null}";
    }

    MEMORY_BASIC_INFORMATION memory_info {};
    if (VirtualQuery(pointer, &memory_info, sizeof(memory_info)) != sizeof(memory_info))
    {
        return L"region={pointer=" + FormatPointer(pointer) + L", query=failed}";
    }

    std::wstringstream stream;
    stream << L"region={pointer=" << FormatPointer(pointer)
        << L", base=" << FormatPointer(memory_info.BaseAddress)
        << L", alloc_base=" << FormatPointer(memory_info.AllocationBase)
        << L", size=0x" << std::hex << std::uppercase << memory_info.RegionSize
        << L", protect=0x" << (memory_info.Protect & 0xFFu)
        << std::dec << std::nouppercase
        << L", type=" << MemoryTypeToString(memory_info.Type);

    if (const auto module = GetModuleFromAddress(pointer); module != nullptr)
    {
        const auto module_name = GetModuleFileNameOnly(module);
        if (!module_name.empty())
        {
            stream << L", module=" << module_name;
        }
    }

    if (preview_bytes != 0 && IsReadablePointer(pointer))
    {
        std::array<std::uint8_t, 24> bytes {};
        const auto byte_count = std::min<std::size_t>(preview_bytes, bytes.size());
        if (byte_count != 0 && SafeReadBytes(pointer, bytes.data(), byte_count))
        {
            stream << L", bytes=[" << FormatByteSequence(bytes.data(), byte_count) << L"]";
        }
    }

    stream << L"}";
    return stream.str();
}

std::optional<ModuleSpan> GetTextSectionSpan(HMODULE module)
{
    const auto module_span = GetModuleSpan(module);
    if (!module_span.has_value())
    {
        return std::nullopt;
    }

    auto* base = module_span->base;
    auto* dos_header = reinterpret_cast<IMAGE_DOS_HEADER*>(base);
    if (dos_header == nullptr || dos_header->e_magic != IMAGE_DOS_SIGNATURE)
    {
        return module_span;
    }

    auto* nt_headers = reinterpret_cast<IMAGE_NT_HEADERS*>(base + dos_header->e_lfanew);
    if (nt_headers == nullptr || nt_headers->Signature != IMAGE_NT_SIGNATURE)
    {
        return module_span;
    }

    auto* section = IMAGE_FIRST_SECTION(nt_headers);
    for (WORD index = 0; index < nt_headers->FileHeader.NumberOfSections; ++index, ++section)
    {
        char name[9] {};
        std::memcpy(name, section->Name, 8);
        if (std::strcmp(name, ".text") == 0)
        {
            return ModuleSpan {
                base + section->VirtualAddress,
                static_cast<std::size_t>(std::max(section->Misc.VirtualSize, section->SizeOfRawData)),
            };
        }
    }

    return module_span;
}

std::vector<int> ParsePattern(const char* pattern)
{
    std::vector<int> bytes;
    std::istringstream stream(pattern != nullptr ? pattern : "");
    std::string token;
    while (stream >> token)
    {
        if (token == "?" || token == "??")
        {
            bytes.push_back(-1);
            continue;
        }

        bytes.push_back(std::stoi(token, nullptr, 16));
    }

    return bytes;
}

std::uint8_t* FindUniquePattern(const ModuleSpan& span, const char* pattern)
{
    const auto bytes = ParsePattern(pattern);
    if (bytes.empty() || span.base == nullptr || span.size < bytes.size())
    {
        return nullptr;
    }

    std::uint8_t* only_match = nullptr;
    std::size_t match_count = 0;
    for (std::size_t offset = 0; offset + bytes.size() <= span.size; ++offset)
    {
        bool matched = true;
        for (std::size_t index = 0; index < bytes.size(); ++index)
        {
            if (bytes[index] != -1 && span.base[offset + index] != static_cast<std::uint8_t>(bytes[index]))
            {
                matched = false;
                break;
            }
        }
        if (matched)
        {
            only_match = span.base + offset;
            if (++match_count > 1)
            {
                return nullptr;
            }
        }
    }
    return match_count == 1 ? only_match : nullptr;
}

template <typename T>
bool SafeReadValue(const void* address, T& out)
{
    if (address == nullptr)
    {
        return false;
    }

    __try
    {
        out = *reinterpret_cast<const T*>(address);
        return true;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }
}

bool SafeIncrementResourceBindingRefCount(
    const std::uint64_t binding,
    LONG& before,
    LONG& after) noexcept
{
    before = 0;
    after = 0;
    if (binding == 0)
    {
        return false;
    }

    auto* const counter = reinterpret_cast<volatile LONG*>(
        static_cast<std::uintptr_t>(binding) + 0x20u);
    if (!SafeReadValue(const_cast<const LONG*>(counter), before) ||
        before < 0 || before >= 0x3FFFFFFF)
    {
        return false;
    }

    __try
    {
        after = InterlockedIncrement(counter);
        return after == before + 1;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        after = 0;
        return false;
    }
}

template <typename T>
bool SafeReadField(const void* base, const std::ptrdiff_t offset, T& out)
{
    if (base == nullptr)
    {
        return false;
    }

    return SafeReadValue(reinterpret_cast<const std::uint8_t*>(base) + offset, out);
}

bool SafeReadBytes(const void* address, void* destination, const std::size_t size)
{
    if (address == nullptr || destination == nullptr)
    {
        return false;
    }

    __try
    {
        std::memcpy(destination, address, size);
        return true;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }
}

bool SafeReadCString(const char* address, std::string& out, const std::size_t max_length = 512)
{
    out.clear();
    if (address == nullptr || max_length == 0)
    {
        return false;
    }

    for (std::size_t index = 0; index < max_length; ++index)
    {
        char ch = '\0';
        if (!SafeReadValue(address + index, ch))
        {
            out.clear();
            return false;
        }

        if (ch == '\0')
        {
            return !out.empty();
        }

        out.push_back(ch);
    }

    out.clear();
    return false;
}

bool SafeWriteBytes(void* address, const void* source, const std::size_t size)
{
    if (address == nullptr || source == nullptr)
    {
        return false;
    }

    __try
    {
        std::memcpy(address, source, size);
        return true;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }
}

template <typename T>
bool SafeWriteValue(void* address, const T& value)
{
    return SafeWriteBytes(address, &value, sizeof(T));
}

template <typename T>
bool SafeWriteField(void* base, const std::ptrdiff_t offset, const T& value)
{
    if (base == nullptr)
    {
        return false;
    }

    return SafeWriteValue(reinterpret_cast<std::uint8_t*>(base) + offset, value);
}

bool SafeWriteFixedString(void* base, const std::ptrdiff_t offset, const std::size_t capacity, const std::string& value)
{
    if (base == nullptr || capacity == 0)
    {
        return false;
    }

    std::string storage = value.substr(0, capacity - 1);
    storage.push_back('\0');
    storage.resize(capacity, '\0');
    return SafeWriteBytes(reinterpret_cast<std::uint8_t*>(base) + offset, storage.data(), storage.size());
}

bool SafeReadFixedString(const void* base, const std::ptrdiff_t offset, const std::size_t capacity, std::string& value)
{
    value.clear();
    if (base == nullptr || capacity == 0)
    {
        return false;
    }

    std::vector<char> storage(capacity, '\0');
    if (!SafeReadBytes(reinterpret_cast<const std::uint8_t*>(base) + offset, storage.data(), storage.size()))
    {
        return false;
    }

    const auto terminator = std::find(storage.begin(), storage.end(), '\0');
    value.assign(storage.begin(), terminator);
    return true;
}

struct MsvcRttiCompleteObjectLocator
{
    std::uint32_t signature = 0;
    std::uint32_t offset = 0;
    std::uint32_t cd_offset = 0;
    std::int32_t type_descriptor_rva = 0;
    std::int32_t class_descriptor_rva = 0;
    std::int32_t self_rva = 0;
};

std::string SimplifyMsvcDecoratedTypeName(const std::string& raw_name)
{
    if (raw_name.size() < 6 ||
        raw_name[0] != '.' ||
        raw_name[1] != '?' ||
        raw_name[2] != 'A')
    {
        return raw_name;
    }

    const auto start =
        (raw_name.rfind(".?AV", 0) == 0 ||
         raw_name.rfind(".?AU", 0) == 0 ||
         raw_name.rfind(".?AT", 0) == 0 ||
         raw_name.rfind(".?AW", 0) == 0)
            ? std::size_t {4}
            : std::string::npos;
    if (start == std::string::npos)
    {
        return raw_name;
    }

    const auto end = raw_name.find("@@", start);
    if (end == std::string::npos || end <= start)
    {
        return raw_name;
    }

    std::vector<std::string> parts;
    std::stringstream part_stream(raw_name.substr(start, end - start));
    std::string part;
    while (std::getline(part_stream, part, '@'))
    {
        if (!part.empty())
        {
            parts.push_back(part);
        }
    }

    if (parts.empty())
    {
        return raw_name.substr(start, end - start);
    }

    std::reverse(parts.begin(), parts.end());
    std::string simplified_name;
    for (std::size_t index = 0; index < parts.size(); ++index)
    {
        if (index != 0)
        {
            simplified_name += "::";
        }
        simplified_name += parts[index];
    }

    return simplified_name;
}

std::wstring BuildRuntimeEntityRttiDescriptor(const void* object)
{
    std::wstringstream stream;
    stream << L"rtti{object=" << FormatPointer(object);

    if (object == nullptr)
    {
        stream << L", status=null}";
        return stream.str();
    }

    void** vtable = nullptr;
    if (!SafeReadValue(object, vtable) || vtable == nullptr)
    {
        stream << L", status=vtable_unreadable}";
        return stream.str();
    }

    stream << L", vtable=" << FormatPointer(vtable);
    if (const auto vtable_module = GetModuleFromAddress(vtable); vtable_module != nullptr)
    {
        const auto module_name = GetModuleFileNameOnly(vtable_module);
        if (!module_name.empty())
        {
            stream << L", vtable_module=" << module_name;
        }
    }

    void* locator = nullptr;
    if (!SafeReadValue(vtable - 1, locator) || locator == nullptr)
    {
        stream << L", status=locator_unreadable}";
        return stream.str();
    }

    stream << L", locator=" << FormatPointer(locator);
    const auto locator_module = GetModuleFromAddress(locator);
    if (locator_module != nullptr)
    {
        const auto module_name = GetModuleFileNameOnly(locator_module);
        if (!module_name.empty())
        {
            stream << L", locator_module=" << module_name;
        }
    }

    const auto locator_module_span = locator_module != nullptr
        ? GetModuleSpan(locator_module)
        : std::optional<ModuleSpan> {};
    if (!locator_module_span.has_value())
    {
        stream << L", status=locator_module_unknown}";
        return stream.str();
    }

    MsvcRttiCompleteObjectLocator complete_object_locator {};
    if (!SafeReadValue(locator, complete_object_locator))
    {
        stream << L", status=locator_read_failed}";
        return stream.str();
    }

    stream << L", signature=" << complete_object_locator.signature
        << L", type_rva=0x" << std::hex << std::uppercase
        << static_cast<std::uint32_t>(complete_object_locator.type_descriptor_rva)
        << std::dec << std::nouppercase;

    if (complete_object_locator.type_descriptor_rva <= 0 ||
        static_cast<std::size_t>(complete_object_locator.type_descriptor_rva) >=
            locator_module_span->size)
    {
        stream << L", status=type_descriptor_rva_invalid}";
        return stream.str();
    }

    const auto* type_descriptor =
        locator_module_span->base +
        static_cast<std::size_t>(complete_object_locator.type_descriptor_rva);
    stream << L", type_descriptor=" << FormatPointer(type_descriptor);

    std::string raw_name;
    if (!SafeReadCString(
            reinterpret_cast<const char*>(type_descriptor) + sizeof(void*) * 2,
            raw_name,
            256))
    {
        stream << L", status=type_name_unreadable}";
        return stream.str();
    }

    const auto simplified_name = SimplifyMsvcDecoratedTypeName(raw_name);
    stream << L", name=" << NarrowToWide(simplified_name);
    if (simplified_name != raw_name)
    {
        stream << L", raw_name=" << NarrowToWide(raw_name);
    }

    stream << L", status=ok}";
    return stream.str();
}

template <typename Result>
bool SafeInvokeMethod0(void* instance, const std::size_t index, Result& out)
{
    if (instance == nullptr)
    {
        return false;
    }

    void** vtable = nullptr;
    if (!SafeReadValue(instance, vtable) || vtable == nullptr)
    {
        return false;
    }

    using Method = Result(__fastcall*)(void*);
    void* method_address = nullptr;
    if (!SafeReadValue(vtable + index, method_address) || method_address == nullptr)
    {
        return false;
    }

    __try
    {
        out = reinterpret_cast<Method>(method_address)(instance);
        return true;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }
}

