constexpr int kMaxEntityIndex = 0x7FFE;
constexpr std::uint32_t kInvalidEntityHandle = 0xFFFFFFFFu;

int HandleToEntityIndex(const std::uint32_t handle)
{
    if (handle == kInvalidEntityHandle)
    {
        return -1;
    }

    return static_cast<int>(handle & 0x7FFFu);
}

