struct VmtPatch
{
    void** slot = nullptr;
    void* original = nullptr;
    void* replacement = nullptr;
    DWORD original_protect = 0;
    bool installed = false;

    bool Install(void* iface, const std::size_t index, void* detour)
    {
        if (installed || iface == nullptr || detour == nullptr)
        {
            return false;
        }

        void** vtable = nullptr;
        if (!SafeReadValue(iface, vtable) || vtable == nullptr)
        {
            return false;
        }

        slot = vtable + index;
        if (slot == nullptr)
        {
            return false;
        }

        DWORD old_protect = 0;
        if (!VirtualProtect(slot, sizeof(void*), PAGE_EXECUTE_READWRITE, &old_protect))
        {
            slot = nullptr;
            return false;
        }

        original = *slot;
        replacement = detour;
        original_protect = old_protect;
        *slot = detour;
        FlushInstructionCache(GetCurrentProcess(), slot, sizeof(void*));

        DWORD ignored = 0;
        VirtualProtect(slot, sizeof(void*), old_protect, &ignored);

        installed = true;
        return true;
    }

    void Remove()
    {
        if (!installed || slot == nullptr)
        {
            return;
        }

        DWORD old_protect = 0;
        if (VirtualProtect(slot, sizeof(void*), PAGE_EXECUTE_READWRITE, &old_protect))
        {
            *slot = original;
            FlushInstructionCache(GetCurrentProcess(), slot, sizeof(void*));
            DWORD ignored = 0;
            VirtualProtect(slot, sizeof(void*), original_protect != 0 ? original_protect : old_protect, &ignored);
        }

        slot = nullptr;
        original = nullptr;
        replacement = nullptr;
        original_protect = 0;
        installed = false;
    }
};

