std::wstring BuildResourceHandleQueryBindingRuntimeText(const ResourceHandleQueryBinding& binding)
{
    std::wstring text = ResourceHandleQueryStateText(binding.state);
    if (binding.path_to_handle_slot_ready &&
        binding.path_to_handle_slot != kInvalidResourceHandleQuerySlot)
    {
        text += L"@";
        text += std::to_wstring(binding.path_to_handle_slot);
    }
    else if (binding.last_attempted_slot != kInvalidResourceHandleQuerySlot)
    {
        text += L"~";
        text += std::to_wstring(binding.last_attempted_slot);
    }

    if (binding.validated_attempt_count != 0)
    {
        text += L"#";
        text += std::to_wstring(binding.validated_attempt_count);
    }

    if ((binding.state == ResourceHandleQueryState::Inactive ||
         binding.state == ResourceHandleQueryState::AwaitingSafePoint ||
         binding.state == ResourceHandleQueryState::Calibrating ||
         binding.state == ResourceHandleQueryState::Miss ||
         binding.state == ResourceHandleQueryState::Faulted ||
         (binding.passive_monitor_mode &&
          (binding.state == ResourceHandleQueryState::Armed ||
           binding.state == ResourceHandleQueryState::Active))) &&
        binding.last_failure_reason != nullptr &&
        binding.last_failure_reason[0] != L'\0')
    {
        text += L"(";
        text += binding.last_failure_reason;
        if (!binding.last_failure_detail.empty() &&
            binding.last_failure_detail != binding.last_failure_reason)
        {
            text += L"/";
            text += binding.last_failure_detail;
        }
        text += L")";
    }

    return text;
}

ResourceHandleQueryState ResolveGlobalResourceHandleQueryState() noexcept
{
    const auto rs_state = g_hook_state.resource_system_query.state;
    const auto rhu_state = g_hook_state.resource_handle_utils_query.state;
    if (rs_state == ResourceHandleQueryState::Active ||
        rhu_state == ResourceHandleQueryState::Active)
    {
        return ResourceHandleQueryState::Active;
    }
    if (rs_state == ResourceHandleQueryState::Armed ||
        rhu_state == ResourceHandleQueryState::Armed)
    {
        return ResourceHandleQueryState::Armed;
    }
    if (rs_state == ResourceHandleQueryState::Calibrating ||
        rhu_state == ResourceHandleQueryState::Calibrating)
    {
        return ResourceHandleQueryState::Calibrating;
    }
    if (rs_state == ResourceHandleQueryState::AwaitingSafePoint ||
        rhu_state == ResourceHandleQueryState::AwaitingSafePoint)
    {
        return ResourceHandleQueryState::AwaitingSafePoint;
    }
    if (rs_state == ResourceHandleQueryState::Faulted ||
        rhu_state == ResourceHandleQueryState::Faulted)
    {
        return ResourceHandleQueryState::Faulted;
    }
    if (rs_state == ResourceHandleQueryState::Miss ||
        rhu_state == ResourceHandleQueryState::Miss)
    {
        return ResourceHandleQueryState::Miss;
    }
    return ResourceHandleQueryState::Inactive;
}

std::wstring BuildResourceHandleQueryRuntimeText()
{
    int total_hits = 0;
    std::size_t max_pairs = 0;
    for (const auto& target : g_hook_state.knife_model_path_swap_query_hooks)
    {
        total_hits += target.valid_resource_hit_count;
        max_pairs = std::max(max_pairs, CountKnifeModelPathSwapQueryHookRedirectPairs(target));
    }

    std::wstring text = L"Query Swapper: [";
    text += ResourceHandleQueryStateText(ResolveGlobalResourceHandleQueryState());
    text += L"] | RS=";
    text += BuildResourceHandleQueryBindingRuntimeText(g_hook_state.resource_system_query);
    text += L" | RHU=";
    text += BuildResourceHandleQueryBindingRuntimeText(g_hook_state.resource_handle_utils_query);
    text += L" | Hits=";
    text += std::to_wstring(total_hits);
    text += L" | Pairs=";
    text += std::to_wstring(max_pairs);
    const auto& swap_state = g_hook_state.knife_model_path_swap_state;
    if (swap_state.enabled)
    {
        text += L" | Bridge=";
        if (swap_state.bridge_last_reason != nullptr && swap_state.bridge_last_reason[0] != L'\0')
        {
            text += swap_state.bridge_last_reason;
        }
        else
        {
            text += max_pairs != 0 ? L"ready" : L"pending";
        }
        text += L" | Src=";
        text += swap_state.bridge_source_world_resolved ? L"W1" : L"W0";
        text += L"/";
        text += swap_state.bridge_source_view_resolved ? L"V1" : L"V0";
        text += L" | Donor=";
        text += swap_state.bridge_world_donor_found ? L"W1" : L"W0";
        text += L"/";
        text += swap_state.bridge_view_donor_found ? L"V1" : L"V0";
        if (swap_state.target_handle_last_reason != nullptr &&
            swap_state.target_handle_last_reason[0] != L'\0' &&
            swap_state.target_handle_last_reason != kKnifeModelPathSwapTargetResolveReasonNone)
        {
            text += L" | Resolve=";
            switch (swap_state.target_handle_last_bucket)
            {
            case KnifeModelPathSwapHandleBucket::World:
                text += L"world";
                break;
            case KnifeModelPathSwapHandleBucket::View:
                text += L"view";
                break;
            case KnifeModelPathSwapHandleBucket::Hud:
                text += L"hud";
                break;
            case KnifeModelPathSwapHandleBucket::Unknown:
            default:
                text += L"handle";
                break;
            }
            text += L"/";
            text += swap_state.target_handle_last_reason;
        }
    }
    text += L" | Gate=";
    text += ResourceHandleQuerySafePointGateText(
        static_cast<ResourceHandleQuerySafePointGate>(
            g_hook_state.resource_handle_query_safe_point_gate.load(
                std::memory_order_acquire)));
    text += L" | Entered=RHU";
    text += std::to_wstring(
        g_hook_state.resource_handle_query_live_probe.entered_counts[0].load(
            std::memory_order_acquire));
    text += L"/RS";
    text += std::to_wstring(
        g_hook_state.resource_handle_query_live_probe.entered_counts[1].load(
            std::memory_order_acquire));
    text += L" | Live=";
    text += g_hook_state.resource_handle_query_live_probe.total_entered_count.load(
        std::memory_order_acquire) > 0 ? L"SEEN" : L"IDLE";
    text += L" | Probe=";
    const auto probe_capture_state =
        g_hook_state.resource_handle_query_live_probe.capture_state.load(
            std::memory_order_acquire);
    if (probe_capture_state == kResourceHandleQueryCarrierCaptureLogged)
    {
        text += L"CAPTURED";
    }
    else if (probe_capture_state == kResourceHandleQueryCarrierCapturePending ||
             probe_capture_state == kResourceHandleQueryCarrierCaptureWriting)
    {
        text += L"PENDING";
    }
    else
    {
        text += L"NONE";
    }
    return text;
}

std::uint64_t BuildKnifeRuntimeChainDiagnosticSignature(
    std::uint64_t signature,
    const nskinzcs2::runtime::KnifeRuntimeContext& context,
    const nskinzcs2::runtime::KnifeApplyGateResult& gate) noexcept
{
    const auto mix =
        [&](const std::uint64_t value) noexcept
        {
            signature ^= value + (signature << 6) + (signature >> 2);
        };

    mix(context.resource_query_bridge_ready ? 1ull : 0ull);
    mix(context.resource_query_target_handle_ready ? 1ull : 0ull);
    mix(context.resource_model_swap_ready ? 1ull : 0ull);
    mix(context.resource_model_path_readback_changed ? 1ull : 0ull);
    mix(static_cast<std::uint64_t>(std::max(0, context.resource_query_redirect_pairs)));
    // A monotonically increasing hit counter is telemetry, not a changed
    // binding. Hashing it generated a new multi-line diagnostic every frame.
    mix(context.resource_query_redirect_hits > 0 ? 1ull : 0ull);
    mix(gate.allow_finish_writes ? 1ull : 0ull);
    mix(gate.allow_model_writes ? 1ull : 0ull);
    mix(gate.allow_animation_remap ? 1ull : 0ull);
    mix(static_cast<std::uint64_t>(gate.resolved_mode));
    mix(g_hook_state.knife_model_path_swap_bridge_publish_generation.load(std::memory_order_acquire));
    return signature;
}

void LogKnifeRuntimeChainResourceSnapshotAfterBridgePushLocked(
    const ResourceHandleQueryBinding& binding,
    const KnifeModelPathSwapQueryHookTarget& hook_target) noexcept
{
    const auto& swap_state = g_hook_state.knife_model_path_swap_state;
    const auto hook_pairs = static_cast<int>(CountKnifeModelPathSwapQueryHookRedirectPairs(hook_target));
    if (!swap_state.enabled ||
        swap_state.xuid == 0 ||
        binding.interface_kind != ResourceHandleQueryInterfaceKind::ResourceSystem ||
        hook_pairs <= 0)
    {
        return;
    }

    int world_entity_index = -1;
    if (const auto player_it = g_hook_state.runtime_entities.players_by_xuid.find(swap_state.xuid);
        player_it != g_hook_state.runtime_entities.players_by_xuid.end())
    {
        world_entity_index = player_it->second.active_weapon_entity_index;
    }
    const bool snapshot_target_handle_ready =
        (swap_state.target_world_path != nullptr &&
         swap_state.target_world_path[0] != '\0' &&
         ((swap_state.resolved_target_world_handle_valid &&
           swap_state.resolved_target_world_handle != 0) ||
          binding.last_target_handle != 0)) ||
        (swap_state.target_view_path != nullptr &&
         swap_state.target_view_path[0] != '\0' &&
         ((swap_state.resolved_target_view_handle_valid &&
           swap_state.resolved_target_view_handle != 0) ||
          binding.last_target_handle != 0));
    const bool snapshot_resource_swap_ready =
        hook_target.valid_resource_hit_count > 0 || snapshot_target_handle_ready;

    std::wstringstream stream;
    stream << L"Knife runtime chain resource snapshot for XUID " << swap_state.xuid
        << L": world_entity=" << world_entity_index
        << L", resource_bridge_ready="
        << ((swap_state.handle_redirect_pair_count > 0 && hook_pairs > 0) ? 1 : 0)
        << L", resource_target_handle_ready="
        << (snapshot_target_handle_ready ? 1 : 0)
        << L", resource_swap_ready="
        << (snapshot_resource_swap_ready ? 1 : 0)
        << L", resource_pairs=" << hook_pairs
        << L", resource_hits=" << hook_target.valid_resource_hit_count
        << L", resource_total_hits=" << hook_target.hit_count
        << L", bridge_reason="
        << ((swap_state.bridge_last_reason != nullptr && swap_state.bridge_last_reason[0] != L'\0')
                ? swap_state.bridge_last_reason
                : L"none")
        << L", preferred=0x" << std::hex << std::uppercase
        << binding.last_source_handle << L"->0x" << binding.last_target_handle
        << std::dec << std::nouppercase
        << L", publish_generation="
        << g_hook_state.knife_model_path_swap_bridge_publish_generation.load(std::memory_order_acquire);
    nskinzcs2::Logger::Info(stream.str());
}

