std::wstring BuildWatchedKnifeAttackStateSummaryText()
{
    std::vector<std::pair<int, std::uint32_t>> samples;
    samples.reserve(g_hook_state.watched_knife_trace_counts.size());
    for (const auto& [gameplay_state, count] : g_hook_state.watched_knife_trace_counts)
    {
        samples.emplace_back(gameplay_state, count);
    }

    if (samples.empty())
    {
        return {};
    }

    std::sort(
        samples.begin(),
        samples.end(),
        [](const auto& lhs, const auto& rhs)
        {
            if (lhs.second != rhs.second)
            {
                return lhs.second > rhs.second;
            }

            return lhs.first < rhs.first;
        });

    std::wstringstream stream;
    stream << L"Watched knife attack samples: classifier="
        << (nskinzcs2::runtime::KnifeAnimationAttackClassifierReady() ? L"ready" : L"uncalibrated")
        << L", states=";
    constexpr std::size_t kMaxStateSamples = 4;
    for (std::size_t index = 0; index < samples.size() && index < kMaxStateSamples; ++index)
    {
        if (index != 0)
        {
            stream << L"; ";
        }

        stream << samples[index].first << L"x" << samples[index].second;
    }

    if (samples.size() > kMaxStateSamples)
    {
        stream << L"; ...";
    }

    return stream.str();
}

std::wstring BuildKnifeModelResourceOverrideSummaryText()
{
    const auto& state = g_hook_state.knife_model_resource_override;
    if (!state.active)
    {
        return {};
    }

    const auto& path_swap_state = g_hook_state.knife_model_path_swap_state;

    int probe_hits = 0;
    int global_hits = 0;
    for (const auto& probe_state : state.probe_slots)
    {
        probe_hits += probe_state.override_hit_count;
    }
    for (const auto& target : state.global_targets)
    {
        global_hits += target.override_hit_count;
    }

    std::wstringstream stream;
    stream << L"Knife model hook: phase=" << KnifeModelResourceOverridePhaseText(state.phase)
        << L", armed=1"
        << L", target_definition=" << state.target_definition_index
        << L", world_hit=" << (state.world_model_hit_observed ? 1 : 0)
        << L", first_person_hit=" << (state.first_person_model_hit_observed ? 1 : 0)
        << L", override_applied=" << (state.override_applied ? 1 : 0)
        << L", exact_post_apply=" << (state.exact_post_call_apply_succeeded ? 1 : 0)
        << L", probe_override_hits=" << probe_hits
        << L", global_override_hits=" << global_hits;
    if (path_swap_state.enabled)
    {
        stream << L", path_swap_world_hits=" << path_swap_state.hit_count_world
            << L", path_swap_view_hits=" << path_swap_state.hit_count_view;
    }
    if (const auto desired_model_name =
            state.desired_first_person_model_name != nullptr
                ? state.desired_first_person_model_name
                : state.desired_world_model_name;
        desired_model_name != nullptr && desired_model_name[0] != '\0')
    {
        stream << L", target_model=" << NarrowToWide(std::string(desired_model_name));
    }
    return stream.str();
}

std::wstring BuildKnifeModelPathSwapHookSummaryText()
{
    const auto& state = g_hook_state.knife_model_path_swap_state;
    if (!state.enabled)
    {
        return {};
    }

    std::wstringstream stream;
    stream << L"Knife model path swap hook: world_hit=" << state.hit_count_world
        << L", view_hit=" << state.hit_count_view;
    for (const auto& target : g_hook_state.knife_model_path_swap_query_hooks)
    {
        if (!target.valid)
        {
            continue;
        }

        stream << L" | {interface=" << ResourceHandleQueryInterfaceKindText(target.interface_kind)
            << L", slot=" << target.slot
            << L", pairs=" << CountKnifeModelPathSwapQueryHookRedirectPairs(target)
            << L", hits=" << target.hit_count
            << L", valid_hits=" << target.valid_resource_hit_count
            << L", path_hits=" << target.path_redirect_hit_count
            << L", live_result_hits=" << target.live_result_redirect_hit_count
            << L", calibrated_hits=" << target.calibrated_handle_hit_count
            << L", learned_hits=" << target.learned_handle_hit_count
            << L", bridge_handle_hits=" << target.bridge_handle_hit_count
            << L", redirects=" << target.redirect_count;
        if (target.last_hit_kind != nullptr && target.last_hit_kind[0] != L'\0')
        {
            stream << L", last_hit_kind=" << target.last_hit_kind;
        }
        if (target.last_match_bucket != nullptr && target.last_match_bucket[0] != '\0')
        {
            stream << L", bucket=" << NarrowToWide(std::string(target.last_match_bucket));
        }
        if (target.last_redirect_path != nullptr && target.last_redirect_path[0] != '\0')
        {
            stream << L", last_out=" << NarrowToWide(std::string(target.last_redirect_path));
        }
        if (target.last_valid_hit_caller_return_address != 0)
        {
            stream << L", valid_caller="
                << FormatModuleOwnerWithOffset(
                       reinterpret_cast<void*>(target.last_valid_hit_caller_return_address))
                << L", valid_arg4=0x" << std::hex << std::uppercase << target.last_valid_hit_arg4
                << std::dec << std::nouppercase;
        }
        stream << L"}";
    }
    return stream.str();
}

std::wstring BuildKnifeCarrierDiscoveryRuntimeReasonText(
    const bool no_exposed_non_synthetic_render_owner,
    const nskinzcs2::runtime::KnifeCarrierDiscoveryResult carrier_result,
    const nskinzcs2::runtime::KnifeCarrierFactoryFeasibility factory_feasibility)
{
    if (!no_exposed_non_synthetic_render_owner)
    {
        return L"Waiting for strict verification before enabling deploy/inspect.";
    }

    if (carrier_result == nskinzcs2::runtime::KnifeCarrierDiscoveryResult::DiscoverableIncompleteCarrier)
    {
        return L"Waiting for a writable real viewmodel carrier; discovery found knife-related shells, but none exposed a safe writable real viewmodel carrier, so first-person writes remain blocked.";
    }

    if (factory_feasibility == nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::ViewmodelFactoryPresentWithoutInstance)
    {
        return L"Waiting for a verified real viewmodel owner; live/raw scans found no exposed writable real viewmodel carrier, while viewmodel/weapon client classes were observed without a live instance.";
    }

    if (factory_feasibility == nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::NoViewmodelFactoryEvidence)
    {
        return L"Waiting for a verified real viewmodel owner; live/raw scans found no exposed writable real viewmodel carrier and no viewmodel/weapon factory evidence was observed.";
    }

    return L"Waiting for a verified real viewmodel owner; live/raw scans found no exposed writable real viewmodel carrier, so first-person writes remain blocked.";
}

