std::wstring BuildKnifeModelOnlyRuntimeReasonText(const KnifeModelPathState& state)
{
    if (state.resource_only_render_active &&
        state.no_exposed_non_synthetic_render_owner)
    {
        return L"single world consumer active; no separate first-person consumer observed";
    }

    if (HasObservedKnifeModelResourceOverrideHit(g_hook_state.knife_model_resource_override))
    {
        if (!state.animation_owner_verified ||
            state.owner_kind != nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel ||
            state.first_person_render_only ||
            state.no_exposed_non_synthetic_render_owner)
        {
            return L"Knife model hook observed the requested render path; visual replacement is active while deploy/inspect waits for a verified real animation owner.";
        }
    }

    if (!state.direct_render_rebind_succeeded)
    {
        return L"Waiting for verified world + first-person render knife swap.";
    }

    if (state.owner_kind != nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel ||
        state.first_person_render_only ||
        state.no_exposed_non_synthetic_render_owner)
    {
        return L"World + HUD render-shell model path active; deploy/inspect stays disabled until a verified real animation owner appears.";
    }

    if (!state.strict_verified)
    {
        return L"Waiting for strict first-person render verification before enabling deploy/inspect.";
    }

    if (!state.animation_owner_verified)
    {
        return L"Waiting for a verified first-person animation owner.";
    }

    return {};
}

