constexpr int kKnifeModelWriteCooldownFailureThreshold = 3;
constexpr std::uint64_t kKnifeModelWriteCooldownMillis = 1600;

bool TryGetKnifeModelWriteCooldownReason(
    const std::uint64_t xuid,
    const std::uint64_t now_millis,
    std::wstring& reason)
{
    std::scoped_lock lock(g_hook_state.knife_model_write_stability_mutex);
    const auto it = g_hook_state.knife_model_write_stability_by_xuid.find(xuid);
    if (it == g_hook_state.knife_model_write_stability_by_xuid.end())
    {
        return false;
    }

    auto& state = it->second;
    if (state.cooldown_until_millis == 0 || now_millis >= state.cooldown_until_millis)
    {
        state.cooldown_until_millis = 0;
        state.consecutive_failures = 0;
        state.last_failure_reason.clear();
        return false;
    }

    reason = state.last_failure_reason;
    if (reason.empty())
    {
        reason = L"Knife model write cooldown active after repeated unstable frames.";
    }
    return true;
}

void RememberKnifeModelWriteFailure(
    const std::uint64_t xuid,
    const std::uint64_t now_millis,
    std::wstring failure_reason)
{
    std::scoped_lock lock(g_hook_state.knife_model_write_stability_mutex);
    auto& state = g_hook_state.knife_model_write_stability_by_xuid[xuid];
    if (!failure_reason.empty())
    {
        state.last_failure_reason = std::move(failure_reason);
    }

    if (state.cooldown_until_millis != 0 && now_millis < state.cooldown_until_millis)
    {
        return;
    }

    if (state.cooldown_until_millis != 0 && now_millis >= state.cooldown_until_millis)
    {
        state.cooldown_until_millis = 0;
        state.consecutive_failures = 0;
    }

    ++state.consecutive_failures;
    if (state.consecutive_failures < kKnifeModelWriteCooldownFailureThreshold)
    {
        return;
    }

    state.consecutive_failures = 0;
    state.cooldown_until_millis = now_millis + kKnifeModelWriteCooldownMillis;
    std::wstringstream stream;
    stream << L"Knife model write cooldown active for "
        << kKnifeModelWriteCooldownMillis
        << L" ms after repeated write failures.";
    if (!state.last_failure_reason.empty())
    {
        stream << L" Last failure: " << state.last_failure_reason;
    }
    state.last_failure_reason = stream.str();
}

void ClearKnifeModelWriteFailureState(const std::uint64_t xuid)
{
    std::scoped_lock lock(g_hook_state.knife_model_write_stability_mutex);
    g_hook_state.knife_model_write_stability_by_xuid.erase(xuid);
}

