class RuntimePollTraceScope
{
public:
    explicit RuntimePollTraceScope(const bool active) noexcept
        : active_(active)
    {
    }

    ~RuntimePollTraceScope()
    {
        if (!active_)
        {
            return;
        }

        auto remaining = g_hook_state.runtime_trace_polls_remaining.load();
        while (remaining > 0 &&
               !g_hook_state.runtime_trace_polls_remaining.compare_exchange_weak(
                   remaining,
                   remaining - 1))
        {
        }
    }

    [[nodiscard]] bool active() const noexcept
    {
        return active_;
    }

    void Step(const std::wstring& message) const
    {
        if (!active_)
        {
            return;
        }

        nskinzcs2::Logger::Info(L"Runtime breadcrumb: " + message);
    }

private:
    bool active_ = false;
};

