bool TryGetEntityFromIndex(void* entity_list, const int entity_index, void*& entity)
{
    entity = nullptr;

    __try
    {
        entity = g_hook_state.entity_system.get_entity_from_index(entity_list, entity_index);
        return true;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }
}

void* ResolveWeaponItemView(void* weapon_entity, const ClientSchemaOffsets& offsets)
{
    if (weapon_entity == nullptr)
    {
        return nullptr;
    }

    auto* attribute_manager = reinterpret_cast<std::uint8_t*>(weapon_entity) + offsets.econ_entity_attribute_manager;
    return attribute_manager + offsets.attribute_container_item;
}

void* ResolveWeaponAttributeContainer(void* weapon_entity, const ClientSchemaOffsets& offsets)
{
    if (weapon_entity == nullptr || offsets.econ_entity_attribute_manager == 0)
    {
        return nullptr;
    }

    return reinterpret_cast<std::uint8_t*>(weapon_entity) + offsets.econ_entity_attribute_manager;
}

int ResolveEntityIndexFromPointer(const std::vector<void*>& entity_cache, void* entity)
{
    if (entity == nullptr)
    {
        return -1;
    }

    for (std::size_t index = 0; index < entity_cache.size(); ++index)
    {
        if (entity_cache[index] == entity)
        {
            return static_cast<int>(index);
        }
    }

    return -1;
}

bool TryResolveLiveEntityFromStoredBinding(
    const int entity_index,
    void* cached_entity,
    void* cached_item_view,
    const ClientSchemaOffsets& offsets,
    void*& live_entity,
    void*& live_item_view,
    std::wstring* issue,
    const wchar_t* label)
{
    live_entity = nullptr;
    live_item_view = nullptr;
    const auto is_resolved_runtime_entity_index =
        [](const int candidate_index) noexcept
        {
            return candidate_index != -1;
        };
    const auto is_synthetic_runtime_entity_index =
        [](const int candidate_index) noexcept
        {
            return candidate_index < -1;
        };
    if (issue != nullptr)
    {
        issue->clear();
    }

    auto set_issue =
        [&](const wchar_t* reason, void* resolved_entity = nullptr)
        {
            if (issue == nullptr)
            {
                return;
            }

            std::wstringstream stream;
            stream << (label != nullptr ? label : L"stored_entity")
                << L": " << (reason != nullptr ? reason : L"unknown")
                << L", entity_index=" << entity_index
                << L", cached_entity=" << FormatPointer(cached_entity);
            if (resolved_entity != nullptr)
            {
                stream << L", live_entity=" << FormatPointer(resolved_entity);
            }
            *issue = stream.str();
        };

    if (cached_entity == nullptr)
    {
        set_issue(L"cached_entity_missing");
        return false;
    }

    if (is_synthetic_runtime_entity_index(entity_index))
    {
        set_issue(L"synthetic_entity_unreacquirable");
        return false;
    }

    if (!is_resolved_runtime_entity_index(entity_index))
    {
        set_issue(
            L"entity_index_invalid");
        return false;
    }

    auto* entity_list = g_hook_state.runtime_entities.last_entity_list;
    if (entity_list == nullptr)
    {
        set_issue(L"entity_list_unavailable");
        return false;
    }

    if (!TryGetEntityFromIndex(entity_list, entity_index, live_entity) ||
        live_entity == nullptr)
    {
        set_issue(L"live_entity_missing");
        live_entity = nullptr;
        return false;
    }

    if (live_entity != cached_entity)
    {
        set_issue(L"pointer_mismatch", live_entity);
        live_entity = nullptr;
        return false;
    }

    live_item_view = ResolveWeaponItemView(live_entity, offsets);
    if (cached_item_view != nullptr &&
        live_item_view != cached_item_view)
    {
        set_issue(L"item_view_mismatch", live_entity);
        live_entity = nullptr;
        live_item_view = nullptr;
        return false;
    }

    return true;
}

int BuildSyntheticEntityIndex(const void* entity, const std::uint32_t salt)
{
    const auto bits = static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(entity));
    const auto folded = static_cast<std::uint32_t>(((bits >> 4) ^ bits ^ salt) & 0x3FFFFFFFu);
    return -1 - static_cast<int>(folded);
}

bool IsResolvedRuntimeEntityIndex(const int entity_index) noexcept
{
    return entity_index != -1;
}

bool IsSyntheticRuntimeEntityIndex(const int entity_index) noexcept
{
    return entity_index < -1;
}

