bool TryReadWeaponMeshGroupMaskRaw(
    void* weapon_entity,
    const ClientSchemaOffsets& offsets,
    std::uint64_t& mesh_group_mask)
{
    mesh_group_mask = 0;
    if (weapon_entity == nullptr ||
        offsets.base_entity_game_scene_node == 0 ||
        offsets.skeleton_instance_model_state == 0 ||
        offsets.model_state_mesh_group_mask == 0)
    {
        return false;
    }

    void* game_scene_node = nullptr;
    if (!SafeReadField(weapon_entity, offsets.base_entity_game_scene_node, game_scene_node) ||
        game_scene_node == nullptr)
    {
        return false;
    }

    if (!SafeReadValue(
            reinterpret_cast<std::uint8_t*>(game_scene_node) +
                offsets.skeleton_instance_model_state +
                offsets.model_state_mesh_group_mask,
            mesh_group_mask))
    {
        return false;
    }

    return true;
}

bool TryReadWeaponMeshGroupMask(
    void* weapon_entity,
    const ClientSchemaOffsets& offsets,
    std::uint64_t& mesh_group_mask)
{
    if (!TryReadWeaponMeshGroupMaskRaw(weapon_entity, offsets, mesh_group_mask))
    {
        return false;
    }

    constexpr std::uint64_t kInvalidMeshGroupMask = ~std::uint64_t {0};
    return mesh_group_mask != kInvalidMeshGroupMask;
}

bool TryReadKnifeRenderableMeshGroupMask(
    const int entity_index,
    void* weapon_entity,
    const ClientSchemaOffsets& offsets,
    std::uint64_t& mesh_group_mask)
{
    if (weapon_entity == nullptr)
    {
        return false;
    }

    if (IsSyntheticRuntimeEntityIndex(entity_index))
    {
        return TryReadWeaponMeshGroupMaskRaw(weapon_entity, offsets, mesh_group_mask);
    }

    return TryReadWeaponMeshGroupMask(weapon_entity, offsets, mesh_group_mask);
}

struct KnifeSyntheticProxyMeshGroupMaskResolution
{
    std::uint64_t mesh_group_mask = 1ull;
    const wchar_t* source = L"default";
};

KnifeSyntheticProxyMeshGroupMaskResolution ResolveKnifeSyntheticProxyDesiredMeshGroupMaskImpl(
    const bool original_first_person_mesh_group_mask_valid,
    const std::uint64_t original_first_person_mesh_group_mask,
    const bool live_first_person_mesh_group_mask_valid,
    const std::uint64_t live_first_person_mesh_group_mask,
    const bool world_render_mesh_group_mask_valid,
    const std::uint64_t world_render_mesh_group_mask) noexcept
{
    constexpr std::uint64_t kAllMeshGroupsMask = ~std::uint64_t {0};

    if (original_first_person_mesh_group_mask_valid &&
        original_first_person_mesh_group_mask != 0)
    {
        return {
            original_first_person_mesh_group_mask,
            original_first_person_mesh_group_mask == kAllMeshGroupsMask
                ? L"original_first_person_render_raw_all_groups"
                : L"original_first_person_render_raw",
        };
    }

    if (live_first_person_mesh_group_mask_valid &&
        live_first_person_mesh_group_mask != 0)
    {
        return {
            live_first_person_mesh_group_mask,
            live_first_person_mesh_group_mask == kAllMeshGroupsMask
                ? L"live_first_person_render_raw_all_groups"
                : L"live_first_person_render_raw",
        };
    }

    if (world_render_mesh_group_mask_valid &&
        world_render_mesh_group_mask != 0)
    {
        return {
            world_render_mesh_group_mask,
            L"world_render_mesh_group_mask",
        };
    }

    return {};
}

void AppendPointerValue(std::wstringstream& stream, const void* pointer)
{
    stream << L"0x" << std::hex << reinterpret_cast<std::uintptr_t>(pointer) << std::dec;
}

std::wstring DescribeRenderedWorldWeaponTrace(const RenderedWorldWeaponTrace& trace)
{
    std::wstringstream stream;
    stream << L"pawn=" << trace.pawn_entity_index
        << L", active_handle=0x" << std::hex << trace.active_weapon_handle << std::dec
        << L", active_entity=" << trace.active_weapon_entity_index
        << L", owned_handle=0x" << std::hex << trace.owned_weapon_handle << std::dec
        << L", owned_entity=" << trace.owned_weapon_entity_index
        << L", owned_item_view=";
    AppendPointerValue(stream, trace.owned_weapon_item_view);
    stream << L", owned_owner=" << trace.owned_weapon_owner_index
        << L", scene_owner=" << trace.scene_owner_entity_index
        << L", scene_owner_matches=" << (trace.scene_owner_matches_owned_weapon ? 1 : 0)
        << L", explicit_owner_children=" << trace.explicit_owner_child_count;

    if (trace.explicit_owner_child_entity_index >= 0)
    {
        stream << L", explicit_child_entity=" << trace.explicit_owner_child_entity_index
            << L", explicit_child_item_view=";
        AppendPointerValue(stream, trace.explicit_owner_child_item_view);
    }

    if (trace.hud_weapon_entity_index >= 0)
    {
        stream << L", hud_entity=" << trace.hud_weapon_entity_index
            << L", hud_item_view=";
        AppendPointerValue(stream, trace.hud_weapon_item_view);
    }

    stream << L", shared_scene=" << (trace.owned_and_scene_owner_share_item_view ? 1 : 0)
        << L", shared_explicit=" << (trace.owned_and_explicit_child_share_item_view ? 1 : 0)
        << L", shared_hud=" << (trace.owned_and_hud_share_item_view ? 1 : 0)
        << L", mesh_owned=";
    if (trace.owned_weapon_mesh_group_mask_valid)
    {
        stream << trace.owned_weapon_mesh_group_mask;
    }
    else
    {
        stream << L"?";
    }

    stream << L", mesh_explicit=";
    if (trace.explicit_owner_child_mesh_group_mask_valid)
    {
        stream << trace.explicit_owner_child_mesh_group_mask;
    }
    else
    {
        stream << L"?";
    }

    stream << L", mesh_hud=";
    if (trace.hud_weapon_mesh_group_mask_valid)
    {
        stream << trace.hud_weapon_mesh_group_mask;
    }
    else
    {
        stream << L"?";
    }

    return stream.str();
}

bool ResolveExactWorldWeaponApplicationBinding(
    const RenderedWorldWeaponTrace& trace,
    ExactWorldWeaponApplicationBinding& binding)
{
    binding = {};

    if (trace.owned_weapon_entity == nullptr || trace.owned_weapon_item_view == nullptr || trace.owned_weapon_entity_index < 0)
    {
        return false;
    }

    binding.carrier_entity_index = trace.owned_weapon_entity_index;
    binding.carrier_entity = trace.owned_weapon_entity;
    binding.carrier_item_view = trace.owned_weapon_item_view;
    binding.render_entity_index = trace.owned_weapon_entity_index;
    binding.render_entity = trace.owned_weapon_entity;
    binding.hud_weapon_entity_index = trace.hud_weapon_entity_index;
    binding.hud_weapon_entity = trace.hud_weapon_entity;

    const auto explicit_owner_child_is_exact =
        trace.explicit_owner_child_count == 1 &&
        trace.explicit_owner_child_entity != nullptr &&
        trace.explicit_owner_child_entity_index >= 0;
    if (!explicit_owner_child_is_exact)
    {
        return true;
    }

    binding.render_entity_index = trace.explicit_owner_child_entity_index;
    binding.render_entity = trace.explicit_owner_child_entity;
    binding.render_entity_is_owned = false;
    binding.render_entity_is_explicit_owner_child = true;

    if (trace.explicit_owner_child_item_view != nullptr &&
        trace.explicit_owner_child_item_view != trace.owned_weapon_item_view)
    {
        binding.carrier_entity_index = trace.explicit_owner_child_entity_index;
        binding.carrier_entity = trace.explicit_owner_child_entity;
        binding.carrier_item_view = trace.explicit_owner_child_item_view;
        binding.carrier_entity_is_explicit_owner_child = true;
    }

    return true;
}

std::wstring DescribeObservedPawnClassName(void* entity);
bool IsStandardWeaponBaseItem(int definition_index);

bool TryReadHudBindingHandle(void* entity, const ClientSchemaOffsets& offsets, std::uint32_t& handle)
{
    // Named Schema fields anchor the adjacent native full-handle layout.
    // Use the shared identity offsets, not a truncated entity slot comparison.
    void* identity = nullptr;
    void* roundtrip = nullptr;
    return entity != nullptr && offsets.knife_entity_identity != 0 &&
        offsets.knife_identity_name_index == 0x14 &&
        SafeReadField(entity, offsets.knife_entity_identity, identity) && identity != nullptr &&
        SafeReadValue(identity, roundtrip) && roundtrip == entity &&
        SafeReadField(identity, 0x10, handle) && handle != kInvalidEntityHandle && handle != 0xFFFFFFFEu;
}

bool TryTrackStandardWeaponAppearanceEpoch(
    const int carrier_index, void* carrier, void* render, void* hud,
    const ClientSchemaOffsets& offsets)
{
    // These Schema fields belong to CEntityInstance/C_BaseEntity, despite their
    // historical knife_* names. Track object generations, not mutable cosmetic
    // fields: replicated paint/mesh repairs must not trigger native regeneration.
    const auto capture = [&](void* entity, StandardWeaponEntityEpoch& epoch)
    {
        if (entity == nullptr) { return true; }
        epoch.entity = entity;
        return offsets.knife_creation_tick != 0 &&
            TryReadHudBindingHandle(entity, offsets, epoch.handle) &&
            SafeReadField(entity, offsets.knife_entity_identity, epoch.identity) &&
            SafeReadField(entity, offsets.knife_creation_tick, epoch.creation_tick);
    };
    StandardWeaponAppearanceEpoch current;
    if (carrier == nullptr || carrier_index < 0 ||
        !capture(carrier, current.carrier) || !capture(render, current.render) ||
        !capture(hud, current.hud) || HandleToEntityIndex(current.carrier.handle) != carrier_index)
    {
        // No cache mutation on a partial/unreadable snapshot. The caller stays
        // pending before writes and can retry when the binding stabilizes.
        return false;
    }
    auto [iterator, inserted] = g_hook_state.standard_weapon_appearance_epochs.try_emplace(carrier_index);
    auto& previous = iterator->second;
    const bool carrier_changed = inserted || previous.carrier != current.carrier;
    const bool consumer_changed =
        (render != nullptr && previous.render != current.render) ||
        (hud != nullptr && previous.hud != current.hud);
    if (carrier_changed || consumer_changed)
    {
        g_hook_state.applied_weapon_signatures.erase(carrier_index);
        g_hook_state.refreshed_weapon_signatures.erase(carrier_index);
    }
    if (carrier_changed) { previous = {}; }
    previous.carrier = current.carrier;
    // Holstering or observing a world-only view is not proof of destruction.
    // Preserve the last verified consumer until a different one is observed.
    if (render != nullptr) { previous.render = current.render; }
    if (hud != nullptr) { previous.hud = current.hud; }
    return true;
}

bool TryResolveStandardWeaponHudRender(
    const std::vector<void*>& entities, const RuntimePlayerBinding& player,
    const std::uint32_t weapon_handle, void* world, const ClientSchemaOffsets& offsets,
    int& hud_index, void*& hud, void* entity_list = nullptr)
{
    hud_index = -1;
    hud = nullptr;
    if (offsets.pawn_hud_model_arms == 0 || offsets.pawn_weapon_services == 0 ||
        offsets.weapon_services_active_weapon == 0 || offsets.base_owner_entity == 0 ||
        offsets.base_entity_game_scene_node == 0 || offsets.game_scene_node_owner == 0 ||
        offsets.game_scene_node_child == 0 || offsets.game_scene_node_next_sibling == 0)
    {
        return false;
    }
    std::uint32_t pawn_handle = kInvalidEntityHandle, actual_weapon = kInvalidEntityHandle;
    std::uint32_t owner = kInvalidEntityHandle, active = kInvalidEntityHandle;
    void* services = nullptr;
    if (!TryReadHudBindingHandle(player.pawn_entity, offsets, pawn_handle) || pawn_handle != player.pawn_handle ||
        !TryReadHudBindingHandle(world, offsets, actual_weapon) || actual_weapon != weapon_handle ||
        !SafeReadField(world, offsets.base_owner_entity, owner) || owner != pawn_handle ||
        !SafeReadField(player.pawn_entity, offsets.pawn_weapon_services, services) || services == nullptr ||
        !SafeReadField(services, offsets.weapon_services_active_weapon, active) || active != weapon_handle)
    {
        return false;
    }
    std::uint32_t arms_handle = kInvalidEntityHandle, actual_arms = kInvalidEntityHandle;
    if (!SafeReadField(player.pawn_entity, offsets.pawn_hud_model_arms, arms_handle)) { return false; }
    const auto arms_index = HandleToEntityIndex(arms_handle);
    void* arms = arms_index >= 0 && static_cast<std::size_t>(arms_index) < entities.size()
        ? entities[static_cast<std::size_t>(arms_index)] : nullptr;
    // Client-only HUD arms live above sparse network entities (observed index
    // 17050). The bounded discovery cache can legitimately stop below them.
    // Resolve this ONE explicit handle through the native getter, then retain
    // every identity/owner/scene check. Do not enlarge or scan the entity cache.
    if ((!TryReadHudBindingHandle(arms, offsets, actual_arms) || actual_arms != arms_handle) &&
        arms_index >= 0 && arms_index <= kMaxEntityIndex && entity_list != nullptr &&
        g_hook_state.entity_system.get_entity_from_index != nullptr)
    {
        arms = nullptr;
        if (!TryGetEntityFromIndex(entity_list, arms_index, arms)) { return false; }
    }
    if (!TryReadHudBindingHandle(arms, offsets, actual_arms) || actual_arms != arms_handle ||
        DescribeObservedPawnClassName(arms) != L"C_CS2HudModelArms" ||
        !SafeReadField(arms, offsets.base_owner_entity, owner) || owner != pawn_handle)
    {
        return false;
    }
    void* root = nullptr;
    void* root_owner = nullptr;
    void* child = nullptr;
    if (!SafeReadField(arms, offsets.base_entity_game_scene_node, root) || root == nullptr ||
        !SafeReadField(root, offsets.game_scene_node_owner, root_owner) || root_owner != arms ||
        !SafeReadField(root, offsets.game_scene_node_child, child) || child == nullptr)
    {
        return false;
    }
    std::array<void*, 64> pending {}, visited {};
    std::size_t count = 1, seen = 0;
    pending[0] = child;
    void* selected = nullptr;
    while (count != 0)
    {
        auto* node = pending[--count];
        if (node == root) { return false; } // A malformed cycle cannot leave the verified arms subtree.
        if (std::find(visited.begin(), visited.begin() + seen, node) != visited.begin() + seen) { continue; }
        if (seen == visited.size()) { return false; }
        visited[seen++] = node;
        for (const auto link : {offsets.game_scene_node_child, offsets.game_scene_node_next_sibling})
        {
            void* next = nullptr;
            if (!SafeReadField(node, link, next)) { return false; }
            if (next != nullptr)
            {
                if (count == pending.size()) { return false; }
                pending[count++] = next;
            }
        }
        void* candidate = nullptr;
        void* candidate_scene = nullptr;
        std::uint32_t candidate_owner = kInvalidEntityHandle;
        if (!SafeReadField(node, offsets.game_scene_node_owner, candidate) || candidate == nullptr ||
            candidate == arms || candidate == world || candidate == player.pawn_entity ||
            !SafeReadField(candidate, offsets.base_owner_entity, candidate_owner) || candidate_owner != weapon_handle ||
            !SafeReadField(candidate, offsets.base_entity_game_scene_node, candidate_scene) || candidate_scene != node)
        {
            continue;
        }
        std::string model_name;
        if (!TryReadEntityModelNameString(candidate, offsets, model_name) ||
            !nskinzcs2::runtime::IsStandardWeaponHudRenderCandidate(
                DescribeObservedPawnClassName(candidate), model_name, candidate_owner, weapon_handle, true, false))
        {
            continue;
        }
        if (selected != nullptr && selected != candidate) { return false; }
        selected = candidate;
    }
    if (selected == nullptr) { return false; }
    hud = selected;
    hud_index = ResolveEntityIndexFromPointer(entities, selected);
    if (hud_index < 0) { hud_index = BuildSyntheticEntityIndex(selected, 0x48554457u); }
    return true;
}

bool TryBuildRenderedWorldWeaponTrace(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const std::uint64_t xuid,
    const std::uint32_t owned_weapon_handle,
    const int owned_weapon_entity_index,
    void* owned_weapon_entity,
    const ClientSchemaOffsets& offsets,
    RenderedWorldWeaponTrace& trace)
{
    trace = {};

    if (owned_weapon_entity == nullptr || owned_weapon_entity_index < 0)
    {
        return false;
    }

    trace.xuid = xuid;
    trace.pawn_entity_index = player_binding.pawn_entity_index;
    trace.pawn_handle = player_binding.pawn_handle;
    trace.active_weapon_handle = player_binding.active_weapon_handle;
    trace.active_weapon_entity_index = player_binding.active_weapon_entity_index;
    if (offsets.pawn_hud_model_arms != 0 && player_binding.pawn_entity != nullptr)
    {
        SafeReadField(player_binding.pawn_entity, offsets.pawn_hud_model_arms, trace.hud_arms_handle);
    }
    trace.owned_weapon_handle = owned_weapon_handle;
    trace.owned_weapon_entity_index = owned_weapon_entity_index;
    trace.owned_weapon_entity = owned_weapon_entity;
    trace.owned_weapon_item_view = ResolveWeaponItemView(owned_weapon_entity, offsets);

    if (offsets.base_owner_entity != 0)
    {
        SafeReadField(owned_weapon_entity, offsets.base_owner_entity, trace.owned_weapon_owner_handle);
        trace.owned_weapon_owner_index = HandleToEntityIndex(trace.owned_weapon_owner_handle);
    }

    trace.owned_weapon_mesh_group_mask_valid =
        TryReadWeaponMeshGroupMask(owned_weapon_entity, offsets, trace.owned_weapon_mesh_group_mask);

    if (offsets.base_entity_game_scene_node != 0 && offsets.game_scene_node_owner != 0)
    {
        void* game_scene_node = nullptr;
        if (SafeReadField(owned_weapon_entity, offsets.base_entity_game_scene_node, game_scene_node) &&
            game_scene_node != nullptr &&
            SafeReadField(game_scene_node, offsets.game_scene_node_owner, trace.scene_owner_entity) &&
            trace.scene_owner_entity != nullptr)
        {
            trace.scene_owner_entity_index = ResolveEntityIndexFromPointer(entity_cache, trace.scene_owner_entity);
            if (trace.scene_owner_entity_index < 0)
            {
                trace.scene_owner_entity_index = BuildSyntheticEntityIndex(trace.scene_owner_entity, 0x57524C44u);
            }
            trace.scene_owner_item_view = ResolveWeaponItemView(trace.scene_owner_entity, offsets);
            trace.scene_owner_matches_owned_weapon = trace.scene_owner_entity == owned_weapon_entity;
            trace.owned_and_scene_owner_share_item_view =
                trace.owned_weapon_item_view != nullptr &&
                trace.owned_weapon_item_view == trace.scene_owner_item_view;
        }
    }

    int world_definition = 0;
    const bool standard_weapon = TryReadItemDefinitionIndex(trace.owned_weapon_item_view, offsets, world_definition) &&
        IsStandardWeaponBaseItem(world_definition);
    if (owned_weapon_handle != kInvalidEntityHandle && offsets.base_owner_entity != 0)
    {
        for (std::size_t index = 0; index < entity_cache.size(); ++index)
        {
            auto* candidate = entity_cache[index];
            if (candidate == nullptr || candidate == owned_weapon_entity)
            {
                continue;
            }

            std::uint32_t candidate_owner_handle = kInvalidEntityHandle;
            if (!SafeReadField(candidate, offsets.base_owner_entity, candidate_owner_handle) ||
                candidate_owner_handle != owned_weapon_handle)
            {
                continue;
            }

            if (standard_weapon && DescribeObservedPawnClassName(candidate) == L"C_CS2HudModelWeapon")
            {
                continue; // Even an indexed AG2 HUD object is render-only, not a world econ carrier.
            }

            ++trace.explicit_owner_child_count;
            if (trace.explicit_owner_child_entity == nullptr)
            {
                trace.explicit_owner_child_entity = candidate;
                trace.explicit_owner_child_entity_index = static_cast<int>(index);
                trace.explicit_owner_child_item_view = ResolveWeaponItemView(candidate, offsets);
                trace.owned_and_explicit_child_share_item_view =
                    trace.owned_weapon_item_view != nullptr &&
                    trace.owned_weapon_item_view == trace.explicit_owner_child_item_view;
                trace.explicit_owner_child_mesh_group_mask_valid =
                    TryReadWeaponMeshGroupMask(candidate, offsets, trace.explicit_owner_child_mesh_group_mask);
            }
        }
    }

    trace.hud_render_only_verified = standard_weapon && TryResolveStandardWeaponHudRender(
        entity_cache, player_binding, owned_weapon_handle, owned_weapon_entity, offsets,
        trace.hud_weapon_entity_index, trace.hud_weapon_entity, entity_list);
    // An AG2 C_CS2HudModelWeapon has a render model but no CEconItemView. Never
    // fabricate one by adding the CEconEntity offset to that shorter object.
    const auto resolved_hud_entity = trace.hud_render_only_verified || (!standard_weapon && (
        TryResolveHudWeaponEntity(
            entity_list,
            entity_cache,
            player_binding,
            owned_weapon_entity_index,
            offsets,
            trace.hud_weapon_entity_index,
            trace.hud_weapon_entity) ||
        TryResolveHudWeaponRenderEntity(
            entity_list,
            entity_cache,
            player_binding,
            owned_weapon_entity_index,
            offsets,
            trace.hud_weapon_entity_index,
            trace.hud_weapon_entity)));
    if (resolved_hud_entity)
    {
        trace.hud_weapon_item_view = trace.hud_render_only_verified
            ? nullptr : ResolveWeaponItemView(trace.hud_weapon_entity, offsets);
        trace.owned_and_hud_share_item_view =
            trace.owned_weapon_item_view != nullptr &&
            trace.owned_weapon_item_view == trace.hud_weapon_item_view;
        trace.hud_weapon_mesh_group_mask_valid =
            TryReadWeaponMeshGroupMask(trace.hud_weapon_entity, offsets, trace.hud_weapon_mesh_group_mask);
    }

    return true;
}

bool CanonicalWeaponCarrierDecisionIsSharedImpl(
    const nskinzcs2::runtime::CanonicalWeaponCarrierDecisionInputs& inputs) noexcept
{
    return inputs.world_hud_shared ||
        inputs.world_viewmodel_shared ||
        inputs.world_providee_shared ||
        inputs.hud_viewmodel_shared ||
        inputs.hud_providee_shared ||
        inputs.viewmodel_providee_shared;
}

nskinzcs2::runtime::CanonicalWeaponCarrierKind ResolveCanonicalWeaponCarrierKindImpl(
    const nskinzcs2::runtime::CanonicalWeaponCarrierDecisionInputs& inputs) noexcept
{
    using nskinzcs2::runtime::CanonicalWeaponCarrierKind;

    const auto has_only =
        [&inputs](const CanonicalWeaponCarrierKind kind)
        {
            switch (kind)
            {
            case CanonicalWeaponCarrierKind::World:
                return inputs.world_valid && !inputs.hud_valid && !inputs.viewmodel_valid && !inputs.providee_valid;
            case CanonicalWeaponCarrierKind::Hud:
                return !inputs.world_valid && inputs.hud_valid && !inputs.viewmodel_valid && !inputs.providee_valid;
            case CanonicalWeaponCarrierKind::ViewModel:
                return !inputs.world_valid && !inputs.hud_valid && inputs.viewmodel_valid && !inputs.providee_valid;
            case CanonicalWeaponCarrierKind::Providee:
                return !inputs.world_valid && !inputs.hud_valid && !inputs.viewmodel_valid && inputs.providee_valid;
            case CanonicalWeaponCarrierKind::None:
            default:
                return false;
            }
        };

    if (inputs.world_valid &&
        (inputs.world_hud_shared || inputs.world_viewmodel_shared || inputs.world_providee_shared || has_only(CanonicalWeaponCarrierKind::World)))
    {
        return CanonicalWeaponCarrierKind::World;
    }

    if (inputs.hud_valid &&
        (inputs.world_hud_shared || inputs.hud_viewmodel_shared || inputs.hud_providee_shared || has_only(CanonicalWeaponCarrierKind::Hud)))
    {
        return CanonicalWeaponCarrierKind::Hud;
    }

    if (inputs.viewmodel_valid &&
        (inputs.world_viewmodel_shared || inputs.hud_viewmodel_shared || inputs.viewmodel_providee_shared || has_only(CanonicalWeaponCarrierKind::ViewModel)))
    {
        return CanonicalWeaponCarrierKind::ViewModel;
    }

    if (inputs.providee_valid &&
        (inputs.world_providee_shared || inputs.hud_providee_shared || inputs.viewmodel_providee_shared || has_only(CanonicalWeaponCarrierKind::Providee)))
    {
        return CanonicalWeaponCarrierKind::Providee;
    }

    return CanonicalWeaponCarrierKind::None;
}

bool TryResolveHudWeaponSceneOwnerEntity(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int world_weapon_entity_index,
    const ClientSchemaOffsets& offsets,
    const bool require_matching_item_view,
    int& hud_weapon_entity_index,
    void*& hud_weapon_entity)
{
    hud_weapon_entity_index = -1;
    hud_weapon_entity = nullptr;

    if (entity_list == nullptr ||
        player_binding.pawn_entity == nullptr ||
        world_weapon_entity_index < 0 ||
        offsets.pawn_hud_model_arms == 0 ||
        offsets.base_entity_game_scene_node == 0 ||
        offsets.game_scene_node_child == 0 ||
        offsets.game_scene_node_next_sibling == 0 ||
        offsets.game_scene_node_owner == 0 ||
        offsets.base_owner_entity == 0)
    {
        return false;
    }

    void* world_weapon_entity = nullptr;
    if (world_weapon_entity_index >= static_cast<int>(entity_cache.size()) ||
        (world_weapon_entity = entity_cache[static_cast<std::size_t>(world_weapon_entity_index)]) == nullptr)
    {
        if (!TryGetEntityFromIndex(entity_list, world_weapon_entity_index, world_weapon_entity) ||
            world_weapon_entity == nullptr)
        {
            return false;
        }
    }

    int expected_definition_index = 0;
    std::uint32_t expected_account_id = 0;
    bool has_expected_account_id = false;
    if (require_matching_item_view)
    {
        const auto world_item_view = ResolveWeaponItemView(world_weapon_entity, offsets);
        if (world_item_view == nullptr ||
            !TryReadItemDefinitionIndex(world_item_view, offsets, expected_definition_index))
        {
            return false;
        }

        has_expected_account_id =
            offsets.item_view_account_id != 0 &&
            SafeReadField(world_item_view, offsets.item_view_account_id, expected_account_id);
    }

    std::uint32_t hud_model_arms_handle = kInvalidEntityHandle;
    if (!SafeReadField(player_binding.pawn_entity, offsets.pawn_hud_model_arms, hud_model_arms_handle))
    {
        return false;
    }

    const auto hud_model_arms_entity_index = HandleToEntityIndex(hud_model_arms_handle);
    if (hud_model_arms_entity_index < 0)
    {
        return false;
    }

    void* hud_model_arms_entity = nullptr;
    if (!TryGetEntityFromIndex(entity_list, hud_model_arms_entity_index, hud_model_arms_entity) ||
        hud_model_arms_entity == nullptr)
    {
        return false;
    }

    void* arms_scene_node = nullptr;
    if (!SafeReadField(hud_model_arms_entity, offsets.base_entity_game_scene_node, arms_scene_node) ||
        arms_scene_node == nullptr)
    {
        return false;
    }

    struct PendingSceneNode
    {
        void* scene_node = nullptr;
        int depth = 0;
    };

    void* first_child_scene_node = nullptr;
    if (!SafeReadField(arms_scene_node, offsets.game_scene_node_child, first_child_scene_node) ||
        first_child_scene_node == nullptr)
    {
        return false;
    }

    std::vector<PendingSceneNode> pending_scene_nodes;
    pending_scene_nodes.reserve(16);
    pending_scene_nodes.push_back({first_child_scene_node, 1});

    std::unordered_set<void*> visited_scene_nodes;
    std::unordered_set<void*> visited_owner_entities;
    int preferred_hud_weapon_entity_index = -1;
    void* preferred_hud_weapon_entity = nullptr;
    int preferred_hud_weapon_score = -1000000;
    bool preferred_hud_weapon_entity_weapon_like = false;
    while (!pending_scene_nodes.empty())
    {
        const auto pending = pending_scene_nodes.back();
        pending_scene_nodes.pop_back();
        auto* view_model_scene_node = pending.scene_node;
        if (view_model_scene_node == nullptr ||
            !visited_scene_nodes.insert(view_model_scene_node).second)
        {
            continue;
        }

        void* child_scene_node = nullptr;
        if (SafeReadField(view_model_scene_node, offsets.game_scene_node_child, child_scene_node) &&
            child_scene_node != nullptr)
        {
            pending_scene_nodes.push_back({child_scene_node, pending.depth + 1});
        }

        void* next_sibling_scene_node = nullptr;
        if (SafeReadField(
                view_model_scene_node,
                offsets.game_scene_node_next_sibling,
                next_sibling_scene_node) &&
            next_sibling_scene_node != nullptr)
        {
            pending_scene_nodes.push_back({next_sibling_scene_node, pending.depth});
        }

        void* owner_entity = nullptr;
        if (SafeReadField(view_model_scene_node, offsets.game_scene_node_owner, owner_entity) &&
            owner_entity != nullptr)
        {
            std::uint32_t owner_handle = kInvalidEntityHandle;
            if (SafeReadField(owner_entity, offsets.base_owner_entity, owner_handle) &&
                HandleToEntityIndex(owner_handle) == world_weapon_entity_index)
            {
                if (require_matching_item_view)
                {
                    const auto candidate_item_view = ResolveWeaponItemView(owner_entity, offsets);
                    int candidate_definition_index = 0;
                    if (candidate_item_view == nullptr ||
                        !TryReadItemDefinitionIndex(candidate_item_view, offsets, candidate_definition_index) ||
                        candidate_definition_index != expected_definition_index)
                    {
                        continue;
                    }

                    if (has_expected_account_id && expected_account_id != 0)
                    {
                        std::uint32_t candidate_account_id = 0;
                        if (!SafeReadField(candidate_item_view, offsets.item_view_account_id, candidate_account_id) ||
                            (candidate_account_id != 0 && candidate_account_id != expected_account_id))
                        {
                            continue;
                        }
                    }
                }

                if (require_matching_item_view)
                {
                    hud_weapon_entity = owner_entity;
                    hud_weapon_entity_index = ResolveEntityIndexFromPointer(entity_cache, hud_weapon_entity);
                    if (hud_weapon_entity_index < 0)
                    {
                        hud_weapon_entity_index = BuildSyntheticEntityIndex(hud_weapon_entity, 0x48554457u);
                    }
                    return true;
                }

                if (!visited_owner_entities.insert(owner_entity).second)
                {
                    continue;
                }

                auto candidate_entity_index = ResolveEntityIndexFromPointer(entity_cache, owner_entity);
                if (candidate_entity_index < 0)
                {
                    candidate_entity_index = BuildSyntheticEntityIndex(owner_entity, 0x48554457u);
                }

                const auto candidate_item_view = ResolveWeaponItemView(owner_entity, offsets);
                std::string candidate_model_name;
                TryReadEntityModelNameString(owner_entity, offsets, candidate_model_name);

                const auto in_characters_tree =
                    ContainsAsciiInsensitive(candidate_model_name, "characters/models/");
                const auto in_shared_arms_tree =
                    ContainsAsciiInsensitive(candidate_model_name, "shared/arms/");
                const auto has_arms_token =
                    ContainsAsciiInsensitive(candidate_model_name, "/arms/");
                const auto in_weapons_tree =
                    ContainsAsciiInsensitive(candidate_model_name, "/weapons/") ||
                    ContainsAsciiInsensitive(candidate_model_name, "weapons/models/");
                const auto has_knife_token =
                    ContainsAsciiInsensitive(candidate_model_name, "weapon_knife") ||
                    ContainsAsciiInsensitive(candidate_model_name, "/knife/") ||
                    ContainsAsciiInsensitive(candidate_model_name, "knife_");
                const auto weapon_like =
                    in_weapons_tree && has_knife_token && !in_shared_arms_tree && !has_arms_token;
                const auto character_like =
                    in_characters_tree || in_shared_arms_tree || has_arms_token ||
                    ContainsAsciiInsensitive(candidate_model_name, "glove_");

                auto candidate_score = 0;
                if (candidate_entity_index == world_weapon_entity_index)
                {
                    candidate_score -= 1000;
                }
                if (weapon_like)
                {
                    candidate_score += 400;
                }
                else if (character_like)
                {
                    candidate_score += 40;
                }
                if (candidate_item_view != nullptr)
                {
                    candidate_score += 30;
                }
                if (IsSyntheticRuntimeEntityIndex(candidate_entity_index))
                {
                    candidate_score += 80;
                }
                if (ContainsAsciiInsensitive(candidate_model_name, "glove_"))
                {
                    candidate_score -= 120;
                }

                if (preferred_hud_weapon_entity == nullptr || candidate_score > preferred_hud_weapon_score)
                {
                    preferred_hud_weapon_entity = owner_entity;
                    preferred_hud_weapon_entity_index = candidate_entity_index;
                    preferred_hud_weapon_score = candidate_score;
                    preferred_hud_weapon_entity_weapon_like = weapon_like;
                }
            }
        }
    }

    if (!require_matching_item_view &&
        preferred_hud_weapon_entity != nullptr &&
        preferred_hud_weapon_entity_weapon_like &&
        preferred_hud_weapon_entity_index != world_weapon_entity_index)
    {
        hud_weapon_entity = preferred_hud_weapon_entity;
        hud_weapon_entity_index = preferred_hud_weapon_entity_index;
        return true;
    }

    hud_weapon_entity = nullptr;
    hud_weapon_entity_index = -1;
    return false;
}

