void* ResolveGloveItemView(void* pawn_entity, const ClientSchemaOffsets& offsets)
{
    if (pawn_entity == nullptr)
    {
        return nullptr;
    }

    return reinterpret_cast<std::uint8_t*>(pawn_entity) + offsets.pawn_econ_gloves;
}

bool TryResolvePawnGloveSlotCarrier(
    void* pawn_entity,
    const ClientSchemaOffsets& offsets,
    void*& glove_item_view,
    int& current_definition_index)
{
    glove_item_view = ResolveGloveItemView(pawn_entity, offsets);
    current_definition_index = 0;
    return glove_item_view != nullptr &&
        TryReadItemDefinitionIndex(glove_item_view, offsets, current_definition_index);
}

bool TryReadItemDefinitionIndex(void* item_view, const ClientSchemaOffsets& offsets, int& definition_index)
{
    std::uint16_t raw_definition_index = 0;
    if (!SafeReadField(item_view, offsets.item_view_definition_index, raw_definition_index))
    {
        return false;
    }

    definition_index = static_cast<int>(raw_definition_index);
    return true;
}

std::uint32_t AccountIdFromXuid(const std::uint64_t xuid)
{
    return static_cast<std::uint32_t>(xuid & 0xFFFFFFFFull);
}

std::pair<std::uint32_t, std::uint32_t> SplitXuid(const std::uint64_t xuid)
{
    return {
        static_cast<std::uint32_t>(xuid & 0xFFFFFFFFull),
        static_cast<std::uint32_t>((xuid >> 32) & 0xFFFFFFFFull),
    };
}

std::uint64_t CombineXuidParts(const std::uint32_t low, const std::uint32_t high)
{
    return (static_cast<std::uint64_t>(high) << 32) | static_cast<std::uint64_t>(low);
}

bool LooksLikeSteamXuid(const std::uint64_t xuid)
{
    const auto parts = SplitXuid(xuid);
    return parts.first != 0 && parts.second == 0x01100001u;
}

int NormalizeBaseItem(
    const int definition_index,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices)
{
    if (knife_definition_indices.find(definition_index) != knife_definition_indices.end())
    {
        return 42;
    }

    if (glove_definition_indices.find(definition_index) != glove_definition_indices.end())
    {
        return 5028;
    }

    return definition_index;
}

bool IsKnifeBaseItem(const int definition_index)
{
    return definition_index == 42;
}

bool IsGloveBaseItem(const int definition_index)
{
    return definition_index == 5028;
}

bool IsStandardWeaponBaseItem(const int definition_index)
{
    switch (definition_index)
    {
    case 1:
    case 2:
    case 3:
    case 4:
    case 7:
    case 8:
    case 9:
    case 10:
    case 11:
    case 13:
    case 14:
    case 16:
    case 17:
    case 19:
    case 23:
    case 24:
    case 25:
    case 26:
    case 27:
    case 28:
    case 29:
    case 30:
    case 32:
    case 33:
    case 34:
    case 35:
    case 36:
    case 38:
    case 39:
    case 40:
    case 60:
    case 61:
    case 63:
    case 64:
        return true;
    default:
        return false;
    }
}

bool IsKnifeProfile(const nskinzcs2::model::CosmeticProfile& profile)
{
    return IsKnifeBaseItem(profile.base_item);
}

