std::string LookupNamedIdName(const std::vector<nskinzcs2::model::NamedId>& values, const int id)
{
    const auto it = std::find_if(
        values.begin(),
        values.end(),
        [id](const nskinzcs2::model::NamedId& value)
        {
            return value.id == id;
        });
    return it == values.end() ? "Unknown" : it->name;
}

int CompatibleGloveDefinitionForPaint(const nskinzcs2::model::Catalog& catalog, const int paint_kit)
{
    if (paint_kit == 0)
    {
        return 0;
    }

    const auto it = catalog.glove_paint_compatibility.find(paint_kit);
    return it == catalog.glove_paint_compatibility.end() ? 0 : it->second;
}

bool IsCompatibleGlovePaint(
    const nskinzcs2::model::Catalog& catalog,
    const int glove_definition_index,
    const int paint_kit)
{
    if (paint_kit == 0)
    {
        return true;
    }

    const auto compatible_glove_definition = CompatibleGloveDefinitionForPaint(catalog, paint_kit);
    return compatible_glove_definition != 0 && compatible_glove_definition == glove_definition_index;
}

