bool TryResolveKnifeEffectiveOwnerCarrier(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const ClientSchemaOffsets& offsets,
    const int world_weapon_entity_index,
    const int candidate_entity_index,
    const int fallback_definition_index,
    int& resolved_entity_index,
    void*& resolved_entity,
    int& resolved_definition_index) noexcept
{
    resolved_entity_index = -1;
    resolved_entity = nullptr;
    resolved_definition_index = 0;

    if (!IsResolvedRuntimeEntityIndex(candidate_entity_index) ||
        IsSyntheticRuntimeEntityIndex(candidate_entity_index) ||
        candidate_entity_index == world_weapon_entity_index)
    {
        return false;
    }

    if (candidate_entity_index >= 0 &&
        static_cast<std::size_t>(candidate_entity_index) < entity_cache.size())
    {
        resolved_entity = entity_cache[static_cast<std::size_t>(candidate_entity_index)];
    }

    if (resolved_entity == nullptr &&
        (!TryGetEntityFromIndex(entity_list, candidate_entity_index, resolved_entity) || resolved_entity == nullptr))
    {
        return false;
    }

    auto* item_view = ResolveWeaponItemView(resolved_entity, offsets);
    if (item_view == nullptr)
    {
        resolved_entity = nullptr;
        return false;
    }

    const auto model_kind = ClassifyKnifeFirstPersonRenderableModel(resolved_entity, offsets);
    if (model_kind == KnifeFirstPersonRenderableModelKind::Unknown)
    {
        resolved_entity = nullptr;
        return false;
    }

    int raw_definition_index = 0;
    TryReadItemDefinitionIndex(item_view, offsets, raw_definition_index);

    resolved_entity_index = candidate_entity_index;
    resolved_definition_index =
        model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike
            ? (fallback_definition_index != 0 ? fallback_definition_index : raw_definition_index)
            : (raw_definition_index != 0 ? raw_definition_index : fallback_definition_index);
    return true;
}

KnifeEffectiveOwnerBindingState ResolveKnifeEffectiveOwnerBindingState(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int world_weapon_entity_index,
    const ClientSchemaOffsets& offsets,
    const int fallback_definition_index,
    const nskinzcs2::runtime::KnifeRuntimeContext* context) noexcept
{
    KnifeEffectiveOwnerBindingState state {};

    auto resolve_owner =
        [&](const int candidate_entity_index,
            const int current_definition_index,
            int& target_entity_index,
            int& target_definition_index,
            bool& target_valid)
        {
            void* resolved_entity = nullptr;
            int resolved_definition_index = 0;
            if (!TryResolveKnifeEffectiveOwnerCarrier(
                    entity_list,
                    entity_cache,
                    offsets,
                    world_weapon_entity_index,
                    candidate_entity_index,
                    current_definition_index != 0 ? current_definition_index : fallback_definition_index,
                    target_entity_index,
                    resolved_entity,
                    resolved_definition_index))
            {
                return false;
            }

            target_definition_index = resolved_definition_index;
            target_valid = true;
            return true;
        };

    if (context != nullptr)
    {
        resolve_owner(
            context->providee_entity_index,
            context->providee_definition_index,
            state.providee_entity_index,
            state.providee_definition_index,
            state.providee_valid);
        resolve_owner(
            context->viewmodel_entity_index,
            context->viewmodel_definition_index,
            state.viewmodel_entity_index,
            state.viewmodel_definition_index,
            state.viewmodel_valid);
    }

    const auto player_weapon_binding_it =
        player_binding.weapons_by_entity_index.find(world_weapon_entity_index);
    if (player_weapon_binding_it == player_binding.weapons_by_entity_index.end())
    {
        return state;
    }

    if (!state.providee_valid &&
        resolve_owner(
            player_weapon_binding_it->second.providee_entity_index,
            context != nullptr ? context->providee_definition_index : fallback_definition_index,
            state.providee_entity_index,
            state.providee_definition_index,
            state.providee_valid))
    {
        state.providee_from_player_binding = true;
        state.used_player_binding_fallback = true;
    }

    if (!state.viewmodel_valid &&
        resolve_owner(
            player_weapon_binding_it->second.viewmodel_entity_index,
            context != nullptr ? context->viewmodel_definition_index : fallback_definition_index,
            state.viewmodel_entity_index,
            state.viewmodel_definition_index,
            state.viewmodel_valid))
    {
        state.viewmodel_from_player_binding = true;
        state.used_player_binding_fallback = true;
    }

    return state;
}

void LogKnifeEffectiveOwnerBindingState(
    const wchar_t* stage,
    const std::uint64_t xuid,
    const int world_weapon_entity_index,
    const nskinzcs2::runtime::KnifeRuntimeContext* context,
    const KnifeEffectiveOwnerBindingState& state)
{
    if (!state.used_player_binding_fallback || !ShouldLogWatchedKnifeAnimationTrace(xuid))
    {
        return;
    }

    std::wstringstream stream;
    stream << L"Knife " << (stage != nullptr ? stage : L"owner binding")
        << L" restored owner indices from player binding: world_entity=" << world_weapon_entity_index
        << L", providee_entity=" << state.providee_entity_index
        << L", providee_valid=" << (state.providee_valid ? 1 : 0)
        << L", viewmodel_entity=" << state.viewmodel_entity_index
        << L", viewmodel_valid=" << (state.viewmodel_valid ? 1 : 0)
        << L", providee_from_player_binding=" << (state.providee_from_player_binding ? 1 : 0)
        << L", viewmodel_from_player_binding=" << (state.viewmodel_from_player_binding ? 1 : 0);
    if (context != nullptr)
    {
        stream << L", original_providee_entity=" << context->providee_entity_index
            << L", original_viewmodel_entity=" << context->viewmodel_entity_index;
    }
    stream << L", reason=context_owner_indices_missing";
    nskinzcs2::Logger::Info(stream.str());
}

const wchar_t* KnifeViewmodelAbsenceAuditResultTextForTrace(const std::uint32_t raw_result) noexcept
{
    switch (static_cast<nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult>(raw_result))
    {
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::MissingHandle:
        return L"missing_handle";
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::StaleHandle:
        return L"stale_handle";
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::ShellWithoutWritableCarrier:
        return L"shell_without_writable_carrier";
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::NonQualifyingCandidate:
        return L"non_qualifying_candidate";
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::SyntheticAliasOnly:
        return L"synthetic_alias_only";
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::Skipped:
    default:
        return L"skipped";
    }
}

void LogWatchedKnifeViewmodelResolutionTrace(
    const wchar_t* stage,
    const std::uint64_t xuid,
    const nskinzcs2::runtime::KnifeRuntimeContext& context)
{
    if (!ShouldLogWatchedKnifeAnimationTrace(xuid))
    {
        return;
    }

    std::wstringstream stream;
    stream << L"Watched knife viewmodel trace: stage="
        << (stage != nullptr ? stage : L"runtime_context")
        << L", world_entity=" << context.world_entity_index
        << L", world_definition=" << context.world_definition_index
        << L", resolution_source="
        << (context.viewmodel_resolution_source != nullptr
                ? context.viewmodel_resolution_source
                : L"none")
        << L", shell_entity=" << context.viewmodel_shell_entity_index
        << L", carrier_entity=" << context.viewmodel_carrier_entity_index
        << L", render_entity=" << context.viewmodel_render_entity_index
        << L", absence_result="
        << KnifeViewmodelAbsenceAuditResultTextForTrace(context.viewmodel_absence_audit_result)
        << L", viewmodel_entity=" << context.viewmodel_entity_index
        << L", viewmodel_valid=" << (context.viewmodel_carrier_valid ? 1 : 0)
        << L", viewmodel_definition=" << context.viewmodel_definition_index
        << L", providee_entity=" << context.providee_entity_index
        << L", providee_valid=" << (context.providee_carrier_valid ? 1 : 0)
        << L", providee_definition=" << context.providee_definition_index
        << L", direct_render_entity=" << context.direct_first_person_render_entity_index
        << L", direct_render_valid=" << (context.direct_first_person_render_valid ? 1 : 0)
        << L", direct_render_only=" << (context.direct_first_person_render_only ? 1 : 0)
        << L", animation_owner_entity=" << context.direct_first_person_animation_owner_entity_index
        << L", animation_owner_valid=" << (context.direct_first_person_animation_owner_valid ? 1 : 0)
        << L", observer_chain=" << (context.observer_chain_present ? 1 : 0)
        << L", observer_in_eye=" << (context.observer_in_eye_valid ? 1 : 0)
        << L", observer_target_xuid=" << context.observer_target_xuid
        << L", observer_target_pawn=" << context.observer_target_pawn_entity_index
        << L", observer_active_weapon=" << context.observer_active_weapon_entity_index
        << L", observer_active_weapon_is_knife=" << (context.observer_active_weapon_is_knife ? 1 : 0)
        << L", bridge_source=" << (context.bridge_source != nullptr ? context.bridge_source : L"none")
        << L", bridge_cache_hit=" << (context.bridge_cache_hit ? 1 : 0)
        << L", bridged_controller=" << context.bridged_controller_entity_index
        << L", bridged_pawn=" << context.bridged_pawn_entity_index
        << L", bridge_pawn_health=";
    if (context.bridge_pawn_alive || context.bridge_pawn_health != 0)
    {
        stream << context.bridge_pawn_health;
    }
    else
    {
        stream << L"?";
    }
    stream << L", bridge_pawn_alive=" << (context.bridge_pawn_alive ? 1 : 0)
        << L", bridge_active_weapon=" << context.bridge_active_weapon_entity_index
        << L", bridge_active_weapon_is_knife=" << (context.bridge_active_weapon_is_knife ? 1 : 0)
        << L", real_viewmodel_entity=" << context.real_viewmodel_entity_index
        << L", real_viewmodel_weapon_entity=" << context.real_viewmodel_weapon_entity_index
        << L", real_viewmodel_services=" << (context.real_viewmodel_services_present ? 1 : 0)
        << L", real_viewmodel_handle_valid=" << (context.real_viewmodel_handle_valid ? 1 : 0)
        << L", real_viewmodel_handle_invalid=" << (context.real_viewmodel_handle_invalid ? 1 : 0)
        << L", real_viewmodel_weapon_matches_active="
        << (context.real_viewmodel_weapon_matches_active_weapon ? 1 : 0)
        << L", real_viewmodel_verified_knife="
        << (context.real_viewmodel_active_weapon_verified_knife ? 1 : 0)
        << L", hud_fallback_allowed=" << (context.hud_proxy_fallback_allowed ? 1 : 0)
        << L", owner_kind="
        << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(context.first_person_owner_kind)
        << L", first_person_source_definition=" << context.first_person_source_definition_index
        << L", first_person_source_valid=" << (context.first_person_source_valid ? 1 : 0)
        << L", knife_sync_ready=" << (context.knife_sync_ready ? 1 : 0);
    nskinzcs2::Logger::Info(stream.str());
}

