bool ObservedRuntimeEntityLooksLikePawn(
    const std::unordered_map<int, std::uint64_t>& pawn_xuids,
    const int entity_index,
    void* entity)
{
    if (entity_index >= 0)
    {
        const auto pawn_it = pawn_xuids.find(entity_index);
        if (pawn_it != pawn_xuids.end() && LooksLikeSteamXuid(pawn_it->second))
        {
            return true;
        }
    }

    if (entity == nullptr)
    {
        return false;
    }

    const auto rtti = BuildRuntimeEntityRttiDescriptor(entity);
    return rtti.find(L"PlayerPawn") != std::wstring::npos ||
        rtti.find(L"ObserverPawn") != std::wstring::npos;
}

std::wstring BuildObservedPawnCandidateSummary(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const std::unordered_map<int, std::uint64_t>& pawn_xuids,
    const void* base,
    const std::size_t max_offset)
{
    if (base == nullptr || max_offset == 0)
    {
        return L"none";
    }

    std::wstringstream stream;
    bool wrote_entry = false;
    int emitted = 0;

    auto append_candidate =
        [&](const wchar_t* source_kind,
            const std::size_t offset,
            const std::uint64_t raw_value,
            const int entity_index,
            void* entity)
        {
            if (wrote_entry)
            {
                stream << L" | ";
            }

            stream << (source_kind != nullptr ? source_kind : L"candidate")
                << L"+0x" << std::hex << std::uppercase << offset
                << L"=0x" << raw_value
                << std::dec << std::nouppercase
                << L"{entity=" << entity_index
                << L", ptr=" << FormatPointer(entity)
                << L", rtti=" << BuildRuntimeEntityRttiDescriptor(entity);

            const auto pawn_it = pawn_xuids.find(entity_index);
            if (pawn_it != pawn_xuids.end() && LooksLikeSteamXuid(pawn_it->second))
            {
                stream << L", xuid=" << pawn_it->second;
            }

            stream << L"}";
            wrote_entry = true;
            ++emitted;
        };

    for (std::size_t offset = 0; offset < max_offset; offset += sizeof(std::uint32_t))
    {
        std::uint32_t raw = 0;
        if (!SafeReadField(base, static_cast<std::ptrdiff_t>(offset), raw) ||
            raw == 0 ||
            raw == kInvalidEntityHandle ||
            !IsPlausibleEntityHandle(raw))
        {
            continue;
        }

        int entity_index = -1;
        void* entity = nullptr;
        if (!TryResolveRuntimeEntityFromHandle(entity_list, entity_cache, raw, entity_index, entity) ||
            !ObservedRuntimeEntityLooksLikePawn(pawn_xuids, entity_index, entity))
        {
            continue;
        }

        append_candidate(L"handle", offset, raw, entity_index, entity);
        if (emitted >= 12)
        {
            stream << L" | ...";
            return stream.str();
        }
    }

    for (std::size_t offset = 0; offset + sizeof(std::uintptr_t) <= max_offset; offset += sizeof(std::uintptr_t))
    {
        std::uintptr_t raw = 0;
        if (!SafeReadField(base, static_cast<std::ptrdiff_t>(offset), raw) || raw == 0)
        {
            continue;
        }

        auto* entity = reinterpret_cast<void*>(raw);
        const auto entity_index = ResolveEntityIndexFromPointer(entity_cache, entity);
        if (entity_index < 0 || !ObservedRuntimeEntityLooksLikePawn(pawn_xuids, entity_index, entity))
        {
            continue;
        }

        append_candidate(L"pointer", offset, raw, entity_index, entity);
        if (emitted >= 12)
        {
            stream << L" | ...";
            return stream.str();
        }
    }

    return wrote_entry ? stream.str() : L"none";
}

struct ObservedReadablePointerCandidate
{
    std::ptrdiff_t offset = 0;
    const void* pointer = nullptr;
};

std::vector<ObservedReadablePointerCandidate> CollectObservedReadablePointerCandidates(
    const void* base,
    const std::size_t max_offset,
    const std::vector<void*>& entity_cache,
    const std::vector<const void*>& excluded_pointers,
    const std::size_t max_candidates = 4)
{
    std::vector<ObservedReadablePointerCandidate> candidates;
    if (base == nullptr || max_offset == 0 || max_candidates == 0)
    {
        return candidates;
    }

    auto is_excluded =
        [&](const void* pointer) noexcept
        {
            if (pointer == nullptr)
            {
                return true;
            }

            for (const auto* excluded : excluded_pointers)
            {
                if (excluded == pointer)
                {
                    return true;
                }
            }

            for (const auto& candidate : candidates)
            {
                if (candidate.pointer == pointer)
                {
                    return true;
                }
            }

            return false;
        };

    for (std::size_t offset = 0; offset + sizeof(std::uintptr_t) <= max_offset; offset += sizeof(std::uintptr_t))
    {
        std::uintptr_t raw = 0;
        if (!SafeReadField(base, static_cast<std::ptrdiff_t>(offset), raw) || raw == 0)
        {
            continue;
        }

        const auto* pointer = reinterpret_cast<const void*>(raw);
        if (is_excluded(pointer))
        {
            continue;
        }

        if (GetModuleFromAddress(pointer) != nullptr ||
            !IsReadablePointer(pointer) ||
            ResolveEntityIndexFromPointer(entity_cache, const_cast<void*>(pointer)) >= 0)
        {
            continue;
        }

        candidates.push_back({static_cast<std::ptrdiff_t>(offset), pointer});
        if (candidates.size() >= max_candidates)
        {
            break;
        }
    }

    return candidates;
}

std::wstring BuildObservedReadablePointerCandidateSummary(
    const std::vector<ObservedReadablePointerCandidate>& candidates)
{
    if (candidates.empty())
    {
        return L"none";
    }

    std::wstringstream stream;
    bool wrote_entry = false;
    for (const auto& candidate : candidates)
    {
        if (candidate.pointer == nullptr)
        {
            continue;
        }

        if (wrote_entry)
        {
            stream << L" | ";
        }

        stream << L"+0x" << std::hex << std::uppercase << candidate.offset
            << L"=" << FormatPointer(candidate.pointer)
            << std::dec << std::nouppercase
            << L", rtti=" << BuildRuntimeEntityRttiDescriptor(candidate.pointer)
            << L", region=" << DescribeReadableMemoryRegion(candidate.pointer, 16);
        wrote_entry = true;
    }

    return wrote_entry ? stream.str() : L"none";
}

void LogObservedRelaySubobjectTrace(
    const std::uint64_t signature,
    const wchar_t* label,
    const wchar_t* parent_label,
    const std::ptrdiff_t parent_offset,
    const void* parent_object,
    const void* subobject,
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const std::unordered_map<int, std::uint64_t>& pawn_xuids,
    const ClientSchemaOffsets& offsets,
    void* observer_pawn_entity,
    void* observer_controller_entity,
    void* relay_services,
    void* sibling_subobject,
    void* scene_node,
    void* scene_owner_entity,
    void* viewmodel_services)
{
    if (subobject == nullptr)
    {
        return;
    }

    const auto object_backrefs = BuildObservedPointerBackrefSummary(entity_cache, offsets, subobject);
    const auto pawn_candidates =
        BuildObservedPawnCandidateSummary(entity_list, entity_cache, pawn_xuids, subobject, 0x120);
    const auto pointer_window =
        BuildObservedPointerWindow(
            subobject,
            0x120,
            entity_cache,
            {
                {subobject, L"self"},
                {parent_object, L"parent"},
                {relay_services, L"relay_services"},
                {observer_pawn_entity, L"observer_pawn"},
                {observer_controller_entity, L"observer_controller"},
                {scene_node, L"observer_scene_node"},
                {scene_owner_entity, L"scene_owner"},
                {viewmodel_services, L"viewmodel_services"},
                {sibling_subobject, L"sibling"},
            });
    const auto handle_window = BuildObservedHandleWindow(subobject, 0x120, entity_list, entity_cache);

    std::wstringstream stream;
    stream << L"Watched knife observer relay subobject trace: label="
        << (label != nullptr ? label : L"unknown")
        << L", parent_label=" << (parent_label != nullptr ? parent_label : L"unknown")
        << L", parent=" << FormatPointer(parent_object)
        << L", parent_offset=0x" << std::hex << std::uppercase << parent_offset
        << std::dec << std::nouppercase
        << L", ptr=" << FormatPointer(subobject)
        << L", rtti=" << BuildRuntimeEntityRttiDescriptor(subobject)
        << L", region=" << DescribeReadableMemoryRegion(subobject, 16)
        << L", known_backrefs=["
        << (parent_label != nullptr ? parent_label : L"parent")
        << L"+0x";
    stream << std::hex << std::uppercase << parent_offset
        << std::dec << std::nouppercase
        << L"]";
    if (object_backrefs != L"none")
    {
        stream << L", entity_backrefs=[" << object_backrefs << L"]";
    }
    else
    {
        stream << L", entity_backrefs=[none]";
    }
    stream << L", pawn_candidates=[" << pawn_candidates
        << L"], handle_window=[" << handle_window
        << L"], pointer_window=[" << pointer_window
        << L"]";

    LogProfileDiagnosticOnce(signature, stream.str());
}

void LogObservedCameraServicesFixedChildTrace(
    const std::uint64_t signature,
    const wchar_t* parent_label,
    const void* camera_services_object,
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const std::unordered_map<int, std::uint64_t>& pawn_xuids,
    const ClientSchemaOffsets& offsets,
    void* observer_pawn_entity,
    void* observer_controller_entity,
    void* relay_services,
    void* scene_node,
    void* scene_owner_entity,
    void* viewmodel_services);

void LogObservedRelayTertiaryTrace(
    const std::uint64_t signature,
    const wchar_t* parent_label,
    const void* parent_object,
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const std::unordered_map<int, std::uint64_t>& pawn_xuids,
    const ClientSchemaOffsets& offsets,
    void* observer_pawn_entity,
    void* observer_controller_entity,
    void* relay_services,
    void* scene_node,
    void* scene_owner_entity,
    void* viewmodel_services)
{
    if (parent_object == nullptr)
    {
        return;
    }

    const auto child_candidates =
        CollectObservedReadablePointerCandidates(
            parent_object,
            0x120,
            entity_cache,
            {
                parent_object,
                relay_services,
                observer_pawn_entity,
                observer_controller_entity,
                scene_node,
                scene_owner_entity,
                viewmodel_services,
            });

    {
        std::wstringstream summary;
        summary << L"Watched knife observer relay tertiary candidate summary: parent_label="
            << (parent_label != nullptr ? parent_label : L"unknown")
            << L", parent_ptr=" << FormatPointer(parent_object)
            << L", parent_rtti=" << BuildRuntimeEntityRttiDescriptor(parent_object)
            << L", readable_children=[" << BuildObservedReadablePointerCandidateSummary(child_candidates)
            << L"]";
        LogProfileDiagnosticOnce(signature ^ 0x700ull, summary.str());
    }

    int candidate_ordinal = 0;
    for (const auto& candidate : child_candidates)
    {
        if (candidate.pointer == nullptr)
        {
            continue;
        }

        const auto candidate_rtti = BuildRuntimeEntityRttiDescriptor(candidate.pointer);
        std::wstringstream label_stream;
        label_stream << (parent_label != nullptr ? parent_label : L"parent")
            << L":child_0x" << std::hex << std::uppercase << candidate.offset
            << std::dec << std::nouppercase;

        const auto label = label_stream.str();
        LogObservedRelaySubobjectTrace(
            signature ^ 0x900ull ^ (static_cast<std::uint64_t>(candidate.offset) << 4) ^
                static_cast<std::uint64_t>(candidate_ordinal + 1),
            label.c_str(),
            parent_label,
            candidate.offset,
            parent_object,
            candidate.pointer,
            entity_list,
            entity_cache,
            pawn_xuids,
            offsets,
            observer_pawn_entity,
            observer_controller_entity,
            relay_services,
            nullptr,
            scene_node,
            scene_owner_entity,
            viewmodel_services);

        if (candidate_rtti.find(L"CCSObserver_CameraServices") != std::wstring::npos)
        {
            LogObservedCameraServicesFixedChildTrace(
                signature ^ 0xC40ull ^ (static_cast<std::uint64_t>(candidate.offset) << 6) ^
                    static_cast<std::uint64_t>(candidate_ordinal + 1),
                label.c_str(),
                candidate.pointer,
                entity_list,
                entity_cache,
                pawn_xuids,
                offsets,
                observer_pawn_entity,
                observer_controller_entity,
                relay_services,
                scene_node,
                scene_owner_entity,
                viewmodel_services);
        }
        ++candidate_ordinal;
    }
}

void LogObservedCameraServicesFixedChildTrace(
    const std::uint64_t signature,
    const wchar_t* parent_label,
    const void* camera_services_object,
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const std::unordered_map<int, std::uint64_t>& pawn_xuids,
    const ClientSchemaOffsets& offsets,
    void* observer_pawn_entity,
    void* observer_controller_entity,
    void* relay_services,
    void* scene_node,
    void* scene_owner_entity,
    void* viewmodel_services)
{
    if (camera_services_object == nullptr)
    {
        return;
    }

    void* camera_child_40 = nullptr;
    const bool camera_child_40_readable =
        SafeReadField(camera_services_object, 0x40, camera_child_40);

    std::wstringstream summary;
    summary << L"Watched knife observer camera-services fixed child trace: parent_label="
        << (parent_label != nullptr ? parent_label : L"unknown")
        << L", parent_ptr=" << FormatPointer(camera_services_object)
        << L", parent_rtti=" << BuildRuntimeEntityRttiDescriptor(camera_services_object)
        << L", child_offset=0x40"
        << L", child_readable=" << (camera_child_40_readable ? 1 : 0)
        << L", child_ptr=" << FormatPointer(camera_child_40);
    if (camera_child_40 != nullptr)
    {
        summary << L", child_rtti=" << BuildRuntimeEntityRttiDescriptor(camera_child_40)
            << L", child_region=" << DescribeReadableMemoryRegion(camera_child_40, 16);
    }
    else
    {
        summary << L", child_rtti=none, child_region=none";
    }
    LogProfileDiagnosticOnce(signature ^ 0xA40ull, summary.str());

    if (!camera_child_40_readable || camera_child_40 == nullptr)
    {
        return;
    }

    std::wstring label =
        std::wstring(parent_label != nullptr ? parent_label : L"camera_services") + L":child_0x40";
    LogObservedRelaySubobjectTrace(
        signature ^ 0xB40ull,
        label.c_str(),
        parent_label,
        0x40,
        camera_services_object,
        camera_child_40,
        entity_list,
        entity_cache,
        pawn_xuids,
        offsets,
        observer_pawn_entity,
        observer_controller_entity,
        relay_services,
        nullptr,
        scene_node,
        scene_owner_entity,
        viewmodel_services);
}

void LogControllerObserverRawScan(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const ClientSchemaOffsets& offsets,
    const ObserverTargetResolution& observer_resolution,
    const std::uint64_t heuristic_watched_xuid,
    const WatchedXuidResolution& watched_resolution)
{
    if (observer_resolution.state == ObserverTargetResolutionState::Resolved &&
        observer_resolution.observer_source == ObserverSourceKind::Controller)
    {
        return;
    }

    if (!ObserverTargetResolutionHasChain(observer_resolution) &&
        heuristic_watched_xuid == 0 &&
        watched_resolution.watched_xuid == 0 &&
        g_hook_state.runtime_trace_polls_remaining.load() <= 0)
    {
        return;
    }

    std::uint64_t scan_signature = 0xC0417EADBEAD1201ull;
    scan_signature ^= watched_resolution.watched_xuid;
    scan_signature ^= (heuristic_watched_xuid << 1);
    scan_signature ^= (static_cast<std::uint64_t>(observer_resolution.observer_controller_entity_index + 2) << 16);
    scan_signature ^= (static_cast<std::uint64_t>(observer_resolution.observer_pawn_entity_index + 2) << 32);
    scan_signature ^= static_cast<std::uint64_t>(observer_resolution.state == ObserverTargetResolutionState::Resolved ? 1 : 0)
        << 48;
    scan_signature ^=
        static_cast<std::uint64_t>(std::hash<std::wstring> {}(observer_resolution.failure_reason));

    {
        std::wstringstream summary;
        summary << L"Watched knife controller raw scan trigger: observer_state="
            << ObserverTargetResolutionStateText(observer_resolution.state)
            << L", observer_source=" << ObserverSourceKindText(observer_resolution.observer_source)
            << L", final_watched_xuid=" << watched_resolution.watched_xuid
            << L", heuristic_watched_xuid=" << heuristic_watched_xuid
            << L", observer_controller=" << observer_resolution.observer_controller_entity_index
            << L", observer_pawn=" << observer_resolution.observer_pawn_entity_index
            << L", observer_target_handle_valid=" << (observer_resolution.observer_target_handle_valid ? 1 : 0)
            << L", observer_services=" << (observer_resolution.observer_services_present ? 1 : 0);
        if (!observer_resolution.failure_reason.empty())
        {
            summary << L", failure_reason=" << observer_resolution.failure_reason;
        }
        LogProfileDiagnosticOnce(scan_signature, summary.str());
    }

    for (std::size_t entity_index = 0; entity_index < entity_cache.size(); ++entity_index)
    {
        auto* entity = entity_cache[entity_index];
        if (entity == nullptr)
        {
            continue;
        }

        bool controller_like = false;
        std::uint64_t steam_id = 0;
        const bool steam_id_readable =
            offsets.controller_steam_id != 0 &&
            SafeReadField(entity, offsets.controller_steam_id, steam_id);
        controller_like = steam_id_readable && LooksLikeSteamXuid(steam_id);

        std::uint32_t pawn_handle = kInvalidEntityHandle;
        const bool pawn_handle_readable =
            offsets.controller_pawn != 0 &&
            SafeReadField(entity, offsets.controller_pawn, pawn_handle);
        const bool pawn_handle_valid =
            pawn_handle_readable &&
            pawn_handle != 0 &&
            pawn_handle != kInvalidEntityHandle &&
            IsPlausibleEntityHandle(pawn_handle);
        controller_like = controller_like || pawn_handle_valid;
        if (!controller_like)
        {
            continue;
        }

        void* observer_services = nullptr;
        const bool observer_services_readable =
            offsets.controller_observer_services != 0 &&
            SafeReadField(entity, offsets.controller_observer_services, observer_services);
        const bool observer_services_present = observer_services_readable && observer_services != nullptr;

        std::uint8_t direct_mode = 0;
        const bool direct_mode_readable =
            offsets.controller_observer_mode != 0 &&
            SafeReadField(entity, offsets.controller_observer_mode, direct_mode);

        std::uint32_t direct_target_handle = kInvalidEntityHandle;
        const bool direct_target_handle_readable =
            offsets.controller_observer_target != 0 &&
            SafeReadField(entity, offsets.controller_observer_target, direct_target_handle);
        const bool direct_target_handle_valid =
            direct_target_handle_readable &&
            direct_target_handle != 0 &&
            direct_target_handle != kInvalidEntityHandle &&
            IsPlausibleEntityHandle(direct_target_handle);

        std::uint8_t service_mode = 0;
        const bool service_mode_readable =
            observer_services_present &&
            offsets.observer_services_mode != 0 &&
            SafeReadField(observer_services, offsets.observer_services_mode, service_mode);

        std::uint32_t service_target_handle = kInvalidEntityHandle;
        const bool service_target_handle_readable =
            observer_services_present &&
            offsets.observer_services_target != 0 &&
            SafeReadField(observer_services, offsets.observer_services_target, service_target_handle);
        const bool service_target_handle_valid =
            service_target_handle_readable &&
            service_target_handle != 0 &&
            service_target_handle != kInvalidEntityHandle &&
            IsPlausibleEntityHandle(service_target_handle);

        auto describe_handle =
            [&](const std::uint32_t handle) -> std::wstring
            {
                if (handle == kInvalidEntityHandle)
                {
                    return L"0xFFFFFFFF(invalid)";
                }

                std::wstringstream handle_stream;
                handle_stream << L"0x" << std::hex << std::uppercase << handle
                    << std::dec << std::nouppercase;

                int resolved_entity_index = -1;
                void* resolved_entity = nullptr;
                if (TryResolveRuntimeEntityFromHandle(
                        entity_list,
                        entity_cache,
                        handle,
                        resolved_entity_index,
                        resolved_entity))
                {
                    handle_stream << L"(idx=" << resolved_entity_index
                        << L",ptr=" << FormatPointer(resolved_entity)
                        << L",rtti=" << BuildRuntimeEntityRttiDescriptor(resolved_entity) << L")";
                }
                else
                {
                    handle_stream << L"(idx=" << HandleToEntityIndex(handle) << L",unresolved=1)";
                }

                return handle_stream.str();
            };

        std::wstringstream stream;
        stream << L"Watched knife controller raw scan: entity=" << static_cast<int>(entity_index)
            << L", ptr=" << FormatPointer(entity)
            << L", controller_rtti=" << BuildRuntimeEntityRttiDescriptor(entity)
            << L", steam_id=";
        if (steam_id_readable)
        {
            stream << steam_id;
        }
        else
        {
            stream << L"?";
        }
        stream << L", pawn_handle=";
        if (pawn_handle_readable)
        {
            stream << describe_handle(pawn_handle);
        }
        else
        {
            stream << L"?";
        }
        stream << L", direct_mode=";
        if (direct_mode_readable)
        {
            stream << static_cast<int>(direct_mode);
        }
        else
        {
            stream << L"?";
        }
        stream << L", direct_target=";
        if (direct_target_handle_readable)
        {
            stream << describe_handle(direct_target_handle);
        }
        else
        {
            stream << L"?";
        }
        stream << L", direct_target_valid=" << (direct_target_handle_valid ? 1 : 0)
            << L", observer_services_ptr=" << FormatPointer(observer_services)
            << L", observer_services_present=" << (observer_services_present ? 1 : 0)
            << L", observer_services_rtti=";
        if (observer_services_present)
        {
            stream << BuildRuntimeEntityRttiDescriptor(observer_services);
        }
        else
        {
            stream << L"none";
        }
        stream << L", services_mode=";
        if (service_mode_readable)
        {
            stream << static_cast<int>(service_mode);
        }
        else
        {
            stream << L"?";
        }
        stream << L", services_target=";
        if (service_target_handle_readable)
        {
            stream << describe_handle(service_target_handle);
        }
        else
        {
            stream << L"?";
        }
        stream << L", services_target_valid=" << (service_target_handle_valid ? 1 : 0)
            << L", controller_handle_window=["
            << BuildObservedHandleWindow(entity, 0x100, entity_list, entity_cache)
            << L"]";
        if (observer_services_present)
        {
            stream << L", observer_services_handle_window=["
                << BuildObservedHandleWindow(observer_services, 0x80, entity_list, entity_cache)
                << L"]";
        }
        LogProfileDiagnosticOnce(
            scan_signature ^ (static_cast<std::uint64_t>(entity_index) + 1ull),
            stream.str());
    }
}

void LogObserverPawnRelayTrace(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const std::unordered_map<int, std::uint64_t>& pawn_xuids,
    const ClientSchemaOffsets& offsets,
    const ObserverTargetResolution& observer_resolution,
    const WatchedXuidResolution& watched_resolution)
{
    void* observer_pawn_entity = observer_resolution.observer_intermediate_target_entity;
    auto observer_pawn_entity_index = observer_resolution.observer_intermediate_target_entity_index;
    if (observer_pawn_entity == nullptr)
    {
        if (observer_resolution.target_xuid == 0 &&
            observer_resolution.target_pawn_entity != nullptr)
        {
            observer_pawn_entity = observer_resolution.target_pawn_entity;
            observer_pawn_entity_index = observer_resolution.target_pawn_entity_index;
        }
        else
        {
            return;
        }
    }

    std::uint64_t signature = 0x0B5E6F1A7E2D44A1ull;
    signature ^= watched_resolution.watched_xuid;
    signature ^= (static_cast<std::uint64_t>(observer_resolution.observer_controller_entity_index + 2) << 16);
    signature ^= (static_cast<std::uint64_t>(observer_pawn_entity_index + 2) << 32);
    signature ^= static_cast<std::uint64_t>(observer_resolution.observer_target_relay_used ? 1 : 0) << 48;

    void* relay_services = nullptr;
    const bool relay_services_present =
        offsets.pawn_observer_services != 0 &&
        SafeReadField(observer_pawn_entity, offsets.pawn_observer_services, relay_services) &&
        relay_services != nullptr;

    std::uint8_t relay_mode = 0;
    const bool relay_mode_readable =
        relay_services_present &&
        offsets.observer_services_mode != 0 &&
        SafeReadField(relay_services, offsets.observer_services_mode, relay_mode);

    std::uint32_t relay_target_handle = kInvalidEntityHandle;
    const bool relay_target_handle_readable =
        relay_services_present &&
        offsets.observer_services_target != 0 &&
        SafeReadField(relay_services, offsets.observer_services_target, relay_target_handle);
    const bool relay_target_handle_valid =
        relay_target_handle_readable &&
        relay_target_handle != 0 &&
        relay_target_handle != kInvalidEntityHandle &&
        IsPlausibleEntityHandle(relay_target_handle);

    std::uint32_t controller_handle = kInvalidEntityHandle;
    const bool controller_handle_readable =
        offsets.pawn_controller != 0 &&
        SafeReadField(observer_pawn_entity, offsets.pawn_controller, controller_handle);
    const auto controller_backref_index =
        controller_handle_readable ? HandleToEntityIndex(controller_handle) : -1;

    std::uint32_t owner_handle = kInvalidEntityHandle;
    const bool owner_handle_readable =
        offsets.base_owner_entity != 0 &&
        SafeReadField(observer_pawn_entity, offsets.base_owner_entity, owner_handle);

    void* scene_node = nullptr;
    const bool scene_node_readable =
        offsets.base_entity_game_scene_node != 0 &&
        SafeReadField(observer_pawn_entity, offsets.base_entity_game_scene_node, scene_node) &&
        scene_node != nullptr;
    void* scene_owner_entity = nullptr;
    const bool scene_owner_readable =
        scene_node_readable &&
        offsets.game_scene_node_owner != 0 &&
        SafeReadField(scene_node, offsets.game_scene_node_owner, scene_owner_entity) &&
        scene_owner_entity != nullptr;
    const auto scene_owner_entity_index =
        scene_owner_readable ? ResolveEntityIndexFromPointer(entity_cache, scene_owner_entity) : -1;

    void* viewmodel_services = nullptr;
    const bool viewmodel_services_present =
        offsets.pawn_viewmodel_services != 0 &&
        SafeReadField(observer_pawn_entity, offsets.pawn_viewmodel_services, viewmodel_services) &&
        viewmodel_services != nullptr;

    std::uint32_t viewmodel_handle = kInvalidEntityHandle;
    const bool viewmodel_handle_readable =
        offsets.pawn_viewmodel_handle != 0 &&
        SafeReadField(observer_pawn_entity, offsets.pawn_viewmodel_handle, viewmodel_handle);
    const bool viewmodel_handle_valid =
        viewmodel_handle_readable &&
        viewmodel_handle != 0 &&
        viewmodel_handle != kInvalidEntityHandle &&
        IsPlausibleEntityHandle(viewmodel_handle);

    const auto relay_backrefs = BuildRelayServicesBackrefSummary(entity_cache, offsets, relay_services);

    void* relay_subobject_40 = nullptr;
    const bool relay_subobject_40_present =
        relay_services_present &&
        SafeReadField(relay_services, 0x40, relay_subobject_40) &&
        relay_subobject_40 != nullptr;

    void* relay_subobject_f0 = nullptr;
    const bool relay_subobject_f0_present =
        relay_services_present &&
        SafeReadField(relay_services, 0xF0, relay_subobject_f0) &&
        relay_subobject_f0 != nullptr;

    const auto relay_pointer_window =
        relay_services_present
            ? BuildObservedPointerWindow(
                relay_services,
                0x100,
                entity_cache,
                {
                    {observer_pawn_entity, L"observer_pawn"},
                    {relay_services, L"self"},
                    {relay_subobject_40, L"relay_child_0x40"},
                    {relay_subobject_f0, L"relay_child_0xF0"},
                    {scene_node, L"observer_scene_node"},
                    {scene_owner_entity, L"scene_owner"},
                    {viewmodel_services, L"viewmodel_services"},
                    {observer_resolution.observer_controller_entity, L"observer_controller"},
                })
            : std::wstring(L"none");

    std::wstringstream stream;
    stream << L"Watched knife observer-pawn deep trace: observer_controller="
        << observer_resolution.observer_controller_entity_index
        << L", observer_pawn=" << observer_resolution.observer_pawn_entity_index
        << L", intermediate_observer_target=" << observer_pawn_entity_index
        << L", intermediate_ptr=" << FormatPointer(observer_pawn_entity)
        << L", intermediate_rtti=" << BuildRuntimeEntityRttiDescriptor(observer_pawn_entity)
        << L", relay_services=" << FormatPointer(relay_services)
        << L", relay_services_present=" << (relay_services_present ? 1 : 0)
        << L", relay_mode=";
    if (relay_mode_readable)
    {
        stream << static_cast<int>(relay_mode);
    }
    else
    {
        stream << L"?";
    }
    stream << L", relay_target=";
    if (relay_target_handle_readable)
    {
        stream << DescribeObservedRuntimeHandle(entity_list, entity_cache, relay_target_handle);
    }
    else
    {
        stream << L"?";
    }
    stream << L", relay_target_valid=" << (relay_target_handle_valid ? 1 : 0)
        << L", pawn_controller_backref=";
    if (controller_handle_readable)
    {
        stream << DescribeObservedRuntimeHandle(entity_list, entity_cache, controller_handle);
    }
    else
    {
        stream << L"?";
    }
    stream << L", pawn_controller_matches_observer="
        << ((controller_handle_readable && controller_backref_index == observer_resolution.observer_controller_entity_index) ? 1 : 0)
        << L", owner_handle=";
    if (owner_handle_readable)
    {
        stream << DescribeObservedRuntimeHandle(entity_list, entity_cache, owner_handle);
    }
    else
    {
        stream << L"?";
    }
    stream << L", scene_node=" << FormatPointer(scene_node)
        << L", scene_owner_ptr=" << FormatPointer(scene_owner_entity)
        << L", scene_owner_entity=" << scene_owner_entity_index
        << L", viewmodel_services=" << FormatPointer(viewmodel_services)
        << L", viewmodel_services_present=" << (viewmodel_services_present ? 1 : 0)
        << L", viewmodel_handle=";
    if (viewmodel_handle_readable)
    {
        stream << DescribeObservedRuntimeHandle(entity_list, entity_cache, viewmodel_handle);
    }
    else
    {
        stream << L"?";
    }
    stream << L", viewmodel_handle_valid=" << (viewmodel_handle_valid ? 1 : 0)
        << L", relay_used=" << (observer_resolution.observer_target_relay_used ? 1 : 0)
        << L", relay_final_target=" << observer_resolution.observer_target_relay_entity_index
        << L", final_target=" << observer_resolution.target_pawn_entity_index
        << L", final_target_xuid=" << observer_resolution.target_xuid
        << L", relay_child_0x40=" << FormatPointer(relay_subobject_40)
        << L", relay_child_0xF0=" << FormatPointer(relay_subobject_f0)
        << L", relay_services_region=";
    if (relay_services_present)
    {
        stream << DescribeReadableMemoryRegion(relay_services, 16);
    }
    else
    {
        stream << L"none";
    }
    stream << L", relay_services_backrefs=[" << relay_backrefs << L"]"
        << L", observer_pawn_handle_window=["
        << BuildObservedHandleWindow(observer_pawn_entity, 0x100, entity_list, entity_cache)
        << L"]";
    if (relay_services_present)
    {
        stream << L", relay_services_handle_window=["
            << BuildObservedHandleWindow(relay_services, 0x80, entity_list, entity_cache)
            << L"]"
            << L", relay_services_pointer_window=["
            << relay_pointer_window
            << L"]";
    }

    LogProfileDiagnosticOnce(signature, stream.str());

    if (relay_subobject_40_present)
    {
        LogObservedRelaySubobjectTrace(
            signature ^ 0x40ull,
            L"relay_child_0x40",
            L"relay_services",
            0x40,
            relay_services,
            relay_subobject_40,
            entity_list,
            entity_cache,
            pawn_xuids,
            offsets,
            observer_pawn_entity,
            observer_resolution.observer_controller_entity,
            relay_services,
            relay_subobject_f0,
            scene_node,
            scene_owner_entity,
            viewmodel_services);
        LogObservedRelayTertiaryTrace(
            signature ^ 0x440ull,
            L"relay_child_0x40",
            relay_subobject_40,
            entity_list,
            entity_cache,
            pawn_xuids,
            offsets,
            observer_pawn_entity,
            observer_resolution.observer_controller_entity,
            relay_services,
            scene_node,
            scene_owner_entity,
            viewmodel_services);
    }

    if (relay_subobject_f0_present)
    {
        LogObservedRelaySubobjectTrace(
            signature ^ 0xF0ull,
            L"relay_child_0xF0",
            L"relay_services",
            0xF0,
            relay_services,
            relay_subobject_f0,
            entity_list,
            entity_cache,
            pawn_xuids,
            offsets,
            observer_pawn_entity,
            observer_resolution.observer_controller_entity,
            relay_services,
            relay_subobject_40,
            scene_node,
            scene_owner_entity,
            viewmodel_services);
        LogObservedRelayTertiaryTrace(
            signature ^ 0xFF0ull,
            L"relay_child_0xF0",
            relay_subobject_f0,
            entity_list,
            entity_cache,
            pawn_xuids,
            offsets,
            observer_pawn_entity,
            observer_resolution.observer_controller_entity,
            relay_services,
            scene_node,
            scene_owner_entity,
            viewmodel_services);
    }
}

void LogBridgedPawnViewmodelDeepTrace(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const std::unordered_map<int, std::uint64_t>& pawn_xuids,
    const std::unordered_map<int, ObservedPawnRuntimeInfo>& pawn_runtime,
    const ClientSchemaOffsets& offsets,
    const HeuristicXuidBridgeResolution& bridge_resolution,
    const ObserverRealViewmodelResolution& bridge_real_viewmodel_resolution,
    const WatchedXuidResolution& watched_resolution)
{
    auto bridged_pawn_entity_index = bridge_resolution.pawn_entity_index;
    auto* bridged_pawn_entity = bridge_resolution.pawn_entity;
    if (bridged_pawn_entity_index < 0)
    {
        bridged_pawn_entity_index = watched_resolution.bridged_pawn_entity_index;
    }
    if (bridged_pawn_entity == nullptr &&
        bridged_pawn_entity_index >= 0 &&
        static_cast<std::size_t>(bridged_pawn_entity_index) < entity_cache.size())
    {
        bridged_pawn_entity = entity_cache[static_cast<std::size_t>(bridged_pawn_entity_index)];
    }
    if (bridged_pawn_entity == nullptr || bridged_pawn_entity_index < 0)
    {
        return;
    }

    const auto watched_xuid = bridge_resolution.xuid != 0 ? bridge_resolution.xuid : watched_resolution.watched_xuid;
    std::uint64_t signature = 0x4252494447454450ull;
    signature ^= watched_xuid;
    signature ^= (static_cast<std::uint64_t>(bridged_pawn_entity_index + 2) << 16);
    signature ^= (static_cast<std::uint64_t>(bridge_resolution.active_weapon_entity_index + 2) << 32);
    signature ^= (static_cast<std::uint64_t>(bridge_real_viewmodel_resolution.viewmodel_entity_index + 2) << 48);

    auto join_samples =
        [](const std::vector<std::wstring>& samples)
        {
            if (samples.empty())
            {
                return std::wstring(L"<none>");
            }

            std::wstringstream stream;
            for (std::size_t index = 0; index < samples.size(); ++index)
            {
                if (index != 0)
                {
                    stream << L" | ";
                }
                stream << samples[index];
            }
            return stream.str();
        };

    auto brief_entity =
        [&](const wchar_t* label, const int entity_index, void* entity)
        {
            std::wstringstream stream;
            stream << (label != nullptr ? label : L"entity")
                << L"{entity=" << entity_index
                << L", ptr=" << FormatPointer(entity);
            if (entity == nullptr)
            {
                stream << L"}";
                return stream.str();
            }

            auto* item_view = ResolveWeaponItemView(entity, offsets);
            int definition_index = 0;
            const auto definition_ok =
                item_view != nullptr && TryReadItemDefinitionIndex(item_view, offsets, definition_index);
            std::uint32_t owner_handle = kInvalidEntityHandle;
            const auto owner_ok =
                offsets.base_owner_entity != 0 && SafeReadField(entity, offsets.base_owner_entity, owner_handle);
            std::uint32_t viewmodel_weapon_handle = kInvalidEntityHandle;
            const auto viewmodel_weapon_ok =
                offsets.viewmodel_weapon != 0 && SafeReadField(entity, offsets.viewmodel_weapon, viewmodel_weapon_handle);
            void* scene_node = nullptr;
            void* scene_owner_entity = nullptr;
            auto scene_owner_index = -1;
            if (offsets.base_entity_game_scene_node != 0 &&
                offsets.game_scene_node_owner != 0 &&
                SafeReadField(entity, offsets.base_entity_game_scene_node, scene_node) &&
                scene_node != nullptr &&
                SafeReadField(scene_node, offsets.game_scene_node_owner, scene_owner_entity) &&
                scene_owner_entity != nullptr)
            {
                scene_owner_index = ResolveEntityIndexFromPointer(entity_cache, scene_owner_entity);
            }

            stream << L", rtti=" << BuildRuntimeEntityRttiDescriptor(entity)
                << L", definition=";
            if (definition_ok)
            {
                stream << definition_index;
            }
            else
            {
                stream << L"?";
            }
            stream << L", owner_index=" << (owner_ok ? HandleToEntityIndex(owner_handle) : -1)
                << L", scene_owner_index=" << scene_owner_index
                << L", viewmodel_weapon_index="
                << (viewmodel_weapon_ok ? HandleToEntityIndex(viewmodel_weapon_handle) : -1)
                << L"}";
            return stream.str();
        };

    auto* bridged_controller_entity = bridge_resolution.controller_entity;
    if (bridged_controller_entity == nullptr &&
        bridge_resolution.controller_entity_index >= 0 &&
        static_cast<std::size_t>(bridge_resolution.controller_entity_index) < entity_cache.size())
    {
        bridged_controller_entity = entity_cache[static_cast<std::size_t>(bridge_resolution.controller_entity_index)];
    }
    auto* active_weapon_entity = bridge_resolution.active_weapon_entity;
    if (active_weapon_entity == nullptr &&
        bridge_resolution.active_weapon_entity_index >= 0 &&
        static_cast<std::size_t>(bridge_resolution.active_weapon_entity_index) < entity_cache.size())
    {
        active_weapon_entity = entity_cache[static_cast<std::size_t>(bridge_resolution.active_weapon_entity_index)];
    }

    void* pawn_weapon_services = nullptr;
    const auto pawn_weapon_services_present =
        offsets.pawn_weapon_services != 0 &&
        SafeReadField(bridged_pawn_entity, offsets.pawn_weapon_services, pawn_weapon_services) &&
        pawn_weapon_services != nullptr;
    void* pawn_viewmodel_services = nullptr;
    const auto pawn_viewmodel_services_present =
        offsets.pawn_viewmodel_services != 0 &&
        SafeReadField(bridged_pawn_entity, offsets.pawn_viewmodel_services, pawn_viewmodel_services) &&
        pawn_viewmodel_services != nullptr;
    std::uint32_t services_active_weapon_handle = kInvalidEntityHandle;
    const auto services_active_weapon_ok =
        pawn_weapon_services_present &&
        offsets.weapon_services_active_weapon != 0 &&
        SafeReadField(pawn_weapon_services, offsets.weapon_services_active_weapon, services_active_weapon_handle);
    std::uint32_t services_viewmodel_handle = kInvalidEntityHandle;
    const auto services_viewmodel_ok =
        pawn_viewmodel_services_present &&
        offsets.viewmodel_services_viewmodel != 0 &&
        SafeReadField(pawn_viewmodel_services, offsets.viewmodel_services_viewmodel, services_viewmodel_handle);

    std::vector<std::uint32_t> owned_weapon_handles;
    if (const auto runtime_it = pawn_runtime.find(bridged_pawn_entity_index); runtime_it != pawn_runtime.end())
    {
        owned_weapon_handles = runtime_it->second.owned_weapon_handles;
    }
    else if (pawn_weapon_services_present)
    {
        owned_weapon_handles = CollectWeaponServiceWeaponHandles(pawn_weapon_services, offsets);
    }

    std::wstringstream summary_stream;
    summary_stream << L"Watched knife bridged pawn deep trace: watched_xuid=" << watched_xuid
        << L", bridge_source=" << (bridge_resolution.source != nullptr ? bridge_resolution.source : L"none")
        << L", cache_hit=" << (bridge_resolution.cache_hit ? 1 : 0)
        << L", " << brief_entity(L"pawn", bridged_pawn_entity_index, bridged_pawn_entity)
        << L" | " << brief_entity(L"controller", bridge_resolution.controller_entity_index, bridged_controller_entity)
        << L" | " << brief_entity(L"active_weapon", bridge_resolution.active_weapon_entity_index, active_weapon_entity)
        << L", pawn_weapon_services=" << FormatPointer(pawn_weapon_services)
        << L", pawn_viewmodel_services=" << FormatPointer(pawn_viewmodel_services)
        << L", services_active_weapon_index="
        << (services_active_weapon_ok ? HandleToEntityIndex(services_active_weapon_handle) : -1)
        << L", services_viewmodel_index="
        << (services_viewmodel_ok ? HandleToEntityIndex(services_viewmodel_handle) : -1)
        << L", bridge_real_viewmodel=" << bridge_real_viewmodel_resolution.viewmodel_entity_index
        << L", bridge_viewmodel_weapon=" << bridge_real_viewmodel_resolution.viewmodel_weapon_entity_index
        << L", bridge_viewmodel_weapon_matches_active="
        << (bridge_real_viewmodel_resolution.viewmodel_weapon_matches_active_weapon ? 1 : 0)
        << L", owned_weapon_handles=" << owned_weapon_handles.size()
        << L", pawn_candidate_summary=["
        << BuildObservedPawnCandidateSummary(entity_list, entity_cache, pawn_xuids, bridged_pawn_entity, 0x180)
        << L"], pawn_handle_window=["
        << BuildObservedHandleWindow(bridged_pawn_entity, 0x180, entity_list, entity_cache)
        << L"], pawn_pointer_window=["
        << BuildObservedPointerWindow(
               bridged_pawn_entity,
               0x180,
               entity_cache,
               {
                   {bridged_pawn_entity, L"bridged_pawn"},
                   {bridged_controller_entity, L"bridged_controller"},
                   {pawn_weapon_services, L"pawn_weapon_services"},
                   {pawn_viewmodel_services, L"pawn_viewmodel_services"},
                   {active_weapon_entity, L"bridge_active_weapon"},
                   {bridge_real_viewmodel_resolution.viewmodel_entity, L"bridge_real_viewmodel"},
               })
        << L"], pawn_readable_pointer_candidates=["
        << BuildObservedReadablePointerCandidateSummary(
               CollectObservedReadablePointerCandidates(
                   bridged_pawn_entity,
                   0x180,
                   entity_cache,
                   {
                       bridged_pawn_entity,
                       bridged_controller_entity,
                       pawn_weapon_services,
                       pawn_viewmodel_services,
                       active_weapon_entity,
                       bridge_real_viewmodel_resolution.viewmodel_entity,
                   }))
        << L"], weapon_services_backrefs=["
        << BuildObservedPointerBackrefSummary(entity_cache, offsets, pawn_weapon_services)
        << L"], viewmodel_services_backrefs=["
        << BuildObservedPointerBackrefSummary(entity_cache, offsets, pawn_viewmodel_services)
        << L"]";
    LogProfileDiagnosticOnce(signature, summary_stream.str());

    void* pawn_scene_node = nullptr;
    if (offsets.base_entity_game_scene_node != 0 &&
        offsets.game_scene_node_child != 0 &&
        offsets.game_scene_node_next_sibling != 0 &&
        offsets.game_scene_node_owner != 0 &&
        SafeReadField(bridged_pawn_entity, offsets.base_entity_game_scene_node, pawn_scene_node) &&
        pawn_scene_node != nullptr)
    {
        struct PendingSceneNode
        {
            void* scene_node = nullptr;
            int depth = 0;
        };

        int child_count = 0;
        int ownerless_count = 0;
        int active_weapon_match_count = 0;
        int real_viewmodel_match_count = 0;
        std::vector<std::wstring> child_samples;
        std::vector<PendingSceneNode> pending_scene_nodes;
        std::unordered_set<void*> visited_scene_nodes;

        void* first_child_scene_node = nullptr;
        if (SafeReadField(pawn_scene_node, offsets.game_scene_node_child, first_child_scene_node) &&
            first_child_scene_node != nullptr)
        {
            pending_scene_nodes.push_back({first_child_scene_node, 1});
        }

        while (!pending_scene_nodes.empty())
        {
            const auto pending = pending_scene_nodes.back();
            pending_scene_nodes.pop_back();
            auto* child_scene_node = pending.scene_node;
            if (child_scene_node == nullptr || !visited_scene_nodes.insert(child_scene_node).second)
            {
                continue;
            }

            void* nested_child_scene_node = nullptr;
            if (SafeReadField(child_scene_node, offsets.game_scene_node_child, nested_child_scene_node) &&
                nested_child_scene_node != nullptr)
            {
                pending_scene_nodes.push_back({nested_child_scene_node, pending.depth + 1});
            }

            void* next_sibling_scene_node = nullptr;
            if (SafeReadField(child_scene_node, offsets.game_scene_node_next_sibling, next_sibling_scene_node) &&
                next_sibling_scene_node != nullptr)
            {
                pending_scene_nodes.push_back({next_sibling_scene_node, pending.depth});
            }

            ++child_count;

            void* child_owner_entity = nullptr;
            if (!SafeReadField(child_scene_node, offsets.game_scene_node_owner, child_owner_entity) ||
                child_owner_entity == nullptr)
            {
                ++ownerless_count;
                continue;
            }

            const auto child_owner_index = ResolveEntityIndexFromPointer(entity_cache, child_owner_entity);
            if (child_owner_index == bridge_resolution.active_weapon_entity_index)
            {
                ++active_weapon_match_count;
            }
            if (child_owner_index == bridge_real_viewmodel_resolution.viewmodel_entity_index)
            {
                ++real_viewmodel_match_count;
            }
            if (child_samples.size() < 10)
            {
                std::wstringstream sample_stream;
                sample_stream << L"child{depth=" << pending.depth
                    << L", owner=" << brief_entity(L"owner", child_owner_index, child_owner_entity)
                    << L", active_match=" << (child_owner_index == bridge_resolution.active_weapon_entity_index ? 1 : 0)
                    << L", real_viewmodel_match="
                    << (child_owner_index == bridge_real_viewmodel_resolution.viewmodel_entity_index ? 1 : 0)
                    << L"}";
                child_samples.push_back(sample_stream.str());
            }
        }

        std::wstringstream scene_stream;
        scene_stream << L"Watched knife bridged pawn scene trace: watched_xuid=" << watched_xuid
            << L", pawn=" << bridged_pawn_entity_index
            << L", child_count=" << child_count
            << L", ownerless=" << ownerless_count
            << L", active_weapon_matches=" << active_weapon_match_count
            << L", real_viewmodel_matches=" << real_viewmodel_match_count
            << L", samples=" << join_samples(child_samples);
        LogProfileDiagnosticOnce(signature ^ 0x10ull, scene_stream.str());
    }

    int total_viewmodels = 0;
    int owner_match_count = 0;
    int scene_owner_match_count = 0;
    int weapon_match_count = 0;
    std::vector<std::wstring> viewmodel_samples;
    for (std::size_t entity_index = 0; entity_index < entity_cache.size(); ++entity_index)
    {
        auto* entity = entity_cache[entity_index];
        if (entity == nullptr)
        {
            continue;
        }

        const auto rtti = BuildRuntimeEntityRttiDescriptor(entity);
        if (rtti.find(L"ViewModel") == std::wstring::npos &&
            rtti.find(L"viewmodel") == std::wstring::npos)
        {
            continue;
        }

        ++total_viewmodels;

        std::uint32_t owner_handle = kInvalidEntityHandle;
        const auto owner_ok =
            offsets.base_owner_entity != 0 && SafeReadField(entity, offsets.base_owner_entity, owner_handle);
        const auto owner_index = owner_ok ? HandleToEntityIndex(owner_handle) : -1;
        if (owner_index == bridged_pawn_entity_index)
        {
            ++owner_match_count;
        }

        std::uint32_t viewmodel_weapon_handle = kInvalidEntityHandle;
        const auto viewmodel_weapon_ok =
            offsets.viewmodel_weapon != 0 && SafeReadField(entity, offsets.viewmodel_weapon, viewmodel_weapon_handle);
        const auto viewmodel_weapon_index = viewmodel_weapon_ok ? HandleToEntityIndex(viewmodel_weapon_handle) : -1;
        if (viewmodel_weapon_index == bridge_resolution.active_weapon_entity_index)
        {
            ++weapon_match_count;
        }

        void* scene_node = nullptr;
        void* scene_owner_entity = nullptr;
        auto scene_owner_index = -1;
        if (offsets.base_entity_game_scene_node != 0 &&
            offsets.game_scene_node_owner != 0 &&
            SafeReadField(entity, offsets.base_entity_game_scene_node, scene_node) &&
            scene_node != nullptr &&
            SafeReadField(scene_node, offsets.game_scene_node_owner, scene_owner_entity) &&
            scene_owner_entity != nullptr)
        {
            scene_owner_index = ResolveEntityIndexFromPointer(entity_cache, scene_owner_entity);
        }
        if (scene_owner_index == bridged_pawn_entity_index)
        {
            ++scene_owner_match_count;
        }

        if ((owner_index == bridged_pawn_entity_index ||
             scene_owner_index == bridged_pawn_entity_index ||
             viewmodel_weapon_index == bridge_resolution.active_weapon_entity_index) &&
            viewmodel_samples.size() < 10)
        {
            viewmodel_samples.push_back(
                brief_entity(L"viewmodel", static_cast<int>(entity_index), entity));
        }
    }

    std::wstringstream viewmodel_stream;
    viewmodel_stream << L"Watched knife global viewmodel lookup: watched_xuid=" << watched_xuid
        << L", bridged_pawn=" << bridged_pawn_entity_index
        << L", active_weapon=" << bridge_resolution.active_weapon_entity_index
        << L", total_viewmodels=" << total_viewmodels
        << L", owner_matches_pawn=" << owner_match_count
        << L", scene_owner_matches_pawn=" << scene_owner_match_count
        << L", weapon_matches_active=" << weapon_match_count
        << L", samples=" << join_samples(viewmodel_samples);
    LogProfileDiagnosticOnce(signature ^ 0x20ull, viewmodel_stream.str());

    if (active_weapon_entity != nullptr && bridge_resolution.active_weapon_entity_index >= 0)
    {
        int owner_ref_count = 0;
        int old_move_parent_ref_count = 0;
        int viewmodel_attachment_ref_count = 0;
        int providee_ref_count = 0;
        int viewmodel_weapon_ref_count = 0;
        std::vector<std::wstring> reverse_samples;

        for (std::size_t entity_index = 0; entity_index < entity_cache.size(); ++entity_index)
        {
            auto* entity = entity_cache[entity_index];
            if (entity == nullptr)
            {
                continue;
            }

            auto append_sample =
                [&](const wchar_t* relation)
                {
                    if (reverse_samples.size() >= 10)
                    {
                        return;
                    }
                    std::wstringstream sample_stream;
                    sample_stream << (relation != nullptr ? relation : L"ref")
                        << L"=" << brief_entity(L"entity", static_cast<int>(entity_index), entity);
                    reverse_samples.push_back(sample_stream.str());
                };

            std::uint32_t handle = kInvalidEntityHandle;
            if (offsets.base_owner_entity != 0 &&
                SafeReadField(entity, offsets.base_owner_entity, handle) &&
                HandleToEntityIndex(handle) == bridge_resolution.active_weapon_entity_index)
            {
                ++owner_ref_count;
                append_sample(L"owner");
            }
            if (offsets.base_old_move_parent != 0 &&
                SafeReadField(entity, offsets.base_old_move_parent, handle) &&
                HandleToEntityIndex(handle) == bridge_resolution.active_weapon_entity_index)
            {
                ++old_move_parent_ref_count;
                append_sample(L"old_move_parent");
            }
            if (offsets.econ_entity_viewmodel_attachment != 0 &&
                SafeReadField(entity, offsets.econ_entity_viewmodel_attachment, handle) &&
                HandleToEntityIndex(handle) == bridge_resolution.active_weapon_entity_index)
            {
                ++viewmodel_attachment_ref_count;
                append_sample(L"viewmodel_attachment");
            }
            if (offsets.econ_entity_old_providee != 0 &&
                SafeReadField(entity, offsets.econ_entity_old_providee, handle) &&
                HandleToEntityIndex(handle) == bridge_resolution.active_weapon_entity_index)
            {
                ++providee_ref_count;
                append_sample(L"providee");
            }
            if (offsets.viewmodel_weapon != 0 &&
                SafeReadField(entity, offsets.viewmodel_weapon, handle) &&
                HandleToEntityIndex(handle) == bridge_resolution.active_weapon_entity_index)
            {
                ++viewmodel_weapon_ref_count;
                append_sample(L"viewmodel_weapon");
            }
        }

        std::wstringstream reverse_stream;
        reverse_stream << L"Watched knife active-weapon reverse trace: watched_xuid=" << watched_xuid
            << L", " << brief_entity(L"active_weapon", bridge_resolution.active_weapon_entity_index, active_weapon_entity)
            << L", owner_refs=" << owner_ref_count
            << L", old_move_parent_refs=" << old_move_parent_ref_count
            << L", viewmodel_attachment_refs=" << viewmodel_attachment_ref_count
            << L", providee_refs=" << providee_ref_count
            << L", viewmodel_weapon_refs=" << viewmodel_weapon_ref_count
            << L", samples=" << join_samples(reverse_samples);
        LogProfileDiagnosticOnce(signature ^ 0x30ull, reverse_stream.str());
    }
}

void LogWatchedKnifeOwnerAttachmentProbe(
    const std::uint64_t xuid,
    void* entity_list,
    const std::vector<void*>& entity_cache,
    void* world_weapon_entity,
    const ClientSchemaOffsets& offsets,
    const int world_weapon_entity_index,
    const int fallback_definition_index,
    const KnifeEffectiveOwnerBindingState& state)
{
    if (!ShouldLogWatchedKnifeAnimationTrace(xuid) || world_weapon_entity == nullptr)
    {
        return;
    }

    auto describe_candidate =
        [&](const wchar_t* label, const bool field_present, const std::uint32_t raw_handle, const bool effective_valid)
        {
            std::wstringstream stream;
            const auto entity_index = HandleToEntityIndex(raw_handle);
            void* entity = nullptr;
            if (IsResolvedRuntimeEntityIndex(entity_index))
            {
                if (entity_index >= 0 && static_cast<std::size_t>(entity_index) < entity_cache.size())
                {
                    entity = entity_cache[static_cast<std::size_t>(entity_index)];
                }

                if (entity == nullptr)
                {
                    TryGetEntityFromIndex(entity_list, entity_index, entity);
                }
            }

            void* item_view = entity != nullptr ? ResolveWeaponItemView(entity, offsets) : nullptr;
            int definition_index = 0;
            if (item_view != nullptr)
            {
                TryReadItemDefinitionIndex(item_view, offsets, definition_index);
            }

            const auto model_kind =
                entity != nullptr
                    ? ClassifyKnifeFirstPersonRenderableModel(entity, offsets)
                    : KnifeFirstPersonRenderableModelKind::Unknown;
            const auto* model_kind_text =
                model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike
                    ? L"weapon"
                    : (model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike ? L"character" : L"unknown");

            int safe_entity_index = -1;
            void* safe_entity = nullptr;
            int safe_definition_index = 0;
            const auto safe_owner =
                TryResolveKnifeEffectiveOwnerCarrier(
                    entity_list,
                    entity_cache,
                    offsets,
                    world_weapon_entity_index,
                    entity_index,
                    fallback_definition_index,
                    safe_entity_index,
                    safe_entity,
                    safe_definition_index);

            stream << (label != nullptr ? label : L"candidate")
                << L"{field=" << (field_present ? 1 : 0)
                << L", raw_handle=0x" << std::hex << std::uppercase << raw_handle
                << std::dec << std::nouppercase
                << L", entity=" << entity_index
                << L", entity_ptr=" << FormatPointer(entity)
                << L", item_view=" << FormatPointer(item_view)
                << L", definition=" << definition_index
                << L", model_kind=" << model_kind_text
                << L", synthetic=" << (IsSyntheticRuntimeEntityIndex(entity_index) ? 1 : 0)
                << L", effective_valid=" << (effective_valid ? 1 : 0)
                << L", safe_owner=" << (safe_owner ? 1 : 0);
            if (safe_owner)
            {
                stream << L", safe_entity=" << safe_entity_index
                    << L", safe_definition=" << safe_definition_index;
            }
            stream << L"}";
            return stream.str();
        };

    std::uint32_t viewmodel_handle = kInvalidEntityHandle;
    const auto viewmodel_field_present = offsets.econ_entity_viewmodel_attachment != 0;
    if (viewmodel_field_present)
    {
        SafeReadField(world_weapon_entity, offsets.econ_entity_viewmodel_attachment, viewmodel_handle);
    }

    std::uint32_t providee_handle = kInvalidEntityHandle;
    const auto providee_field_present = offsets.econ_entity_old_providee != 0;
    if (providee_field_present)
    {
        SafeReadField(world_weapon_entity, offsets.econ_entity_old_providee, providee_handle);
    }

    std::wstringstream stream;
    stream << L"Knife owner attachment probe for XUID " << xuid
        << L": world_entity=" << world_weapon_entity_index
        << L", fallback_definition=" << fallback_definition_index
        << L", "
        << describe_candidate(L"viewmodel", viewmodel_field_present, viewmodel_handle, state.viewmodel_valid)
        << L" | "
        << describe_candidate(L"providee", providee_field_present, providee_handle, state.providee_valid);
    nskinzcs2::Logger::Info(stream.str());
}

void LogWatchedKnifeWorldNeighborhoodProbe(
    const std::uint64_t xuid,
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    void* world_weapon_entity,
    void* world_item_view,
    const ClientSchemaOffsets& offsets,
    const int world_weapon_entity_index,
    const int fallback_definition_index)
{
    if (!ShouldLogWatchedKnifeAnimationTrace(xuid) ||
        world_weapon_entity == nullptr ||
        world_weapon_entity_index < 0)
    {
        return;
    }

    const auto owned_weapon_handle_it =
        player_binding.owned_weapon_handles_by_entity_index.find(world_weapon_entity_index);
    const auto owned_weapon_handle =
        owned_weapon_handle_it != player_binding.owned_weapon_handles_by_entity_index.end()
            ? owned_weapon_handle_it->second
            : kInvalidEntityHandle;

    std::uintptr_t world_model_state = 0;
    const auto world_model_state_valid =
        TryResolveEntityModelStateAddress(world_weapon_entity, offsets, world_model_state) &&
        world_model_state != 0;

    std::uint64_t world_mesh_mask = 0;
    const auto world_mesh_mask_valid =
        TryReadWeaponMeshGroupMask(world_weapon_entity, offsets, world_mesh_mask);

    std::uint32_t world_viewmodel_handle = kInvalidEntityHandle;
    const auto world_viewmodel_field_present = offsets.econ_entity_viewmodel_attachment != 0;
    if (world_viewmodel_field_present)
    {
        SafeReadField(world_weapon_entity, offsets.econ_entity_viewmodel_attachment, world_viewmodel_handle);
    }

    std::uint32_t world_providee_handle = kInvalidEntityHandle;
    const auto world_providee_field_present = offsets.econ_entity_old_providee != 0;
    if (world_providee_field_present)
    {
        SafeReadField(world_weapon_entity, offsets.econ_entity_old_providee, world_providee_handle);
    }

    std::uint32_t world_owner_handle = kInvalidEntityHandle;
    const auto world_owner_field_present = offsets.base_owner_entity != 0;
    if (world_owner_field_present)
    {
        SafeReadField(world_weapon_entity, offsets.base_owner_entity, world_owner_handle);
    }

    std::uint32_t world_old_move_parent_handle = kInvalidEntityHandle;
    const auto world_old_move_parent_field_present = offsets.base_old_move_parent != 0;
    if (world_old_move_parent_field_present)
    {
        SafeReadField(world_weapon_entity, offsets.base_old_move_parent, world_old_move_parent_handle);
    }

    void* world_scene_node = nullptr;
    const auto world_scene_node_valid =
        offsets.base_entity_game_scene_node != 0 &&
        SafeReadField(world_weapon_entity, offsets.base_entity_game_scene_node, world_scene_node) &&
        world_scene_node != nullptr;

    void* world_scene_owner_entity = nullptr;
    int world_scene_owner_entity_index = -1;
    if (world_scene_node_valid && offsets.game_scene_node_owner != 0)
    {
        if (SafeReadField(world_scene_node, offsets.game_scene_node_owner, world_scene_owner_entity) &&
            world_scene_owner_entity != nullptr)
        {
            world_scene_owner_entity_index =
                ResolveEntityIndexFromPointer(entity_cache, world_scene_owner_entity);
            if (world_scene_owner_entity_index < 0)
            {
                world_scene_owner_entity_index =
                    BuildSyntheticEntityIndex(world_scene_owner_entity, 0x57505242u);
            }
        }
    }

    RenderedWorldWeaponTrace trace {};
    const auto trace_built =
        owned_weapon_handle != kInvalidEntityHandle &&
        TryBuildRenderedWorldWeaponTrace(
            entity_list,
            entity_cache,
            player_binding,
            xuid,
            owned_weapon_handle,
            world_weapon_entity_index,
            world_weapon_entity,
            offsets,
            trace);

    auto describe_entity =
        [&](const wchar_t* label,
            const int entity_index_hint,
            void* entity,
            const std::uint32_t relation_handle,
            const wchar_t* relation_kind,
            const int scene_depth)
        {
            std::wstringstream stream;
            stream << (label != nullptr ? label : L"candidate")
                << L"{relation=" << (relation_kind != nullptr ? relation_kind : L"none")
                << L", via_handle=0x" << std::hex << std::uppercase << relation_handle
                << std::dec << std::nouppercase
                << L", scene_depth=" << scene_depth;

            if (entity == nullptr)
            {
                stream << L", entity=-1, entity_ptr=0x0}";
                return stream.str();
            }

            auto entity_index = entity_index_hint;
            if (entity_index < 0)
            {
                entity_index = ResolveEntityIndexFromPointer(entity_cache, entity);
                if (entity_index < 0)
                {
                    entity_index = BuildSyntheticEntityIndex(entity, 0x57505243u);
                }
            }

            auto* item_view = ResolveWeaponItemView(entity, offsets);
            int definition_index = 0;
            if (item_view != nullptr)
            {
                TryReadItemDefinitionIndex(item_view, offsets, definition_index);
            }

            std::uintptr_t model_state = 0;
            const auto model_state_valid =
                TryResolveEntityModelStateAddress(entity, offsets, model_state) &&
                model_state != 0;
            std::uint64_t mesh_mask = 0;
            const auto mesh_mask_valid = TryReadWeaponMeshGroupMask(entity, offsets, mesh_mask);
            const auto model_kind = ClassifyKnifeFirstPersonRenderableModel(entity, offsets);
            const auto* model_kind_text =
                model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike
                    ? L"weapon"
                    : (model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike
                           ? L"character"
                           : L"unknown");

            std::uint32_t owner_handle = kInvalidEntityHandle;
            const auto owner_handle_valid =
                offsets.base_owner_entity != 0 &&
                SafeReadField(entity, offsets.base_owner_entity, owner_handle);
            const auto owner_index =
                owner_handle_valid ? HandleToEntityIndex(owner_handle) : -1;

            std::uint32_t old_move_parent_handle = kInvalidEntityHandle;
            const auto old_move_parent_handle_valid =
                offsets.base_old_move_parent != 0 &&
                SafeReadField(entity, offsets.base_old_move_parent, old_move_parent_handle);
            const auto old_move_parent_index =
                old_move_parent_handle_valid ? HandleToEntityIndex(old_move_parent_handle) : -1;

            std::uint32_t viewmodel_handle = kInvalidEntityHandle;
            const auto viewmodel_handle_valid =
                offsets.econ_entity_viewmodel_attachment != 0 &&
                SafeReadField(entity, offsets.econ_entity_viewmodel_attachment, viewmodel_handle);
            const auto viewmodel_index =
                viewmodel_handle_valid ? HandleToEntityIndex(viewmodel_handle) : -1;

            std::uint32_t providee_handle = kInvalidEntityHandle;
            const auto providee_handle_valid =
                offsets.econ_entity_old_providee != 0 &&
                SafeReadField(entity, offsets.econ_entity_old_providee, providee_handle);
            const auto providee_index =
                providee_handle_valid ? HandleToEntityIndex(providee_handle) : -1;

            void* scene_node = nullptr;
            const auto scene_node_resolved =
                offsets.base_entity_game_scene_node != 0 &&
                SafeReadField(entity, offsets.base_entity_game_scene_node, scene_node) &&
                scene_node != nullptr;
            void* scene_owner_entity = nullptr;
            int scene_owner_index = -1;
            if (scene_node_resolved && offsets.game_scene_node_owner != 0)
            {
                if (SafeReadField(scene_node, offsets.game_scene_node_owner, scene_owner_entity) &&
                    scene_owner_entity != nullptr)
                {
                    scene_owner_index = ResolveEntityIndexFromPointer(entity_cache, scene_owner_entity);
                    if (scene_owner_index < 0)
                    {
                        scene_owner_index = BuildSyntheticEntityIndex(scene_owner_entity, 0x57505244u);
                    }
                }
            }

            int safe_entity_index = -1;
            void* safe_entity = nullptr;
            int safe_definition_index = 0;
            const auto safe_owner =
                TryResolveKnifeEffectiveOwnerCarrier(
                    entity_list,
                    entity_cache,
                    offsets,
                    world_weapon_entity_index,
                    entity_index,
                    fallback_definition_index,
                    safe_entity_index,
                    safe_entity,
                    safe_definition_index);

            std::string model_name;
            TryReadEntityModelNameString(entity, offsets, model_name);

            stream << L", entity=" << entity_index
                << L", entity_ptr=" << FormatPointer(entity)
                << L", synthetic=" << (IsSyntheticRuntimeEntityIndex(entity_index) ? 1 : 0)
                << L", item_view=" << FormatPointer(item_view)
                << L", shared_world_item_view=" << (item_view != nullptr && item_view == world_item_view ? 1 : 0)
                << L", definition=" << definition_index
                << L", model_kind=" << model_kind_text
                << L", model_state="
                << (model_state_valid ? FormatPointer(reinterpret_cast<void*>(model_state)) : L"0x0")
                << L", shared_world_model_state="
                << (model_state_valid && world_model_state_valid && model_state == world_model_state ? 1 : 0)
                << L", mesh_mask=";
            if (mesh_mask_valid)
            {
                stream << mesh_mask;
            }
            else
            {
                stream << L"?";
            }

            stream << L", owner_handle=";
            if (owner_handle_valid)
            {
                stream << L"0x" << std::hex << std::uppercase << owner_handle << std::dec << std::nouppercase;
            }
            else
            {
                stream << L"?";
            }
            stream << L", owner_index=" << owner_index
                << L", old_move_parent_handle=";
            if (old_move_parent_handle_valid)
            {
                stream << L"0x" << std::hex << std::uppercase << old_move_parent_handle
                    << std::dec << std::nouppercase;
            }
            else
            {
                stream << L"?";
            }
            stream << L", old_move_parent_index=" << old_move_parent_index
                << L", viewmodel_handle=";
            if (viewmodel_handle_valid)
            {
                stream << L"0x" << std::hex << std::uppercase << viewmodel_handle
                    << std::dec << std::nouppercase;
            }
            else
            {
                stream << L"?";
            }
            stream << L", viewmodel_index=" << viewmodel_index
                << L", providee_handle=";
            if (providee_handle_valid)
            {
                stream << L"0x" << std::hex << std::uppercase << providee_handle
                    << std::dec << std::nouppercase;
            }
            else
            {
                stream << L"?";
            }
            stream << L", providee_index=" << providee_index
                << L", scene_node=" << FormatPointer(scene_node)
                << L", scene_owner=" << scene_owner_index
                << L", scene_owner_ptr=" << FormatPointer(scene_owner_entity)
                << L", safe_owner=" << (safe_owner ? 1 : 0);
            if (safe_owner)
            {
                stream << L", safe_entity=" << safe_entity_index
                    << L", safe_definition=" << safe_definition_index
                    << L", safe_entity_ptr=" << FormatPointer(safe_entity);
            }
            if (!model_name.empty())
            {
                stream << L", model_name=" << NarrowToWide(model_name);
            }
            stream << L"}";
            return stream.str();
        };

    std::vector<std::wstring> attachment_samples;
    attachment_samples.reserve(8);
    attachment_samples.push_back(
        describe_entity(
            L"world",
            world_weapon_entity_index,
            world_weapon_entity,
            owned_weapon_handle,
            L"self",
            0));

    auto add_handle_attachment =
        [&](const wchar_t* label, const wchar_t* relation_kind, const std::uint32_t raw_handle)
        {
            if (raw_handle == kInvalidEntityHandle)
            {
                std::wstringstream stream;
                stream << (label != nullptr ? label : L"handle")
                    << L"{relation=" << (relation_kind != nullptr ? relation_kind : L"handle")
                    << L", via_handle=0xFFFFFFFF, entity=-1, entity_ptr=0x0}";
                attachment_samples.push_back(stream.str());
                return;
            }

            const auto entity_index = HandleToEntityIndex(raw_handle);
            void* entity = nullptr;
            if (entity_index >= 0 && static_cast<std::size_t>(entity_index) < entity_cache.size())
            {
                entity = entity_cache[static_cast<std::size_t>(entity_index)];
            }
            if (entity == nullptr && entity_index >= 0)
            {
                TryGetEntityFromIndex(entity_list, entity_index, entity);
            }

            attachment_samples.push_back(
                describe_entity(label, entity_index, entity, raw_handle, relation_kind, 0));
        };

    add_handle_attachment(L"viewmodel_attachment", L"world_viewmodel_attachment", world_viewmodel_handle);
    add_handle_attachment(L"old_providee", L"world_old_providee", world_providee_handle);
    add_handle_attachment(L"owner_entity", L"world_owner_entity", world_owner_handle);
    add_handle_attachment(L"old_move_parent", L"world_old_move_parent", world_old_move_parent_handle);
    if (trace_built)
    {
        if (trace.scene_owner_entity != nullptr)
        {
            attachment_samples.push_back(
                describe_entity(
                    L"scene_owner",
                    trace.scene_owner_entity_index,
                    trace.scene_owner_entity,
                    kInvalidEntityHandle,
                    L"trace_scene_owner",
                    0));
        }
        if (trace.explicit_owner_child_entity != nullptr)
        {
            attachment_samples.push_back(
                describe_entity(
                    L"explicit_owner_child",
                    trace.explicit_owner_child_entity_index,
                    trace.explicit_owner_child_entity,
                    kInvalidEntityHandle,
                    L"trace_explicit_owner_child",
                    1));
        }
        if (trace.hud_weapon_entity != nullptr)
        {
            attachment_samples.push_back(
                describe_entity(
                    L"hud_weapon",
                    trace.hud_weapon_entity_index,
                    trace.hud_weapon_entity,
                    kInvalidEntityHandle,
                    L"trace_hud_weapon",
                    1));
        }
    }

    std::vector<std::wstring> reverse_ref_samples;
    reverse_ref_samples.reserve(16);
    int reverse_owner_ref_count = 0;
    int reverse_old_move_parent_ref_count = 0;
    int reverse_viewmodel_ref_count = 0;
    int reverse_providee_ref_count = 0;

    const auto highest_live_entity_index =
        std::max(g_hook_state.highest_live_entity_index.load(), static_cast<int>(entity_cache.size()) - 1);
    for (int entity_index = 0; entity_index <= highest_live_entity_index; ++entity_index)
    {
        void* entity = nullptr;
        if (entity_index >= 0 && static_cast<std::size_t>(entity_index) < entity_cache.size())
        {
            entity = entity_cache[static_cast<std::size_t>(entity_index)];
        }
        if (entity == nullptr &&
            (!TryGetEntityFromIndex(entity_list, entity_index, entity) || entity == nullptr))
        {
            continue;
        }
        if (entity == world_weapon_entity)
        {
            continue;
        }

        std::uint32_t candidate_owner_handle = kInvalidEntityHandle;
        if (offsets.base_owner_entity != 0 &&
            SafeReadField(entity, offsets.base_owner_entity, candidate_owner_handle) &&
            HandleToEntityIndex(candidate_owner_handle) == world_weapon_entity_index)
        {
            ++reverse_owner_ref_count;
            reverse_ref_samples.push_back(
                describe_entity(
                    L"reverse_owner_ref",
                    entity_index,
                    entity,
                    candidate_owner_handle,
                    L"reverse_owner_entity",
                    0));
        }

        std::uint32_t candidate_old_move_parent_handle = kInvalidEntityHandle;
        if (offsets.base_old_move_parent != 0 &&
            SafeReadField(entity, offsets.base_old_move_parent, candidate_old_move_parent_handle) &&
            HandleToEntityIndex(candidate_old_move_parent_handle) == world_weapon_entity_index)
        {
            ++reverse_old_move_parent_ref_count;
            reverse_ref_samples.push_back(
                describe_entity(
                    L"reverse_old_move_parent_ref",
                    entity_index,
                    entity,
                    candidate_old_move_parent_handle,
                    L"reverse_old_move_parent",
                    0));
        }

        std::uint32_t candidate_viewmodel_handle = kInvalidEntityHandle;
        if (offsets.econ_entity_viewmodel_attachment != 0 &&
            SafeReadField(entity, offsets.econ_entity_viewmodel_attachment, candidate_viewmodel_handle) &&
            HandleToEntityIndex(candidate_viewmodel_handle) == world_weapon_entity_index)
        {
            ++reverse_viewmodel_ref_count;
            reverse_ref_samples.push_back(
                describe_entity(
                    L"reverse_viewmodel_ref",
                    entity_index,
                    entity,
                    candidate_viewmodel_handle,
                    L"reverse_viewmodel_attachment",
                    0));
        }

        std::uint32_t candidate_providee_handle = kInvalidEntityHandle;
        if (offsets.econ_entity_old_providee != 0 &&
            SafeReadField(entity, offsets.econ_entity_old_providee, candidate_providee_handle) &&
            HandleToEntityIndex(candidate_providee_handle) == world_weapon_entity_index)
        {
            ++reverse_providee_ref_count;
            reverse_ref_samples.push_back(
                describe_entity(
                    L"reverse_providee_ref",
                    entity_index,
                    entity,
                    candidate_providee_handle,
                    L"reverse_old_providee",
                    0));
        }
    }

    std::vector<std::wstring> scene_child_samples;
    scene_child_samples.reserve(16);
    int scene_child_count = 0;
    int scene_child_ownerless_count = 0;
    int scene_child_weapon_like_count = 0;
    int scene_child_character_like_count = 0;
    int scene_child_synthetic_count = 0;
    if (world_scene_node_valid &&
        offsets.game_scene_node_child != 0 &&
        offsets.game_scene_node_next_sibling != 0 &&
        offsets.game_scene_node_owner != 0)
    {
        struct PendingSceneNode
        {
            void* scene_node = nullptr;
            int depth = 0;
        };

        void* first_child_scene_node = nullptr;
        if (SafeReadField(world_scene_node, offsets.game_scene_node_child, first_child_scene_node) &&
            first_child_scene_node != nullptr)
        {
            std::vector<PendingSceneNode> pending_scene_nodes;
            pending_scene_nodes.reserve(16);
            pending_scene_nodes.push_back({first_child_scene_node, 1});

            std::unordered_set<void*> visited_scene_nodes;
            while (!pending_scene_nodes.empty())
            {
                const auto pending = pending_scene_nodes.back();
                pending_scene_nodes.pop_back();
                auto* child_scene_node = pending.scene_node;
                if (child_scene_node == nullptr ||
                    !visited_scene_nodes.insert(child_scene_node).second)
                {
                    continue;
                }

                void* nested_child_scene_node = nullptr;
                if (SafeReadField(child_scene_node, offsets.game_scene_node_child, nested_child_scene_node) &&
                    nested_child_scene_node != nullptr)
                {
                    pending_scene_nodes.push_back({nested_child_scene_node, pending.depth + 1});
                }

                void* next_sibling_scene_node = nullptr;
                if (SafeReadField(child_scene_node, offsets.game_scene_node_next_sibling, next_sibling_scene_node) &&
                    next_sibling_scene_node != nullptr)
                {
                    pending_scene_nodes.push_back({next_sibling_scene_node, pending.depth});
                }

                ++scene_child_count;

                void* owner_entity = nullptr;
                if (!SafeReadField(child_scene_node, offsets.game_scene_node_owner, owner_entity) ||
                    owner_entity == nullptr)
                {
                    ++scene_child_ownerless_count;
                    std::wstringstream stream;
                    stream << L"scene_child_ownerless{scene_depth=" << pending.depth
                        << L", scene_node=" << FormatPointer(child_scene_node)
                        << L", owner_entity=0x0}";
                    scene_child_samples.push_back(stream.str());
                    continue;
                }

                auto owner_entity_index = ResolveEntityIndexFromPointer(entity_cache, owner_entity);
                if (owner_entity_index < 0)
                {
                    owner_entity_index = BuildSyntheticEntityIndex(owner_entity, 0x57505343u);
                }

                const auto model_kind = ClassifyKnifeFirstPersonRenderableModel(owner_entity, offsets);
                if (model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
                {
                    ++scene_child_weapon_like_count;
                }
                else if (model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike)
                {
                    ++scene_child_character_like_count;
                }
                if (IsSyntheticRuntimeEntityIndex(owner_entity_index))
                {
                    ++scene_child_synthetic_count;
                }

                scene_child_samples.push_back(
                    describe_entity(
                        L"scene_child_owner",
                        owner_entity_index,
                        owner_entity,
                        kInvalidEntityHandle,
                        L"world_scene_child_owner",
                        pending.depth));
            }
        }
    }

    auto join_samples =
        [](const std::vector<std::wstring>& samples)
        {
            if (samples.empty())
            {
                return std::wstring(L"<none>");
            }

            std::wstringstream stream;
            for (std::size_t index = 0; index < samples.size(); ++index)
            {
                if (index != 0)
                {
                    stream << L" | ";
                }
                stream << samples[index];
            }
            return stream.str();
        };

    std::wstringstream summary_stream;
    summary_stream << L"Knife world neighborhood probe for XUID " << xuid
        << L": world_entity=" << world_weapon_entity_index
        << L", owned_weapon_handle=";
    if (owned_weapon_handle != kInvalidEntityHandle)
    {
        summary_stream << L"0x" << std::hex << std::uppercase << owned_weapon_handle
            << std::dec << std::nouppercase;
    }
    else
    {
        summary_stream << L"0xFFFFFFFF";
    }
    summary_stream << L", world_ptr=" << FormatPointer(world_weapon_entity)
        << L", world_item_view=" << FormatPointer(world_item_view)
        << L", world_model_state="
        << (world_model_state_valid ? FormatPointer(reinterpret_cast<void*>(world_model_state)) : L"0x0")
        << L", world_mesh_mask=";
    if (world_mesh_mask_valid)
    {
        summary_stream << world_mesh_mask;
    }
    else
    {
        summary_stream << L"?";
    }
    summary_stream << L", world_viewmodel_present=" << (world_viewmodel_handle != kInvalidEntityHandle ? 1 : 0)
        << L", world_providee_present=" << (world_providee_handle != kInvalidEntityHandle ? 1 : 0)
        << L", world_owner_present=" << (world_owner_handle != kInvalidEntityHandle ? 1 : 0)
        << L", world_old_move_parent_present=" << (world_old_move_parent_handle != kInvalidEntityHandle ? 1 : 0)
        << L", world_scene_node=" << FormatPointer(world_scene_node)
        << L", world_scene_owner=" << world_scene_owner_entity_index
        << L", world_scene_owner_ptr=" << FormatPointer(world_scene_owner_entity)
        << L", trace_built=" << (trace_built ? 1 : 0);
    if (trace_built)
    {
        summary_stream << L", trace={" << DescribeRenderedWorldWeaponTrace(trace) << L"}";
    }
    nskinzcs2::Logger::Info(summary_stream.str());

    std::wstringstream attachment_stream;
    attachment_stream << L"Knife world neighborhood attachments for XUID " << xuid
        << L": " << join_samples(attachment_samples);
    nskinzcs2::Logger::Info(attachment_stream.str());

    std::wstringstream reverse_stream;
    reverse_stream << L"Knife world neighborhood reverse refs for XUID " << xuid
        << L": owner_refs=" << reverse_owner_ref_count
        << L", old_move_parent_refs=" << reverse_old_move_parent_ref_count
        << L", viewmodel_refs=" << reverse_viewmodel_ref_count
        << L", providee_refs=" << reverse_providee_ref_count
        << L", samples=" << join_samples(reverse_ref_samples);
    nskinzcs2::Logger::Info(reverse_stream.str());

    std::wstringstream scene_stream;
    scene_stream << L"Knife world neighborhood scene children for XUID " << xuid
        << L": child_count=" << scene_child_count
        << L", ownerless=" << scene_child_ownerless_count
        << L", weapon_like=" << scene_child_weapon_like_count
        << L", character_like=" << scene_child_character_like_count
        << L", synthetic=" << scene_child_synthetic_count
        << L", samples=" << join_samples(scene_child_samples);
    nskinzcs2::Logger::Info(scene_stream.str());
}

nskinzcs2::runtime::KnifeRuntimeContext ResolveKnifeRuntimeContext(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int world_weapon_entity_index,
    void* world_weapon_entity,
    void* world_item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const std::uint64_t watched_xuid,
    const int current_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    const bool demo_playing,
    const bool schema_ready,
    const bool entity_system_ready,
    const ObserverTargetResolution* observer_resolution,
    const HeuristicXuidBridgeResolution* bridge_resolution)
{
    nskinzcs2::runtime::KnifeRuntimeContext context {};
    context.watched_xuid = watched_xuid;
    context.live_definition_index = current_definition_index;
    context.world_entity_index = world_weapon_entity_index;
    context.world_definition_index = current_definition_index;
    context.demo_playing = demo_playing;
    context.schema_ready = schema_ready;
    context.entity_system_ready = entity_system_ready;
    context.watched_target = xuid == watched_xuid;
    context.active_weapon_is_knife =
        NormalizeBaseItem(current_definition_index, knife_definition_indices, glove_definition_indices) == 42;
    context.world_carrier_valid = world_weapon_entity != nullptr;
    context.world_item_view_valid = world_item_view != nullptr;

    context.viewmodel_absence_audit_result =
        static_cast<std::uint32_t>(nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::Skipped);
    ObserverRealViewmodelResolution observer_real_viewmodel_resolution {};
    ObserverRealViewmodelResolution bridge_real_viewmodel_resolution {};
    const bool observer_context_matches_xuid =
        observer_resolution != nullptr &&
        ObserverTargetResolutionResolved(*observer_resolution) &&
        observer_resolution->target_xuid == xuid;
    const bool bridge_context_matches_xuid =
        bridge_resolution != nullptr &&
        bridge_resolution->Resolved() &&
        bridge_resolution->xuid == xuid;
    auto apply_real_viewmodel_resolution =
        [&](const ObserverRealViewmodelResolution& resolution, const int active_weapon_entity_index)
        {
            context.real_viewmodel_services_present = resolution.viewmodel_services_present;
            context.real_viewmodel_handle_valid = resolution.viewmodel_handle_valid;
            context.real_viewmodel_handle_invalid = resolution.viewmodel_handle_invalid;
            context.real_viewmodel_entity_index = resolution.viewmodel_entity_index;
            context.real_viewmodel_weapon_entity_index = resolution.viewmodel_weapon_entity_index;
            context.real_viewmodel_weapon_matches_active_weapon =
                resolution.viewmodel_weapon_matches_active_weapon &&
                active_weapon_entity_index == world_weapon_entity_index;
            context.real_viewmodel_active_weapon_verified_knife =
                resolution.active_weapon_verified_knife &&
                active_weapon_entity_index == world_weapon_entity_index;
        };
    if (observer_context_matches_xuid)
    {
        context.observer_chain_present = true;
        context.observer_in_eye_valid = observer_resolution->observer_in_eye_valid;
        context.observer_target_xuid = observer_resolution->target_xuid;
        context.observer_target_pawn_entity_index = observer_resolution->target_pawn_entity_index;
        context.observer_active_weapon_entity_index = observer_resolution->active_weapon_entity_index;
        context.observer_active_weapon_is_knife =
            observer_resolution->active_weapon_is_knife &&
            observer_resolution->active_weapon_entity_index == world_weapon_entity_index;
        observer_real_viewmodel_resolution =
            ResolveObserverFirstRealViewmodel(
                entity_list,
                entity_cache,
                *observer_resolution,
                offsets);
        apply_real_viewmodel_resolution(
            observer_real_viewmodel_resolution,
            observer_resolution->active_weapon_entity_index);
    }

    if (bridge_context_matches_xuid)
    {
        context.bridge_source =
            bridge_resolution->source != nullptr ? bridge_resolution->source : L"heuristic_xuid_bridge";
        context.bridged_controller_entity_index = bridge_resolution->controller_entity_index;
        context.bridged_pawn_entity_index = bridge_resolution->pawn_entity_index;
        context.bridge_active_weapon_entity_index = bridge_resolution->active_weapon_entity_index;
        context.bridge_pawn_health = bridge_resolution->health;
        context.bridge_cache_hit = bridge_resolution->cache_hit;
        context.bridge_pawn_alive = bridge_resolution->pawn_alive;
        context.bridge_active_weapon_is_knife =
            bridge_resolution->active_weapon_is_knife &&
            bridge_resolution->active_weapon_entity_index == world_weapon_entity_index;
        bridge_real_viewmodel_resolution =
            ResolveHeuristicXuidBridgeRealViewmodel(
                entity_list,
                entity_cache,
                *bridge_resolution,
                offsets);
        if (!observer_context_matches_xuid)
        {
            apply_real_viewmodel_resolution(
                bridge_real_viewmodel_resolution,
                bridge_resolution->active_weapon_entity_index);
        }
    }

    const auto* authoritative_real_viewmodel_resolution =
        observer_context_matches_xuid
            ? &observer_real_viewmodel_resolution
            : bridge_context_matches_xuid
                ? &bridge_real_viewmodel_resolution
                : nullptr;
    const auto authoritative_active_weapon_definition_index =
        observer_context_matches_xuid
            ? observer_resolution->active_weapon_definition_index
            : bridge_context_matches_xuid
                ? bridge_resolution->active_weapon_definition_index
                : current_definition_index;
    const bool authoritative_watched_active_knife =
        observer_context_matches_xuid
            ? context.observer_active_weapon_is_knife
            : bridge_context_matches_xuid
                ? context.bridge_active_weapon_is_knife
                : (context.watched_target && context.active_weapon_is_knife);

    auto remember_viewmodel_shell =
        [&](const int entity_index, const wchar_t* source)
        {
            if (!IsResolvedRuntimeEntityIndex(entity_index) || entity_index == world_weapon_entity_index)
            {
                return;
            }

            if (context.viewmodel_shell_entity_index < 0)
            {
                context.viewmodel_shell_entity_index = entity_index;
            }
            if ((context.viewmodel_resolution_source == nullptr ||
                 std::wcscmp(context.viewmodel_resolution_source, L"none") == 0) &&
                source != nullptr)
            {
                context.viewmodel_resolution_source = source;
            }
        };

    auto remember_providee_diagnostic =
        [&](const int entity_index, const int definition_index)
        {
            if (!IsResolvedRuntimeEntityIndex(entity_index) ||
                IsSyntheticRuntimeEntityIndex(entity_index) ||
                entity_index == world_weapon_entity_index)
            {
                return false;
            }

            context.providee_carrier_valid = true;
            context.providee_entity_index = entity_index;
            context.providee_definition_index =
                definition_index != 0 ? definition_index : current_definition_index;
            return true;
        };

    auto log_providee_candidate_diagnostic_once =
        [&](const wchar_t* stage)
        {
            const auto* resolution_source = context.viewmodel_resolution_source;
            if (!context.providee_carrier_valid ||
                context.viewmodel_carrier_valid ||
                resolution_source == nullptr ||
                std::wcscmp(resolution_source, L"providee_render_child") != 0 ||
                !IsResolvedRuntimeEntityIndex(context.providee_entity_index) ||
                IsSyntheticRuntimeEntityIndex(context.providee_entity_index))
            {
                return;
            }

            const auto signature =
                xuid ^
                (static_cast<std::uint64_t>(
                     static_cast<std::uint32_t>(
                         world_weapon_entity_index >= 0 ? world_weapon_entity_index : 0))
                 << 32) ^
                (static_cast<std::uint64_t>(
                     static_cast<std::uint32_t>(
                         context.providee_entity_index >= 0 ? context.providee_entity_index : 0))
                 << 8) ^
                0x5052564449414731ull;

            void* providee_entity = nullptr;
            if (static_cast<std::size_t>(context.providee_entity_index) < entity_cache.size())
            {
                providee_entity = entity_cache[static_cast<std::size_t>(context.providee_entity_index)];
            }
            if (providee_entity == nullptr &&
                (!TryGetEntityFromIndex(entity_list, context.providee_entity_index, providee_entity) ||
                 providee_entity == nullptr))
            {
                std::wstringstream stream;
                stream << L"Knife providee candidate diagnostic: stage="
                    << (stage != nullptr ? stage : L"runtime_context")
                    << L", world_entity=" << world_weapon_entity_index
                    << L", providee_entity=" << context.providee_entity_index
                    << L", entity_ptr=0x0"
                    << L", entity_resolved=0"
                    << L", resolution_source=" << resolution_source;
                LogProfileDiagnosticOnce(signature, stream.str());
                return;
            }

            auto* providee_item_view = ResolveWeaponItemView(providee_entity, offsets);
            int providee_definition_index = 0;
            if (providee_item_view != nullptr)
            {
                TryReadItemDefinitionIndex(providee_item_view, offsets, providee_definition_index);
            }
            const auto providee_model_kind =
                ClassifyKnifeFirstPersonRenderableModel(providee_entity, offsets);
            const auto* providee_model_kind_text =
                providee_model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike
                    ? L"weapon"
                    : providee_model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike
                        ? L"character"
                        : L"unknown";
            int safe_definition_index = 0;
            const auto parent_definition_index =
                current_definition_index != 0
                    ? current_definition_index
                    : (context.providee_definition_index != 0
                           ? context.providee_definition_index
                           : context.live_definition_index);
            const auto safe_linked =
                providee_item_view != nullptr &&
                IsSafeLinkedWeaponItemView(
                    providee_item_view,
                    offsets,
                    xuid,
                    parent_definition_index,
                    known_definition_indices,
                    knife_definition_indices,
                    glove_definition_indices,
                    safe_definition_index);

            std::string model_name;
            TryReadEntityModelNameString(providee_entity, offsets, model_name);

            std::wstringstream stream;
            stream << L"Knife providee candidate diagnostic: stage="
                << (stage != nullptr ? stage : L"runtime_context")
                << L", world_entity=" << world_weapon_entity_index
                << L", providee_entity=" << context.providee_entity_index
                << L", entity_ptr=" << FormatPointer(providee_entity)
                << L", item_view=" << FormatPointer(providee_item_view)
                << L", definition=" << providee_definition_index
                << L", model_kind=" << providee_model_kind_text
                << L", safe_linked=" << (safe_linked ? 1 : 0)
                << L", safe_definition=" << safe_definition_index
                << L", current_definition=" << current_definition_index
                << L", providee_definition=" << context.providee_definition_index
                << L", live_definition=" << context.live_definition_index
                << L", source=" << resolution_source;
            if (!model_name.empty())
            {
                stream << L", model_name=" << NarrowToWide(model_name);
            }
            LogProfileDiagnosticOnce(signature, stream.str());
        };

    auto try_promote_real_viewmodel_carrier =
        [&](const int entity_index,
            const int fallback_definition_index,
            const wchar_t* source)
        {
            if (!IsResolvedRuntimeEntityIndex(entity_index) ||
                IsSyntheticRuntimeEntityIndex(entity_index) ||
                entity_index == world_weapon_entity_index)
            {
                return false;
            }

            void* entity = nullptr;
            if (static_cast<std::size_t>(entity_index) < entity_cache.size())
            {
                entity = entity_cache[static_cast<std::size_t>(entity_index)];
            }
            if (entity == nullptr &&
                (!TryGetEntityFromIndex(entity_list, entity_index, entity) || entity == nullptr))
            {
                return false;
            }

            remember_viewmodel_shell(entity_index, source);

            auto* item_view = ResolveWeaponItemView(entity, offsets);
            if (item_view == nullptr)
            {
                return false;
            }

            if (ClassifyKnifeFirstPersonRenderableModel(entity, offsets) !=
                KnifeFirstPersonRenderableModelKind::WeaponLike)
            {
                return false;
            }

            int safe_definition_index = 0;
            const auto parent_definition_index =
                current_definition_index != 0 ? current_definition_index : fallback_definition_index;
            if (!IsSafeLinkedWeaponItemView(
                    item_view,
                    offsets,
                    xuid,
                    parent_definition_index != 0 ? parent_definition_index : fallback_definition_index,
                    known_definition_indices,
                    knife_definition_indices,
                    glove_definition_indices,
                    safe_definition_index))
            {
                return false;
            }

            context.viewmodel_carrier_valid = true;
            context.viewmodel_entity_index = entity_index;
            context.viewmodel_carrier_entity_index = entity_index;
            context.viewmodel_definition_index =
                safe_definition_index != 0
                    ? safe_definition_index
                    : (fallback_definition_index != 0 ? fallback_definition_index : current_definition_index);
            if (context.viewmodel_render_entity_index < 0)
            {
                context.viewmodel_render_entity_index = entity_index;
            }
            context.viewmodel_resolution_source =
                source != nullptr ? source : L"resolved_viewmodel";
            return true;
        };

    if (authoritative_real_viewmodel_resolution != nullptr &&
        IsResolvedRuntimeEntityIndex(context.real_viewmodel_entity_index))
    {
        remember_viewmodel_shell(
            context.real_viewmodel_entity_index,
            authoritative_real_viewmodel_resolution->resolution_source);
        if (context.viewmodel_render_entity_index < 0)
        {
            context.viewmodel_render_entity_index = context.real_viewmodel_entity_index;
        }
        if (context.real_viewmodel_weapon_matches_active_weapon &&
        context.real_viewmodel_active_weapon_verified_knife)
        {
            try_promote_real_viewmodel_carrier(
                context.real_viewmodel_entity_index,
                authoritative_active_weapon_definition_index,
                authoritative_real_viewmodel_resolution->resolution_source);
            if (!context.viewmodel_carrier_valid &&
                context.real_viewmodel_handle_valid &&
                world_item_view != nullptr &&
                authoritative_real_viewmodel_resolution->viewmodel_entity != nullptr &&
                ClassifyKnifeFirstPersonRenderableModel(
                    authoritative_real_viewmodel_resolution->viewmodel_entity,
                    offsets) == KnifeFirstPersonRenderableModelKind::WeaponLike)
            {
                context.viewmodel_carrier_valid = true;
                context.viewmodel_entity_index = context.real_viewmodel_entity_index;
                context.viewmodel_carrier_entity_index = context.real_viewmodel_entity_index;
                context.viewmodel_definition_index =
                    authoritative_active_weapon_definition_index != 0
                        ? authoritative_active_weapon_definition_index
                        : current_definition_index;
                context.viewmodel_resolution_source =
                    authoritative_real_viewmodel_resolution->resolution_source != nullptr
                        ? authoritative_real_viewmodel_resolution->resolution_source
                        : (observer_context_matches_xuid
                               ? L"observer_real_viewmodel"
                               : L"bridge_real_viewmodel");
            }
        }
    }

    CanonicalWeaponCarrierBinding binding {};
    if (context.world_carrier_valid &&
        context.world_item_view_valid &&
        TryResolveCanonicalWeaponCarrier(
            entity_list,
            entity_cache,
            player_binding,
            world_weapon_entity_index,
            world_weapon_entity,
            world_item_view,
            offsets,
            xuid,
            current_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            binding))
    {
        context.world_carrier_valid = binding.world.IsValid();
        context.world_item_view_valid = binding.world.item_view != nullptr;
        if (binding.providee.IsValid())
        {
            remember_providee_diagnostic(
                binding.providee.entity_index,
                binding.providee.definition_index);
        }
        if (binding.viewmodel.entity_index >= 0)
        {
            remember_viewmodel_shell(binding.viewmodel.entity_index, L"canonical_binding");
        }
        if (binding.viewmodel.IsValid())
        {
            try_promote_real_viewmodel_carrier(
                binding.viewmodel.entity_index,
                binding.viewmodel.definition_index,
                L"canonical_binding");
        }
    }

    const auto effective_owner_state =
        ResolveKnifeEffectiveOwnerBindingState(
            entity_list,
            entity_cache,
            player_binding,
            world_weapon_entity_index,
            offsets,
            current_definition_index,
            &context);
    LogKnifeEffectiveOwnerBindingState(
        L"runtime context",
        xuid,
        world_weapon_entity_index,
        &context,
        effective_owner_state);
    LogWatchedKnifeOwnerAttachmentProbe(
        xuid,
        entity_list,
        entity_cache,
        world_weapon_entity,
        offsets,
        world_weapon_entity_index,
        current_definition_index,
        effective_owner_state);
    LogWatchedKnifeWorldNeighborhoodProbe(
        xuid,
        entity_list,
        entity_cache,
        player_binding,
        world_weapon_entity,
        world_item_view,
        offsets,
        world_weapon_entity_index,
        current_definition_index);
    if (effective_owner_state.providee_valid &&
        ShouldLogWatchedKnifeAnimationTrace(xuid))
    {
        void* effective_providee_entity = nullptr;
        if (static_cast<std::size_t>(effective_owner_state.providee_entity_index) < entity_cache.size())
        {
            effective_providee_entity =
                entity_cache[static_cast<std::size_t>(effective_owner_state.providee_entity_index)];
        }
        if (effective_providee_entity == nullptr)
        {
            TryGetEntityFromIndex(
                entity_list,
                effective_owner_state.providee_entity_index,
                effective_providee_entity);
        }
        if (effective_providee_entity != nullptr &&
            ClassifyKnifeFirstPersonRenderableModel(effective_providee_entity, offsets) ==
                KnifeFirstPersonRenderableModelKind::CharacterLike)
        {
            const auto signature =
                xuid ^
                (static_cast<std::uint64_t>(
                     static_cast<std::uint32_t>(
                         world_weapon_entity_index >= 0 ? world_weapon_entity_index : 0))
                 << 32) ^
                static_cast<std::uint64_t>(
                    static_cast<std::uint32_t>(
                        effective_owner_state.providee_entity_index >= 0
                            ? effective_owner_state.providee_entity_index
                            : 0)) ^
                0x4546465052563031ull;
            auto* effective_item_view = ResolveWeaponItemView(effective_providee_entity, offsets);
            std::uint32_t old_providee_handle = kInvalidEntityHandle;
            const auto old_providee_field_present =
                offsets.econ_entity_old_providee != 0 &&
                world_weapon_entity != nullptr &&
                SafeReadField(world_weapon_entity, offsets.econ_entity_old_providee, old_providee_handle);
            std::uint32_t providee_viewmodel_handle = kInvalidEntityHandle;
            const auto providee_viewmodel_field_present =
                offsets.econ_entity_viewmodel_attachment != 0 &&
                SafeReadField(
                    effective_providee_entity,
                    offsets.econ_entity_viewmodel_attachment,
                    providee_viewmodel_handle);
            std::string model_name;
            TryReadEntityModelNameString(effective_providee_entity, offsets, model_name);
            std::wstringstream stream;
            stream << L"Knife effective providee retention: world_entity=" << world_weapon_entity_index
                << L", context_providee_entity=" << context.providee_entity_index
                << L", effective_providee_entity=" << effective_owner_state.providee_entity_index
                << L", same_as_context="
                << (effective_owner_state.providee_entity_index == context.providee_entity_index ? 1 : 0)
                << L", from_player_binding="
                << (effective_owner_state.providee_from_player_binding ? 1 : 0)
                << L", definition=" << effective_owner_state.providee_definition_index
                << L", item_view=" << FormatPointer(effective_item_view)
                << L", old_providee_field_present=" << (old_providee_field_present ? 1 : 0)
                << L", old_providee_handle=0x" << std::hex << std::uppercase << old_providee_handle
                << L", providee_viewmodel_field_present=" << (providee_viewmodel_field_present ? 1 : 0)
                << L", providee_viewmodel_handle=0x" << providee_viewmodel_handle
                << std::dec << std::nouppercase
                << L", current_viewmodel_entity=" << context.viewmodel_entity_index
                << L", current_viewmodel_valid=" << (context.viewmodel_carrier_valid ? 1 : 0)
                << L", reason=character_like_item_view_accepted";
            if (!model_name.empty())
            {
                stream << L", model_name=" << NarrowToWide(model_name);
            }
            LogProfileDiagnosticOnce(signature, stream.str());
        }
    }
    if (!context.providee_carrier_valid && effective_owner_state.providee_valid)
    {
        remember_providee_diagnostic(
            effective_owner_state.providee_entity_index,
            effective_owner_state.providee_definition_index);
    }
    if (effective_owner_state.viewmodel_entity_index >= 0)
    {
        remember_viewmodel_shell(
            effective_owner_state.viewmodel_entity_index,
            effective_owner_state.viewmodel_from_player_binding
                ? L"player_binding_viewmodel"
                : L"effective_owner_binding");
    }
    if (!context.viewmodel_carrier_valid && effective_owner_state.viewmodel_valid)
    {
        try_promote_real_viewmodel_carrier(
            effective_owner_state.viewmodel_entity_index,
            effective_owner_state.viewmodel_definition_index,
            effective_owner_state.viewmodel_from_player_binding
                ? L"player_binding_viewmodel"
                : L"effective_owner_binding");
    }

    if (!context.viewmodel_carrier_valid)
    {
        int cached_first_person_entity_index = -1;
        void* cached_first_person_entity = nullptr;
        void* cached_first_person_item_view = nullptr;
        int cached_first_person_definition_index = 0;
        auto cached_owner_kind = nskinzcs2::runtime::KnifeFirstPersonOwnerKind::None;
        if (TryResolveCachedKnifeFirstPersonEntity(
                entity_list,
                entity_cache,
                offsets,
                xuid,
                world_weapon_entity_index,
                current_definition_index,
                known_definition_indices,
                knife_definition_indices,
                glove_definition_indices,
                cached_first_person_entity_index,
                cached_first_person_entity,
                cached_first_person_item_view,
                cached_first_person_definition_index,
                cached_owner_kind))
        {
            if (cached_owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel &&
                try_promote_real_viewmodel_carrier(
                    cached_first_person_entity_index,
                    cached_first_person_definition_index,
                    L"cached_viewmodel_snapshot"))
            {
                if (ShouldLogWatchedKnifeAnimationTrace(xuid))
                {
                    std::wstringstream stream;
                    stream << L"Knife runtime context recovered cached real viewmodel binding: world_entity="
                        << world_weapon_entity_index
                        << L", first_person_entity=" << cached_first_person_entity_index
                        << L", owner_kind=" << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(cached_owner_kind)
                        << L", first_person_definition=" << cached_first_person_definition_index;
                    nskinzcs2::Logger::Info(stream.str());
                }
            }
        }
    }

    log_providee_candidate_diagnostic_once(L"post_owner_resolution");

    if ((observer_context_matches_xuid || bridge_context_matches_xuid) &&
        (context.real_viewmodel_entity_index >= 0 ||
         context.real_viewmodel_handle_valid ||
         context.real_viewmodel_handle_invalid) &&
        !context.real_viewmodel_weapon_matches_active_weapon)
    {
        context.viewmodel_carrier_valid = false;
        context.viewmodel_entity_index = -1;
        context.viewmodel_carrier_entity_index = -1;
        context.viewmodel_definition_index = 0;
    }

    if (!context.viewmodel_carrier_valid &&
        context.watched_target &&
        authoritative_watched_active_knife &&
        context.world_carrier_valid &&
        context.world_item_view_valid)
    {
        KnifePersistentOwnerResolution resolution {};
        if (TryResolvePersistentKnifeOwnerFromDirectRender(
                entity_list,
                entity_cache,
                player_binding,
                world_weapon_entity_index,
                world_weapon_entity,
                world_item_view,
                offsets,
                xuid,
                current_definition_index,
                known_definition_indices,
                knife_definition_indices,
                glove_definition_indices,
                context.providee_entity_index,
                context.viewmodel_entity_index,
                nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel,
                resolution) ||
            resolution.clue_found)
        {
            context.direct_first_person_render_valid = resolution.clue_found;
            context.direct_first_person_render_only = resolution.clue_render_only;
            context.direct_first_person_render_entity_index = resolution.clue_entity_index;
            context.direct_first_person_render_entity = resolution.clue_entity;
            context.direct_first_person_render_definition_index =
                resolution.clue_definition_index != 0
                    ? resolution.clue_definition_index
                    : current_definition_index;
            context.direct_first_person_animation_owner_valid =
                resolution.promoted &&
                resolution.owner_entity_index >= 0 &&
                resolution.owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel &&
                !IsSyntheticRuntimeEntityIndex(resolution.owner_entity_index);
            context.direct_first_person_animation_owner_entity_index =
                resolution.promoted &&
                    resolution.owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel
                ? resolution.owner_entity_index
                : -1;
            context.direct_first_person_animation_owner_definition_index =
                resolution.promoted &&
                    resolution.owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel
                ? resolution.owner_definition_index
                : 0;
            context.viewmodel_absence_audit_result =
                static_cast<std::uint32_t>(resolution.discovery_snapshot.viewmodel_absence_audit.result);
            if (resolution.discovery_snapshot.viewmodel_absence_audit.handle_entity_index >= 0)
            {
                remember_viewmodel_shell(
                    resolution.discovery_snapshot.viewmodel_absence_audit.handle_entity_index,
                    L"viewmodel_attachment");
            }
            if (resolution.clue_found)
            {
                remember_viewmodel_shell(resolution.clue_entity_index, resolution.clue_source);
                context.viewmodel_render_entity_index = resolution.clue_entity_index;
                if (context.viewmodel_resolution_source == nullptr ||
                    std::wcscmp(context.viewmodel_resolution_source, L"none") == 0)
                {
                    context.viewmodel_resolution_source =
                        resolution.clue_source != nullptr
                            ? resolution.clue_source
                            : L"direct_render_clue";
                }
            }

            if (resolution.promoted &&
                resolution.owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel)
            {
                try_promote_real_viewmodel_carrier(
                    resolution.owner_entity_index,
                    resolution.owner_definition_index,
                    L"direct_render_reacquire");
            }
        }
    }

    log_providee_candidate_diagnostic_once(L"post_direct_render_resolution");

    if (context.viewmodel_carrier_valid)
    {
        context.first_person_owner_kind = nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel;
        context.first_person_source_definition_index = context.viewmodel_definition_index;
        context.first_person_source_valid = context.first_person_source_definition_index != 0;
        if (context.viewmodel_shell_entity_index < 0)
        {
            context.viewmodel_shell_entity_index = context.viewmodel_entity_index;
        }
        if (context.viewmodel_render_entity_index < 0)
        {
            context.viewmodel_render_entity_index = context.viewmodel_entity_index;
        }
        context.viewmodel_carrier_entity_index = context.viewmodel_entity_index;
    }
    else if (context.direct_first_person_render_valid)
    {
        context.first_person_owner_kind = nskinzcs2::runtime::KnifeFirstPersonOwnerKind::None;
        context.first_person_source_definition_index = context.direct_first_person_render_definition_index;
        context.first_person_source_valid = context.first_person_source_definition_index != 0;
        if (context.viewmodel_resolution_source == nullptr ||
            std::wcscmp(context.viewmodel_resolution_source, L"none") == 0)
        {
            context.viewmodel_resolution_source = L"proxy_diagnostic";
        }
    }
    else if (context.providee_carrier_valid)
    {
        context.first_person_owner_kind = nskinzcs2::runtime::KnifeFirstPersonOwnerKind::None;
        context.first_person_source_definition_index =
            context.providee_definition_index != 0
                ? context.providee_definition_index
                : context.live_definition_index;
        context.first_person_source_valid = context.first_person_source_definition_index != 0;
        if (context.viewmodel_resolution_source == nullptr ||
            std::wcscmp(context.viewmodel_resolution_source, L"none") == 0)
        {
            context.viewmodel_resolution_source = L"proxy_diagnostic";
        }
    }
    else if (context.world_carrier_valid)
    {
        context.first_person_owner_kind = nskinzcs2::runtime::KnifeFirstPersonOwnerKind::WorldDiagnosticOnly;
        context.first_person_source_definition_index = context.world_definition_index;
    }

    const bool observer_chain_weapon_mismatch =
        context.observer_chain_present &&
        (context.real_viewmodel_entity_index >= 0 ||
         context.real_viewmodel_handle_valid ||
         context.real_viewmodel_handle_invalid) &&
        !context.real_viewmodel_weapon_matches_active_weapon;
    const bool bridge_chain_weapon_mismatch =
        bridge_context_matches_xuid &&
        (context.real_viewmodel_entity_index >= 0 ||
         context.real_viewmodel_handle_valid ||
         context.real_viewmodel_handle_invalid) &&
        !context.real_viewmodel_weapon_matches_active_weapon;
    context.hud_proxy_fallback_allowed =
        context.watched_target &&
        authoritative_watched_active_knife &&
        (!context.observer_chain_present ||
         (context.observer_in_eye_valid &&
          context.observer_active_weapon_is_knife &&
          (!context.real_viewmodel_handle_valid ||
           !context.viewmodel_carrier_valid ||
           observer_chain_weapon_mismatch)));
        if (!context.observer_chain_present &&
            bridge_context_matches_xuid)
        {
            context.hud_proxy_fallback_allowed =
                context.hud_proxy_fallback_allowed &&
                context.bridge_active_weapon_is_knife &&
                (!context.real_viewmodel_handle_valid ||
                 !context.viewmodel_carrier_valid ||
                 bridge_chain_weapon_mismatch);
        }

    const auto has_persistent_first_person_binding =
        context.first_person_source_valid &&
        context.viewmodel_carrier_valid &&
        context.first_person_owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel;
    context.knife_sync_ready =
        context.demo_playing &&
        context.schema_ready &&
        context.entity_system_ready &&
        context.watched_target &&
        authoritative_watched_active_knife &&
        context.world_carrier_valid &&
        context.world_item_view_valid &&
        has_persistent_first_person_binding;
    if (!context.knife_sync_ready &&
        context.providee_carrier_valid &&
        !context.viewmodel_carrier_valid &&
        context.viewmodel_resolution_source != nullptr &&
        std::wcscmp(context.viewmodel_resolution_source, L"providee_render_child") == 0)
    {
        const auto signature =
            xuid ^
            (static_cast<std::uint64_t>(
                 static_cast<std::uint32_t>(
                     world_weapon_entity_index >= 0 ? world_weapon_entity_index : 0))
             << 32) ^
            (static_cast<std::uint64_t>(
                 static_cast<std::uint32_t>(
                     context.providee_entity_index >= 0 ? context.providee_entity_index : 0))
             << 8) ^
            0x53594E4347415445ull;
        std::wstringstream stream;
        stream << L"Knife sync gate diagnostic: world_entity=" << world_weapon_entity_index
            << L", providee_entity=" << context.providee_entity_index
            << L", resolution_source=" << context.viewmodel_resolution_source
            << L", demo_playing=" << (context.demo_playing ? 1 : 0)
            << L", schema_ready=" << (context.schema_ready ? 1 : 0)
            << L", entity_system_ready=" << (context.entity_system_ready ? 1 : 0)
            << L", watched_target=" << (context.watched_target ? 1 : 0)
            << L", watched_active_knife=" << (authoritative_watched_active_knife ? 1 : 0)
            << L", world_carrier_valid=" << (context.world_carrier_valid ? 1 : 0)
            << L", world_item_view_valid=" << (context.world_item_view_valid ? 1 : 0)
            << L", first_person_source_valid=" << (context.first_person_source_valid ? 1 : 0)
            << L", viewmodel_carrier_valid=" << (context.viewmodel_carrier_valid ? 1 : 0)
            << L", direct_render_valid=" << (context.direct_first_person_render_valid ? 1 : 0)
            << L", direct_render_owner_valid="
            << (context.direct_first_person_animation_owner_valid ? 1 : 0)
            << L", owner_kind="
            << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(context.first_person_owner_kind)
            << L", absence_result="
            << KnifeViewmodelAbsenceAuditResultTextForTrace(context.viewmodel_absence_audit_result)
            << L", has_persistent_first_person_binding="
            << (has_persistent_first_person_binding ? 1 : 0);
        LogProfileDiagnosticOnce(signature, stream.str());
    }
    LogWatchedKnifeViewmodelResolutionTrace(L"runtime_context_resolved", xuid, context);
    return context;
}

