void RestoreRuntimeWearableHandleBuffers(const wchar_t* reason) noexcept;

bool TryInvokeNetworkVectorOperation(
    const NetworkVectorOperationFn operation,
    const std::uint32_t operation_code,
    void* vector,
    const std::int32_t index,
    const std::int32_t count) noexcept
{
    if (operation == nullptr || vector == nullptr)
    {
        return false;
    }

    __try
    {
        operation(operation_code, vector, index, count);
        return true;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }
}

bool TryInvokeNetworkVectorElementMutation(
    const NetworkVectorOperationFn operation,
    void* vector,
    const std::int32_t index,
    void* expected_element) noexcept
{
    if (operation == nullptr || vector == nullptr || index < 0 || expected_element == nullptr)
    {
        return false;
    }

    // Schema's network-vector callback uses operation 2 for mutable element
    // access.  Unlike operation 1 (plain element lookup), operation 2 first
    // calls the vector's NetworkStateChanged path and then returns the element
    // address.  Raw CEconItemAttribute writes without this notification leave
    // the attribute manager/material generator free to reuse its old cached
    // value even though direct readback sees the new paint kit.
    __try
    {
        const auto mutable_element = operation(2, vector, index, 0);
        return mutable_element == reinterpret_cast<std::uintptr_t>(expected_element);
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }
}

void RestoreAppliedCosmeticStateForOriginalFrameStage(
    const AttributeBindingReleaseMode mode = AttributeBindingReleaseMode::RestoreOriginal,
    const wchar_t* reason = nullptr)
{
    g_hook_state.last_applied_demo_tick = -1;
    RestoreRuntimeWearableHandleBuffers(reason != nullptr ? reason : L"frame_stage_restore");
    ResetDemoKeychainControllerState();
    ReleaseRuntimeCreatedKeychainModuleEntities(
        g_hook_state.schema_offsets,
        reason != nullptr ? reason : L"frame_stage_restore");
    RestoreTrackedWeaponAppearanceRestorePoints(
        g_hook_state.schema_offsets,
        mode,
        reason);
    ReleaseRuntimeOwnedAttributeListBindings(mode);
    ClearKnifeRefreshHelperEpoch();
    ResetWeaponSkinRefreshAttemptWindowForRebuild();
    g_hook_state.applied_weapon_signatures.clear();
    g_hook_state.refreshed_weapon_signatures.clear();
    g_hook_state.standard_weapon_appearance_epochs.clear();
    g_hook_state.applied_glove_signatures.clear();
    g_hook_state.transient_glove_signatures.clear();
    g_hook_state.applied_preview_weapon_signatures.clear();
    g_hook_state.applied_preview_glove_signatures.clear();
    ClearKnifeModelWriteFailureStateCache();
    TryRestoreAndClearKnifeModelPathState(g_hook_state.schema_offsets, reason, mode);
    ClearKnifeModelPathSwapState(true);
    ClearCachedKnifeFirstPersonBinding();
    g_hook_state.next_runtime_poll_millis.store(0);
}

void RestoreRuntimeWearableHandleBuffers(const wchar_t* reason) noexcept
{
    auto& buffers = g_hook_state.runtime_entities.runtime_wearable_handle_buffers;
    for (auto& [xuid, binding] : buffers)
    {
        if (binding.appended_with_engine_operation &&
            binding.vector_address != nullptr &&
            binding.vector_operation != nullptr)
        {
            NetworkVectorView current {};
            std::uint32_t current_handle = kInvalidEntityHandle;
            if (TryReadNetworkVectorView(binding.vector_address, current) &&
                binding.appended_index < current.size &&
                current.data != nullptr &&
                SafeReadValue(
                    current.data + binding.appended_index * sizeof(std::uint32_t),
                    current_handle) &&
                current_handle == binding.installed_handle)
            {
                const auto removed = TryInvokeNetworkVectorOperation(
                    binding.vector_operation,
                    5,
                    binding.vector_address,
                    static_cast<std::int32_t>(binding.appended_index),
                    1);

                if (removed)
                {
                    std::wstringstream stream;
                    stream << L"Removed engine-appended m_hMyWearables slot for XUID " << xuid
                        << L": reason=" << (reason != nullptr ? reason : L"reset")
                        << L", installed_handle=0x" << std::hex << std::uppercase
                        << binding.installed_handle << std::dec << std::nouppercase << L".";
                    nskinzcs2::Logger::Info(stream.str());
                }
            }
            continue;
        }

        if (binding.in_place_slot != nullptr)
        {
            std::uint32_t current_handle = kInvalidEntityHandle;
            if (SafeReadValue(binding.in_place_slot, current_handle) &&
                current_handle == binding.installed_handle &&
                SafeWriteValue(binding.in_place_slot, binding.original_handle))
            {
                std::wstringstream stream;
                stream << L"Restored in-place m_hMyWearables slot for XUID " << xuid
                    << L": reason=" << (reason != nullptr ? reason : L"reset")
                    << L", slot=" << FormatPointer(binding.in_place_slot)
                    << L", installed_handle=0x" << std::hex << std::uppercase << binding.installed_handle
                    << L", original_handle=0x" << binding.original_handle
                    << std::dec << std::nouppercase << L".";
                nskinzcs2::Logger::Info(stream.str());
            }
            continue;
        }

        if (binding.vector_address == nullptr || binding.installed_data == nullptr)
        {
            continue;
        }

        NetworkVectorView current {};
        if (!TryReadNetworkVectorView(binding.vector_address, current) ||
            current.data != binding.installed_data)
        {
            continue;
        }

        NetworkVectorView original {};
        original.data = binding.original_data;
        original.size = binding.original_size;
        if (SafeWriteValue(binding.vector_address, original))
        {
            // Publishing this buffer transfers ownership to Source 2. During
            // a full update the engine can retain the old vector storage in a
            // pending network/destructor path even after we restore the field
            // header before FrameStageNotify. Freeing here races that pending
            // path and causes tier0 to touch an already-freed block. Detach the
            // header only; CS2 remains the sole final releaser. If a particular
            // reset path does not release it, the bounded cost is 64 bytes per
            // runtime-created glove binding.
            std::wstringstream stream;
            stream << L"Restored runtime-owned m_hMyWearables storage for XUID " << xuid
                << L": reason=" << (reason != nullptr ? reason : L"reset")
                << L", installed_data=" << FormatPointer(binding.installed_data)
                << L", original_data=" << FormatPointer(binding.original_data)
                << L", original_size=" << binding.original_size
                << L", tier0_release=deferred_to_cs2.";
            nskinzcs2::Logger::Info(stream.str());
        }
    }

    buffers.clear();
}

void PrepareAppliedCosmeticStateForDemoSeekBeforeOriginalFrameStage(const wchar_t* reason = nullptr)
{
    g_hook_state.knife_model_scene_epoch.fetch_add(1, std::memory_order_relaxed);
    g_hook_state.last_applied_demo_tick = -1;
    RestoreRuntimeWearableHandleBuffers(reason != nullptr ? reason : L"demo_seek_prepare");
    ResetDemoKeychainControllerState();
    ReleaseRuntimeCreatedKeychainModuleEntities(
        g_hook_state.schema_offsets,
        reason != nullptr ? reason : L"demo_seek_prepare");
    RestoreTrackedWeaponAppearanceRestorePoints(
        g_hook_state.schema_offsets,
        AttributeBindingReleaseMode::AbandonInstalled,
        reason);
    ReleaseRuntimeOwnedAttributeListBindings(AttributeBindingReleaseMode::AbandonInstalled);
    ClearKnifeRefreshHelperEpoch();
    ResetWeaponSkinRefreshAttemptWindowForRebuild();
    g_hook_state.applied_weapon_signatures.clear();
    g_hook_state.refreshed_weapon_signatures.clear();
    g_hook_state.standard_weapon_appearance_epochs.clear();
    g_hook_state.applied_glove_signatures.clear();
    g_hook_state.transient_glove_signatures.clear();
    g_hook_state.applied_preview_weapon_signatures.clear();
    g_hook_state.applied_preview_glove_signatures.clear();
    ClearKnifeModelWriteFailureStateCache();
    ResetKnifeAnimationStateSnapshot();
    ResetWatchedKnifeAnimationTraceState();
    TryRestoreAndClearKnifeModelPathState(
        g_hook_state.schema_offsets,
        reason,
        AttributeBindingReleaseMode::AbandonInstalled);
    ClearKnifeModelPathSwapState(true);
    ClearCachedKnifeFirstPersonBinding();
    g_hook_state.next_runtime_poll_millis.store(0);
}

void ClearRuntimeEntityManager(
    const std::wstring& reason,
    const AttributeBindingReleaseMode knife_model_path_release_mode = AttributeBindingReleaseMode::RestoreOriginal)
{
    ResetDemoKeychainControllerState();
    RestoreRuntimeWearableHandleBuffers(reason.empty() ? L"reset" : reason.c_str());
    g_hook_state.runtime_entities.players_by_xuid.clear();
    g_hook_state.runtime_entities.logged_profile_diagnostics.clear();
    g_hook_state.runtime_entities.last_rebuild_reason = reason;
    g_hook_state.last_rebuild_reason = reason;
    g_hook_state.stable_wearable_bound.store(false);
    g_hook_state.runtime_created_wearable_bound.store(false);
    g_hook_state.glove_pawn_fallback_bound.store(false);
    g_hook_state.knife_model_override_ready.store(false);
    g_hook_state.knife_viewmodel_sync_ready.store(false);
    g_hook_state.client_entity_factory_requested.store(false);
    g_hook_state.viewmodel_factory_discovery_ran.store(false);
    g_hook_state.viewmodel_factory_observed.store(false);
    g_hook_state.watched_xuid.store(0);
    {
        std::lock_guard<std::mutex> lock(g_hook_state.runtime_keychain_module_mutex);
        g_hook_state.runtime_created_keychain_module_entity_indices.clear();
    }
    g_hook_state.keychain_module_create_cooldown_until_millis.store(0);
    ClearKnifeModelWriteFailureStateCache();
    g_hook_state.runtime_rebuilding.store(!reason.empty());
    g_hook_state.runtime_rebuild_generation.fetch_add(1);
    ResetWatchedKnifeAnimationTraceState();
    TryRestoreAndClearKnifeModelPathState(
        g_hook_state.schema_offsets,
        reason.c_str(),
        knife_model_path_release_mode);
    ClearCachedKnifeFirstPersonBinding();
    ClearHeuristicXuidBridgeCache();
}

void ResetRuntimeState(
    const std::wstring& reason,
    const AttributeBindingReleaseMode attribute_binding_release_mode = AttributeBindingReleaseMode::RestoreOriginal,
    const bool invalidate_wearable_factory = false,
    const bool preserve_weapon_appearance_signatures = false)
{
    const auto knife_model_path_release_mode =
        ResolveKnifeModelPathReleaseModeForReset(reason, attribute_binding_release_mode);
    ResetAppliedStateCaches(
        attribute_binding_release_mode,
        knife_model_path_release_mode,
        preserve_weapon_appearance_signatures);
    ClearKnifeRefreshHelperEpoch();
    ResetWeaponSkinRefreshAttemptWindowForRebuild();
    ClearRuntimeEntityManager(reason, knife_model_path_release_mode);
    {
        std::lock_guard<std::mutex> lock(g_hook_state.runtime_glove_provenance_mutex);
        g_hook_state.runtime_glove_provenance_by_handle.clear();
        g_hook_state.runtime_glove_create_generation_by_xuid.clear();
    }
    g_hook_state.attempted_wearable_definition_refresh_signatures.clear();
    g_hook_state.attempted_wearable_set_model_signatures.clear();
    g_hook_state.rejected_wearable_model_bind_signatures.clear();
    if (invalidate_wearable_factory)
    {
        InvalidateCachedWearableFactoryResolutionForProviderChange();
    }
    else
    {
        // Manual/config/watched-player rebuilds do not change the validated
        // Source2Client/CGameEntitySystem tuple. Preserve an available binding
        // so Update cannot land in the one-frame Unknown window. Failed or
        // pending resolutions are cleared and may recover normally.
        ClearCachedWearableFactoryResolution(true);
    }
    g_hook_state.runtime_entities.client_entity_factory = RuntimeFeatureAvailability::Unknown;
    g_hook_state.runtime_entities.wearable_client_factory = {};
    g_hook_state.client_entity_factory_requested.store(false);
    g_hook_state.client_entity_factory_ready.store(false);
    g_hook_state.viewmodel_factory_discovery_ran.store(false);
    g_hook_state.viewmodel_factory_observed.store(false);
    {
        std::scoped_lock lock(g_hook_state.resource_handle_query_mutex);
        g_hook_state.published_knife_model_path_swap_bridge = {};
        g_hook_state.knife_model_path_swap_bridge_publish_generation.store(
            0,
            std::memory_order_release);
    }
    ClearWeaponAppearanceTelemetry();
}

bool WarnOnceForRuntimeSignature(const std::uint64_t signature, const std::wstring& message)
{
    if (!g_hook_state.warned_runtime_signatures.insert(signature).second)
    {
        return false;
    }

    nskinzcs2::Logger::Warn(message);
    return true;
}

bool LogProfileDiagnosticOnce(const std::uint64_t signature, const std::wstring& message)
{
    if (!g_hook_state.runtime_entities.logged_profile_diagnostics.insert(signature).second)
    {
        return false;
    }

    nskinzcs2::Logger::Info(message);
    return true;
}

const wchar_t* WeaponSkinRefreshTargetText(const nskinzcs2::runtime::WeaponSkinRefreshTarget target) noexcept
{
    using nskinzcs2::runtime::WeaponSkinRefreshTarget;

    switch (target)
    {
    case WeaponSkinRefreshTarget::CanonicalItemView:
        return L"CanonicalItemView";
    case WeaponSkinRefreshTarget::PrimaryItemView:
        return L"PrimaryItemView";
    case WeaponSkinRefreshTarget::ExactHudItemView:
        return L"ExactHudItemView";
    case WeaponSkinRefreshTarget::SecondaryItemView:
        return L"SecondaryItemView";
    case WeaponSkinRefreshTarget::ViewModelItemView:
        return L"ViewModelItemView";
    case WeaponSkinRefreshTarget::HeuristicViewModelItemView:
        return L"HeuristicViewModelItemView";
    case WeaponSkinRefreshTarget::ProvideeItemView:
        return L"ProvideeItemView";
    case WeaponSkinRefreshTarget::HeuristicProvideeItemView:
        return L"HeuristicProvideeItemView";
    case WeaponSkinRefreshTarget::PreviewItemView:
        return L"PreviewItemView";
    }

    return L"Unknown";
}

void TraceWatchedKnifeDiagnostic(
    const nskinzcs2::model::CosmeticProfile& profile,
    const std::wstring& message);

void LogKnifeRefreshHelperSuppressed(
    const PendingWeaponRefreshRequest& request,
    void* effective_refresh_item_view)
{
    const auto diagnostic_signature = request.desired_signature ^ 0x7424ull;
    std::wstringstream stream;
    stream << L"Knife refresh helper suppressed by crash guard: entity=" << request.entity_index
        << L", econ=" << FormatPointer(request.econ_entity)
        << L", item_view=" << FormatPointer(request.item_view)
        << L", refresh_item_view=" << FormatPointer(effective_refresh_item_view)
        << L", target=" << WeaponSkinRefreshTargetText(request.target)
        << L", " << DescribeKnifeRefreshHelperWindowState()
        << L". Finish-field writes remain enabled while automatic knife material refresh stays blocked.";
    LogProfileDiagnosticOnce(diagnostic_signature, stream.str());
    TraceWatchedKnifeDiagnostic(request.profile, stream.str());
}

void LogKnifeAttributeListMutationSuppressed(
    const nskinzcs2::model::CosmeticProfile& profile,
    void* item_view)
{
    const auto diagnostic_signature =
        BuildProfileApplySignature(profile, profile.xuid, profile.base_item, kTargetTagWeaponReadback) ^ 0x7428ull;
    std::wstringstream stream;
    stream << L"Knife attribute-list vector mutation suppressed by crash guard: item_view="
        << FormatPointer(item_view)
        << L", base_item=" << profile.base_item
        << L", paint=" << profile.paint_kit
        << L", seed=" << profile.seed
        << L", wear=" << profile.wear
        << L", stattrak=" << profile.stat_trak
        << L". Using fallback-field writes plus in-place-only attribute updates; append/growth and runtime-owned installs stay disabled to avoid cross-round crashes from knife attribute vectors.";
    LogProfileDiagnosticOnce(diagnostic_signature, stream.str());
    TraceWatchedKnifeDiagnostic(profile, stream.str());
}

const wchar_t* WeaponLinkTargetTagText(const std::uint64_t target_tag) noexcept
{
    switch (target_tag)
    {
    case kTargetTagWeaponEntity:
        return L"weapon_entity";
    case kTargetTagWeaponViewModel:
        return L"viewmodel";
    case kTargetTagWeaponProvidee:
        return L"providee";
    case kTargetTagWeaponCanonical:
        return L"canonical";
    case kTargetTagPreviewWeapon:
        return L"preview";
    default:
        return L"unknown";
    }
}

bool IsWatchedKnifeDiagnosticProfile(const nskinzcs2::model::CosmeticProfile& profile) noexcept
{
    if (!IsKnifeProfile(profile) || profile.xuid == 0)
    {
        return false;
    }

    const auto watched_xuid = g_hook_state.watched_xuid.load();
    return watched_xuid != 0 && profile.xuid == watched_xuid;
}

bool ShouldTraceWatchedKnifeDiagnostic(const nskinzcs2::model::CosmeticProfile& profile) noexcept
{
    return IsWatchedKnifeDiagnosticProfile(profile) &&
        (g_hook_state.runtime_trace_polls_remaining.load() > 0 ||
         g_hook_state.frame_stage_trace_callbacks_remaining.load() > 0);
}

void TraceWatchedKnifeDiagnostic(
    const nskinzcs2::model::CosmeticProfile& profile,
    const std::wstring& message)
{
    if (!ShouldTraceWatchedKnifeDiagnostic(profile))
    {
        return;
    }

    nskinzcs2::Logger::Info(L"Watched knife diagnostic: " + message);
}

bool KnifeProfileStoresDeferredModelSelection(const nskinzcs2::model::KnifeProfile& profile) noexcept
{
    return profile.mode == nskinzcs2::model::KnifeProfileMode::ModelAndFinish ||
        profile.model_definition != 0;
}

void LogKnifeFinishOnlyNormalization(
    const nskinzcs2::model::KnifeProfile& profile,
    const nskinzcs2::runtime::KnifeAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index)
{
    if (!KnifeProfileStoresDeferredModelSelection(profile) ||
        request.mode == nskinzcs2::runtime::KnifeSlotMode::None ||
        request.mode == nskinzcs2::runtime::KnifeSlotMode::ModelAndFinish)
    {
        return;
    }

    const auto signature =
        BuildKnifeProfileApplySignature(request, xuid, current_definition_index, kTargetTagWeaponEntity) ^ 0x3303ull;
    std::wstringstream stream;
    stream << L"Knife runtime normalized for XUID " << xuid
        << L": stored_mode="
        << (profile.mode == nskinzcs2::model::KnifeProfileMode::ModelAndFinish ? L"model_and_finish" : L"finish_only")
        << L", stored_model_definition=" << profile.model_definition
        << L", resolved_runtime_mode=finish_only"
        << L", resolved_runtime_model_definition=" << request.model_definition
        << L", applied_override_definition=0"
        << L". Runtime preserves the watched player's live knife model and only applies finish fields. Animation remap and linked first-person sync remain disabled.";
    LogProfileDiagnosticOnce(signature, stream.str());
}

void LogKnifeFinishOnlyGateBlocked(
    const nskinzcs2::runtime::KnifeAppearanceRequest& request,
    const nskinzcs2::runtime::KnifeApplyGateResult& gate,
    const std::uint64_t xuid,
    const std::uint64_t watched_xuid,
    const int current_definition_index)
{
    const auto signature =
        BuildKnifeProfileApplySignature(request, xuid, current_definition_index, kTargetTagWeaponEntity) ^ 0x3304ull;
    std::wstringstream stream;
    stream << L"Knife runtime gate blocked for XUID " << xuid
        << L": " << nskinzcs2::runtime::KnifeApplyGateReasonText(gate.reason);
    if (watched_xuid != 0)
    {
        stream << L" (watched_xuid=" << watched_xuid << L')';
    }
    LogProfileDiagnosticOnce(signature, stream.str());
}

void LogKnifeExactApplyResult(
    const nskinzcs2::runtime::KnifeAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index,
    const int entity_index)
{
    const auto signature =
        BuildKnifeProfileApplySignature(request, xuid, current_definition_index, kTargetTagWeaponCanonical) ^ 0x3305ull;
    std::wstringstream stream;
    stream << L"Knife exact apply succeeded/queued for XUID " << xuid
        << L" on entity " << entity_index << L'.';
    LogProfileDiagnosticOnce(signature, stream.str());
}

void LogKnifeFallbackWorldOnlyApplyResult(
    const nskinzcs2::runtime::KnifeAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index,
    const int entity_index)
{
    const auto signature =
        BuildKnifeProfileApplySignature(request, xuid, current_definition_index, kTargetTagWeaponEntity) ^ 0x3306ull;
    std::wstringstream stream;
    stream << L"Knife fallback world-only apply succeeded/queued for XUID " << xuid
        << L" on entity " << entity_index << L'.';
    LogProfileDiagnosticOnce(signature, stream.str());
}

struct KnifeAnimationBinding
{
    int first_person_entity_index = -1;
    void* first_person_entity = nullptr;
    void* first_person_item_view = nullptr;
    int first_person_definition_index = 0;
    bool direct_render_source = false;
    bool render_only = false;
    const wchar_t* binding_source = L"owner";
    void* weapon_entity = nullptr;
    void* weapon_services = nullptr;
    nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind =
        nskinzcs2::runtime::KnifeFirstPersonOwnerKind::None;
};

bool TryResolveKnifeAnimationOwnerCandidate(
    const std::vector<void*>& entity_cache,
    const ClientSchemaOffsets& offsets,
    const int entity_index,
    KnifeAnimationBinding& binding)
{
    if (entity_index < 0 || static_cast<std::size_t>(entity_index) >= entity_cache.size())
    {
        return false;
    }

    void* entity = entity_cache[static_cast<std::size_t>(entity_index)];
    if (entity == nullptr)
    {
        return false;
    }

    void* item_view = ResolveWeaponItemView(entity, offsets);
    if (item_view == nullptr)
    {
        return false;
    }

    binding.first_person_entity_index = entity_index;
    binding.first_person_entity = entity;
    binding.first_person_item_view = item_view;
    return true;
}

bool IsRecoverableKnifeFirstPersonOwnerKind(
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind) noexcept
{
    return owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel;
}

bool ShouldTreatKnifeModelPathFirstPersonBindingAsPersistent(
    const int first_person_entity_index,
    const bool first_person_render_only,
    const bool first_person_direct_render_source,
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind) noexcept
{
    return first_person_entity_index >= 0 &&
        !IsSyntheticRuntimeEntityIndex(first_person_entity_index) &&
        !first_person_render_only &&
        !first_person_direct_render_source &&
        IsRecoverableKnifeFirstPersonOwnerKind(owner_kind);
}

bool IsGuardedKnifeModelPathSyntheticFirstPersonBinding(
    const int first_person_entity_index,
    const bool first_person_render_only,
    const bool first_person_direct_render_source,
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind) noexcept
{
    return IsSyntheticRuntimeEntityIndex(first_person_entity_index) &&
        first_person_render_only &&
        first_person_direct_render_source &&
        IsRecoverableKnifeFirstPersonOwnerKind(owner_kind);
}

bool ShouldTreatKnifeModelPathFirstPersonBindingAsReusable(
    const int first_person_entity_index,
    const bool first_person_render_only,
    const bool first_person_direct_render_source,
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind) noexcept
{
    return ShouldTreatKnifeModelPathFirstPersonBindingAsPersistent(
               first_person_entity_index,
               first_person_render_only,
               first_person_direct_render_source,
               owner_kind) ||
        IsGuardedKnifeModelPathSyntheticFirstPersonBinding(
               first_person_entity_index,
               first_person_render_only,
               first_person_direct_render_source,
               owner_kind);
}

bool IsStickyKnifeFirstPersonRenderSourceEligible(const wchar_t* source) noexcept
{
    if (source == nullptr)
    {
        return false;
    }

    return std::wcscmp(source, L"hud_scene_owner") == 0 ||
        std::wcscmp(source, L"providee_render_child") == 0 ||
        std::wcscmp(source, L"viewmodel_render_child") == 0 ||
        std::wcscmp(source, L"hud_scene_render_child") == 0 ||
        std::wcscmp(source, L"explicit_render_child") == 0 ||
        std::wcscmp(source, L"explicit_render_grandchild") == 0;
}

bool KnifeModelPathStateMatchesCurrentRefreshEpoch(const KnifeModelPathState& state) noexcept
{
    const auto current_refresh_epoch_generation = g_hook_state.knife_refresh_helper_epoch_generation.load();
    return state.refresh_epoch_generation != 0 &&
        current_refresh_epoch_generation != 0 &&
        state.refresh_epoch_generation == current_refresh_epoch_generation;
}

bool ShouldAttemptKnifeModelPathStateRestore(
    const KnifeModelPathState& state,
    const AttributeBindingReleaseMode release_mode) noexcept
{
    if (!state.active ||
        !state.direct_render_rebind_attempted ||
        state.resource_only_render_active)
    {
        return false;
    }

    if (release_mode == AttributeBindingReleaseMode::RestoreOriginal)
    {
        return true;
    }

    const auto has_persistent_first_person_binding =
        ShouldTreatKnifeModelPathFirstPersonBindingAsPersistent(
            state.first_person_entity_index,
            state.first_person_render_only,
            state.first_person_direct_render_source,
            state.owner_kind);
    const auto has_guarded_synthetic_first_person_binding =
        IsGuardedKnifeModelPathSyntheticFirstPersonBinding(
            state.first_person_entity_index,
            state.first_person_render_only,
            state.first_person_direct_render_source,
            state.owner_kind);
    const auto has_first_person_render_target =
        state.first_person_render_entity != nullptr &&
        (IsResolvedRuntimeEntityIndex(state.first_person_render_entity_index) ||
         IsSyntheticRuntimeEntityIndex(state.first_person_render_entity_index));

    return state.world_entity != nullptr &&
        state.world_item_view != nullptr &&
        state.world_render_entity != nullptr &&
        state.first_person_entity != nullptr &&
        has_first_person_render_target &&
        IsResolvedRuntimeEntityIndex(state.world_entity_index) &&
        IsResolvedRuntimeEntityIndex(state.world_render_entity_index) &&
        (IsResolvedRuntimeEntityIndex(state.first_person_entity_index) ||
         IsSyntheticRuntimeEntityIndex(state.first_person_entity_index)) &&
        ((has_persistent_first_person_binding && state.first_person_item_view != nullptr) ||
         has_guarded_synthetic_first_person_binding);
}

void RememberCachedKnifeFirstPersonBinding(
    const std::uint64_t xuid,
    const int world_entity_index,
    const int first_person_entity_index,
    const int first_person_definition_index,
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind) noexcept
{
    if (xuid == 0 ||
        world_entity_index < 0 ||
        first_person_entity_index < 0 ||
        first_person_entity_index == world_entity_index ||
        first_person_definition_index == 0 ||
        !IsRecoverableKnifeFirstPersonOwnerKind(owner_kind))
    {
        return;
    }

    auto& cache = g_hook_state.cached_knife_first_person_binding;
    cache.active = true;
    cache.xuid = xuid;
    cache.world_entity_index = world_entity_index;
    cache.first_person_entity_index = first_person_entity_index;
    cache.first_person_definition_index = first_person_definition_index;
    cache.owner_kind = owner_kind;
}

bool TryResolveKnifeFirstPersonBindingFromSnapshot(
    const bool snapshot_active,
    const std::uint64_t snapshot_xuid,
    const int snapshot_world_entity_index,
    const int snapshot_first_person_entity_index,
    const int snapshot_first_person_definition_index,
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind snapshot_owner_kind,
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int world_weapon_entity_index,
    int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    int& first_person_entity_index,
    void*& first_person_entity,
    void*& first_person_item_view,
    int& first_person_definition_index,
    nskinzcs2::runtime::KnifeFirstPersonOwnerKind& owner_kind)
{
    if (!snapshot_active ||
        snapshot_xuid != xuid ||
        snapshot_world_entity_index != world_weapon_entity_index ||
        snapshot_first_person_entity_index < 0 ||
        snapshot_first_person_entity_index == world_weapon_entity_index ||
        !IsRecoverableKnifeFirstPersonOwnerKind(snapshot_owner_kind))
    {
        return false;
    }

    if (parent_definition_index == 0)
    {
        parent_definition_index = snapshot_first_person_definition_index;
    }
    if (parent_definition_index == 0)
    {
        return false;
    }

    void* entity = nullptr;
    if (static_cast<std::size_t>(snapshot_first_person_entity_index) < entity_cache.size())
    {
        entity = entity_cache[static_cast<std::size_t>(snapshot_first_person_entity_index)];
    }

    if (entity == nullptr &&
        (!TryGetEntityFromIndex(entity_list, snapshot_first_person_entity_index, entity) || entity == nullptr))
    {
        return false;
    }

    const auto item_view = ResolveWeaponItemView(entity, offsets);
    int definition_index = 0;
    if (!IsSafeLinkedWeaponItemView(
            item_view,
            offsets,
            xuid,
            parent_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            definition_index))
    {
        return false;
    }

    first_person_entity_index = snapshot_first_person_entity_index;
    first_person_entity = entity;
    first_person_item_view = item_view;
    first_person_definition_index = definition_index;
    owner_kind = snapshot_owner_kind;
    return true;
}

bool TryResolveCachedKnifeFirstPersonEntity(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int world_weapon_entity_index,
    int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    int& first_person_entity_index,
    void*& first_person_entity,
    void*& first_person_item_view,
    int& first_person_definition_index,
    nskinzcs2::runtime::KnifeFirstPersonOwnerKind& owner_kind)
{
    first_person_entity_index = -1;
    first_person_entity = nullptr;
    first_person_item_view = nullptr;
    first_person_definition_index = 0;

    const auto cached_binding = g_hook_state.cached_knife_first_person_binding;
    if (TryResolveKnifeFirstPersonBindingFromSnapshot(
            cached_binding.active,
            cached_binding.xuid,
            cached_binding.world_entity_index,
            cached_binding.first_person_entity_index,
            cached_binding.first_person_definition_index,
            cached_binding.owner_kind,
            entity_list,
            entity_cache,
            offsets,
            xuid,
            world_weapon_entity_index,
            parent_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            first_person_entity_index,
            first_person_entity,
            first_person_item_view,
            first_person_definition_index,
            owner_kind))
    {
        return true;
    }

    auto state = g_hook_state.knife_model_path_state;
    const auto model_path_parent_definition_index =
        parent_definition_index != 0
        ? parent_definition_index
        : state.original_first_person_definition_index != 0
            ? state.original_first_person_definition_index
            : state.target_definition_index != 0
                ? state.target_definition_index
                : state.original_world_definition_index;
    return TryResolveKnifeFirstPersonBindingFromSnapshot(
        state.active,
        state.xuid,
        state.world_entity_index,
        state.first_person_entity_index,
        model_path_parent_definition_index,
        state.owner_kind,
        entity_list,
        entity_cache,
        offsets,
        xuid,
        world_weapon_entity_index,
        model_path_parent_definition_index,
        known_definition_indices,
        knife_definition_indices,
        glove_definition_indices,
        first_person_entity_index,
        first_person_entity,
        first_person_item_view,
        first_person_definition_index,
        owner_kind);
}

bool TryResolveKnifeAnimationBinding(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    void* weapon_entity,
    const nskinzcs2::runtime::KnifeRuntimeContext& context,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    KnifeAnimationBinding& binding)
{
    binding = {};
    binding.weapon_entity = weapon_entity;

    if (player_binding.pawn_entity == nullptr ||
        !SafeReadField(
            player_binding.pawn_entity,
            offsets.pawn_weapon_services,
            binding.weapon_services) ||
        binding.weapon_services == nullptr)
    {
        return false;
    }

    const auto expected_definition_index =
        context.first_person_source_definition_index != 0
            ? context.first_person_source_definition_index
            : context.live_definition_index;
    const auto effective_owner_state =
        ResolveKnifeEffectiveOwnerBindingState(
            entity_list,
            entity_cache,
            player_binding,
            context.world_entity_index,
            offsets,
            expected_definition_index,
            &context);
    LogKnifeEffectiveOwnerBindingState(
        L"animation binding",
        xuid,
        context.world_entity_index,
        &context,
        effective_owner_state);
    const auto effective_providee_entity_index =
        effective_owner_state.providee_valid
            ? effective_owner_state.providee_entity_index
            : context.providee_entity_index;
    const auto effective_viewmodel_entity_index =
        effective_owner_state.viewmodel_valid
            ? effective_owner_state.viewmodel_entity_index
            : context.viewmodel_entity_index;
    const auto preferred_owner_kind =
        IsRecoverableKnifeFirstPersonOwnerKind(context.first_person_owner_kind)
            ? context.first_person_owner_kind
            : nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel;
    KnifePersistentOwnerResolution direct_render_owner_resolution {};
    if (weapon_entity != nullptr && context.world_entity_index >= 0)
    {
        auto* world_item_view = ResolveWeaponItemView(weapon_entity, offsets);
        if (world_item_view != nullptr)
        {
            TryResolvePersistentKnifeOwnerFromDirectRender(
                entity_list,
                entity_cache,
                player_binding,
                context.world_entity_index,
                weapon_entity,
                world_item_view,
                offsets,
                xuid,
                expected_definition_index,
                known_definition_indices,
                knife_definition_indices,
                glove_definition_indices,
                effective_providee_entity_index,
                effective_viewmodel_entity_index,
                preferred_owner_kind,
                direct_render_owner_resolution);
        }
    }

    const auto validate_animation_owner_model =
        [&](const int entity_index,
            void* entity,
            const wchar_t* binding_source,
            const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind)
        {
            if (entity == nullptr || IsSyntheticRuntimeEntityIndex(entity_index))
            {
                if (ShouldLogWatchedKnifeAnimationTrace(xuid))
                {
                    std::wstringstream stream;
                    stream << L"Knife animation binding rejected synthetic/null owner: owner_kind="
                        << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(owner_kind)
                        << L", binding_source=" << binding_source
                        << L", entity=" << entity_index
                        << L", reason=animation_owner_must_be_real_weapon_owner";
                    nskinzcs2::Logger::Info(stream.str());
                }

                return false;
            }

            if (owner_kind != nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel)
            {
                if (ShouldLogWatchedKnifeAnimationTrace(xuid))
                {
                    std::wstringstream stream;
                    stream << L"Knife animation binding rejected non-viewmodel owner: owner_kind="
                        << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(owner_kind)
                        << L", binding_source=" << binding_source
                        << L", entity=" << entity_index
                        << L", reason=animation_owner_must_be_real_viewmodel";
                    nskinzcs2::Logger::Info(stream.str());
                }

                return false;
            }

            const auto model_kind = ClassifyKnifeFirstPersonRenderableModel(entity, offsets);
            if (model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
            {
                return true;
            }

            if (ShouldLogWatchedKnifeAnimationTrace(xuid))
            {
                std::string model_name;
                TryReadEntityModelNameString(entity, offsets, model_name);

                std::wstringstream stream;
                const auto* model_kind_text =
                    model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike
                    ? L"weapon"
                    : model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike
                        ? L"character"
                        : L"unknown";
                stream << L"Knife animation binding rejected unreadable owner: owner_kind="
                    << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(owner_kind)
                    << L", binding_source=" << binding_source
                    << L", entity=" << entity_index
                    << L", model_kind=" << model_kind_text;
                if (!model_name.empty())
                {
                    stream << L", model_name=" << NarrowToWide(model_name);
                }
                stream << L", reason=animation_owner_must_be_weapon_like_viewmodel";
                nskinzcs2::Logger::Info(stream.str());
            }

            return false;
        };

    const auto finalize_binding =
        [&]()
        {
            if (binding.first_person_item_view != nullptr && binding.first_person_definition_index == 0)
            {
                TryReadItemDefinitionIndex(
                    binding.first_person_item_view,
                    offsets,
                    binding.first_person_definition_index);
            }
            if (binding.first_person_definition_index == 0)
            {
                binding.first_person_definition_index =
                    context.first_person_source_definition_index != 0
                        ? context.first_person_source_definition_index
                        : context.live_definition_index;
            }
            if (!binding.direct_render_source && !binding.render_only)
            {
                RememberCachedKnifeFirstPersonBinding(
                    xuid,
                    context.world_entity_index,
                    binding.first_person_entity_index,
                    binding.first_person_definition_index,
                    binding.owner_kind);
            }
            return true;
        };

    const auto try_direct_render_owner =
        [&]()
        {
            if (!direct_render_owner_resolution.promoted)
            {
                return false;
            }

            KnifeAnimationBinding candidate = binding;
            candidate.owner_kind = direct_render_owner_resolution.owner_kind;
            candidate.first_person_entity_index = direct_render_owner_resolution.owner_entity_index;
            candidate.first_person_entity = direct_render_owner_resolution.owner_entity;
            candidate.first_person_item_view = direct_render_owner_resolution.owner_item_view;
            candidate.first_person_definition_index =
                direct_render_owner_resolution.owner_definition_index != 0
                    ? direct_render_owner_resolution.owner_definition_index
                    : expected_definition_index;
            candidate.direct_render_source = false;
            candidate.render_only = false;
            candidate.binding_source = direct_render_owner_resolution.binding_source;

            if (!validate_animation_owner_model(
                    candidate.first_person_entity_index,
                    candidate.first_person_entity,
                    candidate.binding_source,
                    candidate.owner_kind))
            {
                return false;
            }

            binding = candidate;
            return true;
        };

    const auto finalize_preferring_reacquired_real_owner =
        [&]()
        {
            const auto owner_model_kind =
                ClassifyKnifeFirstPersonRenderableModel(binding.first_person_entity, offsets);
            if (owner_model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike)
            {
                const auto fallback_binding = binding;
                if (try_direct_render_owner())
                {
                    if (ShouldLogWatchedKnifeAnimationTrace(xuid))
                    {
                        std::wstringstream stream;
                        stream << L"Knife animation binding promoted real owner over character owner: "
                            << L"fallback_entity=" << fallback_binding.first_person_entity_index
                            << L", fallback_source=" << fallback_binding.binding_source
                            << L", promoted_entity=" << binding.first_person_entity_index
                            << L", promoted_source=" << binding.binding_source;
                        nskinzcs2::Logger::Info(stream.str());
                    }
                }
                else
                {
                    binding = fallback_binding;
                }
            }

            return finalize_binding();
        };

    const auto try_owner =
        [&](const int entity_index, const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind)
        {
            KnifeAnimationBinding candidate = binding;
            candidate.owner_kind = owner_kind;
            if (!TryResolveKnifeAnimationOwnerCandidate(entity_cache, offsets, entity_index, candidate))
            {
                return false;
            }

            auto resolved_first_person_entity_index = candidate.first_person_entity_index;
            auto* resolved_first_person_entity = candidate.first_person_entity;
            auto* resolved_first_person_item_view = candidate.first_person_item_view;
            auto resolved_first_person_definition_index = candidate.first_person_definition_index;
            if (resolved_first_person_item_view != nullptr)
            {
                TryReadItemDefinitionIndex(
                    resolved_first_person_item_view,
                    offsets,
                    resolved_first_person_definition_index);
            }
            const auto source_model_kind =
                ClassifyKnifeFirstPersonRenderableModel(resolved_first_person_entity, offsets);
            if (source_model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike &&
                expected_definition_index != 0)
            {
                resolved_first_person_definition_index = expected_definition_index;
            }

            candidate.first_person_entity_index = resolved_first_person_entity_index;
            candidate.first_person_entity = resolved_first_person_entity;
            candidate.first_person_item_view = resolved_first_person_item_view;
            candidate.first_person_definition_index = resolved_first_person_definition_index;
            candidate.direct_render_source = false;
            candidate.render_only = false;
            candidate.binding_source =
                owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::Providee
                ? L"providee_owner"
                : L"viewmodel_owner";

            if (!validate_animation_owner_model(
                    candidate.first_person_entity_index,
                    candidate.first_person_entity,
                    candidate.binding_source,
                    candidate.owner_kind))
            {
                return false;
            }

            if (ShouldLogWatchedKnifeAnimationTrace(xuid))
            {
                std::string source_model_name;
                TryReadEntityModelNameString(resolved_first_person_entity, offsets, source_model_name);
                std::wstringstream stream;
                stream << L"Knife animation binding selected real owner: owner_kind="
                    << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(owner_kind)
                    << L", entity=" << candidate.first_person_entity_index
                    << L", definition=" << candidate.first_person_definition_index
                    << L", model_kind="
                    << (source_model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike
                            ? L"weapon"
                            : source_model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike
                                  ? L"character"
                                  : L"unknown");
                if (!source_model_name.empty())
                {
                    stream << L", model_name=" << NarrowToWide(source_model_name);
                }
                nskinzcs2::Logger::Info(stream.str());
            }

            binding = candidate;
            return true;
        };

    if (context.first_person_owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel &&
        try_owner(effective_viewmodel_entity_index, nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel))
    {
        return finalize_preferring_reacquired_real_owner();
    }

    if (try_owner(effective_viewmodel_entity_index, nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel))
    {
        return finalize_preferring_reacquired_real_owner();
    }

    binding.owner_kind = context.first_person_owner_kind;
    if (TryResolveCachedKnifeFirstPersonEntity(
            entity_list,
            entity_cache,
            offsets,
            xuid,
            context.world_entity_index,
            context.first_person_source_definition_index != 0
                ? context.first_person_source_definition_index
                : context.live_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            binding.first_person_entity_index,
            binding.first_person_entity,
            binding.first_person_item_view,
            binding.first_person_definition_index,
            binding.owner_kind))
    {
        if (!validate_animation_owner_model(
                binding.first_person_entity_index,
                binding.first_person_entity,
                L"cached_owner",
                binding.owner_kind))
        {
            return false;
        }

        return finalize_preferring_reacquired_real_owner();
    }

    if (try_direct_render_owner())
    {
        return finalize_binding();
    }

    return false;
}

bool ShouldLogWatchedKnifeAnimationTrace(const std::uint64_t xuid) noexcept
{
    return xuid != 0 &&
        g_hook_state.watched_xuid.load() == xuid &&
        (g_hook_state.runtime_trace_polls_remaining.load() > 0 ||
         g_hook_state.frame_stage_trace_callbacks_remaining.load() > 0);
}

int ResolveKnifeAnimationTraceTargetDefinition(
    const nskinzcs2::runtime::KnifeAppearanceRequest& request,
    const nskinzcs2::runtime::KnifeRuntimeContext& context) noexcept
{
    if (request.model_definition != 0)
    {
        return request.model_definition;
    }

    if (context.first_person_source_definition_index != 0)
    {
        return context.first_person_source_definition_index;
    }

    if (context.world_definition_index != 0)
    {
        return context.world_definition_index;
    }

    return context.live_definition_index;
}

bool ShouldAttemptPassiveWatchedKnifeAnimationTrace(
    const nskinzcs2::runtime::KnifeRuntimeContext& context,
    const std::uint64_t xuid) noexcept
{
    return context.demo_playing &&
        context.schema_ready &&
        context.entity_system_ready &&
        context.watched_target &&
        nskinzcs2::runtime::KnifeRuntimeContextHasAuthoritativeWatchedKnife(context) &&
        xuid != 0 &&
        context.watched_xuid != 0 &&
        xuid == context.watched_xuid;
}

bool TryCaptureKnifeAnimationState(
    const KnifeAnimationBinding& binding,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::KnifeRuntimeContext& context,
    const nskinzcs2::runtime::KnifeAppearanceRequest& request,
    const std::uint64_t xuid,
    const std::uint64_t apply_signature,
    nskinzcs2::runtime::KnifeAnimationStateSnapshot& snapshot)
{
    snapshot = {};

    if (binding.weapon_entity == nullptr ||
        binding.first_person_entity == nullptr ||
        binding.weapon_services == nullptr)
    {
        return false;
    }

    int live_definition_index = binding.first_person_definition_index;
    if ((binding.first_person_item_view == nullptr ||
         !TryReadItemDefinitionIndex(binding.first_person_item_view, offsets, live_definition_index)) &&
        live_definition_index == 0)
    {
        live_definition_index = context.live_definition_index;
    }

    snapshot.xuid = xuid;
    snapshot.apply_signature = apply_signature;
    snapshot.world_entity_index = context.world_entity_index;
    snapshot.first_person_entity_index = binding.first_person_entity_index;
    snapshot.live_definition_index = live_definition_index;
    snapshot.source_definition_index =
        context.first_person_source_definition_index != 0
        ? context.first_person_source_definition_index
        : live_definition_index;
    snapshot.target_definition_index = ResolveKnifeAnimationTraceTargetDefinition(request, context);

    if (!SafeReadField(
            binding.first_person_entity,
            offsets.anim_graph_controller_sequence,
            snapshot.sequence) ||
        !SafeReadField(
            binding.first_person_entity,
            offsets.anim_graph_controller_seq_start_time,
            snapshot.sequence_start_time) ||
        !SafeReadField(
            binding.first_person_entity,
            offsets.anim_graph_controller_networked_sequence_changed,
            snapshot.networked_sequence_changed) ||
        !SafeReadField(
            binding.first_person_entity,
            offsets.anim_graph_controller_sequence_finished,
            snapshot.sequence_finished) ||
        !SafeReadField(
            binding.weapon_entity,
            offsets.weapon_gameplay_anim_state,
            snapshot.gameplay_state) ||
        !SafeReadField(
            binding.weapon_entity,
            offsets.weapon_gameplay_anim_state_timestamp,
            snapshot.gameplay_state_timestamp) ||
        !SafeReadField(
            binding.weapon_entity,
            offsets.weapon_inspect_pending,
            snapshot.inspect_pending) ||
        !SafeReadField(
            binding.weapon_entity,
            offsets.weapon_inspect_should_loop,
            snapshot.inspect_should_loop) ||
        !SafeReadField(
            binding.weapon_services,
            offsets.weapon_services_is_looking_at_weapon,
            snapshot.is_looking_at_weapon) ||
        !SafeReadField(
            binding.weapon_services,
            offsets.weapon_services_is_holding_look_at_weapon,
            snapshot.is_holding_look_at_weapon) ||
        !SafeReadField(
            binding.weapon_services,
            offsets.weapon_services_block_inspect_until_next_graph_update,
            snapshot.block_inspect_until_next_graph_update))
    {
        return false;
    }

    snapshot.valid = true;
    return true;
}

void LogWatchedKnifeAnimationTrace(
    const KnifeAnimationBinding& binding,
    const nskinzcs2::runtime::KnifeAnimationStateSnapshot& snapshot)
{
    if (!ShouldLogWatchedKnifeAnimationTrace(snapshot.xuid))
    {
        return;
    }

    std::wstringstream trace_stream;
    trace_stream << L"Watched knife animation trace: gameplay_state=" << snapshot.gameplay_state
        << L", gameplay_state_timestamp=" << snapshot.gameplay_state_timestamp
        << L", sequence=" << snapshot.sequence
        << L", sequence_finished=" << (snapshot.sequence_finished ? 1 : 0)
        << L", inspect_pending=" << (snapshot.inspect_pending ? 1 : 0)
        << L", inspect_should_loop=" << (snapshot.inspect_should_loop ? 1 : 0)
        << L", is_looking_at_weapon=" << (snapshot.is_looking_at_weapon ? 1 : 0)
        << L", is_holding_look_at_weapon=" << (snapshot.is_holding_look_at_weapon ? 1 : 0)
        << L", xuid=" << snapshot.xuid
        << L", owner_kind=" << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(binding.owner_kind)
        << L", binding_source=" << binding.binding_source
        << L", render_only=" << (binding.render_only ? 1 : 0)
        << L", source_definition=" << snapshot.source_definition_index
        << L", target_definition=" << snapshot.target_definition_index
        << L", first_person_entity=" << snapshot.first_person_entity_index;
    nskinzcs2::Logger::Info(trace_stream.str());
}

bool DidWatchedKnifeAnimationObservationChange(
    const nskinzcs2::runtime::KnifeAnimationStateSnapshot& previous,
    const nskinzcs2::runtime::KnifeAnimationStateSnapshot& current) noexcept
{
    if (!previous.valid)
    {
        return true;
    }

    return previous.gameplay_state != current.gameplay_state ||
        current.gameplay_state_timestamp > previous.gameplay_state_timestamp + 0.000001f ||
        previous.sequence != current.sequence ||
        previous.sequence_finished != current.sequence_finished ||
        previous.inspect_pending != current.inspect_pending ||
        previous.inspect_should_loop != current.inspect_should_loop ||
        previous.is_looking_at_weapon != current.is_looking_at_weapon ||
        previous.is_holding_look_at_weapon != current.is_holding_look_at_weapon ||
        previous.first_person_entity_index != current.first_person_entity_index ||
        previous.source_definition_index != current.source_definition_index ||
        previous.target_definition_index != current.target_definition_index;
}

void RecordWatchedKnifeAnimationObservation(
    const KnifeAnimationBinding& binding,
    const nskinzcs2::runtime::KnifeAnimationStateSnapshot& snapshot)
{
    const auto previous_valid = g_hook_state.last_watched_knife_trace_state_valid;
    const auto previous = g_hook_state.last_watched_knife_trace_state;
    if (!DidWatchedKnifeAnimationObservationChange(previous, snapshot))
    {
        return;
    }

    auto event_kind = L"initial";
    if (previous_valid)
    {
        if (previous.gameplay_state != snapshot.gameplay_state)
        {
            event_kind = L"state-edge";
        }
        else if (snapshot.gameplay_state_timestamp > previous.gameplay_state_timestamp + 0.000001f)
        {
            event_kind = L"timestamp-edge";
        }
        else if (previous.inspect_pending != snapshot.inspect_pending ||
                 previous.inspect_should_loop != snapshot.inspect_should_loop ||
                 previous.is_looking_at_weapon != snapshot.is_looking_at_weapon ||
                 previous.is_holding_look_at_weapon != snapshot.is_holding_look_at_weapon)
        {
            event_kind = L"inspect-edge";
        }
        else
        {
            event_kind = L"state-refresh";
        }
    }

    const auto observation_count = ++g_hook_state.watched_knife_trace_counts[snapshot.gameplay_state];
    const auto trigger =
        nskinzcs2::runtime::DetectKnifeAnimationTrigger(
            {previous_valid, g_hook_state.last_watched_knife_trace_state, snapshot});
    const auto inspect_active = nskinzcs2::runtime::KnifeAnimationInspectActive(snapshot);
    const auto action_hint =
        trigger == nskinzcs2::runtime::KnifeAnimationTrigger::Deploy
            ? L"suspected_deploy"
            : trigger == nskinzcs2::runtime::KnifeAnimationTrigger::Inspect
                ? L"suspected_inspect"
                : trigger == nskinzcs2::runtime::KnifeAnimationTrigger::LightAttack
                    ? L"suspected_light_attack"
                    : trigger == nskinzcs2::runtime::KnifeAnimationTrigger::HeavyAttack
                        ? L"suspected_heavy_attack"
                : inspect_active
                    ? L"inspect_like"
                    : snapshot.gameplay_state == 0
                        ? L"idle_or_post_action"
                        : L"attack_candidate_unmapped";

    std::wstringstream stream;
    stream << L"Watched knife animation event: kind=" << event_kind
        << L", gameplay_state=" << snapshot.gameplay_state
        << L", previous_gameplay_state=" << (previous_valid ? previous.gameplay_state : -1)
        << L", gameplay_state_timestamp=" << snapshot.gameplay_state_timestamp
        << L", previous_gameplay_state_timestamp=" << (previous_valid ? previous.gameplay_state_timestamp : -1.0f)
        << L", sequence=" << snapshot.sequence
        << L", sequence_finished=" << (snapshot.sequence_finished ? 1 : 0)
        << L", inspect_pending=" << (snapshot.inspect_pending ? 1 : 0)
        << L", inspect_should_loop=" << (snapshot.inspect_should_loop ? 1 : 0)
        << L", is_looking_at_weapon=" << (snapshot.is_looking_at_weapon ? 1 : 0)
        << L", is_holding_look_at_weapon=" << (snapshot.is_holding_look_at_weapon ? 1 : 0)
        << L", owner_kind=" << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(binding.owner_kind)
        << L", binding_source=" << binding.binding_source
        << L", render_only=" << (binding.render_only ? 1 : 0)
        << L", source_definition=" << snapshot.source_definition_index
        << L", target_definition=" << snapshot.target_definition_index
        << L", first_person_entity=" << snapshot.first_person_entity_index
        << L", detected_trigger=" << nskinzcs2::runtime::KnifeAnimationTriggerText(trigger)
        << L", inspect_active=" << (inspect_active ? 1 : 0)
        << L", action_hint=" << action_hint
        << L", observation_count=" << observation_count;
    nskinzcs2::Logger::Info(stream.str());

    g_hook_state.last_watched_knife_trace_state_valid = true;
    g_hook_state.last_watched_knife_trace_state = snapshot;
}

bool TryObserveWatchedKnifeAnimationTrace(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    void* weapon_entity,
    const nskinzcs2::runtime::KnifeAppearanceRequest& request,
    const nskinzcs2::runtime::KnifeRuntimeContext& context,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const std::uint64_t apply_signature,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices)
{
    if (!HasKnifeAnimationSchemaOffsets(offsets) ||
        !ShouldAttemptPassiveWatchedKnifeAnimationTrace(context, xuid))
    {
        return false;
    }

    KnifeAnimationBinding binding {};
    if (!TryResolveKnifeAnimationBinding(
            entity_list,
            entity_cache,
            player_binding,
            weapon_entity,
            context,
            offsets,
            xuid,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            binding))
    {
        if (ShouldLogWatchedKnifeAnimationTrace(xuid))
        {
            WarnOnceForRuntimeSignature(
                apply_signature ^ 0x7701ull,
                L"Watched knife animation trace skipped: first-person knife animation owner was not resolved.");
        }
        return false;
    }

    nskinzcs2::runtime::KnifeAnimationStateSnapshot snapshot {};
    if (!TryCaptureKnifeAnimationState(binding, offsets, context, request, xuid, apply_signature, snapshot))
    {
        if (ShouldLogWatchedKnifeAnimationTrace(xuid))
        {
            WarnOnceForRuntimeSignature(
                apply_signature ^ 0x7702ull,
                L"Watched knife animation trace skipped: knife animation fields were not readable from the watched first-person owner.");
        }
        return false;
    }

    RecordWatchedKnifeAnimationObservation(binding, snapshot);
    return true;
}

bool TryApplyKnifeAnimationReset(
    const KnifeAnimationBinding& binding,
    const ClientSchemaOffsets& offsets,
    const bool write_sequence,
    const std::uint32_t sequence,
    const float sequence_start_time)
{
    bool success = true;
    if (write_sequence)
    {
        success = success &&
            SafeWriteField(binding.first_person_entity, offsets.anim_graph_controller_sequence, sequence);
    }

    success = success &&
        SafeWriteField(
            binding.first_person_entity,
            offsets.anim_graph_controller_seq_start_time,
            sequence_start_time) &&
        SafeWriteField(
            binding.first_person_entity,
            offsets.anim_graph_controller_networked_sequence_changed,
            true) &&
        SafeWriteField(
            binding.first_person_entity,
            offsets.anim_graph_controller_sequence_finished,
            false);
    return success;
}

bool TryApplyKnifeDeployRemap(
    const KnifeAnimationBinding& binding,
    const ClientSchemaOffsets& offsets,
    nskinzcs2::runtime::KnifeAnimationStateSnapshot& snapshot)
{
    constexpr std::uint32_t kDeploySequence = 0;
    const auto sequence_start_time =
        snapshot.gameplay_state_timestamp != 0.0f
            ? snapshot.gameplay_state_timestamp
            : snapshot.sequence_start_time;

    bool success =
        TryApplyKnifeAnimationReset(binding, offsets, true, kDeploySequence, sequence_start_time) &&
        SafeWriteField(binding.weapon_entity, offsets.weapon_inspect_pending, false) &&
        SafeWriteField(binding.weapon_entity, offsets.weapon_inspect_should_loop, false) &&
        SafeWriteField(binding.weapon_services, offsets.weapon_services_is_looking_at_weapon, false) &&
        SafeWriteField(binding.weapon_services, offsets.weapon_services_is_holding_look_at_weapon, false) &&
        SafeWriteField(
            binding.weapon_services,
            offsets.weapon_services_block_inspect_until_next_graph_update,
            false);

    if (success)
    {
        snapshot.sequence = kDeploySequence;
        snapshot.sequence_start_time = sequence_start_time;
        snapshot.networked_sequence_changed = true;
        snapshot.sequence_finished = false;
        snapshot.inspect_pending = false;
        snapshot.inspect_should_loop = false;
        snapshot.is_looking_at_weapon = false;
        snapshot.is_holding_look_at_weapon = false;
        snapshot.block_inspect_until_next_graph_update = false;
    }

    return success;
}

bool TryApplyKnifeInspectRemap(
    const KnifeAnimationBinding& binding,
    const ClientSchemaOffsets& offsets,
    nskinzcs2::runtime::KnifeAnimationStateSnapshot& snapshot)
{
    const auto sequence_start_time =
        snapshot.gameplay_state_timestamp != 0.0f
            ? snapshot.gameplay_state_timestamp
            : snapshot.sequence_start_time;
    const auto should_loop = snapshot.inspect_should_loop || snapshot.is_holding_look_at_weapon;

    bool success =
        TryApplyKnifeAnimationReset(binding, offsets, false, snapshot.sequence, sequence_start_time) &&
        SafeWriteField(binding.weapon_entity, offsets.weapon_inspect_pending, true) &&
        SafeWriteField(binding.weapon_entity, offsets.weapon_inspect_should_loop, should_loop) &&
        SafeWriteField(binding.weapon_services, offsets.weapon_services_is_looking_at_weapon, true) &&
        SafeWriteField(binding.weapon_services, offsets.weapon_services_is_holding_look_at_weapon, true) &&
        SafeWriteField(
            binding.weapon_services,
            offsets.weapon_services_block_inspect_until_next_graph_update,
            false);

    if (success)
    {
        snapshot.sequence_start_time = sequence_start_time;
        snapshot.networked_sequence_changed = true;
        snapshot.sequence_finished = false;
        snapshot.inspect_pending = true;
        snapshot.inspect_should_loop = should_loop;
        snapshot.is_looking_at_weapon = true;
        snapshot.is_holding_look_at_weapon = true;
        snapshot.block_inspect_until_next_graph_update = false;
    }

    return success;
}

KnifeAnimationHookOutcome TryProcessKnifeAnimationHook(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    void* weapon_entity,
    const nskinzcs2::runtime::KnifeAppearanceRequest& request,
    const nskinzcs2::runtime::KnifeRuntimeContext& context,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const std::uint64_t apply_signature,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    bool& observed_this_poll)
{
    observed_this_poll = false;

    if (!HasKnifeAnimationSchemaOffsets(offsets) ||
        request.mode != nskinzcs2::runtime::KnifeSlotMode::ModelAndFinish ||
        request.model_definition == 0 ||
        !context.knife_sync_ready ||
        xuid != context.watched_xuid ||
        context.first_person_source_definition_index == 0 ||
        context.first_person_source_definition_index == request.model_definition)
    {
        return KnifeAnimationHookOutcome::Skipped;
    }

    KnifeAnimationBinding binding {};
    if (!TryResolveKnifeAnimationBinding(
            entity_list,
            entity_cache,
            player_binding,
            weapon_entity,
            context,
            offsets,
            xuid,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            binding))
    {
        WarnOnceForRuntimeSignature(
            apply_signature ^ 0x7701ull,
            L"Knife animation hook skipped: first-person knife animation owner was not resolved.");
        return KnifeAnimationHookOutcome::Skipped;
    }

    nskinzcs2::runtime::KnifeAnimationStateSnapshot snapshot {};
    if (!TryCaptureKnifeAnimationState(binding, offsets, context, request, xuid, apply_signature, snapshot))
    {
        WarnOnceForRuntimeSignature(
            apply_signature ^ 0x7702ull,
            L"Knife animation hook skipped: knife animation fields were not readable from the watched first-person owner.");
        return KnifeAnimationHookOutcome::Skipped;
    }

    observed_this_poll = true;
    LogWatchedKnifeAnimationTrace(binding, snapshot);

    if (!nskinzcs2::runtime::KnifeAnimationGameplayStateKnown(snapshot))
    {
        if (context.attack_classifier_ready)
        {
            WarnOnceForRuntimeSignature(
                apply_signature ^ 0x7703ull,
                L"Knife animation attack state unknown; model path degraded to finish-only.");
            ResetKnifeAnimationStateSnapshot();
            return KnifeAnimationHookOutcome::UnknownAttackState;
        }

        LogProfileDiagnosticOnce(
            apply_signature ^ 0x7703ull,
            L"Knife attack classifier is not calibrated yet; keeping the model path active while attack remap stays disabled.");
    }

    const auto trigger =
        nskinzcs2::runtime::DetectKnifeAnimationTrigger(
            {g_hook_state.last_knife_animation_state_valid, g_hook_state.last_knife_animation_state, snapshot});

    if ((trigger == nskinzcs2::runtime::KnifeAnimationTrigger::LightAttack ||
         trigger == nskinzcs2::runtime::KnifeAnimationTrigger::HeavyAttack) &&
        !context.attack_classifier_ready)
    {
        g_hook_state.last_knife_animation_state = snapshot;
        g_hook_state.last_knife_animation_state_valid = true;
        return KnifeAnimationHookOutcome::ObservedNoTrigger;
    }

    nskinzcs2::runtime::KnifeRemapActionKind remap_action_kind {};
    if (TryMapKnifeTriggerToRemapAction(trigger, remap_action_kind) &&
        !nskinzcs2::runtime::KnifeAnimationRemapTableSupportsTransition(
            snapshot.source_definition_index,
            snapshot.target_definition_index,
            remap_action_kind))
    {
        std::wstringstream stream;
        stream << L"Knife animation " << nskinzcs2::runtime::KnifeAnimationTriggerText(trigger)
            << L" remap skipped: unsupported knife transition source="
            << snapshot.source_definition_index
            << L", target=" << snapshot.target_definition_index
            << L". Keeping the model path active without animation remap.";
        WarnOnceForRuntimeSignature(apply_signature ^ 0x7704ull, stream.str());
        g_hook_state.last_knife_animation_state = snapshot;
        g_hook_state.last_knife_animation_state_valid = true;
        return KnifeAnimationHookOutcome::ObservedNoTrigger;
    }

    bool applied = false;
    if (trigger == nskinzcs2::runtime::KnifeAnimationTrigger::Deploy)
    {
        applied = TryApplyKnifeDeployRemap(binding, offsets, snapshot);
    }
    else if (trigger == nskinzcs2::runtime::KnifeAnimationTrigger::Inspect)
    {
        applied = TryApplyKnifeInspectRemap(binding, offsets, snapshot);
    }
    else if (trigger == nskinzcs2::runtime::KnifeAnimationTrigger::LightAttack ||
             trigger == nskinzcs2::runtime::KnifeAnimationTrigger::HeavyAttack)
    {
        bool success =
            SafeWriteField(
                binding.weapon_entity,
                offsets.weapon_gameplay_anim_state,
                snapshot.gameplay_state) &&
            SafeWriteField(
                binding.weapon_entity,
                offsets.weapon_gameplay_anim_state_timestamp,
                snapshot.gameplay_state_timestamp) &&
            SafeWriteField(
                binding.first_person_entity,
                offsets.anim_graph_controller_networked_sequence_changed,
                true) &&
            SafeWriteField(
                binding.first_person_entity,
                offsets.anim_graph_controller_sequence_finished,
                false) &&
            SafeWriteField(binding.weapon_entity, offsets.weapon_inspect_pending, false) &&
            SafeWriteField(binding.weapon_entity, offsets.weapon_inspect_should_loop, false) &&
            SafeWriteField(binding.weapon_services, offsets.weapon_services_is_looking_at_weapon, false) &&
            SafeWriteField(binding.weapon_services, offsets.weapon_services_is_holding_look_at_weapon, false) &&
            SafeWriteField(
                binding.weapon_services,
                offsets.weapon_services_block_inspect_until_next_graph_update,
                false);
        if (success)
        {
            snapshot.networked_sequence_changed = true;
            snapshot.sequence_finished = false;
            snapshot.inspect_pending = false;
            snapshot.inspect_should_loop = false;
            snapshot.is_looking_at_weapon = false;
            snapshot.is_holding_look_at_weapon = false;
            snapshot.block_inspect_until_next_graph_update = false;
        }
        applied = success;
    }

    g_hook_state.last_knife_animation_state = snapshot;
    g_hook_state.last_knife_animation_state_valid = true;

    if (applied)
    {
        std::wstringstream stream;
        stream << L"Knife animation " << nskinzcs2::runtime::KnifeAnimationTriggerText(trigger)
            << L" remap engaged for XUID " << xuid
            << L": owner=" << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(binding.owner_kind)
            << L", binding_source=" << binding.binding_source
            << L", render_only=" << (binding.render_only ? 1 : 0)
            << L", source_definition=" << context.first_person_source_definition_index
            << L", target_definition=" << request.model_definition
            << L", first_person_entity=" << binding.first_person_entity_index;
        std::uint64_t trigger_suffix = 0x7720ull;
        if (trigger == nskinzcs2::runtime::KnifeAnimationTrigger::Deploy)
        {
            trigger_suffix = 0x7710ull;
        }
        else if (trigger == nskinzcs2::runtime::KnifeAnimationTrigger::LightAttack)
        {
            trigger_suffix = 0x7730ull;
        }
        else if (trigger == nskinzcs2::runtime::KnifeAnimationTrigger::HeavyAttack)
        {
            trigger_suffix = 0x7740ull;
        }
        LogProfileDiagnosticOnce(apply_signature ^ trigger_suffix, stream.str());
        return KnifeAnimationHookOutcome::Applied;
    }

    return KnifeAnimationHookOutcome::ObservedNoTrigger;
}

int ResolveDynamicEntityScanUpperBound(void* entity_list, std::wstring& issue)
{
    issue.clear();

    const auto previous_highest = std::max(g_hook_state.runtime_entities.highest_live_entity_index, 0);
    const auto minimum_scan_limit = std::min(kMaxEntityIndex, std::max(4096, previous_highest + 256));
    constexpr int kConsecutiveNullThreshold = 768;
    constexpr int kTailMargin = 256;

    int highest_live_entity_index = -1;
    int consecutive_nulls = 0;

    for (int entity_index = 0; entity_index <= kMaxEntityIndex; ++entity_index)
    {
        void* entity = nullptr;
        if (!TryGetEntityFromIndex(entity_list, entity_index, entity))
        {
            issue = L"GetEntityFromIndex raised an exception while probing the live entity ceiling.";
            return -1;
        }

        if (entity != nullptr)
        {
            highest_live_entity_index = entity_index;
            consecutive_nulls = 0;
        }
        else if (entity_index >= minimum_scan_limit)
        {
            ++consecutive_nulls;
            if (highest_live_entity_index >= 0 &&
                entity_index > highest_live_entity_index + kTailMargin &&
                consecutive_nulls >= kConsecutiveNullThreshold)
            {
                break;
            }
        }
    }

    return highest_live_entity_index;
}

std::uint64_t ResolveWatchedXuid(
    void* entity_list,
    const std::unordered_map<int, std::uint64_t>& pawn_xuids,
    const std::unordered_map<std::uint32_t, std::uint64_t>& target_xuids_by_account,
    const std::vector<void*>& entity_cache,
    const std::unordered_set<int>& knife_definition_indices,
    const std::uint64_t preferred_target_xuid,
    const ClientSchemaOffsets& offsets)
{
    static_cast<void>(entity_list);
    static_cast<void>(knife_definition_indices);

    if (entity_list == nullptr ||
        offsets.pawn_hud_model_arms == 0 ||
        offsets.pawn_weapon_services == 0 ||
        offsets.weapon_services_active_weapon == 0)
    {
        return 0;
    }

    if (preferred_target_xuid != 0)
    {
        for (const auto& [pawn_entity_index, xuid] : pawn_xuids)
        {
            if (xuid != preferred_target_xuid ||
                pawn_entity_index < 0 ||
                pawn_entity_index >= static_cast<int>(entity_cache.size()))
            {
                continue;
            }

            if (entity_cache[static_cast<std::size_t>(pawn_entity_index)] != nullptr)
            {
                return preferred_target_xuid;
            }
        }
    }

    struct WatchedPawnCandidate
    {
        int pawn_entity_index = -1;
        std::uint64_t xuid = 0;
        int score = -1;
    };

    std::vector<std::pair<int, std::uint64_t>> sorted_pawns;
    sorted_pawns.reserve(pawn_xuids.size());
    for (const auto& entry : pawn_xuids)
    {
        sorted_pawns.push_back(entry);
    }
    std::sort(
        sorted_pawns.begin(),
        sorted_pawns.end(),
        [](const auto& lhs, const auto& rhs)
        {
            return lhs.first < rhs.first;
        });

    const auto last_watched_xuid = g_hook_state.runtime_entities.last_watched_xuid;
    WatchedPawnCandidate best_candidate {};
    bool last_watched_candidate_still_valid = false;

    auto candidate_is_better =
        [last_watched_xuid](const WatchedPawnCandidate& candidate, const WatchedPawnCandidate& best)
        {
            if (best.xuid == 0)
            {
                return true;
            }

            if (candidate.score != best.score)
            {
                return candidate.score > best.score;
            }

            if (candidate.xuid == last_watched_xuid && best.xuid != last_watched_xuid)
            {
                return true;
            }

            if (candidate.xuid != last_watched_xuid && best.xuid == last_watched_xuid)
            {
                return false;
            }

            return candidate.pawn_entity_index < best.pawn_entity_index;
        };

    auto is_last_watched_candidate_still_valid =
        [last_watched_xuid](const std::uint64_t xuid)
        {
            return last_watched_xuid != 0 && xuid == last_watched_xuid;
        };

    for (const auto& [pawn_entity_index, xuid] : sorted_pawns)
    {
        if (xuid == 0 ||
            pawn_entity_index < 0 ||
            pawn_entity_index >= static_cast<int>(entity_cache.size()))
        {
            continue;
        }

        void* pawn_entity = entity_cache[static_cast<std::size_t>(pawn_entity_index)];
        if (pawn_entity == nullptr)
        {
            continue;
        }

        std::uint32_t hud_model_arms_handle = kInvalidEntityHandle;
        if (!SafeReadField(pawn_entity, offsets.pawn_hud_model_arms, hud_model_arms_handle) ||
            HandleToEntityIndex(hud_model_arms_handle) < 0)
        {
            continue;
        }

        void* weapon_services = nullptr;
        if (!SafeReadField(pawn_entity, offsets.pawn_weapon_services, weapon_services) || weapon_services == nullptr)
        {
            continue;
        }

        std::uint32_t active_weapon_handle = kInvalidEntityHandle;
        if (!SafeReadField(weapon_services, offsets.weapon_services_active_weapon, active_weapon_handle))
        {
            continue;
        }

        const auto active_weapon_entity_index = HandleToEntityIndex(active_weapon_handle);
        if (active_weapon_entity_index < 0 ||
            active_weapon_entity_index >= static_cast<int>(entity_cache.size()))
        {
            continue;
        }

        void* active_weapon_entity = entity_cache[static_cast<std::size_t>(active_weapon_entity_index)];
        if (active_weapon_entity == nullptr)
        {
            continue;
        }

        RuntimePlayerBinding player_binding {};
        player_binding.xuid = xuid;
        player_binding.pawn_entity_index = pawn_entity_index;
        player_binding.pawn_entity = pawn_entity;
        player_binding.active_weapon_handle = active_weapon_handle;
        player_binding.active_weapon_entity_index = active_weapon_entity_index;

        int hud_weapon_entity_index = -1;
        void* hud_weapon_entity = nullptr;
        const auto exact_hud_match =
            TryResolveHudWeaponEntity(
                entity_list,
                entity_cache,
                player_binding,
                active_weapon_entity_index,
                offsets,
                hud_weapon_entity_index,
                hud_weapon_entity);
        const auto render_hud_match =
            exact_hud_match ||
            TryResolveHudWeaponRenderEntity(
                entity_list,
                entity_cache,
                player_binding,
                active_weapon_entity_index,
                offsets,
                hud_weapon_entity_index,
                hud_weapon_entity);

        bool owner_xuid_matches = false;
        if (offsets.econ_entity_original_owner_xuid_low != 0 ||
            offsets.econ_entity_original_owner_xuid_high != 0)
        {
            std::uint32_t owner_xuid_low = 0;
            std::uint32_t owner_xuid_high = 0;
            const auto has_owner_xuid_low =
                offsets.econ_entity_original_owner_xuid_low != 0 &&
                SafeReadField(active_weapon_entity, offsets.econ_entity_original_owner_xuid_low, owner_xuid_low);
            const auto has_owner_xuid_high =
                offsets.econ_entity_original_owner_xuid_high != 0 &&
                SafeReadField(active_weapon_entity, offsets.econ_entity_original_owner_xuid_high, owner_xuid_high);
            owner_xuid_matches =
                (has_owner_xuid_low || has_owner_xuid_high) &&
                (owner_xuid_low != 0 || owner_xuid_high != 0) &&
                CombineXuidParts(owner_xuid_low, owner_xuid_high) == xuid;
        }

        const auto active_weapon_item_view = ResolveWeaponItemView(active_weapon_entity, offsets);
        bool account_matches_xuid = false;
        if (active_weapon_item_view != nullptr && offsets.item_view_account_id != 0)
        {
            std::uint32_t account_id = 0;
            account_matches_xuid =
                SafeReadField(active_weapon_item_view, offsets.item_view_account_id, account_id) &&
                account_id != 0 &&
                account_id == AccountIdFromXuid(xuid);
        }

        std::uint64_t resolved_target_xuid = 0;
        const auto has_resolved_target_xuid =
            TryResolveTargetXuidForWeaponEntity(
                active_weapon_entity,
                active_weapon_item_view,
                offsets,
                pawn_xuids,
                target_xuids_by_account,
                resolved_target_xuid) &&
            LooksLikeSteamXuid(resolved_target_xuid);
        bool viewmodel_attachment_valid = false;
        if (offsets.econ_entity_viewmodel_attachment != 0)
        {
            std::uint32_t viewmodel_handle = kInvalidEntityHandle;
            viewmodel_attachment_valid =
                SafeReadField(active_weapon_entity, offsets.econ_entity_viewmodel_attachment, viewmodel_handle) &&
                HandleToEntityIndex(viewmodel_handle) >= 0;
        }

        bool providee_attachment_valid = false;
        if (offsets.econ_entity_old_providee != 0)
        {
            std::uint32_t providee_handle = kInvalidEntityHandle;
            providee_attachment_valid =
                SafeReadField(active_weapon_entity, offsets.econ_entity_old_providee, providee_handle) &&
                HandleToEntityIndex(providee_handle) >= 0;
        }

        const auto has_strong_first_person_evidence =
            exact_hud_match ||
            render_hud_match ||
            owner_xuid_matches ||
            account_matches_xuid ||
            viewmodel_attachment_valid ||
            providee_attachment_valid;
        if (!has_strong_first_person_evidence)
        {
            last_watched_candidate_still_valid =
                last_watched_candidate_still_valid || is_last_watched_candidate_still_valid(xuid);
            continue;
        }

        WatchedPawnCandidate candidate;
        candidate.pawn_entity_index = pawn_entity_index;
        candidate.xuid = xuid;
        candidate.score =
            (exact_hud_match ? 64 : 0) +
            (exact_hud_match ? 0 : (render_hud_match ? 32 : 0)) +
            (has_resolved_target_xuid && resolved_target_xuid == xuid ? 16 : 0) +
            (owner_xuid_matches ? 16 : 0) +
            (account_matches_xuid ? 8 : 0) +
            (viewmodel_attachment_valid ? 4 : 0) +
            (providee_attachment_valid ? 2 : 0) +
            1;

        if (candidate_is_better(candidate, best_candidate))
        {
            best_candidate = candidate;
        }
    }

    if (best_candidate.xuid != 0)
    {
        return best_candidate.xuid;
    }

    return last_watched_candidate_still_valid ? last_watched_xuid : 0;
}

std::uint64_t ResolvePreferredKnifeTargetXuid(
    const nskinzcs2::model::ConfigDocument& config,
    const std::unordered_map<int, std::uint64_t>& pawn_xuids) noexcept
{
    std::uint64_t preferred_xuid = 0;
    for (const auto& profile : config.knife_profiles)
    {
        if (!profile.enabled || profile.xuid == 0)
        {
            continue;
        }

        if (preferred_xuid == 0)
        {
            preferred_xuid = profile.xuid;
            continue;
        }

        if (preferred_xuid != profile.xuid)
        {
            return 0;
        }
    }

    if (preferred_xuid == 0)
    {
        return 0;
    }

    for (const auto& [pawn_entity_index, xuid] : pawn_xuids)
    {
        static_cast<void>(pawn_entity_index);
        if (xuid == preferred_xuid)
        {
            return preferred_xuid;
        }
    }

    return 0;
}

bool HasAppliedSignature(
    const std::unordered_map<int, std::uint64_t>& applied_signatures,
    const int entity_index,
    const std::uint64_t signature)
{
    const auto it = applied_signatures.find(entity_index);
    return it != applied_signatures.end() && it->second == signature;
}

void RememberAppliedSignature(
    std::unordered_map<int, std::uint64_t>& applied_signatures,
    const int entity_index,
    const std::uint64_t signature)
{
    applied_signatures[entity_index] = signature;
}

float ReadAttributeValueOrDefault(
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint16_t attribute_definition_index,
    const float default_value);

std::wstring BuildWeaponApplyReadback(
    void* econ_entity,
    void* item_view,
    const ClientSchemaOffsets& offsets)
{
    std::wstringstream stream;
    stream << L"def=";

    int definition_index = 0;
    if (TryReadItemDefinitionIndex(item_view, offsets, definition_index))
    {
        stream << definition_index;
    }
    else
    {
        stream << L"?";
    }

    if (offsets.item_view_item_id_high != 0)
    {
        std::uint32_t item_id_high = 0;
        stream << L", high=";
        if (SafeReadField(item_view, offsets.item_view_item_id_high, item_id_high))
        {
            stream << item_id_high;
        }
        else
        {
            stream << L"?";
        }
    }

    if (offsets.item_view_item_id_low != 0)
    {
        std::uint32_t item_id_low = 0;
        stream << L", low=";
        if (SafeReadField(item_view, offsets.item_view_item_id_low, item_id_low))
        {
            stream << item_id_low;
        }
        else
        {
            stream << L"?";
        }
    }

    if (offsets.item_view_account_id != 0)
    {
        std::uint32_t account_id = 0;
        stream << L", account=";
        if (SafeReadField(item_view, offsets.item_view_account_id, account_id))
        {
            stream << account_id;
        }
        else
        {
            stream << L"?";
        }
    }

    if (offsets.item_view_initialized != 0)
    {
        bool initialized = false;
        stream << L", item_init=";
        if (SafeReadField(item_view, offsets.item_view_initialized, initialized))
        {
            stream << (initialized ? 1 : 0);
        }
        else
        {
            stream << L"?";
        }
    }

    if (offsets.item_view_disallow_soc != 0)
    {
        bool disallow_soc = false;
        stream << L", disallow_soc=";
        if (SafeReadField(item_view, offsets.item_view_disallow_soc, disallow_soc))
        {
            stream << (disallow_soc ? 1 : 0);
        }
        else
        {
            stream << L"?";
        }
    }

    if (offsets.item_view_restore_custom_material_after_precache != 0)
    {
        bool restore_custom_material = false;
        stream << L", restore_custom_material=";
        if (SafeReadField(
                item_view,
                offsets.item_view_restore_custom_material_after_precache,
                restore_custom_material))
        {
            stream << (restore_custom_material ? 1 : 0);
        }
        else
        {
            stream << L"?";
        }
    }

    auto* attribute_container = ResolveWeaponAttributeContainer(econ_entity, offsets);
    if (attribute_container != nullptr &&
        offsets.attribute_container_external_item_provider_registered_token != 0)
    {
        std::uint32_t provider_token = 0;
        stream << L", provider_token=";
        if (SafeReadField(
                attribute_container,
                offsets.attribute_container_external_item_provider_registered_token,
                provider_token))
        {
            stream << provider_token;
        }
        else
        {
            stream << L"?";
        }
    }

    if (attribute_container != nullptr &&
        offsets.attribute_container_registered_as_item_id != 0)
    {
        std::uint64_t registered_item_id = 0;
        stream << L", registered_item_id=";
        if (SafeReadField(
                attribute_container,
                offsets.attribute_container_registered_as_item_id,
                registered_item_id))
        {
            stream << registered_item_id;
        }
        else
        {
            stream << L"?";
        }
    }

    if (offsets.econ_entity_initialized != 0 && econ_entity != nullptr)
    {
        bool initialized = false;
        stream << L", entity_init=";
        if (SafeReadField(econ_entity, offsets.econ_entity_initialized, initialized))
        {
            stream << (initialized ? 1 : 0);
        }
        else
        {
            stream << L"?";
        }
    }

    if (econ_entity != nullptr)
    {
        int fallback_paint_kit = 0;
        int fallback_seed = 0;
        int fallback_stat_trak = 0;
        float fallback_wear = 0.0f;

        stream << L", fallback_paint=";
        if (SafeReadField(econ_entity, offsets.econ_entity_fallback_paint_kit, fallback_paint_kit))
        {
            stream << fallback_paint_kit;
        }
        else
        {
            stream << L"?";
        }

        stream << L", fallback_seed=";
        if (SafeReadField(econ_entity, offsets.econ_entity_fallback_seed, fallback_seed))
        {
            stream << fallback_seed;
        }
        else
        {
            stream << L"?";
        }

        stream << L", fallback_wear=";
        if (SafeReadField(econ_entity, offsets.econ_entity_fallback_wear, fallback_wear))
        {
            stream << fallback_wear;
        }
        else
        {
            stream << L"?";
        }

        stream << L", fallback_stattrak=";
        if (SafeReadField(econ_entity, offsets.econ_entity_fallback_stat_trak, fallback_stat_trak))
        {
            stream << fallback_stat_trak;
        }
        else
        {
            stream << L"?";
        }
    }

    stream << L", attr_paint=" << ReadAttributeValueOrDefault(item_view, offsets, kAttributePaintKit, -1.0f)
        << L", attr_seed=" << ReadAttributeValueOrDefault(item_view, offsets, kAttributeSeed, -1.0f)
        << L", attr_wear=" << ReadAttributeValueOrDefault(item_view, offsets, kAttributeWear, -1.0f)
        << L", attr_stattrak=" << ReadAttributeValueOrDefault(item_view, offsets, kAttributeStatTrak, -1.0f);

    if (econ_entity != nullptr &&
        offsets.base_entity_game_scene_node != 0 &&
        offsets.skeleton_instance_model_state != 0 &&
        offsets.model_state_mesh_group_mask != 0)
    {
        stream << L", mesh_mask=";
        void* game_scene_node = nullptr;
        std::uint64_t mesh_group_mask = 0;
        if (SafeReadField(econ_entity, offsets.base_entity_game_scene_node, game_scene_node) &&
            game_scene_node != nullptr &&
            SafeReadValue(
                reinterpret_cast<std::uint8_t*>(game_scene_node) +
                    offsets.skeleton_instance_model_state +
                    offsets.model_state_mesh_group_mask,
                mesh_group_mask))
        {
            stream << mesh_group_mask;
        }
        else
        {
            stream << L"?";
        }
    }

    return stream.str();
}

