bool TryInstallKnifeModelResourceOverrideGlobalDetours()
{
    return false;

    auto& state = g_hook_state.knife_model_resource_override;
    const auto already_installed =
        state.global_target_count > 0 &&
        std::any_of(
            state.global_targets.begin(),
            state.global_targets.end(),
            [](const KnifeModelResourceOverrideGlobalDetourTarget& target)
            {
                return target.installed;
            });
    if (already_installed)
    {
        state.phase = KnifeModelResourceOverridePhase::GlobalDetour;
        return true;
    }

    state.global_targets = {};
    g_hook_state.original_knife_model_resource_global_detours = {};
    state.global_target_count = 0;

    if (!state.active || !EnsureMinHookInitializedForKnifeResourceOverride())
    {
        state.phase = KnifeModelResourceOverridePhase::GlobalDetour;
        return false;
    }

    std::unordered_set<void*> seen_function_starts;
    for (std::size_t index = 0; index < kKnifeModelResourceOverrideProbeSlotCount; ++index)
    {
        const auto& probe_state = state.probe_slots[index];
        if (!probe_state.candidate_valid || probe_state.candidate.function_start == nullptr)
        {
            continue;
        }

        if (!seen_function_starts.insert(probe_state.candidate.function_start).second)
        {
            continue;
        }

        auto& target = state.global_targets[state.global_target_count];
        target.valid = true;
        target.source_slot_index = probe_state.slot_index;
        target.target = probe_state.candidate.function_start;
        target.method = probe_state.candidate.method;
        target.function_start = probe_state.candidate.function_start;

        void* original = nullptr;
        const auto detour =
            reinterpret_cast<void*>(GetKnifeModelResourceOverrideGlobalWrapper(state.global_target_count));
        const auto create_status = MH_CreateHook(target.target, detour, &original);
        if (create_status != MH_OK)
        {
            std::wstringstream stream;
            stream << L"Knife resource override global detour create failed for XUID "
                << state.xuid
                << L": slot=" << target.source_slot_index
                << L", function=" << FormatPointer(target.function_start)
                << L", status=" << static_cast<int>(create_status);
            nskinzcs2::Logger::Warn(stream.str());
            target = {};
            continue;
        }

        const auto enable_status = MH_EnableHook(target.target);
        if (enable_status != MH_OK && enable_status != MH_ERROR_ENABLED)
        {
            MH_RemoveHook(target.target);
            std::wstringstream stream;
            stream << L"Knife resource override global detour enable failed for XUID "
                << state.xuid
                << L": slot=" << target.source_slot_index
                << L", function=" << FormatPointer(target.function_start)
                << L", status=" << static_cast<int>(enable_status);
            nskinzcs2::Logger::Warn(stream.str());
            target = {};
            continue;
        }

        g_hook_state.original_knife_model_resource_global_detours[state.global_target_count] =
            reinterpret_cast<HookState::KnifeModelResourceOverrideFn>(original);
        target.installed = true;
        ++state.global_target_count;
    }

    state.phase = KnifeModelResourceOverridePhase::GlobalDetour;
    state.phase_frames_without_hit = 0;
    state.global_detour_frames_without_call = 0;
    state.global_detour_frames_without_valid_resource = 0;

    if (ShouldLogWatchedKnifeAnimationTrace(state.xuid))
    {
        std::wstringstream stream;
        stream << L"Knife resource override global detours "
            << (state.global_target_count > 0 ? L"installed" : L"empty")
            << L" for XUID " << state.xuid
            << L": count=" << state.global_target_count;
        for (std::size_t index = 0; index < state.global_target_count; ++index)
        {
            const auto& target = state.global_targets[index];
            stream << L" | {slot=" << target.source_slot_index
                << L", function=" << FormatPointer(target.function_start)
                << L", method=" << FormatPointer(target.method)
                << L", installed=" << (target.installed ? 1 : 0) << L"}";
        }
        nskinzcs2::Logger::Info(stream.str());
    }

    return state.global_target_count > 0;
}

void AdvanceKnifeModelResourceOverridePhaseBeforeOriginal()
{
    auto& state = g_hook_state.knife_model_resource_override;
    if (!state.active || state.phase == KnifeModelResourceOverridePhase::None)
    {
        return;
    }

    const auto any_probe_hit =
        std::any_of(
            state.probe_slots.begin(),
            state.probe_slots.end(),
            [](const KnifeModelResourceOverrideProbeSlotState& probe_state)
            {
                return probe_state.hit_count > 0;
            });
    const auto any_meaningful_probe_hit =
        std::any_of(
            state.probe_slots.begin(),
            state.probe_slots.end(),
            [](const KnifeModelResourceOverrideProbeSlotState& probe_state)
            {
                return HasMeaningfulKnifeModelResourceOverrideHit(probe_state);
            });
    const auto any_meaningful_global_hit =
        std::any_of(
            state.global_targets.begin(),
            state.global_targets.end(),
            [](const KnifeModelResourceOverrideGlobalDetourTarget& target)
            {
                return HasMeaningfulKnifeModelResourceOverrideHit(target);
            });
    const auto any_global_call =
        std::any_of(
            state.global_targets.begin(),
            state.global_targets.end(),
            [](const KnifeModelResourceOverrideGlobalDetourTarget& target)
            {
                return target.hit_count > 0;
            });
    if (any_meaningful_probe_hit || any_meaningful_global_hit)
    {
        return;
    }

    if (state.phase == KnifeModelResourceOverridePhase::GlobalDetour)
    {
        state.phase_frames_without_hit += 1;
        state.global_detour_frames_without_call += any_global_call ? 0 : 1;
        state.global_detour_frames_without_valid_resource += 1;

        const auto should_log_watchdog =
            ShouldLogWatchedKnifeAnimationTrace(state.xuid) &&
            (state.global_detour_frames_without_valid_resource <= 5 ||
             state.global_detour_frames_without_valid_resource % 15 == 0);
        if (should_log_watchdog)
        {
            std::wstringstream stream;
            stream << L"Knife resource override global detour watchdog for XUID "
                << state.xuid
                << L": status=" << (any_global_call ? L"non_resource_traffic_only" : L"silent")
                << L", silent_frames=" << state.global_detour_frames_without_call
                << L", no_valid_resource_frames=" << state.global_detour_frames_without_valid_resource
                << L", target_count=" << state.global_target_count
                << L", observed_slot_mask=" << state.observed_slot_mask;
            for (const auto& target : state.global_targets)
            {
                if (!target.valid)
                {
                    continue;
                }

                stream << L" | {slot=" << target.source_slot_index
                    << L", hits=" << target.hit_count
                    << L", resource_hits=" << target.valid_resource_hit_count
                    << L", knife_hits=" << target.knife_model_hit_count
                    << L", overrides=" << target.override_hit_count
                    << L", exact=" << target.exact_apply_success_count
                    << L", last_path_arg=" << target.last_path_argument_index
                    << L"}";
            }
            nskinzcs2::Logger::Info(stream.str());
        }

        if (state.global_detour_frames_without_valid_resource >=
                kKnifeModelResourceOverrideGlobalFallbackFrames &&
            !state.no_resource_bind_entry_observed_logged)
        {
            state.no_resource_bind_entry_observed_logged = true;

            if (ShouldLogWatchedKnifeAnimationTrace(state.xuid))
            {
                std::wstringstream stream;
                stream << L"Knife resource override no_resource_bind_entry_observed for XUID "
                    << state.xuid
                    << L": phase=" << KnifeModelResourceOverridePhaseText(state.phase)
                    << L", render_entity=" << state.render_entity_index
                    << L", world_entity=" << state.world_render_entity_index
                    << L", observed_slot_mask=" << state.observed_slot_mask
                    << L", global_target_count=" << state.global_target_count
                    << L", silent_frames=" << state.global_detour_frames_without_call
                    << L", no_valid_resource_frames="
                    << state.global_detour_frames_without_valid_resource;
                nskinzcs2::Logger::Info(stream.str());
            }
        }

        return;
    }

    state.phase_frames_without_hit += 1;
    if (state.phase == KnifeModelResourceOverridePhase::MultiSlotTriage &&
        state.phase_frames_without_hit >= kKnifeModelResourceOverrideProbeFallbackFrames)
    {
        if (!kKnifeModelResourceOverrideEnableGlobalDetours)
        {
            return;
        }

        if (any_probe_hit && ShouldLogWatchedKnifeAnimationTrace(state.xuid))
        {
            std::wstringstream stream;
            stream << L"Knife resource override escalating to global detour after non-resource probe hits for XUID "
                << state.xuid
                << L": observed_slot_mask=" << state.observed_slot_mask;
            for (const auto& probe_state : state.probe_slots)
            {
                if (probe_state.hit_count <= 0)
                {
                    continue;
                }

                stream << L" | {slot=" << probe_state.slot_index
                    << L", hits=" << probe_state.hit_count
                    << L", resource_hits=" << probe_state.valid_resource_hit_count
                    << L", knife_hits=" << probe_state.knife_model_hit_count
                    << L", overrides=" << probe_state.override_hit_count
                    << L", exact=" << probe_state.exact_apply_success_count
                    << L", last_path_arg=" << probe_state.last_path_argument_index
                    << L"}";
            }
            nskinzcs2::Logger::Info(stream.str());
        }

        TryInstallKnifeModelResourceOverrideGlobalDetours();
        return;
    }
}

bool TryInstallKnifeModelResourceOverrideHook(
    const KnifePhase2ModelBindInterceptionState& phase2_state,
    const ClientSchemaOffsets& offsets)
{
    (void)phase2_state;
    (void)offsets;
    return false;

    if (!phase2_state.active ||
        phase2_state.render_entity == nullptr ||
        !(IsResolvedRuntimeEntityIndex(phase2_state.render_entity_index) ||
          IsSyntheticRuntimeEntityIndex(phase2_state.render_entity_index)) ||
        phase2_state.desired_model_name_pointer == nullptr ||
        phase2_state.desired_model_name_pointer[0] == '\0')
    {
        return false;
    }

    if (phase2_state.synthetic_render_proxy &&
        !kKnifeModelResourceOverrideEnableSyntheticProbeHooks)
    {
        if (ShouldLogWatchedKnifeAnimationTrace(phase2_state.xuid))
        {
            std::wstringstream stream;
            stream << L"Knife resource override probe install skipped for XUID "
                << phase2_state.xuid
                << L": render_entity=" << phase2_state.render_entity_index
                << L", reason=synthetic_render_proxy_hooks_temporarily_disabled";
            LogProfileDiagnosticOnce(
                phase2_state.render_signature ^ 0x78F0ull,
                stream.str());
        }
        return false;
    }

    auto& state = g_hook_state.knife_model_resource_override;
    const auto current_rebuild_generation = g_hook_state.runtime_rebuild_generation.load();
    const auto same_session =
        state.active &&
        state.xuid == phase2_state.xuid &&
        state.render_entity == phase2_state.render_entity &&
        state.render_entity_index == phase2_state.render_entity_index &&
        state.world_render_entity == phase2_state.world_render_entity &&
        state.world_render_entity_index == phase2_state.world_render_entity_index &&
        state.target_definition_index == phase2_state.target_definition_index &&
        state.desired_model_name != nullptr &&
        phase2_state.desired_model_name != nullptr &&
        ModelIdentityPathMatches(state.desired_model_name, phase2_state.desired_model_name);
    const auto& carry = g_hook_state.knife_model_resource_override_carry;
    const auto carry_matches =
        !same_session &&
        carry.valid &&
        carry.xuid == phase2_state.xuid &&
        carry.render_entity == phase2_state.render_entity &&
        carry.render_entity_index == phase2_state.render_entity_index &&
        carry.world_render_entity == phase2_state.world_render_entity &&
        carry.world_render_entity_index == phase2_state.world_render_entity_index &&
        carry.target_definition_index == phase2_state.target_definition_index &&
        carry.desired_model_name != nullptr &&
        phase2_state.desired_model_name != nullptr &&
        ModelIdentityPathMatches(carry.desired_model_name, phase2_state.desired_model_name) &&
        carry.runtime_rebuild_generation != 0 &&
        current_rebuild_generation != 0 &&
        carry.runtime_rebuild_generation != current_rebuild_generation;
    auto inherited_phase_frames_without_hit = 0;
    auto inherited_observed_slot_mask = 0ull;
    auto inherited_phase = KnifeModelResourceOverridePhase::None;

    if (!same_session)
    {
        ClearKnifeModelResourceOverrideHook();
        state = {};
        state.active = true;
        state.phase = KnifeModelResourceOverridePhase::MultiSlotTriage;
        if (carry_matches)
        {
            inherited_phase_frames_without_hit = carry.phase_frames_without_hit;
            inherited_observed_slot_mask = carry.observed_slot_mask;
            inherited_phase = carry.phase;
            state.phase_frames_without_hit =
                std::max(state.phase_frames_without_hit, inherited_phase_frames_without_hit);
            state.observed_slot_mask |= inherited_observed_slot_mask;
        }
    }

    state.xuid = phase2_state.xuid;
    state.render_signature = phase2_state.render_signature;
    state.target_definition_index = phase2_state.target_definition_index;
    state.render_entity_index = phase2_state.render_entity_index;
    state.render_entity = phase2_state.render_entity;
    state.world_render_entity_index = phase2_state.world_render_entity_index;
    state.world_render_entity = phase2_state.world_render_entity;
    state.world_render_mesh_group_mask = phase2_state.world_render_mesh_group_mask;
    state.world_render_mesh_group_mask_valid = phase2_state.world_render_mesh_group_mask_valid;
    state.desired_world_model_name = phase2_state.desired_world_model_name;
    state.desired_world_model_name_pointer = phase2_state.desired_world_model_name_pointer;
    state.desired_world_model_handle = phase2_state.desired_world_model_handle;
    state.desired_world_model_name_token = phase2_state.desired_world_model_name_token;
    state.desired_world_model_handle_valid = phase2_state.desired_world_model_handle_valid;
    state.desired_world_model_name_token_valid = phase2_state.desired_world_model_name_token_valid;
    state.desired_first_person_model_name = phase2_state.desired_first_person_model_name;
    state.desired_first_person_model_name_pointer = phase2_state.desired_first_person_model_name_pointer;
    state.desired_first_person_model_handle = phase2_state.desired_first_person_model_handle;
    state.desired_first_person_model_name_token = phase2_state.desired_first_person_model_name_token;
    state.desired_first_person_model_handle_valid = phase2_state.desired_first_person_model_handle_valid;
    state.desired_first_person_model_name_token_valid = phase2_state.desired_first_person_model_name_token_valid;
    state.desired_model_name = phase2_state.desired_model_name;
    state.desired_model_name_pointer = phase2_state.desired_model_name_pointer;
    state.desired_model_handle = phase2_state.desired_model_handle;
    state.desired_model_name_token = phase2_state.desired_model_name_token;
    state.desired_mesh_group_mask = phase2_state.desired_mesh_group_mask;
    state.desired_model_handle_valid = phase2_state.desired_model_handle_valid;
    state.desired_model_name_token_valid = phase2_state.desired_model_name_token_valid;
    state.desired_mesh_group_mask_valid = phase2_state.desired_mesh_group_mask_valid;

    const auto probes_already_installed =
        std::any_of(
            state.probe_slots.begin(),
            state.probe_slots.end(),
            [](const KnifeModelResourceOverrideProbeSlotState& probe_state)
            {
                return probe_state.installed;
            });
    const auto global_detours_already_installed =
        state.global_target_count > 0 &&
        std::any_of(
            state.global_targets.begin(),
            state.global_targets.end(),
            [](const KnifeModelResourceOverrideGlobalDetourTarget& target)
            {
                return target.installed;
            });
    if (same_session && probes_already_installed)
    {
        if (kKnifeModelResourceOverrideEnableGlobalDetours &&
            !global_detours_already_installed)
        {
            if (ShouldLogWatchedKnifeAnimationTrace(phase2_state.xuid))
            {
                std::wstringstream stream;
                stream << L"Knife resource override prearming global detours for XUID "
                    << phase2_state.xuid
                    << L": render_entity=" << phase2_state.render_entity_index
                    << L", reason=same_session_missing_global_detour";
                nskinzcs2::Logger::Info(stream.str());
            }

            TryInstallKnifeModelResourceOverrideGlobalDetours();
        }
        return true;
    }

    std::vector<KnifeModelResourceOverrideCandidate> render_candidates;
    std::vector<KnifeModelResourceOverrideCandidate> world_candidates;
    const auto any_candidate =
        TryPopulateKnifeModelResourceOverrideProbeCandidates(
            phase2_state,
            offsets,
            render_candidates,
            world_candidates);

    std::size_t installed_probe_count = 0;
    for (std::size_t index = 0; index < kKnifeModelResourceOverrideProbeSlotCount; ++index)
    {
        auto& probe_state = state.probe_slots[index];
        if (!probe_state.candidate_valid)
        {
            continue;
        }

        if (installed_probe_count >= kKnifeModelResourceOverrideMaxActiveProbeHooks)
        {
            continue;
        }

        const auto detour = reinterpret_cast<void*>(GetKnifeModelResourceOverrideProbeWrapper(index));
        if (!g_hook_state.knife_model_resource_override_probe_patches[index].Install(
                phase2_state.render_entity,
                probe_state.slot_index,
                detour))
        {
            if (ShouldLogWatchedKnifeAnimationTrace(phase2_state.xuid))
            {
                std::wstringstream stream;
                stream << L"Knife resource override probe install failed for XUID "
                    << phase2_state.xuid
                    << L": slot=" << probe_state.slot_index
                    << L", render_entity=" << phase2_state.render_entity_index;
                nskinzcs2::Logger::Warn(stream.str());
            }
            continue;
        }

        g_hook_state.original_knife_model_resource_override_probes[index] =
            reinterpret_cast<HookState::KnifeModelResourceOverrideFn>(
                g_hook_state.knife_model_resource_override_probe_patches[index].original);
        probe_state.installed =
            g_hook_state.original_knife_model_resource_override_probes[index] != nullptr;
        installed_probe_count += probe_state.installed ? 1 : 0;
    }

    if (ShouldLogWatchedKnifeAnimationTrace(phase2_state.xuid))
    {
        std::wstringstream stream;
        stream << L"Knife resource override probe triage armed for XUID " << phase2_state.xuid
            << L": phase=" << KnifeModelResourceOverridePhaseText(state.phase)
            << L", render_entity=" << phase2_state.render_entity_index
            << L", render_source=" << phase2_state.render_source
            << L", any_candidate=" << (any_candidate ? 1 : 0)
            << L", inherited_phase=" << KnifeModelResourceOverridePhaseText(inherited_phase)
            << L", inherited_miss_frames=" << inherited_phase_frames_without_hit
            << L", inherited_observed_slot_mask=" << inherited_observed_slot_mask;
        for (std::size_t index = 0; index < kKnifeModelResourceOverrideProbeSlotCount; ++index)
        {
            const auto& probe_state = state.probe_slots[index];
            stream << L" | {slot=" << probe_state.slot_index
                << L", candidate=" << (probe_state.candidate_valid ? 1 : 0)
                << L", installed=" << (probe_state.installed ? 1 : 0);
            if (probe_state.candidate_valid)
            {
                stream << L", detail=" << BuildKnifeModelResourceOverrideCandidateText(probe_state.candidate);
            }
            stream << L"}";
        }
        nskinzcs2::Logger::Info(stream.str());
    }

    if (kKnifeModelResourceOverrideEnableGlobalDetours &&
        any_candidate &&
        !global_detours_already_installed)
    {
        if (ShouldLogWatchedKnifeAnimationTrace(phase2_state.xuid))
        {
            std::wstringstream stream;
            stream << L"Knife resource override prearming global detours for XUID "
                << phase2_state.xuid
                << L": render_entity=" << phase2_state.render_entity_index
                << L", reason=arm_immediate_install";
            nskinzcs2::Logger::Info(stream.str());
        }

        TryInstallKnifeModelResourceOverrideGlobalDetours();
    }

    if (kKnifeModelResourceOverrideEnableGlobalDetours &&
        !same_session &&
        inherited_phase_frames_without_hit >= kKnifeModelResourceOverrideProbeFallbackFrames)
    {
        if (ShouldLogWatchedKnifeAnimationTrace(phase2_state.xuid))
        {
            std::wstringstream stream;
            stream << L"Knife resource override inherited miss budget forcing global detour for XUID "
                << phase2_state.xuid
                << L": carried_phase=" << KnifeModelResourceOverridePhaseText(inherited_phase)
                << L", carried_miss_frames=" << inherited_phase_frames_without_hit
                << L", carried_observed_slot_mask=" << inherited_observed_slot_mask
                << L", rebuild_generation=" << current_rebuild_generation;
            nskinzcs2::Logger::Info(stream.str());
        }

        TryInstallKnifeModelResourceOverrideGlobalDetours();
    }

    return any_candidate;
}

bool TryApplyKnifeWorldRenderVisualIsolation(
    const int entity_index,
    void* entity,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t desired_signature,
    const std::uint64_t xuid,
    const wchar_t* reason)
{
    if (entity == nullptr || !IsResolvedRuntimeEntityIndex(entity_index))
    {
        return false;
    }

    const auto isolated =
        TryApplyWeaponMeshGroupMask(
            entity_index,
            entity,
            offsets,
            0ull,
            desired_signature ^ 0x78A3ull);

    if (ShouldLogWatchedKnifeAnimationTrace(xuid))
    {
        std::uint64_t live_mesh_group_mask = 0;
        const auto live_mesh_group_mask_valid =
            TryReadWeaponMeshGroupMaskRaw(entity, offsets, live_mesh_group_mask);

        std::wstringstream stream;
        stream << L"Knife world render visual isolation for XUID " << xuid
            << L": entity=" << entity_index
            << L", reason=" << (reason != nullptr ? reason : L"unknown")
            << L", applied=" << (isolated ? 1 : 0);
        if (live_mesh_group_mask_valid)
        {
            stream << L", live_mesh_mask=" << live_mesh_group_mask;
        }
        nskinzcs2::Logger::Info(stream.str());
    }

    return isolated;
}

bool ShouldKeepKnifeSyntheticRenderIsolationActive(const KnifeModelPathState& state) noexcept
{
    return state.active &&
        state.direct_render_rebind_succeeded &&
        !state.resource_only_render_active &&
        state.synthetic_world_visual_isolation_active &&
        IsResolvedRuntimeEntityIndex(state.world_render_entity_index) &&
        state.world_render_entity != nullptr &&
        IsSyntheticRuntimeEntityIndex(state.first_person_render_entity_index) &&
        state.first_person_render_entity != nullptr;
}

bool KnifeModelPathUsesSyntheticFirstPersonRenderTarget(const KnifeModelPathState& state) noexcept
{
    return state.active &&
        IsSyntheticRuntimeEntityIndex(state.first_person_render_entity_index) &&
        state.first_person_render_entity != nullptr;
}

bool TryReassertKnifeSyntheticRenderIsolation(
    const ClientSchemaOffsets& offsets,
    const KnifeModelPathState& state,
    const wchar_t* reason)
{
    if (!ShouldKeepKnifeSyntheticRenderIsolationActive(state))
    {
        return false;
    }

    const auto desired_first_person_mesh_group_mask =
        state.desired_first_person_render_mesh_group_mask != 0
            ? state.desired_first_person_render_mesh_group_mask
            : 1ull;

    std::wstring world_revalidation_issue;
    void* live_world_render_entity = nullptr;
    void* live_world_render_item_view = nullptr;
    if (!TryResolveLiveEntityFromStoredBinding(
            state.world_render_entity_index,
            state.world_render_entity,
            state.world_render_item_view,
            offsets,
            live_world_render_entity,
            live_world_render_item_view,
            &world_revalidation_issue,
            L"synthetic_reassert_world_render"))
    {
        if (ShouldLogWatchedKnifeAnimationTrace(state.xuid))
        {
            std::wstringstream stream;
            stream << L"Knife synthetic isolation reassert aborted for XUID " << state.xuid
                << L": reason=" << (reason != nullptr ? reason : L"synthetic_reassert")
                << L", detail=" << world_revalidation_issue;
            nskinzcs2::Logger::Warn(stream.str());
        }

        TryRestoreAndClearKnifeModelPathState(
            offsets,
            L"synthetic_reassert_stale_binding");
        ResetKnifeAnimationStateSnapshot();
        return false;
    }

    bool first_person_render_revalidated = false;
    int live_first_person_render_entity_index = -1;
    void* live_first_person_render_entity = nullptr;
    std::wstring first_person_skip_reason;
    if (state.first_person_render_entity != nullptr)
    {
        std::wstring first_person_revalidation_issue;
        void* live_first_person_render_item_view = nullptr;
        if (!TryResolveLiveKnifeRenderTarget(
                state.first_person_render_entity_index,
                state.first_person_render_object,
                state.first_person_render_entity,
                state.first_person_render_item_view,
                offsets,
                live_first_person_render_entity_index,
                live_first_person_render_entity,
                live_first_person_render_item_view,
                &first_person_revalidation_issue,
                L"synthetic_reassert_first_person_render"))
        {
            if (ShouldLogWatchedKnifeAnimationTrace(state.xuid))
            {
                std::wstringstream stream;
                stream << L"Knife synthetic isolation reassert aborted for XUID " << state.xuid
                    << L": reason=" << (reason != nullptr ? reason : L"synthetic_reassert")
                    << L", detail=" << first_person_revalidation_issue;
                nskinzcs2::Logger::Warn(stream.str());
            }

            TryRestoreAndClearKnifeModelPathState(
                offsets,
                L"synthetic_reassert_stale_binding");
            ResetKnifeAnimationStateSnapshot();
            return false;
        }

        first_person_render_revalidated = true;
    }
    else
    {
        first_person_skip_reason =
            state.first_person_render_entity == nullptr
            ? L"first_person_render_missing"
            : IsSyntheticRuntimeEntityIndex(state.first_person_render_entity_index)
                ? L"synthetic_first_person_render_unreacquirable"
                : L"first_person_render_unresolved";
    }

    const auto world_isolated =
        TryApplyKnifeWorldRenderVisualIsolation(
            state.world_render_entity_index,
            live_world_render_entity,
            offsets,
            state.apply_signature ^ 0x78E0ull,
            state.xuid,
            reason != nullptr ? reason : L"synthetic_reassert");
    const auto first_person_mask_reapplied =
        first_person_render_revalidated &&
        TryApplyWeaponMeshGroupMask(
            live_first_person_render_entity_index,
            live_first_person_render_entity,
            offsets,
            desired_first_person_mesh_group_mask,
            state.apply_signature ^ 0x78E1ull);

    if (ShouldLogWatchedKnifeAnimationTrace(state.xuid))
    {
        std::uint64_t live_world_mesh_group_mask = 0;
        const auto live_world_mesh_group_mask_valid =
            TryReadWeaponMeshGroupMaskRaw(
                live_world_render_entity,
                offsets,
                live_world_mesh_group_mask);
        std::uint64_t live_first_person_mesh_group_mask = 0;
        const auto live_first_person_mesh_group_mask_valid =
            first_person_render_revalidated &&
            TryReadWeaponMeshGroupMaskRaw(
                live_first_person_render_entity,
                offsets,
                live_first_person_mesh_group_mask);

        std::wstringstream stream;
        stream << L"Knife synthetic isolation reassert for XUID " << state.xuid
            << L": reason=" << (reason != nullptr ? reason : L"synthetic_reassert")
            << L", world_isolated=" << (world_isolated ? 1 : 0)
            << L", first_person_mask_reapplied=" << (first_person_mask_reapplied ? 1 : 0)
            << L", desired_first_person_mesh_mask=" << desired_first_person_mesh_group_mask;
        if (!first_person_skip_reason.empty())
        {
            stream << L", first_person_skip_reason=" << first_person_skip_reason;
        }
        if (live_world_mesh_group_mask_valid)
        {
            stream << L", live_world_mesh_mask=" << live_world_mesh_group_mask;
        }
        if (live_first_person_mesh_group_mask_valid)
        {
            stream << L", live_first_person_mesh_mask=" << live_first_person_mesh_group_mask;
        }
        nskinzcs2::Logger::Info(stream.str());
    }

    return world_isolated &&
        (!first_person_render_revalidated || first_person_mask_reapplied);
}

void TryRestoreAndClearKnifeModelPathState(
    const ClientSchemaOffsets& offsets,
    const wchar_t* reason,
    const AttributeBindingReleaseMode release_mode)
{
    auto state = g_hook_state.knife_model_path_state;
    if (!state.active)
    {
        ClearKnifeModelPathState();
        return;
    }

    if (!ShouldAttemptKnifeModelPathStateRestore(state, release_mode))
    {
        if (ShouldLogWatchedKnifeAnimationTrace(state.xuid))
        {
            std::wstringstream stream;
            stream << L"Knife model path reset skipped state restore for XUID " << state.xuid
                << L": reason=" << (reason != nullptr ? reason : L"unknown")
                << L", release_mode="
                << (release_mode == AttributeBindingReleaseMode::RestoreOriginal
                        ? L"restore_original"
                        : L"abandon_installed")
                << L", first_person_persistent="
                << (ShouldTreatKnifeModelPathFirstPersonBindingAsPersistent(
                        state.first_person_entity_index,
                        state.first_person_render_only,
                        state.first_person_direct_render_source,
                        state.owner_kind)
                        ? 1
                        : 0);
            nskinzcs2::Logger::Info(stream.str());
        }

        ClearKnifeModelPathState();
        return;
    }

    bool attempted_restore = false;
    bool world_restored = true;
    bool first_person_restored = true;
    const auto restore_signature =
        state.apply_signature != 0
            ? state.apply_signature
            : 0x78F1000000000000ull;

    auto abort_stale_restore =
        [&](const std::wstring& revalidation_issue)
        {
            if (ShouldLogWatchedKnifeAnimationTrace(state.xuid))
            {
                std::wstringstream stream;
                stream << L"Knife model path reset skipped stale restore for XUID " << state.xuid
                    << L": reason=" << (reason != nullptr ? reason : L"unknown");
                if (!revalidation_issue.empty())
                {
                    stream << L", detail=" << revalidation_issue;
                }
                nskinzcs2::Logger::Warn(stream.str());
            }

            ClearKnifeModelPathState();
        };

    if (state.direct_render_rebind_attempted)
    {
        if (state.world_render_entity != nullptr &&
            IsResolvedRuntimeEntityIndex(state.world_render_entity_index))
        {
            std::wstring revalidation_issue;
            void* live_world_render_entity = nullptr;
            void* live_world_render_item_view = nullptr;
            if (!TryResolveLiveEntityFromStoredBinding(
                    state.world_render_entity_index,
                    state.world_render_entity,
                    state.world_render_item_view,
                    offsets,
                    live_world_render_entity,
                    live_world_render_item_view,
                    &revalidation_issue,
                    L"world_render_restore"))
            {
                abort_stale_restore(revalidation_issue);
                return;
            }

            state.world_render_entity = live_world_render_entity;
            state.world_render_item_view = live_world_render_item_view;
            attempted_restore = true;
            world_restored =
                TryRestoreKnifeDirectRenderModelState(
                    state.world_render_entity_index,
                    state.world_render_entity,
                    offsets,
                    state.original_world_render_model_handle_valid,
                    state.original_world_render_model_handle,
                    state.original_world_render_model_name_token_valid,
                    state.original_world_render_model_name_token,
                    restore_signature ^ 0x78D0ull) &&
                world_restored;
            if (state.original_world_render_mesh_group_mask_valid)
            {
                world_restored =
                    TryApplyWeaponMeshGroupMask(
                        state.world_render_entity_index,
                        state.world_render_entity,
                        offsets,
                        state.original_world_render_mesh_group_mask,
                        restore_signature ^ 0x78D6ull) &&
                    world_restored;
            }
        }

        if (state.first_person_render_entity != nullptr &&
            (state.first_person_render_entity != state.world_render_entity ||
             state.first_person_render_entity_index != state.world_render_entity_index))
        {
            std::wstring revalidation_issue;
            int live_first_person_render_entity_index = -1;
            void* live_first_person_render_entity = nullptr;
            void* live_first_person_render_item_view = nullptr;
            if (!TryResolveLiveKnifeRenderTarget(
                    state.first_person_render_entity_index,
                    state.first_person_render_object,
                    state.first_person_render_entity,
                    state.first_person_render_item_view,
                    offsets,
                    live_first_person_render_entity_index,
                    live_first_person_render_entity,
                    live_first_person_render_item_view,
                    &revalidation_issue,
                    L"first_person_render_restore"))
            {
                abort_stale_restore(revalidation_issue);
                return;
            }

            state.first_person_render_entity_index = live_first_person_render_entity_index;
            state.first_person_render_entity = live_first_person_render_entity;
            state.first_person_render_item_view = live_first_person_render_item_view;
            attempted_restore = true;
            const auto restored_first_person_render =
                IsSyntheticRuntimeEntityIndex(state.first_person_render_entity_index)
                    ? TryRestoreKnifeSyntheticRenderProxyModelState(
                          state.first_person_render_entity_index,
                          state.first_person_render_entity,
                          offsets,
                          state.original_first_person_model_handle_valid,
                          state.original_first_person_model_handle,
                          state.original_first_person_model_name_token_valid,
                          state.original_first_person_model_name_token,
                          state.original_first_person_mesh_group_mask_valid,
                          state.original_first_person_mesh_group_mask,
                          restore_signature ^ 0x78D1ull,
                          state.xuid,
                          L"first_person_render_restore")
                    : TryRestoreKnifeDirectRenderModelState(
                          state.first_person_render_entity_index,
                          state.first_person_render_entity,
                          offsets,
                          state.original_first_person_model_handle_valid,
                          state.original_first_person_model_handle,
                          state.original_first_person_model_name_token_valid,
                          state.original_first_person_model_name_token,
                          restore_signature ^ 0x78D1ull);
            first_person_restored = restored_first_person_render && first_person_restored;
        }
    }

    if (attempted_restore && ShouldLogWatchedKnifeAnimationTrace(state.xuid))
    {
        std::wstringstream stream;
        stream << L"Knife model path reset restore for XUID " << state.xuid
            << L": reason=" << (reason != nullptr ? reason : L"unknown")
            << L", world_restored=" << (world_restored ? 1 : 0)
            << L", first_person_restored=" << (first_person_restored ? 1 : 0)
            << L", first_person_synthetic="
            << (IsSyntheticRuntimeEntityIndex(state.first_person_entity_index) ? 1 : 0);
        nskinzcs2::Logger::Info(stream.str());
    }

    ClearKnifeModelPathState();
}

std::wstring DescribeItemViewAttributeVectorForDiagnostics(
    void* item_view,
    const std::ptrdiff_t item_list_offset,
    const ClientSchemaOffsets& offsets)
{
    if (item_view == nullptr || item_list_offset == 0 || offsets.attribute_list_attributes == 0)
    {
        return L"?";
    }

    NetworkVectorView vector_view {};
    if (!TryReadNetworkVectorView(
            reinterpret_cast<const std::uint8_t*>(item_view) + item_list_offset + offsets.attribute_list_attributes,
            vector_view))
    {
        return L"unreadable";
    }

    std::wstringstream stream;
    stream << L"{size=" << vector_view.size
        << L", data=" << FormatPointer(vector_view.data) << L"}";
    return stream.str();
}

std::wstring BuildWeaponRenderConsumerEntityDiagnostic(
    const wchar_t* label,
    const int entity_index,
    void* entity,
    void* item_view,
    const ClientSchemaOffsets& offsets)
{
    std::wstringstream stream;
    stream << label
        << L"{entity=" << entity_index
        << L", entity_ptr=" << FormatPointer(entity)
        << L", item_view=" << FormatPointer(item_view);

    if (item_view != nullptr)
    {
        stream << L", readback=" << BuildWeaponApplyReadback(entity, item_view, offsets);
        stream << L", static_attrs="
            << DescribeItemViewAttributeVectorForDiagnostics(item_view, offsets.item_view_attribute_list, offsets);
        stream << L", dynamic_attrs="
            << DescribeItemViewAttributeVectorForDiagnostics(item_view, offsets.item_view_dynamic_attribute_list, offsets);
    }
    else
    {
        stream << L", readback=item_view_missing";
    }

    std::uintptr_t model_state_address = 0;
    if (TryResolveEntityModelStateAddress(entity, offsets, model_state_address))
    {
        stream << L", model_state=0x" << std::hex << std::uppercase << model_state_address << std::dec;
    }
    else
    {
        stream << L", model_state=?";
    }

    std::uint64_t model_name_token = 0;
    if (TryReadEntityModelNameToken(entity, offsets, model_name_token))
    {
        stream << L", model_name_token=0x" << std::hex << std::uppercase << model_name_token << std::dec;
    }
    else
    {
        stream << L", model_name_token=?";
    }

    std::string model_name;
    if (TryReadEntityModelNameString(entity, offsets, model_name))
    {
        stream << L", model_name=" << NarrowToWide(model_name);
    }

    std::uint64_t live_mesh_group_mask = 0;
    if (TryReadKnifeRenderableMeshGroupMask(entity_index, entity, offsets, live_mesh_group_mask))
    {
        stream << L", live_mesh_mask=" << live_mesh_group_mask;
    }

    stream << L'}';
    return stream.str();
}

enum class KnifeWorldOnlyRenderVerificationReason
{
    Verified,
    MissingWorldRenderState,
    MissingWorldRenderModel,
    WorldRenderModelMismatch,
    WorldRenderHandleMismatch,
    WorldRenderMeshMismatch,
    MissingResourceHits,
    MissingResourceReadback,
};

struct KnifeWorldOnlyRenderVerificationInputs
{
    bool world_render_state_resolved = false;
    bool world_render_expected_model_resolved = false;
    bool world_render_model_matches_target = false;
    bool world_render_handle_matches_target_or_donor = false;
    bool world_render_mesh_matches_target = false;
    int resource_hits = 0;
    bool resource_readback = false;
};

struct KnifeWorldOnlyRenderVerificationResult
{
    bool verified = false;
    KnifeWorldOnlyRenderVerificationReason reason =
        KnifeWorldOnlyRenderVerificationReason::MissingWorldRenderState;
};

const wchar_t* KnifeWorldOnlyRenderVerificationReasonText(
    const KnifeWorldOnlyRenderVerificationReason reason) noexcept
{
    switch (reason)
    {
    case KnifeWorldOnlyRenderVerificationReason::Verified:
        return L"verified";
    case KnifeWorldOnlyRenderVerificationReason::MissingWorldRenderModel:
        return L"missing_world_render_model";
    case KnifeWorldOnlyRenderVerificationReason::WorldRenderModelMismatch:
        return L"world_render_model_mismatch";
    case KnifeWorldOnlyRenderVerificationReason::WorldRenderHandleMismatch:
        return L"world_render_handle_mismatch";
    case KnifeWorldOnlyRenderVerificationReason::WorldRenderMeshMismatch:
        return L"world_render_mesh_mismatch";
    case KnifeWorldOnlyRenderVerificationReason::MissingResourceHits:
        return L"missing_resource_hits";
    case KnifeWorldOnlyRenderVerificationReason::MissingResourceReadback:
        return L"missing_resource_readback";
    default:
        return L"missing_world_render_state";
    }
}

KnifeWorldOnlyRenderVerificationResult EvaluateKnifeWorldOnlyRenderVerification(
    const KnifeWorldOnlyRenderVerificationInputs& inputs) noexcept
{
    if (!inputs.world_render_state_resolved)
    {
        return {};
    }

    if (!inputs.world_render_expected_model_resolved)
    {
        return {false, KnifeWorldOnlyRenderVerificationReason::MissingWorldRenderModel};
    }

    if (!inputs.world_render_model_matches_target)
    {
        return {false, KnifeWorldOnlyRenderVerificationReason::WorldRenderModelMismatch};
    }

    if (!inputs.world_render_handle_matches_target_or_donor)
    {
        return {false, KnifeWorldOnlyRenderVerificationReason::WorldRenderHandleMismatch};
    }

    if (!inputs.world_render_mesh_matches_target)
    {
        return {false, KnifeWorldOnlyRenderVerificationReason::WorldRenderMeshMismatch};
    }

    if (inputs.resource_hits <= 0)
    {
        return {false, KnifeWorldOnlyRenderVerificationReason::MissingResourceHits};
    }

    if (!inputs.resource_readback)
    {
        return {false, KnifeWorldOnlyRenderVerificationReason::MissingResourceReadback};
    }

    return {true, KnifeWorldOnlyRenderVerificationReason::Verified};
}

struct KnifeWorldOnlyResourceEvidence
{
    int resource_hits = 0;
    std::uint64_t donor_world_handle = 0;
    std::uint64_t target_world_handle = 0;
};

KnifeWorldOnlyResourceEvidence CollectKnifeWorldOnlyResourceEvidence(
    const std::uint64_t xuid) noexcept
{
    KnifeWorldOnlyResourceEvidence evidence {};

    std::scoped_lock lock(g_hook_state.resource_handle_query_mutex);
    const auto& swap_state = g_hook_state.knife_model_path_swap_state;
    if (swap_state.enabled && swap_state.xuid == xuid)
    {
        evidence.donor_world_handle = swap_state.bridge_world_donor_handle;
        if (swap_state.resolved_target_world_handle_valid &&
            swap_state.resolved_target_world_handle != 0)
        {
            evidence.target_world_handle = swap_state.resolved_target_world_handle;
        }
    }

    const auto& published_bridge = g_hook_state.published_knife_model_path_swap_bridge;
    if (published_bridge.valid && published_bridge.xuid == xuid)
    {
        if (evidence.donor_world_handle == 0)
        {
            evidence.donor_world_handle = published_bridge.preferred_source_handle;
        }
        if (evidence.target_world_handle == 0)
        {
            evidence.target_world_handle = published_bridge.preferred_target_handle;
        }
    }

    const auto hook_index = ResourceHandleQueryHookIndex(ResourceHandleQueryInterfaceKind::ResourceSystem);
    if (hook_index != kInvalidResourceHandleQuerySlot &&
        hook_index < g_hook_state.knife_model_path_swap_query_hooks.size())
    {
        const auto& hook_target = g_hook_state.knife_model_path_swap_query_hooks[hook_index];
        if (hook_target.valid &&
            hook_target.patch.installed &&
            hook_target.original != nullptr)
        {
            evidence.resource_hits = hook_target.valid_resource_hit_count;
        }
    }

    return evidence;
}

bool TryProcessKnifePostRefreshVerification(
    const ClientSchemaOffsets& offsets,
    const PendingKnifePostRefreshVerification& verification,
    std::wstring* issue = nullptr)
{
    if (issue != nullptr)
    {
        issue->clear();
    }

    if (!verification.active)
    {
        return true;
    }

    const auto trace_watched = ShouldLogWatchedKnifeAnimationTrace(verification.xuid);
    auto live_verification = verification;

    auto fail_stale_verification =
        [&](const std::wstring& revalidation_issue)
        {
            const auto verification_issue =
                std::wstring(L"knife post-refresh verification aborted: stale entity binding") +
                (revalidation_issue.empty() ? std::wstring {} : std::wstring {L" ("} + revalidation_issue + L")");
            if (issue != nullptr)
            {
                *issue = verification_issue;
            }

            if (trace_watched)
            {
                std::wstringstream stream;
                stream << L"Knife post-refresh verification aborted for XUID " << verification.xuid
                    << L": " << verification_issue;
                nskinzcs2::Logger::Warn(stream.str());
            }
            else
            {
                nskinzcs2::Logger::Warn(verification_issue);
            }

            TryRestoreAndClearKnifeModelPathState(
                offsets,
                L"post_refresh_verification_stale_binding");
            ResetKnifeAnimationStateSnapshot();
            return false;
        };

    auto clear_optional_binding =
        [](int& entity_index, void*& entity, void*& item_view) noexcept
        {
            entity_index = -1;
            entity = nullptr;
            item_view = nullptr;
        };

    auto try_refresh_optional_binding =
        [&](const wchar_t* label,
            int& entity_index,
            void*& entity,
            void*& item_view)
        {
            if (entity == nullptr || !IsResolvedRuntimeEntityIndex(entity_index))
            {
                return;
            }

            std::wstring revalidation_issue;
            void* live_entity = nullptr;
            void* live_item_view = nullptr;
            if (!TryResolveLiveEntityFromStoredBinding(
                    entity_index,
                    entity,
                    item_view,
                    offsets,
                    live_entity,
                    live_item_view,
                    &revalidation_issue,
                    label))
            {
                clear_optional_binding(entity_index, entity, item_view);
                if (trace_watched)
                {
                    std::wstringstream stream;
                    stream << L"Knife post-refresh verification cleared stale optional binding for XUID "
                        << verification.xuid
                        << L": " << revalidation_issue;
                    nskinzcs2::Logger::Info(stream.str());
                }
                return;
            }

            entity = live_entity;
            if (live_item_view != nullptr)
            {
                item_view = live_item_view;
            }
        };

    if (live_verification.world_render_entity == nullptr ||
        !IsResolvedRuntimeEntityIndex(live_verification.world_render_entity_index))
    {
        return fail_stale_verification(L"world_render: missing resolved render entity");
    }

    {
        std::wstring revalidation_issue;
        void* live_world_render_entity = nullptr;
        void* live_world_render_item_view = nullptr;
        if (!TryResolveLiveEntityFromStoredBinding(
                live_verification.world_render_entity_index,
                live_verification.world_render_entity,
                live_verification.world_render_item_view,
                offsets,
                live_world_render_entity,
                live_world_render_item_view,
                &revalidation_issue,
                L"world_render_verification"))
        {
            return fail_stale_verification(revalidation_issue);
        }

        live_verification.world_render_entity = live_world_render_entity;
        if (live_world_render_item_view != nullptr)
        {
            live_verification.world_render_item_view = live_world_render_item_view;
        }
    }

    try_refresh_optional_binding(
        L"world_owner_verification",
        live_verification.world_entity_index,
        live_verification.world_entity,
        live_verification.world_item_view);
    try_refresh_optional_binding(
        L"hud_verification",
        live_verification.hud_entity_index,
        live_verification.hud_entity,
        live_verification.hud_item_view);

    if (live_verification.target_mode == nskinzcs2::runtime::KnifePhase2TargetMode::WorldOnlyConsumer)
    {
        bool world_render_dirty = false;
        if (live_verification.world_render_entity != nullptr &&
            IsResolvedRuntimeEntityIndex(live_verification.world_render_entity_index))
        {
            world_render_dirty =
                TryApplyWeaponMeshGroupMask(
                    live_verification.world_render_entity_index,
                    live_verification.world_render_entity,
                    offsets,
                    live_verification.world_render_desired_mesh_group_mask,
                    live_verification.desired_signature ^ 0x7861ull);
        }

        std::string world_render_model_name;
        const auto world_render_state_resolved =
            live_verification.world_render_entity != nullptr &&
            IsResolvedRuntimeEntityIndex(live_verification.world_render_entity_index);
        const auto world_render_model_resolved =
            world_render_state_resolved &&
            TryReadEntityModelNameString(
                live_verification.world_render_entity,
                offsets,
                world_render_model_name);
        std::uint64_t world_render_live_mesh_mask = 0;
        const auto world_render_mesh_resolved =
            world_render_state_resolved &&
            TryReadKnifeRenderableMeshGroupMask(
                live_verification.world_render_entity_index,
                live_verification.world_render_entity,
                offsets,
                world_render_live_mesh_mask);
        const auto world_render_identity =
            ResolveKnifeRenderModelIdentitySnapshot(
                live_verification.world_render_entity_index,
                live_verification.world_render_entity,
                offsets);
        const auto world_only_resource_evidence =
            CollectKnifeWorldOnlyResourceEvidence(live_verification.xuid);
        const auto world_render_handle_matches_target_or_donor =
            world_render_identity.model_handle_resolved &&
            ((live_verification.expected_world_render_model_handle_valid &&
              world_render_identity.model_handle ==
                  live_verification.expected_world_render_model_handle) ||
             (world_only_resource_evidence.target_world_handle != 0 &&
              world_render_identity.model_handle ==
                  world_only_resource_evidence.target_world_handle) ||
             (world_only_resource_evidence.donor_world_handle != 0 &&
              world_render_identity.model_handle ==
                  world_only_resource_evidence.donor_world_handle));

        KnifeWorldOnlyRenderVerificationInputs verification_inputs;
        verification_inputs.world_render_state_resolved = world_render_state_resolved;
        verification_inputs.world_render_expected_model_resolved =
            live_verification.expected_world_render_model_name != nullptr;
        verification_inputs.world_render_model_matches_target =
            live_verification.expected_world_render_model_name != nullptr &&
            world_render_model_resolved &&
            ModelIdentityPathMatches(
                world_render_model_name,
                live_verification.expected_world_render_model_name);
        verification_inputs.world_render_handle_matches_target_or_donor =
            world_render_handle_matches_target_or_donor;
        verification_inputs.world_render_mesh_matches_target =
            world_render_mesh_resolved &&
            world_render_live_mesh_mask == live_verification.world_render_desired_mesh_group_mask;
        verification_inputs.resource_hits = world_only_resource_evidence.resource_hits;
        verification_inputs.resource_readback =
            verification_inputs.world_render_model_matches_target;

        const auto world_only_verification =
            EvaluateKnifeWorldOnlyRenderVerification(verification_inputs);
        const auto expected_world_model_text =
            live_verification.expected_world_render_model_name != nullptr
                ? NarrowToWide(live_verification.expected_world_render_model_name)
                : std::wstring {L"?"};

        std::wstringstream stream;
        stream << L"Knife post-refresh world-only verification for XUID "
            << live_verification.xuid
            << L": target_mode=world_only_consumer"
            << L", world_render_dirty=" << (world_render_dirty ? 1 : 0)
            << L", world_render_target_mesh_mask="
            << live_verification.world_render_desired_mesh_group_mask
            << L", resource_hits=" << world_only_resource_evidence.resource_hits
            << L", resource_readback=" << (verification_inputs.resource_readback ? 1 : 0)
            << L", verified=" << (world_only_verification.verified ? 1 : 0)
            << L", reason="
            << KnifeWorldOnlyRenderVerificationReasonText(world_only_verification.reason)
            << L", expected_world_model=" << expected_world_model_text
            << L", expected_world_handle_valid="
            << (live_verification.expected_world_render_model_handle_valid ? 1 : 0)
            << L", donor_world_handle=0x" << std::hex << std::uppercase
            << world_only_resource_evidence.donor_world_handle
            << L", target_world_handle=0x"
            << world_only_resource_evidence.target_world_handle
            << std::dec << std::nouppercase
            << L" | "
            << BuildWeaponRenderConsumerEntityDiagnostic(
                   L"world_carrier",
                   live_verification.world_entity_index,
                   live_verification.world_entity,
                   live_verification.world_item_view,
                   offsets)
            << L" | "
            << BuildWeaponRenderConsumerEntityDiagnostic(
                   L"world_render",
                   live_verification.world_render_entity_index,
                   live_verification.world_render_entity,
                   live_verification.world_render_item_view,
                   offsets);
        if (live_verification.hud_entity != nullptr &&
            IsResolvedRuntimeEntityIndex(live_verification.hud_entity_index))
        {
            stream << L" | "
                << BuildWeaponRenderConsumerEntityDiagnostic(
                       L"hud",
                       live_verification.hud_entity_index,
                       live_verification.hud_entity,
                       live_verification.hud_item_view,
                       offsets);
        }
        if (live_verification.world_render_is_explicit_owner_child &&
            live_verification.world_render_model_name_token_before_valid)
        {
            std::uint64_t world_render_model_name_token_after = 0;
            if (TryReadEntityModelNameToken(
                    live_verification.world_render_entity,
                    offsets,
                    world_render_model_name_token_after) &&
                world_render_model_name_token_after ==
                    live_verification.world_render_model_name_token_before)
            {
                stream << L" | note=binding correct, render rebind still missing";
            }
        }

        nskinzcs2::model::CosmeticProfile diagnostic_profile;
        diagnostic_profile.xuid = live_verification.xuid;
        diagnostic_profile.base_item = 42;
        diagnostic_profile.override_item = live_verification.target_definition_index;

        if (world_only_verification.verified)
        {
            nskinzcs2::Logger::Info(stream.str());
            if (trace_watched)
            {
                TraceWatchedKnifeDiagnostic(diagnostic_profile, stream.str());
            }

            if (g_hook_state.knife_model_path_state.active &&
                g_hook_state.knife_model_path_state.xuid == live_verification.xuid &&
                g_hook_state.knife_model_path_state.world_entity_index ==
                    live_verification.world_entity_index &&
                g_hook_state.knife_model_path_state.world_render_entity_index ==
                    live_verification.world_render_entity_index)
            {
                g_hook_state.knife_model_path_state.real_viewmodel_verified = false;
                g_hook_state.knife_model_path_state.strict_verified = false;
                g_hook_state.knife_model_path_state.animation_owner_verified = false;
                g_hook_state.knife_model_path_state.verified_target_definition_index = 0;
                g_hook_state.knife_model_path_state.verified_viewmodel_carrier_entity_index = -1;
                g_hook_state.knife_model_path_state.verified_viewmodel_render_entity_index = -1;
                g_hook_state.knife_model_path_state.direct_render_rebind_attempted = false;
                g_hook_state.knife_model_path_state.direct_render_rebind_succeeded = false;
                g_hook_state.knife_model_path_state.resource_only_render_active = true;
                UpdateKnifeRuntimeStatusText(
                    BuildKnifeModelAndFinishRuntimePathText(),
                    L"single world consumer active; no separate first-person consumer observed");
            }

            return true;
        }

        const auto verification_issue =
            std::wstring(L"knife post-refresh verification failed: ") +
            KnifeWorldOnlyRenderVerificationReasonText(world_only_verification.reason);
        if (issue != nullptr)
        {
            *issue = verification_issue;
        }

        nskinzcs2::Logger::Warn(stream.str());
        TryRestoreAndClearKnifeModelPathState(
            offsets,
            L"post_refresh_world_only_verification_failed");
        ResetKnifeAnimationStateSnapshot();
        UpdateKnifeRuntimeStatusText(
            BuildKnifeFinishOnlyRuntimePathText(),
            BuildKnifeRuntimeReasonText(
                nskinzcs2::runtime::KnifeApplyGateReason::RestoreUnverified));
        return false;
    }

    if (live_verification.first_person_render_entity == nullptr ||
        !IsResolvedRuntimeEntityIndex(live_verification.first_person_render_entity_index))
    {
        return fail_stale_verification(L"first_person_render: missing resolved render entity");
    }

    {
        std::wstring revalidation_issue;
        void* live_first_person_render_entity = nullptr;
        void* live_first_person_render_item_view = nullptr;
        if (!TryResolveLiveEntityFromStoredBinding(
                live_verification.first_person_render_entity_index,
                live_verification.first_person_render_entity,
                live_verification.first_person_render_item_view,
                offsets,
                live_first_person_render_entity,
                live_first_person_render_item_view,
                &revalidation_issue,
                L"first_person_render_verification"))
        {
            return fail_stale_verification(revalidation_issue);
        }

        live_verification.first_person_render_entity = live_first_person_render_entity;
        if (live_first_person_render_item_view != nullptr)
        {
            live_verification.first_person_render_item_view = live_first_person_render_item_view;
        }
    }

    if (live_verification.first_person_owner_entity == nullptr ||
        !IsResolvedRuntimeEntityIndex(live_verification.first_person_owner_entity_index))
    {
        return fail_stale_verification(L"first_person_owner: missing resolved animation owner");
    }

    {
        std::wstring revalidation_issue;
        void* live_first_person_owner_entity = nullptr;
        void* live_first_person_owner_item_view = nullptr;
        if (!TryResolveLiveEntityFromStoredBinding(
                live_verification.first_person_owner_entity_index,
                live_verification.first_person_owner_entity,
                live_verification.first_person_owner_item_view,
                offsets,
                live_first_person_owner_entity,
                live_first_person_owner_item_view,
                &revalidation_issue,
                L"first_person_owner_verification"))
        {
            return fail_stale_verification(revalidation_issue);
        }

        live_verification.first_person_owner_entity = live_first_person_owner_entity;
        if (live_first_person_owner_item_view != nullptr)
        {
            live_verification.first_person_owner_item_view = live_first_person_owner_item_view;
        }
    }

    if (!live_verification.first_person_owner_safe_for_animation ||
        live_verification.first_person_owner_kind != nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel)
    {
        return fail_stale_verification(L"first_person_owner: unsafe animation owner");
    }

    if (live_verification.first_person_owner_item_view == nullptr)
    {
        return fail_stale_verification(L"first_person_owner: missing item view");
    }

    int first_person_owner_definition_index = 0;
    if (!TryReadItemDefinitionIndex(
            live_verification.first_person_owner_item_view,
            offsets,
            first_person_owner_definition_index))
    {
        return fail_stale_verification(L"first_person_owner: definition unreadable");
    }

    if (first_person_owner_definition_index != live_verification.target_definition_index)
    {
        return fail_stale_verification(L"first_person_owner: definition drifted from requested knife");
    }

    bool world_render_dirty = false;
    if (live_verification.world_render_entity != nullptr &&
        IsResolvedRuntimeEntityIndex(live_verification.world_render_entity_index))
    {
        world_render_dirty =
            TryApplyWeaponMeshGroupMask(
                live_verification.world_render_entity_index,
                live_verification.world_render_entity,
                offsets,
                live_verification.world_render_desired_mesh_group_mask,
                live_verification.desired_signature ^ 0x7861ull);
    }

    bool first_person_dirty = false;
    if (live_verification.first_person_render_entity != nullptr &&
        IsResolvedRuntimeEntityIndex(live_verification.first_person_render_entity_index) &&
        (live_verification.first_person_render_entity != live_verification.world_render_entity ||
         live_verification.first_person_render_entity_index != live_verification.world_render_entity_index))
    {
        first_person_dirty =
            TryApplyWeaponMeshGroupMask(
                live_verification.first_person_render_entity_index,
                live_verification.first_person_render_entity,
                offsets,
                live_verification.first_person_render_desired_mesh_group_mask,
                live_verification.desired_signature ^ 0x7862ull);
    }

    bool hud_dirty = false;
    if (live_verification.hud_entity != nullptr &&
        IsResolvedRuntimeEntityIndex(live_verification.hud_entity_index) &&
        !IsSyntheticRuntimeEntityIndex(live_verification.hud_entity_index) &&
        (live_verification.hud_entity != live_verification.first_person_render_entity ||
         live_verification.hud_entity_index != live_verification.first_person_render_entity_index) &&
        (live_verification.hud_entity != live_verification.world_render_entity ||
         live_verification.hud_entity_index != live_verification.world_render_entity_index))
    {
        hud_dirty =
            TryApplyWeaponMeshGroupMask(
                live_verification.hud_entity_index,
                live_verification.hud_entity,
                offsets,
                1ull,
                live_verification.desired_signature ^ 0x7863ull);
    }

    std::string world_render_model_name;
    const auto world_render_state_resolved =
        live_verification.world_render_entity != nullptr &&
        IsResolvedRuntimeEntityIndex(live_verification.world_render_entity_index);
    const auto world_render_model_resolved =
        world_render_state_resolved &&
        TryReadEntityModelNameString(
            live_verification.world_render_entity,
            offsets,
            world_render_model_name);
    std::uint64_t world_render_live_mesh_mask = 0;
    const auto world_render_mesh_resolved =
        world_render_state_resolved &&
        TryReadKnifeRenderableMeshGroupMask(
            live_verification.world_render_entity_index,
            live_verification.world_render_entity,
            offsets,
            world_render_live_mesh_mask);

    std::string first_person_render_model_name;
    const auto first_person_render_state_resolved =
        live_verification.first_person_render_entity != nullptr &&
        IsResolvedRuntimeEntityIndex(live_verification.first_person_render_entity_index);
    const auto first_person_render_model_resolved =
        first_person_render_state_resolved &&
        TryReadEntityModelNameString(
            live_verification.first_person_render_entity,
            offsets,
            first_person_render_model_name);
    std::uint64_t first_person_render_live_mesh_mask = 0;
    const auto first_person_render_mesh_resolved =
        first_person_render_state_resolved &&
        TryReadKnifeRenderableMeshGroupMask(
            live_verification.first_person_render_entity_index,
            live_verification.first_person_render_entity,
            offsets,
            first_person_render_live_mesh_mask);

    nskinzcs2::runtime::KnifeRenderVerificationInputs verification_inputs;
    verification_inputs.world_render_state_resolved = world_render_state_resolved;
    verification_inputs.world_render_expected_model_resolved =
        live_verification.expected_world_render_model_name != nullptr;
    verification_inputs.world_render_model_matches_target =
        live_verification.expected_world_render_model_name != nullptr &&
        world_render_model_resolved &&
        ModelIdentityPathMatches(
            world_render_model_name,
            live_verification.expected_world_render_model_name);
    verification_inputs.world_render_mesh_matches_target =
        world_render_mesh_resolved &&
        world_render_live_mesh_mask == live_verification.world_render_desired_mesh_group_mask;
    verification_inputs.first_person_render_state_resolved = first_person_render_state_resolved;
    verification_inputs.first_person_render_expected_model_resolved =
        live_verification.expected_first_person_render_model_name != nullptr;
    verification_inputs.first_person_render_model_matches_target =
        live_verification.expected_first_person_render_model_name != nullptr &&
        first_person_render_model_resolved &&
        ModelIdentityPathMatches(
            first_person_render_model_name,
            live_verification.expected_first_person_render_model_name);
    verification_inputs.first_person_render_mesh_matches_target =
        first_person_render_mesh_resolved &&
        first_person_render_live_mesh_mask == live_verification.first_person_render_desired_mesh_group_mask;
    verification_inputs.first_person_render_untrusted = live_verification.first_person_render_untrusted;

    const auto strict_verification =
        nskinzcs2::runtime::EvaluateKnifeRenderVerification(verification_inputs);
    const auto expected_world_model_text =
        live_verification.expected_world_render_model_name != nullptr
        ? NarrowToWide(live_verification.expected_world_render_model_name)
        : std::wstring {L"?"};
    const auto expected_first_person_model_text =
        live_verification.expected_first_person_render_model_name != nullptr
        ? NarrowToWide(live_verification.expected_first_person_render_model_name)
        : std::wstring {L"?"};

    std::wstringstream stream;
    stream << L"Knife post-refresh render verification for XUID " << live_verification.xuid
        << L": target_definition=" << live_verification.target_definition_index
        << L", world_render_dirty=" << (world_render_dirty ? 1 : 0)
        << L", world_render_target_mesh_mask=" << live_verification.world_render_desired_mesh_group_mask
        << L", first_person_dirty=" << (first_person_dirty ? 1 : 0)
        << L", first_person_target_mesh_mask=" << live_verification.first_person_render_desired_mesh_group_mask
        << L", hud_dirty=" << (hud_dirty ? 1 : 0)
        << L", strict_verified=" << (strict_verification.verified ? 1 : 0)
        << L", strict_reason="
        << nskinzcs2::runtime::KnifeRenderVerificationReasonText(strict_verification.reason)
        << L", expected_world_model=" << expected_world_model_text
        << L", expected_first_person_model=" << expected_first_person_model_text
        << L", first_person_untrusted=" << (live_verification.first_person_render_untrusted ? 1 : 0)
        << L", first_person_binding_source="
        << (live_verification.first_person_binding_source != nullptr
                ? live_verification.first_person_binding_source
                : L"owner")
        << L", first_person_render_source="
        << (live_verification.first_person_render_source != nullptr
                ? live_verification.first_person_render_source
                : L"owner")
        << L" | "
        << BuildWeaponRenderConsumerEntityDiagnostic(
               L"world_carrier",
               live_verification.world_entity_index,
               live_verification.world_entity,
               live_verification.world_item_view,
               offsets)
        << L" | "
        << BuildWeaponRenderConsumerEntityDiagnostic(
               L"world_render",
               live_verification.world_render_entity_index,
               live_verification.world_render_entity,
               live_verification.world_render_item_view,
               offsets)
        << L" | "
        << BuildWeaponRenderConsumerEntityDiagnostic(
               L"first_person_owner",
               live_verification.first_person_owner_entity_index,
               live_verification.first_person_owner_entity,
               live_verification.first_person_owner_item_view,
               offsets)
        << L" | "
        << BuildWeaponRenderConsumerEntityDiagnostic(
               L"first_person_render",
               live_verification.first_person_render_entity_index,
               live_verification.first_person_render_entity,
               live_verification.first_person_render_item_view,
               offsets);
    if (live_verification.hud_entity != nullptr && IsResolvedRuntimeEntityIndex(live_verification.hud_entity_index))
    {
        stream << L" | "
            << BuildWeaponRenderConsumerEntityDiagnostic(
                   L"hud",
                   live_verification.hud_entity_index,
                   live_verification.hud_entity,
                   live_verification.hud_item_view,
                   offsets);
    }
    std::uint64_t world_render_model_name_token_after = 0;
    if (live_verification.world_render_is_explicit_owner_child &&
        live_verification.world_render_model_name_token_before_valid &&
        TryReadEntityModelNameToken(
            live_verification.world_render_entity,
            offsets,
            world_render_model_name_token_after) &&
        world_render_model_name_token_after == live_verification.world_render_model_name_token_before)
    {
        stream << L" | note=binding correct, render rebind still missing";
    }

    nskinzcs2::model::CosmeticProfile diagnostic_profile;
    diagnostic_profile.xuid = live_verification.xuid;
    diagnostic_profile.base_item = 42;
    diagnostic_profile.override_item = live_verification.target_definition_index;
    if (strict_verification.verified)
    {
        if (trace_watched)
        {
            TraceWatchedKnifeDiagnostic(diagnostic_profile, stream.str());
        }

        if (g_hook_state.knife_model_path_state.active &&
            g_hook_state.knife_model_path_state.xuid == live_verification.xuid &&
            g_hook_state.knife_model_path_state.world_entity_index == live_verification.world_entity_index &&
            g_hook_state.knife_model_path_state.world_render_entity_index ==
                live_verification.world_render_entity_index &&
            g_hook_state.knife_model_path_state.first_person_render_entity_index ==
                live_verification.first_person_render_entity_index)
        {
            g_hook_state.knife_model_path_state.real_viewmodel_verified = true;
            g_hook_state.knife_model_path_state.strict_verified = true;
            g_hook_state.knife_model_path_state.animation_owner_verified = true;
            g_hook_state.knife_model_path_state.verified_target_definition_index =
                live_verification.target_definition_index;
            g_hook_state.knife_model_path_state.verified_viewmodel_carrier_entity_index =
                live_verification.first_person_owner_entity_index;
            g_hook_state.knife_model_path_state.verified_viewmodel_render_entity_index =
                live_verification.first_person_render_entity_index;
            UpdateKnifeRuntimeStatusText(
                BuildKnifeModelAndFinishRuntimePathText(),
                {});
        }

        return true;
    }

    const auto verification_issue =
        std::wstring(L"knife post-refresh verification failed: ") +
        nskinzcs2::runtime::KnifeRenderVerificationReasonText(strict_verification.reason);
    if (issue != nullptr)
    {
        *issue = verification_issue;
    }

    if (trace_watched)
    {
        nskinzcs2::Logger::Warn(stream.str());
    }
    else
    {
        nskinzcs2::Logger::Warn(verification_issue);
    }

    TryRestoreAndClearKnifeModelPathState(
        offsets,
        L"post_refresh_verification_failed");
    ResetKnifeAnimationStateSnapshot();
    UpdateKnifeRuntimeStatusText(
        BuildKnifeFinishOnlyRuntimePathText(),
        BuildKnifeRuntimeReasonText(nskinzcs2::runtime::KnifeApplyGateReason::RestoreUnverified));
    return false;
}

std::wstring BuildRenderedWorldWeaponConsumerDiagnostic(
    const RenderedWorldWeaponTrace& trace,
    const ClientSchemaOffsets& offsets)
{
    std::wstringstream stream;
    stream << L"shared{scene=" << (trace.owned_and_scene_owner_share_item_view ? 1 : 0)
        << L", explicit=" << (trace.owned_and_explicit_child_share_item_view ? 1 : 0)
        << L", hud=" << (trace.owned_and_hud_share_item_view ? 1 : 0) << L"}";
    stream << L" | "
        << BuildWeaponRenderConsumerEntityDiagnostic(
               L"world",
               trace.owned_weapon_entity_index,
               trace.owned_weapon_entity,
               trace.owned_weapon_item_view,
               offsets);
    stream << L" | "
        << BuildWeaponRenderConsumerEntityDiagnostic(
               L"scene_owner",
               trace.scene_owner_entity_index,
               trace.scene_owner_entity,
               trace.scene_owner_item_view,
               offsets);
    stream << L" | "
        << BuildWeaponRenderConsumerEntityDiagnostic(
               L"explicit_child",
               trace.explicit_owner_child_entity_index,
               trace.explicit_owner_child_entity,
               trace.explicit_owner_child_item_view,
               offsets);
    stream << L" | "
        << BuildWeaponRenderConsumerEntityDiagnostic(
               L"hud",
               trace.hud_weapon_entity_index,
               trace.hud_weapon_entity,
               trace.hud_weapon_item_view,
               offsets);
    return stream.str();
}

bool TryReadEntityMaterialGroupToken(
    void* entity,
    const ClientSchemaOffsets& offsets,
    std::uint32_t& material_group)
{
    material_group = 0;

    if (entity == nullptr ||
        offsets.base_entity_game_scene_node == 0 ||
        offsets.skeleton_instance_material_group == 0)
    {
        return false;
    }

    void* game_scene_node = nullptr;
    if (!SafeReadField(entity, offsets.base_entity_game_scene_node, game_scene_node) ||
        game_scene_node == nullptr)
    {
        return false;
    }

    return SafeReadValue(
        reinterpret_cast<const void*>(
            reinterpret_cast<std::uintptr_t>(game_scene_node) + offsets.skeleton_instance_material_group),
        material_group);
}

bool TryResetEntityMaterialGroupToDefault(
    void* entity,
    const ClientSchemaOffsets& offsets,
    std::uint32_t& previous_material_group)
{
    previous_material_group = 0;
    if (entity == nullptr ||
        offsets.base_entity_game_scene_node == 0 ||
        offsets.skeleton_instance_material_group == 0)
    {
        return false;
    }

    void* game_scene_node = nullptr;
    if (!SafeReadField(entity, offsets.base_entity_game_scene_node, game_scene_node) ||
        game_scene_node == nullptr)
    {
        return false;
    }

    auto* material_group_address =
        reinterpret_cast<std::uint8_t*>(game_scene_node) + offsets.skeleton_instance_material_group;
    if (!SafeReadValue(material_group_address, previous_material_group))
    {
        return false;
    }

    constexpr std::uint32_t kDefaultMaterialGroupToken = 0;
    return previous_material_group == kDefaultMaterialGroupToken ||
        SafeWriteValue(material_group_address, kDefaultMaterialGroupToken);
}

bool ContainsAsciiInsensitive(std::string_view haystack, std::string_view needle)
{
    if (needle.empty() || haystack.size() < needle.size())
    {
        return false;
    }

    const auto to_lower =
        [](unsigned char ch) -> unsigned char
        {
            return static_cast<unsigned char>(std::tolower(ch));
        };

    for (std::size_t start = 0; start + needle.size() <= haystack.size(); ++start)
    {
        bool matches = true;
        for (std::size_t index = 0; index < needle.size(); ++index)
        {
            if (to_lower(static_cast<unsigned char>(haystack[start + index])) !=
                to_lower(static_cast<unsigned char>(needle[index])))
            {
                matches = false;
                break;
            }
        }

        if (matches)
        {
            return true;
        }
    }

    return false;
}

bool IsLikelyGloveModelPath(const std::string& model_name)
{
    return !model_name.empty() &&
        (ContainsAsciiInsensitive(model_name, "glove") ||
         ContainsAsciiInsensitive(model_name, "handwrap"));
}

const wchar_t* KnifeFirstPersonRenderableModelKindText(
    const KnifeFirstPersonRenderableModelKind kind) noexcept
{
    switch (kind)
    {
    case KnifeFirstPersonRenderableModelKind::WeaponLike:
        return L"weapon";
    case KnifeFirstPersonRenderableModelKind::CharacterLike:
        return L"character";
    case KnifeFirstPersonRenderableModelKind::Unknown:
    default:
        return L"unknown";
    }
}

KnifeFirstPersonRenderableModelKind ClassifyKnifeFirstPersonRenderableModel(
    void* entity,
    const ClientSchemaOffsets& offsets)
{
    if (entity == nullptr)
    {
        return KnifeFirstPersonRenderableModelKind::Unknown;
    }

    std::string model_name;
    if (!TryReadEntityModelNameString(entity, offsets, model_name) || model_name.empty())
    {
        return KnifeFirstPersonRenderableModelKind::Unknown;
    }

    const auto in_characters_tree = ContainsAsciiInsensitive(model_name, "characters/models/");
    const auto in_shared_arms_tree = ContainsAsciiInsensitive(model_name, "shared/arms/");
    const auto has_arms_token = ContainsAsciiInsensitive(model_name, "/arms/");
    const auto in_weapons_tree =
        ContainsAsciiInsensitive(model_name, "/weapons/") ||
        ContainsAsciiInsensitive(model_name, "weapons/models/");
    const auto has_knife_token =
        ContainsAsciiInsensitive(model_name, "weapon_knife") ||
        ContainsAsciiInsensitive(model_name, "/knife/") ||
        ContainsAsciiInsensitive(model_name, "knife_");

    if (in_weapons_tree && has_knife_token && !in_shared_arms_tree && !has_arms_token)
    {
        return KnifeFirstPersonRenderableModelKind::WeaponLike;
    }

    if (in_characters_tree || in_shared_arms_tree || has_arms_token)
    {
        return KnifeFirstPersonRenderableModelKind::CharacterLike;
    }

    return KnifeFirstPersonRenderableModelKind::Unknown;
}

bool TryResolveKnifeFirstPersonRenderChild(
    const std::vector<void*>& entity_cache,
    const wchar_t* source,
    const int source_entity_index,
    const int world_entity_index,
    const std::uint32_t owner_handle,
    void* world_item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    int& render_entity_index,
    void*& render_entity,
    void*& render_item_view,
    int& render_definition_index,
    bool& render_item_view_validated,
    bool& render_item_view_used_heuristic,
    bool& render_item_view_has_raw)
{
    render_entity_index = -1;
    render_entity = nullptr;
    render_item_view = nullptr;
    render_definition_index = 0;
    render_item_view_validated = false;
    render_item_view_used_heuristic = false;
    render_item_view_has_raw = false;

    const auto owner_entity_index = HandleToEntityIndex(owner_handle);
    if (owner_handle == kInvalidEntityHandle ||
        offsets.base_owner_entity == 0 ||
        owner_entity_index < 0)
    {
        return false;
    }

    struct RenderChildCandidate
    {
        int entity_index = -1;
        void* entity = nullptr;
        void* item_view = nullptr;
        int owner_chain_depth = 0;
        int definition_index = 0;
        bool definition_known = false;
        bool definition_family_matches = false;
        bool validated = false;
        bool used_heuristic = false;
        bool has_raw_item_view = false;
        bool shared_world_item_view = false;
        bool same_world_entity = false;
        bool account_id_resolved = false;
        std::uint32_t account_id = 0;
        bool raw_promotable = false;
        KnifeFirstPersonRenderableModelKind model_kind =
            KnifeFirstPersonRenderableModelKind::Unknown;
        std::string model_name;
        const wchar_t* resolution_kind = L"rejected";
        const wchar_t* reject_reason = L"none";
        int score = -1;
    };

    auto build_candidate_descriptor =
        [&](const RenderChildCandidate& candidate)
        {
            std::wstringstream stream;
            stream << L"{entity=" << candidate.entity_index
                << L", entity_ptr=" << FormatPointer(candidate.entity)
                << L", item_view=" << FormatPointer(candidate.item_view)
                << L", owner_chain_depth=" << candidate.owner_chain_depth
                << L", raw_item_view=" << (candidate.has_raw_item_view ? 1 : 0)
                << L", validated=" << (candidate.validated ? 1 : 0)
                << L", heuristic=" << (candidate.used_heuristic ? 1 : 0)
                << L", raw_promotable=" << (candidate.raw_promotable ? 1 : 0)
                << L", shared_world_item_view=" << (candidate.shared_world_item_view ? 1 : 0)
                << L", same_world_entity=" << (candidate.same_world_entity ? 1 : 0)
                << L", definition=" << candidate.definition_index
                << L", definition_known=" << (candidate.definition_known ? 1 : 0)
                << L", family_match=" << (candidate.definition_family_matches ? 1 : 0)
                << L", account_id=";
            if (candidate.account_id_resolved)
            {
                stream << candidate.account_id;
            }
            else
            {
                stream << L"unresolved";
            }

            stream << L", model_kind="
                << KnifeFirstPersonRenderableModelKindText(candidate.model_kind)
                << L", resolution=" << candidate.resolution_kind
                << L", reject_reason=" << candidate.reject_reason
                << L", score=" << candidate.score;
            if (!candidate.model_name.empty())
            {
                stream << L", model_name=" << NarrowToWide(candidate.model_name);
            }
            stream << L'}';
            return stream.str();
        };

    const auto expected_account_id = AccountIdFromXuid(xuid);
    const auto normalized_parent =
        NormalizeBaseItem(parent_definition_index, knife_definition_indices, glove_definition_indices);
    auto resolve_owner_chain_depth =
        [&](void* entity) noexcept
        {
            if (entity == nullptr ||
                (offsets.base_owner_entity == 0 &&
                 offsets.base_old_move_parent == 0))
            {
                return -1;
            }

            struct PendingOwner
            {
                int entity_index = -1;
                int depth = 0;
            };

            auto queue_owner_handle =
                [&](std::uint32_t handle,
                    const int depth,
                    std::vector<PendingOwner>& pending_owners,
                    std::unordered_set<int>& queued_owner_indices) noexcept
                {
                    const auto entity_index = HandleToEntityIndex(handle);
                    if (entity_index < 0 ||
                        depth > 8 ||
                        !queued_owner_indices.insert(entity_index).second)
                    {
                        return;
                    }

                    pending_owners.push_back({entity_index, depth});
                };

            std::vector<PendingOwner> pending_owners;
            pending_owners.reserve(16);
            std::unordered_set<int> queued_owner_indices;

            std::uint32_t owner_handle = kInvalidEntityHandle;
            if (offsets.base_owner_entity != 0 &&
                SafeReadField(entity, offsets.base_owner_entity, owner_handle))
            {
                queue_owner_handle(owner_handle, 1, pending_owners, queued_owner_indices);
            }

            std::uint32_t old_move_parent_handle = kInvalidEntityHandle;
            if (offsets.base_old_move_parent != 0 &&
                SafeReadField(entity, offsets.base_old_move_parent, old_move_parent_handle))
            {
                queue_owner_handle(old_move_parent_handle, 1, pending_owners, queued_owner_indices);
            }

            while (!pending_owners.empty())
            {
                const auto pending = pending_owners.back();
                pending_owners.pop_back();

                if (pending.entity_index == owner_entity_index)
                {
                    return pending.depth;
                }

                if (pending.entity_index < 0 ||
                    pending.entity_index >= static_cast<int>(entity_cache.size()))
                {
                    continue;
                }

                auto* owner_entity = entity_cache[static_cast<std::size_t>(pending.entity_index)];
                if (owner_entity == nullptr)
                {
                    continue;
                }

                if (offsets.base_owner_entity != 0 &&
                    SafeReadField(owner_entity, offsets.base_owner_entity, owner_handle))
                {
                    queue_owner_handle(
                        owner_handle,
                        pending.depth + 1,
                        pending_owners,
                        queued_owner_indices);
                }

                if (offsets.base_old_move_parent != 0 &&
                    SafeReadField(owner_entity, offsets.base_old_move_parent, old_move_parent_handle))
                {
                    queue_owner_handle(
                        old_move_parent_handle,
                        pending.depth + 1,
                        pending_owners,
                        queued_owner_indices);
                }
            }

            return -1;
        };

    int best_score = -1;
    RenderChildCandidate best_candidate {};
    int child_count = 0;
    int validated_count = 0;
    int heuristic_count = 0;
    int raw_promotable_count = 0;
    int weapon_like_count = 0;
    int max_owner_chain_depth = 0;
    std::vector<std::wstring> candidate_samples;
    candidate_samples.reserve(8);
    for (std::size_t index = 0; index < entity_cache.size(); ++index)
    {
        auto* candidate = entity_cache[index];
        if (candidate == nullptr)
        {
            continue;
        }

        const auto owner_chain_depth = resolve_owner_chain_depth(candidate);
        if (owner_chain_depth < 1)
        {
            continue;
        }

        ++child_count;
        RenderChildCandidate candidate_evaluation {};
        candidate_evaluation.entity_index = static_cast<int>(index);
        candidate_evaluation.entity = candidate;
        candidate_evaluation.owner_chain_depth = owner_chain_depth;
        ResolveKnifeFirstPersonProbeItemView(
            candidate,
            offsets,
            xuid,
            parent_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            candidate_evaluation.item_view,
            candidate_evaluation.definition_index,
            candidate_evaluation.validated,
            candidate_evaluation.used_heuristic,
            candidate_evaluation.has_raw_item_view);
        candidate_evaluation.model_kind =
            ClassifyKnifeFirstPersonRenderableModel(candidate, offsets);
        TryReadEntityModelNameString(candidate, offsets, candidate_evaluation.model_name);
        candidate_evaluation.same_world_entity =
            world_entity_index >= 0 &&
            candidate_evaluation.entity_index == world_entity_index;
        candidate_evaluation.shared_world_item_view =
            candidate_evaluation.item_view != nullptr &&
            world_item_view != nullptr &&
            candidate_evaluation.item_view == world_item_view;

        if (candidate_evaluation.item_view != nullptr)
        {
            if (candidate_evaluation.definition_index == 0)
            {
                TryReadItemDefinitionIndex(
                    candidate_evaluation.item_view,
                    offsets,
                    candidate_evaluation.definition_index);
            }

            if (offsets.item_view_account_id != 0)
            {
                candidate_evaluation.account_id_resolved =
                    SafeReadField(
                        candidate_evaluation.item_view,
                        offsets.item_view_account_id,
                        candidate_evaluation.account_id);
            }
        }

        candidate_evaluation.definition_known =
            IsKnownDefinitionIndex(candidate_evaluation.definition_index, known_definition_indices);
        candidate_evaluation.definition_family_matches =
            candidate_evaluation.definition_index != 0 &&
            NormalizeBaseItem(
                candidate_evaluation.definition_index,
                knife_definition_indices,
                glove_definition_indices) == normalized_parent;

        const auto account_matches =
            !candidate_evaluation.account_id_resolved ||
            candidate_evaluation.account_id == 0 ||
            candidate_evaluation.account_id == expected_account_id;

        candidate_evaluation.raw_promotable =
            !candidate_evaluation.validated &&
            candidate_evaluation.has_raw_item_view &&
            candidate_evaluation.item_view != nullptr &&
            !candidate_evaluation.same_world_entity &&
            candidate_evaluation.model_kind != KnifeFirstPersonRenderableModelKind::CharacterLike &&
            (candidate_evaluation.model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike ||
             candidate_evaluation.shared_world_item_view) &&
            account_matches &&
            (candidate_evaluation.shared_world_item_view ||
             (candidate_evaluation.definition_known &&
              candidate_evaluation.definition_family_matches));

        if (candidate_evaluation.validated)
        {
            ++validated_count;
        }
        if (candidate_evaluation.used_heuristic)
        {
            ++heuristic_count;
        }
        if (candidate_evaluation.raw_promotable)
        {
            ++raw_promotable_count;
        }
        if (candidate_evaluation.model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
        {
            ++weapon_like_count;
        }
        max_owner_chain_depth = std::max(max_owner_chain_depth, candidate_evaluation.owner_chain_depth);

        if (candidate_evaluation.same_world_entity)
        {
            candidate_evaluation.reject_reason = L"world_entity_self_promotion";
        }
        else if (candidate_evaluation.model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike)
        {
            candidate_evaluation.reject_reason = L"character_like";
        }
        else if (candidate_evaluation.validated)
        {
            candidate_evaluation.resolution_kind =
                candidate_evaluation.used_heuristic ? L"heuristic" : L"validated";
        }
        else if (candidate_evaluation.raw_promotable)
        {
            candidate_evaluation.resolution_kind = L"raw";
        }
        else if (candidate_evaluation.item_view == nullptr)
        {
            candidate_evaluation.reject_reason = L"item_view_missing";
        }
        else if (candidate_evaluation.definition_index == 0)
        {
            candidate_evaluation.reject_reason = L"definition_unreadable";
        }
        else if (!candidate_evaluation.definition_known &&
                 !candidate_evaluation.shared_world_item_view)
        {
            candidate_evaluation.reject_reason = L"definition_unknown";
        }
        else if (!candidate_evaluation.definition_family_matches &&
                 !candidate_evaluation.shared_world_item_view)
        {
            candidate_evaluation.reject_reason = L"definition_family_mismatch";
        }
        else if (candidate_evaluation.account_id_resolved &&
                 candidate_evaluation.account_id != 0 &&
                 candidate_evaluation.account_id != expected_account_id)
        {
            candidate_evaluation.reject_reason = L"account_mismatch";
        }
        else if (candidate_evaluation.model_kind == KnifeFirstPersonRenderableModelKind::Unknown)
        {
            candidate_evaluation.reject_reason = L"unknown_model_kind";
        }
        else
        {
            candidate_evaluation.reject_reason = L"unvalidated_candidate";
        }

        if (candidate_evaluation.resolution_kind != nullptr &&
            std::wcscmp(candidate_evaluation.resolution_kind, L"rejected") != 0)
        {
            candidate_evaluation.score = 0;
            if (candidate_evaluation.validated)
            {
                candidate_evaluation.score += 64;
                if (candidate_evaluation.used_heuristic)
                {
                    candidate_evaluation.score -= 8;
                }
            }
            else if (candidate_evaluation.raw_promotable)
            {
                candidate_evaluation.score += 32;
            }

            if (candidate_evaluation.model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
            {
                candidate_evaluation.score += 16;
            }
            else if (candidate_evaluation.model_kind == KnifeFirstPersonRenderableModelKind::Unknown)
            {
                candidate_evaluation.score += 4;
            }

            if (candidate_evaluation.shared_world_item_view)
            {
                candidate_evaluation.score += 12;
            }
            if (candidate_evaluation.definition_known)
            {
                candidate_evaluation.score += 8;
            }
            if (candidate_evaluation.definition_family_matches)
            {
                candidate_evaluation.score += 6;
            }
            if (parent_definition_index != 0 &&
                candidate_evaluation.definition_index == parent_definition_index)
            {
                candidate_evaluation.score += 4;
            }
            if (candidate_evaluation.account_id_resolved)
            {
                if (candidate_evaluation.account_id == expected_account_id)
                {
                    candidate_evaluation.score += 4;
                }
                else if (candidate_evaluation.account_id == 0)
                {
                    candidate_evaluation.score += 2;
                }
            }
            if (!candidate_evaluation.model_name.empty() &&
                (ContainsAsciiInsensitive(candidate_evaluation.model_name, "weapon_knife") ||
                 ContainsAsciiInsensitive(candidate_evaluation.model_name, "/knife/") ||
                 ContainsAsciiInsensitive(candidate_evaluation.model_name, "knife_")))
            {
                candidate_evaluation.score += 2;
            }
        }

        if (candidate_samples.size() < 8)
        {
            candidate_samples.push_back(build_candidate_descriptor(candidate_evaluation));
        }

        if (candidate_evaluation.score > best_score)
        {
            best_score = candidate_evaluation.score;
            best_candidate = candidate_evaluation;
            render_entity_index = candidate_evaluation.entity_index;
            render_entity = candidate_evaluation.entity;
            render_item_view = candidate_evaluation.item_view;
            render_definition_index = candidate_evaluation.definition_index;
            render_item_view_validated = candidate_evaluation.validated;
            render_item_view_used_heuristic = candidate_evaluation.used_heuristic;
            render_item_view_has_raw = candidate_evaluation.has_raw_item_view;
        }
    }

    if (ShouldLogWatchedKnifeAnimationTrace(xuid))
    {
        std::wstringstream stream;
        stream << L"Knife first-person render child enumeration for XUID " << xuid
            << L": source=" << (source != nullptr ? source : L"unknown")
            << L", source_entity=" << source_entity_index
            << L", owner_entity=" << owner_entity_index
            << L", owner_handle=0x" << std::hex << std::uppercase << owner_handle
            << std::dec << std::nouppercase
            << L", parent_definition=" << parent_definition_index
            << L", child_count=" << child_count
            << L", max_owner_depth=" << max_owner_chain_depth
            << L", validated=" << validated_count
            << L", heuristic=" << heuristic_count
            << L", raw_promotable=" << raw_promotable_count
            << L", weapon_like=" << weapon_like_count;
        if (best_score >= 0)
        {
            stream << L", selected=" << build_candidate_descriptor(best_candidate);
        }
        else
        {
            stream << L", selected=<none>";
        }

        if (!candidate_samples.empty())
        {
            stream << L", samples=" << JoinDiagnosticSamples(candidate_samples);
        }
        else
        {
            stream << L", samples=<none>";
        }
        nskinzcs2::Logger::Info(stream.str());
    }

    return best_score >= 0 &&
        render_entity_index >= 0 &&
        render_entity != nullptr &&
        render_item_view != nullptr;
}

bool EntityLooksLikeGloveRenderable(
    void* entity_list,
    const int highest_live_entity_index,
    const int entity_index,
    void* entity,
    const ClientSchemaOffsets& offsets)
{
    if (entity == nullptr)
    {
        return false;
    }

    std::string model_name;
    if (TryReadEntityModelNameString(entity, offsets, model_name) &&
        IsLikelyGloveModelPath(model_name))
    {
        return true;
    }

    if (entity_list == nullptr || highest_live_entity_index < 0 || offsets.base_owner_entity == 0)
    {
        return false;
    }

    for (int candidate_index = 0; candidate_index <= highest_live_entity_index; ++candidate_index)
    {
        if (candidate_index == entity_index)
        {
            continue;
        }

        void* candidate = nullptr;
        if (!TryGetEntityFromIndex(entity_list, candidate_index, candidate) || candidate == nullptr)
        {
            continue;
        }

        std::uint32_t owner_handle = kInvalidEntityHandle;
        if (!SafeReadField(candidate, offsets.base_owner_entity, owner_handle) ||
            HandleToEntityIndex(owner_handle) != entity_index)
        {
            continue;
        }

        std::string child_model_name;
        if (TryReadEntityModelNameString(candidate, offsets, child_model_name) &&
            IsLikelyGloveModelPath(child_model_name))
        {
            return true;
        }
    }

    return false;
}

bool TryResolveHudArmsEntity(
    void* entity_list,
    const RuntimePlayerBinding& player_binding,
    const ClientSchemaOffsets& offsets,
    int& hud_arms_entity_index,
    void*& hud_arms_entity)
{
    hud_arms_entity_index = -1;
    hud_arms_entity = nullptr;

    if (entity_list == nullptr ||
        player_binding.pawn_entity == nullptr ||
        offsets.pawn_hud_model_arms == 0)
    {
        return false;
    }

    std::uint32_t hud_model_arms_handle = kInvalidEntityHandle;
    if (!SafeReadField(player_binding.pawn_entity, offsets.pawn_hud_model_arms, hud_model_arms_handle))
    {
        return false;
    }

    hud_arms_entity_index = HandleToEntityIndex(hud_model_arms_handle);
    if (hud_arms_entity_index < 0)
    {
        hud_arms_entity_index = -1;
        return false;
    }

    if (!TryGetEntityFromIndex(entity_list, hud_arms_entity_index, hud_arms_entity) || hud_arms_entity == nullptr)
    {
        hud_arms_entity_index = -1;
        hud_arms_entity = nullptr;
        return false;
    }

    return true;
}

struct HudArmsIdentity
{
    int entity_index = -1;
    void* entity = nullptr;
    std::uintptr_t model_state = 0;
    std::uint64_t model_handle = 0;
    std::uint64_t model_name_token = 0;
    std::uint64_t skeleton_identity_hash = 0;
    std::string model_name;
    std::string model_resource_path;
    bool entity_resolved = false;
    bool model_state_resolved = false;
    bool model_handle_resolved = false;
    bool model_name_token_resolved = false;
    bool model_name_resolved = false;
    bool skeleton_identity_resolved = false;
};

HudArmsIdentity ResolveHudArmsIdentity(
    void* entity_list,
    const RuntimePlayerBinding& player_binding,
    const ClientSchemaOffsets& offsets)
{
    HudArmsIdentity identity {};
    identity.entity_resolved =
        TryResolveHudArmsEntity(entity_list, player_binding, offsets, identity.entity_index, identity.entity);
    if (!identity.entity_resolved || identity.entity == nullptr)
    {
        return identity;
    }

    identity.model_state_resolved =
        TryResolveEntityModelStateAddress(identity.entity, offsets, identity.model_state);
    identity.model_handle_resolved =
        TryReadEntityModelHandle(identity.entity, offsets, identity.model_handle);
    identity.model_name_token_resolved =
        TryReadEntityModelNameToken(identity.entity, offsets, identity.model_name_token);
    identity.model_name_resolved =
        TryReadEntityModelNameString(identity.entity, offsets, identity.model_name);

    if (identity.model_name_resolved)
    {
        if (const auto* metadata = TryResolveModelResourceMetadata(identity.model_name); metadata != nullptr)
        {
            identity.model_resource_path =
                TryMapModelPathToResourcePath(identity.model_name).value_or(std::string {});
            identity.skeleton_identity_hash = metadata->skeleton_identity_hash;
            identity.skeleton_identity_resolved = metadata->skeleton_identity_resolved;
        }
    }

    return identity;
}

void ResolveKnifeFirstPersonProbeItemView(
    void* entity,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    void*& resolved_item_view,
    int& definition_index,
    bool& validated,
    bool& used_heuristic,
    bool& has_raw_item_view)
{
    resolved_item_view = nullptr;
    definition_index = 0;
    validated = false;
    used_heuristic = false;
    has_raw_item_view = false;

    if (entity == nullptr)
    {
        return;
    }

    auto* direct_item_view = ResolveWeaponItemView(entity, offsets);
    has_raw_item_view = direct_item_view != nullptr;
    resolved_item_view = direct_item_view;
    if (direct_item_view != nullptr &&
        IsSafeLinkedWeaponItemView(
            direct_item_view,
            offsets,
            xuid,
            parent_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            definition_index))
    {
        validated = true;
        return;
    }

    HeuristicItemViewResolution heuristic_resolution {};
    if (TryResolveHeuristicLinkedItemView(
            entity,
            offsets,
            xuid,
            parent_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            heuristic_resolution))
    {
        resolved_item_view = heuristic_resolution.item_view;
        definition_index = heuristic_resolution.definition_index;
        validated = true;
        used_heuristic = true;
    }
}

bool KnifeOwnerChainContainsEntity(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const int root_entity_index,
    void* root_entity,
    const ClientSchemaOffsets& offsets,
    const int target_entity_index,
    int& matched_depth);

const wchar_t* KnifePersistentOwnerResolutionResultText(
    const KnifePersistentOwnerResolutionResult result) noexcept
{
    switch (result)
    {
    case KnifePersistentOwnerResolutionResult::PendingConfirmation:
        return L"pending_confirmation";
    case KnifePersistentOwnerResolutionResult::PromotedRealOwner:
        return L"promoted_real_owner";
    case KnifePersistentOwnerResolutionResult::NoExposedNonSyntheticRenderOwner:
        return L"no_exposed_non_synthetic_render_owner";
    case KnifePersistentOwnerResolutionResult::Unresolved:
    default:
        return L"unresolved";
    }
}

const wchar_t* KnifeCarrierDiscoveryResultText(
    const nskinzcs2::runtime::KnifeCarrierDiscoveryResult result) noexcept
{
    switch (result)
    {
    case nskinzcs2::runtime::KnifeCarrierDiscoveryResult::RealCarrierFound:
        return L"real_carrier_found";
    case nskinzcs2::runtime::KnifeCarrierDiscoveryResult::DiscoverableIncompleteCarrier:
        return L"discoverable_incomplete_carrier";
    case nskinzcs2::runtime::KnifeCarrierDiscoveryResult::NoDiscoverableCompleteCarrier:
        return L"no_discoverable_complete_carrier";
    case nskinzcs2::runtime::KnifeCarrierDiscoveryResult::Unresolved:
    default:
        return L"unresolved";
    }
}

const wchar_t* KnifeCarrierFactoryFeasibilityText(
    const nskinzcs2::runtime::KnifeCarrierFactoryFeasibility result) noexcept
{
    switch (result)
    {
    case nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::ViewmodelFactoryPresentWithoutInstance:
        return L"viewmodel_factory_present_without_instance";
    case nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::NoViewmodelFactoryEvidence:
        return L"no_viewmodel_factory_evidence";
    case nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::Unknown:
    default:
        return L"unknown";
    }
}

const wchar_t* KnifeViewmodelAbsenceAuditResultText(
    const nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult result) noexcept
{
    switch (result)
    {
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::MissingHandle:
        return L"missing_handle";
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::StaleHandle:
        return L"stale_handle";
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::ShellWithoutWritableCarrier:
        return L"shell_without_writable_carrier";
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::NonQualifyingCandidate:
        return L"non_qualifying_candidate";
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::SyntheticAliasOnly:
        return L"synthetic_alias_only";
    case nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::Skipped:
    default:
        return L"skipped";
    }
}

std::string ToLowerAscii(std::string value)
{
    std::transform(
        value.begin(),
        value.end(),
        value.begin(),
        [](unsigned char ch)
        {
            return static_cast<char>(std::tolower(ch));
        });
    return value;
}

ClientClassDescriptor ClassifyClientClassDescriptor(
    const std::string& class_name,
    void* client_class,
    void* create_fn,
    const bool trusted_create) noexcept
{
    ClientClassDescriptor descriptor {};
    descriptor.class_name = class_name;
    descriptor.client_class = client_class;
    descriptor.create_fn = create_fn;
    descriptor.trusted_module = trusted_create;

    const auto lowered = ToLowerAscii(class_name);
    descriptor.viewmodel_like = lowered.find("viewmodel") != std::string::npos;
    descriptor.weapon_like =
        descriptor.viewmodel_like ||
        lowered.find("weapon") != std::string::npos ||
        lowered.find("knife") != std::string::npos;
    descriptor.econ_like = lowered.find("econ") != std::string::npos;
    return descriptor;
}

nskinzcs2::runtime::KnifeCarrierDiscoveryResult ResolveKnifeCarrierDiscoveryResult(
    const bool complete_candidate_found,
    const bool related_incomplete_candidate_found) noexcept
{
    if (complete_candidate_found)
    {
        return nskinzcs2::runtime::KnifeCarrierDiscoveryResult::RealCarrierFound;
    }

    return related_incomplete_candidate_found
        ? nskinzcs2::runtime::KnifeCarrierDiscoveryResult::DiscoverableIncompleteCarrier
        : nskinzcs2::runtime::KnifeCarrierDiscoveryResult::NoDiscoverableCompleteCarrier;
}

nskinzcs2::runtime::KnifeCarrierFactoryFeasibility ResolveKnifeCarrierFactoryFeasibility(
    const ClientClassDiscoverySummary& summary) noexcept
{
    if (summary.viewmodel_factory_observed || summary.weapon_factory_observed)
    {
        return nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::ViewmodelFactoryPresentWithoutInstance;
    }

    return nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::NoViewmodelFactoryEvidence;
}

nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult ClassifyKnifeViewmodelAbsenceAudit(
    const KnifeViewmodelAbsenceAudit& audit) noexcept
{
    if (!audit.ran)
    {
        return nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::Skipped;
    }

    if (audit.shared_with_render_object &&
        audit.handle_entity_synthetic &&
        (!audit.raw_entity_visible || !audit.handle_entity_item_view_safe))
    {
        return nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::SyntheticAliasOnly;
    }

    if (!audit.field_present || audit.raw_handle == kInvalidEntityHandle)
    {
        return nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::MissingHandle;
    }

    if (!audit.raw_entity_visible)
    {
        return nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::StaleHandle;
    }

    if (audit.handle_entity_shell_like &&
        (!audit.handle_entity_weapon_like ||
         !audit.handle_entity_has_item_view ||
         !audit.handle_entity_item_view_safe ||
         audit.handle_entity_synthetic))
    {
        return nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::ShellWithoutWritableCarrier;
    }

    if (!audit.handle_entity_weapon_like ||
        !audit.handle_entity_has_item_view ||
        !audit.handle_entity_item_view_safe ||
        audit.handle_entity_synthetic)
    {
        return nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::NonQualifyingCandidate;
    }

    if (audit.reverse_viewmodel_ref_count == 0 && audit.shared_with_render_object)
    {
        return nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::SyntheticAliasOnly;
    }

    return nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::Skipped;
}

KnifeRenderObjectIdentity ResolveKnifeRenderObjectIdentity(
    void* entity,
    void* item_view,
    const ClientSchemaOffsets& offsets) noexcept
{
    KnifeRenderObjectIdentity identity {};
    identity.entity = entity;
    identity.entity_resolved = entity != nullptr;
    identity.item_view = item_view;
    identity.item_view_resolved = item_view != nullptr;
    identity.model_state_resolved =
        entity != nullptr &&
        TryResolveEntityModelStateAddress(entity, offsets, identity.model_state) &&
        identity.model_state != 0;
    if (!identity.model_state_resolved)
    {
        identity.model_state = 0;
    }
    return identity;
}

bool KnifeRenderObjectIdentityMatches(
    const KnifeRenderObjectIdentity& lhs,
    const KnifeRenderObjectIdentity& rhs) noexcept
{
    if (lhs.entity_resolved &&
        rhs.entity_resolved &&
        lhs.entity != nullptr &&
        lhs.entity == rhs.entity)
    {
        return true;
    }

    return lhs.item_view_resolved &&
        rhs.item_view_resolved &&
        lhs.item_view != nullptr &&
        lhs.item_view == rhs.item_view &&
        lhs.model_state_resolved &&
        rhs.model_state_resolved &&
        lhs.model_state != 0 &&
        lhs.model_state == rhs.model_state;
}

std::wstring BuildKnifeRenderObjectIdentityDescriptor(
    const KnifeRenderObjectIdentity& identity)
{
    std::wstringstream stream;
    stream << L"{entity_ptr=" << FormatPointer(identity.entity)
        << L", item_view=" << FormatPointer(identity.item_view)
        << L", model_state="
        << (identity.model_state_resolved
                ? FormatPointer(reinterpret_cast<void*>(identity.model_state))
                : L"0x0")
        << L", entity_resolved=" << (identity.entity_resolved ? 1 : 0)
        << L", item_view_resolved=" << (identity.item_view_resolved ? 1 : 0)
        << L", model_state_resolved=" << (identity.model_state_resolved ? 1 : 0)
        << L"}";
    return stream.str();
}

std::wstring BuildClientClassDescriptorText(const ClientClassDescriptor& descriptor)
{
    std::wstringstream stream;
    stream << L"class{name=" << NarrowToWide(descriptor.class_name)
        << L", client_class=" << FormatPointer(descriptor.client_class)
        << L", create_fn=" << FormatPointer(descriptor.create_fn)
        << L", trusted=" << (descriptor.trusted_module ? 1 : 0)
        << L", viewmodel_like=" << (descriptor.viewmodel_like ? 1 : 0)
        << L", weapon_like=" << (descriptor.weapon_like ? 1 : 0)
        << L", econ_like=" << (descriptor.econ_like ? 1 : 0)
        << L"}";
    return stream.str();
}

bool ShouldKeepClientClassDiscoverySample(const ClientClassDescriptor& descriptor) noexcept
{
    return descriptor.viewmodel_like ||
        descriptor.weapon_like ||
        descriptor.econ_like ||
        descriptor.class_name == "CEconWearable";
}

bool TryDiscoverKnifeViewmodelClientClasses(
    ClientClassDiscoverySummary& summary)
{
    RuntimePerfScope performance(RuntimePerfPhase::KnifeDiscovery);
    summary = {};

    auto* client_module = GetModuleHandleW(L"client.dll");
    if (client_module == nullptr)
    {
        summary.issue = L"client.dll module handle is unavailable for GetAllClasses discovery.";
        return false;
    }

    std::array<std::pair<const wchar_t*, void*>, 2> provider_candidates {{
        {L"callback", g_hook_state.source2_client_callback_instance.load()},
        {L"interface", g_hook_state.source2_client_interface.load()},
    }};
    std::unordered_set<std::uintptr_t> attempted_candidates;
    std::vector<std::wstring> issues;
    for (const auto& [candidate_tag, provider_candidate] : provider_candidates)
    {
        if (provider_candidate == nullptr ||
            !attempted_candidates.insert(reinterpret_cast<std::uintptr_t>(provider_candidate)).second)
        {
            continue;
        }

        Source2ClientClassProviderResolution provider_resolution {};
        std::wstring provider_issue;
        if (!TryResolveWrappedSource2ClientClassProvider(
                provider_candidate,
                client_module,
                provider_resolution,
                provider_issue))
        {
            if (!provider_issue.empty())
            {
                issues.push_back(std::wstring(candidate_tag) + L": " + provider_issue);
            }
            continue;
        }

        summary.provider_resolved = true;
        WearableClientClassLayout inferred_layout {};
        int inferred_chain_length = 0;
        std::wstring layout_issue;
        if (!TryInferClientClassNameNextLayout(
                provider_resolution.client_class_chain_head,
                client_module,
                inferred_layout,
                inferred_chain_length,
                layout_issue))
        {
            if (!layout_issue.empty())
            {
                issues.push_back(std::wstring(candidate_tag) + L": " + layout_issue);
            }
            continue;
        }

        std::size_t inferred_create_offset = 0;
        std::wstring create_issue;
        if (!TryInferClientClassCreateOffset(
                provider_resolution.client_class_chain_head,
                client_module,
                inferred_layout,
                inferred_create_offset,
                create_issue))
        {
            if (!create_issue.empty())
            {
                issues.push_back(std::wstring(candidate_tag) + L": " + create_issue);
            }
            continue;
        }

        summary.layout_inferred = true;
        const auto trusted_modules =
            BuildTrustedClientClassModuleSpans(
                client_module,
                provider_resolution.client_class_chain_head);
        std::unordered_set<std::uintptr_t> visited;
        visited.reserve(256);
        auto* current = static_cast<std::uint8_t*>(provider_resolution.client_class_chain_head);
        while (current != nullptr && summary.enumerated_count < 4096)
        {
            if (!visited.insert(reinterpret_cast<std::uintptr_t>(current)).second)
            {
                break;
            }

            void* network_name_pointer = nullptr;
            void* next = nullptr;
            void* create_fn = nullptr;
            std::size_t name_encoded_size = 0;
            std::size_t next_encoded_size = 0;
            std::size_t create_encoded_size = 0;
            if (!TryResolveClientClassFieldPointerCandidate(
                    current,
                    current + inferred_layout.name_offset,
                    network_name_pointer,
                    nullptr,
                    false,
                    false,
                    &name_encoded_size) ||
                !TryResolveClientClassFieldPointerCandidate(
                    current,
                    current + inferred_layout.next_offset,
                    next,
                    nullptr,
                    true,
                    false,
                    &next_encoded_size) ||
                !TryResolveClientClassFieldPointerCandidate(
                    current,
                    current + inferred_create_offset,
                    create_fn,
                    nullptr,
                    false,
                    true,
                    &create_encoded_size))
            {
                break;
            }

            const auto* network_name = static_cast<const char*>(network_name_pointer);
            std::string network_name_value;
            if (!IsReadablePointer(network_name) ||
                !TryReadClientClassName(network_name, network_name_value) ||
                !IsReadableNullOrClientClassNodePointer(trusted_modules, next))
            {
                break;
            }

            void* resolved_create_fn = nullptr;
            std::wstring resolved_module_name;
            std::wstring resolved_kind;
            const auto trusted_create =
                TryResolveUsableClientClassCreateFunctionPointer(
                    client_module,
                    create_fn,
                    resolved_create_fn,
                    resolved_module_name,
                    resolved_kind);
            auto descriptor =
                ClassifyClientClassDescriptor(
                    network_name_value,
                    current,
                    trusted_create ? resolved_create_fn : create_fn,
                    trusted_create);
            ++summary.enumerated_count;
            if (descriptor.trusted_module)
            {
                ++summary.trusted_create_count;
            }
            if (descriptor.viewmodel_like)
            {
                ++summary.viewmodel_like_count;
            }
            if (descriptor.weapon_like)
            {
                ++summary.weapon_like_count;
            }
            if (descriptor.econ_like)
            {
                ++summary.econ_like_count;
            }
            if (descriptor.trusted_module && descriptor.viewmodel_like)
            {
                summary.viewmodel_factory_observed = true;
            }
            if (descriptor.trusted_module && descriptor.weapon_like)
            {
                summary.weapon_factory_observed = true;
            }

            if (summary.samples.size() < 8 &&
                ShouldKeepClientClassDiscoverySample(descriptor))
            {
                summary.samples.push_back(std::move(descriptor));
            }

            current = static_cast<std::uint8_t*>(next);
        }

        break;
    }

    if (!summary.provider_resolved)
    {
        summary.issue = issues.empty()
            ? L"Source2Client provider was unavailable for GetAllClasses discovery."
            : JoinDiagnosticSamples(issues);
        return false;
    }

    if (!summary.layout_inferred)
    {
        summary.issue = issues.empty()
            ? L"GetAllClasses discovery did not expose a readable client-class layout."
            : JoinDiagnosticSamples(issues);
        return false;
    }

    return true;
}

void LogKnifeViewmodelClientClassDiscovery(
    const std::uint64_t xuid,
    const ClientClassDiscoverySummary& summary)
{
    if (!ShouldLogWatchedKnifeAnimationTrace(xuid))
    {
        return;
    }

    std::wstringstream stream;
    stream << L"Knife first-person client class discovery for XUID " << xuid
        << L": provider_resolved=" << (summary.provider_resolved ? 1 : 0)
        << L", layout_inferred=" << (summary.layout_inferred ? 1 : 0)
        << L", enumerated=" << summary.enumerated_count
        << L", trusted_create=" << summary.trusted_create_count
        << L", viewmodel_like=" << summary.viewmodel_like_count
        << L", weapon_like=" << summary.weapon_like_count
        << L", econ_like=" << summary.econ_like_count
        << L", viewmodel_factory_observed=" << (summary.viewmodel_factory_observed ? 1 : 0)
        << L", weapon_factory_observed=" << (summary.weapon_factory_observed ? 1 : 0);
    if (!summary.issue.empty())
    {
        stream << L", issue=" << summary.issue;
    }
    if (!summary.samples.empty())
    {
        stream << L", samples=";
        for (std::size_t index = 0; index < summary.samples.size(); ++index)
        {
            if (index != 0)
            {
                stream << L" | ";
            }
            stream << BuildClientClassDescriptorText(summary.samples[index]);
        }
    }
    nskinzcs2::Logger::Info(stream.str());
}

KnifeViewmodelAbsenceAudit BuildKnifeViewmodelAbsenceAudit(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int world_weapon_entity_index,
    void* world_weapon_entity,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    const int providee_entity_index,
    const int viewmodel_entity_index,
    const KnifeRenderObjectIdentity& render_object)
{
    KnifeViewmodelAbsenceAudit audit {};
    audit.ran = world_weapon_entity != nullptr;
    if (!audit.ran)
    {
        return audit;
    }

    audit.field_present = offsets.econ_entity_viewmodel_attachment != 0;
    if (audit.field_present)
    {
        SafeReadField(world_weapon_entity, offsets.econ_entity_viewmodel_attachment, audit.raw_handle);
    }
    if (audit.raw_handle != kInvalidEntityHandle)
    {
        audit.handle_entity_index = HandleToEntityIndex(audit.raw_handle);
    }

    void* handle_entity = nullptr;
    if (audit.handle_entity_index >= 0 &&
        static_cast<std::size_t>(audit.handle_entity_index) < entity_cache.size())
    {
        handle_entity = entity_cache[static_cast<std::size_t>(audit.handle_entity_index)];
        audit.live_cache_visible = handle_entity != nullptr;
    }
    if (handle_entity == nullptr &&
        audit.handle_entity_index >= 0 &&
        entity_list != nullptr &&
        TryGetEntityFromIndex(entity_list, audit.handle_entity_index, handle_entity) &&
        handle_entity != nullptr)
    {
        audit.raw_entity_visible = true;
    }
    else
    {
        audit.raw_entity_visible = handle_entity != nullptr;
    }

    const auto highest_live_entity_index =
        std::max(g_hook_state.highest_live_entity_index.load(), static_cast<int>(entity_cache.size()) - 1);
    for (int entity_index = 0; entity_index <= highest_live_entity_index; ++entity_index)
    {
        void* entity = nullptr;
        if (entity_index >= 0 && static_cast<std::size_t>(entity_index) < entity_cache.size())
        {
            entity = entity_cache[static_cast<std::size_t>(entity_index)];
        }
        if (entity == nullptr &&
            (!TryGetEntityFromIndex(entity_list, entity_index, entity) || entity == nullptr))
        {
            continue;
        }

        std::uint32_t candidate_viewmodel_handle = kInvalidEntityHandle;
        if (offsets.econ_entity_viewmodel_attachment != 0 &&
            SafeReadField(entity, offsets.econ_entity_viewmodel_attachment, candidate_viewmodel_handle) &&
            HandleToEntityIndex(candidate_viewmodel_handle) == world_weapon_entity_index)
        {
            ++audit.reverse_viewmodel_ref_count;
        }
    }

    if (handle_entity != nullptr)
    {
        auto* handle_item_view = ResolveWeaponItemView(handle_entity, offsets);
        audit.handle_entity_has_item_view = handle_item_view != nullptr;
        audit.handle_entity_synthetic = IsSyntheticRuntimeEntityIndex(audit.handle_entity_index);
        audit.handle_entity_weapon_like =
            ClassifyKnifeFirstPersonRenderableModel(handle_entity, offsets) ==
            KnifeFirstPersonRenderableModelKind::WeaponLike;
        int safe_definition_index = 0;
        audit.handle_entity_item_view_safe =
            handle_item_view != nullptr &&
            IsSafeLinkedWeaponItemView(
                handle_item_view,
                offsets,
                xuid,
                parent_definition_index,
                known_definition_indices,
                knife_definition_indices,
                glove_definition_indices,
                safe_definition_index);
        audit.shared_with_render_object =
            KnifeRenderObjectIdentityMatches(
                ResolveKnifeRenderObjectIdentity(handle_entity, handle_item_view, offsets),
                render_object);

        const auto update_closest_owner_chain =
            [&](const int target_entity_index)
            {
                if (target_entity_index < 0)
                {
                    return;
                }

                int depth = -1;
                if (audit.handle_entity_index == target_entity_index)
                {
                    depth = 0;
                }
                else if (!KnifeOwnerChainContainsEntity(
                             entity_list,
                             entity_cache,
                             audit.handle_entity_index,
                             handle_entity,
                             offsets,
                             target_entity_index,
                             depth))
                {
                    return;
                }

                if (audit.closest_owner_chain_depth < 0 || depth < audit.closest_owner_chain_depth)
                {
                    audit.closest_owner_chain_depth = depth;
                    audit.closest_owner_chain_entity_index = target_entity_index;
                }
            };

        update_closest_owner_chain(player_binding.pawn_entity_index);
        update_closest_owner_chain(providee_entity_index);
        update_closest_owner_chain(viewmodel_entity_index);
        audit.handle_entity_shell_like =
            audit.raw_entity_visible &&
            (audit.handle_entity_weapon_like ||
             audit.handle_entity_has_item_view ||
             audit.shared_with_render_object ||
             audit.reverse_viewmodel_ref_count != 0 ||
             audit.closest_owner_chain_entity_index >= 0);
    }

    audit.result = ClassifyKnifeViewmodelAbsenceAudit(audit);
    return audit;
}

void LogKnifeViewmodelAbsenceAudit(
    const std::uint64_t xuid,
    const KnifeViewmodelAbsenceAudit& audit)
{
    if (!ShouldLogWatchedKnifeAnimationTrace(xuid) || !audit.ran)
    {
        return;
    }

    std::wstringstream stream;
    stream << L"Knife first-person viewmodel absence audit for XUID " << xuid
        << L": field_present=" << (audit.field_present ? 1 : 0)
        << L", raw_handle=0x" << std::hex << std::uppercase << audit.raw_handle
        << std::dec << std::nouppercase
        << L", handle_entity=" << audit.handle_entity_index
        << L", live_cache_visible=" << (audit.live_cache_visible ? 1 : 0)
        << L", raw_entity_visible=" << (audit.raw_entity_visible ? 1 : 0)
        << L", reverse_viewmodel_refs=" << audit.reverse_viewmodel_ref_count
        << L", closest_owner_chain_entity=" << audit.closest_owner_chain_entity_index
        << L", closest_owner_chain_depth=" << audit.closest_owner_chain_depth
        << L", shared_with_render_object=" << (audit.shared_with_render_object ? 1 : 0)
        << L", handle_entity_synthetic=" << (audit.handle_entity_synthetic ? 1 : 0)
        << L", handle_entity_weapon_like=" << (audit.handle_entity_weapon_like ? 1 : 0)
        << L", handle_entity_has_item_view=" << (audit.handle_entity_has_item_view ? 1 : 0)
        << L", handle_entity_item_view_safe=" << (audit.handle_entity_item_view_safe ? 1 : 0)
        << L", handle_entity_shell_like=" << (audit.handle_entity_shell_like ? 1 : 0)
        << L", result=" << KnifeViewmodelAbsenceAuditResultText(audit.result);
    nskinzcs2::Logger::Info(stream.str());
}

bool TryResolveLiveSyntheticRenderObjectFromIdentity(
    const int cached_entity_index,
    const KnifeRenderObjectIdentity& stored_identity,
    void* cached_entity,
    void* cached_item_view,
    const ClientSchemaOffsets& offsets,
    int& live_entity_index,
    void*& live_entity,
    void*& live_item_view,
    std::wstring* issue,
    const wchar_t* label)
{
    live_entity_index = -1;
    live_entity = nullptr;
    live_item_view = nullptr;
    if (issue != nullptr)
    {
        issue->clear();
    }

    if (cached_entity == nullptr)
    {
        if (issue != nullptr)
        {
            std::wstringstream stream;
            stream << (label != nullptr ? label : L"synthetic_render_object")
                << L": cached_entity_missing, entity_index=" << cached_entity_index;
            *issue = stream.str();
        }
        return false;
    }

    auto expected_identity = stored_identity;
    if (!expected_identity.IsUsable())
    {
        expected_identity =
            ResolveKnifeRenderObjectIdentity(
                cached_entity,
                cached_item_view != nullptr
                    ? cached_item_view
                    : ResolveWeaponItemView(cached_entity, offsets),
                offsets);
    }

    auto set_issue =
        [&](const wchar_t* reason, void* resolved_entity = nullptr)
        {
            if (issue == nullptr)
            {
                return;
            }

            std::wstringstream stream;
            stream << (label != nullptr ? label : L"synthetic_render_object")
                << L": " << (reason != nullptr ? reason : L"unknown")
                << L", entity_index=" << cached_entity_index
                << L", cached_entity=" << FormatPointer(cached_entity)
                << L", render_object="
                << BuildKnifeRenderObjectIdentityDescriptor(expected_identity);
            if (resolved_entity != nullptr)
            {
                stream << L", live_entity=" << FormatPointer(resolved_entity);
            }
            *issue = stream.str();
        };

    if (!expected_identity.IsUsable())
    {
        set_issue(L"render_object_identity_missing");
        return false;
    }

    auto try_candidate =
        [&](const int candidate_entity_index, void* candidate_entity) noexcept
        {
            if (candidate_entity == nullptr)
            {
                return false;
            }

            const auto candidate_item_view =
                ResolveWeaponItemView(candidate_entity, offsets);
            const auto candidate_identity =
                ResolveKnifeRenderObjectIdentity(
                    candidate_entity,
                    candidate_item_view,
                    offsets);
            if (!KnifeRenderObjectIdentityMatches(expected_identity, candidate_identity))
            {
                return false;
            }

            live_entity_index = candidate_entity_index;
            live_entity = candidate_entity;
            live_item_view = candidate_item_view;
            return true;
        };

    if (try_candidate(cached_entity_index, cached_entity))
    {
        return true;
    }

    auto* entity_list = g_hook_state.runtime_entities.last_entity_list;
    if (entity_list == nullptr)
    {
        set_issue(L"entity_list_unavailable");
        return false;
    }

    const auto highest_live_entity_index = g_hook_state.highest_live_entity_index.load();
    if (highest_live_entity_index < 0)
    {
        set_issue(L"live_entity_scan_unavailable");
        return false;
    }

    for (int entity_index = 0; entity_index <= highest_live_entity_index; ++entity_index)
    {
        void* candidate_entity = nullptr;
        if (!TryGetEntityFromIndex(entity_list, entity_index, candidate_entity) ||
            candidate_entity == nullptr)
        {
            continue;
        }

        if (try_candidate(entity_index, candidate_entity))
        {
            return true;
        }
    }

    set_issue(L"render_object_identity_mismatch");
    return false;
}

bool TryResolveLiveKnifeRenderTarget(
    const int entity_index,
    const KnifeRenderObjectIdentity& render_object,
    void* cached_entity,
    void* cached_item_view,
    const ClientSchemaOffsets& offsets,
    int& live_entity_index,
    void*& live_entity,
    void*& live_item_view,
    std::wstring* issue,
    const wchar_t* label)
{
    if (IsSyntheticRuntimeEntityIndex(entity_index))
    {
        return TryResolveLiveSyntheticRenderObjectFromIdentity(
            entity_index,
            render_object,
            cached_entity,
            cached_item_view,
            offsets,
            live_entity_index,
            live_entity,
            live_item_view,
            issue,
            label);
    }

    const auto resolved =
        TryResolveLiveEntityFromStoredBinding(
            entity_index,
            cached_entity,
            cached_item_view,
            offsets,
            live_entity,
            live_item_view,
            issue,
            label);
    if (resolved)
    {
        live_entity_index = entity_index;
    }
    return resolved;
}

std::wstring BuildKnifeFirstPersonProbeCandidateDescriptor(
    const wchar_t* source,
    const int entity_index,
    void* entity,
    void* item_view,
    const bool has_raw_item_view,
    const bool validated,
    const bool used_heuristic,
    const int definition_index,
    const std::uint32_t owner_handle,
    const int owner_index,
    const bool owner_matches_world,
    const bool shared_world_item_view,
    const KnifeFirstPersonRenderableModelKind model_kind,
    const ClientSchemaOffsets& offsets)
{
    std::wstringstream stream;
    stream << source
        << L"{entity=" << entity_index
        << L", owner_handle=0x" << std::hex << std::uppercase << owner_handle << std::dec << std::nouppercase
        << L", owner_index=" << owner_index
        << L", owner_matches_world=" << (owner_matches_world ? 1 : 0)
        << L", raw_item_view=" << (has_raw_item_view ? 1 : 0)
        << L", item_view=" << FormatPointer(item_view)
        << L", validated=" << (validated ? 1 : 0)
        << L", heuristic=" << (used_heuristic ? 1 : 0)
        << L", shared_world_item_view=" << (shared_world_item_view ? 1 : 0)
        << L", definition=" << definition_index
        << L", model_kind=" << KnifeFirstPersonRenderableModelKindText(model_kind);

    std::string model_name;
    if (TryReadEntityModelNameString(entity, offsets, model_name) && !model_name.empty())
    {
        stream << L", model_name=" << NarrowToWide(model_name);
    }

    stream << L'}';
    return stream.str();
}

std::wstring BuildKnifeOwnerChainDescriptor(
    const std::vector<void*>& entity_cache,
    const int entity_index,
    void* entity,
    const ClientSchemaOffsets& offsets,
    const int max_depth = 4)
{
    if (entity == nullptr)
    {
        return L"<none>";
    }

    std::wstringstream stream;
    std::unordered_set<void*> visited_entities;
    auto* current_entity = entity;
    auto current_entity_index = entity_index;

    for (int depth = 0; depth < max_depth && current_entity != nullptr; ++depth)
    {
        if (depth != 0)
        {
            stream << L" -> ";
        }

        if (!visited_entities.insert(current_entity).second)
        {
            stream << L"{depth=" << depth
                << L", entity=" << current_entity_index
                << L", ptr=" << FormatPointer(current_entity)
                << L", loop=1}";
            break;
        }

        auto* current_item_view = ResolveWeaponItemView(current_entity, offsets);
        int current_definition_index = 0;
        if (current_item_view != nullptr)
        {
            TryReadItemDefinitionIndex(current_item_view, offsets, current_definition_index);
        }

        std::uintptr_t current_model_state_address = 0;
        const auto current_model_state_resolved =
            TryResolveEntityModelStateAddress(current_entity, offsets, current_model_state_address) &&
            current_model_state_address != 0;
        const auto current_model_kind =
            ClassifyKnifeFirstPersonRenderableModel(current_entity, offsets);

        std::uint32_t current_owner_handle = kInvalidEntityHandle;
        const auto current_owner_handle_valid =
            offsets.base_owner_entity != 0 &&
            SafeReadField(current_entity, offsets.base_owner_entity, current_owner_handle);
        const auto current_owner_index =
            current_owner_handle_valid ? HandleToEntityIndex(current_owner_handle) : -1;

        std::string current_model_name;
        TryReadEntityModelNameString(current_entity, offsets, current_model_name);

        stream << L"{depth=" << depth
            << L", entity=" << current_entity_index
            << L", ptr=" << FormatPointer(current_entity)
            << L", item_view=" << FormatPointer(current_item_view)
            << L", definition=" << current_definition_index
            << L", model_kind=" << KnifeFirstPersonRenderableModelKindText(current_model_kind)
            << L", synthetic=" << (IsSyntheticRuntimeEntityIndex(current_entity_index) ? 1 : 0)
            << L", model_state="
            << (current_model_state_resolved
                    ? FormatPointer(reinterpret_cast<void*>(current_model_state_address))
                    : L"0x0")
            << L", owner_handle=";
        if (current_owner_handle_valid)
        {
            stream << L"0x" << std::hex << std::uppercase << current_owner_handle
                << std::dec << std::nouppercase;
        }
        else
        {
            stream << L"?";
        }
        stream << L", owner_index=" << current_owner_index;
        if (!current_model_name.empty())
        {
            stream << L", model_name=" << NarrowToWide(current_model_name);
        }
        stream << L"}";

        if (!current_owner_handle_valid ||
            current_owner_handle == kInvalidEntityHandle ||
            current_owner_index < 0)
        {
            break;
        }

        void* next_entity = nullptr;
        if (static_cast<std::size_t>(current_owner_index) < entity_cache.size())
        {
            next_entity = entity_cache[static_cast<std::size_t>(current_owner_index)];
        }

        if (next_entity == nullptr)
        {
            stream << L" -> {depth=" << (depth + 1)
                << L", entity=" << current_owner_index
                << L", ptr=<cache-miss>}";
            break;
        }

        current_entity = next_entity;
        current_entity_index = current_owner_index;
    }

    return stream.str();
}

void LogWatchedKnifeHudWeaponConsumerDeepTrace(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int world_weapon_entity_index,
    void* world_weapon_entity,
    void* world_item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    const wchar_t* selected_render_source,
    const int selected_render_entity_index,
    void* selected_render_entity,
    void* selected_render_item_view)
{
    if (!ShouldLogWatchedKnifeAnimationTrace(xuid) ||
        entity_list == nullptr ||
        world_weapon_entity == nullptr ||
        xuid == 0)
    {
        return;
    }

    auto hash_render_source =
        [](const wchar_t* source) noexcept
        {
            if (source == nullptr)
            {
                return 0x55AAull;
            }
            if (std::wcscmp(source, L"hud_scene_owner") == 0)
            {
                return 0x1001ull;
            }
            if (std::wcscmp(source, L"hud_scene_render_child") == 0)
            {
                return 0x1002ull;
            }
            if (std::wcscmp(source, L"providee_render_child") == 0)
            {
                return 0x1003ull;
            }
            if (std::wcscmp(source, L"viewmodel_render_child") == 0)
            {
                return 0x1004ull;
            }
            if (std::wcscmp(source, L"explicit_child") == 0)
            {
                return 0x1005ull;
            }
            if (std::wcscmp(source, L"explicit_render_child") == 0)
            {
                return 0x1006ull;
            }
            if (std::wcscmp(source, L"explicit_render_grandchild") == 0)
            {
                return 0x1007ull;
            }
            return 0x1FFFull;
        };

    const auto signature =
        xuid ^
        (static_cast<std::uint64_t>(static_cast<std::uint32_t>(world_weapon_entity_index)) << 32) ^
        (static_cast<std::uint64_t>(static_cast<std::uint32_t>(parent_definition_index)) << 12) ^
        (static_cast<std::uint64_t>(
             static_cast<std::uint32_t>(selected_render_entity_index >= 0 ? selected_render_entity_index : 0))
         << 3) ^
        hash_render_source(selected_render_source) ^
        0x485544434F4E5355ull;

    const auto hud_arms_identity = ResolveHudArmsIdentity(entity_list, player_binding, offsets);

    int hud_weapon_entity_index = -1;
    void* hud_weapon_entity = nullptr;
    const auto hud_weapon_resolved =
        TryResolveHudWeaponEntity(
            entity_list,
            entity_cache,
            player_binding,
            world_weapon_entity_index,
            offsets,
            hud_weapon_entity_index,
            hud_weapon_entity);
    auto* hud_weapon_item_view =
        hud_weapon_entity != nullptr ? ResolveWeaponItemView(hud_weapon_entity, offsets) : nullptr;

    int hud_render_entity_index = -1;
    void* hud_render_entity = nullptr;
    const auto hud_render_resolved =
        TryResolveHudWeaponRenderEntity(
            entity_list,
            entity_cache,
            player_binding,
            world_weapon_entity_index,
            offsets,
            hud_render_entity_index,
            hud_render_entity);
    auto* hud_render_item_view =
        hud_render_entity != nullptr ? ResolveWeaponItemView(hud_render_entity, offsets) : nullptr;

    auto resolve_model_state =
        [&](void* entity, std::uintptr_t& model_state) noexcept
        {
            model_state = 0;
            return entity != nullptr &&
                TryResolveEntityModelStateAddress(entity, offsets, model_state) &&
                model_state != 0;
        };

    std::uintptr_t selected_model_state = 0;
    const auto selected_model_state_resolved =
        resolve_model_state(selected_render_entity, selected_model_state);
    std::uintptr_t hud_weapon_model_state = 0;
    const auto hud_weapon_model_state_resolved =
        resolve_model_state(hud_weapon_entity, hud_weapon_model_state);
    std::uintptr_t hud_render_model_state = 0;
    const auto hud_render_model_state_resolved =
        resolve_model_state(hud_render_entity, hud_render_model_state);

    auto resolve_entity_from_handle =
        [&](const std::uint32_t handle) -> void*
        {
            if (handle == kInvalidEntityHandle)
            {
                return nullptr;
            }

            const auto entity_index = HandleToEntityIndex(handle);
            if (entity_index < 0)
            {
                return nullptr;
            }

            if (static_cast<std::size_t>(entity_index) < entity_cache.size() &&
                entity_cache[static_cast<std::size_t>(entity_index)] != nullptr)
            {
                return entity_cache[static_cast<std::size_t>(entity_index)];
            }

            void* entity = nullptr;
            return TryGetEntityFromIndex(entity_list, entity_index, entity) ? entity : nullptr;
        };

    auto resolve_trace_entity_index =
        [&](const int entity_index_hint, void* entity, const std::uint32_t synthetic_tag) noexcept
        {
            if (IsResolvedRuntimeEntityIndex(entity_index_hint))
            {
                return entity_index_hint;
            }

            auto resolved_entity_index = ResolveEntityIndexFromPointer(entity_cache, entity);
            if (resolved_entity_index >= 0)
            {
                return resolved_entity_index;
            }

            return entity != nullptr ? BuildSyntheticEntityIndex(entity, synthetic_tag) : -1;
        };

    struct ReverseRefSummary
    {
        int owner_ref_count = 0;
        int old_move_parent_ref_count = 0;
        int viewmodel_ref_count = 0;
        int providee_ref_count = 0;
        int scene_owner_ref_count = 0;
        std::vector<std::wstring> samples {};
    };

    auto build_reverse_ref_summary =
        [&](const int candidate_entity_index, void* candidate_entity)
        {
            ReverseRefSummary summary {};
            summary.samples.reserve(5);

            auto matches_candidate =
                [&](const std::uint32_t handle) noexcept
                {
                    if (handle == kInvalidEntityHandle)
                    {
                        return false;
                    }

                    const auto handle_entity_index = HandleToEntityIndex(handle);
                    if (candidate_entity_index >= 0 &&
                        !IsSyntheticRuntimeEntityIndex(candidate_entity_index) &&
                        handle_entity_index == candidate_entity_index)
                    {
                        return true;
                    }

                    return candidate_entity != nullptr &&
                        resolve_entity_from_handle(handle) == candidate_entity;
                };

            auto build_ref_sample =
                [&](const wchar_t* label, const int ref_entity_index, void* ref_entity)
                {
                    std::wstringstream stream;
                    stream << (label != nullptr ? label : L"ref")
                        << L"{entity=" << ref_entity_index
                        << L", ptr=" << FormatPointer(ref_entity)
                        << L", rtti=" << BuildRuntimeEntityRttiDescriptor(ref_entity);
                    std::string model_name;
                    if (TryReadEntityModelNameString(ref_entity, offsets, model_name) && !model_name.empty())
                    {
                        stream << L", model_name=" << NarrowToWide(model_name);
                    }
                    stream << L'}';
                    return stream.str();
                };

            for (std::size_t index = 0; index < entity_cache.size(); ++index)
            {
                auto* ref_entity = entity_cache[index];
                if (ref_entity == nullptr || ref_entity == candidate_entity)
                {
                    continue;
                }

                std::uint32_t owner_handle = kInvalidEntityHandle;
                if (offsets.base_owner_entity != 0 &&
                    SafeReadField(ref_entity, offsets.base_owner_entity, owner_handle) &&
                    matches_candidate(owner_handle))
                {
                    ++summary.owner_ref_count;
                    if (summary.samples.size() < 5)
                    {
                        summary.samples.push_back(
                            build_ref_sample(L"reverse_owner_ref", static_cast<int>(index), ref_entity));
                    }
                }

                std::uint32_t old_move_parent_handle = kInvalidEntityHandle;
                if (offsets.base_old_move_parent != 0 &&
                    SafeReadField(ref_entity, offsets.base_old_move_parent, old_move_parent_handle) &&
                    matches_candidate(old_move_parent_handle))
                {
                    ++summary.old_move_parent_ref_count;
                    if (summary.samples.size() < 5)
                    {
                        summary.samples.push_back(
                            build_ref_sample(L"reverse_old_move_parent_ref", static_cast<int>(index), ref_entity));
                    }
                }

                std::uint32_t viewmodel_handle = kInvalidEntityHandle;
                if (offsets.econ_entity_viewmodel_attachment != 0 &&
                    SafeReadField(ref_entity, offsets.econ_entity_viewmodel_attachment, viewmodel_handle) &&
                    matches_candidate(viewmodel_handle))
                {
                    ++summary.viewmodel_ref_count;
                    if (summary.samples.size() < 5)
                    {
                        summary.samples.push_back(
                            build_ref_sample(L"reverse_viewmodel_ref", static_cast<int>(index), ref_entity));
                    }
                }

                std::uint32_t providee_handle = kInvalidEntityHandle;
                if (offsets.econ_entity_old_providee != 0 &&
                    SafeReadField(ref_entity, offsets.econ_entity_old_providee, providee_handle) &&
                    matches_candidate(providee_handle))
                {
                    ++summary.providee_ref_count;
                    if (summary.samples.size() < 5)
                    {
                        summary.samples.push_back(
                            build_ref_sample(L"reverse_providee_ref", static_cast<int>(index), ref_entity));
                    }
                }

                void* scene_node = nullptr;
                if (offsets.base_entity_game_scene_node != 0 &&
                    offsets.game_scene_node_owner != 0 &&
                    SafeReadField(ref_entity, offsets.base_entity_game_scene_node, scene_node) &&
                    scene_node != nullptr)
                {
                    void* scene_owner_entity = nullptr;
                    if (SafeReadField(scene_node, offsets.game_scene_node_owner, scene_owner_entity) &&
                        scene_owner_entity != nullptr &&
                        scene_owner_entity == candidate_entity)
                    {
                        ++summary.scene_owner_ref_count;
                        if (summary.samples.size() < 5)
                        {
                            summary.samples.push_back(
                                build_ref_sample(L"reverse_scene_owner_ref", static_cast<int>(index), ref_entity));
                        }
                    }
                }
            }

            return summary;
        };

    struct HudWeaponConsumerTraceSample
    {
        int score = 0;
        std::wstring text;
    };

    std::vector<HudWeaponConsumerTraceSample> consumer_samples;
    consumer_samples.reserve(16);
    std::unordered_set<std::uint64_t> seen_consumers;
    std::unordered_set<std::uintptr_t> unique_entity_ptrs;
    std::unordered_set<std::uintptr_t> unique_model_states;

    auto append_consumer =
        [&](const wchar_t* source,
            const int entity_index_hint,
            void* entity,
            const int scene_depth,
            const std::uint32_t synthetic_tag)
        {
            if (entity == nullptr)
            {
                return;
            }

            const auto entity_index =
                resolve_trace_entity_index(entity_index_hint, entity, synthetic_tag);
            if (!IsResolvedRuntimeEntityIndex(entity_index))
            {
                return;
            }

            const auto consumer_key =
                (static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(entity)) >> 4) ^
                (static_cast<std::uint64_t>(scene_depth + 1) << 48) ^
                hash_render_source(source);
            if (!seen_consumers.insert(consumer_key).second)
            {
                return;
            }

            unique_entity_ptrs.insert(reinterpret_cast<std::uintptr_t>(entity));

            void* candidate_item_view = nullptr;
            int candidate_definition_index = 0;
            bool validated = false;
            bool used_heuristic = false;
            bool has_raw_item_view = false;
            ResolveKnifeFirstPersonProbeItemView(
                entity,
                offsets,
                xuid,
                parent_definition_index,
                known_definition_indices,
                knife_definition_indices,
                glove_definition_indices,
                candidate_item_view,
                candidate_definition_index,
                validated,
                used_heuristic,
                has_raw_item_view);

            if (candidate_item_view == nullptr)
            {
                candidate_item_view = ResolveWeaponItemView(entity, offsets);
            }

            std::uint32_t owner_handle = kInvalidEntityHandle;
            const auto owner_handle_readable =
                offsets.base_owner_entity != 0 &&
                SafeReadField(entity, offsets.base_owner_entity, owner_handle);
            const auto owner_index =
                owner_handle_readable ? HandleToEntityIndex(owner_handle) : -1;

            std::uint32_t viewmodel_handle = kInvalidEntityHandle;
            const auto viewmodel_handle_readable =
                offsets.econ_entity_viewmodel_attachment != 0 &&
                SafeReadField(entity, offsets.econ_entity_viewmodel_attachment, viewmodel_handle);

            std::uint32_t providee_handle = kInvalidEntityHandle;
            const auto providee_handle_readable =
                offsets.econ_entity_old_providee != 0 &&
                SafeReadField(entity, offsets.econ_entity_old_providee, providee_handle);

            const auto model_kind =
                ClassifyKnifeFirstPersonRenderableModel(entity, offsets);

            std::uintptr_t candidate_model_state = 0;
            const auto candidate_model_state_resolved =
                resolve_model_state(entity, candidate_model_state);
            if (candidate_model_state_resolved)
            {
                unique_model_states.insert(candidate_model_state);
            }

            std::uint64_t candidate_model_name_token = 0;
            const auto candidate_model_name_token_resolved =
                TryReadEntityModelNameToken(entity, offsets, candidate_model_name_token);

            const auto reverse_refs =
                build_reverse_ref_summary(entity_index, entity);

            std::wstring descriptor =
                BuildWeaponRenderConsumerEntityDiagnostic(
                    L"consumer",
                    entity_index,
                    entity,
                    candidate_item_view,
                    offsets);
            if (!descriptor.empty() && descriptor.back() == L'}')
            {
                descriptor.pop_back();
            }

            std::wstringstream suffix;
            suffix << L", source=" << (source != nullptr ? source : L"unknown")
                << L", scene_depth=" << scene_depth
                << L", owner_handle=";
            if (owner_handle_readable)
            {
                suffix << L"0x" << std::hex << std::uppercase << owner_handle
                    << std::dec << std::nouppercase;
            }
            else
            {
                suffix << L"?";
            }
            suffix << L", owner_index=" << owner_index
                << L", owner_matches_world=" << (owner_index == world_weapon_entity_index ? 1 : 0)
                << L", raw_item_view=" << (has_raw_item_view ? 1 : 0)
                << L", validated=" << (validated ? 1 : 0)
                << L", heuristic=" << (used_heuristic ? 1 : 0)
                << L", shared_world_item_view="
                << (candidate_item_view != nullptr && candidate_item_view == world_item_view ? 1 : 0)
                << L", definition=" << candidate_definition_index
                << L", model_kind=" << KnifeFirstPersonRenderableModelKindText(model_kind)
                << L", selected_ptr_alias=" << (entity == selected_render_entity ? 1 : 0)
                << L", selected_item_view_alias="
                << ((candidate_item_view != nullptr && candidate_item_view == selected_render_item_view) ? 1 : 0)
                << L", selected_model_state_alias="
                << (candidate_model_state_resolved &&
                            selected_model_state_resolved &&
                            candidate_model_state == selected_model_state
                        ? 1
                        : 0)
                << L", hud_weapon_ptr_alias=" << (entity == hud_weapon_entity ? 1 : 0)
                << L", hud_weapon_item_view_alias="
                << ((candidate_item_view != nullptr && candidate_item_view == hud_weapon_item_view) ? 1 : 0)
                << L", hud_weapon_model_state_alias="
                << (candidate_model_state_resolved &&
                            hud_weapon_model_state_resolved &&
                            candidate_model_state == hud_weapon_model_state
                        ? 1
                        : 0)
                << L", hud_render_ptr_alias=" << (entity == hud_render_entity ? 1 : 0)
                << L", hud_render_item_view_alias="
                << ((candidate_item_view != nullptr && candidate_item_view == hud_render_item_view) ? 1 : 0)
                << L", hud_render_model_state_alias="
                << (candidate_model_state_resolved &&
                            hud_render_model_state_resolved &&
                            candidate_model_state == hud_render_model_state
                        ? 1
                        : 0)
                << L", attached_viewmodel=";
            if (viewmodel_handle_readable)
            {
                suffix << HandleToEntityIndex(viewmodel_handle);
            }
            else
            {
                suffix << L"?";
            }
            suffix << L", old_providee=";
            if (providee_handle_readable)
            {
                suffix << HandleToEntityIndex(providee_handle);
            }
            else
            {
                suffix << L"?";
            }
            suffix << L", model_name_token=";
            if (candidate_model_name_token_resolved)
            {
                suffix << L"0x" << std::hex << std::uppercase << candidate_model_name_token
                    << std::dec << std::nouppercase;
            }
            else
            {
                suffix << L"?";
            }
            suffix << L", rtti=" << BuildRuntimeEntityRttiDescriptor(entity)
                << L", owner_chain="
                << BuildKnifeOwnerChainDescriptor(entity_cache, entity_index, entity, offsets)
                << L", reverse_refs={owner=" << reverse_refs.owner_ref_count
                << L", old_move_parent=" << reverse_refs.old_move_parent_ref_count
                << L", viewmodel=" << reverse_refs.viewmodel_ref_count
                << L", providee=" << reverse_refs.providee_ref_count
                << L", scene_owner=" << reverse_refs.scene_owner_ref_count << L"}";
            if (!reverse_refs.samples.empty())
            {
                suffix << L", reverse_samples=" << JoinDiagnosticSamples(reverse_refs.samples);
            }
            suffix << L'}';

            auto score = 0;
            if (entity == selected_render_entity)
            {
                score += 200;
            }
            if (entity == hud_render_entity)
            {
                score += 160;
            }
            if (entity == hud_weapon_entity)
            {
                score += 120;
            }
            if (model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
            {
                score += 40;
            }
            if (validated)
            {
                score += 20;
            }
            if (candidate_item_view != nullptr && candidate_item_view == world_item_view)
            {
                score += 10;
            }
            score -= std::max(0, scene_depth);

            consumer_samples.push_back({score, descriptor + suffix.str()});
        };

    if (hud_arms_identity.entity_resolved &&
        hud_arms_identity.entity != nullptr &&
        offsets.base_entity_game_scene_node != 0 &&
        offsets.game_scene_node_child != 0 &&
        offsets.game_scene_node_next_sibling != 0 &&
        offsets.game_scene_node_owner != 0)
    {
        void* arms_scene_node = nullptr;
        if (SafeReadField(hud_arms_identity.entity, offsets.base_entity_game_scene_node, arms_scene_node) &&
            arms_scene_node != nullptr)
        {
            struct PendingSceneNode
            {
                void* scene_node = nullptr;
                int depth = 0;
            };

            void* first_child_scene_node = nullptr;
            if (SafeReadField(arms_scene_node, offsets.game_scene_node_child, first_child_scene_node) &&
                first_child_scene_node != nullptr)
            {
                std::vector<PendingSceneNode> pending_scene_nodes;
                pending_scene_nodes.reserve(16);
                pending_scene_nodes.push_back({first_child_scene_node, 1});

                std::unordered_set<void*> visited_scene_nodes;
                while (!pending_scene_nodes.empty())
                {
                    const auto pending = pending_scene_nodes.back();
                    pending_scene_nodes.pop_back();

                    auto* child_scene_node = pending.scene_node;
                    if (child_scene_node == nullptr ||
                        !visited_scene_nodes.insert(child_scene_node).second)
                    {
                        continue;
                    }

                    void* nested_child_scene_node = nullptr;
                    if (SafeReadField(
                            child_scene_node,
                            offsets.game_scene_node_child,
                            nested_child_scene_node) &&
                        nested_child_scene_node != nullptr)
                    {
                        pending_scene_nodes.push_back({nested_child_scene_node, pending.depth + 1});
                    }

                    void* next_sibling_scene_node = nullptr;
                    if (SafeReadField(
                            child_scene_node,
                            offsets.game_scene_node_next_sibling,
                            next_sibling_scene_node) &&
                        next_sibling_scene_node != nullptr)
                    {
                        pending_scene_nodes.push_back({next_sibling_scene_node, pending.depth});
                    }

                    void* owner_entity = nullptr;
                    if (SafeReadField(child_scene_node, offsets.game_scene_node_owner, owner_entity) &&
                        owner_entity != nullptr)
                    {
                        append_consumer(
                            L"hud_scene_owner",
                            ResolveEntityIndexFromPointer(entity_cache, owner_entity),
                            owner_entity,
                            pending.depth,
                            0x48554331u);
                    }
                }
            }
        }
    }

    if (offsets.base_owner_entity != 0 && player_binding.active_weapon_handle != kInvalidEntityHandle)
    {
        for (std::size_t index = 0; index < entity_cache.size(); ++index)
        {
            auto* candidate = entity_cache[index];
            if (candidate == nullptr || candidate == world_weapon_entity)
            {
                continue;
            }

            std::uint32_t candidate_owner_handle = kInvalidEntityHandle;
            if (!SafeReadField(candidate, offsets.base_owner_entity, candidate_owner_handle) ||
                candidate_owner_handle != player_binding.active_weapon_handle)
            {
                continue;
            }

            append_consumer(
                L"explicit_child",
                static_cast<int>(index),
                candidate,
                0,
                0x48554332u);
        }
    }

    if (hud_weapon_resolved)
    {
        append_consumer(
            L"hud_resolved_weapon",
            hud_weapon_entity_index,
            hud_weapon_entity,
            0,
            0x48554333u);
    }

    if (hud_render_resolved)
    {
        append_consumer(
            L"hud_resolved_render",
            hud_render_entity_index,
            hud_render_entity,
            0,
            0x48554334u);
    }

    if (selected_render_entity != nullptr)
    {
        append_consumer(
            selected_render_source != nullptr ? selected_render_source : L"selected_render",
            selected_render_entity_index,
            selected_render_entity,
            0,
            0x48554335u);
    }

    std::sort(
        consumer_samples.begin(),
        consumer_samples.end(),
        [](const HudWeaponConsumerTraceSample& lhs, const HudWeaponConsumerTraceSample& rhs)
        {
            if (lhs.score != rhs.score)
            {
                return lhs.score > rhs.score;
            }
            return lhs.text < rhs.text;
        });

    constexpr std::size_t kMaxConsumerSamples = 8;
    if (consumer_samples.size() > kMaxConsumerSamples)
    {
        consumer_samples.resize(kMaxConsumerSamples);
    }

    std::vector<std::wstring> consumer_text;
    consumer_text.reserve(consumer_samples.size());
    for (const auto& sample : consumer_samples)
    {
        consumer_text.push_back(sample.text);
    }

    std::wstringstream summary;
    summary << L"Knife HUD weapon consumer deep trace for XUID " << xuid
        << L": world_entity=" << world_weapon_entity_index
        << L", parent_definition=" << parent_definition_index
        << L", selected_source=" << (selected_render_source != nullptr ? selected_render_source : L"none")
        << L", selected_entity=" << selected_render_entity_index
        << L", selected_ptr=" << FormatPointer(selected_render_entity)
        << L", selected_item_view=" << FormatPointer(selected_render_item_view)
        << L", selected_model_state="
        << (selected_model_state_resolved
                ? FormatPointer(reinterpret_cast<void*>(selected_model_state))
                : L"0x0")
        << L", hud_arms_entity=" << hud_arms_identity.entity_index
        << L", hud_arms_ptr=" << FormatPointer(hud_arms_identity.entity);
    if (hud_arms_identity.model_name_resolved && !hud_arms_identity.model_name.empty())
    {
        summary << L", hud_arms_model=" << NarrowToWide(hud_arms_identity.model_name);
    }
    summary << L", hud_weapon_resolved=" << (hud_weapon_resolved ? 1 : 0)
        << L", hud_weapon_entity=" << hud_weapon_entity_index
        << L", hud_weapon_ptr=" << FormatPointer(hud_weapon_entity)
        << L", hud_weapon_model_state="
        << (hud_weapon_model_state_resolved
                ? FormatPointer(reinterpret_cast<void*>(hud_weapon_model_state))
                : L"0x0")
        << L", hud_render_resolved=" << (hud_render_resolved ? 1 : 0)
        << L", hud_render_entity=" << hud_render_entity_index
        << L", hud_render_ptr=" << FormatPointer(hud_render_entity)
        << L", hud_render_model_state="
        << (hud_render_model_state_resolved
                ? FormatPointer(reinterpret_cast<void*>(hud_render_model_state))
                : L"0x0")
        << L", sampled_consumers=" << consumer_text.size()
        << L", unique_ptrs=" << unique_entity_ptrs.size()
        << L", unique_model_states=" << unique_model_states.size();
    LogProfileDiagnosticOnce(signature, summary.str());

    std::wstringstream details;
    details << L"Knife HUD weapon consumer deep trace consumers for XUID " << xuid
        << L": samples=" << JoinDiagnosticSamples(consumer_text);
    LogProfileDiagnosticOnce(signature ^ 0x01ull, details.str());
}

void LogWatchedKnifeSyntheticShellBacktrace(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int world_weapon_entity_index,
    void* world_weapon_entity,
    void* world_item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const wchar_t* source,
    const int shell_entity_index,
    void* shell_entity,
    void* shell_item_view)
{
    if (!ShouldLogWatchedKnifeAnimationTrace(xuid) ||
        shell_entity == nullptr ||
        shell_entity_index < 0 ||
        !IsSyntheticRuntimeEntityIndex(shell_entity_index) ||
        !IsStickyKnifeFirstPersonRenderSourceEligible(source))
    {
        return;
    }

    auto signature =
        xuid ^
        (static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(shell_entity)) >> 4) ^
        0x4B5348454C4Cull;
    if (source != nullptr)
    {
        if (std::wcscmp(source, L"providee_render_child") == 0)
        {
            signature ^= 0x1001ull;
        }
        else if (std::wcscmp(source, L"hud_scene_owner") == 0)
        {
            signature ^= 0x1002ull;
        }
        else if (std::wcscmp(source, L"hud_scene_render_child") == 0)
        {
            signature ^= 0x1003ull;
        }
        else if (std::wcscmp(source, L"viewmodel_render_child") == 0)
        {
            signature ^= 0x1004ull;
        }
        else if (std::wcscmp(source, L"explicit_render_child") == 0)
        {
            signature ^= 0x1005ull;
        }
        else if (std::wcscmp(source, L"explicit_render_grandchild") == 0)
        {
            signature ^= 0x1006ull;
        }
    }

    auto format_optional_handle =
        [](const bool readable, const std::uint32_t raw_handle)
        {
            if (!readable)
            {
                return std::wstring(L"?");
            }

            std::wstringstream stream;
            stream << L"0x" << std::hex << std::uppercase << raw_handle
                << std::dec << std::nouppercase;
            return stream.str();
        };

    auto format_definition =
        [&](void* item_view)
        {
            if (item_view == nullptr)
            {
                return std::wstring(L"?");
            }

            int definition_index = 0;
            return TryReadItemDefinitionIndex(item_view, offsets, definition_index)
                ? std::to_wstring(definition_index)
                : std::wstring(L"?");
        };

    std::uint32_t shell_owner_handle = kInvalidEntityHandle;
    const auto shell_owner_handle_readable =
        offsets.base_owner_entity != 0 &&
        SafeReadField(shell_entity, offsets.base_owner_entity, shell_owner_handle);
    const auto shell_owner_index =
        shell_owner_handle_readable ? HandleToEntityIndex(shell_owner_handle) : -1;

    void* shell_owner_entity = nullptr;
    if (shell_owner_index >= 0)
    {
        if (static_cast<std::size_t>(shell_owner_index) < entity_cache.size())
        {
            shell_owner_entity = entity_cache[static_cast<std::size_t>(shell_owner_index)];
        }
        if (shell_owner_entity == nullptr)
        {
            TryGetEntityFromIndex(entity_list, shell_owner_index, shell_owner_entity);
        }
    }

    auto* shell_owner_item_view =
        shell_owner_entity != nullptr ? ResolveWeaponItemView(shell_owner_entity, offsets) : nullptr;
    const auto shell_owner_item_view_matches_world =
        shell_owner_item_view != nullptr && shell_owner_item_view == world_item_view;

    int hud_weapon_entity_index = -1;
    void* hud_weapon_entity = nullptr;
    const auto hud_weapon_resolved =
        TryResolveHudWeaponEntity(
            entity_list,
            entity_cache,
            player_binding,
            world_weapon_entity_index,
            offsets,
            hud_weapon_entity_index,
            hud_weapon_entity);

    int hud_render_entity_index = -1;
    void* hud_render_entity = nullptr;
    const auto hud_render_resolved =
        TryResolveHudWeaponRenderEntity(
            entity_list,
            entity_cache,
            player_binding,
            world_weapon_entity_index,
            offsets,
            hud_render_entity_index,
            hud_render_entity);

    std::wstringstream stream;
    stream << L"Knife synthetic shell backtrace for XUID " << xuid
        << L": source=" << (source != nullptr ? source : L"none")
        << L", shell_entity=" << shell_entity_index
        << L", shell_ptr=" << FormatPointer(shell_entity)
        << L", alias_render_child=" << BuildSyntheticEntityIndex(shell_entity, 0x4B465243u)
        << L", alias_hud_scene_owner=" << BuildSyntheticEntityIndex(shell_entity, 0x4B464850u)
        << L", alias_hud_weapon=" << BuildSyntheticEntityIndex(shell_entity, 0x48554457u)
        << L", shell_definition=" << format_definition(shell_item_view)
        << L", world_definition=" << format_definition(world_item_view)
        << L", shell_item_view_matches_world=" << (shell_item_view == world_item_view ? 1 : 0)
        << L", shell_owner_handle=" << format_optional_handle(shell_owner_handle_readable, shell_owner_handle)
        << L", shell_owner_index=" << shell_owner_index
        << L", shell_owner_is_world=" << (shell_owner_index == world_weapon_entity_index ? 1 : 0)
        << L", shell_owner_item_view=" << FormatPointer(shell_owner_item_view)
        << L", shell_owner_definition=" << format_definition(shell_owner_item_view)
        << L", shell_owner_item_view_matches_world=" << (shell_owner_item_view_matches_world ? 1 : 0)
        << L", shell_item_view_matches_owner=" << (shell_item_view == shell_owner_item_view ? 1 : 0)
        << L", world_entity_ptr=" << FormatPointer(world_weapon_entity)
        << L", watched_pawn_entity=" << player_binding.pawn_entity_index
        << L", watched_pawn_ptr=" << FormatPointer(player_binding.pawn_entity)
        << L", hud_weapon_resolved=" << (hud_weapon_resolved ? 1 : 0)
        << L", hud_weapon_entity=" << hud_weapon_entity_index
        << L", hud_weapon_same_ptr=" << (hud_weapon_entity == shell_entity ? 1 : 0)
        << L", hud_weapon_same_item_view="
        << ((hud_weapon_entity != nullptr &&
             ResolveWeaponItemView(hud_weapon_entity, offsets) == shell_item_view)
                ? 1
                : 0)
        << L", hud_render_resolved=" << (hud_render_resolved ? 1 : 0)
        << L", hud_render_entity=" << hud_render_entity_index
        << L", hud_render_same_ptr=" << (hud_render_entity == shell_entity ? 1 : 0)
        << L", hud_render_same_item_view="
        << ((hud_render_entity != nullptr &&
             ResolveWeaponItemView(hud_render_entity, offsets) == shell_item_view)
                ? 1
                : 0)
        << L", shell_rtti=" << BuildRuntimeEntityRttiDescriptor(shell_entity)
        << L", shell_diag="
        << BuildWeaponRenderConsumerEntityDiagnostic(
               L"shell",
               shell_entity_index,
               shell_entity,
               shell_item_view,
               offsets)
        << L", shell_chain="
        << BuildKnifeOwnerChainDescriptor(entity_cache, shell_entity_index, shell_entity, offsets);

    if (shell_owner_entity != nullptr)
    {
        stream << L", shell_owner_diag="
            << BuildWeaponRenderConsumerEntityDiagnostic(
                   L"shell_owner",
                   shell_owner_index,
                   shell_owner_entity,
                   shell_owner_item_view,
                   offsets)
            << L", shell_owner_rtti=" << BuildRuntimeEntityRttiDescriptor(shell_owner_entity)
            << L", shell_owner_chain="
            << BuildKnifeOwnerChainDescriptor(
                   entity_cache,
                   shell_owner_index,
                   shell_owner_entity,
                   offsets);
    }

    if (hud_weapon_entity != nullptr)
    {
        auto* hud_weapon_item_view = ResolveWeaponItemView(hud_weapon_entity, offsets);
        stream << L", hud_weapon_diag="
            << BuildWeaponRenderConsumerEntityDiagnostic(
                   L"hud_weapon",
                   hud_weapon_entity_index,
                   hud_weapon_entity,
                   hud_weapon_item_view,
                   offsets)
            << L", hud_weapon_rtti=" << BuildRuntimeEntityRttiDescriptor(hud_weapon_entity)
            << L", hud_weapon_chain="
            << BuildKnifeOwnerChainDescriptor(
                   entity_cache,
                   hud_weapon_entity_index,
                   hud_weapon_entity,
                   offsets);
    }

    if (hud_render_entity != nullptr && hud_render_entity != hud_weapon_entity)
    {
        auto* hud_render_item_view = ResolveWeaponItemView(hud_render_entity, offsets);
        stream << L", hud_render_diag="
            << BuildWeaponRenderConsumerEntityDiagnostic(
                   L"hud_render",
                   hud_render_entity_index,
                   hud_render_entity,
                   hud_render_item_view,
                   offsets)
            << L", hud_render_rtti=" << BuildRuntimeEntityRttiDescriptor(hud_render_entity)
            << L", hud_render_chain="
            << BuildKnifeOwnerChainDescriptor(
                   entity_cache,
                   hud_render_entity_index,
                   hud_render_entity,
                   offsets);
    }

    LogProfileDiagnosticOnce(signature, stream.str());
}

struct KnifeOwnerChainRenderableOwnerCandidate
{
    int entity_index = -1;
    void* entity = nullptr;
    void* item_view = nullptr;
    int definition_index = 0;
    KnifeFirstPersonRenderableModelKind model_kind =
        KnifeFirstPersonRenderableModelKind::Unknown;
    int depth = -1;
};

bool TryResolveKnifeOwnerChainEntity(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const int entity_index,
    void*& entity)
{
    entity = nullptr;
    if (entity_index < 0 || IsSyntheticRuntimeEntityIndex(entity_index))
    {
        return false;
    }

    if (static_cast<std::size_t>(entity_index) < entity_cache.size())
    {
        entity = entity_cache[static_cast<std::size_t>(entity_index)];
    }

    return entity != nullptr ||
        (TryGetEntityFromIndex(entity_list, entity_index, entity) && entity != nullptr);
}

bool KnifeOwnerChainContainsEntity(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const int root_entity_index,
    void* root_entity,
    const ClientSchemaOffsets& offsets,
    const int target_entity_index,
    int& matched_depth)
{
    matched_depth = -1;
    if (root_entity == nullptr ||
        target_entity_index < 0 ||
        offsets.base_owner_entity == 0)
    {
        return false;
    }

    std::unordered_set<void*> visited_entities;
    auto* current_entity = root_entity;
    auto current_entity_index = root_entity_index;
    for (int depth = 0; depth < 6 && current_entity != nullptr; ++depth)
    {
        if (!visited_entities.insert(current_entity).second)
        {
            break;
        }

        if (current_entity_index == target_entity_index)
        {
            matched_depth = depth;
            return true;
        }

        std::uint32_t owner_handle = kInvalidEntityHandle;
        if (!SafeReadField(current_entity, offsets.base_owner_entity, owner_handle) ||
            owner_handle == kInvalidEntityHandle)
        {
            break;
        }

        const auto owner_entity_index = HandleToEntityIndex(owner_handle);
        if (owner_entity_index < 0)
        {
            break;
        }

        void* owner_entity = nullptr;
        if (!TryResolveKnifeOwnerChainEntity(
                entity_list,
                entity_cache,
                owner_entity_index,
                owner_entity))
        {
            break;
        }

        current_entity = owner_entity;
        current_entity_index = owner_entity_index;
    }

    return false;
}

bool TryResolveStickyKnifeFirstPersonRenderTarget(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int world_entity_index,
    const int world_render_entity_index,
    void* world_render_entity,
    const int first_person_entity_index,
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind,
    int& render_entity_index,
    void*& render_entity,
    void*& render_item_view,
    const wchar_t*& render_source,
    int& owner_chain_depth)
{
    render_entity_index = -1;
    render_entity = nullptr;
    render_item_view = nullptr;
    render_source = L"owner";
    owner_chain_depth = -1;

    const auto state = g_hook_state.knife_model_path_state;
    if (!state.active ||
        !KnifeModelPathStateMatchesCurrentRefreshEpoch(state) ||
        state.xuid != xuid ||
        state.world_entity_index != world_entity_index ||
        state.world_render_entity_index != world_render_entity_index ||
        state.first_person_entity_index != first_person_entity_index ||
        state.owner_kind != owner_kind ||
        state.first_person_render_entity == nullptr ||
        state.first_person_render_entity_index == state.first_person_entity_index ||
        !IsStickyKnifeFirstPersonRenderSourceEligible(state.first_person_render_source))
    {
        return false;
    }

    if (state.first_person_render_entity == world_render_entity ||
        state.first_person_render_entity_index == world_render_entity_index)
    {
        return false;
    }

    int live_render_entity_index = -1;
    void* live_render_entity = nullptr;
    void* live_render_item_view = nullptr;
    std::wstring revalidation_issue;
    if (!TryResolveLiveKnifeRenderTarget(
            state.first_person_render_entity_index,
            state.first_person_render_object,
            state.first_person_render_entity,
            state.first_person_render_item_view,
            offsets,
            live_render_entity_index,
            live_render_entity,
            live_render_item_view,
            &revalidation_issue,
            L"sticky_first_person_render"))
    {
        return false;
    }

    if (live_render_entity == nullptr ||
        ClassifyKnifeFirstPersonRenderableModel(live_render_entity, offsets) !=
            KnifeFirstPersonRenderableModelKind::WeaponLike)
    {
        return false;
    }

    std::uintptr_t model_state_address = 0;
    if (!TryResolveEntityModelStateAddress(live_render_entity, offsets, model_state_address) ||
        model_state_address == 0)
    {
        return false;
    }

    if (!KnifeOwnerChainContainsEntity(
            entity_list,
            entity_cache,
            live_render_entity_index,
            live_render_entity,
            offsets,
            first_person_entity_index,
            owner_chain_depth))
    {
        return false;
    }

    render_entity_index = live_render_entity_index;
    render_entity = live_render_entity;
    render_item_view =
        live_render_item_view != nullptr
            ? live_render_item_view
            : state.first_person_render_item_view;
    render_source = state.first_person_render_source;
    return true;
}

bool TryResolveKnifeRenderableOwnerFromOwnerChain(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    void* clue_entity,
    const int world_weapon_entity_index,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    KnifeOwnerChainRenderableOwnerCandidate& candidate)
{
    candidate = {};
    if (clue_entity == nullptr || offsets.base_owner_entity == 0)
    {
        return false;
    }

    const auto expected_account_id = AccountIdFromXuid(xuid);
    std::unordered_set<void*> visited_entities;
    auto* current_entity = clue_entity;
    for (int depth = 0; depth < 6 && current_entity != nullptr; ++depth)
    {
        if (!visited_entities.insert(current_entity).second)
        {
            break;
        }

        std::uint32_t owner_handle = kInvalidEntityHandle;
        if (!SafeReadField(current_entity, offsets.base_owner_entity, owner_handle) ||
            owner_handle == kInvalidEntityHandle)
        {
            break;
        }

        const auto owner_entity_index = HandleToEntityIndex(owner_handle);
        if (owner_entity_index < 0)
        {
            break;
        }

        void* owner_entity = nullptr;
        if (!TryResolveKnifeOwnerChainEntity(
                entity_list,
                entity_cache,
                owner_entity_index,
                owner_entity))
        {
            break;
        }

        const auto owner_model_kind =
            ClassifyKnifeFirstPersonRenderableModel(owner_entity, offsets);
        auto* owner_item_view = ResolveWeaponItemView(owner_entity, offsets);

        bool valid_owner = owner_item_view != nullptr &&
            !IsSyntheticRuntimeEntityIndex(owner_entity_index) &&
            owner_entity_index != world_weapon_entity_index &&
            (owner_model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike ||
             owner_model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike);
        int resolved_definition_index = 0;
        if (valid_owner && owner_model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
        {
            valid_owner =
                IsSafeLinkedWeaponItemView(
                    owner_item_view,
                    offsets,
                    xuid,
                    parent_definition_index,
                    known_definition_indices,
                    knife_definition_indices,
                    glove_definition_indices,
                    resolved_definition_index);
        }
        else if (valid_owner)
        {
            if (offsets.item_view_account_id != 0)
            {
                std::uint32_t account_id = 0;
                if (SafeReadField(owner_item_view, offsets.item_view_account_id, account_id) &&
                    account_id != 0 &&
                    account_id != expected_account_id)
                {
                    valid_owner = false;
                }
            }

            if (valid_owner)
            {
                int raw_definition_index = 0;
                TryReadItemDefinitionIndex(owner_item_view, offsets, raw_definition_index);
                resolved_definition_index =
                    parent_definition_index != 0
                        ? parent_definition_index
                        : raw_definition_index;
                valid_owner = resolved_definition_index != 0;
            }
        }

        if (valid_owner)
        {
            candidate.entity_index = owner_entity_index;
            candidate.entity = owner_entity;
            candidate.item_view = owner_item_view;
            candidate.definition_index = resolved_definition_index;
            candidate.model_kind = owner_model_kind;
            candidate.depth = depth + 1;
        }

        current_entity = owner_entity;
    }

    return candidate.entity != nullptr;
}

bool TryResolveKnifeSceneOwnedRenderChild(
    const std::vector<void*>& entity_cache,
    const wchar_t* source,
    const int source_entity_index,
    void* source_entity,
    const int world_entity_index,
    void* world_item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    int& render_entity_index,
    void*& render_entity,
    void*& render_item_view,
    int& render_definition_index,
    bool& render_item_view_validated,
    bool& render_item_view_used_heuristic,
    bool& render_item_view_has_raw)
{
    render_entity_index = -1;
    render_entity = nullptr;
    render_item_view = nullptr;
    render_definition_index = 0;
    render_item_view_validated = false;
    render_item_view_used_heuristic = false;
    render_item_view_has_raw = false;

    if (source_entity == nullptr ||
        offsets.base_entity_game_scene_node == 0 ||
        offsets.game_scene_node_child == 0 ||
        offsets.game_scene_node_next_sibling == 0 ||
        offsets.game_scene_node_owner == 0)
    {
        return false;
    }

    struct NestedRenderCandidate
    {
        int entity_index = -1;
        void* entity = nullptr;
        void* item_view = nullptr;
        int scene_depth = 0;
        int definition_index = 0;
        bool validated = false;
        bool used_heuristic = false;
        bool has_raw_item_view = false;
        bool shared_world_item_view = false;
        bool same_world_entity = false;
        bool same_source_entity = false;
        bool render_proxy_only = false;
        bool model_state_resolved = false;
        KnifeFirstPersonRenderableModelKind model_kind =
            KnifeFirstPersonRenderableModelKind::Unknown;
        std::uint32_t owner_handle = kInvalidEntityHandle;
        int owner_index = -1;
        std::string model_name;
        const wchar_t* resolution_kind = L"rejected";
        const wchar_t* reject_reason = L"none";
        int score = -1;
    };

    auto build_candidate_descriptor =
        [&](const NestedRenderCandidate& candidate)
        {
            std::wstringstream stream;
            stream << BuildKnifeFirstPersonProbeCandidateDescriptor(
                source != nullptr ? source : L"render_child",
                candidate.entity_index,
                candidate.entity,
                candidate.item_view,
                candidate.has_raw_item_view,
                candidate.validated,
                candidate.used_heuristic,
                candidate.definition_index,
                candidate.owner_handle,
                candidate.owner_index,
                candidate.same_world_entity,
                candidate.shared_world_item_view,
                candidate.model_kind,
                offsets);

            auto descriptor = stream.str();
            if (!descriptor.empty() && descriptor.back() == L'}')
            {
                descriptor.pop_back();
            }

            std::wstringstream suffix;
            suffix << L", source_self=" << (candidate.same_source_entity ? 1 : 0)
                << L", scene_depth=" << candidate.scene_depth
                << L", render_proxy_only=" << (candidate.render_proxy_only ? 1 : 0)
                << L", model_state=" << (candidate.model_state_resolved ? 1 : 0)
                << L", resolution=" << candidate.resolution_kind
                << L", reject_reason=" << candidate.reject_reason
                << L", score=" << candidate.score
                << L'}';
            descriptor += suffix.str();
            return descriptor;
        };

    void* source_scene_node = nullptr;
    if (!SafeReadField(source_entity, offsets.base_entity_game_scene_node, source_scene_node) ||
        source_scene_node == nullptr)
    {
        return false;
    }

    void* first_child_scene_node = nullptr;
    if (!SafeReadField(source_scene_node, offsets.game_scene_node_child, first_child_scene_node) ||
        first_child_scene_node == nullptr)
    {
        return false;
    }

    struct PendingSceneNode
    {
        void* scene_node = nullptr;
        int depth = 0;
    };

    NestedRenderCandidate best_candidate {};
    int best_score = -1;
    int child_count = 0;
    int validated_count = 0;
    int weapon_like_count = 0;
    int render_proxy_only_count = 0;
    int max_scene_depth = 0;
    std::vector<std::wstring> samples;
    std::vector<std::wstring> owner_chain_samples;
    samples.reserve(6);
    owner_chain_samples.reserve(12);

    std::vector<PendingSceneNode> pending_scene_nodes;
    pending_scene_nodes.reserve(16);
    pending_scene_nodes.push_back({first_child_scene_node, 1});
    std::unordered_set<void*> visited_scene_nodes;
    while (!pending_scene_nodes.empty())
    {
        const auto pending = pending_scene_nodes.back();
        pending_scene_nodes.pop_back();
        auto* child_scene_node = pending.scene_node;
        if (child_scene_node == nullptr ||
            !visited_scene_nodes.insert(child_scene_node).second)
        {
            continue;
        }

        void* nested_child_scene_node = nullptr;
        if (SafeReadField(child_scene_node, offsets.game_scene_node_child, nested_child_scene_node) &&
            nested_child_scene_node != nullptr)
        {
            pending_scene_nodes.push_back({nested_child_scene_node, pending.depth + 1});
        }

        void* next_sibling_scene_node = nullptr;
        if (SafeReadField(child_scene_node, offsets.game_scene_node_next_sibling, next_sibling_scene_node) &&
            next_sibling_scene_node != nullptr)
        {
            pending_scene_nodes.push_back({next_sibling_scene_node, pending.depth});
        }

        void* owner_entity = nullptr;
        if (SafeReadField(child_scene_node, offsets.game_scene_node_owner, owner_entity) &&
            owner_entity != nullptr)
        {
            ++child_count;

            NestedRenderCandidate candidate {};
            candidate.entity = owner_entity;
            candidate.scene_depth = pending.depth;
            candidate.entity_index = ResolveEntityIndexFromPointer(entity_cache, owner_entity);
            if (candidate.entity_index < 0)
            {
                candidate.entity_index = BuildSyntheticEntityIndex(owner_entity, 0x4B465243u);
            }

            ResolveKnifeFirstPersonProbeItemView(
                owner_entity,
                offsets,
                xuid,
                parent_definition_index,
                known_definition_indices,
                knife_definition_indices,
                glove_definition_indices,
                candidate.item_view,
                candidate.definition_index,
                candidate.validated,
                candidate.used_heuristic,
                candidate.has_raw_item_view);
            candidate.model_kind = ClassifyKnifeFirstPersonRenderableModel(owner_entity, offsets);
            candidate.same_world_entity =
                world_entity_index >= 0 &&
                candidate.entity_index == world_entity_index;
            candidate.same_source_entity =
                candidate.entity == source_entity &&
                candidate.entity_index == source_entity_index;
            candidate.shared_world_item_view =
                candidate.item_view != nullptr &&
                world_item_view != nullptr &&
                candidate.item_view == world_item_view;
            candidate.model_state_resolved =
                [&]() noexcept
                {
                    std::uintptr_t model_state_address = 0;
                    return TryResolveEntityModelStateAddress(
                               owner_entity,
                               offsets,
                               model_state_address) &&
                        model_state_address != 0;
                }();
            candidate.render_proxy_only =
                !candidate.validated &&
                candidate.model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike &&
                candidate.model_state_resolved;
            if (offsets.base_owner_entity != 0)
            {
                SafeReadField(owner_entity, offsets.base_owner_entity, candidate.owner_handle);
            }
            candidate.owner_index = HandleToEntityIndex(candidate.owner_handle);
            TryReadEntityModelNameString(owner_entity, offsets, candidate.model_name);

            if (candidate.validated)
            {
                ++validated_count;
            }
            if (candidate.model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
            {
                ++weapon_like_count;
            }
            if (candidate.render_proxy_only)
            {
                ++render_proxy_only_count;
            }
            max_scene_depth = std::max(max_scene_depth, candidate.scene_depth);

            if (candidate.same_source_entity)
            {
                candidate.reject_reason = L"source_self";
            }
            else if (candidate.same_world_entity)
            {
                candidate.reject_reason = L"world_entity_self_promotion";
            }
            else if (candidate.model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike)
            {
                candidate.reject_reason = L"character_like";
            }
            else if (candidate.validated)
            {
                candidate.resolution_kind =
                    candidate.used_heuristic ? L"heuristic" : L"validated";
            }
            else if (candidate.render_proxy_only)
            {
                candidate.resolution_kind = L"render_proxy";
            }
            else if (candidate.item_view == nullptr)
            {
                candidate.reject_reason = L"item_view_missing";
            }
            else
            {
                candidate.reject_reason = L"unvalidated_render_child";
            }

            if (candidate.resolution_kind != nullptr &&
                std::wcscmp(candidate.resolution_kind, L"rejected") != 0)
            {
                candidate.score = 0;
                if (candidate.validated)
                {
                    candidate.score += 64;
                    if (candidate.used_heuristic)
                    {
                        candidate.score -= 8;
                    }
                }
                else if (candidate.render_proxy_only)
                {
                    candidate.score += 28;
                }

                if (candidate.model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
                {
                    candidate.score += 16;
                }
                if (candidate.shared_world_item_view)
                {
                    candidate.score += 12;
                }
                if (!IsSyntheticRuntimeEntityIndex(candidate.entity_index))
                {
                    candidate.score += 8;
                }
                if (candidate.model_state_resolved)
                {
                    candidate.score += 4;
                }
            }

            if (samples.size() < 6)
            {
                samples.push_back(build_candidate_descriptor(candidate));
            }
            if (owner_chain_samples.size() < 12)
            {
                std::wstringstream chain_stream;
                chain_stream << (source != nullptr ? source : L"render_child")
                    << L"{entity=" << candidate.entity_index
                    << L", scene_depth=" << candidate.scene_depth
                    << L", resolution=" << candidate.resolution_kind
                    << L", reject_reason=" << candidate.reject_reason
                    << L", owner_chain="
                    << BuildKnifeOwnerChainDescriptor(
                           entity_cache,
                           candidate.entity_index,
                           candidate.entity,
                           offsets)
                    << L"}";
                owner_chain_samples.push_back(chain_stream.str());
            }

            if (candidate.score > best_score)
            {
                best_score = candidate.score;
                best_candidate = candidate;
                render_entity_index = candidate.entity_index;
                render_entity = candidate.entity;
                render_item_view = candidate.item_view;
                render_definition_index = candidate.definition_index;
                render_item_view_validated = candidate.validated;
                render_item_view_used_heuristic = candidate.used_heuristic;
                render_item_view_has_raw = candidate.has_raw_item_view;
            }
        }

    }

    if (ShouldLogWatchedKnifeAnimationTrace(xuid))
    {
        std::wstringstream stream;
        stream << L"Knife direct render child enumeration for XUID " << xuid
            << L": source=" << (source != nullptr ? source : L"unknown")
            << L", source_entity=" << source_entity_index
            << L", source_chain="
            << BuildKnifeOwnerChainDescriptor(
                   entity_cache,
                   source_entity_index,
                   source_entity,
                   offsets)
            << L", child_count=" << child_count
            << L", max_depth=" << max_scene_depth
            << L", validated=" << validated_count
            << L", weapon_like=" << weapon_like_count
            << L", render_proxy_only=" << render_proxy_only_count;
        if (best_score >= 0)
        {
            stream << L", selected=" << build_candidate_descriptor(best_candidate);
        }
        else
        {
            stream << L", selected=<none>";
        }
        if (!samples.empty())
        {
            stream << L", samples=" << JoinDiagnosticSamples(samples);
        }
        if (!owner_chain_samples.empty())
        {
            stream << L", owner_chains=" << JoinDiagnosticSamples(owner_chain_samples);
        }
        nskinzcs2::Logger::Info(stream.str());
    }

    return best_score >= 0 && render_entity != nullptr;
}

void LogWatchedKnifeFirstPersonCandidateProbe(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int world_weapon_entity_index,
    void* world_weapon_entity,
    void* world_item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    const wchar_t* selected_render_source,
    const int selected_render_entity_index,
    void* selected_render_entity,
    void* selected_render_item_view)
{
    if (!ShouldLogWatchedKnifeAnimationTrace(xuid) ||
        entity_list == nullptr ||
        world_weapon_entity == nullptr ||
        xuid == 0)
    {
        return;
    }

    const auto signature =
        xuid ^
        (static_cast<std::uint64_t>(static_cast<std::uint32_t>(world_weapon_entity_index)) << 32) ^
        (static_cast<std::uint64_t>(static_cast<std::uint32_t>(parent_definition_index)) << 8) ^
        0x4B4E46505052424Cull;

    const auto hud_arms_identity = ResolveHudArmsIdentity(entity_list, player_binding, offsets);
    std::vector<std::wstring> hud_samples;
    std::vector<std::wstring> explicit_samples;
    hud_samples.reserve(4);
    explicit_samples.reserve(4);

    int hud_total = 0;
    int hud_validated = 0;
    int hud_weapon_like = 0;
    int hud_max_depth = 0;
    int explicit_total = 0;
    int explicit_validated = 0;
    int explicit_weapon_like = 0;

    if (hud_arms_identity.entity_resolved &&
        hud_arms_identity.entity != nullptr &&
        offsets.base_entity_game_scene_node != 0 &&
        offsets.game_scene_node_child != 0 &&
        offsets.game_scene_node_next_sibling != 0 &&
        offsets.game_scene_node_owner != 0 &&
        offsets.base_owner_entity != 0)
    {
        void* arms_scene_node = nullptr;
        if (SafeReadField(hud_arms_identity.entity, offsets.base_entity_game_scene_node, arms_scene_node) &&
            arms_scene_node != nullptr)
        {
            struct PendingSceneNode
            {
                void* scene_node = nullptr;
                int depth = 0;
            };

            void* first_child_scene_node = nullptr;
            if (SafeReadField(arms_scene_node, offsets.game_scene_node_child, first_child_scene_node) &&
                first_child_scene_node != nullptr)
            {
                std::vector<PendingSceneNode> pending_scene_nodes;
                pending_scene_nodes.reserve(16);
                pending_scene_nodes.push_back({first_child_scene_node, 1});

                std::unordered_set<void*> visited_scene_nodes;
                while (!pending_scene_nodes.empty())
                {
                    const auto pending = pending_scene_nodes.back();
                    pending_scene_nodes.pop_back();
                    auto* child_scene_node = pending.scene_node;
                    if (child_scene_node == nullptr ||
                        !visited_scene_nodes.insert(child_scene_node).second)
                    {
                        continue;
                    }

                    void* nested_child_scene_node = nullptr;
                    if (SafeReadField(
                            child_scene_node,
                            offsets.game_scene_node_child,
                            nested_child_scene_node) &&
                        nested_child_scene_node != nullptr)
                    {
                        pending_scene_nodes.push_back({nested_child_scene_node, pending.depth + 1});
                    }

                    void* next_sibling_scene_node = nullptr;
                    if (SafeReadField(
                            child_scene_node,
                            offsets.game_scene_node_next_sibling,
                            next_sibling_scene_node) &&
                        next_sibling_scene_node != nullptr)
                    {
                        pending_scene_nodes.push_back({next_sibling_scene_node, pending.depth});
                    }

                    void* owner_entity = nullptr;
                    if (SafeReadField(child_scene_node, offsets.game_scene_node_owner, owner_entity) &&
                        owner_entity != nullptr)
                    {
                        ++hud_total;
                        hud_max_depth = std::max(hud_max_depth, pending.depth);
                        std::uint32_t owner_handle = kInvalidEntityHandle;
                        SafeReadField(owner_entity, offsets.base_owner_entity, owner_handle);
                        const auto owner_index = HandleToEntityIndex(owner_handle);
                        const auto owner_matches_world = owner_index == world_weapon_entity_index;

                        int owner_entity_index = ResolveEntityIndexFromPointer(entity_cache, owner_entity);
                        if (owner_entity_index < 0)
                        {
                            owner_entity_index = BuildSyntheticEntityIndex(owner_entity, 0x4B464850u);
                        }

                        void* candidate_item_view = nullptr;
                        int candidate_definition_index = 0;
                        bool validated = false;
                        bool used_heuristic = false;
                        bool has_raw_item_view = false;
                        ResolveKnifeFirstPersonProbeItemView(
                            owner_entity,
                            offsets,
                            xuid,
                            parent_definition_index,
                            known_definition_indices,
                            knife_definition_indices,
                            glove_definition_indices,
                            candidate_item_view,
                            candidate_definition_index,
                            validated,
                            used_heuristic,
                            has_raw_item_view);

                        const auto model_kind =
                            ClassifyKnifeFirstPersonRenderableModel(owner_entity, offsets);
                        if (validated)
                        {
                            ++hud_validated;
                        }
                        if (model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
                        {
                            ++hud_weapon_like;
                        }

                        if (hud_samples.size() < 4)
                        {
                            auto sample = BuildKnifeFirstPersonProbeCandidateDescriptor(
                                    L"hud_scene_owner",
                                    owner_entity_index,
                                    owner_entity,
                                    candidate_item_view,
                                    has_raw_item_view,
                                    validated,
                                    used_heuristic,
                                    candidate_definition_index,
                                    owner_handle,
                                    owner_index,
                                    owner_matches_world,
                                    candidate_item_view != nullptr && candidate_item_view == world_item_view,
                                    model_kind,
                                    offsets);
                            if (!sample.empty() && sample.back() == L'}')
                            {
                                sample.pop_back();
                            }
                            std::wstringstream sample_suffix;
                            sample_suffix << L", scene_depth=" << pending.depth << L'}';
                            sample += sample_suffix.str();
                            hud_samples.push_back(sample);
                        }
                    }
                }
            }
        }
    }

    if (offsets.base_owner_entity != 0 && player_binding.active_weapon_handle != kInvalidEntityHandle)
    {
        for (std::size_t index = 0; index < entity_cache.size(); ++index)
        {
            auto* candidate = entity_cache[index];
            if (candidate == nullptr || candidate == world_weapon_entity)
            {
                continue;
            }

            std::uint32_t candidate_owner_handle = kInvalidEntityHandle;
            if (!SafeReadField(candidate, offsets.base_owner_entity, candidate_owner_handle) ||
                candidate_owner_handle != player_binding.active_weapon_handle)
            {
                continue;
            }

            ++explicit_total;
            void* candidate_item_view = nullptr;
            int candidate_definition_index = 0;
            bool validated = false;
            bool used_heuristic = false;
            bool has_raw_item_view = false;
            ResolveKnifeFirstPersonProbeItemView(
                candidate,
                offsets,
                xuid,
                parent_definition_index,
                known_definition_indices,
                knife_definition_indices,
                glove_definition_indices,
                candidate_item_view,
                candidate_definition_index,
                validated,
                used_heuristic,
                has_raw_item_view);

            const auto model_kind =
                ClassifyKnifeFirstPersonRenderableModel(candidate, offsets);
            if (validated)
            {
                ++explicit_validated;
            }
            if (model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
            {
                ++explicit_weapon_like;
            }

            if (explicit_samples.size() < 4)
            {
                explicit_samples.push_back(
                    BuildKnifeFirstPersonProbeCandidateDescriptor(
                        L"explicit_child",
                        static_cast<int>(index),
                        candidate,
                        candidate_item_view,
                        has_raw_item_view,
                        validated,
                        used_heuristic,
                        candidate_definition_index,
                        candidate_owner_handle,
                        HandleToEntityIndex(candidate_owner_handle),
                        HandleToEntityIndex(candidate_owner_handle) == world_weapon_entity_index,
                        candidate_item_view != nullptr && candidate_item_view == world_item_view,
                        model_kind,
                        offsets));
            }
        }
    }

    std::wstringstream stream;
    stream << L"Knife first-person candidate probe for XUID " << xuid
        << L": world_entity=" << world_weapon_entity_index
        << L", active_weapon_handle=0x" << std::hex << std::uppercase << player_binding.active_weapon_handle
        << std::dec << std::nouppercase
        << L", parent_definition=" << parent_definition_index
        << L", hud_arms_entity=" << hud_arms_identity.entity_index;
    if (hud_arms_identity.model_name_resolved && !hud_arms_identity.model_name.empty())
    {
        stream << L", hud_arms_model=" << NarrowToWide(hud_arms_identity.model_name);
    }

    stream << L", hud_scene_children=" << hud_total
        << L", hud_scene_max_depth=" << hud_max_depth
        << L", hud_validated=" << hud_validated
        << L", hud_weapon_like=" << hud_weapon_like
        << L", explicit_children=" << explicit_total
        << L", explicit_validated=" << explicit_validated
        << L", explicit_weapon_like=" << explicit_weapon_like;

    if (!hud_samples.empty())
    {
        stream << L", hud_samples=" << JoinDiagnosticSamples(hud_samples);
    }
    else
    {
        stream << L", hud_samples=<none>";
    }

    if (!explicit_samples.empty())
    {
        stream << L", explicit_samples=" << JoinDiagnosticSamples(explicit_samples);
    }
    else
    {
        stream << L", explicit_samples=<none>";
    }

    LogProfileDiagnosticOnce(signature, stream.str());
    LogWatchedKnifeHudWeaponConsumerDeepTrace(
        entity_list,
        entity_cache,
        player_binding,
        world_weapon_entity_index,
        world_weapon_entity,
        world_item_view,
        offsets,
        xuid,
        parent_definition_index,
        known_definition_indices,
        knife_definition_indices,
        glove_definition_indices,
        selected_render_source,
        selected_render_entity_index,
        selected_render_entity,
        selected_render_item_view);
}

bool TryResolveKnifeDirectFirstPersonRenderTarget(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int world_weapon_entity_index,
    void* world_weapon_entity,
    void* world_item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    const wchar_t*& binding_source,
    int& render_entity_index,
    void*& render_entity,
    void*& render_item_view,
    int& render_definition_index,
    bool& render_only,
    KnifeRenderObjectIdentity& render_object_identity)
{
    binding_source = L"owner";
    render_entity_index = -1;
    render_entity = nullptr;
    render_item_view = nullptr;
    render_definition_index = 0;
    render_only = false;
    render_object_identity = {};

    auto try_candidate =
        [&](const wchar_t* source, const int candidate_entity_index, void* candidate_entity)
        {
            if (!IsResolvedRuntimeEntityIndex(candidate_entity_index) || candidate_entity == nullptr)
            {
                return false;
            }

            const auto model_kind =
                ClassifyKnifeFirstPersonRenderableModel(candidate_entity, offsets);
            if (model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike)
            {
                return false;
            }

            void* candidate_item_view = nullptr;
            int candidate_definition_index = 0;
            bool validated = false;
            bool used_heuristic = false;
            bool has_raw_item_view = false;
            ResolveKnifeFirstPersonProbeItemView(
                candidate_entity,
                offsets,
                xuid,
                parent_definition_index,
                known_definition_indices,
                knife_definition_indices,
                glove_definition_indices,
                candidate_item_view,
                candidate_definition_index,
                validated,
                used_heuristic,
                has_raw_item_view);

            const auto raw_item_view_writable_without_validation =
                !validated &&
                has_raw_item_view &&
                candidate_item_view != nullptr &&
                model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike;
            std::uintptr_t candidate_model_state_address = 0;
            std::uint64_t candidate_model_name_token = 0;
            const auto source_allows_render_proxy_only =
                source != nullptr &&
                (std::wcscmp(source, L"hud_scene_owner") == 0 ||
                 std::wcscmp(source, L"providee_render_child") == 0 ||
                 std::wcscmp(source, L"viewmodel_render_child") == 0 ||
                 std::wcscmp(source, L"explicit_render_child") == 0 ||
                 std::wcscmp(source, L"hud_scene_render_child") == 0 ||
                 std::wcscmp(source, L"explicit_render_grandchild") == 0);
            const auto render_proxy_only_writable =
                !validated &&
                source_allows_render_proxy_only &&
                model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike &&
                TryResolveEntityModelStateAddress(
                    candidate_entity,
                    offsets,
                    candidate_model_state_address) &&
                candidate_model_state_address != 0 &&
                TryReadEntityModelNameToken(candidate_entity, offsets, candidate_model_name_token);

            if (!validated)
            {
                if (render_proxy_only_writable)
                {
                    binding_source = source;
                    render_entity_index = candidate_entity_index;
                    render_entity = candidate_entity;
                    render_item_view = candidate_item_view;
                    render_object_identity =
                        ResolveKnifeRenderObjectIdentity(candidate_entity, candidate_item_view, offsets);
                    render_definition_index =
                        parent_definition_index != 0
                            ? parent_definition_index
                            : candidate_definition_index;
                    render_only = true;

                    if (ShouldLogWatchedKnifeAnimationTrace(xuid))
                    {
                        std::string model_name;
                        TryReadEntityModelNameString(candidate_entity, offsets, model_name);
                        std::wstringstream stream;
                        stream << L"Knife direct first-person render target selected: source=" << source
                            << L", entity=" << candidate_entity_index
                            << L", entity_ptr=" << FormatPointer(candidate_entity)
                            << L", item_view=" << FormatPointer(candidate_item_view)
                            << L", model_state="
                            << FormatPointer(reinterpret_cast<void*>(candidate_model_state_address))
                            << L", raw_item_view=" << (has_raw_item_view ? 1 : 0)
                            << L", validated=0"
                            << L", heuristic=" << (used_heuristic ? 1 : 0)
                            << L", raw_writable=" << (raw_item_view_writable_without_validation ? 1 : 0)
                            << L", render_only=1"
                            << L", definition=" << render_definition_index
                            << L", model_kind=" << KnifeFirstPersonRenderableModelKindText(model_kind)
                            << L", note=promoted_render_proxy_only";
                        if (!model_name.empty())
                        {
                            stream << L", model_name=" << NarrowToWide(model_name);
                        }
                        nskinzcs2::Logger::Info(stream.str());
                    }

                    LogWatchedKnifeSyntheticShellBacktrace(
                        entity_list,
                        entity_cache,
                        player_binding,
                        world_weapon_entity_index,
                        world_weapon_entity,
                        world_item_view,
                        offsets,
                        xuid,
                        source,
                        candidate_entity_index,
                        candidate_entity,
                        candidate_item_view);

                    return true;
                }

                if (ShouldLogWatchedKnifeAnimationTrace(xuid))
                {
                    std::string model_name;
                    TryReadEntityModelNameString(candidate_entity, offsets, model_name);
                    std::wstringstream stream;
                    stream << L"Knife direct first-person render target rejected: source=" << source
                        << L", entity=" << candidate_entity_index
                        << L", item_view=" << FormatPointer(candidate_item_view)
                        << L", raw_item_view=" << (has_raw_item_view ? 1 : 0)
                        << L", heuristic=" << (used_heuristic ? 1 : 0)
                        << L", raw_writable=" << (raw_item_view_writable_without_validation ? 1 : 0)
                        << L", render_proxy_only=" << (render_proxy_only_writable ? 1 : 0)
                        << L", model_kind=" << KnifeFirstPersonRenderableModelKindText(model_kind)
                        << L", reason=unvalidated_first_person_target";
                    if (!model_name.empty())
                    {
                        stream << L", model_name=" << NarrowToWide(model_name);
                    }
                    nskinzcs2::Logger::Info(stream.str());
                }

                return false;
            }

            binding_source = source;
            render_entity_index = candidate_entity_index;
            render_entity = candidate_entity;
            render_item_view = candidate_item_view;
            render_object_identity =
                ResolveKnifeRenderObjectIdentity(candidate_entity, candidate_item_view, offsets);
            render_definition_index =
                candidate_definition_index != 0
                    ? candidate_definition_index
                    : parent_definition_index;
            render_only = false;

            if (ShouldLogWatchedKnifeAnimationTrace(xuid))
            {
                std::string model_name;
                TryReadEntityModelNameString(candidate_entity, offsets, model_name);
                std::wstringstream stream;
                stream << L"Knife direct first-person render target selected: source=" << source
                    << L", entity=" << candidate_entity_index
                    << L", entity_ptr=" << FormatPointer(candidate_entity)
                    << L", item_view=" << FormatPointer(candidate_item_view)
                    << L", model_state="
                    << (render_object_identity.model_state_resolved
                            ? FormatPointer(reinterpret_cast<void*>(render_object_identity.model_state))
                            : L"0x0")
                    << L", raw_item_view=" << (has_raw_item_view ? 1 : 0)
                    << L", validated=" << (validated ? 1 : 0)
                    << L", heuristic=" << (used_heuristic ? 1 : 0)
                    << L", raw_writable=" << (raw_item_view_writable_without_validation ? 1 : 0)
                    << L", render_only=" << (render_only ? 1 : 0)
                    << L", definition=" << render_definition_index
                    << L", model_kind=" << KnifeFirstPersonRenderableModelKindText(model_kind);
                if (!model_name.empty())
                {
                    stream << L", model_name=" << NarrowToWide(model_name);
                }
                if (candidate_item_view != nullptr && candidate_item_view == world_item_view)
                {
                    stream << L", shared_world_item_view=1";
                }
                if (raw_item_view_writable_without_validation)
                {
                    stream << L", note=promoted_raw_item_view_for_writes";
                }
                nskinzcs2::Logger::Info(stream.str());
            }

            return true;
        };

    auto resolve_non_synthetic_entity =
        [&](const int candidate_entity_index) -> void*
        {
            if (!IsResolvedRuntimeEntityIndex(candidate_entity_index) ||
                IsSyntheticRuntimeEntityIndex(candidate_entity_index))
            {
                return nullptr;
            }

            if (candidate_entity_index >= 0 &&
                static_cast<std::size_t>(candidate_entity_index) < entity_cache.size() &&
                entity_cache[static_cast<std::size_t>(candidate_entity_index)] != nullptr)
            {
                return entity_cache[static_cast<std::size_t>(candidate_entity_index)];
            }

            void* candidate_entity = nullptr;
            if (entity_list != nullptr &&
                TryGetEntityFromIndex(entity_list, candidate_entity_index, candidate_entity) &&
                candidate_entity != nullptr)
            {
                return candidate_entity;
            }

            return nullptr;
        };

    int hud_render_entity_index = -1;
    void* hud_render_entity = nullptr;
    if (TryResolveHudWeaponRenderEntity(
            entity_list,
            entity_cache,
            player_binding,
            world_weapon_entity_index,
            offsets,
            hud_render_entity_index,
            hud_render_entity))
    {
        int nested_render_entity_index = -1;
        void* nested_render_entity = nullptr;
        void* nested_render_item_view = nullptr;
        int nested_render_definition_index = 0;
        bool nested_render_item_view_validated = false;
        bool nested_render_item_view_used_heuristic = false;
        bool nested_render_item_view_has_raw = false;
        if (TryResolveKnifeSceneOwnedRenderChild(
                entity_cache,
                L"hud_scene_owner",
                hud_render_entity_index,
                hud_render_entity,
                world_weapon_entity_index,
                world_item_view,
                offsets,
                xuid,
                parent_definition_index,
                known_definition_indices,
                knife_definition_indices,
                glove_definition_indices,
                nested_render_entity_index,
                nested_render_entity,
                nested_render_item_view,
                nested_render_definition_index,
                nested_render_item_view_validated,
                nested_render_item_view_used_heuristic,
                nested_render_item_view_has_raw) &&
            try_candidate(
                L"hud_scene_render_child",
                nested_render_entity_index,
                nested_render_entity))
        {
            return true;
        }

        const auto weapon_binding_it =
            player_binding.weapons_by_entity_index.find(world_weapon_entity_index);
        if (weapon_binding_it != player_binding.weapons_by_entity_index.end())
        {
            auto try_owned_render_child =
                [&](const wchar_t* source, const int source_entity_index)
                {
                    auto* source_entity = resolve_non_synthetic_entity(source_entity_index);
                    if (source_entity == nullptr)
                    {
                        return false;
                    }

                    int nested_render_entity_index = -1;
                    void* nested_render_entity = nullptr;
                    void* nested_render_item_view = nullptr;
                    int nested_render_definition_index = 0;
                    bool nested_render_item_view_validated = false;
                    bool nested_render_item_view_used_heuristic = false;
                    bool nested_render_item_view_has_raw = false;
                    return
                        TryResolveKnifeSceneOwnedRenderChild(
                            entity_cache,
                            source,
                            source_entity_index,
                            source_entity,
                            world_weapon_entity_index,
                            world_item_view,
                            offsets,
                            xuid,
                            parent_definition_index,
                            known_definition_indices,
                            knife_definition_indices,
                            glove_definition_indices,
                            nested_render_entity_index,
                            nested_render_entity,
                            nested_render_item_view,
                            nested_render_definition_index,
                            nested_render_item_view_validated,
                            nested_render_item_view_used_heuristic,
                            nested_render_item_view_has_raw) &&
                        try_candidate(source, nested_render_entity_index, nested_render_entity);
                };

            if (try_owned_render_child(
                    L"providee_render_child",
                    weapon_binding_it->second.providee_entity_index))
            {
                return true;
            }

            if (try_owned_render_child(
                    L"viewmodel_render_child",
                    weapon_binding_it->second.viewmodel_entity_index))
            {
                return true;
            }
        }

        if (try_candidate(L"hud_scene_owner", hud_render_entity_index, hud_render_entity))
        {
            return true;
        }
    }

    if (world_weapon_entity != nullptr && offsets.base_owner_entity != 0)
    {
        for (std::size_t index = 0; index < entity_cache.size(); ++index)
        {
            auto* candidate = entity_cache[index];
            if (candidate == nullptr || candidate == world_weapon_entity)
            {
                continue;
            }

            std::uint32_t candidate_owner_handle = kInvalidEntityHandle;
            if (!SafeReadField(candidate, offsets.base_owner_entity, candidate_owner_handle) ||
                HandleToEntityIndex(candidate_owner_handle) != world_weapon_entity_index)
            {
                continue;
            }

            int nested_render_entity_index = -1;
            void* nested_render_entity = nullptr;
            void* nested_render_item_view = nullptr;
            int nested_render_definition_index = 0;
            bool nested_render_item_view_validated = false;
            bool nested_render_item_view_used_heuristic = false;
            bool nested_render_item_view_has_raw = false;
            if (TryResolveKnifeSceneOwnedRenderChild(
                    entity_cache,
                    L"explicit_render_child",
                    static_cast<int>(index),
                    candidate,
                    world_weapon_entity_index,
                    world_item_view,
                    offsets,
                    xuid,
                    parent_definition_index,
                    known_definition_indices,
                    knife_definition_indices,
                    glove_definition_indices,
                    nested_render_entity_index,
                    nested_render_entity,
                    nested_render_item_view,
                    nested_render_definition_index,
                    nested_render_item_view_validated,
                    nested_render_item_view_used_heuristic,
                    nested_render_item_view_has_raw) &&
                try_candidate(
                    L"explicit_render_grandchild",
                    nested_render_entity_index,
                    nested_render_entity))
            {
                return true;
            }

            if (try_candidate(L"explicit_render_child", static_cast<int>(index), candidate))
            {
                return true;
            }
        }
    }

    return false;
}

bool TryResolveLinkedWeaponOwnerCarrier(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    void* linked_entity,
    const ClientSchemaOffsets& offsets,
    int& owner_entity_index,
    void*& owner_entity,
    void*& owner_item_view)
{
    owner_entity_index = -1;
    owner_entity = nullptr;
    owner_item_view = nullptr;

    if (linked_entity == nullptr || offsets.base_owner_entity == 0)
    {
        return false;
    }

    std::uint32_t owner_handle = kInvalidEntityHandle;
    if (!SafeReadField(linked_entity, offsets.base_owner_entity, owner_handle) ||
        owner_handle == kInvalidEntityHandle)
    {
        return false;
    }

    owner_entity_index = HandleToEntityIndex(owner_handle);
    if (owner_entity_index < 0)
    {
        owner_entity_index = -1;
        return false;
    }

    if (static_cast<std::size_t>(owner_entity_index) < entity_cache.size())
    {
        owner_entity = entity_cache[static_cast<std::size_t>(owner_entity_index)];
    }

    if (owner_entity == nullptr &&
        (!TryGetEntityFromIndex(entity_list, owner_entity_index, owner_entity) || owner_entity == nullptr))
    {
        owner_entity_index = -1;
        return false;
    }

    owner_item_view = ResolveWeaponItemView(owner_entity, offsets);
    if (owner_item_view == nullptr)
    {
        owner_entity_index = -1;
        owner_entity = nullptr;
        return false;
    }

    return true;
}

const wchar_t* ReacquiredKnifeOwnerBindingSource(
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind) noexcept
{
    return owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::Providee
        ? L"reacquired_providee_owner"
        : L"reacquired_viewmodel_owner";
}

nskinzcs2::runtime::KnifeFirstPersonOwnerKind ResolvePersistentKnifeOwnerKind(
    const int owner_entity_index,
    const int providee_entity_index,
    const int viewmodel_entity_index,
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind preferred_owner_kind) noexcept
{
    if (owner_entity_index >= 0 && owner_entity_index == providee_entity_index)
    {
        return nskinzcs2::runtime::KnifeFirstPersonOwnerKind::Providee;
    }

    if (owner_entity_index >= 0 && owner_entity_index == viewmodel_entity_index)
    {
        return nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel;
    }

    if (preferred_owner_kind == nskinzcs2::runtime::KnifeFirstPersonOwnerKind::Providee)
    {
        return preferred_owner_kind;
    }

    return nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel;
}

KnifePersistentOwnerReacquireDecision AdvancePendingKnifeFirstPersonReacquire(
    PendingKnifeFirstPersonReacquire& pending,
    const std::uint64_t xuid,
    const int world_entity_index,
    const int candidate_entity_index,
    const int candidate_definition_index,
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind,
    const std::uint64_t observation_frame,
    int& confirm_hits) noexcept
{
    confirm_hits = 0;
    if (xuid == 0 ||
        world_entity_index < 0 ||
        candidate_entity_index < 0 ||
        candidate_definition_index == 0 ||
        !IsRecoverableKnifeFirstPersonOwnerKind(owner_kind))
    {
        pending = {};
        return KnifePersistentOwnerReacquireDecision::None;
    }

    const auto same_candidate =
        pending.active &&
        pending.xuid == xuid &&
        pending.world_entity_index == world_entity_index &&
        pending.candidate_entity_index == candidate_entity_index &&
        pending.candidate_definition_index == candidate_definition_index &&
        pending.owner_kind == owner_kind;

    if (!same_candidate)
    {
        pending = {};
        pending.active = true;
        pending.xuid = xuid;
        pending.world_entity_index = world_entity_index;
        pending.candidate_entity_index = candidate_entity_index;
        pending.candidate_definition_index = candidate_definition_index;
        pending.owner_kind = owner_kind;
        pending.confirm_hits = 1;
        pending.last_observation_frame = observation_frame;
        confirm_hits = pending.confirm_hits;
        return KnifePersistentOwnerReacquireDecision::Pending;
    }

    if (pending.last_observation_frame != observation_frame)
    {
        pending.last_observation_frame = observation_frame;
        if (pending.confirm_hits < 2)
        {
            ++pending.confirm_hits;
        }
    }

    confirm_hits = pending.confirm_hits;
    if (pending.confirm_hits >= 2)
    {
        pending = {};
        return KnifePersistentOwnerReacquireDecision::Confirmed;
    }

    return KnifePersistentOwnerReacquireDecision::Pending;
}

struct KnifeCarrierPromotionDecision
{
    bool promotable_relation = false;
    bool discovery_relevant = false;
    bool accept_writable_carrier = false;
};

KnifeCarrierPromotionDecision ResolveKnifeCarrierPromotionDecision(
    const bool safe_linked_item_view,
    const bool world_owned_proxy,
    const bool direct_viewmodel_attachment,
    const bool reverse_viewmodel_attachment,
    const bool owner_chain_matches_player,
    const bool exact_render_object_entity,
    const bool exact_render_object_alias,
    const bool shell_direct_viewmodel_attachment,
    const bool shell_reverse_viewmodel_attachment,
    const bool shell_owner_chain_matches_player,
    const bool shell_relation_to_render_object,
    const bool world_neighborhood_match,
    const bool shell_world_neighborhood_match) noexcept
{
    const bool promotable_relation =
        direct_viewmodel_attachment ||
        reverse_viewmodel_attachment ||
        owner_chain_matches_player ||
        exact_render_object_entity ||
        exact_render_object_alias ||
        shell_direct_viewmodel_attachment ||
        shell_reverse_viewmodel_attachment ||
        shell_owner_chain_matches_player ||
        shell_relation_to_render_object;
    const bool discovery_relevant =
        promotable_relation ||
        world_neighborhood_match ||
        shell_world_neighborhood_match;
    return {
        promotable_relation,
        discovery_relevant,
        safe_linked_item_view && promotable_relation && !world_owned_proxy};
}

bool TryResolvePersistentKnifeOwnerFromDirectRender(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int world_weapon_entity_index,
    void* world_weapon_entity,
    void* world_item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int parent_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    const int providee_entity_index,
    const int viewmodel_entity_index,
    const nskinzcs2::runtime::KnifeFirstPersonOwnerKind preferred_owner_kind,
    KnifePersistentOwnerResolution& resolution)
{
    resolution = {};
    resolution.discovery_snapshot.xuid = xuid;
    resolution.discovery_snapshot.world_entity_index = world_weapon_entity_index;
    resolution.discovery_snapshot.logical_owner_entity_index =
        viewmodel_entity_index >= 0 ? viewmodel_entity_index : providee_entity_index;
    resolution.discovery_snapshot.viewmodel_entity_index = viewmodel_entity_index;

    const wchar_t* clue_source = L"owner";
    int clue_entity_index = -1;
    void* clue_entity = nullptr;
    void* clue_item_view = nullptr;
    int clue_definition_index = 0;
    bool clue_render_only = false;
    KnifeRenderObjectIdentity clue_render_object {};
    const auto current_refresh_epoch_generation =
        g_hook_state.knife_refresh_helper_epoch_generation.load();
    resolution.discovery_snapshot.refresh_epoch_generation = current_refresh_epoch_generation;
    const auto clue_found =
        TryResolveKnifeDirectFirstPersonRenderTarget(
            entity_list,
            entity_cache,
            player_binding,
            world_weapon_entity_index,
            world_weapon_entity,
            world_item_view,
            offsets,
            xuid,
            parent_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            clue_source,
            clue_entity_index,
            clue_entity,
            clue_item_view,
            clue_definition_index,
            clue_render_only,
            clue_render_object);
    if (clue_found)
    {
        resolution.clue_found = true;
        resolution.clue_source = clue_source;
        resolution.clue_entity_index = clue_entity_index;
        resolution.clue_entity = clue_entity;
        resolution.clue_item_view = clue_item_view;
        resolution.clue_definition_index =
            clue_definition_index != 0 ? clue_definition_index : parent_definition_index;
        resolution.clue_render_only = clue_render_only;
        resolution.clue_render_object = clue_render_object;
        resolution.discovery_snapshot.clue_entity_index = clue_entity_index;
        resolution.discovery_snapshot.render_object = clue_render_object;
        if (ShouldLogWatchedKnifeAnimationTrace(xuid))
        {
            std::wstringstream stream;
            stream << L"Knife first-person owner clue for XUID " << xuid
                << L": clue_source=" << resolution.clue_source
                << L", clue_entity=" << resolution.clue_entity_index
                << L", clue_render_only=" << (resolution.clue_render_only ? 1 : 0)
                << L", clue_render_object="
                << BuildKnifeRenderObjectIdentityDescriptor(resolution.clue_render_object)
                << L", clue_chain="
                << BuildKnifeOwnerChainDescriptor(
                       entity_cache,
                       resolution.clue_entity_index,
                       resolution.clue_entity,
                       offsets);
            nskinzcs2::Logger::Info(stream.str());
        }
    }
    else
    {
        resolution.clue_found = false;
        resolution.clue_source = L"none";
        resolution.clue_entity_index = -1;
        resolution.clue_entity = nullptr;
        resolution.clue_item_view = nullptr;
        resolution.clue_definition_index = parent_definition_index;
        resolution.clue_render_only = false;
        resolution.clue_render_object = {};
    }

    auto log_resolution =
        [&](const bool promoted)
        {
            if (!ShouldLogWatchedKnifeAnimationTrace(xuid))
            {
                return;
            }

            std::wstringstream stream;
            stream << L"Knife first-person owner reacquire: clue_source="
                << resolution.clue_source
                << L", candidate_entity=" << resolution.owner_entity_index
                << L", owner_kind="
                << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(resolution.owner_kind)
                << L", definition=" << resolution.owner_definition_index
                << L", result=" << KnifePersistentOwnerResolutionResultText(resolution.result)
                << L", carrier_result=" << KnifeCarrierDiscoveryResultText(resolution.carrier_result)
                << L", factory_feasibility=" << KnifeCarrierFactoryFeasibilityText(resolution.factory_feasibility)
                << L", viewmodel_absence="
                << KnifeViewmodelAbsenceAuditResultText(
                       resolution.discovery_snapshot.viewmodel_absence_audit.result)
                << L", validation_result=" << resolution.validation_result
                << L", confirm_hits=" << resolution.confirm_hits << L"/2"
                << L", promoted=" << (promoted ? 1 : 0);
            nskinzcs2::Logger::Info(stream.str());
        };

    auto accept_candidate =
        [&](const int candidate_entity_index,
            void* candidate_entity,
            void* candidate_item_view,
            int candidate_definition_index,
            const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind_hint,
            const wchar_t* validation_result)
        {
            const auto owner_kind =
                ResolvePersistentKnifeOwnerKind(
                    candidate_entity_index,
                    providee_entity_index,
                    viewmodel_entity_index,
                    owner_kind_hint);
            if (owner_kind != nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel)
            {
                resolution.validation_result = L"real_viewmodel_owner_required";
                resolution.owner_kind = owner_kind;
                const auto signature =
                    xuid ^
                    (static_cast<std::uint64_t>(
                         static_cast<std::uint32_t>(
                             world_weapon_entity_index >= 0 ? world_weapon_entity_index : 0))
                     << 32) ^
                    (static_cast<std::uint64_t>(
                         static_cast<std::uint32_t>(
                             candidate_entity_index >= 0 ? candidate_entity_index : 0))
                     << 8) ^
                    0x4F574E4552524A31ull;
                std::wstringstream stream;
                stream << L"Knife first-person owner rejection: candidate_entity="
                    << candidate_entity_index
                    << L", candidate_definition=" << candidate_definition_index
                    << L", owner_kind="
                    << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(owner_kind)
                    << L", preferred_owner_kind="
                    << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(owner_kind_hint)
                    << L", providee_entity=" << providee_entity_index
                    << L", viewmodel_entity=" << viewmodel_entity_index
                    << L", clue_source="
                    << (resolution.clue_source != nullptr ? resolution.clue_source : L"none")
                    << L", validation_result=real_viewmodel_owner_required";
                LogProfileDiagnosticOnce(signature, stream.str());
                return false;
            }

            resolution.owner_valid = true;
            resolution.validation_result = validation_result;
            resolution.owner_entity_index = candidate_entity_index;
            resolution.owner_entity = candidate_entity;
            resolution.owner_item_view = candidate_item_view;
            resolution.owner_definition_index = candidate_definition_index;
            resolution.owner_kind = owner_kind;
            resolution.binding_source = ReacquiredKnifeOwnerBindingSource(owner_kind);
            resolution.carrier_result = nskinzcs2::runtime::KnifeCarrierDiscoveryResult::RealCarrierFound;
            resolution.factory_feasibility = nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::Unknown;
            g_hook_state.knife_persistent_owner_negative_cache = {};

            const auto observation_frame = g_hook_state.frame_callback_count.load();
            auto decision =
                AdvancePendingKnifeFirstPersonReacquire(
                    g_hook_state.pending_knife_first_person_reacquire,
                    xuid,
                    world_weapon_entity_index,
                    candidate_entity_index,
                    candidate_definition_index,
                    owner_kind,
                    observation_frame,
                    resolution.confirm_hits);

            resolution.pending = decision == KnifePersistentOwnerReacquireDecision::Pending;
            resolution.promoted = decision == KnifePersistentOwnerReacquireDecision::Confirmed;
            resolution.result =
                resolution.promoted
                ? KnifePersistentOwnerResolutionResult::PromotedRealOwner
                : resolution.pending
                    ? KnifePersistentOwnerResolutionResult::PendingConfirmation
                    : KnifePersistentOwnerResolutionResult::Unresolved;
            log_resolution(resolution.promoted);
            return resolution.promoted;
        };

    auto validate_candidate =
        [&](const int candidate_entity_index,
            void* candidate_entity,
            void* candidate_item_view,
            int candidate_definition_index,
            const nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind_hint,
            const wchar_t* direct_validation_result,
            const wchar_t* synthetic_reason,
            const wchar_t* world_alias_reason,
            const wchar_t* world_owned_proxy_reason,
            const wchar_t* item_view_reason,
            const wchar_t* weapon_like_reason)
        {
            if (candidate_entity == nullptr || candidate_entity_index < 0)
            {
                resolution.validation_result = direct_validation_result;
                return false;
            }

            if (IsSyntheticRuntimeEntityIndex(candidate_entity_index))
            {
                resolution.validation_result = synthetic_reason;
                return false;
            }

            if (candidate_entity_index == world_weapon_entity_index)
            {
                resolution.validation_result = world_alias_reason;
                return false;
            }

            if (offsets.base_owner_entity != 0)
            {
                std::uint32_t candidate_owner_handle = kInvalidEntityHandle;
                if (SafeReadField(candidate_entity, offsets.base_owner_entity, candidate_owner_handle) &&
                    HandleToEntityIndex(candidate_owner_handle) == world_weapon_entity_index)
                {
                    resolution.validation_result = world_owned_proxy_reason;
                    return false;
                }
            }

            if (candidate_item_view == nullptr)
            {
                resolution.validation_result = item_view_reason;
                return false;
            }

            const auto model_kind =
                ClassifyKnifeFirstPersonRenderableModel(candidate_entity, offsets);
            if (model_kind != KnifeFirstPersonRenderableModelKind::WeaponLike)
            {
                resolution.validation_result = weapon_like_reason;
                return false;
            }

            int safe_definition_index = 0;
            if (!IsSafeLinkedWeaponItemView(
                    candidate_item_view,
                    offsets,
                    xuid,
                    parent_definition_index,
                    known_definition_indices,
                    knife_definition_indices,
                    glove_definition_indices,
                    safe_definition_index))
            {
                resolution.validation_result = item_view_reason;
                return false;
            }

            return accept_candidate(
                candidate_entity_index,
                candidate_entity,
                candidate_item_view,
                safe_definition_index != 0 ? safe_definition_index : candidate_definition_index,
                owner_kind_hint,
                direct_validation_result);
        };

    auto log_providee_owner_certification_once =
        [&]()
        {
            if (!clue_found ||
                resolution.clue_source == nullptr ||
                std::wcscmp(resolution.clue_source, L"providee_render_child") != 0 ||
                !IsResolvedRuntimeEntityIndex(providee_entity_index) ||
                IsSyntheticRuntimeEntityIndex(providee_entity_index) ||
                providee_entity_index == world_weapon_entity_index)
            {
                return;
            }

            const auto signature =
                xuid ^
                (static_cast<std::uint64_t>(
                     static_cast<std::uint32_t>(
                         world_weapon_entity_index >= 0 ? world_weapon_entity_index : 0))
                 << 32) ^
                (static_cast<std::uint64_t>(
                     static_cast<std::uint32_t>(
                         providee_entity_index >= 0 ? providee_entity_index : 0))
                 << 8) ^
                0x5052564F574E5231ull;

            void* providee_entity = nullptr;
            if (static_cast<std::size_t>(providee_entity_index) < entity_cache.size())
            {
                providee_entity = entity_cache[static_cast<std::size_t>(providee_entity_index)];
            }
            if (providee_entity == nullptr &&
                (!TryGetEntityFromIndex(entity_list, providee_entity_index, providee_entity) ||
                 providee_entity == nullptr))
            {
                std::wstringstream stream;
                stream << L"Knife providee owner certification: candidate_entity="
                    << providee_entity_index
                    << L", clue_source=" << resolution.clue_source
                    << L", result=entity_unresolved";
                LogProfileDiagnosticOnce(signature, stream.str());
                return;
            }

            auto* providee_item_view = ResolveWeaponItemView(providee_entity, offsets);
            if (providee_item_view == nullptr)
            {
                std::wstringstream stream;
                stream << L"Knife providee owner certification: candidate_entity="
                    << providee_entity_index
                    << L", clue_source=" << resolution.clue_source
                    << L", result=item_view_missing";
                LogProfileDiagnosticOnce(signature, stream.str());
                return;
            }

            if (ClassifyKnifeFirstPersonRenderableModel(providee_entity, offsets) !=
                KnifeFirstPersonRenderableModelKind::WeaponLike)
            {
                std::wstringstream stream;
                stream << L"Knife providee owner certification: candidate_entity="
                    << providee_entity_index
                    << L", clue_source=" << resolution.clue_source
                    << L", result=not_weapon_like";
                LogProfileDiagnosticOnce(signature, stream.str());
                return;
            }

            if (offsets.base_owner_entity != 0)
            {
                std::uint32_t candidate_owner_handle = kInvalidEntityHandle;
                if (SafeReadField(providee_entity, offsets.base_owner_entity, candidate_owner_handle) &&
                    HandleToEntityIndex(candidate_owner_handle) == world_weapon_entity_index)
                {
                    std::wstringstream stream;
                    stream << L"Knife providee owner certification: candidate_entity="
                        << providee_entity_index
                        << L", clue_source=" << resolution.clue_source
                        << L", result=world_owned_proxy";
                    LogProfileDiagnosticOnce(signature, stream.str());
                    return;
                }
            }

            int safe_definition_index = 0;
            if (!IsSafeLinkedWeaponItemView(
                    providee_item_view,
                    offsets,
                    xuid,
                    parent_definition_index,
                    known_definition_indices,
                    knife_definition_indices,
                    glove_definition_indices,
                    safe_definition_index))
            {
                std::wstringstream stream;
                stream << L"Knife providee owner certification: candidate_entity="
                    << providee_entity_index
                    << L", clue_source=" << resolution.clue_source
                    << L", result=item_view_unsafe";
                LogProfileDiagnosticOnce(signature, stream.str());
                return;
            }

            const auto owner_kind =
                ResolvePersistentKnifeOwnerKind(
                    providee_entity_index,
                    providee_entity_index,
                    viewmodel_entity_index,
                    nskinzcs2::runtime::KnifeFirstPersonOwnerKind::Providee);
            if (owner_kind != nskinzcs2::runtime::KnifeFirstPersonOwnerKind::ViewModel)
            {
                std::wstringstream stream;
                stream << L"Knife first-person owner rejection: candidate_entity="
                    << providee_entity_index
                    << L", candidate_definition="
                    << (safe_definition_index != 0 ? safe_definition_index : parent_definition_index)
                    << L", owner_kind="
                    << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(owner_kind)
                    << L", preferred_owner_kind="
                    << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(
                           nskinzcs2::runtime::KnifeFirstPersonOwnerKind::Providee)
                    << L", providee_entity=" << providee_entity_index
                    << L", viewmodel_entity=" << viewmodel_entity_index
                    << L", clue_source=" << resolution.clue_source
                    << L", validation_result=real_viewmodel_owner_required";
                LogProfileDiagnosticOnce(signature, stream.str());
                return;
            }

            std::wstringstream stream;
            stream << L"Knife providee owner certification: candidate_entity="
                << providee_entity_index
                << L", clue_source=" << resolution.clue_source
                << L", result=viewmodel_owner";
            LogProfileDiagnosticOnce(signature, stream.str());
        };

    auto log_providee_missing_handle_diagnostic_once =
        [&](const KnifeViewmodelAbsenceAudit& audit)
        {
            if (resolution.clue_source == nullptr ||
                std::wcscmp(resolution.clue_source, L"providee_render_child") != 0 ||
                audit.result != nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::MissingHandle)
            {
                return;
            }

            const auto signature =
                xuid ^
                (static_cast<std::uint64_t>(
                     static_cast<std::uint32_t>(
                         world_weapon_entity_index >= 0 ? world_weapon_entity_index : 0))
                 << 32) ^
                (static_cast<std::uint64_t>(
                     static_cast<std::uint32_t>(
                         providee_entity_index >= 0 ? providee_entity_index : 0))
                 << 8) ^
                0x4D49535348444C31ull;
            std::wstringstream stream;
            stream << L"Knife viewmodel handle missing on providee path: world_entity="
                << world_weapon_entity_index
                << L", providee_entity=" << providee_entity_index
                << L", clue_entity=" << resolution.clue_entity_index
                << L", clue_source=" << resolution.clue_source
                << L", field_present=" << (audit.field_present ? 1 : 0)
                << L", raw_handle=0x" << std::hex << std::uppercase << audit.raw_handle
                << std::dec << std::nouppercase
                << L", handle_entity=" << audit.handle_entity_index
                << L", raw_entity_visible=" << (audit.raw_entity_visible ? 1 : 0)
                << L", reverse_viewmodel_refs=" << audit.reverse_viewmodel_ref_count
                << L", closest_owner_chain_entity=" << audit.closest_owner_chain_entity_index
                << L", result=" << KnifeViewmodelAbsenceAuditResultText(audit.result);
            LogProfileDiagnosticOnce(signature, stream.str());
        };
    const auto should_force_providee_owner_search_diagnostics =
        clue_found &&
        resolution.clue_source != nullptr &&
        std::wcscmp(resolution.clue_source, L"providee_render_child") == 0;

    auto log_providee_owner_search_stage_once =
        [&](const wchar_t* stage, const std::wstring& detail)
        {
            if (!should_force_providee_owner_search_diagnostics)
            {
                return;
            }

            std::uint64_t stage_hash = 0x5345415243483031ull;
            if (stage != nullptr)
            {
                for (const wchar_t* cursor = stage; *cursor != L'\0'; ++cursor)
                {
                    stage_hash = (stage_hash * 131ull) ^ static_cast<std::uint64_t>(*cursor);
                }
            }

            const auto signature =
                xuid ^
                (static_cast<std::uint64_t>(
                     static_cast<std::uint32_t>(
                         world_weapon_entity_index >= 0 ? world_weapon_entity_index : 0))
                 << 32) ^
                (static_cast<std::uint64_t>(
                     static_cast<std::uint32_t>(
                         providee_entity_index >= 0 ? providee_entity_index : 0))
                 << 8) ^
                stage_hash;
            std::wstringstream stream;
            stream << L"Knife providee owner search[" << (stage != nullptr ? stage : L"unknown")
                << L"]: clue_entity=" << resolution.clue_entity_index
                << L", providee_entity=" << providee_entity_index
                << L", detail=" << detail;
            LogProfileDiagnosticOnce(signature, stream.str());
        };

    auto build_targeted_probe_entity_descriptor =
        [&](const int entity_index)
        {
            if (entity_index < 0 || IsSyntheticRuntimeEntityIndex(entity_index))
            {
                return std::wstring(L"entity=<invalid>");
            }

            void* entity = nullptr;
            if (static_cast<std::size_t>(entity_index) < entity_cache.size())
            {
                entity = entity_cache[static_cast<std::size_t>(entity_index)];
            }
            if (entity == nullptr &&
                (!TryGetEntityFromIndex(entity_list, entity_index, entity) || entity == nullptr))
            {
                std::wstringstream stream;
                stream << L"entity=" << entity_index << L", unresolved=1";
                return stream.str();
            }

            auto* item_view = ResolveWeaponItemView(entity, offsets);
            std::wstring descriptor =
                BuildWeaponRenderConsumerEntityDiagnostic(L"entity", entity_index, entity, item_view, offsets);
            if (!descriptor.empty() && descriptor.back() == L'}')
            {
                descriptor.pop_back();
            }

            std::uint32_t owner_handle = kInvalidEntityHandle;
            const auto owner_readable =
                offsets.base_owner_entity != 0 &&
                SafeReadField(entity, offsets.base_owner_entity, owner_handle);
            const auto owner_index = owner_readable ? HandleToEntityIndex(owner_handle) : -1;

            std::uint32_t old_move_parent_handle = kInvalidEntityHandle;
            const auto old_move_parent_readable =
                offsets.base_old_move_parent != 0 &&
                SafeReadField(entity, offsets.base_old_move_parent, old_move_parent_handle);
            const auto old_move_parent_index =
                old_move_parent_readable ? HandleToEntityIndex(old_move_parent_handle) : -1;

            std::uint32_t viewmodel_handle = kInvalidEntityHandle;
            const auto viewmodel_readable =
                offsets.econ_entity_viewmodel_attachment != 0 &&
                SafeReadField(entity, offsets.econ_entity_viewmodel_attachment, viewmodel_handle);
            const auto viewmodel_index =
                viewmodel_readable ? HandleToEntityIndex(viewmodel_handle) : -1;

            std::uint32_t providee_handle = kInvalidEntityHandle;
            const auto providee_readable =
                offsets.econ_entity_old_providee != 0 &&
                SafeReadField(entity, offsets.econ_entity_old_providee, providee_handle);
            const auto attached_providee_index =
                providee_readable ? HandleToEntityIndex(providee_handle) : -1;

            std::uintptr_t model_state_address = 0;
            const auto model_state_resolved =
                TryResolveEntityModelStateAddress(entity, offsets, model_state_address) &&
                model_state_address != 0;

            void* scene_node = nullptr;
            const auto scene_node_resolved =
                offsets.base_entity_game_scene_node != 0 &&
                SafeReadField(entity, offsets.base_entity_game_scene_node, scene_node) &&
                scene_node != nullptr;
            void* scene_owner_entity = nullptr;
            int scene_owner_index = -1;
            if (scene_node_resolved && offsets.game_scene_node_owner != 0)
            {
                if (SafeReadField(scene_node, offsets.game_scene_node_owner, scene_owner_entity) &&
                    scene_owner_entity != nullptr)
                {
                    scene_owner_index = ResolveEntityIndexFromPointer(entity_cache, scene_owner_entity);
                    if (scene_owner_index < 0)
                    {
                        scene_owner_index = BuildSyntheticEntityIndex(scene_owner_entity, 0x50525453u);
                    }
                }
            }

            const auto render_identity =
                ResolveKnifeRenderObjectIdentity(entity, item_view, offsets);
            const auto render_match =
                resolution.clue_render_object.IsUsable() &&
                KnifeRenderObjectIdentityMatches(render_identity, resolution.clue_render_object);

            int owner_chain_depth_to_pawn = -1;
            const auto owner_chain_to_pawn =
                player_binding.pawn_entity_index >= 0 &&
                KnifeOwnerChainContainsEntity(
                    entity_list,
                    entity_cache,
                    entity_index,
                    entity,
                    offsets,
                    player_binding.pawn_entity_index,
                    owner_chain_depth_to_pawn);

            int owner_chain_depth_to_providee = -1;
            const auto owner_chain_to_providee =
                providee_entity_index >= 0 &&
                KnifeOwnerChainContainsEntity(
                    entity_list,
                    entity_cache,
                    entity_index,
                    entity,
                    offsets,
                    providee_entity_index,
                    owner_chain_depth_to_providee);

            int owner_chain_depth_to_viewmodel = -1;
            const auto owner_chain_to_viewmodel =
                viewmodel_entity_index >= 0 &&
                KnifeOwnerChainContainsEntity(
                    entity_list,
                    entity_cache,
                    entity_index,
                    entity,
                    offsets,
                    viewmodel_entity_index,
                    owner_chain_depth_to_viewmodel);

            auto format_optional_handle =
                [](const bool readable, const std::uint32_t raw_handle)
                {
                    if (!readable)
                    {
                        return std::wstring(L"?");
                    }

                    std::wstringstream stream;
                    stream << L"0x" << std::hex << std::uppercase << raw_handle
                           << std::dec << std::nouppercase;
                    return stream.str();
                };

            descriptor +=
                std::wstring(L", owner_handle=") + format_optional_handle(owner_readable, owner_handle) +
                L", owner_index=" + std::to_wstring(owner_index) +
                L", old_move_parent_handle=" +
                format_optional_handle(old_move_parent_readable, old_move_parent_handle) +
                L", old_move_parent_index=" + std::to_wstring(old_move_parent_index) +
                L", viewmodel_handle=" + format_optional_handle(viewmodel_readable, viewmodel_handle) +
                L", attached_viewmodel_index=" + std::to_wstring(viewmodel_index) +
                L", providee_handle=" + format_optional_handle(providee_readable, providee_handle) +
                L", attached_providee_index=" + std::to_wstring(attached_providee_index) +
                L", model_state=" +
                std::wstring(
                    model_state_resolved
                        ? FormatPointer(reinterpret_cast<void*>(model_state_address))
                        : L"0x0") +
                L", scene_owner=" + std::to_wstring(scene_owner_index) +
                L", scene_owner_ptr=" + FormatPointer(scene_owner_entity) +
                L", pawn_match=" + std::to_wstring(entity_index == player_binding.pawn_entity_index ? 1 : 0) +
                L", providee_match=" + std::to_wstring(entity_index == providee_entity_index ? 1 : 0) +
                L", viewmodel_match=" + std::to_wstring(entity_index == viewmodel_entity_index ? 1 : 0) +
                L", render_object_match=" + std::to_wstring(render_match ? 1 : 0) +
                L", owner_chain_to_pawn=" + std::to_wstring(owner_chain_to_pawn ? 1 : 0) +
                L", owner_chain_depth_to_pawn=" + std::to_wstring(owner_chain_depth_to_pawn) +
                L", owner_chain_to_providee=" + std::to_wstring(owner_chain_to_providee ? 1 : 0) +
                L", owner_chain_depth_to_providee=" +
                std::to_wstring(owner_chain_depth_to_providee) +
                L", owner_chain_to_viewmodel=" + std::to_wstring(owner_chain_to_viewmodel ? 1 : 0) +
                L", owner_chain_depth_to_viewmodel=" +
                std::to_wstring(owner_chain_depth_to_viewmodel) +
                L", " + BuildRuntimeEntityRttiDescriptor(entity) +
                L", owner_chain=" +
                BuildKnifeOwnerChainDescriptor(entity_cache, entity_index, entity, offsets) +
                L'}';
            return descriptor;
        };

    auto log_targeted_owner_pair_probe_once =
        [&](const wchar_t* stage, const int candidate_entity_index, const int owner_entity_index)
        {
            if (!should_force_providee_owner_search_diagnostics)
            {
                return;
            }

            std::wstringstream stream;
            stream << L"candidate=" << candidate_entity_index
                << L", owner=" << owner_entity_index
                << L", candidate_descriptor="
                << build_targeted_probe_entity_descriptor(candidate_entity_index)
                << L", owner_descriptor="
                << build_targeted_probe_entity_descriptor(owner_entity_index);
            log_providee_owner_search_stage_once(
                stage != nullptr ? stage : L"targeted_probe",
                stream.str());
        };

    auto resolve_probe_entity =
        [&](const int entity_index) -> void*
        {
            if (entity_index < 0 || IsSyntheticRuntimeEntityIndex(entity_index))
            {
                return nullptr;
            }

            if (static_cast<std::size_t>(entity_index) < entity_cache.size())
            {
                if (entity_cache[static_cast<std::size_t>(entity_index)] != nullptr)
                {
                    return entity_cache[static_cast<std::size_t>(entity_index)];
                }
            }

            void* entity = nullptr;
            if (TryGetEntityFromIndex(entity_list, entity_index, entity) && entity != nullptr)
            {
                return entity;
            }

            return nullptr;
        };

    auto build_probe_trace_node =
        [&](const int entity_index)
        {
            void* entity = resolve_probe_entity(entity_index);
            if (entity == nullptr)
            {
                std::wstringstream stream;
                stream << L"{entity=" << entity_index << L", unresolved=1}";
                return stream.str();
            }

            std::uintptr_t model_state_address = 0;
            const auto model_state_resolved =
                TryResolveEntityModelStateAddress(entity, offsets, model_state_address) &&
                model_state_address != 0;
            void* scene_node = nullptr;
            const auto scene_node_resolved =
                offsets.base_entity_game_scene_node != 0 &&
                SafeReadField(entity, offsets.base_entity_game_scene_node, scene_node) &&
                scene_node != nullptr;
            void* scene_owner_entity = nullptr;
            int scene_owner_index = -1;
            if (scene_node_resolved && offsets.game_scene_node_owner != 0)
            {
                if (SafeReadField(scene_node, offsets.game_scene_node_owner, scene_owner_entity) &&
                    scene_owner_entity != nullptr)
                {
                    scene_owner_index = ResolveEntityIndexFromPointer(entity_cache, scene_owner_entity);
                    if (scene_owner_index < 0)
                    {
                        scene_owner_index = BuildSyntheticEntityIndex(scene_owner_entity, 0x54524353u);
                    }
                }
            }

            std::uint32_t owner_handle = kInvalidEntityHandle;
            const auto owner_readable =
                offsets.base_owner_entity != 0 &&
                SafeReadField(entity, offsets.base_owner_entity, owner_handle);
            const auto owner_index = owner_readable ? HandleToEntityIndex(owner_handle) : -1;

            std::uint32_t old_move_parent_handle = kInvalidEntityHandle;
            const auto old_move_parent_readable =
                offsets.base_old_move_parent != 0 &&
                SafeReadField(entity, offsets.base_old_move_parent, old_move_parent_handle);
            const auto old_move_parent_index =
                old_move_parent_readable ? HandleToEntityIndex(old_move_parent_handle) : -1;

            std::string model_name;
            TryReadEntityModelNameString(entity, offsets, model_name);
            const auto render_identity =
                ResolveKnifeRenderObjectIdentity(entity, ResolveWeaponItemView(entity, offsets), offsets);
            const auto render_match =
                resolution.clue_render_object.IsUsable() &&
                KnifeRenderObjectIdentityMatches(render_identity, resolution.clue_render_object);

            std::wstringstream stream;
            stream << L"{entity=" << entity_index
                << L", ptr=" << FormatPointer(entity)
                << L", scene_owner=" << scene_owner_index
                << L", owner=" << owner_index
                << L", old_move_parent=" << old_move_parent_index
                << L", model_state="
                << (model_state_resolved
                        ? FormatPointer(reinterpret_cast<void*>(model_state_address))
                        : L"0x0")
                << L", render_match=" << (render_match ? 1 : 0)
                << L", rtti=" << BuildRuntimeEntityRttiDescriptor(entity);
            if (!model_name.empty())
            {
                stream << L", model=" << NarrowToWide(model_name);
            }
            stream << L"}";
            return stream.str();
        };

    auto log_providee_scene_owner_trace_once =
        [&]()
        {
            if (!should_force_providee_owner_search_diagnostics ||
                !IsResolvedRuntimeEntityIndex(providee_entity_index) ||
                IsSyntheticRuntimeEntityIndex(providee_entity_index))
            {
                return;
            }

            auto build_branch =
                [&](const int start_entity_index, const bool follow_scene_owner)
                {
                    std::wstringstream stream;
                    std::unordered_set<int> visited;
                    int current_entity_index = start_entity_index;
                    for (int depth = 0; depth < 4; ++depth)
                    {
                        if (current_entity_index < 0 || visited.contains(current_entity_index))
                        {
                            break;
                        }

                        visited.insert(current_entity_index);
                        if (depth != 0)
                        {
                            stream << L" -> ";
                        }
                        stream << build_probe_trace_node(current_entity_index);

                        void* current_entity = resolve_probe_entity(current_entity_index);
                        if (current_entity == nullptr)
                        {
                            break;
                        }

                        if (follow_scene_owner)
                        {
                            void* scene_node = nullptr;
                            if (!(offsets.base_entity_game_scene_node != 0 &&
                                  SafeReadField(
                                      current_entity,
                                      offsets.base_entity_game_scene_node,
                                      scene_node) &&
                                  scene_node != nullptr))
                            {
                                break;
                            }

                            void* scene_owner_entity = nullptr;
                            if (!(offsets.game_scene_node_owner != 0 &&
                                  SafeReadField(
                                      scene_node,
                                      offsets.game_scene_node_owner,
                                      scene_owner_entity) &&
                                  scene_owner_entity != nullptr))
                            {
                                break;
                            }

                            current_entity_index =
                                ResolveEntityIndexFromPointer(entity_cache, scene_owner_entity);
                            continue;
                        }

                        std::uint32_t owner_handle = kInvalidEntityHandle;
                        if (offsets.base_owner_entity != 0 &&
                            SafeReadField(current_entity, offsets.base_owner_entity, owner_handle) &&
                            owner_handle != kInvalidEntityHandle)
                        {
                            current_entity_index = HandleToEntityIndex(owner_handle);
                            continue;
                        }

                        std::uint32_t old_move_parent_handle = kInvalidEntityHandle;
                        if (offsets.base_old_move_parent != 0 &&
                            SafeReadField(
                                current_entity,
                                offsets.base_old_move_parent,
                                old_move_parent_handle) &&
                            old_move_parent_handle != kInvalidEntityHandle)
                        {
                            current_entity_index = HandleToEntityIndex(old_move_parent_handle);
                            continue;
                        }

                        break;
                    }

                    return stream.str();
                };

            std::wstringstream stream;
            stream << L"providee=" << build_probe_trace_node(providee_entity_index)
                << L", scene_branch=" << build_branch(providee_entity_index, true)
                << L", owner_branch=" << build_branch(providee_entity_index, false);
            log_providee_owner_search_stage_once(L"providee_scene_owner_trace", stream.str());
        };

    auto log_world_render_alias_neighbors_once =
        [&]()
        {
            if (!should_force_providee_owner_search_diagnostics || world_weapon_entity == nullptr)
            {
                return;
            }

            std::uintptr_t world_model_state = 0;
            const auto world_model_state_resolved =
                TryResolveEntityModelStateAddress(world_weapon_entity, offsets, world_model_state) &&
                world_model_state != 0;
            const auto world_render_identity =
                ResolveKnifeRenderObjectIdentity(world_weapon_entity, world_item_view, offsets);

            std::uint32_t world_viewmodel_handle = kInvalidEntityHandle;
            if (offsets.econ_entity_viewmodel_attachment != 0)
            {
                SafeReadField(world_weapon_entity, offsets.econ_entity_viewmodel_attachment, world_viewmodel_handle);
            }
            const auto world_viewmodel_entity =
                world_viewmodel_handle != kInvalidEntityHandle
                    ? HandleToEntityIndex(world_viewmodel_handle)
                    : -1;

            int scanned = 0;
            int shared_render_object_count = 0;
            int shared_world_model_state_count = 0;
            int without_viewmodel_attachment_count = 0;
            std::vector<std::wstring> samples;
            samples.reserve(4);

            const auto highest_live_entity_index =
                std::max(g_hook_state.highest_live_entity_index.load(), static_cast<int>(entity_cache.size()) - 1);
            for (int entity_index = 0; entity_index <= highest_live_entity_index; ++entity_index)
            {
                void* entity = resolve_probe_entity(entity_index);
                if (entity == nullptr || entity == world_weapon_entity)
                {
                    continue;
                }

                ++scanned;

                auto* item_view = ResolveWeaponItemView(entity, offsets);
                const auto render_identity = ResolveKnifeRenderObjectIdentity(entity, item_view, offsets);
                const auto shared_clue_render_object =
                    resolution.clue_render_object.IsUsable() &&
                    KnifeRenderObjectIdentityMatches(render_identity, resolution.clue_render_object);
                const auto shared_world_render_object =
                    world_render_identity.IsUsable() &&
                    KnifeRenderObjectIdentityMatches(render_identity, world_render_identity);

                std::uintptr_t candidate_model_state = 0;
                const auto candidate_model_state_resolved =
                    TryResolveEntityModelStateAddress(entity, offsets, candidate_model_state) &&
                    candidate_model_state != 0;
                const auto shared_world_model_state =
                    world_model_state_resolved &&
                    candidate_model_state_resolved &&
                    candidate_model_state == world_model_state;

                if (!shared_clue_render_object &&
                    !shared_world_render_object &&
                    !shared_world_model_state)
                {
                    continue;
                }

                if (shared_clue_render_object || shared_world_render_object)
                {
                    ++shared_render_object_count;
                }
                if (shared_world_model_state)
                {
                    ++shared_world_model_state_count;
                }

                std::uint32_t candidate_viewmodel_handle = kInvalidEntityHandle;
                const auto candidate_viewmodel_readable =
                    offsets.econ_entity_viewmodel_attachment != 0 &&
                    SafeReadField(entity, offsets.econ_entity_viewmodel_attachment, candidate_viewmodel_handle);
                const auto candidate_viewmodel_entity =
                    candidate_viewmodel_readable ? HandleToEntityIndex(candidate_viewmodel_handle) : -1;
                const auto uses_viewmodel_attachment =
                    candidate_viewmodel_entity == world_weapon_entity_index ||
                    entity_index == world_viewmodel_entity;
                if (uses_viewmodel_attachment)
                {
                    continue;
                }

                ++without_viewmodel_attachment_count;
                if (samples.size() < 4)
                {
                    std::wstringstream sample;
                    sample << L"entity=" << entity_index
                        << L", shared_clue_render_object=" << (shared_clue_render_object ? 1 : 0)
                        << L", shared_world_render_object=" << (shared_world_render_object ? 1 : 0)
                        << L", shared_world_model_state=" << (shared_world_model_state ? 1 : 0)
                        << L", candidate_viewmodel_entity=" << candidate_viewmodel_entity
                        << L", descriptor=" << build_targeted_probe_entity_descriptor(entity_index);
                    samples.push_back(sample.str());
                }
            }

            std::wstringstream stream;
            stream << L"world_entity=" << world_weapon_entity_index
                << L", world_viewmodel_entity=" << world_viewmodel_entity
                << L", world_model_state="
                << (world_model_state_resolved
                        ? FormatPointer(reinterpret_cast<void*>(world_model_state))
                        : L"0x0")
                << L", scanned=" << scanned
                << L", shared_render_object=" << shared_render_object_count
                << L", shared_world_model_state=" << shared_world_model_state_count
                << L", without_viewmodel_attachment=" << without_viewmodel_attachment_count
                << L", samples=";
            if (samples.empty())
            {
                stream << L"<none>";
            }
            else
            {
                for (std::size_t index = 0; index < samples.size(); ++index)
                {
                    if (index != 0)
                    {
                        stream << L" | ";
                    }
                    stream << samples[index];
                }
            }
            log_providee_owner_search_stage_once(L"world_render_alias_neighbors", stream.str());
        };

    log_targeted_owner_pair_probe_once(L"target_pair0", 280, 271);
    log_targeted_owner_pair_probe_once(L"target_pair1", 503, 171);
    log_providee_scene_owner_trace_once();
    log_world_render_alias_neighbors_once();

    const auto matches_negative_resolution_cache =
        [&]() noexcept
        {
            const auto& cache = g_hook_state.knife_persistent_owner_negative_cache;
            return clue_found &&
                cache.active &&
                cache.xuid == xuid &&
                cache.refresh_epoch_generation != 0 &&
                cache.refresh_epoch_generation == current_refresh_epoch_generation &&
                cache.world_entity_index == world_weapon_entity_index &&
                cache.clue_definition_index == resolution.clue_definition_index &&
                KnifeRenderObjectIdentityMatches(cache.render_object, resolution.clue_render_object);
        };

    if (matches_negative_resolution_cache())
    {
        log_providee_owner_certification_once();
        if (clue_found &&
            resolution.clue_source != nullptr &&
            std::wcscmp(resolution.clue_source, L"providee_render_child") == 0)
        {
            const auto audit =
                BuildKnifeViewmodelAbsenceAudit(
                    entity_list,
                    entity_cache,
                    player_binding,
                    world_weapon_entity_index,
                    world_weapon_entity,
                    offsets,
                    xuid,
                    parent_definition_index,
                    known_definition_indices,
                    knife_definition_indices,
                    glove_definition_indices,
                    providee_entity_index,
                    viewmodel_entity_index,
                    resolution.clue_render_object);
            log_providee_missing_handle_diagnostic_once(audit);
        }
        ClearPendingKnifeFirstPersonReacquire();
        resolution.validation_result = L"cached_negative_resolution";
        resolution.carrier_result = g_hook_state.knife_persistent_owner_negative_cache.carrier_result;
        resolution.factory_feasibility = g_hook_state.knife_persistent_owner_negative_cache.factory_feasibility;
        resolution.discovery_snapshot.viewmodel_absence_audit.result =
            g_hook_state.knife_persistent_owner_negative_cache.viewmodel_absence_result;
        resolution.result = KnifePersistentOwnerResolutionResult::NoExposedNonSyntheticRenderOwner;
        g_hook_state.viewmodel_factory_discovery_ran.store(true);
        g_hook_state.viewmodel_factory_observed.store(
            resolution.factory_feasibility ==
            nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::ViewmodelFactoryPresentWithoutInstance);
        log_resolution(false);
        return false;
    }

    if (clue_found &&
        validate_candidate(
            clue_entity_index,
            clue_entity,
            clue_item_view,
            clue_definition_index != 0 ? clue_definition_index : parent_definition_index,
            preferred_owner_kind,
            L"direct_target_validated",
            L"direct_target_synthetic",
            L"direct_target_world_alias",
            L"direct_target_world_owned_proxy",
            L"direct_target_item_view_unsafe",
            L"direct_target_not_weapon_like"))
    {
        return true;
    }
    if (resolution.result == KnifePersistentOwnerResolutionResult::PendingConfirmation)
    {
        return false;
    }

    int linked_owner_entity_index = -1;
    void* linked_owner_entity = nullptr;
    void* linked_owner_item_view = nullptr;
    if (clue_found &&
        TryResolveLinkedWeaponOwnerCarrier(
            entity_list,
            entity_cache,
            clue_entity,
            offsets,
            linked_owner_entity_index,
            linked_owner_entity,
            linked_owner_item_view))
    {
        if (ShouldLogWatchedKnifeAnimationTrace(xuid))
        {
            std::wstringstream stream;
            stream << L"Knife first-person linked owner candidate for XUID " << xuid
                << L": clue_source=" << resolution.clue_source
                << L", clue_entity=" << resolution.clue_entity_index
                << L", linked_owner_entity=" << linked_owner_entity_index
                << L", linked_owner_chain="
                << BuildKnifeOwnerChainDescriptor(
                       entity_cache,
                       linked_owner_entity_index,
                       linked_owner_entity,
                       offsets);
            nskinzcs2::Logger::Info(stream.str());
        }
        std::wstringstream stream;
        stream << L"linked_owner_entity=" << linked_owner_entity_index
            << L", linked_owner_ptr=" << FormatPointer(linked_owner_entity)
            << L", linked_owner_item_view=" << FormatPointer(linked_owner_item_view);
        log_providee_owner_search_stage_once(L"linked_owner", stream.str());
    }
    else
    {
        resolution.validation_result = L"linked_owner_missing";
        log_providee_owner_search_stage_once(L"linked_owner", L"missing");
    }
    (void)linked_owner_item_view;

    KnifeOwnerChainRenderableOwnerCandidate owner_chain_candidate {};
    if (clue_found &&
        TryResolveKnifeRenderableOwnerFromOwnerChain(
            entity_list,
            entity_cache,
            clue_entity,
            world_weapon_entity_index,
            offsets,
            xuid,
            parent_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            owner_chain_candidate))
    {
        if (ShouldLogWatchedKnifeAnimationTrace(xuid))
        {
            std::wstringstream stream;
            stream << L"Knife first-person owner-chain candidate for XUID " << xuid
                << L": clue_source=" << resolution.clue_source
                << L", clue_entity=" << resolution.clue_entity_index
                << L", owner_entity=" << owner_chain_candidate.entity_index
                << L", owner_depth=" << owner_chain_candidate.depth
                << L", owner_model_kind="
                << KnifeFirstPersonRenderableModelKindText(owner_chain_candidate.model_kind)
                << L", owner_chain="
                << BuildKnifeOwnerChainDescriptor(
                       entity_cache,
                       owner_chain_candidate.entity_index,
                       owner_chain_candidate.entity,
                       offsets);
            nskinzcs2::Logger::Info(stream.str());
        }
        std::wstringstream stream;
        stream << L"owner_entity=" << owner_chain_candidate.entity_index
            << L", owner_depth=" << owner_chain_candidate.depth
            << L", owner_model_kind="
            << KnifeFirstPersonRenderableModelKindText(owner_chain_candidate.model_kind);
        log_providee_owner_search_stage_once(L"owner_chain", stream.str());
    }
    else if (should_force_providee_owner_search_diagnostics)
    {
        log_providee_owner_search_stage_once(L"owner_chain", L"missing");
    }

    if (clue_found)
    {
        int scanned_candidates = 0;
        int safe_weapon_like_candidates = 0;
        int matched_candidates = 0;
        int best_candidate_entity_index = -1;
        void* best_candidate_entity = nullptr;
        void* best_candidate_item_view = nullptr;
        int best_candidate_definition_index = 0;
        int best_candidate_score = -1;
        int best_owner_chain_depth = -1;
        const wchar_t* best_match_reason = L"none";
        auto best_owner_kind = nskinzcs2::runtime::KnifeFirstPersonOwnerKind::None;

        for (std::size_t index = 0; index < entity_cache.size(); ++index)
        {
            auto* candidate_entity = entity_cache[index];
            if (candidate_entity == nullptr)
            {
                continue;
            }

            const auto candidate_entity_index = static_cast<int>(index);
            if (!IsResolvedRuntimeEntityIndex(candidate_entity_index) ||
                IsSyntheticRuntimeEntityIndex(candidate_entity_index) ||
                candidate_entity_index == world_weapon_entity_index)
            {
                continue;
            }

            ++scanned_candidates;

            auto* candidate_item_view = ResolveWeaponItemView(candidate_entity, offsets);
            if (candidate_item_view == nullptr)
            {
                continue;
            }

            const auto model_kind =
                ClassifyKnifeFirstPersonRenderableModel(candidate_entity, offsets);
            if (model_kind != KnifeFirstPersonRenderableModelKind::WeaponLike)
            {
                continue;
            }

            int safe_definition_index = 0;
            if (!IsSafeLinkedWeaponItemView(
                    candidate_item_view,
                    offsets,
                    xuid,
                    parent_definition_index,
                    known_definition_indices,
                    knife_definition_indices,
                    glove_definition_indices,
                    safe_definition_index))
            {
                continue;
            }

            ++safe_weapon_like_candidates;

            int candidate_score = -1;
            int owner_chain_depth = -1;
            const wchar_t* match_reason = L"none";
            if (resolution.clue_render_object.entity_resolved &&
                resolution.clue_render_object.entity != nullptr &&
                candidate_entity == resolution.clue_render_object.entity)
            {
                candidate_score = 300;
                match_reason = L"same_entity_ptr";
            }
            else
            {
                std::uintptr_t candidate_model_state_address = 0;
                const auto candidate_model_state_resolved =
                    TryResolveEntityModelStateAddress(
                        candidate_entity,
                        offsets,
                        candidate_model_state_address) &&
                    candidate_model_state_address != 0;
                if (resolution.clue_render_object.item_view_resolved &&
                    resolution.clue_render_object.item_view != nullptr &&
                    resolution.clue_render_object.model_state_resolved &&
                    candidate_item_view == resolution.clue_render_object.item_view &&
                    candidate_model_state_resolved &&
                    candidate_model_state_address == resolution.clue_render_object.model_state)
                {
                    candidate_score = 200;
                    match_reason = L"shared_item_view_and_model_state";
                }
                else if (KnifeOwnerChainContainsEntity(
                             entity_list,
                             entity_cache,
                             resolution.clue_entity_index,
                             resolution.clue_entity,
                             offsets,
                             candidate_entity_index,
                             owner_chain_depth))
                {
                    candidate_score = 100;
                    match_reason = L"owner_chain_matches_render_object";
                }
            }

            if (candidate_score < 0)
            {
                continue;
            }

            ++matched_candidates;

            const auto owner_kind =
                ResolvePersistentKnifeOwnerKind(
                    candidate_entity_index,
                    providee_entity_index,
                    viewmodel_entity_index,
                    preferred_owner_kind);
            if (owner_kind == preferred_owner_kind)
            {
                candidate_score += 10;
            }
            if (candidate_entity_index == providee_entity_index ||
                candidate_entity_index == viewmodel_entity_index)
            {
                candidate_score += 20;
            }
            if (owner_chain_depth >= 0)
            {
                candidate_score += std::max(0, 8 - owner_chain_depth);
            }

            if (best_candidate_entity == nullptr ||
                candidate_score > best_candidate_score ||
                (candidate_score == best_candidate_score &&
                 candidate_entity_index < best_candidate_entity_index))
            {
                best_candidate_entity_index = candidate_entity_index;
                best_candidate_entity = candidate_entity;
                best_candidate_item_view = candidate_item_view;
                best_candidate_definition_index =
                    safe_definition_index != 0
                        ? safe_definition_index
                        : parent_definition_index;
                best_candidate_score = candidate_score;
                best_owner_chain_depth = owner_chain_depth;
                best_match_reason = match_reason;
                best_owner_kind = owner_kind;
            }
        }

        if (ShouldLogWatchedKnifeAnimationTrace(xuid))
        {
            std::wstringstream stream;
            stream << L"Knife first-person owner reverse scan for XUID " << xuid
                << L": clue_source=" << resolution.clue_source
                << L", clue_entity=" << resolution.clue_entity_index
                << L", clue_render_object="
                << BuildKnifeRenderObjectIdentityDescriptor(resolution.clue_render_object)
                << L", scanned=" << scanned_candidates
                << L", safe_weapon_like=" << safe_weapon_like_candidates
                << L", matched=" << matched_candidates;
            if (best_candidate_entity != nullptr)
            {
                stream << L", selected_entity=" << best_candidate_entity_index
                    << L", selected_owner_kind="
                    << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(best_owner_kind)
                    << L", selected_definition=" << best_candidate_definition_index
                    << L", match_reason=" << best_match_reason;
                if (best_owner_chain_depth >= 0)
                {
                    stream << L", owner_chain_depth=" << best_owner_chain_depth;
                }
            }
            else
            {
                stream << L", selected=<none>";
            }
            nskinzcs2::Logger::Info(stream.str());
        }
        {
            std::wstringstream stream;
            stream << L"scanned=" << scanned_candidates
                << L", safe_weapon_like=" << safe_weapon_like_candidates
                << L", matched=" << matched_candidates;
            if (best_candidate_entity != nullptr)
            {
                stream << L", selected_entity=" << best_candidate_entity_index
                    << L", selected_definition=" << best_candidate_definition_index
                    << L", match_reason=" << best_match_reason;
            }
            else
            {
                stream << L", selected=<none>";
            }
            log_providee_owner_search_stage_once(L"reverse_scan", stream.str());
        }

        if (best_candidate_entity != nullptr)
        {
            return accept_candidate(
                best_candidate_entity_index,
                best_candidate_entity,
                best_candidate_item_view,
                best_candidate_definition_index,
                best_owner_kind,
                L"reverse_scan_validated");
        }

        struct CompleteCarrierCandidate
        {
            int entity_index = -1;
            void* entity = nullptr;
            void* item_view = nullptr;
            int definition_index = 0;
            int definition_readback = 0;
            int score = -1;
            int owner_index = -1;
            int old_move_parent_index = -1;
            int owner_chain_depth_to_pawn = -1;
            int owner_chain_depth_to_providee = -1;
            int owner_chain_depth_to_viewmodel = -1;
            std::uint32_t item_id_high = 0;
            std::uint32_t account_id = 0;
            bool complete_fields_ok = false;
            bool static_attrs_readable = false;
            bool dynamic_attrs_readable = false;
            bool definition_readable = false;
            bool definition_ok = false;
            bool item_id_high_readable = false;
            bool item_id_high_ok = false;
            bool account_id_readable = false;
            bool account_ok = false;
            bool initialized_readable = false;
            bool initialized_ok = false;
            bool owner_matches_player = false;
            bool old_move_parent_matches_player = false;
            bool owner_chain_matches_player = false;
            bool safe_linked_item_view = false;
            bool shared_world_item_view = false;
            bool world_owned_proxy = false;
            bool relation_to_render_object = false;
            bool direct_viewmodel_attachment = false;
            bool reverse_viewmodel_attachment = false;
            bool direct_old_providee_attachment = false;
            bool reverse_old_providee_reference = false;
            bool explicit_owner_child_match = false;
            bool scene_owner_match = false;
            bool world_neighborhood_match = false;
            bool exact_render_object_entity = false;
            bool exact_render_object_alias = false;
            int shell_entity_index = -1;
            const wchar_t* shell_source = L"none";
            bool shell_relation_to_render_object = false;
            bool shell_owner_chain_matches_player = false;
            bool shell_direct_viewmodel_attachment = false;
            bool shell_reverse_viewmodel_attachment = false;
            bool shell_world_neighborhood_match = false;
            bool promotable_relation = false;
            bool discovery_relevant = false;
            bool hidden_from_live_cache = false;
            const wchar_t* bucket = L"safe_weapon_like";
            const wchar_t* scan_range = L"live_cache";
            const wchar_t* reason = L"none";
            nskinzcs2::runtime::KnifeFirstPersonOwnerKind owner_kind =
                nskinzcs2::runtime::KnifeFirstPersonOwnerKind::None;
        };

        struct CompleteCarrierScanSummary
        {
            int scanned = 0;
            int safe_weapon_like = 0;
            int complete_fields = 0;
            int related_complete = 0;
            int relevant_incomplete = 0;
            int writable_related = 0;
            int hidden_from_live_cache = 0;
            int resolution_failures = 0;
            bool related_incomplete_found = false;
            CompleteCarrierCandidate best {};
            std::vector<CompleteCarrierCandidate> top {};
        };

        auto read_vector_readable =
            [&](void* item_view, const std::ptrdiff_t item_list_offset) noexcept
            {
                if (item_view == nullptr || item_list_offset == 0 || offsets.attribute_list_attributes == 0)
                {
                    return false;
                }

                NetworkVectorView vector_view {};
                return TryReadNetworkVectorView(
                    reinterpret_cast<const std::uint8_t*>(item_view) +
                        item_list_offset + offsets.attribute_list_attributes,
                    vector_view);
            };

        auto append_top_candidate =
            [](std::vector<CompleteCarrierCandidate>& top_candidates, const CompleteCarrierCandidate& candidate)
            {
                top_candidates.push_back(candidate);
                std::sort(
                    top_candidates.begin(),
                    top_candidates.end(),
                    [](const CompleteCarrierCandidate& lhs, const CompleteCarrierCandidate& rhs)
                    {
                        if (lhs.score != rhs.score)
                        {
                            return lhs.score > rhs.score;
                        }
                        return lhs.entity_index < rhs.entity_index;
                    });
                constexpr std::size_t kMaxSamples = 5;
                if (top_candidates.size() > kMaxSamples)
                {
                    top_candidates.resize(kMaxSamples);
                }
            };

        auto build_complete_candidate_descriptor =
            [&](const CompleteCarrierCandidate& candidate)
            {
                std::wstringstream stream;
                stream << BuildWeaponRenderConsumerEntityDiagnostic(
                    L"carrier",
                    candidate.entity_index,
                    candidate.entity,
                    candidate.item_view,
                    offsets);
                auto descriptor = stream.str();
                if (!descriptor.empty() && descriptor.back() == L'}')
                {
                    descriptor.pop_back();
                }

                std::wstringstream suffix;
                suffix << L", score=" << candidate.score
                    << L", bucket=" << candidate.bucket
                    << L", scan_range=" << candidate.scan_range
                    << L", hidden_from_live_cache=" << (candidate.hidden_from_live_cache ? 1 : 0)
                    << L", reason=" << candidate.reason
                    << L", owner_kind="
                    << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(candidate.owner_kind)
                    << L", complete_fields=" << (candidate.complete_fields_ok ? 1 : 0)
                    << L", definition_ok=" << (candidate.definition_ok ? 1 : 0)
                    << L", item_id_high_ok=" << (candidate.item_id_high_ok ? 1 : 0)
                    << L", account_ok=" << (candidate.account_ok ? 1 : 0)
                    << L", initialized_ok=" << (candidate.initialized_ok ? 1 : 0)
                    << L", static_attrs_readable=" << (candidate.static_attrs_readable ? 1 : 0)
                    << L", dynamic_attrs_readable=" << (candidate.dynamic_attrs_readable ? 1 : 0)
                    << L", owner_index=" << candidate.owner_index
                    << L", old_move_parent_index=" << candidate.old_move_parent_index
                    << L", owner_matches_player=" << (candidate.owner_matches_player ? 1 : 0)
                    << L", old_move_parent_matches_player=" << (candidate.old_move_parent_matches_player ? 1 : 0)
                    << L", owner_chain_matches_player=" << (candidate.owner_chain_matches_player ? 1 : 0)
                    << L", owner_chain_depth_to_pawn=" << candidate.owner_chain_depth_to_pawn
                    << L", owner_chain_depth_to_providee=" << candidate.owner_chain_depth_to_providee
                    << L", owner_chain_depth_to_viewmodel=" << candidate.owner_chain_depth_to_viewmodel
                    << L", shared_world_item_view=" << (candidate.shared_world_item_view ? 1 : 0)
                    << L", relation_to_render_object=" << (candidate.relation_to_render_object ? 1 : 0)
                    << L", direct_viewmodel_attachment=" << (candidate.direct_viewmodel_attachment ? 1 : 0)
                    << L", reverse_viewmodel_attachment=" << (candidate.reverse_viewmodel_attachment ? 1 : 0)
                    << L", direct_old_providee_attachment=" << (candidate.direct_old_providee_attachment ? 1 : 0)
                    << L", reverse_old_providee_reference=" << (candidate.reverse_old_providee_reference ? 1 : 0)
                    << L", explicit_owner_child_match=" << (candidate.explicit_owner_child_match ? 1 : 0)
                    << L", scene_owner_match=" << (candidate.scene_owner_match ? 1 : 0)
                    << L", world_neighborhood_match=" << (candidate.world_neighborhood_match ? 1 : 0)
                    << L", exact_render_object_entity=" << (candidate.exact_render_object_entity ? 1 : 0)
                    << L", exact_render_object_alias=" << (candidate.exact_render_object_alias ? 1 : 0)
                    << L", shell_entity=" << candidate.shell_entity_index
                    << L", shell_source=" << candidate.shell_source
                    << L", shell_relation_to_render_object="
                    << (candidate.shell_relation_to_render_object ? 1 : 0)
                    << L", shell_owner_chain_matches_player="
                    << (candidate.shell_owner_chain_matches_player ? 1 : 0)
                    << L", shell_direct_viewmodel_attachment="
                    << (candidate.shell_direct_viewmodel_attachment ? 1 : 0)
                    << L", shell_reverse_viewmodel_attachment="
                    << (candidate.shell_reverse_viewmodel_attachment ? 1 : 0)
                    << L", shell_world_neighborhood_match="
                    << (candidate.shell_world_neighborhood_match ? 1 : 0)
                    << L", promotable_relation=" << (candidate.promotable_relation ? 1 : 0)
                    << L", discovery_relevant=" << (candidate.discovery_relevant ? 1 : 0)
                    << L", safe_linked_item_view=" << (candidate.safe_linked_item_view ? 1 : 0)
                    << L", world_owned_proxy=" << (candidate.world_owned_proxy ? 1 : 0)
                    << L", definition_readback=";
                if (candidate.definition_readable)
                {
                    suffix << candidate.definition_readback;
                }
                else
                {
                    suffix << L"?";
                }
                suffix << L", item_id_high=";
                if (candidate.item_id_high_readable)
                {
                    suffix << L"0x" << std::hex << std::uppercase << candidate.item_id_high
                        << std::dec << std::nouppercase;
                }
                else
                {
                    suffix << L"?";
                }
                suffix << L", account_id=";
                if (candidate.account_id_readable)
                {
                    suffix << candidate.account_id;
                }
                else
                {
                    suffix << L"?";
                }
                suffix << L'}';
                descriptor += suffix.str();
                return descriptor;
            };

        const auto expected_account_id = AccountIdFromXuid(xuid);
        const auto matches_player_index =
            [&](const int entity_index) noexcept
            {
                return entity_index >= 0 &&
                    (entity_index == player_binding.pawn_entity_index ||
                     entity_index == providee_entity_index ||
                     entity_index == viewmodel_entity_index);
            };

        std::uint32_t world_viewmodel_handle = kInvalidEntityHandle;
        if (offsets.econ_entity_viewmodel_attachment != 0)
        {
            SafeReadField(world_weapon_entity, offsets.econ_entity_viewmodel_attachment, world_viewmodel_handle);
        }
        const auto world_viewmodel_entity_index =
            world_viewmodel_handle != kInvalidEntityHandle
                ? HandleToEntityIndex(world_viewmodel_handle)
                : -1;

        std::uint32_t world_providee_handle = kInvalidEntityHandle;
        if (offsets.econ_entity_old_providee != 0)
        {
            SafeReadField(world_weapon_entity, offsets.econ_entity_old_providee, world_providee_handle);
        }
        const auto world_providee_entity_index =
            world_providee_handle != kInvalidEntityHandle
                ? HandleToEntityIndex(world_providee_handle)
                : -1;

        RenderedWorldWeaponTrace world_trace {};
        bool world_trace_built = false;
        if (const auto owned_weapon_handle_it =
                player_binding.owned_weapon_handles_by_entity_index.find(world_weapon_entity_index);
            owned_weapon_handle_it != player_binding.owned_weapon_handles_by_entity_index.end() &&
            owned_weapon_handle_it->second != kInvalidEntityHandle)
        {
            world_trace_built =
                TryBuildRenderedWorldWeaponTrace(
                    entity_list,
                    entity_cache,
                    player_binding,
                    xuid,
                    owned_weapon_handle_it->second,
                    world_weapon_entity_index,
                    world_weapon_entity,
                    offsets,
                    world_trace);
        }

        resolution.discovery_snapshot.viewmodel_absence_audit =
            BuildKnifeViewmodelAbsenceAudit(
                entity_list,
                entity_cache,
                player_binding,
                world_weapon_entity_index,
                world_weapon_entity,
                offsets,
                xuid,
                parent_definition_index,
                known_definition_indices,
                knife_definition_indices,
                glove_definition_indices,
                providee_entity_index,
                viewmodel_entity_index,
                resolution.clue_render_object);
        LogKnifeViewmodelAbsenceAudit(
            xuid,
            resolution.discovery_snapshot.viewmodel_absence_audit);
        log_providee_missing_handle_diagnostic_once(
            resolution.discovery_snapshot.viewmodel_absence_audit);

        auto join_trace_samples =
            [](const std::vector<std::wstring>& samples)
            {
                if (samples.empty())
                {
                    return std::wstring(L"<none>");
                }

                std::wstringstream stream;
                for (std::size_t index = 0; index < samples.size(); ++index)
                {
                    if (index != 0)
                    {
                        stream << L" | ";
                    }
                    stream << samples[index];
                }
                return stream.str();
            };

        auto format_optional_handle =
            [](const bool readable, const std::uint32_t raw_handle)
            {
                if (!readable)
                {
                    return std::wstring(L"?");
                }

                std::wstringstream stream;
                stream << L"0x" << std::hex << std::uppercase << raw_handle
                    << std::dec << std::nouppercase;
                return stream.str();
            };

        auto build_relation_entity_descriptor =
            [&](const wchar_t* label,
                const int entity_index_hint,
                void* entity,
                const wchar_t* relation_kind,
                const std::uint32_t relation_handle,
                const int scene_depth)
            {
                std::wstringstream stream;
                if (entity == nullptr)
                {
                    stream << (label != nullptr ? label : L"entity")
                        << L"{relation=" << (relation_kind != nullptr ? relation_kind : L"none")
                        << L", via_handle=" << format_optional_handle(true, relation_handle)
                        << L", scene_depth=" << scene_depth
                        << L", entity=" << entity_index_hint
                        << L", entity_ptr=0x0}";
                    return stream.str();
                }

                auto entity_index = entity_index_hint;
                if (entity_index < 0)
                {
                    entity_index = ResolveEntityIndexFromPointer(entity_cache, entity);
                    if (entity_index < 0)
                    {
                        entity_index = BuildSyntheticEntityIndex(entity, 0x4B444550u);
                    }
                }

                auto* item_view = ResolveWeaponItemView(entity, offsets);
                std::wstring descriptor =
                    BuildWeaponRenderConsumerEntityDiagnostic(
                        label != nullptr ? label : L"entity",
                        entity_index,
                        entity,
                        item_view,
                        offsets);
                if (!descriptor.empty() && descriptor.back() == L'}')
                {
                    descriptor.pop_back();
                }

                std::uint32_t owner_handle = kInvalidEntityHandle;
                const auto owner_handle_readable =
                    offsets.base_owner_entity != 0 &&
                    SafeReadField(entity, offsets.base_owner_entity, owner_handle);
                const auto owner_index =
                    owner_handle_readable ? HandleToEntityIndex(owner_handle) : -1;

                std::uint32_t old_move_parent_handle = kInvalidEntityHandle;
                const auto old_move_parent_handle_readable =
                    offsets.base_old_move_parent != 0 &&
                    SafeReadField(entity, offsets.base_old_move_parent, old_move_parent_handle);
                const auto old_move_parent_index =
                    old_move_parent_handle_readable ? HandleToEntityIndex(old_move_parent_handle) : -1;

                std::uint32_t viewmodel_handle = kInvalidEntityHandle;
                const auto viewmodel_handle_readable =
                    offsets.econ_entity_viewmodel_attachment != 0 &&
                    SafeReadField(entity, offsets.econ_entity_viewmodel_attachment, viewmodel_handle);
                const auto attached_viewmodel_index =
                    viewmodel_handle_readable ? HandleToEntityIndex(viewmodel_handle) : -1;

                std::uint32_t providee_handle = kInvalidEntityHandle;
                const auto providee_handle_readable =
                    offsets.econ_entity_old_providee != 0 &&
                    SafeReadField(entity, offsets.econ_entity_old_providee, providee_handle);
                const auto attached_providee_index =
                    providee_handle_readable ? HandleToEntityIndex(providee_handle) : -1;

                void* scene_node = nullptr;
                const auto scene_node_resolved =
                    offsets.base_entity_game_scene_node != 0 &&
                    SafeReadField(entity, offsets.base_entity_game_scene_node, scene_node) &&
                    scene_node != nullptr;

                void* scene_owner_entity = nullptr;
                int scene_owner_index = -1;
                if (scene_node_resolved && offsets.game_scene_node_owner != 0)
                {
                    if (SafeReadField(scene_node, offsets.game_scene_node_owner, scene_owner_entity) &&
                        scene_owner_entity != nullptr)
                    {
                        scene_owner_index = ResolveEntityIndexFromPointer(entity_cache, scene_owner_entity);
                        if (scene_owner_index < 0)
                        {
                            scene_owner_index = BuildSyntheticEntityIndex(scene_owner_entity, 0x4B445243u);
                        }
                    }
                }

                int definition_index = 0;
                const auto definition_readable =
                    item_view != nullptr &&
                    TryReadItemDefinitionIndex(item_view, offsets, definition_index);
                const auto render_identity =
                    ResolveKnifeRenderObjectIdentity(entity, item_view, offsets);
                const auto render_match =
                    resolution.clue_render_object.IsUsable() &&
                    KnifeRenderObjectIdentityMatches(render_identity, resolution.clue_render_object);

                int owner_chain_depth_to_pawn = -1;
                const auto owner_chain_to_pawn =
                    player_binding.pawn_entity_index >= 0 &&
                    KnifeOwnerChainContainsEntity(
                        entity_list,
                        entity_cache,
                        entity_index,
                        entity,
                        offsets,
                        player_binding.pawn_entity_index,
                        owner_chain_depth_to_pawn);

                int owner_chain_depth_to_providee = -1;
                const auto owner_chain_to_providee =
                    providee_entity_index >= 0 &&
                    KnifeOwnerChainContainsEntity(
                        entity_list,
                        entity_cache,
                        entity_index,
                        entity,
                        offsets,
                        providee_entity_index,
                        owner_chain_depth_to_providee);

                int owner_chain_depth_to_viewmodel = -1;
                const auto owner_chain_to_viewmodel =
                    viewmodel_entity_index >= 0 &&
                    KnifeOwnerChainContainsEntity(
                        entity_list,
                        entity_cache,
                        entity_index,
                        entity,
                        offsets,
                        viewmodel_entity_index,
                        owner_chain_depth_to_viewmodel);

                int owner_chain_depth_to_world = -1;
                const auto owner_chain_to_world =
                    world_weapon_entity_index >= 0 &&
                    KnifeOwnerChainContainsEntity(
                        entity_list,
                        entity_cache,
                        entity_index,
                        entity,
                        offsets,
                        world_weapon_entity_index,
                        owner_chain_depth_to_world);

                descriptor +=
                    std::wstring(L", relation=") +
                    (relation_kind != nullptr ? relation_kind : L"none") +
                    L", via_handle=" + format_optional_handle(true, relation_handle) +
                    L", scene_depth=" + std::to_wstring(scene_depth) +
                    L", owner_handle=" + format_optional_handle(owner_handle_readable, owner_handle) +
                    L", owner_index=" + std::to_wstring(owner_index) +
                    L", old_move_parent_handle=" +
                    format_optional_handle(old_move_parent_handle_readable, old_move_parent_handle) +
                    L", old_move_parent_index=" + std::to_wstring(old_move_parent_index) +
                    L", viewmodel_handle=" + format_optional_handle(viewmodel_handle_readable, viewmodel_handle) +
                    L", attached_viewmodel_index=" + std::to_wstring(attached_viewmodel_index) +
                    L", providee_handle=" + format_optional_handle(providee_handle_readable, providee_handle) +
                    L", attached_providee_index=" + std::to_wstring(attached_providee_index) +
                    L", scene_node=" + FormatPointer(scene_node) +
                    L", scene_owner=" + std::to_wstring(scene_owner_index) +
                    L", scene_owner_ptr=" + FormatPointer(scene_owner_entity) +
                    L", definition_readback=" +
                    (definition_readable ? std::to_wstring(definition_index) : std::wstring(L"?")) +
                    L", world_match=" + std::to_wstring(entity_index == world_weapon_entity_index ? 1 : 0) +
                    L", pawn_match=" + std::to_wstring(entity_index == player_binding.pawn_entity_index ? 1 : 0) +
                    L", providee_match=" + std::to_wstring(entity_index == providee_entity_index ? 1 : 0) +
                    L", viewmodel_match=" + std::to_wstring(entity_index == viewmodel_entity_index ? 1 : 0) +
                    L", trace_scene_owner_match=" +
                    std::to_wstring(world_trace_built &&
                                            entity_index == world_trace.scene_owner_entity_index
                                        ? 1
                                        : 0) +
                    L", trace_explicit_child_match=" +
                    std::to_wstring(world_trace_built &&
                                            entity_index == world_trace.explicit_owner_child_entity_index
                                        ? 1
                                        : 0) +
                    L", trace_hud_match=" +
                    std::to_wstring(world_trace_built &&
                                            entity_index == world_trace.hud_weapon_entity_index
                                        ? 1
                                        : 0) +
                    L", render_object_match=" + std::to_wstring(render_match ? 1 : 0) +
                    L", owner_chain_to_pawn=" + std::to_wstring(owner_chain_to_pawn ? 1 : 0) +
                    L", owner_chain_depth_to_pawn=" + std::to_wstring(owner_chain_depth_to_pawn) +
                    L", owner_chain_to_providee=" + std::to_wstring(owner_chain_to_providee ? 1 : 0) +
                    L", owner_chain_depth_to_providee=" +
                    std::to_wstring(owner_chain_depth_to_providee) +
                    L", owner_chain_to_viewmodel=" + std::to_wstring(owner_chain_to_viewmodel ? 1 : 0) +
                    L", owner_chain_depth_to_viewmodel=" +
                    std::to_wstring(owner_chain_depth_to_viewmodel) +
                    L", owner_chain_to_world=" + std::to_wstring(owner_chain_to_world ? 1 : 0) +
                    L", owner_chain_depth_to_world=" + std::to_wstring(owner_chain_depth_to_world) +
                    L", " + BuildRuntimeEntityRttiDescriptor(entity) +
                    L", owner_chain=" +
                    BuildKnifeOwnerChainDescriptor(entity_cache, entity_index, entity, offsets) +
                    L'}';
                return descriptor;
            };

        struct OwnerRelationResolutionProbe
        {
            void* cached_entity = nullptr;
            void* raw_entity = nullptr;
            void* wrapper_entity = nullptr;
            void* resolved_entity = nullptr;
            bool raw_lookup_ok = false;
            bool wrapper_resolved = false;
            int roundtrip_index = -1;
        };

        auto probe_owner_relation_entity =
            [&](const int target_entity_index)
            {
                OwnerRelationResolutionProbe probe {};
                if (target_entity_index < 0 || IsSyntheticRuntimeEntityIndex(target_entity_index))
                {
                    return probe;
                }

                if (static_cast<std::size_t>(target_entity_index) < entity_cache.size())
                {
                    probe.cached_entity = entity_cache[static_cast<std::size_t>(target_entity_index)];
                }

                probe.raw_lookup_ok =
                    TryGetEntityFromIndex(entity_list, target_entity_index, probe.raw_entity);
                probe.wrapper_resolved =
                    TryResolveKnifeOwnerChainEntity(
                        entity_list,
                        entity_cache,
                        target_entity_index,
                        probe.wrapper_entity) &&
                    probe.wrapper_entity != nullptr;
                probe.resolved_entity =
                    probe.wrapper_entity != nullptr
                        ? probe.wrapper_entity
                        : (probe.cached_entity != nullptr ? probe.cached_entity : probe.raw_entity);
                if (probe.resolved_entity != nullptr)
                {
                    probe.roundtrip_index =
                        ResolveEntityIndexFromPointer(entity_cache, probe.resolved_entity);
                }
                return probe;
            };

        auto log_candidate_relation_deep_trace =
            [&](const CompleteCarrierCandidate& candidate,
                const int relation_entity_index,
                const wchar_t* relation_label)
            {
                if (!ShouldLogWatchedKnifeAnimationTrace(xuid) ||
                    relation_entity_index < 0 ||
                    IsSyntheticRuntimeEntityIndex(relation_entity_index))
                {
                    return;
                }

                const auto relation_probe = probe_owner_relation_entity(relation_entity_index);

                std::vector<std::wstring> reverse_ref_samples;
                reverse_ref_samples.reserve(12);
                std::vector<std::wstring> scene_child_samples;
                scene_child_samples.reserve(12);
                std::vector<std::wstring> disconnect_reasons;
                disconnect_reasons.reserve(8);

                int reverse_owner_ref_count = 0;
                int reverse_old_move_parent_ref_count = 0;
                int reverse_viewmodel_ref_count = 0;
                int reverse_providee_ref_count = 0;
                int reverse_scene_owner_ref_count = 0;
                int scene_child_count = 0;
                int scene_child_weapon_like_count = 0;
                int scene_child_character_like_count = 0;
                int scene_child_synthetic_count = 0;
                int scene_child_ownerless_count = 0;

                const auto highest_live_entity_index =
                    std::max(g_hook_state.highest_live_entity_index.load(), static_cast<int>(entity_cache.size()) - 1);
                for (int entity_index = 0; entity_index <= highest_live_entity_index; ++entity_index)
                {
                    void* ref_entity = nullptr;
                    if (entity_index >= 0 && static_cast<std::size_t>(entity_index) < entity_cache.size())
                    {
                        ref_entity = entity_cache[static_cast<std::size_t>(entity_index)];
                    }
                    if (ref_entity == nullptr &&
                        (!TryGetEntityFromIndex(entity_list, entity_index, ref_entity) || ref_entity == nullptr))
                    {
                        continue;
                    }

                    std::uint32_t owner_handle = kInvalidEntityHandle;
                    if (offsets.base_owner_entity != 0 &&
                        SafeReadField(ref_entity, offsets.base_owner_entity, owner_handle) &&
                        HandleToEntityIndex(owner_handle) == relation_entity_index)
                    {
                        ++reverse_owner_ref_count;
                        if (reverse_ref_samples.size() < 10)
                        {
                            reverse_ref_samples.push_back(
                                build_relation_entity_descriptor(
                                    L"reverse_owner_ref",
                                    entity_index,
                                    ref_entity,
                                    L"base_owner_entity",
                                    owner_handle,
                                    0));
                        }
                    }

                    std::uint32_t old_move_parent_handle = kInvalidEntityHandle;
                    if (offsets.base_old_move_parent != 0 &&
                        SafeReadField(ref_entity, offsets.base_old_move_parent, old_move_parent_handle) &&
                        HandleToEntityIndex(old_move_parent_handle) == relation_entity_index)
                    {
                        ++reverse_old_move_parent_ref_count;
                        if (reverse_ref_samples.size() < 10)
                        {
                            reverse_ref_samples.push_back(
                                build_relation_entity_descriptor(
                                    L"reverse_old_move_parent_ref",
                                    entity_index,
                                    ref_entity,
                                    L"base_old_move_parent",
                                    old_move_parent_handle,
                                    0));
                        }
                    }

                    std::uint32_t viewmodel_handle = kInvalidEntityHandle;
                    if (offsets.econ_entity_viewmodel_attachment != 0 &&
                        SafeReadField(ref_entity, offsets.econ_entity_viewmodel_attachment, viewmodel_handle) &&
                        HandleToEntityIndex(viewmodel_handle) == relation_entity_index)
                    {
                        ++reverse_viewmodel_ref_count;
                        if (reverse_ref_samples.size() < 10)
                        {
                            reverse_ref_samples.push_back(
                                build_relation_entity_descriptor(
                                    L"reverse_viewmodel_ref",
                                    entity_index,
                                    ref_entity,
                                    L"econ_entity_viewmodel_attachment",
                                    viewmodel_handle,
                                    0));
                        }
                    }

                    std::uint32_t providee_handle = kInvalidEntityHandle;
                    if (offsets.econ_entity_old_providee != 0 &&
                        SafeReadField(ref_entity, offsets.econ_entity_old_providee, providee_handle) &&
                        HandleToEntityIndex(providee_handle) == relation_entity_index)
                    {
                        ++reverse_providee_ref_count;
                        if (reverse_ref_samples.size() < 10)
                        {
                            reverse_ref_samples.push_back(
                                build_relation_entity_descriptor(
                                    L"reverse_providee_ref",
                                    entity_index,
                                    ref_entity,
                                    L"econ_entity_old_providee",
                                    providee_handle,
                                    0));
                        }
                    }

                    void* ref_scene_node = nullptr;
                    if (offsets.base_entity_game_scene_node != 0 &&
                        offsets.game_scene_node_owner != 0 &&
                        SafeReadField(ref_entity, offsets.base_entity_game_scene_node, ref_scene_node) &&
                        ref_scene_node != nullptr)
                    {
                        void* scene_owner_entity = nullptr;
                        if (SafeReadField(ref_scene_node, offsets.game_scene_node_owner, scene_owner_entity) &&
                            scene_owner_entity != nullptr)
                        {
                            auto scene_owner_index =
                                ResolveEntityIndexFromPointer(entity_cache, scene_owner_entity);
                            if (scene_owner_index < 0)
                            {
                                scene_owner_index =
                                    BuildSyntheticEntityIndex(scene_owner_entity, 0x4B445244u);
                            }
                            if (scene_owner_index == relation_entity_index)
                            {
                                ++reverse_scene_owner_ref_count;
                                if (reverse_ref_samples.size() < 10)
                                {
                                    reverse_ref_samples.push_back(
                                        build_relation_entity_descriptor(
                                            L"reverse_scene_owner_ref",
                                            entity_index,
                                            ref_entity,
                                            L"game_scene_node_owner",
                                            kInvalidEntityHandle,
                                            0));
                                }
                            }
                        }
                    }
                }

                if (relation_probe.resolved_entity != nullptr &&
                    offsets.base_entity_game_scene_node != 0 &&
                    offsets.game_scene_node_child != 0 &&
                    offsets.game_scene_node_next_sibling != 0 &&
                    offsets.game_scene_node_owner != 0)
                {
                    void* scene_node = nullptr;
                    if (SafeReadField(
                            relation_probe.resolved_entity,
                            offsets.base_entity_game_scene_node,
                            scene_node) &&
                        scene_node != nullptr)
                    {
                        struct PendingSceneNode
                        {
                            void* scene_node = nullptr;
                            int depth = 0;
                        };

                        void* first_child_scene_node = nullptr;
                        if (SafeReadField(scene_node, offsets.game_scene_node_child, first_child_scene_node) &&
                            first_child_scene_node != nullptr)
                        {
                            std::vector<PendingSceneNode> pending_scene_nodes;
                            pending_scene_nodes.reserve(16);
                            pending_scene_nodes.push_back({first_child_scene_node, 1});

                            std::unordered_set<void*> visited_scene_nodes;
                            while (!pending_scene_nodes.empty())
                            {
                                const auto pending = pending_scene_nodes.back();
                                pending_scene_nodes.pop_back();
                                auto* child_scene_node = pending.scene_node;
                                if (child_scene_node == nullptr ||
                                    !visited_scene_nodes.insert(child_scene_node).second)
                                {
                                    continue;
                                }

                                void* nested_child_scene_node = nullptr;
                                if (SafeReadField(
                                        child_scene_node,
                                        offsets.game_scene_node_child,
                                        nested_child_scene_node) &&
                                    nested_child_scene_node != nullptr)
                                {
                                    pending_scene_nodes.push_back(
                                        {nested_child_scene_node, pending.depth + 1});
                                }

                                void* next_sibling_scene_node = nullptr;
                                if (SafeReadField(
                                        child_scene_node,
                                        offsets.game_scene_node_next_sibling,
                                        next_sibling_scene_node) &&
                                    next_sibling_scene_node != nullptr)
                                {
                                    pending_scene_nodes.push_back({next_sibling_scene_node, pending.depth});
                                }

                                ++scene_child_count;

                                void* child_owner_entity = nullptr;
                                if (!SafeReadField(
                                        child_scene_node,
                                        offsets.game_scene_node_owner,
                                        child_owner_entity) ||
                                    child_owner_entity == nullptr)
                                {
                                    ++scene_child_ownerless_count;
                                    if (scene_child_samples.size() < 10)
                                    {
                                        std::wstringstream sample_stream;
                                        sample_stream << L"scene_child_ownerless{scene_depth="
                                            << pending.depth
                                            << L", scene_node=" << FormatPointer(child_scene_node)
                                            << L"}";
                                        scene_child_samples.push_back(sample_stream.str());
                                    }
                                    continue;
                                }

                                auto child_owner_index =
                                    ResolveEntityIndexFromPointer(entity_cache, child_owner_entity);
                                if (child_owner_index < 0)
                                {
                                    child_owner_index =
                                        BuildSyntheticEntityIndex(child_owner_entity, 0x4B445245u);
                                }

                                const auto child_model_kind =
                                    ClassifyKnifeFirstPersonRenderableModel(child_owner_entity, offsets);
                                if (child_model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike)
                                {
                                    ++scene_child_weapon_like_count;
                                }
                                else if (
                                    child_model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike)
                                {
                                    ++scene_child_character_like_count;
                                }
                                if (IsSyntheticRuntimeEntityIndex(child_owner_index))
                                {
                                    ++scene_child_synthetic_count;
                                }

                                if (scene_child_samples.size() < 10)
                                {
                                    scene_child_samples.push_back(
                                        build_relation_entity_descriptor(
                                            L"scene_child_owner",
                                            child_owner_index,
                                            child_owner_entity,
                                            L"target_scene_child",
                                            kInvalidEntityHandle,
                                            pending.depth));
                                }
                            }
                        }
                    }
                }

                if (relation_probe.wrapper_entity == nullptr)
                {
                    disconnect_reasons.push_back(L"owner_chain_entity_unresolved");
                }
                if (relation_probe.cached_entity == nullptr)
                {
                    disconnect_reasons.push_back(L"missing_from_live_cache");
                }
                if (relation_probe.raw_entity == nullptr)
                {
                    disconnect_reasons.push_back(
                        relation_probe.raw_lookup_ok ? L"raw_entity_system_null" : L"raw_entity_lookup_failed");
                }
                if (relation_entity_index != player_binding.pawn_entity_index &&
                    relation_entity_index != providee_entity_index &&
                    relation_entity_index != viewmodel_entity_index &&
                    relation_entity_index != world_weapon_entity_index &&
                    (!world_trace_built ||
                     (relation_entity_index != world_trace.scene_owner_entity_index &&
                      relation_entity_index != world_trace.explicit_owner_child_entity_index &&
                      relation_entity_index != world_trace.hud_weapon_entity_index)))
                {
                    disconnect_reasons.push_back(L"no_direct_watched_anchor");
                }
                if (reverse_owner_ref_count == 0 &&
                    reverse_old_move_parent_ref_count == 0 &&
                    reverse_viewmodel_ref_count == 0 &&
                    reverse_providee_ref_count == 0 &&
                    reverse_scene_owner_ref_count == 0)
                {
                    disconnect_reasons.push_back(L"no_reverse_refs_from_live_entities");
                }

                std::wstringstream summary_stream;
                summary_stream << L"Knife candidate relation deep trace for XUID " << xuid
                    << L": candidate_entity=" << candidate.entity_index
                    << L", candidate_reason=" << candidate.reason
                    << L", candidate_bucket=" << candidate.bucket
                    << L", relation=" << (relation_label != nullptr ? relation_label : L"unknown")
                    << L", target_entity=" << relation_entity_index
                    << L", resolution_source="
                    << (relation_probe.cached_entity != nullptr
                            ? L"live_cache"
                            : (relation_probe.raw_entity != nullptr ? L"raw_entity_system" : L"none"))
                    << L", cache_ptr=" << FormatPointer(relation_probe.cached_entity)
                    << L", raw_lookup_ok=" << (relation_probe.raw_lookup_ok ? 1 : 0)
                    << L", raw_ptr=" << FormatPointer(relation_probe.raw_entity)
                    << L", wrapper_resolved=" << (relation_probe.wrapper_resolved ? 1 : 0)
                    << L", wrapper_ptr=" << FormatPointer(relation_probe.wrapper_entity)
                    << L", roundtrip_index=" << relation_probe.roundtrip_index
                    << L", hidden_from_live_cache="
                    << (relation_probe.resolved_entity != nullptr && relation_probe.roundtrip_index < 0 ? 1 : 0)
                    << L", disconnect_reasons=" << join_trace_samples(disconnect_reasons)
                    << L", candidate_chain="
                    << BuildKnifeOwnerChainDescriptor(
                           entity_cache,
                           candidate.entity_index,
                           candidate.entity,
                           offsets)
                    << L", target="
                    << build_relation_entity_descriptor(
                           L"target",
                           relation_entity_index,
                           relation_probe.resolved_entity,
                           relation_label,
                           kInvalidEntityHandle,
                           0);
                nskinzcs2::Logger::Info(summary_stream.str());

                std::wstringstream reverse_stream;
                reverse_stream << L"Knife candidate relation reverse refs for XUID " << xuid
                    << L": candidate_entity=" << candidate.entity_index
                    << L", relation=" << (relation_label != nullptr ? relation_label : L"unknown")
                    << L", target_entity=" << relation_entity_index
                    << L", owner_refs=" << reverse_owner_ref_count
                    << L", old_move_parent_refs=" << reverse_old_move_parent_ref_count
                    << L", viewmodel_refs=" << reverse_viewmodel_ref_count
                    << L", providee_refs=" << reverse_providee_ref_count
                    << L", scene_owner_refs=" << reverse_scene_owner_ref_count
                    << L", samples=" << join_trace_samples(reverse_ref_samples);
                nskinzcs2::Logger::Info(reverse_stream.str());

                std::wstringstream scene_stream;
                scene_stream << L"Knife candidate relation scene trace for XUID " << xuid
                    << L": candidate_entity=" << candidate.entity_index
                    << L", relation=" << (relation_label != nullptr ? relation_label : L"unknown")
                    << L", target_entity=" << relation_entity_index
                    << L", child_count=" << scene_child_count
                    << L", ownerless=" << scene_child_ownerless_count
                    << L", weapon_like=" << scene_child_weapon_like_count
                    << L", character_like=" << scene_child_character_like_count
                    << L", synthetic=" << scene_child_synthetic_count
                    << L", samples=" << join_trace_samples(scene_child_samples);
                nskinzcs2::Logger::Info(scene_stream.str());
            };

        auto evaluate_complete_candidate =
            [&](CompleteCarrierScanSummary& scan_summary,
                const int candidate_entity_index,
                void* candidate_entity,
                const wchar_t* scan_range,
                const bool hidden_from_live_cache)
            {
                if (candidate_entity == nullptr ||
                    !IsResolvedRuntimeEntityIndex(candidate_entity_index) ||
                    IsSyntheticRuntimeEntityIndex(candidate_entity_index) ||
                    candidate_entity_index == world_weapon_entity_index)
                {
                    return;
                }

                ++scan_summary.scanned;

                auto* candidate_item_view = ResolveWeaponItemView(candidate_entity, offsets);
                if (candidate_item_view == nullptr)
                {
                    return;
                }

                const auto model_kind =
                    ClassifyKnifeFirstPersonRenderableModel(candidate_entity, offsets);
                if (model_kind != KnifeFirstPersonRenderableModelKind::WeaponLike)
                {
                    return;
                }

                int safe_definition_index = 0;
                if (!IsSafeLinkedWeaponItemView(
                        candidate_item_view,
                        offsets,
                        xuid,
                        parent_definition_index,
                        known_definition_indices,
                        knife_definition_indices,
                        glove_definition_indices,
                        safe_definition_index))
                {
                    return;
                }

                ++scan_summary.safe_weapon_like;

                CompleteCarrierCandidate candidate {};
                candidate.entity_index = candidate_entity_index;
                candidate.entity = candidate_entity;
                candidate.item_view = candidate_item_view;
                candidate.safe_linked_item_view = true;
                candidate.definition_index =
                    safe_definition_index != 0 ? safe_definition_index : parent_definition_index;
                candidate.shared_world_item_view = candidate_item_view == world_item_view;
                candidate.hidden_from_live_cache = hidden_from_live_cache;
                candidate.scan_range = scan_range;
                candidate.owner_kind =
                    ResolvePersistentKnifeOwnerKind(
                        candidate_entity_index,
                        providee_entity_index,
                        viewmodel_entity_index,
                        preferred_owner_kind);

                if (candidate.hidden_from_live_cache)
                {
                    ++scan_summary.hidden_from_live_cache;
                }

                std::uint32_t owner_handle = kInvalidEntityHandle;
                if (offsets.base_owner_entity != 0 &&
                    SafeReadField(candidate_entity, offsets.base_owner_entity, owner_handle))
                {
                    candidate.owner_index = HandleToEntityIndex(owner_handle);
                    candidate.world_owned_proxy = candidate.owner_index == world_weapon_entity_index;
                }

                std::uint32_t old_move_parent_handle = kInvalidEntityHandle;
                if (offsets.base_old_move_parent != 0 &&
                    SafeReadField(candidate_entity, offsets.base_old_move_parent, old_move_parent_handle))
                {
                    candidate.old_move_parent_index = HandleToEntityIndex(old_move_parent_handle);
                    candidate.world_owned_proxy =
                        candidate.world_owned_proxy ||
                        candidate.old_move_parent_index == world_weapon_entity_index;
                }

                candidate.owner_matches_player = matches_player_index(candidate.owner_index);
                candidate.old_move_parent_matches_player =
                    matches_player_index(candidate.old_move_parent_index);

                std::uint32_t candidate_viewmodel_handle = kInvalidEntityHandle;
                if (offsets.econ_entity_viewmodel_attachment != 0 &&
                    SafeReadField(candidate_entity, offsets.econ_entity_viewmodel_attachment, candidate_viewmodel_handle))
                {
                    candidate.reverse_viewmodel_attachment =
                        HandleToEntityIndex(candidate_viewmodel_handle) == world_weapon_entity_index;
                }

                std::uint32_t candidate_old_providee_handle = kInvalidEntityHandle;
                if (offsets.econ_entity_old_providee != 0 &&
                    SafeReadField(candidate_entity, offsets.econ_entity_old_providee, candidate_old_providee_handle))
                {
                    candidate.reverse_old_providee_reference =
                        HandleToEntityIndex(candidate_old_providee_handle) == world_weapon_entity_index;
                }

                candidate.direct_viewmodel_attachment =
                    world_viewmodel_entity_index >= 0 &&
                    candidate_entity_index == world_viewmodel_entity_index;
                candidate.direct_old_providee_attachment =
                    world_providee_entity_index >= 0 &&
                    candidate_entity_index == world_providee_entity_index;
                candidate.explicit_owner_child_match =
                    world_trace_built &&
                    world_trace.explicit_owner_child_entity_index >= 0 &&
                    candidate_entity_index == world_trace.explicit_owner_child_entity_index;
                candidate.scene_owner_match =
                    world_trace_built &&
                    world_trace.scene_owner_entity_index >= 0 &&
                    candidate_entity_index == world_trace.scene_owner_entity_index;

                int best_shell_score = -1;
                auto consider_relation_shell =
                    [&](const int shell_entity_index, const wchar_t* shell_source)
                    {
                        if (shell_entity_index < 0 ||
                            shell_entity_index == world_weapon_entity_index ||
                            IsSyntheticRuntimeEntityIndex(shell_entity_index))
                        {
                            return;
                        }

                        void* shell_entity = nullptr;
                        if (!TryResolveKnifeOwnerChainEntity(
                                entity_list,
                                entity_cache,
                                shell_entity_index,
                                shell_entity) ||
                            shell_entity == nullptr)
                        {
                            return;
                        }

                        auto* shell_item_view = ResolveWeaponItemView(shell_entity, offsets);
                        bool shell_owner_chain_matches_player = false;
                        if (player_binding.pawn_entity_index >= 0)
                        {
                            int shell_depth = -1;
                            shell_owner_chain_matches_player =
                                KnifeOwnerChainContainsEntity(
                                    entity_list,
                                    entity_cache,
                                    shell_entity_index,
                                    shell_entity,
                                    offsets,
                                    player_binding.pawn_entity_index,
                                    shell_depth);
                        }
                        if (!shell_owner_chain_matches_player && providee_entity_index >= 0)
                        {
                            int shell_depth = -1;
                            shell_owner_chain_matches_player =
                                KnifeOwnerChainContainsEntity(
                                    entity_list,
                                    entity_cache,
                                    shell_entity_index,
                                    shell_entity,
                                    offsets,
                                    providee_entity_index,
                                    shell_depth);
                        }
                        if (!shell_owner_chain_matches_player && viewmodel_entity_index >= 0)
                        {
                            int shell_depth = -1;
                            shell_owner_chain_matches_player =
                                KnifeOwnerChainContainsEntity(
                                    entity_list,
                                    entity_cache,
                                    shell_entity_index,
                                    shell_entity,
                                    offsets,
                                    viewmodel_entity_index,
                                    shell_depth);
                        }

                        std::uint32_t shell_viewmodel_handle = kInvalidEntityHandle;
                        const bool shell_reverse_viewmodel_attachment =
                            offsets.econ_entity_viewmodel_attachment != 0 &&
                            SafeReadField(
                                shell_entity,
                                offsets.econ_entity_viewmodel_attachment,
                                shell_viewmodel_handle) &&
                            HandleToEntityIndex(shell_viewmodel_handle) == world_weapon_entity_index;
                        const bool shell_direct_viewmodel_attachment =
                            (world_viewmodel_entity_index >= 0 &&
                             shell_entity_index == world_viewmodel_entity_index) ||
                            shell_entity_index ==
                                resolution.discovery_snapshot.viewmodel_absence_audit.handle_entity_index;
                        const bool shell_relation_to_render_object =
                            resolution.clue_render_object.IsUsable() &&
                            KnifeRenderObjectIdentityMatches(
                                ResolveKnifeRenderObjectIdentity(shell_entity, shell_item_view, offsets),
                                resolution.clue_render_object);
                        const bool shell_explicit_owner_child_match =
                            world_trace_built &&
                            world_trace.explicit_owner_child_entity_index >= 0 &&
                            shell_entity_index == world_trace.explicit_owner_child_entity_index;
                        const bool shell_scene_owner_match =
                            world_trace_built &&
                            world_trace.scene_owner_entity_index >= 0 &&
                            shell_entity_index == world_trace.scene_owner_entity_index;
                        const bool shell_world_neighborhood_match =
                            shell_explicit_owner_child_match ||
                            shell_scene_owner_match ||
                            matches_player_index(shell_entity_index);

                        int shell_score = 0;
                        if (shell_direct_viewmodel_attachment)
                        {
                            shell_score += 500;
                        }
                        else if (shell_reverse_viewmodel_attachment)
                        {
                            shell_score += 420;
                        }
                        else if (shell_owner_chain_matches_player)
                        {
                            shell_score += 340;
                        }
                        else if (shell_relation_to_render_object)
                        {
                            shell_score += 260;
                        }
                        else if (shell_explicit_owner_child_match)
                        {
                            shell_score += 180;
                        }
                        else if (shell_scene_owner_match)
                        {
                            shell_score += 170;
                        }

                        if (shell_score <= 0 || shell_score <= best_shell_score)
                        {
                            return;
                        }

                        best_shell_score = shell_score;
                        candidate.shell_entity_index = shell_entity_index;
                        candidate.shell_source = shell_source != nullptr ? shell_source : L"owner_shell";
                        candidate.shell_relation_to_render_object = shell_relation_to_render_object;
                        candidate.shell_owner_chain_matches_player = shell_owner_chain_matches_player;
                        candidate.shell_direct_viewmodel_attachment = shell_direct_viewmodel_attachment;
                        candidate.shell_reverse_viewmodel_attachment = shell_reverse_viewmodel_attachment;
                        candidate.shell_world_neighborhood_match = shell_world_neighborhood_match;
                    };

                consider_relation_shell(candidate.owner_index, L"owner");
                if (candidate.old_move_parent_index != candidate.owner_index)
                {
                    consider_relation_shell(candidate.old_move_parent_index, L"old_move_parent");
                }

                auto read_complete_field_state =
                    [&]() noexcept
                    {
                        int definition_index = 0;
                        candidate.definition_readable =
                            TryReadItemDefinitionIndex(candidate_item_view, offsets, definition_index);
                        candidate.definition_readback = definition_index;
                        candidate.definition_ok =
                            candidate.definition_readable && definition_index != 0;

                        candidate.item_id_high_readable =
                            offsets.item_view_item_id_high != 0 &&
                            SafeReadField(candidate_item_view, offsets.item_view_item_id_high, candidate.item_id_high);
                        candidate.item_id_high_ok =
                            candidate.item_id_high_readable &&
                            candidate.item_id_high == 0xFFFFFFFFu;

                        candidate.account_id_readable =
                            offsets.item_view_account_id != 0 &&
                            SafeReadField(candidate_item_view, offsets.item_view_account_id, candidate.account_id);
                        candidate.account_ok =
                            candidate.account_id_readable &&
                            candidate.account_id == expected_account_id;

                        bool initialized = false;
                        candidate.initialized_readable =
                            offsets.item_view_initialized == 0 ||
                            SafeReadField(candidate_item_view, offsets.item_view_initialized, initialized);
                        candidate.initialized_ok =
                            offsets.item_view_initialized == 0 ||
                            (candidate.initialized_readable && initialized);

                        candidate.static_attrs_readable =
                            read_vector_readable(candidate_item_view, offsets.item_view_attribute_list);
                        candidate.dynamic_attrs_readable =
                            read_vector_readable(candidate_item_view, offsets.item_view_dynamic_attribute_list);

                        candidate.complete_fields_ok =
                            candidate.definition_ok &&
                            candidate.item_id_high_ok &&
                            candidate.account_ok &&
                            candidate.initialized_ok;
                    };
                read_complete_field_state();
                if (candidate.complete_fields_ok)
                {
                    ++scan_summary.complete_fields;
                }

                if (player_binding.pawn_entity_index >= 0)
                {
                    candidate.owner_chain_matches_player =
                        KnifeOwnerChainContainsEntity(
                            entity_list,
                            entity_cache,
                            candidate_entity_index,
                            candidate_entity,
                            offsets,
                            player_binding.pawn_entity_index,
                            candidate.owner_chain_depth_to_pawn);
                }
                if (providee_entity_index >= 0)
                {
                    int chain_depth = -1;
                    if (KnifeOwnerChainContainsEntity(
                            entity_list,
                            entity_cache,
                            candidate_entity_index,
                            candidate_entity,
                            offsets,
                            providee_entity_index,
                            chain_depth))
                    {
                        candidate.owner_chain_matches_player = true;
                        candidate.owner_chain_depth_to_providee = chain_depth;
                    }
                }
                if (viewmodel_entity_index >= 0)
                {
                    int chain_depth = -1;
                    if (KnifeOwnerChainContainsEntity(
                            entity_list,
                            entity_cache,
                            candidate_entity_index,
                            candidate_entity,
                            offsets,
                            viewmodel_entity_index,
                            chain_depth))
                    {
                        candidate.owner_chain_matches_player = true;
                        candidate.owner_chain_depth_to_viewmodel = chain_depth;
                    }
                }

                std::uintptr_t candidate_model_state_address = 0;
                const auto candidate_model_state_resolved =
                    TryResolveEntityModelStateAddress(
                        candidate_entity,
                        offsets,
                        candidate_model_state_address) &&
                    candidate_model_state_address != 0;
                candidate.exact_render_object_entity =
                    resolution.clue_render_object.entity_resolved &&
                    resolution.clue_render_object.entity != nullptr &&
                    candidate_entity == resolution.clue_render_object.entity;
                candidate.exact_render_object_alias =
                    resolution.clue_render_object.item_view_resolved &&
                    resolution.clue_render_object.item_view != nullptr &&
                    resolution.clue_render_object.model_state_resolved &&
                    candidate_item_view == resolution.clue_render_object.item_view &&
                    candidate_model_state_resolved &&
                    candidate_model_state_address == resolution.clue_render_object.model_state;
                candidate.relation_to_render_object =
                    candidate.exact_render_object_entity ||
                    candidate.exact_render_object_alias;
                candidate.world_neighborhood_match =
                    candidate.direct_old_providee_attachment ||
                    candidate.reverse_old_providee_reference ||
                    candidate.explicit_owner_child_match ||
                    candidate.scene_owner_match ||
                    candidate.owner_matches_player ||
                    candidate.old_move_parent_matches_player;
                const auto promotion =
                    ResolveKnifeCarrierPromotionDecision(
                        candidate.safe_linked_item_view,
                        candidate.world_owned_proxy,
                        candidate.direct_viewmodel_attachment,
                        candidate.reverse_viewmodel_attachment,
                        candidate.owner_chain_matches_player,
                        candidate.exact_render_object_entity,
                        candidate.exact_render_object_alias,
                        candidate.shell_direct_viewmodel_attachment,
                        candidate.shell_reverse_viewmodel_attachment,
                        candidate.shell_owner_chain_matches_player,
                        candidate.shell_relation_to_render_object,
                        candidate.world_neighborhood_match,
                        candidate.shell_world_neighborhood_match);
                candidate.promotable_relation = promotion.promotable_relation;
                candidate.discovery_relevant = promotion.discovery_relevant;

                candidate.score = 0;
                if (candidate.complete_fields_ok)
                {
                    candidate.score += 100;
                }
                if (candidate.static_attrs_readable)
                {
                    candidate.score += 8;
                }
                if (candidate.dynamic_attrs_readable)
                {
                    candidate.score += 8;
                }
                if (candidate.direct_viewmodel_attachment)
                {
                    candidate.score += 500;
                    candidate.bucket = L"viewmodel_attachment";
                    candidate.reason = L"viewmodel_attachment_exact";
                }
                else if (candidate.reverse_viewmodel_attachment)
                {
                    candidate.score += 420;
                    candidate.bucket = L"reverse_viewmodel_attachment";
                    candidate.reason = L"reverse_viewmodel_attachment";
                }
                else if (candidate.owner_chain_matches_player)
                {
                    candidate.score += 340;
                    candidate.bucket = L"owner_chain";
                    candidate.reason = L"owner_chain_matches_player";
                }
                else if (candidate.exact_render_object_entity)
                {
                    candidate.score += 280;
                    candidate.bucket = L"render_object_alias";
                    candidate.reason = L"shared_render_object_entity";
                }
                else if (candidate.exact_render_object_alias)
                {
                    candidate.score += 260;
                    candidate.bucket = L"render_object_alias";
                    candidate.reason = L"shared_item_view_and_model_state";
                }
                else if (candidate.shell_direct_viewmodel_attachment)
                {
                    candidate.score += 250;
                    candidate.bucket = L"shell_viewmodel_attachment";
                    candidate.reason = L"shell_viewmodel_attachment";
                }
                else if (candidate.shell_reverse_viewmodel_attachment)
                {
                    candidate.score += 220;
                    candidate.bucket = L"shell_reverse_viewmodel_attachment";
                    candidate.reason = L"shell_reverse_viewmodel_attachment";
                }
                else if (candidate.shell_owner_chain_matches_player)
                {
                    candidate.score += 200;
                    candidate.bucket = L"shell_owner_chain";
                    candidate.reason = L"shell_owner_chain_matches_player";
                }
                else if (candidate.shell_relation_to_render_object)
                {
                    candidate.score += 190;
                    candidate.bucket = L"shell_render_object_alias";
                    candidate.reason = L"shell_matches_render_object";
                }
                else if (candidate.explicit_owner_child_match)
                {
                    candidate.score += 180;
                    candidate.bucket = L"explicit_owner_child";
                    candidate.reason = L"explicit_owner_child_match";
                }
                else if (candidate.scene_owner_match)
                {
                    candidate.score += 170;
                    candidate.bucket = L"scene_owner";
                    candidate.reason = L"scene_owner_match";
                }
                else if (candidate.direct_old_providee_attachment)
                {
                    candidate.score += 160;
                    candidate.bucket = L"old_providee";
                    candidate.reason = L"old_providee_attachment_exact";
                }
                else if (candidate.reverse_old_providee_reference)
                {
                    candidate.score += 150;
                    candidate.bucket = L"reverse_old_providee";
                    candidate.reason = L"reverse_old_providee_reference";
                }
                else if (candidate.owner_matches_player)
                {
                    candidate.score += 140;
                    candidate.bucket = L"owner_handle";
                    candidate.reason = L"owner_matches_player";
                }
                else if (candidate.old_move_parent_matches_player)
                {
                    candidate.score += 130;
                    candidate.bucket = L"old_move_parent";
                    candidate.reason = L"old_move_parent_matches_player";
                }
                if (candidate.shared_world_item_view)
                {
                    candidate.score += 20;
                }
                if (candidate.relation_to_render_object)
                {
                    candidate.score += 15;
                }
                if (candidate.world_owned_proxy)
                {
                    candidate.score -= 200;
                }
                if (std::wcscmp(candidate.reason, L"none") == 0)
                {
                    if (candidate.discovery_relevant)
                    {
                        candidate.reason = L"relevant_safe_weapon_like_incomplete";
                    }
                    else if (candidate.complete_fields_ok)
                    {
                        candidate.reason = L"complete_fields_only";
                    }
                    else if (
                        candidate.definition_ok ||
                        candidate.item_id_high_ok ||
                        candidate.account_ok ||
                        candidate.initialized_ok)
                    {
                        candidate.reason = L"partial_complete_fields";
                    }
                    else
                    {
                        candidate.reason = L"safe_weapon_like_unrelated";
                    }
                }
                if (candidate.discovery_relevant && !candidate.complete_fields_ok)
                {
                    ++scan_summary.relevant_incomplete;
                    scan_summary.related_incomplete_found = true;
                }
                if (promotion.accept_writable_carrier)
                {
                    ++scan_summary.writable_related;
                }
                if (candidate.promotable_relation && candidate.complete_fields_ok && !candidate.world_owned_proxy)
                {
                    ++scan_summary.related_complete;
                }

                append_top_candidate(scan_summary.top, candidate);

                if (!promotion.accept_writable_carrier)
                {
                    return;
                }

                if (scan_summary.best.entity == nullptr ||
                    candidate.score > scan_summary.best.score ||
                    (candidate.score == scan_summary.best.score &&
                     candidate.entity_index < scan_summary.best.entity_index))
                {
                    scan_summary.best = candidate;
                }
            };

        auto log_complete_scan_summary =
            [&](const wchar_t* label, const CompleteCarrierScanSummary& scan_summary)
            {
                if (!ShouldLogWatchedKnifeAnimationTrace(xuid))
                {
                    if (should_force_providee_owner_search_diagnostics)
                    {
                        auto build_forced_candidate_brief =
                            [&](const CompleteCarrierCandidate& candidate)
                            {
                                std::wstringstream brief;
                                brief << L"entity=" << candidate.entity_index
                                    << L", definition=" << candidate.definition_index
                                    << L", definition_readback=";
                                if (candidate.definition_readable)
                                {
                                    brief << candidate.definition_readback;
                                }
                                else
                                {
                                    brief << L"?";
                                }
                                brief << L", owner=" << candidate.owner_index
                                    << L", old_move_parent=" << candidate.old_move_parent_index
                                    << L", reason=" << candidate.reason
                                    << L", owner_kind="
                                    << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(candidate.owner_kind)
                                    << L", complete_fields=" << (candidate.complete_fields_ok ? 1 : 0)
                                    << L", safe_linked=" << (candidate.safe_linked_item_view ? 1 : 0)
                                    << L", owner_matches_player=" << (candidate.owner_matches_player ? 1 : 0)
                                    << L", old_move_parent_matches_player="
                                    << (candidate.old_move_parent_matches_player ? 1 : 0)
                                    << L", owner_chain_depths=pawn:" << candidate.owner_chain_depth_to_pawn
                                    << L"/providee:" << candidate.owner_chain_depth_to_providee
                                    << L"/viewmodel:" << candidate.owner_chain_depth_to_viewmodel
                                    << L", relation_to_render_object="
                                    << (candidate.relation_to_render_object ? 1 : 0)
                                    << L", direct_viewmodel_attachment="
                                    << (candidate.direct_viewmodel_attachment ? 1 : 0)
                                    << L", reverse_viewmodel_attachment="
                                    << (candidate.reverse_viewmodel_attachment ? 1 : 0)
                                    << L", direct_old_providee_attachment="
                                    << (candidate.direct_old_providee_attachment ? 1 : 0)
                                    << L", reverse_old_providee_reference="
                                    << (candidate.reverse_old_providee_reference ? 1 : 0)
                                    << L", scene_owner_match=" << (candidate.scene_owner_match ? 1 : 0)
                                    << L", explicit_owner_child_match="
                                    << (candidate.explicit_owner_child_match ? 1 : 0)
                                    << L", world_neighborhood_match="
                                    << (candidate.world_neighborhood_match ? 1 : 0);
                                return brief.str();
                            };

                        std::wstringstream brief;
                        brief << L"label=" << (label != nullptr ? label : L"scan")
                            << L", scanned=" << scan_summary.scanned
                            << L", safe_weapon_like=" << scan_summary.safe_weapon_like
                            << L", complete_fields=" << scan_summary.complete_fields
                            << L", related_complete=" << scan_summary.related_complete
                            << L", relevant_incomplete=" << scan_summary.relevant_incomplete
                            << L", writable_related=" << scan_summary.writable_related;
                        if (scan_summary.best.entity != nullptr)
                        {
                            brief << L", selected_entity=" << scan_summary.best.entity_index
                                << L", selected_definition=" << scan_summary.best.definition_index
                                << L", selected_reason=" << scan_summary.best.reason;
                        }
                        else
                        {
                            brief << L", selected=<none>";
                        }
                        const auto* stage_name =
                            label != nullptr && std::wcsstr(label, L"raw carrier scan") != nullptr
                                ? L"raw_scan"
                                : L"live_scan";
                        log_providee_owner_search_stage_once(stage_name, brief.str());
                        const auto top_limit = std::min<std::size_t>(scan_summary.top.size(), 2);
                        for (std::size_t sample_index = 0; sample_index < top_limit; ++sample_index)
                        {
                            std::wstringstream candidate_stage;
                            candidate_stage << stage_name << L"_candidate" << sample_index;
                            log_providee_owner_search_stage_once(
                                candidate_stage.str().c_str(),
                                build_forced_candidate_brief(scan_summary.top[sample_index]));
                        }
                    }
                    return;
                }

                std::wstringstream stream;
                stream << label << xuid
                    << L": clue_source=" << resolution.clue_source
                    << L", clue_entity=" << resolution.clue_entity_index
                    << L", scanned=" << scan_summary.scanned
                    << L", safe_weapon_like=" << scan_summary.safe_weapon_like
                    << L", complete_fields=" << scan_summary.complete_fields
                    << L", related_complete=" << scan_summary.related_complete
                    << L", relevant_incomplete=" << scan_summary.relevant_incomplete
                    << L", writable_related=" << scan_summary.writable_related;
                if (scan_summary.hidden_from_live_cache != 0)
                {
                    stream << L", hidden_from_live_cache=" << scan_summary.hidden_from_live_cache;
                }
                if (scan_summary.resolution_failures != 0)
                {
                    stream << L", resolution_failures=" << scan_summary.resolution_failures;
                }
                if (scan_summary.best.entity != nullptr)
                {
                    stream << L", selected="
                        << build_complete_candidate_descriptor(scan_summary.best);
                }
                else
                {
                    stream << L", selected=<none>";
                }
                if (!scan_summary.top.empty())
                {
                    stream << L", top=";
                    for (std::size_t sample_index = 0; sample_index < scan_summary.top.size(); ++sample_index)
                    {
                        if (sample_index != 0)
                        {
                            stream << L" | ";
                        }
                        stream << build_complete_candidate_descriptor(scan_summary.top[sample_index]);
                    }
                }
                nskinzcs2::Logger::Info(stream.str());

            };

        CompleteCarrierScanSummary live_complete_scan {};
        live_complete_scan.top.reserve(5);
        CompleteCarrierScanSummary raw_complete_scan {};
        raw_complete_scan.top.reserve(5);
        if (should_force_providee_owner_search_diagnostics)
        {
            log_providee_owner_search_stage_once(L"live_scan", L"disabled_for_targeted_probe");
            log_providee_owner_search_stage_once(L"raw_scan", L"disabled_for_targeted_probe");
        }
        else
        {
            for (std::size_t index = 0; index < entity_cache.size(); ++index)
            {
                auto* candidate_entity = entity_cache[index];
                if (candidate_entity == nullptr)
                {
                    continue;
                }

                evaluate_complete_candidate(
                    live_complete_scan,
                    static_cast<int>(index),
                    candidate_entity,
                    L"live_cache",
                    false);
            }

            log_complete_scan_summary(
                L"Knife first-person complete carrier scan for XUID ",
                live_complete_scan);

            if (live_complete_scan.best.entity != nullptr)
            {
                return accept_candidate(
                    live_complete_scan.best.entity_index,
                    live_complete_scan.best.entity,
                    live_complete_scan.best.item_view,
                    live_complete_scan.best.definition_index,
                    live_complete_scan.best.owner_kind,
                    L"complete_carrier_scan_validated");
            }

            std::unordered_set<void*> raw_seen_entities;
            for (int entity_index = 0; entity_index <= kMaxEntityIndex; ++entity_index)
            {
                void* candidate_entity = nullptr;
                if (!TryGetEntityFromIndex(entity_list, entity_index, candidate_entity))
                {
                    ++raw_complete_scan.resolution_failures;
                    continue;
                }

                if (candidate_entity == nullptr)
                {
                    continue;
                }

                if (!raw_seen_entities.insert(candidate_entity).second)
                {
                    continue;
                }

                const auto hidden_from_live_cache =
                    static_cast<std::size_t>(entity_index) >= entity_cache.size() ||
                    entity_cache[static_cast<std::size_t>(entity_index)] != candidate_entity;
                evaluate_complete_candidate(
                    raw_complete_scan,
                    entity_index,
                    candidate_entity,
                    L"raw_entity_system",
                    hidden_from_live_cache);
            }

            log_complete_scan_summary(
                L"Knife first-person raw carrier scan for XUID ",
                raw_complete_scan);

            if (raw_complete_scan.best.entity != nullptr)
            {
                return accept_candidate(
                    raw_complete_scan.best.entity_index,
                    raw_complete_scan.best.entity,
                    raw_complete_scan.best.item_view,
                    raw_complete_scan.best.definition_index,
                    raw_complete_scan.best.owner_kind,
                    L"raw_entity_system_complete_carrier_scan_validated");
            }

            if (raw_complete_scan.resolution_failures != 0)
            {
                ClearPendingKnifeFirstPersonReacquire();
                resolution.validation_result = L"raw_entity_system_scan_incomplete";
                resolution.result = KnifePersistentOwnerResolutionResult::Unresolved;
                log_resolution(false);
                return false;
            }
        }

        ClientClassDiscoverySummary class_discovery {};
        TryDiscoverKnifeViewmodelClientClasses(class_discovery);
        LogKnifeViewmodelClientClassDiscovery(xuid, class_discovery);
        resolution.discovery_snapshot.client_class_discovery = class_discovery;
        resolution.factory_feasibility =
            ResolveKnifeCarrierFactoryFeasibility(class_discovery);
        g_hook_state.viewmodel_factory_discovery_ran.store(true);
        g_hook_state.viewmodel_factory_observed.store(
            resolution.factory_feasibility ==
            nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::ViewmodelFactoryPresentWithoutInstance);

        const auto related_incomplete_candidate_found =
            live_complete_scan.related_incomplete_found ||
            raw_complete_scan.related_incomplete_found ||
            resolution.discovery_snapshot.viewmodel_absence_audit.result ==
                nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::ShellWithoutWritableCarrier ||
            resolution.discovery_snapshot.viewmodel_absence_audit.result ==
                nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult::NonQualifyingCandidate;
        resolution.carrier_result =
            ResolveKnifeCarrierDiscoveryResult(
                false,
                related_incomplete_candidate_found);

        if (current_refresh_epoch_generation != 0 &&
            resolution.clue_render_object.IsUsable())
        {
            auto& cache = g_hook_state.knife_persistent_owner_negative_cache;
            cache = {};
            cache.active = true;
            cache.xuid = xuid;
            cache.refresh_epoch_generation = current_refresh_epoch_generation;
            cache.world_entity_index = world_weapon_entity_index;
            cache.clue_definition_index = resolution.clue_definition_index;
            cache.render_object = resolution.clue_render_object;
            cache.carrier_result = resolution.carrier_result;
            cache.factory_feasibility = resolution.factory_feasibility;
            cache.viewmodel_absence_result =
                resolution.discovery_snapshot.viewmodel_absence_audit.result;
        }

        ClearPendingKnifeFirstPersonReacquire();
        resolution.validation_result = KnifeCarrierDiscoveryResultText(resolution.carrier_result);
        resolution.result = KnifePersistentOwnerResolutionResult::NoExposedNonSyntheticRenderOwner;
        log_resolution(false);
        return false;
    }

    ClearPendingKnifeFirstPersonReacquire();
    resolution.validation_result = L"unresolved";
    resolution.result = KnifePersistentOwnerResolutionResult::Unresolved;
    log_resolution(false);
    return false;
}

const wchar_t* WearableGloveCandidateStageText(const WearableGloveCandidateStage stage) noexcept
{
    switch (stage)
    {
    case WearableGloveCandidateStage::PawnWearableHandles:
        return L"pawn_wearable_handles";
    case WearableGloveCandidateStage::OwnedLiveEntities:
        return L"owned_live_entities";
    case WearableGloveCandidateStage::LooseGloveRenderables:
        return L"loose_glove_renderables";
    }

    return L"unknown";
}

std::uint64_t BuildWearableGloveStageDiagnosticSignature(
    const std::uint64_t xuid,
    const int pawn_entity_index,
    const WearableGloveCandidateStage stage) noexcept
{
    return xuid ^
        (static_cast<std::uint64_t>(static_cast<std::uint32_t>(pawn_entity_index)) << 32) ^
        (0x474C56450000ull + (static_cast<std::uint64_t>(stage) << 8));
}

std::wstring BuildWearableGloveCandidateDescriptor(const WearableGloveCandidate& candidate)
{
    std::wstringstream stream;
    stream << L"entity=" << candidate.entity_index;
    if (candidate.handle != kInvalidEntityHandle)
    {
        stream << L", handle=0x" << std::hex << std::uppercase << candidate.handle
            << std::dec << std::nouppercase;
    }
    stream << L", definition=" << candidate.definition_index
        << L", owner_pawn=" << (candidate.owner_matches_pawn ? 1 : 0)
        << L", owner_xuid=" << (candidate.owner_matches_xuid ? 1 : 0)
        << L", account=" << (candidate.account_matches_xuid ? 1 : 0)
        << L", renderable=" << (candidate.glove_renderable ? 1 : 0);
    if (candidate.evaluation.accepted)
    {
        stream << L", score=" << candidate.evaluation.score
            << L", selected_as=" << candidate.evaluation.selection_reason;
    }
    else
    {
        stream << L", rejected_as=" << candidate.evaluation.rejection_reason;
    }
    return stream.str();
}

bool TrySelectBestWearableGloveCandidate(
    const std::vector<WearableGloveCandidate>& candidates,
    WearableGloveCandidate& best_candidate)
{
    best_candidate = {};
    bool found = false;
    for (const auto& candidate : candidates)
    {
        if (!candidate.evaluation.accepted)
        {
            continue;
        }

        if (!found || IsPreferredWearableGloveCandidate(candidate, best_candidate))
        {
            best_candidate = candidate;
            found = true;
        }
    }

    return found;
}

void LogWearableGloveCandidateStageDiagnosticsOnce(
    const std::uint64_t xuid,
    const int pawn_entity_index,
    const WearableGloveCandidateStage stage,
    const std::vector<WearableGloveCandidate>& candidates)
{
    std::wstringstream stream;
    stream << L"Glove carrier stage " << WearableGloveCandidateStageText(stage)
        << L" for XUID " << xuid
        << L": candidates=" << candidates.size();

    int accepted_count = 0;
    std::vector<std::wstring> rejection_samples;
    rejection_samples.reserve(3);
    for (const auto& candidate : candidates)
    {
        if (candidate.evaluation.accepted)
        {
            ++accepted_count;
        }
        else if (rejection_samples.size() < 3)
        {
            rejection_samples.push_back(BuildWearableGloveCandidateDescriptor(candidate));
        }
    }
    stream << L", accepted=" << accepted_count;

    WearableGloveCandidate best_candidate {};
    if (TrySelectBestWearableGloveCandidate(candidates, best_candidate))
    {
        stream << L", best={" << BuildWearableGloveCandidateDescriptor(best_candidate) << L"}";
    }
    else
    {
        stream << L", best=<none>";
    }

    if (!rejection_samples.empty())
    {
        stream << L", rejected_samples=" << JoinDiagnosticSamples(rejection_samples);
    }

    LogProfileDiagnosticOnce(
        BuildWearableGloveStageDiagnosticSignature(xuid, pawn_entity_index, stage),
        stream.str());
}

void CollectWearableGloveCandidatesFromPawnHandles(
    void* entity_list,
    const int highest_live_entity_index,
    const int pawn_entity_index,
    void* pawn_entity,
    const ClientSchemaOffsets& offsets,
    const std::unordered_set<int>& glove_definition_indices,
    const std::uint64_t xuid,
    std::vector<WearableGloveCandidate>& candidates)
{
    candidates.clear();
    if (entity_list == nullptr || pawn_entity == nullptr)
    {
        return;
    }

    const auto handles = CollectPawnWearableHandles(pawn_entity, offsets);
    for (const auto handle : handles)
    {
        WearableGloveCandidate candidate {};
        candidate.stage = WearableGloveCandidateStage::PawnWearableHandles;
        candidate.handle = handle;

        const auto entity_index = HandleToEntityIndex(handle);
        candidate.entity_index = entity_index;
        if (entity_index < 0 || entity_index == pawn_entity_index)
        {
            candidate.evaluation.rejection_reason = L"invalid_handle_target";
            candidates.push_back(std::move(candidate));
            continue;
        }

        if (!TryGetEntityFromIndex(entity_list, entity_index, candidate.entity) || candidate.entity == nullptr)
        {
            candidate.evaluation.rejection_reason = L"entity_unresolved";
            candidates.push_back(std::move(candidate));
            continue;
        }

        candidate.item_view = ResolveWeaponItemView(candidate.entity, offsets);
        candidate.has_item_view = candidate.item_view != nullptr;
        if (candidate.item_view != nullptr)
        {
            std::uint32_t owner_handle = kInvalidEntityHandle;
            candidate.owner_matches_pawn =
                offsets.base_owner_entity != 0 &&
                SafeReadField(candidate.entity, offsets.base_owner_entity, owner_handle) &&
                HandleToEntityIndex(owner_handle) == pawn_entity_index;

            std::uint32_t account_id = 0;
            candidate.account_matches_xuid =
                offsets.item_view_account_id != 0 &&
                SafeReadField(candidate.item_view, offsets.item_view_account_id, account_id) &&
                account_id == AccountIdFromXuid(xuid);

            if (TryReadItemDefinitionIndex(candidate.item_view, offsets, candidate.definition_index))
            {
                candidate.exact_glove_definition =
                    glove_definition_indices.find(candidate.definition_index) != glove_definition_indices.end();
                candidate.has_non_glove_definition =
                    candidate.definition_index > 0 && !candidate.exact_glove_definition;
            }

            candidate.glove_renderable = EntityLooksLikeGloveRenderable(
                entity_list,
                highest_live_entity_index,
                entity_index,
                candidate.entity,
                offsets);
        }

        candidate.evaluation = EvaluateWearableGloveCandidate(candidate);
        candidates.push_back(std::move(candidate));
    }
}

void CollectWearableGloveCandidatesFromLiveEntities(
    void* entity_list,
    const int highest_live_entity_index,
    const int pawn_entity_index,
    const ClientSchemaOffsets& offsets,
    const std::unordered_set<int>& glove_definition_indices,
    const std::uint64_t xuid,
    std::vector<WearableGloveCandidate>& owned_candidates,
    std::vector<WearableGloveCandidate>& loose_candidates)
{
    owned_candidates.clear();
    loose_candidates.clear();
    if (entity_list == nullptr || highest_live_entity_index < 0)
    {
        return;
    }

    for (int entity_index = 0; entity_index <= highest_live_entity_index; ++entity_index)
    {
        if (entity_index == pawn_entity_index)
        {
            continue;
        }

        void* entity = nullptr;
        if (!TryGetEntityFromIndex(entity_list, entity_index, entity) || entity == nullptr)
        {
            continue;
        }

        std::uint32_t owner_handle = kInvalidEntityHandle;
        const auto owner_matches_pawn =
            offsets.base_owner_entity != 0 &&
            SafeReadField(entity, offsets.base_owner_entity, owner_handle) &&
            HandleToEntityIndex(owner_handle) == pawn_entity_index;

        std::uint32_t owner_xuid_low = 0;
        std::uint32_t owner_xuid_high = 0;
        const auto has_owner_xuid_low =
            offsets.econ_entity_original_owner_xuid_low != 0 &&
            SafeReadField(entity, offsets.econ_entity_original_owner_xuid_low, owner_xuid_low);
        const auto has_owner_xuid_high =
            offsets.econ_entity_original_owner_xuid_high != 0 &&
            SafeReadField(entity, offsets.econ_entity_original_owner_xuid_high, owner_xuid_high);
        const auto owner_xuid_matches =
            (has_owner_xuid_low || has_owner_xuid_high) &&
            (owner_xuid_low != 0 || owner_xuid_high != 0) &&
            CombineXuidParts(owner_xuid_low, owner_xuid_high) == xuid;

        void* item_view = ResolveWeaponItemView(entity, offsets);
        std::uint32_t account_id = 0;
        const auto account_matches_xuid =
            item_view != nullptr &&
            offsets.item_view_account_id != 0 &&
            SafeReadField(item_view, offsets.item_view_account_id, account_id) &&
            account_id != 0 &&
            account_id == AccountIdFromXuid(xuid);

        if (!owner_matches_pawn && !owner_xuid_matches && !account_matches_xuid)
        {
            continue;
        }

        WearableGloveCandidate candidate {};
        candidate.entity_index = entity_index;
        candidate.entity = entity;
        candidate.item_view = item_view;
        candidate.has_item_view = item_view != nullptr;
        candidate.owner_matches_pawn = owner_matches_pawn;
        candidate.owner_matches_xuid = owner_xuid_matches;
        candidate.account_matches_xuid = account_matches_xuid;

        if (item_view != nullptr &&
            TryReadItemDefinitionIndex(item_view, offsets, candidate.definition_index))
        {
            candidate.exact_glove_definition =
                glove_definition_indices.find(candidate.definition_index) != glove_definition_indices.end();
            candidate.has_non_glove_definition =
                candidate.definition_index > 0 && !candidate.exact_glove_definition;
        }

        if (candidate.exact_glove_definition)
        {
            candidate.stage = WearableGloveCandidateStage::OwnedLiveEntities;
            candidate.evaluation = EvaluateWearableGloveCandidate(candidate);
            owned_candidates.push_back(std::move(candidate));
            continue;
        }

        candidate.stage = WearableGloveCandidateStage::LooseGloveRenderables;
        candidate.glove_renderable = EntityLooksLikeGloveRenderable(
            entity_list,
            highest_live_entity_index,
            entity_index,
            entity,
            offsets);
        candidate.evaluation = EvaluateWearableGloveCandidate(candidate);
        loose_candidates.push_back(std::move(candidate));
    }
}

bool TryResolveWearableGloveCarrier(
    void* entity_list,
    const int highest_live_entity_index,
    const int pawn_entity_index,
    void* pawn_entity,
    const ClientSchemaOffsets& offsets,
    const std::unordered_set<int>& glove_definition_indices,
    const std::uint64_t xuid,
    nskinzcs2::runtime::ResolvedGloveCarrier& carrier,
    void*& glove_entity,
    void*& glove_item_view)
{
    carrier = {};
    carrier.xuid = xuid;
    carrier.pawn_entity_index = pawn_entity_index;
    glove_entity = nullptr;
    glove_item_view = nullptr;

    if (entity_list == nullptr || pawn_entity == nullptr)
    {
        return false;
    }

    std::vector<WearableGloveCandidate> handle_candidates;
    std::vector<WearableGloveCandidate> owned_candidates;
    std::vector<WearableGloveCandidate> loose_candidates;
    CollectWearableGloveCandidatesFromPawnHandles(
        entity_list,
        highest_live_entity_index,
        pawn_entity_index,
        pawn_entity,
        offsets,
        glove_definition_indices,
        xuid,
        handle_candidates);
    CollectWearableGloveCandidatesFromLiveEntities(
        entity_list,
        highest_live_entity_index,
        pawn_entity_index,
        offsets,
        glove_definition_indices,
        xuid,
        owned_candidates,
        loose_candidates);

    LogWearableGloveCandidateStageDiagnosticsOnce(
        xuid,
        pawn_entity_index,
        WearableGloveCandidateStage::PawnWearableHandles,
        handle_candidates);
    LogWearableGloveCandidateStageDiagnosticsOnce(
        xuid,
        pawn_entity_index,
        WearableGloveCandidateStage::OwnedLiveEntities,
        owned_candidates);
    LogWearableGloveCandidateStageDiagnosticsOnce(
        xuid,
        pawn_entity_index,
        WearableGloveCandidateStage::LooseGloveRenderables,
        loose_candidates);

    WearableGloveCandidate best_candidate {};
    bool found_candidate = false;
    const auto consider_best =
        [&](const std::vector<WearableGloveCandidate>& candidates)
        {
            WearableGloveCandidate stage_best {};
            if (!TrySelectBestWearableGloveCandidate(candidates, stage_best))
            {
                return;
            }

            if (!found_candidate || IsPreferredWearableGloveCandidate(stage_best, best_candidate))
            {
                best_candidate = stage_best;
                found_candidate = true;
            }
        };

    consider_best(handle_candidates);
    consider_best(owned_candidates);
    consider_best(loose_candidates);
    if (!found_candidate)
    {
        return false;
    }

    carrier.glove_entity_index = best_candidate.entity_index;
    carrier.glove_handle = best_candidate.handle;
    carrier.current_definition_index = best_candidate.definition_index > 0 ? best_candidate.definition_index : 5028;
    carrier.valid = best_candidate.entity != nullptr && best_candidate.item_view != nullptr;
    glove_entity = best_candidate.entity;
    glove_item_view = best_candidate.item_view;
    return carrier.valid;
}

bool DoesLooseGloveEntityMatchXuid(
    void* glove_entity,
    void* glove_item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid)
{
    if (xuid == 0)
    {
        return false;
    }

    std::uint32_t owner_xuid_low = 0;
    std::uint32_t owner_xuid_high = 0;
    const auto has_owner_xuid_low =
        offsets.econ_entity_original_owner_xuid_low != 0 &&
        glove_entity != nullptr &&
        SafeReadField(glove_entity, offsets.econ_entity_original_owner_xuid_low, owner_xuid_low);
    const auto has_owner_xuid_high =
        offsets.econ_entity_original_owner_xuid_high != 0 &&
        glove_entity != nullptr &&
        SafeReadField(glove_entity, offsets.econ_entity_original_owner_xuid_high, owner_xuid_high);
    if ((has_owner_xuid_low || has_owner_xuid_high) &&
        (owner_xuid_low != 0 || owner_xuid_high != 0) &&
        CombineXuidParts(owner_xuid_low, owner_xuid_high) == xuid)
    {
        return true;
    }

    if (offsets.item_view_account_id == 0 || glove_item_view == nullptr)
    {
        return false;
    }

    std::uint32_t account_id = 0;
    return SafeReadField(glove_item_view, offsets.item_view_account_id, account_id) &&
        account_id != 0 &&
        account_id == AccountIdFromXuid(xuid);
}

bool TryResolveLooseGloveRenderEntityForXuid(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    int& render_entity_index,
    void*& render_entity)
{
    render_entity_index = -1;
    render_entity = nullptr;

    if (entity_list == nullptr || xuid == 0)
    {
        return false;
    }

    for (std::size_t index = 0; index < entity_cache.size(); ++index)
    {
        auto* candidate = entity_cache[index];
        if (candidate == nullptr)
        {
            continue;
        }

        if (!EntityLooksLikeGloveRenderable(
                entity_list,
                static_cast<int>(entity_cache.size()) - 1,
                static_cast<int>(index),
                candidate,
                offsets))
        {
            continue;
        }

        void* candidate_item_view = ResolveWeaponItemView(candidate, offsets);
        if (!DoesLooseGloveEntityMatchXuid(candidate, candidate_item_view, offsets, xuid))
        {
            continue;
        }

        render_entity_index = static_cast<int>(index);
        render_entity = candidate;
        return true;
    }

    return false;
}

bool TryResolveWearableOwnedGloveRenderEntity(
    const std::vector<void*>& entity_cache,
    const nskinzcs2::runtime::ResolvedGloveCarrier& carrier,
    const ClientSchemaOffsets& offsets,
    int& render_entity_index,
    void*& render_entity)
{
    render_entity_index = -1;
    render_entity = nullptr;

    if (!carrier.valid || carrier.glove_entity_index < 0 || offsets.base_owner_entity == 0)
    {
        return false;
    }

    int explicit_child_count = 0;
    for (std::size_t index = 0; index < entity_cache.size(); ++index)
    {
        auto* candidate = entity_cache[index];
        if (candidate == nullptr || static_cast<int>(index) == carrier.glove_entity_index)
        {
            continue;
        }

        std::uint32_t owner_handle = kInvalidEntityHandle;
        if (!SafeReadField(candidate, offsets.base_owner_entity, owner_handle) ||
            HandleToEntityIndex(owner_handle) != carrier.glove_entity_index)
        {
            continue;
        }

        ++explicit_child_count;
        if (render_entity == nullptr)
        {
            render_entity = candidate;
            render_entity_index = static_cast<int>(index);
        }
    }

    if (explicit_child_count == 1 && render_entity != nullptr)
    {
        return true;
    }

    if (explicit_child_count == 0 &&
        carrier.glove_entity_index >= 0 &&
        static_cast<std::size_t>(carrier.glove_entity_index) < entity_cache.size())
    {
        render_entity_index = carrier.glove_entity_index;
        render_entity = entity_cache[static_cast<std::size_t>(carrier.glove_entity_index)];
        return render_entity != nullptr;
    }

    render_entity_index = -1;
    render_entity = nullptr;
    return false;
}

bool TryResolveHudGloveRenderEntity(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int preferred_owner_entity_index,
    const int fallback_owner_entity_index,
    const ClientSchemaOffsets& offsets,
    int& hud_glove_entity_index,
    void*& hud_glove_entity)
{
    hud_glove_entity_index = -1;
    hud_glove_entity = nullptr;
    int pawn_owned_hud_glove_entity_index = -1;
    void* pawn_owned_hud_glove_entity = nullptr;

    if (entity_list == nullptr ||
        player_binding.pawn_entity == nullptr ||
        offsets.pawn_hud_model_arms == 0 ||
        offsets.base_entity_game_scene_node == 0 ||
        offsets.game_scene_node_child == 0 ||
        offsets.game_scene_node_next_sibling == 0 ||
        offsets.game_scene_node_owner == 0 ||
        offsets.base_owner_entity == 0)
    {
        return false;
    }

    std::uint32_t hud_model_arms_handle = kInvalidEntityHandle;
    if (!SafeReadField(player_binding.pawn_entity, offsets.pawn_hud_model_arms, hud_model_arms_handle))
    {
        return false;
    }

    const auto hud_model_arms_entity_index = HandleToEntityIndex(hud_model_arms_handle);
    if (hud_model_arms_entity_index < 0)
    {
        return false;
    }

    void* hud_model_arms_entity = nullptr;
    if (!TryGetEntityFromIndex(entity_list, hud_model_arms_entity_index, hud_model_arms_entity) || hud_model_arms_entity == nullptr)
    {
        return false;
    }

    void* arms_scene_node = nullptr;
    if (!SafeReadField(hud_model_arms_entity, offsets.base_entity_game_scene_node, arms_scene_node) || arms_scene_node == nullptr)
    {
        return false;
    }

    void* child_scene_node = nullptr;
    if (!SafeReadField(arms_scene_node, offsets.game_scene_node_child, child_scene_node))
    {
        return false;
    }

    std::unordered_set<void*> visited_scene_nodes;
    while (child_scene_node != nullptr && visited_scene_nodes.insert(child_scene_node).second)
    {
        void* owner_entity = nullptr;
        if (SafeReadField(child_scene_node, offsets.game_scene_node_owner, owner_entity) && owner_entity != nullptr)
        {
            std::uint32_t owner_handle = kInvalidEntityHandle;
            if (SafeReadField(owner_entity, offsets.base_owner_entity, owner_handle))
            {
                const auto owner_index = HandleToEntityIndex(owner_handle);
                if (owner_index == preferred_owner_entity_index || owner_index == fallback_owner_entity_index)
                {
                    if (!EntityLooksLikeGloveRenderable(
                            entity_list,
                            static_cast<int>(entity_cache.size()) - 1,
                            owner_index,
                            owner_entity,
                            offsets))
                    {
                        goto next_glove_scene_node;
                    }

                    hud_glove_entity = owner_entity;
                    hud_glove_entity_index = ResolveEntityIndexFromPointer(entity_cache, hud_glove_entity);
                    if (hud_glove_entity_index < 0)
                    {
                        hud_glove_entity_index = BuildSyntheticEntityIndex(hud_glove_entity, 0x474C5648u);
                    }
                    return true;
                }

                if (owner_index == player_binding.pawn_entity_index &&
                    owner_entity != hud_model_arms_entity &&
                    EntityLooksLikeGloveRenderable(
                        entity_list,
                        static_cast<int>(entity_cache.size()) - 1,
                        owner_index,
                        owner_entity,
                        offsets) &&
                    pawn_owned_hud_glove_entity == nullptr)
                {
                    pawn_owned_hud_glove_entity = owner_entity;
                    pawn_owned_hud_glove_entity_index = ResolveEntityIndexFromPointer(entity_cache, owner_entity);
                    if (pawn_owned_hud_glove_entity_index < 0)
                    {
                        pawn_owned_hud_glove_entity_index =
                            BuildSyntheticEntityIndex(owner_entity, 0x474C5650u);
                    }
                }
            }
        }

next_glove_scene_node:
        if (!SafeReadField(child_scene_node, offsets.game_scene_node_next_sibling, child_scene_node))
        {
            break;
        }
    }

    if (pawn_owned_hud_glove_entity != nullptr)
    {
        hud_glove_entity = pawn_owned_hud_glove_entity;
        hud_glove_entity_index = pawn_owned_hud_glove_entity_index;
        return true;
    }

    return false;
}

nskinzcs2::runtime::ResolvedGloveRenderBinding ResolveGloveRenderBinding(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::ResolvedGloveCarrier& carrier,
    void*& world_render_entity,
    void*& first_person_render_entity)
{
    nskinzcs2::runtime::ResolvedGloveRenderBinding binding {};
    binding.carrier_entity_index = carrier.glove_entity_index;
    world_render_entity = nullptr;
    first_person_render_entity = nullptr;

    if (TryResolveWearableOwnedGloveRenderEntity(
            entity_cache,
            carrier,
            offsets,
            binding.world_render_entity_index,
            world_render_entity))
    {
        binding.has_world_render = true;
    }
    else if (TryResolveLooseGloveRenderEntityForXuid(
                 entity_list,
                 entity_cache,
                 offsets,
                 player_binding.xuid,
                 binding.world_render_entity_index,
                 world_render_entity))
    {
        binding.has_world_render = true;
    }

    if (TryResolveHudGloveRenderEntity(
            entity_list,
            entity_cache,
            player_binding,
            binding.world_render_entity_index,
            carrier.glove_entity_index,
            offsets,
            binding.first_person_render_entity_index,
            first_person_render_entity))
    {
        binding.has_first_person_render = true;
    }

    if (binding.carrier_entity_index < 0)
    {
        binding.carrier_entity_index = player_binding.pawn_entity_index;
    }

    binding.valid = binding.has_world_render || binding.has_first_person_render;
    return binding;
}

nskinzcs2::runtime::ResolvedModelIdentity ResolveGloveModelIdentity(
    const nskinzcs2::model::Catalog& catalog,
    const nskinzcs2::runtime::ResolvedGloveCarrier& carrier,
    void* glove_world_render_entity,
    void* first_person_glove_entity,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request)
{
    nskinzcs2::runtime::ResolvedModelIdentity identity {};
    static_cast<void>(carrier);

    identity.live_glove_model_state_resolved =
        TryResolveEntityModelStateAddress(glove_world_render_entity, offsets, identity.live_glove_model_state);
    identity.first_person_arms_model_state_resolved =
        TryResolveEntityModelStateAddress(first_person_glove_entity, offsets, identity.first_person_arms_model_state);
    identity.live_glove_model_handle_resolved =
        TryReadEntityModelHandle(glove_world_render_entity, offsets, identity.live_glove_model_handle);
    identity.first_person_arms_model_handle_resolved =
        TryReadEntityModelHandle(first_person_glove_entity, offsets, identity.first_person_arms_model_handle);
    identity.live_glove_model_name_token_resolved =
        TryReadEntityModelNameToken(glove_world_render_entity, offsets, identity.live_glove_model_name_token);
    identity.first_person_arms_model_name_token_resolved =
        TryReadEntityModelNameToken(first_person_glove_entity, offsets, identity.first_person_arms_model_name_token);
    identity.live_glove_model_name_resolved =
        TryReadEntityModelNameString(glove_world_render_entity, offsets, identity.live_glove_model_name);
    identity.first_person_arms_model_name_resolved =
        TryReadEntityModelNameString(first_person_glove_entity, offsets, identity.first_person_arms_model_name);
    identity.live_glove_material_group_resolved =
        TryReadEntityMaterialGroupToken(glove_world_render_entity, offsets, identity.live_glove_material_group);
    identity.first_person_arms_material_group_resolved =
        TryReadEntityMaterialGroupToken(first_person_glove_entity, offsets, identity.first_person_arms_material_group);

    if (identity.live_glove_model_name_resolved)
    {
        if (const auto* metadata = TryResolveModelResourceMetadata(identity.live_glove_model_name); metadata != nullptr)
        {
            identity.live_glove_model_resource_path =
                TryMapModelPathToResourcePath(identity.live_glove_model_name).value_or(std::string {});
            identity.live_glove_skeleton_identity_hash = metadata->skeleton_identity_hash;
            identity.live_glove_material_resource_identity_hash = metadata->material_resource_identity_hash;
            identity.live_glove_skeleton_identity_resolved = metadata->skeleton_identity_resolved;
            identity.live_glove_material_resource_identity_resolved = metadata->material_resource_identity_resolved;
        }
    }

    if (identity.first_person_arms_model_name_resolved)
    {
        if (const auto* metadata = TryResolveModelResourceMetadata(identity.first_person_arms_model_name); metadata != nullptr)
        {
            identity.first_person_arms_model_resource_path =
                TryMapModelPathToResourcePath(identity.first_person_arms_model_name).value_or(std::string {});
            identity.first_person_arms_skeleton_identity_hash = metadata->skeleton_identity_hash;
            identity.first_person_arms_material_resource_identity_hash = metadata->material_resource_identity_hash;
            identity.first_person_arms_skeleton_identity_resolved = metadata->skeleton_identity_resolved;
            identity.first_person_arms_material_resource_identity_resolved = metadata->material_resource_identity_resolved;
        }
    }

    if (request.model_definition != 0)
    {
        if (const auto visual_it = catalog.visuals.find(request.model_definition); visual_it != catalog.visuals.end())
        {
            identity.target_world_model_path = visual_it->second.world_model;
            identity.target_view_model_path = visual_it->second.view_model;
            identity.target_model_known =
                !identity.target_world_model_path.empty() ||
                !identity.target_view_model_path.empty();

            if (const auto target_world_resource = TryMapModelPathToResourcePath(identity.target_world_model_path);
                target_world_resource.has_value())
            {
                identity.target_world_model_resource_path = *target_world_resource;
                if (const auto* metadata = TryResolveModelResourceMetadata(*target_world_resource); metadata != nullptr)
                {
                    identity.target_world_skeleton_identity_hash = metadata->skeleton_identity_hash;
                    identity.target_world_material_resource_identity_hash = metadata->material_resource_identity_hash;
                    identity.target_world_skeleton_identity_resolved = metadata->skeleton_identity_resolved;
                    identity.target_world_material_resource_identity_resolved = metadata->material_resource_identity_resolved;
                }
            }

            if (const auto target_view_resource = TryMapModelPathToResourcePath(identity.target_view_model_path);
                target_view_resource.has_value())
            {
                identity.target_view_model_resource_path = *target_view_resource;
                if (const auto* metadata = TryResolveModelResourceMetadata(*target_view_resource); metadata != nullptr)
                {
                    identity.target_view_skeleton_identity_hash = metadata->skeleton_identity_hash;
                    identity.target_view_material_resource_identity_hash = metadata->material_resource_identity_hash;
                    identity.target_view_skeleton_identity_resolved = metadata->skeleton_identity_resolved;
                    identity.target_view_material_resource_identity_resolved = metadata->material_resource_identity_resolved;
                }
            }
        }
    }

    identity.target_view_matches_first_person_skeleton =
        identity.target_view_skeleton_identity_resolved &&
        identity.first_person_arms_skeleton_identity_resolved &&
        identity.target_view_skeleton_identity_hash == identity.first_person_arms_skeleton_identity_hash;

    return identity;
}

int ResolveRequestedGloveDefinitionIndex(
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const int current_definition_index) noexcept
{
    return request.mode == nskinzcs2::runtime::GloveSlotMode::ModelAndFinish &&
            request.model_definition != 0
        ? request.model_definition
        : current_definition_index;
}

struct PawnGloveRefreshSnapshot
{
    bool need_reapply_resolved = false;
    bool need_reapply = false;
    bool gloves_changed_resolved = false;
    std::uint8_t gloves_changed = 0;
};

PawnGloveRefreshSnapshot CapturePawnGloveRefreshSnapshot(
    void* pawn_entity,
    const ClientSchemaOffsets& offsets)
{
    PawnGloveRefreshSnapshot snapshot {};
    if (pawn_entity == nullptr)
    {
        return snapshot;
    }

    if (offsets.pawn_need_reapply_gloves != 0)
    {
        snapshot.need_reapply_resolved =
            SafeReadField(pawn_entity, offsets.pawn_need_reapply_gloves, snapshot.need_reapply);
    }

    if (offsets.pawn_econ_gloves_changed != 0)
    {
        snapshot.gloves_changed_resolved =
            SafeReadField(pawn_entity, offsets.pawn_econ_gloves_changed, snapshot.gloves_changed);
    }

    return snapshot;
}

bool DidPawnGloveRefreshTrigger(
    const PawnGloveRefreshSnapshot& before_snapshot,
    const PawnGloveRefreshSnapshot& after_snapshot) noexcept
{
    if (after_snapshot.need_reapply_resolved && after_snapshot.need_reapply)
    {
        return true;
    }

    if (before_snapshot.gloves_changed_resolved &&
        after_snapshot.gloves_changed_resolved &&
        before_snapshot.gloves_changed != after_snapshot.gloves_changed)
    {
        return true;
    }

    return false;
}

std::vector<std::pair<std::uint16_t, float>> BuildGloveFinishAttributes(
    const nskinzcs2::runtime::GloveAppearanceRequest& request)
{
    return {
        {kAttributePaintKit, static_cast<float>(request.paint_kit)},
        {kAttributeSeed, static_cast<float>(request.seed)},
        {kAttributeWear, request.wear},
    };
}

bool DoesAppliedPawnGloveBaseFieldsMatchRequest(
    void* glove_item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index)
{
    if (glove_item_view == nullptr)
    {
        return false;
    }

    const auto expected_definition_index =
        ResolveRequestedGloveDefinitionIndex(request, current_definition_index);
    int actual_definition_index = 0;
    if (!TryReadItemDefinitionIndex(glove_item_view, offsets, actual_definition_index) ||
        actual_definition_index != expected_definition_index)
    {
        return false;
    }

    std::uint32_t actual_item_id_high = 0;
    if (!SafeReadField(glove_item_view, offsets.item_view_item_id_high, actual_item_id_high) ||
        actual_item_id_high != 0xFFFFFFFFu)
    {
        return false;
    }

    if (offsets.item_view_item_id_low != 0)
    {
        std::uint32_t actual_item_id_low = 0;
        if (!SafeReadField(glove_item_view, offsets.item_view_item_id_low, actual_item_id_low) ||
            actual_item_id_low != 0xFFFFFFFFu)
        {
            return false;
        }
    }

    std::uint32_t actual_account_id = 0;
    if (!SafeReadField(glove_item_view, offsets.item_view_account_id, actual_account_id) ||
        actual_account_id != AccountIdFromXuid(xuid))
    {
        return false;
    }

    if (offsets.item_view_disallow_soc != 0)
    {
        bool actual_disallow_soc = false;
        if (!SafeReadField(glove_item_view, offsets.item_view_disallow_soc, actual_disallow_soc) ||
            !actual_disallow_soc)
        {
            return false;
        }
    }

    if (offsets.item_view_entity_quality != 0)
    {
        std::uint8_t actual_quality = 0;
        if (!SafeReadField(glove_item_view, offsets.item_view_entity_quality, actual_quality) ||
            static_cast<int>(actual_quality) != std::clamp(request.quality, 0, 255))
        {
            return false;
        }
    }

    if (offsets.item_view_initialized != 0)
    {
        bool actual_initialized = false;
        if (!SafeReadField(glove_item_view, offsets.item_view_initialized, actual_initialized) ||
            !actual_initialized)
        {
            return false;
        }
    }

    return true;
}

bool DoesAppliedPawnGloveFinishMatchRequest(
    void* glove_item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index)
{
    const auto direct_attribute_writes_allowed = ShouldAllowDirectAttributeListWrites(offsets);
    const auto has_runtime_owned_binding = HasRuntimeOwnedAttributeListBinding(glove_item_view);
    if (!direct_attribute_writes_allowed && !has_runtime_owned_binding)
    {
        return DoesAppliedPawnGloveBaseFieldsMatchRequest(
            glove_item_view,
            offsets,
            request,
            xuid,
            current_definition_index);
    }

    return DoesAppliedPawnGloveBaseFieldsMatchRequest(
               glove_item_view,
               offsets,
               request,
               xuid,
               current_definition_index) &&
        VerifyAttributeValues(glove_item_view, offsets, BuildGloveFinishAttributes(request));
}

bool ApplyGloveFinishToPawnEconGloves(
    void* glove_item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index)
{
    if (glove_item_view == nullptr)
    {
        return false;
    }

    const auto final_definition_index = static_cast<std::uint16_t>(
        ResolveRequestedGloveDefinitionIndex(request, current_definition_index));
    if (final_definition_index == 0)
    {
        return false;
    }

    const auto quality = static_cast<std::uint8_t>(std::clamp(request.quality, 0, 255));
    const auto item_id_high = static_cast<std::uint32_t>(0xFFFFFFFFu);
    const auto item_id_low = static_cast<std::uint32_t>(0xFFFFFFFFu);
    const auto account_id = AccountIdFromXuid(xuid);
    const auto desired_attributes = BuildGloveFinishAttributes(request);

    bool success = true;
    success = success && SafeWriteField(glove_item_view, offsets.item_view_definition_index, final_definition_index);
    success = success && SafeWriteField(glove_item_view, offsets.item_view_item_id_high, item_id_high);
    if (offsets.item_view_item_id_low != 0)
    {
        success = success && SafeWriteField(glove_item_view, offsets.item_view_item_id_low, item_id_low);
    }
    success = success && SafeWriteField(glove_item_view, offsets.item_view_account_id, account_id);
    if (offsets.item_view_disallow_soc != 0)
    {
        success = success && SafeWriteField(glove_item_view, offsets.item_view_disallow_soc, true);
    }
    if (offsets.item_view_entity_quality != 0)
    {
        success = success && SafeWriteField(glove_item_view, offsets.item_view_entity_quality, quality);
    }
    if (offsets.item_view_initialized != 0)
    {
        success = success && SafeWriteField(glove_item_view, offsets.item_view_initialized, true);
    }

    const auto field_write_succeeded = success;
    const auto direct_attribute_writes_allowed = ShouldAllowDirectAttributeListWrites(offsets);

    bool attribute_update_succeeded = direct_attribute_writes_allowed;
    if (direct_attribute_writes_allowed)
    {
        for (const auto& [definition_index, value] : desired_attributes)
        {
            attribute_update_succeeded =
                TryUpdateExistingAttributeValueInPlaceOnly(glove_item_view, offsets, definition_index, value) &&
                attribute_update_succeeded;
        }
    }

    const auto attribute_values_verified =
        VerifyAttributeValues(glove_item_view, offsets, desired_attributes);
    success = field_write_succeeded && (attribute_update_succeeded || attribute_values_verified);

    if (!attribute_values_verified)
    {
        const auto install_into_dynamic =
            offsets.item_view_dynamic_attribute_list != 0 &&
            TryInstallRuntimeOwnedAttributeList(
                glove_item_view,
                offsets.item_view_dynamic_attribute_list,
                offsets,
                desired_attributes,
                false);
        const auto install_into_static =
            !install_into_dynamic &&
            offsets.item_view_attribute_list != 0 &&
            TryInstallRuntimeOwnedAttributeList(
                glove_item_view,
                offsets.item_view_attribute_list,
                offsets,
                desired_attributes,
                false);
        success = (install_into_dynamic || install_into_static) && field_write_succeeded;
    }

    return success &&
        DoesAppliedPawnGloveFinishMatchRequest(
            glove_item_view,
            offsets,
            request,
            xuid,
            current_definition_index);
}

std::wstring BuildGloveFinishVerifyLine(
    const int pawn_entity_index,
    void* glove_item_view,
    const ClientSchemaOffsets& offsets,
    const PawnGloveRefreshSnapshot& refresh_snapshot)
{
    int definition_index = 0;
    TryReadItemDefinitionIndex(glove_item_view, offsets, definition_index);

    std::uint32_t account_id = 0;
    SafeReadField(glove_item_view, offsets.item_view_account_id, account_id);

    std::uint8_t quality = 0;
    if (offsets.item_view_entity_quality != 0)
    {
        SafeReadField(glove_item_view, offsets.item_view_entity_quality, quality);
    }

    std::wstringstream stream;
    stream << L"Verified pawn glove appearance slot: pawn_entity=" << pawn_entity_index
        << L", item_view=" << FormatPointer(glove_item_view)
        << L", definition=" << definition_index
        << L", attr_paint=" << ReadAttributeValueOrDefault(glove_item_view, offsets, kAttributePaintKit, -1.0f)
        << L", attr_seed=" << ReadAttributeValueOrDefault(glove_item_view, offsets, kAttributeSeed, -1.0f)
        << L", attr_wear=" << ReadAttributeValueOrDefault(glove_item_view, offsets, kAttributeWear, -1.0f)
        << L", account_id=" << account_id
        << L", quality=" << static_cast<int>(quality)
        << L", need_reapply=" << (refresh_snapshot.need_reapply_resolved && refresh_snapshot.need_reapply ? 1 : 0)
        << L", gloves_changed="
        << (refresh_snapshot.gloves_changed_resolved ? std::to_wstring(refresh_snapshot.gloves_changed) : L"?");
    return stream.str();
}

struct GloveAppearanceSnapshot
{
    int carrier_entity_index = -1;
    int world_render_entity_index = -1;
    int first_person_render_entity_index = -1;
    int definition_index = 0;
    int fallback_paint = 0;
    int fallback_seed = 0;
    float fallback_wear = 0.0f;
    bool field_readback_resolved = false;
    bool has_world_render = false;
    bool has_first_person_render = false;
    nskinzcs2::runtime::ResolvedModelIdentity model_identity;
};

bool DoesAppliedGloveCarrierMatchProfile(
    void* econ_entity,
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index,
    const bool read_finish_from_item_view);

bool DoesAppliedGloveWearableMatchProfile(
    void* econ_entity,
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index);

GloveAppearanceSnapshot CaptureGloveAppearanceSnapshot(
    void* econ_entity,
    void* item_view,
    const nskinzcs2::runtime::ResolvedGloveRenderBinding& render_binding,
    const nskinzcs2::runtime::ResolvedModelIdentity& model_identity,
    const ClientSchemaOffsets& offsets,
    const bool read_finish_from_item_view)
{
    GloveAppearanceSnapshot snapshot {};
    snapshot.carrier_entity_index = render_binding.carrier_entity_index;
    snapshot.world_render_entity_index = render_binding.world_render_entity_index;
    snapshot.first_person_render_entity_index = render_binding.first_person_render_entity_index;
    snapshot.has_world_render = render_binding.has_world_render;
    snapshot.has_first_person_render = render_binding.has_first_person_render;
    snapshot.model_identity = model_identity;

    int definition_index = 0;
    int fallback_paint = 0;
    int fallback_seed = 0;
    float fallback_wear = 0.0f;
    if (read_finish_from_item_view)
    {
        snapshot.field_readback_resolved = TryReadItemDefinitionIndex(item_view, offsets, definition_index);
        fallback_paint = static_cast<int>(ReadAttributeValueOrDefault(item_view, offsets, kAttributePaintKit, 0.0f));
        fallback_seed = static_cast<int>(ReadAttributeValueOrDefault(item_view, offsets, kAttributeSeed, 0.0f));
        fallback_wear = ReadAttributeValueOrDefault(item_view, offsets, kAttributeWear, 0.0000001f);
    }
    else
    {
        snapshot.field_readback_resolved =
            TryReadItemDefinitionIndex(item_view, offsets, definition_index) &&
            SafeReadField(econ_entity, offsets.econ_entity_fallback_paint_kit, fallback_paint) &&
            SafeReadField(econ_entity, offsets.econ_entity_fallback_seed, fallback_seed) &&
            SafeReadField(econ_entity, offsets.econ_entity_fallback_wear, fallback_wear);
    }

    snapshot.definition_index = definition_index;
    snapshot.fallback_paint = fallback_paint;
    snapshot.fallback_seed = fallback_seed;
    snapshot.fallback_wear = fallback_wear;
    return snapshot;
}

GloveAppearanceSnapshot CaptureGloveAppearanceSnapshot(
    void* econ_entity,
    void* item_view,
    const nskinzcs2::runtime::ResolvedGloveRenderBinding& render_binding,
    const nskinzcs2::runtime::ResolvedModelIdentity& model_identity,
    const ClientSchemaOffsets& offsets)
{
    return CaptureGloveAppearanceSnapshot(
        econ_entity,
        item_view,
        render_binding,
        model_identity,
        offsets,
        false);
}

std::wstring BuildGloveAppearanceVerifyLine(const GloveAppearanceSnapshot& snapshot)
{
    std::wstringstream stream;
    stream << L"Verified glove slot: carrier_entity=" << snapshot.carrier_entity_index
        << L", world_render_entity=" << snapshot.world_render_entity_index
        << L", first_person_render_entity=" << snapshot.first_person_render_entity_index
        << L", definition=" << snapshot.definition_index
        << L", fallback_paint=" << snapshot.fallback_paint
        << L", fallback_seed=" << snapshot.fallback_seed
        << L", fallback_wear=" << snapshot.fallback_wear
        << L", live_model_handle=0x" << std::hex << std::uppercase
        << snapshot.model_identity.live_glove_model_handle
        << L", live_model_name=0x" << snapshot.model_identity.live_glove_model_name_token
        << L", live_material_group=0x" << snapshot.model_identity.live_glove_material_group
        << L", live_skeleton_identity=0x" << snapshot.model_identity.live_glove_skeleton_identity_hash
        << L", live_material_identity=0x" << snapshot.model_identity.live_glove_material_resource_identity_hash
        << std::dec << std::nouppercase;
    if (snapshot.model_identity.live_glove_model_name_resolved)
    {
        stream << L", live_model_name_path=" << NarrowToWide(snapshot.model_identity.live_glove_model_name);
    }
    if (snapshot.model_identity.live_glove_model_resource_path.empty() == false)
    {
        stream << L", live_model_resource=" << NarrowToWide(snapshot.model_identity.live_glove_model_resource_path);
    }
    if (snapshot.has_first_person_render)
    {
        stream << L", first_person_model_handle=0x" << std::hex << std::uppercase
            << snapshot.model_identity.first_person_arms_model_handle
            << L", first_person_model_name=0x" << snapshot.model_identity.first_person_arms_model_name_token
            << L", first_person_material_group=0x" << snapshot.model_identity.first_person_arms_material_group
            << L", first_person_skeleton_identity=0x" << snapshot.model_identity.first_person_arms_skeleton_identity_hash
            << L", first_person_material_identity=0x" << snapshot.model_identity.first_person_arms_material_resource_identity_hash
            << std::dec << std::nouppercase;
        if (snapshot.model_identity.first_person_arms_model_name_resolved)
        {
            stream << L", first_person_model_name_path=" << NarrowToWide(snapshot.model_identity.first_person_arms_model_name);
        }
        if (snapshot.model_identity.first_person_arms_model_resource_path.empty() == false)
        {
            stream << L", first_person_model_resource="
                << NarrowToWide(snapshot.model_identity.first_person_arms_model_resource_path);
        }
    }
    return stream.str();
}

bool VerifyGloveAppearanceState(
    void* econ_entity,
    void* item_view,
    const GloveAppearanceSnapshot& before_snapshot,
    const GloveAppearanceSnapshot& after_snapshot,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index,
    const bool read_finish_from_item_view,
    std::wstring& verify_line,
    std::wstring& issue)
{
    verify_line = BuildGloveAppearanceVerifyLine(after_snapshot);
    issue.clear();

    if (!before_snapshot.field_readback_resolved || !after_snapshot.field_readback_resolved)
    {
        issue = L"glove carrier readback snapshot was incomplete.";
        return false;
    }

    if (!DoesAppliedGloveCarrierMatchProfile(
            econ_entity,
            item_view,
            offsets,
            request,
            xuid,
            current_definition_index,
            read_finish_from_item_view))
    {
        issue = L"glove carrier entity readback did not match the requested glove slot.";
        return false;
    }

    if (!after_snapshot.has_world_render)
    {
        issue = L"glove world render binding was not resolved after apply.";
        return false;
    }

    if (request.mode == nskinzcs2::runtime::GloveSlotMode::ModelAndFinish)
    {
        const auto world_model_matches =
            (!after_snapshot.model_identity.live_glove_model_resource_path.empty() &&
             !after_snapshot.model_identity.target_world_model_resource_path.empty() &&
             ResourcePathMatches(
                 after_snapshot.model_identity.live_glove_model_resource_path,
                 after_snapshot.model_identity.target_world_model_resource_path)) ||
            (after_snapshot.model_identity.live_glove_model_name_resolved &&
             ResourcePathMatches(
                 after_snapshot.model_identity.live_glove_model_name,
                 after_snapshot.model_identity.target_world_model_path));
        if (!world_model_matches)
        {
            issue = L"live glove render model did not bind to the requested glove world model.";
            return false;
        }

        if (!after_snapshot.has_first_person_render)
        {
            issue = L"first-person glove render binding was not resolved after apply.";
            return false;
        }

        const auto first_person_model_matches =
            (!after_snapshot.model_identity.first_person_arms_model_resource_path.empty() &&
             !after_snapshot.model_identity.target_view_model_resource_path.empty() &&
             ResourcePathMatches(
                 after_snapshot.model_identity.first_person_arms_model_resource_path,
                 after_snapshot.model_identity.target_view_model_resource_path)) ||
            (after_snapshot.model_identity.first_person_arms_model_name_resolved &&
             ResourcePathMatches(
                 after_snapshot.model_identity.first_person_arms_model_name,
                 after_snapshot.model_identity.target_view_model_path));
        if (!first_person_model_matches)
        {
            issue = L"first-person glove render model did not bind to the requested glove view model.";
            return false;
        }
    }

    const auto expected_definition_index = ResolveRequestedGloveDefinitionIndex(request, current_definition_index);
    const auto requested_model_changed = expected_definition_index != before_snapshot.definition_index;
    const auto requested_finish_changed =
        before_snapshot.fallback_paint != request.paint_kit ||
        before_snapshot.fallback_seed != request.seed ||
        !nskinzcs2::model::CosmeticWearMatchesExactly(before_snapshot.fallback_wear, request.wear);

    const auto live_render_state_resolved =
        after_snapshot.has_world_render &&
        after_snapshot.model_identity.live_glove_model_state_resolved &&
        after_snapshot.model_identity.live_glove_model_handle_resolved &&
        after_snapshot.model_identity.live_glove_material_group_resolved &&
        after_snapshot.model_identity.live_glove_material_resource_identity_resolved;
    const auto first_person_render_state_resolved =
        after_snapshot.has_first_person_render &&
        after_snapshot.model_identity.first_person_arms_model_state_resolved &&
        after_snapshot.model_identity.first_person_arms_model_handle_resolved &&
        after_snapshot.model_identity.first_person_arms_material_group_resolved &&
        after_snapshot.model_identity.first_person_arms_material_resource_identity_resolved;

    const auto live_model_binding_changed =
        (before_snapshot.model_identity.live_glove_model_handle_resolved &&
         after_snapshot.model_identity.live_glove_model_handle_resolved &&
         before_snapshot.model_identity.live_glove_model_handle != after_snapshot.model_identity.live_glove_model_handle) ||
        (before_snapshot.model_identity.live_glove_model_name_resolved &&
         after_snapshot.model_identity.live_glove_model_name_resolved &&
         before_snapshot.model_identity.live_glove_model_name != after_snapshot.model_identity.live_glove_model_name) ||
        (before_snapshot.model_identity.live_glove_model_name_token_resolved &&
         after_snapshot.model_identity.live_glove_model_name_token_resolved &&
         before_snapshot.model_identity.live_glove_model_name_token != after_snapshot.model_identity.live_glove_model_name_token);

    const auto first_person_model_binding_changed =
        (before_snapshot.model_identity.first_person_arms_model_handle_resolved &&
         after_snapshot.model_identity.first_person_arms_model_handle_resolved &&
         before_snapshot.model_identity.first_person_arms_model_handle !=
             after_snapshot.model_identity.first_person_arms_model_handle) ||
        (before_snapshot.model_identity.first_person_arms_model_name_token_resolved &&
         after_snapshot.model_identity.first_person_arms_model_name_token_resolved &&
         before_snapshot.model_identity.first_person_arms_model_name_token !=
             after_snapshot.model_identity.first_person_arms_model_name_token);
    const auto first_person_model_name_changed =
        before_snapshot.model_identity.first_person_arms_model_name_resolved &&
        after_snapshot.model_identity.first_person_arms_model_name_resolved &&
        before_snapshot.model_identity.first_person_arms_model_name !=
            after_snapshot.model_identity.first_person_arms_model_name;

    const auto live_material_binding_changed =
        (before_snapshot.model_identity.live_glove_material_group_resolved &&
         after_snapshot.model_identity.live_glove_material_group_resolved &&
         before_snapshot.model_identity.live_glove_material_group != after_snapshot.model_identity.live_glove_material_group) ||
        (before_snapshot.model_identity.live_glove_material_resource_identity_resolved &&
         after_snapshot.model_identity.live_glove_material_resource_identity_resolved &&
         before_snapshot.model_identity.live_glove_material_resource_identity_hash !=
             after_snapshot.model_identity.live_glove_material_resource_identity_hash);

    const auto first_person_material_binding_changed =
        (before_snapshot.model_identity.first_person_arms_material_group_resolved &&
         after_snapshot.model_identity.first_person_arms_material_group_resolved &&
         before_snapshot.model_identity.first_person_arms_material_group !=
            after_snapshot.model_identity.first_person_arms_material_group) ||
        (before_snapshot.model_identity.first_person_arms_material_resource_identity_resolved &&
         after_snapshot.model_identity.first_person_arms_material_resource_identity_resolved &&
         before_snapshot.model_identity.first_person_arms_material_resource_identity_hash !=
            after_snapshot.model_identity.first_person_arms_material_resource_identity_hash);

    const auto finish_binding_confirmed =
        after_snapshot.field_readback_resolved &&
        after_snapshot.definition_index == expected_definition_index &&
        after_snapshot.fallback_paint == request.paint_kit &&
        after_snapshot.fallback_seed == request.seed &&
        nskinzcs2::model::CosmeticWearMatchesExactly(after_snapshot.fallback_wear, request.wear);

    bool live_material_resource_matches_target = false;
    bool first_person_material_resource_matches_target = !after_snapshot.has_first_person_render;
    if (request.mode == nskinzcs2::runtime::GloveSlotMode::ModelAndFinish)
    {
        live_material_resource_matches_target =
            after_snapshot.model_identity.live_glove_material_resource_identity_resolved &&
            after_snapshot.model_identity.target_world_material_resource_identity_resolved &&
            after_snapshot.model_identity.live_glove_material_resource_identity_hash ==
                after_snapshot.model_identity.target_world_material_resource_identity_hash;
        first_person_material_resource_matches_target =
            after_snapshot.has_first_person_render &&
            after_snapshot.model_identity.first_person_arms_material_resource_identity_resolved &&
            after_snapshot.model_identity.target_view_material_resource_identity_resolved &&
            after_snapshot.model_identity.first_person_arms_material_resource_identity_hash ==
                after_snapshot.model_identity.target_view_material_resource_identity_hash;
    }
    else
    {
        live_material_resource_matches_target =
            before_snapshot.model_identity.live_glove_material_resource_identity_resolved &&
            after_snapshot.model_identity.live_glove_material_resource_identity_resolved &&
            before_snapshot.model_identity.live_glove_material_resource_identity_hash ==
                after_snapshot.model_identity.live_glove_material_resource_identity_hash;
        first_person_material_resource_matches_target =
            !after_snapshot.has_first_person_render ||
            (before_snapshot.model_identity.first_person_arms_material_resource_identity_resolved &&
             after_snapshot.model_identity.first_person_arms_material_resource_identity_resolved &&
             before_snapshot.model_identity.first_person_arms_material_resource_identity_hash ==
                after_snapshot.model_identity.first_person_arms_material_resource_identity_hash);
    }

    nskinzcs2::runtime::GloveRenderVerificationInputs verification_inputs;
    verification_inputs.mode = request.mode;
    verification_inputs.has_first_person_render = after_snapshot.has_first_person_render;
    verification_inputs.requested_model_changed = requested_model_changed;
    verification_inputs.requested_finish_changed = requested_finish_changed;
    verification_inputs.live_render_state_resolved = live_render_state_resolved;
    verification_inputs.first_person_render_state_resolved = first_person_render_state_resolved;
    verification_inputs.live_model_binding_changed = live_model_binding_changed;
    verification_inputs.first_person_model_binding_changed =
        first_person_model_binding_changed || first_person_model_name_changed;
    verification_inputs.live_material_binding_changed = live_material_binding_changed;
    verification_inputs.first_person_material_binding_changed = first_person_material_binding_changed;
    verification_inputs.first_person_binding_changed =
        before_snapshot.first_person_render_entity_index != after_snapshot.first_person_render_entity_index;
    verification_inputs.finish_binding_confirmed = finish_binding_confirmed;
    verification_inputs.live_material_resource_matches_target = live_material_resource_matches_target;
    verification_inputs.first_person_material_resource_matches_target =
        first_person_material_resource_matches_target;

    const auto verification = nskinzcs2::runtime::EvaluateGloveRenderVerification(verification_inputs);

    if (!verification.verified)
    {
        issue = std::wstring(L"glove render verification failed: ") +
            nskinzcs2::runtime::GloveRenderVerificationReasonText(verification.reason);
        return false;
    }

    return true;
}

bool VerifyGloveAppearanceState(
    void* econ_entity,
    void* item_view,
    const GloveAppearanceSnapshot& before_snapshot,
    const GloveAppearanceSnapshot& after_snapshot,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index,
    std::wstring& verify_line,
    std::wstring& issue)
{
    return VerifyGloveAppearanceState(
        econ_entity,
        item_view,
        before_snapshot,
        after_snapshot,
        offsets,
        request,
        xuid,
        current_definition_index,
        false,
        verify_line,
        issue);
}

bool DoesAppliedGloveCarrierMatchProfile(
    void* econ_entity,
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index,
    const bool read_finish_from_item_view)
{
    if (item_view == nullptr)
    {
        return false;
    }

    const auto expected_definition_index = ResolveRequestedGloveDefinitionIndex(request, current_definition_index);
    int actual_definition_index = 0;
    if (!TryReadItemDefinitionIndex(item_view, offsets, actual_definition_index) ||
        actual_definition_index != expected_definition_index)
    {
        return false;
    }

    std::uint32_t actual_item_id_high = 0;
    if (!SafeReadField(item_view, offsets.item_view_item_id_high, actual_item_id_high) ||
        actual_item_id_high != 0xFFFFFFFFu)
    {
        return false;
    }

    if (offsets.item_view_item_id_low != 0)
    {
        std::uint32_t actual_item_id_low = 0;
        if (!SafeReadField(item_view, offsets.item_view_item_id_low, actual_item_id_low) ||
            actual_item_id_low != 0xFFFFFFFFu)
        {
            return false;
        }
    }

    std::uint32_t actual_account_id = 0;
    if (!SafeReadField(item_view, offsets.item_view_account_id, actual_account_id) ||
        actual_account_id != AccountIdFromXuid(xuid))
    {
        return false;
    }

    if (offsets.item_view_disallow_soc != 0)
    {
        bool actual_disallow_soc = false;
        if (!SafeReadField(item_view, offsets.item_view_disallow_soc, actual_disallow_soc) ||
            !actual_disallow_soc)
        {
            return false;
        }
    }

    if (offsets.item_view_initialized != 0)
    {
        bool actual_initialized = false;
        if (!SafeReadField(item_view, offsets.item_view_initialized, actual_initialized) ||
            !actual_initialized)
        {
            return false;
        }
    }

    if (offsets.item_view_entity_quality != 0)
    {
        std::uint8_t actual_quality = 0;
        if (!SafeReadField(item_view, offsets.item_view_entity_quality, actual_quality) ||
            static_cast<int>(actual_quality) != std::clamp(request.quality, 0, 255))
        {
            return false;
        }
    }

    if (read_finish_from_item_view)
    {
        const auto should_verify_item_view_attributes =
            ShouldAllowDirectAttributeListWrites(offsets) ||
            HasRuntimeOwnedAttributeListBinding(item_view);
        if (should_verify_item_view_attributes &&
            !VerifyAttributeValues(item_view, offsets, BuildGloveFinishAttributes(request)))
        {
            return false;
        }
    }
    else
    {
        if (econ_entity == nullptr)
        {
            return false;
        }

        int actual_paint_kit = 0;
        if (!SafeReadField(econ_entity, offsets.econ_entity_fallback_paint_kit, actual_paint_kit) ||
            actual_paint_kit != request.paint_kit)
        {
            return false;
        }

        int actual_seed = 0;
        if (!SafeReadField(econ_entity, offsets.econ_entity_fallback_seed, actual_seed) ||
            actual_seed != request.seed)
        {
            return false;
        }

        float actual_wear = 0.0000001f;
        if (!SafeReadField(econ_entity, offsets.econ_entity_fallback_wear, actual_wear) ||
            !nskinzcs2::model::CosmeticWearMatchesExactly(actual_wear, request.wear))
        {
            return false;
        }

        if (offsets.econ_entity_fallback_stat_trak != 0)
        {
            int actual_stat_trak = 0;
            if (!SafeReadField(econ_entity, offsets.econ_entity_fallback_stat_trak, actual_stat_trak) ||
                actual_stat_trak != 0)
            {
                return false;
            }
        }

        const auto xuid_parts = SplitXuid(xuid);
        if (offsets.econ_entity_original_owner_xuid_low != 0)
        {
            std::uint32_t owner_low = 0;
            if (!SafeReadField(econ_entity, offsets.econ_entity_original_owner_xuid_low, owner_low) ||
                owner_low != xuid_parts.first)
            {
                return false;
            }
        }

        if (offsets.econ_entity_original_owner_xuid_high != 0)
        {
            std::uint32_t owner_high = 0;
            if (!SafeReadField(econ_entity, offsets.econ_entity_original_owner_xuid_high, owner_high) ||
                owner_high != xuid_parts.second)
            {
                return false;
            }
        }

        if (offsets.econ_entity_initialized != 0)
        {
            bool actual_initialized = false;
            if (!SafeReadField(econ_entity, offsets.econ_entity_initialized, actual_initialized) ||
                !actual_initialized)
            {
                return false;
            }
        }
    }

    return true;
}

bool DoesAppliedGloveWearableMatchProfile(
    void* econ_entity,
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index)
{
    return DoesAppliedGloveCarrierMatchProfile(
        econ_entity,
        item_view,
        offsets,
        request,
        xuid,
        current_definition_index,
        false);
}

bool ApplyGloveProfileToWearable(
    void* econ_entity,
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::runtime::GloveAppearanceRequest& request,
    const std::uint64_t xuid,
    const int current_definition_index)
{
    if (econ_entity == nullptr || item_view == nullptr)
    {
        return false;
    }

    const auto final_definition_index = static_cast<std::uint16_t>(
        ResolveRequestedGloveDefinitionIndex(request, current_definition_index));
    const auto quality = static_cast<std::uint8_t>(std::clamp(request.quality, 0, 255));
    const auto item_id_high = static_cast<std::uint32_t>(0xFFFFFFFFu);
    const auto item_id_low = static_cast<std::uint32_t>(0xFFFFFFFFu);
    const auto account_id = AccountIdFromXuid(xuid);
    const auto xuid_parts = SplitXuid(xuid);

    bool success = true;
    success = success && SafeWriteField(econ_entity, offsets.econ_entity_fallback_paint_kit, request.paint_kit);
    success = success && SafeWriteField(econ_entity, offsets.econ_entity_fallback_seed, request.seed);
    success = success && SafeWriteField(econ_entity, offsets.econ_entity_fallback_wear, request.wear);
    if (offsets.econ_entity_fallback_stat_trak != 0)
    {
        success = success && SafeWriteField(econ_entity, offsets.econ_entity_fallback_stat_trak, 0);
    }
    if (offsets.econ_entity_original_owner_xuid_low != 0)
    {
        success = success && SafeWriteField(econ_entity, offsets.econ_entity_original_owner_xuid_low, xuid_parts.first);
    }
    if (offsets.econ_entity_original_owner_xuid_high != 0)
    {
        success = success && SafeWriteField(econ_entity, offsets.econ_entity_original_owner_xuid_high, xuid_parts.second);
    }
    if (offsets.econ_entity_initialized != 0)
    {
        success = success && SafeWriteField(econ_entity, offsets.econ_entity_initialized, true);
    }

    success = success && SafeWriteField(item_view, offsets.item_view_definition_index, final_definition_index);
    success = success && SafeWriteField(item_view, offsets.item_view_item_id_high, item_id_high);
    if (offsets.item_view_item_id_low != 0)
    {
        success = success && SafeWriteField(item_view, offsets.item_view_item_id_low, item_id_low);
    }
    success = success && SafeWriteField(item_view, offsets.item_view_account_id, account_id);
    if (offsets.item_view_disallow_soc != 0)
    {
        success = success && SafeWriteField(item_view, offsets.item_view_disallow_soc, true);
    }
    if (offsets.item_view_entity_quality != 0)
    {
        success = success && SafeWriteField(item_view, offsets.item_view_entity_quality, quality);
    }
    if (offsets.item_view_initialized != 0)
    {
        success = success && SafeWriteField(item_view, offsets.item_view_initialized, true);
    }

    return success;
}

std::vector<std::pair<std::uint16_t, float>> BuildWeaponRefreshAttributesImpl(
    const nskinzcs2::model::CosmeticProfile& profile,
    const nskinzcs2::model::KeychainProfile* keychain_profile)
{
    return nskinzcs2::runtime::BuildWeaponAppearancePayload(profile, 0, keychain_profile).temporary_attributes;
}

std::wstring DescribeWeaponRefreshAttributes(
    const std::vector<std::pair<std::uint16_t, float>>& attributes)
{
    std::wstringstream stream;
    bool first = true;
    for (const auto& [definition_index, value] : attributes)
    {
        if (!first)
        {
            stream << L", ";
        }

        first = false;
        switch (definition_index)
        {
        case kAttributePaintKit:
            stream << L"paint=" << value;
            break;
        case kAttributeSeed:
            stream << L"seed=" << value;
            break;
        case kAttributeWear:
            stream << L"wear=" << value;
            break;
        case kAttributeStatTrak:
            stream << L"stattrak=" << value;
            break;
        default:
            stream << L"attr" << definition_index << L"=" << value;
            break;
        }
    }

    return stream.str();
}

std::vector<std::uint16_t> BuildMissingWeaponAttributeDefinitionIndicesImpl(
    const nskinzcs2::model::CosmeticProfile& profile,
    const std::vector<std::uint16_t>& existing_definition_indices,
    const nskinzcs2::model::KeychainProfile* keychain_profile)
{
    std::vector<std::uint16_t> required_definition_indices;
    required_definition_indices.reserve(32);

    auto contains_existing_definition =
        [&existing_definition_indices](const std::uint16_t definition_index)
        {
            return std::find(existing_definition_indices.begin(), existing_definition_indices.end(), definition_index) !=
                existing_definition_indices.end();
        };

    auto append_if_missing =
        [&required_definition_indices, &contains_existing_definition](const std::uint16_t definition_index)
        {
            if (contains_existing_definition(definition_index) ||
                std::find(required_definition_indices.begin(), required_definition_indices.end(), definition_index) !=
                    required_definition_indices.end())
            {
                return;
            }

            required_definition_indices.push_back(definition_index);
        };

    const auto desired_attributes = BuildWeaponRefreshAttributesImpl(profile, keychain_profile);
    for (const auto& [definition_index, value] : desired_attributes)
    {
        static_cast<void>(value);
        append_if_missing(definition_index);
    }

    return required_definition_indices;
}

bool TryAttachTemporaryWeaponRefreshAttributes(
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::CosmeticProfile& profile,
    TemporaryAttributeListAttachment& attachment,
    const nskinzcs2::model::KeychainProfile* keychain_profile = nullptr)
{
    attachment = {};
    if (item_view == nullptr || offsets.item_view_attribute_list == 0 || offsets.attribute_list_attributes == 0)
    {
        return false;
    }

    const auto attributes = BuildWeaponRefreshAttributesImpl(profile, keychain_profile);
    if (attributes.empty())
    {
        return false;
    }

    const auto attribute_stride = ResolveEconItemAttributeStride(offsets);
    if (attribute_stride == 0)
    {
        return false;
    }

    // Current CS2 does not reliably treat paint=0 as a replacement while
    // seed/wear (or a previous paint) remain in either attribute list. Clear
    // both lists through their verified Schema operation once inside the
    // armed knife refresh epoch, then publish one engine-owned paint-kit-zero
    // record. The reference helper's verified machine code only enters its
    // native material clear/rebuild path when an attribute-vector count is
    // positive; this official default record supplies that trigger without
    // retaining any old finish inputs. Never invoke the helper's internal
    // material clear function manually after it returns.
    if (IsExplicitVanillaKnifeFinishProfile(profile))
    {
        if (offsets.attribute_list_attributes_operation == nullptr ||
            offsets.attribute_list_attributes_element_size != attribute_stride ||
            offsets.item_view_dynamic_attribute_list == 0)
        {
            return false;
        }

        auto clear_attribute_list =
            [&](const std::ptrdiff_t list_offset, RefreshAttributeVector& previous)
            {
                auto* list_vector_address =
                    reinterpret_cast<std::uint8_t*>(item_view) +
                    list_offset + offsets.attribute_list_attributes;
                if (!SafeReadValue(list_vector_address, previous) ||
                    previous.size > 128 ||
                    (previous.size != 0 && previous.ptr == 0))
                {
                    return false;
                }

                if (previous.size == 0)
                {
                    return true;
                }

                if (previous.size > static_cast<std::uint64_t>(
                        std::numeric_limits<std::int32_t>::max()) ||
                    !TryInvokeNetworkVectorOperation(
                        offsets.attribute_list_attributes_operation,
                        5,
                        list_vector_address,
                        0,
                        static_cast<std::int32_t>(previous.size)))
                {
                    return false;
                }

                RefreshAttributeVector cleared {};
                return SafeReadValue(list_vector_address, cleared) &&
                    cleared.size == 0;
            };

        RefreshAttributeVector static_previous {};
        RefreshAttributeVector dynamic_previous {};
        if (!clear_attribute_list(offsets.item_view_attribute_list, static_previous) ||
            !clear_attribute_list(offsets.item_view_dynamic_attribute_list, dynamic_previous))
        {
            return false;
        }

        auto* static_vector_address =
            reinterpret_cast<std::uint8_t*>(item_view) +
            offsets.item_view_attribute_list + offsets.attribute_list_attributes;
        if (!TryInvokeNetworkVectorOperation(
                offsets.attribute_list_attributes_operation,
                4,
                static_vector_address,
                0,
                1))
        {
            return false;
        }

        RefreshAttributeVector vanilla_trigger_vector {};
        if (!SafeReadValue(static_vector_address, vanilla_trigger_vector) ||
            vanilla_trigger_vector.size != 1 || vanilla_trigger_vector.ptr == 0)
        {
            return false;
        }

        auto* vanilla_trigger_record =
            reinterpret_cast<void*>(vanilla_trigger_vector.ptr);
        std::uintptr_t vanilla_trigger_vtable = 0;
        std::uintptr_t vanilla_trigger_owner = 0;
        if (!TryInvokeNetworkVectorElementMutation(
                offsets.attribute_list_attributes_operation,
                static_vector_address,
                0,
                vanilla_trigger_record) ||
            !SafeReadValue(vanilla_trigger_record, vanilla_trigger_vtable) ||
            vanilla_trigger_vtable == 0 ||
            !SafeReadField(
                vanilla_trigger_record,
                sizeof(std::uintptr_t),
                vanilla_trigger_owner) ||
            vanilla_trigger_owner == 0 ||
            !SafeWriteField(
                vanilla_trigger_record,
                offsets.econ_item_attribute_definition_index,
                kAttributePaintKit) ||
            !SafeWriteField(
                vanilla_trigger_record,
                offsets.econ_item_attribute_value,
                0.0f) ||
            (offsets.econ_item_attribute_initial_value != 0 &&
                !SafeWriteField(
                    vanilla_trigger_record,
                    offsets.econ_item_attribute_initial_value,
                    0.0f)))
        {
            TryInvokeNetworkVectorOperation(
                offsets.attribute_list_attributes_operation,
                5,
                static_vector_address,
                0,
                1);
            return false;
        }

        float vanilla_paint_readback = -1.0f;
        if (!TryReadAttributeValue(
                item_view,
                offsets,
                kAttributePaintKit,
                vanilla_paint_readback) ||
            vanilla_paint_readback != 0.0f)
        {
            TryInvokeNetworkVectorOperation(
                offsets.attribute_list_attributes_operation,
                5,
                static_vector_address,
                0,
                1);
            return false;
        }

        const auto diagnostic_signature =
            BuildProfileApplySignature(profile, profile.xuid, profile.base_item, 0x56414E434C454152ull);
        std::wstringstream stream;
        stream << L"Explicit vanilla knife cleared stale attribute lists through Schema operations"
            << L": static_previous_count=" << static_previous.size
            << L", dynamic_previous_count=" << dynamic_previous.size
            << L", static_current_count=1"
            << L", dynamic_current_count=0"
            << L", paint_zero_trigger_verified=1"
            << L", element_mutation_notified=1"
            << L", engine_record_identity_preserved=1"
            << L", element_size=" << attribute_stride << L".";
        LogProfileDiagnosticOnce(diagnostic_signature, stream.str());

        attachment.item_view = item_view;
        attachment.uses_explicit_vanilla_paint_zero_trigger = true;
        return true;
    }

    std::vector<AttributeStorageRecord> records;
    records.reserve(64);
    if (!CollectAttributeStorageRecordsFromList(
            item_view,
            offsets.item_view_attribute_list,
            offsets,
            attribute_stride,
            records) ||
        !CollectAttributeStorageRecordsFromList(
            item_view,
            offsets.item_view_dynamic_attribute_list,
            offsets,
            attribute_stride,
            records))
    {
        return false;
    }

    for (const auto& [definition_index, value] : attributes)
    {
        auto* record = FindAttributeStorageRecord(records, definition_index);
        if (record == nullptr)
        {
            AttributeStorageRecord new_record {};
            new_record.definition_index = definition_index;
            new_record.bytes.resize(attribute_stride, 0);
            records.push_back(std::move(new_record));
            record = &records.back();
        }

        if (!SafeWriteField(record->bytes.data(), offsets.econ_item_attribute_definition_index, definition_index) ||
            !SafeWriteField(record->bytes.data(), offsets.econ_item_attribute_value, value))
        {
            return false;
        }

        if (offsets.econ_item_attribute_initial_value != 0 &&
            !SafeWriteField(record->bytes.data(), offsets.econ_item_attribute_initial_value, value))
        {
            return false;
        }
    }

    if (records.empty())
    {
        return false;
    }

    void* vector_address =
        reinterpret_cast<std::uint8_t*>(item_view) + offsets.item_view_attribute_list + offsets.attribute_list_attributes;
    RefreshAttributeVector original {};
    auto original_read = SafeReadValue(vector_address, original);

    // A stock knife often has no paint record in the static attribute list,
    // while its dynamic list still owns seed/wear slots.  For an explicit
    // vanilla request, borrow one of those existing slots for the material
    // refresh. The overlay is retained for the entity lifetime because current
    // CS2 consumes it after the helper returns; it still neither grows nor
    // replaces Source 2's vector.
    if (IsExplicitVanillaKnifeFinishProfile(profile) &&
        (!original_read || original.ptr == 0 || original.size < attributes.size()) &&
        offsets.item_view_dynamic_attribute_list != 0)
    {
        auto* dynamic_vector_address =
            reinterpret_cast<std::uint8_t*>(item_view) +
            offsets.item_view_dynamic_attribute_list +
            offsets.attribute_list_attributes;
        RefreshAttributeVector dynamic_original {};
        if (SafeReadValue(dynamic_vector_address, dynamic_original) &&
            dynamic_original.ptr != 0 &&
            dynamic_original.size >= attributes.size())
        {
            vector_address = dynamic_vector_address;
            original = dynamic_original;
            original_read = true;
            attachment.uses_dynamic_attribute_list = true;
        }
    }

    if (!original_read)
    {
        return false;
    }

    constexpr std::uint64_t kMaxReasonableRefreshAttributeCount = 128;
    if (original.size > kMaxReasonableRefreshAttributeCount ||
        (original.size != 0 && original.ptr == 0))
    {
        return false;
    }

    // Never grow a live CS2 econ-attribute vector. Even the reflected Schema
    // operation updates allocator/index side data that is consumed later by
    // the material system. Standard weapons use fallback scalar fields plus
    // native visuals invalidation instead.

    // For any explicit vanilla request, restoring the pre-existing custom
    // material after precache is exactly what must not happen: paint=0 asks
    // CS2 to drop that material. Positive finishes retain the reference
    // helper's original flag behavior.
    if (!profile.explicit_vanilla_finish &&
        offsets.item_view_restore_custom_material_after_precache != 0)
    {
        bool restore_custom_material = false;
        if (SafeReadField(
                item_view,
                offsets.item_view_restore_custom_material_after_precache,
                restore_custom_material))
        {
            attachment.restore_custom_material_original = restore_custom_material;
            if (!restore_custom_material)
            {
                attachment.restore_custom_material_written =
                    SafeWriteField(item_view, offsets.item_view_restore_custom_material_after_precache, true);
            }
        }
    }

    attachment.item_view = item_view;
    attachment.vector_address = vector_address;
    attachment.original = original;
    attachment.replaced_existing_vector = original.size != 0 || original.ptr != 0;

    // Standard-weapon material generation is deferred beyond the refresh
    // helper call, so its paint attributes must remain visible.  Publishing a
    // VirtualAlloc-backed CUtlVector is unsafe across demo seeks because CS2
    // can destroy the entity before we observe the tick discontinuity.  Reuse
    // the entity-owned records instead; their allocator ownership then remains
    // intact when the demo tears the entity down.
    if ((UsesTemporaryWorldWeaponRefreshModel(profile) ||
            IsExplicitVanillaKnifeFinishProfile(profile)) &&
        original.ptr != 0 &&
        original.size >= attributes.size())
    {
        const auto byte_count = static_cast<std::size_t>(original.size) * attribute_stride;
        attachment.in_place_original_bytes.resize(byte_count);
        if (!SafeReadBytes(
                reinterpret_cast<const void*>(original.ptr),
                attachment.in_place_original_bytes.data(),
                byte_count))
        {
            attachment = {};
            return false;
        }

        attachment.in_place_installed_bytes = attachment.in_place_original_bytes;
        std::vector<bool> used_slots(static_cast<std::size_t>(original.size), false);
        for (const auto& [definition_index, value] : attributes)
        {
            std::size_t selected_slot = static_cast<std::size_t>(original.size);
            for (std::size_t slot = 0; slot < static_cast<std::size_t>(original.size); ++slot)
            {
                if (used_slots[slot])
                {
                    continue;
                }

                std::uint16_t existing_definition_index = 0;
                if (SafeReadField(
                        attachment.in_place_installed_bytes.data() + slot * attribute_stride,
                        offsets.econ_item_attribute_definition_index,
                        existing_definition_index) &&
                    existing_definition_index == definition_index)
                {
                    selected_slot = slot;
                    break;
                }
            }

            if (selected_slot == static_cast<std::size_t>(original.size))
            {
                const auto free_slot = std::find(used_slots.begin(), used_slots.end(), false);
                if (free_slot == used_slots.end())
                {
                    attachment = {};
                    return false;
                }
                selected_slot = static_cast<std::size_t>(std::distance(used_slots.begin(), free_slot));
            }

            auto* record = attachment.in_place_installed_bytes.data() + selected_slot * attribute_stride;
            if (!SafeWriteField(record, offsets.econ_item_attribute_definition_index, definition_index) ||
                !SafeWriteField(record, offsets.econ_item_attribute_value, value) ||
                (offsets.econ_item_attribute_initial_value != 0 &&
                    !SafeWriteField(record, offsets.econ_item_attribute_initial_value, value)))
            {
                attachment = {};
                return false;
            }
            used_slots[selected_slot] = true;
        }

        attachment.in_place_address = reinterpret_cast<void*>(original.ptr);
        attachment.replaced_existing_vector = false;
        if (!SafeWriteBytes(
                attachment.in_place_address,
                attachment.in_place_installed_bytes.data(),
                attachment.in_place_installed_bytes.size()))
        {
            attachment = {};
            return false;
        }
        return true;
    }

    // The current attribute container is 24 bytes (count, data, capacity and
    // allocator flags). Publishing a VirtualAlloc block through its 16-byte
    // prefix corrupts the deferred destructor. In-place overlays above remain
    // allowed; external temporary storage is fail-closed.
    return false;

#if 0
    attachment.allocated_size = records.size() * attribute_stride;
    attachment.allocated_block = VirtualAlloc(nullptr, attachment.allocated_size, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (attachment.allocated_block == nullptr)
    {
        attachment = {};
        return false;
    }

    auto* destination = reinterpret_cast<std::uint8_t*>(attachment.allocated_block);
    for (std::size_t index = 0; index < records.size(); ++index)
    {
        std::memcpy(
            destination + index * attribute_stride,
            records[index].bytes.data(),
            records[index].bytes.size());
    }

    const RefreshAttributeVector refreshed_view {
        static_cast<std::uint64_t>(records.size()),
        reinterpret_cast<std::uintptr_t>(attachment.allocated_block),
    };
    if (!SafeWriteValue(attachment.vector_address, refreshed_view))
    {
        VirtualFree(attachment.allocated_block, 0, MEM_RELEASE);
        attachment = {};
        return false;
    }

    return true;
#endif
}

void RestoreTemporaryWeaponRefreshAttributes(TemporaryAttributeListAttachment& attachment)
{
    if (attachment.item_view != nullptr &&
        attachment.restore_custom_material_written &&
        g_hook_state.schema_offsets.item_view_restore_custom_material_after_precache != 0)
    {
        SafeWriteField(
            attachment.item_view,
            g_hook_state.schema_offsets.item_view_restore_custom_material_after_precache,
            attachment.restore_custom_material_original);
    }

    if (attachment.in_place_address != nullptr &&
        !attachment.in_place_original_bytes.empty() &&
        attachment.in_place_original_bytes.size() == attachment.in_place_installed_bytes.size())
    {
        std::vector<std::uint8_t> current(attachment.in_place_installed_bytes.size());
        if (SafeReadBytes(attachment.in_place_address, current.data(), current.size()) &&
            current == attachment.in_place_installed_bytes)
        {
            SafeWriteBytes(
                attachment.in_place_address,
                attachment.in_place_original_bytes.data(),
                attachment.in_place_original_bytes.size());
        }
    }
    else if (attachment.vector_address != nullptr)
    {
        SafeWriteValue(attachment.vector_address, attachment.original);
    }

    if (attachment.allocated_block != nullptr)
    {
        VirtualFree(attachment.allocated_block, 0, MEM_RELEASE);
    }

    attachment = {};
}

void LogLiveKnifeMaterialOwners(
    const WeaponSkinRefreshBinding& binding,
    const ClientSchemaOffsets& offsets,
    const wchar_t* phase,
    const std::uint64_t signature)
{
    if (!binding.instruction_window_valid ||
        binding.original_offset == 0 ||
        binding.original_companion_offset == 0 ||
        phase == nullptr)
    {
        return;
    }

    auto* entity_list = g_hook_state.runtime_entities.last_entity_list;
    const auto highest_entity_index = std::max(
        g_hook_state.highest_live_entity_index.load(),
        g_hook_state.runtime_entities.highest_live_entity_index);
    if (entity_list == nullptr || highest_entity_index < 0)
    {
        return;
    }

    std::vector<std::wstring> owners;
    owners.reserve(24);
    int scanned = 0;
    int positive_material_count_entities = 0;
    constexpr std::size_t kMaximumLoggedOwners = 48;
    for (int entity_index = 0; entity_index <= highest_entity_index; ++entity_index)
    {
        void* entity = nullptr;
        if (!TryGetEntityFromIndex(entity_list, entity_index, entity) || entity == nullptr)
        {
            continue;
        }
        ++scanned;

        std::int32_t primary_count = -1;
        std::int32_t companion_count = -1;
        const auto primary_read = SafeReadField(
            entity,
            binding.original_offset,
            primary_count);
        const auto companion_read = SafeReadField(
            entity,
            binding.original_companion_offset,
            companion_count);
        const auto plausible_primary = primary_read && primary_count >= 0 && primary_count <= 128;
        const auto plausible_companion = companion_read && companion_count >= 0 && companion_count <= 128;
        const auto has_materials =
            (plausible_primary && primary_count > 0) ||
            (plausible_companion && companion_count > 0);
        if (has_materials)
        {
            ++positive_material_count_entities;
        }

        RefreshAttributeVector primary_vector {};
        const auto primary_vector_read =
            plausible_primary &&
            SafeReadValue(
                reinterpret_cast<std::uint8_t*>(entity) + binding.original_offset,
                primary_vector) &&
            primary_vector.size == static_cast<std::uint64_t>(primary_count) &&
            (primary_vector.size == 0 || primary_vector.ptr != 0);
        std::uint64_t primary_record_hash = 0;
        bool primary_record_hash_valid = false;
        std::array<std::uint64_t, 4> primary_record_head {};
        if (primary_vector_read &&
            primary_vector.size > 0 &&
            primary_vector.ptr != 0 &&
            offsets.item_view_composite_materials_element_size >= sizeof(primary_record_head) &&
            offsets.item_view_composite_materials_element_size <= 0x1000)
        {
            std::vector<std::uint8_t> record_bytes(
                offsets.item_view_composite_materials_element_size);
            if (SafeReadBytes(
                    reinterpret_cast<const void*>(primary_vector.ptr),
                    record_bytes.data(),
                    record_bytes.size()))
            {
                primary_record_hash = HashFlattenedIdentity(
                    std::string(
                        reinterpret_cast<const char*>(record_bytes.data()),
                        record_bytes.size()));
                std::memcpy(
                    primary_record_head.data(),
                    record_bytes.data(),
                    sizeof(primary_record_head));
                primary_record_hash_valid = true;
            }
        }

        const auto rtti = BuildRuntimeEntityRttiDescriptor(entity);
        const auto viewmodel_like = rtti.find(L"ViewModel") != std::wstring::npos;
        const auto knife_like = rtti.find(L"Knife") != std::wstring::npos;
        std::string model_name;
        const auto model_name_read = TryReadEntityModelNameString(entity, offsets, model_name);
        auto normalized_model_name = model_name;
        std::transform(
            normalized_model_name.begin(),
            normalized_model_name.end(),
            normalized_model_name.begin(),
            [](const unsigned char value)
            {
                return static_cast<char>(std::tolower(value));
            });
        const auto knife_model =
            model_name_read && normalized_model_name.find("knife") != std::string::npos;
        if (!has_materials && !viewmodel_like && !knife_like && !knife_model)
        {
            continue;
        }

        if (owners.size() >= kMaximumLoggedOwners)
        {
            continue;
        }

        std::uint32_t owner_handle = kInvalidEntityHandle;
        if (offsets.base_owner_entity != 0)
        {
            SafeReadField(entity, offsets.base_owner_entity, owner_handle);
        }
        std::uint32_t viewmodel_weapon_handle = kInvalidEntityHandle;
        if (viewmodel_like && offsets.viewmodel_weapon != 0)
        {
            SafeReadField(entity, offsets.viewmodel_weapon, viewmodel_weapon_handle);
        }
        std::uintptr_t model_state = 0;
        const auto model_state_read =
            TryResolveEntityModelStateAddress(entity, offsets, model_state) && model_state != 0;

        int definition_index = 0;
        auto* item_view = ResolveWeaponItemView(entity, offsets);
        const auto definition_read =
            item_view != nullptr &&
            offsets.item_view_definition_index != 0 &&
            SafeReadField(item_view, offsets.item_view_definition_index, definition_index) &&
            definition_index >= 0 && definition_index <= 10000;

        std::wstringstream owner;
        owner << L"entity=" << entity_index
            << L", ptr=" << FormatPointer(entity)
            << L", primary="
            << (plausible_primary ? std::to_wstring(primary_count) : L"?")
            << L", companion="
            << (plausible_companion ? std::to_wstring(companion_count) : L"?")
            << L", primary_ptr="
            << (primary_vector_read
                    ? FormatPointer(reinterpret_cast<void*>(primary_vector.ptr))
                    : L"?")
            << L", primary_record_hash=";
        if (primary_record_hash_valid)
        {
            owner << L"0x" << std::hex << std::uppercase << primary_record_hash
                << L", primary_record_head={0x" << primary_record_head[0]
                << L",0x" << primary_record_head[1]
                << L",0x" << primary_record_head[2]
                << L",0x" << primary_record_head[3]
                << L"}" << std::dec << std::nouppercase;
        }
        else
        {
            owner << L"?";
        }
        owner
            << L", definition="
            << (definition_read ? std::to_wstring(definition_index) : L"?")
            << L", owner=" << HandleToEntityIndex(owner_handle)
            << L", viewmodel_weapon=" << HandleToEntityIndex(viewmodel_weapon_handle)
            << L", model_state="
            << (model_state_read
                    ? FormatPointer(reinterpret_cast<void*>(model_state))
                    : L"0x0")
            << L", model="
            << (model_name_read ? NarrowToWide(model_name) : L"<unreadable>")
            << L", " << rtti;
        owners.push_back(owner.str());
    }

    std::wstringstream stream;
    stream << L"Live knife/viewmodel composite-material owner scan [" << phase << L"]"
        << L": scanned=" << scanned
        << L", positive_count_entities=" << positive_material_count_entities
        << L", logged=" << owners.size()
        << L", native_offsets=0x" << std::hex << std::uppercase
        << binding.original_offset << L"/0x" << binding.original_companion_offset
        << std::dec << std::nouppercase << L", owners=";
    if (owners.empty())
    {
        stream << L"<none>";
    }
    else
    {
        for (std::size_t index = 0; index < owners.size(); ++index)
        {
            if (index != 0)
            {
                stream << L" | ";
            }
            stream << owners[index];
        }
    }
    LogProfileDiagnosticOnce(
        signature ^
            (std::wcscmp(phase, L"before") == 0
                    ? 0x4D41544245464F52ull
                    : 0x4D41544146544552ull),
        stream.str());
}

void LogKnifeRefreshGeneratorState(
    const PendingWeaponRefreshRequest& request,
    const ClientSchemaOffsets& offsets,
    const wchar_t* phase)
{
    if (request.econ_entity == nullptr || phase == nullptr ||
        offsets.weapon_visuals_data_set < 0xA1 ||
        offsets.weapon_custom_econ_reload_event_id == 0)
    {
        return;
    }

    constexpr std::size_t kPrivateVisualPayloadSize = 0xA1;
    const auto private_visual_payload_offset =
        offsets.weapon_visuals_data_set -
        static_cast<std::ptrdiff_t>(kPrivateVisualPayloadSize);
    std::array<std::uint8_t, kPrivateVisualPayloadSize> private_visual_payload {};
    const auto payload_read = SafeReadBytes(
        reinterpret_cast<const std::uint8_t*>(request.econ_entity) +
            private_visual_payload_offset,
        private_visual_payload.data(),
        private_visual_payload.size());

    std::uint64_t payload_hash = 0;
    if (payload_read)
    {
        payload_hash = HashFlattenedIdentity(std::string(
            reinterpret_cast<const char*>(private_visual_payload.data()),
            private_visual_payload.size()));
    }

    const auto read_payload_u64 =
        [&](const std::size_t relative_offset, std::uint64_t& value)
        {
            if (!payload_read ||
                relative_offset + sizeof(value) > private_visual_payload.size())
            {
                return false;
            }
            std::memcpy(
                &value,
                private_visual_payload.data() + relative_offset,
                sizeof(value));
            return true;
        };

    std::array<std::uint64_t, 7> payload_words {};
    constexpr std::array<std::size_t, 7> kPayloadWordOffsets {
        0x00, 0x18, 0x20, 0x50, 0x68, 0x70, 0x78,
    };
    std::array<bool, kPayloadWordOffsets.size()> payload_word_read {};
    for (std::size_t index = 0; index < kPayloadWordOffsets.size(); ++index)
    {
        payload_word_read[index] =
            read_payload_u64(kPayloadWordOffsets[index], payload_words[index]);
    }

    bool clear_weapon_identifying_ugc = false;
    bool visuals_data_set = false;
    std::int32_t reload_event_id = 0;
    const auto clear_ugc_read =
        offsets.weapon_clear_weapon_identifying_ugc != 0 &&
        SafeReadField(
            request.econ_entity,
            offsets.weapon_clear_weapon_identifying_ugc,
            clear_weapon_identifying_ugc);
    const auto visuals_read = SafeReadField(
        request.econ_entity,
        offsets.weapon_visuals_data_set,
        visuals_data_set);
    const auto reload_event_read = SafeReadField(
        request.econ_entity,
        offsets.weapon_custom_econ_reload_event_id,
        reload_event_id);

    auto* item_view = request.refresh_item_view != nullptr
        ? request.refresh_item_view
        : request.item_view;
    const auto attribute_stride = ResolveEconItemAttributeStride(offsets);
    const auto describe_attribute_list =
        [&](const std::ptrdiff_t list_offset)
        {
            std::wstringstream list_stream;
            if (item_view == nullptr || list_offset == 0 ||
                offsets.attribute_list_attributes == 0 || attribute_stride == 0)
            {
                list_stream << L"<unavailable>";
                return list_stream.str();
            }

            auto* vector_address =
                reinterpret_cast<std::uint8_t*>(item_view) +
                list_offset + offsets.attribute_list_attributes;
            NetworkVectorView vector_view {};
            if (!TryReadNetworkVectorView(vector_address, vector_view) ||
                vector_view.size > 128 ||
                (vector_view.size != 0 && vector_view.data == nullptr))
            {
                list_stream << L"<unreadable>";
                return list_stream.str();
            }

            list_stream << L"count=" << vector_view.size
                << L", data=" << FormatPointer(vector_view.data)
                << L", records={";
            const auto logged_count = std::min<std::uint64_t>(vector_view.size, 32);
            for (std::uint64_t index = 0; index < logged_count; ++index)
            {
                if (index != 0)
                {
                    list_stream << L"; ";
                }

                auto* attribute = vector_view.data +
                    static_cast<std::size_t>(index) * attribute_stride;
                std::uintptr_t vtable = 0;
                std::uintptr_t owner = 0;
                std::uint16_t definition_index = 0;
                float value = 0.0f;
                float initial_value = 0.0f;
                const auto record_read =
                    SafeReadValue(attribute, vtable) &&
                    SafeReadField(attribute, sizeof(std::uintptr_t), owner) &&
                    SafeReadField(
                        attribute,
                        offsets.econ_item_attribute_definition_index,
                        definition_index) &&
                    SafeReadField(
                        attribute,
                        offsets.econ_item_attribute_value,
                        value);
                const auto initial_read =
                    offsets.econ_item_attribute_initial_value != 0 &&
                    SafeReadField(
                        attribute,
                        offsets.econ_item_attribute_initial_value,
                        initial_value);
                if (!record_read)
                {
                    list_stream << L"#" << index << L"=<unreadable>";
                    continue;
                }

                list_stream << L"#" << index
                    << L"(def=" << definition_index
                    << L", value=" << value
                    << L", initial=";
                if (initial_read)
                {
                    list_stream << initial_value;
                }
                else
                {
                    list_stream << L"?";
                }
                list_stream << L", vtable="
                    << FormatPointer(reinterpret_cast<void*>(vtable))
                    << L", owner="
                    << FormatPointer(reinterpret_cast<void*>(owner)) << L")";
            }
            if (logged_count != vector_view.size)
            {
                list_stream << L"; ...";
            }
            list_stream << L"}";
            return list_stream.str();
        };

    std::wstringstream stream;
    stream << L"Knife refresh generator state [" << phase << L"]"
        << L": entity=" << request.entity_index
        << L", econ=" << FormatPointer(request.econ_entity)
        << L", item_view=" << FormatPointer(item_view)
        << L", payload_offset=0x" << std::hex << std::uppercase
        << private_visual_payload_offset
        << L", payload_hash=0x" << payload_hash
        << std::dec << std::nouppercase
        << L", payload_read=" << (payload_read ? 1 : 0)
        << L", payload_words={";
    for (std::size_t index = 0; index < kPayloadWordOffsets.size(); ++index)
    {
        if (index != 0)
        {
            stream << L", ";
        }
        stream << L"+0x" << std::hex << std::uppercase
            << kPayloadWordOffsets[index] << L"=";
        if (payload_word_read[index])
        {
            stream << L"0x" << payload_words[index];
        }
        else
        {
            stream << L"?";
        }
        stream << std::dec << std::nouppercase;
    }
    stream << L"}"
        << L", clear_weapon_identifying_ugc="
        << (clear_ugc_read
                ? std::to_wstring(clear_weapon_identifying_ugc ? 1 : 0)
                : L"?")
        << L", visuals_data_set="
        << (visuals_read ? std::to_wstring(visuals_data_set ? 1 : 0) : L"?")
        << L", reload_event="
        << (reload_event_read ? std::to_wstring(reload_event_id) : L"?")
        << L", static_attributes=["
        << describe_attribute_list(offsets.item_view_attribute_list)
        << L"], dynamic_attributes=["
        << describe_attribute_list(offsets.item_view_dynamic_attribute_list)
        << L"].";

    const auto phase_tag = std::wcscmp(phase, L"before") == 0
        ? 0x47454E4245464F52ull
        : 0x47454E4146544552ull;
    LogProfileDiagnosticOnce(request.desired_signature ^ phase_tag, stream.str());
}

bool TryProcessPendingWeaponRefreshRequests(
    const ClientSchemaOffsets& offsets,
    std::vector<PendingWeaponRefreshRequest>& requests)
{
    if (requests.empty())
    {
        return false;
    }

    std::vector<TemporaryAttributeListAttachment> attachments;
    attachments.reserve(requests.size());
    std::unordered_set<void*> scheduled_item_views;
    scheduled_item_views.reserve(requests.size());

    std::vector<PendingWeaponRefreshRequest> candidate_requests;
    candidate_requests.reserve(requests.size());
    std::unordered_set<void*> promoted_item_views;
    promoted_item_views.reserve(requests.size());
    const nskinzcs2::model::CosmeticProfile* watched_knife_profile = nullptr;
    int watched_knife_candidate_count = 0;
    const auto knife_refresh_policy = g_hook_state.knife_refresh_helper_policy.load();
    const auto knife_epoch_armed = KnifeRefreshHelperEpochArmed();
    bool suppressed_knife_request = false;
    bool dispatched_knife_request = false;
    std::size_t completed_request_count = 0;

    for (const auto& request : requests)
    {
        const auto is_material_target = IsMaterialRefreshTarget(request.target);
        const auto* keychain_profile =
            request.keychain_profile.has_value() ? &*request.keychain_profile : nullptr;
        const auto keychain_only_request =
            IsKeychainOnlyApplyRequest(request.profile, keychain_profile);
        const auto needs_skin_refresh = NeedsWeaponSkinRefresh(request.profile, keychain_profile);
        const auto trace_watched_knife = ShouldTraceWatchedKnifeDiagnostic(request.profile);
        const auto knife_request = IsKnifeProfile(request.profile);
        const auto standard_weapon_request = UsesTemporaryWorldWeaponRefreshModel(request.profile);
        const auto promote_refresh_attachment =
            ShouldPromoteWeaponRefreshAttachmentToRuntimeOwned(request.profile, keychain_profile);
        const auto restore_promoted_refresh_attachment_on_abandon =
            ShouldRestorePromotedWeaponRefreshAttachmentOnAbandon(request.profile, keychain_profile);
        void* effective_refresh_item_view =
            request.refresh_item_view != nullptr ? request.refresh_item_view : request.item_view;
        if (trace_watched_knife)
        {
            std::wstringstream stream;
            stream << L"Refresh request inspect: entity=" << request.entity_index
                << L", econ=" << FormatPointer(request.econ_entity)
                << L", item_view=" << FormatPointer(request.item_view)
                << L", refresh_item_view=" << FormatPointer(effective_refresh_item_view)
                << L", target=" << WeaponSkinRefreshTargetText(request.target)
                << L", material_target=" << (is_material_target ? 1 : 0)
                << L", refresh_item_view_present=" << (effective_refresh_item_view != nullptr ? 1 : 0)
                << L", needs_refresh=" << (needs_skin_refresh ? 1 : 0);
            TraceWatchedKnifeDiagnostic(request.profile, stream.str());
        }

        if (keychain_only_request)
        {
            const auto diagnostic_signature = request.desired_signature ^ 0x7324ull;
            std::wstringstream stream;
            stream << L"Skipped refresh helper dispatch for keychain-only weapon request on entity "
                << request.entity_index << L".";
            LogProfileDiagnosticOnce(diagnostic_signature, stream.str());
            continue;
        }

        const auto missing_refresh_prerequisites =
            !is_material_target || effective_refresh_item_view == nullptr;
        if (missing_refresh_prerequisites ||
            (!needs_skin_refresh && !request.force_dispatch))
        {
            if (trace_watched_knife)
            {
                std::wstringstream stream;
                stream << L"Refresh request skipped before candidate queue: entity=" << request.entity_index
                    << L", target=" << WeaponSkinRefreshTargetText(request.target)
                    << L", reason="
                    << (!is_material_target
                            ? L"target_does_not_trigger_material_refresh"
                            : (effective_refresh_item_view == nullptr
                                   ? L"refresh_item_view_missing"
                                   : (request.force_dispatch
                                          ? L"force_dispatch"
                                          : L"profile_does_not_need_refresh")));
                TraceWatchedKnifeDiagnostic(request.profile, stream.str());
            }
            if (missing_refresh_prerequisites || !request.force_dispatch)
            {
                continue;
            }
        }

        const auto desired_refresh_attributes =
            BuildWeaponRefreshAttributesImpl(request.profile, keychain_profile);
        if (standard_weapon_request && !VerifyStandardWeaponAttributes(
                effective_refresh_item_view, offsets, desired_refresh_attributes))
        {
            LogProfileDiagnosticOnce(request.desired_signature ^ 0x535444434F4E464Cull,
                L"Standard-weapon material refresh rejected: existing attribute slots conflict with the requested appearance.");
            continue;
        }
        const auto live_attribute_values_match =
            !desired_refresh_attributes.empty() &&
            (knife_request
                ? VerifyKnifeFinishRefreshAttributeValues(
                      effective_refresh_item_view,
                      offsets,
                      request.profile,
                      keychain_profile)
                : VerifyAttributeValues(
                      effective_refresh_item_view,
                      offsets,
                      desired_refresh_attributes));
        const auto refresh_signature_matches =
            HasAppliedSignature(
                g_hook_state.refreshed_weapon_signatures,
                request.entity_index,
                request.desired_signature);
        if (refresh_signature_matches &&
            !nskinzcs2::runtime::ShouldQueueWeaponMaterialRefresh(
                needs_skin_refresh, true, request.force_dispatch))
        {
            ++completed_request_count;
            LogProfileDiagnosticOnce(request.desired_signature ^ 0x5245465245555345ull,
                L"Reused completed material refresh for the unchanged appearance; no native regeneration dispatched.");
            continue;
        }
        const auto verified_in_place_initialization_refresh =
            nskinzcs2::runtime::ShouldAllowVerifiedInPlaceKnifeInitializationRefresh(
                knife_request,
                needs_skin_refresh,
                live_attribute_values_match,
                refresh_signature_matches);
        const auto refresh_epoch_allows_dispatch =
            nskinzcs2::runtime::ShouldAllowWeaponRefreshHelperDispatch(
                knife_request,
                knife_refresh_policy,
                knife_epoch_armed);
        if (!refresh_epoch_allows_dispatch && !verified_in_place_initialization_refresh)
        {
            if (knife_request)
            {
                suppressed_knife_request = true;
                LogKnifeRefreshHelperSuppressed(request, effective_refresh_item_view);
            }
            continue;
        }

        if (verified_in_place_initialization_refresh && !refresh_epoch_allows_dispatch)
        {
            std::wstringstream stream;
            stream << L"Allowed one verified in-place knife initialization refresh: entity="
                << request.entity_index
                << L", paint=" << request.profile.paint_kit
                << L", signature=0x" << std::hex << request.desired_signature
                << std::dec << L". Repeated steady-state helper dispatch remains blocked.";
            LogProfileDiagnosticOnce(request.desired_signature ^ 0x494E495452454652ull, stream.str());
        }

        if (scheduled_item_views.find(effective_refresh_item_view) != scheduled_item_views.end())
        {
            if (promote_refresh_attachment)
            {
                promoted_item_views.insert(effective_refresh_item_view);
            }
            if (knife_request)
            {
                dispatched_knife_request = true;
            }

            if (trace_watched_knife)
            {
                if (watched_knife_profile == nullptr)
                {
                    watched_knife_profile = &request.profile;
                }
                ++watched_knife_candidate_count;

                std::wstringstream stream;
                stream << L"Refresh request re-used existing candidate item_view: entity=" << request.entity_index
                    << L", item_view=" << FormatPointer(request.item_view)
                    << L", refresh_item_view=" << FormatPointer(effective_refresh_item_view)
                    << L", target=" << WeaponSkinRefreshTargetText(request.target);
                TraceWatchedKnifeDiagnostic(request.profile, stream.str());
            }
            candidate_requests.push_back(request);
            continue;
        }

        if (UsesTemporaryWorldWeaponRefreshModel(request.profile))
        {
            const auto payload = BuildWeaponRefreshAttributesImpl(request.profile, keychain_profile);
            if (!payload.empty())
            {
                const auto diagnostic_signature = request.desired_signature ^ 0x7330ull;
                std::wstringstream stream;
                stream << L"Prepared in-place/fallback attribute payload for world weapon entity "
                    << request.entity_index << L": "
                    << DescribeWeaponRefreshAttributes(payload) << L".";
                LogProfileDiagnosticOnce(diagnostic_signature, stream.str());
            }
        }

        float live_paint_attribute = 0.0f;
        const auto live_paint_attribute_present =
            TryReadAttributeValue(
                effective_refresh_item_view,
                offsets,
                kAttributePaintKit,
                live_paint_attribute);
        const auto use_vanilla_temporary_refresh_overlay =
            nskinzcs2::runtime::ShouldUseKnifeVanillaTemporaryRefreshOverlay(
                knife_request,
                request.profile.explicit_vanilla_finish,
                live_paint_attribute_present);
        const auto dispatch_with_in_place_attributes =
            nskinzcs2::runtime::ShouldDispatchKnifeRefreshWithInPlaceAttributes(
                knife_request,
                needs_skin_refresh,
                live_attribute_values_match) &&
            !use_vanilla_temporary_refresh_overlay;

        if (knife_request && dispatch_with_in_place_attributes)
        {
            std::size_t notified_slot_count = 0;
            if (!TryNotifyAndRewriteWeaponRefreshAttributes(
                    effective_refresh_item_view,
                    offsets,
                    desired_refresh_attributes,
                    notified_slot_count))
            {
                std::wstringstream stream;
                stream << L"Knife refresh rejected because the current Schema mutable-element operation "
                    << L"could not notify every paint/seed/wear slot: entity="
                    << request.entity_index
                    << L", item_view=" << FormatPointer(effective_refresh_item_view)
                    << L", desired_count=" << desired_refresh_attributes.size()
                    << L", notified_slots=" << notified_slot_count << L".";
                LogProfileDiagnosticOnce(
                    request.desired_signature ^ 0x4E45544D55544154ull,
                    stream.str());
                continue;
            }

            std::wstringstream stream;
            stream << L"Knife refresh notified the attribute manager through Schema mutable-element access"
                << L": entity=" << request.entity_index
                << L", item_view=" << FormatPointer(effective_refresh_item_view)
                << L", desired_count=" << desired_refresh_attributes.size()
                << L", notified_slots=" << notified_slot_count << L".";
            LogProfileDiagnosticOnce(
                request.desired_signature ^ 0x4E45544D55544154ull,
                stream.str());

            std::uint64_t previous_static_attribute_count = 0;
            std::uint64_t current_static_attribute_count = 0;
            if (!TryEnsureKnifeRefreshStaticAttributeMirror(
                    effective_refresh_item_view,
                    offsets,
                    desired_refresh_attributes,
                    previous_static_attribute_count,
                    current_static_attribute_count))
            {
                std::wstringstream rejection_stream;
                rejection_stream
                    << L"Knife refresh rejected because an engine-owned static attribute mirror "
                    << L"could not be prepared for the reference helper gate: entity="
                    << request.entity_index
                    << L", item_view=" << FormatPointer(effective_refresh_item_view)
                    << L", previous_static_count=" << previous_static_attribute_count
                    << L", current_static_count=" << current_static_attribute_count
                    << L", desired_count=" << desired_refresh_attributes.size() << L".";
                LogProfileDiagnosticOnce(
                    request.desired_signature ^ 0x535441544D495246ull,
                    rejection_stream.str());
                continue;
            }

            std::wstringstream mirror_stream;
            mirror_stream
                << L"Knife refresh prepared an engine-owned static attribute mirror for the "
                << L"reference helper gate: entity=" << request.entity_index
                << L", item_view=" << FormatPointer(effective_refresh_item_view)
                << L", previous_static_count=" << previous_static_attribute_count
                << L", current_static_count=" << current_static_attribute_count
                << L", desired_count=" << desired_refresh_attributes.size()
                << L", external_vector_replacement=0.";
            LogProfileDiagnosticOnce(
                request.desired_signature ^ 0x535441544D495252ull,
                mirror_stream.str());
        }

        // The temporary-attribute path normally raises this flag while the
        // reference refresh helper rebuilds custom materials. Knife crash
        // protection deliberately reuses the entity-owned attribute vector,
        // so it bypassed that side effect and a zero paint value cleared the
        // HUD/econ state without replacing the previously cached blade
        // material. Mirror only the scoped flag write; do not replace or grow
        // the knife attribute vector.
        TemporaryAttributeListAttachment in_place_material_refresh_scope;
        if (dispatch_with_in_place_attributes &&
            offsets.item_view_restore_custom_material_after_precache != 0)
        {
            bool restore_custom_material = false;
            if (SafeReadField(
                    effective_refresh_item_view,
                    offsets.item_view_restore_custom_material_after_precache,
                    restore_custom_material))
            {
                in_place_material_refresh_scope.item_view = effective_refresh_item_view;
                in_place_material_refresh_scope.restore_custom_material_original = restore_custom_material;
                if (!restore_custom_material)
                {
                    in_place_material_refresh_scope.restore_custom_material_written =
                        SafeWriteField(
                            effective_refresh_item_view,
                            offsets.item_view_restore_custom_material_after_precache,
                            true);
                }
            }
        }

        TemporaryAttributeListAttachment attachment;
        const auto attached_refresh_attributes =
            (dispatch_with_in_place_attributes || standard_weapon_request)
                ? false
                : TryAttachTemporaryWeaponRefreshAttributes(
                      effective_refresh_item_view,
                      offsets,
                      request.profile,
                      attachment,
                      keychain_profile);
        if (!attached_refresh_attributes &&
            !dispatch_with_in_place_attributes &&
            needs_skin_refresh &&
            !standard_weapon_request)
        {
            if (UsesTemporaryWorldWeaponRefreshModel(request.profile))
            {
                RefreshAttributeVector observed_vector {};
                const auto vector_header_readable =
                    effective_refresh_item_view != nullptr &&
                    offsets.item_view_attribute_list != 0 &&
                    offsets.attribute_list_attributes != 0 &&
                    SafeReadValue(
                        reinterpret_cast<std::uint8_t*>(effective_refresh_item_view) +
                            offsets.item_view_attribute_list + offsets.attribute_list_attributes,
                        observed_vector);
                std::wstringstream stream;
                stream << L"Standard-weapon refresh attachment unavailable for entity "
                    << request.entity_index
                    << L": econ_attribute_size=" << offsets.econ_item_attribute_size
                    << L", vector_operation="
                    << FormatPointer(reinterpret_cast<void*>(offsets.attribute_list_attributes_operation))
                    << L", vector_element_size=" << offsets.attribute_list_attributes_element_size
                    << L", vector_schema_tail_span="
                    << offsets.attribute_list_attributes_schema_tail_span
                    << L", header_readable=" << (vector_header_readable ? 1 : 0)
                    << L", current_count=" << (vector_header_readable ? observed_vector.size : 0)
                    << L", current_data="
                    << FormatPointer(
                           vector_header_readable
                               ? reinterpret_cast<void*>(observed_vector.ptr)
                               : nullptr)
                    << L", required_count="
                    << BuildWeaponRefreshAttributesImpl(request.profile, keychain_profile).size()
                    << L".";
                LogProfileDiagnosticOnce(request.desired_signature ^ 0x7331ull, stream.str());
            }
            if (trace_watched_knife)
            {
                std::wstringstream stream;
                stream << L"Refresh request could not attach temporary attributes: entity=" << request.entity_index
                    << L", item_view=" << FormatPointer(request.item_view)
                    << L", refresh_item_view=" << FormatPointer(effective_refresh_item_view)
                    << L", target=" << WeaponSkinRefreshTargetText(request.target);
                TraceWatchedKnifeDiagnostic(request.profile, stream.str());
            }
            continue;
        }

        if (standard_weapon_request)
        {
            LogProfileDiagnosticOnce(
                request.desired_signature ^ 0x4E41545653544457ull,
                L"Standard-weapon refresh uses verified in-place attributes, fallback fields and the native material gate; "
                L"no CS2 attribute vector was grown, replaced, or retained.");
        }

        scheduled_item_views.insert(effective_refresh_item_view);
        if (promote_refresh_attachment && attached_refresh_attributes)
        {
            promoted_item_views.insert(effective_refresh_item_view);
        }
        if (knife_request)
        {
            dispatched_knife_request = true;
        }
        if (attached_refresh_attributes && attachment.replaced_existing_vector)
        {
            const auto diagnostic_signature = request.desired_signature ^ 0x7338ull;
            std::wstringstream stream;
            stream << L"Replacing existing attribute vector for world weapon entity "
                << request.entity_index << L" during refresh window (size="
                << attachment.original.size << L").";
            LogProfileDiagnosticOnce(diagnostic_signature, stream.str());
        }
        if (attached_refresh_attributes)
        {
            attachment.restore_on_abandon_when_promoted =
                restore_promoted_refresh_attachment_on_abandon;
            attachments.push_back(std::move(attachment));
        }
        else if (in_place_material_refresh_scope.restore_custom_material_written)
        {
            // The helper only queues the composite-material work.  Keep this
            // Schema flag raised until the runtime-owned binding is released;
            // restoring it when the helper returns races the later material
            // consumer and leaves the first-person knife bound to its old
            // composite material.
            in_place_material_refresh_scope.restore_on_abandon_when_promoted = false;
            promoted_item_views.insert(effective_refresh_item_view);
            attachments.push_back(std::move(in_place_material_refresh_scope));
        }
        candidate_requests.push_back(request);
        if (trace_watched_knife)
        {
            if (watched_knife_profile == nullptr)
            {
                watched_knife_profile = &request.profile;
            }
            ++watched_knife_candidate_count;

            std::wstringstream stream;
            stream << L"Refresh request queued for helper dispatch: entity=" << request.entity_index
                << L", econ=" << FormatPointer(request.econ_entity)
                << L", item_view=" << FormatPointer(request.item_view)
                << L", refresh_item_view=" << FormatPointer(effective_refresh_item_view)
                << L", target=" << WeaponSkinRefreshTargetText(request.target)
                << L", queued_candidates=" << candidate_requests.size();
            TraceWatchedKnifeDiagnostic(request.profile, stream.str());
        }
    }

    if (candidate_requests.empty())
    {
        g_hook_state.pending_knife_post_refresh_verification = {};
        return suppressed_knife_request || completed_request_count == requests.size();
    }

    if (!g_hook_state.weapon_skin_refresh_ready.load())
    {
        std::wstring issue;
        WeaponSkinRefreshBinding binding;
        if (!TryResolveWeaponSkinRefreshBinding(GetModuleHandleW(L"client.dll"), offsets, binding, issue))
        {
            for (auto& attachment : attachments)
            {
                RestoreTemporaryWeaponRefreshAttributes(attachment);
            }

            if (!issue.empty())
            {
                nskinzcs2::Logger::Warn(issue);
            }
            g_hook_state.pending_knife_post_refresh_verification = {};
            return false;
        }

        g_hook_state.weapon_skin_refresh = binding;
        g_hook_state.weapon_skin_refresh_ready.store(true);
        g_hook_state.weapon_skin_refresh_state.store(nskinzcs2::runtime::WeaponSkinRefreshState::Ready);

        std::wstringstream stream;
        stream << L"Resolved reference-style weapon refresh helper at "
            << FormatPointer(binding.function)
            << L" using the native composite-material gate at 0x"
            << std::hex << std::uppercase << binding.original_offset
            << L"; executable-code displacement patching is disabled.";
        nskinzcs2::Logger::Info(stream.str());
    }

    std::wstring refresh_issue;
    if (watched_knife_profile != nullptr)
    {
        std::wstringstream stream;
        stream << L"Dispatching refresh helper: candidate_count=" << candidate_requests.size()
            << L", watched_knife_candidates=" << watched_knife_candidate_count;
        TraceWatchedKnifeDiagnostic(*watched_knife_profile, stream.str());
    }
    const auto has_explicit_vanilla_pass =
        std::any_of(
            candidate_requests.begin(),
            candidate_requests.end(),
            [](const PendingWeaponRefreshRequest& request)
            {
                return IsExplicitVanillaKnifeFinishProfile(request.profile);
            });
    const auto has_vanilla_paint_zero_trigger =
        std::any_of(
            attachments.begin(),
            attachments.end(),
            [](const TemporaryAttributeListAttachment& attachment)
            {
                return attachment.uses_explicit_vanilla_paint_zero_trigger;
            });
    auto configure_native_material_binding =
        [](WeaponSkinRefreshBinding& binding)
        {
            binding.patched_offset = binding.original_offset;
            binding.offset_patched = false;
        };

    auto active_refresh_binding = g_hook_state.weapon_skin_refresh;
    configure_native_material_binding(active_refresh_binding);

    if (has_explicit_vanilla_pass)
    {
        for (const auto& request : candidate_requests)
        {
            if (!IsExplicitVanillaKnifeFinishProfile(request.profile) ||
                request.econ_entity == nullptr)
            {
                continue;
            }

            std::int32_t primary_material_count = -1;
            std::int32_t companion_material_count = -1;
            const auto primary_read = SafeReadField(
                request.econ_entity,
                g_hook_state.weapon_skin_refresh.original_offset,
                primary_material_count);
            const auto companion_read = SafeReadField(
                request.econ_entity,
                g_hook_state.weapon_skin_refresh.original_companion_offset,
                companion_material_count);

            std::wstringstream stream;
            stream << L"Explicit vanilla knife native composite-material gate for XUID "
                << request.profile.xuid
                << L": entity=" << request.entity_index
                << L", primary_offset=0x" << std::hex << std::uppercase
                << g_hook_state.weapon_skin_refresh.original_offset
                << L", companion_offset=0x"
                << g_hook_state.weapon_skin_refresh.original_companion_offset
                << std::dec << std::nouppercase
                << L", primary_count="
                << (primary_read ? std::to_wstring(primary_material_count) : L"<unreadable>")
                << L", companion_count="
                << (companion_read ? std::to_wstring(companion_material_count) : L"<unreadable>")
                << L", dispatch_mode="
                << (has_vanilla_paint_zero_trigger
                        ? L"native_with_engine_paint_zero_record"
                        : L"native_only")
                << L".";
            LogProfileDiagnosticOnce(
                request.desired_signature ^ 0x56414E4E41544956ull,
                stream.str());
        }
    }

    const auto diagnostic_knife_request = std::find_if(
        candidate_requests.begin(),
        candidate_requests.end(),
        [](const PendingWeaponRefreshRequest& request)
        {
            return IsKnifeProfile(request.profile);
        });
    const auto trace_material_owners = diagnostic_knife_request != candidate_requests.end() &&
        ShouldTraceWatchedKnifeDiagnostic(diagnostic_knife_request->profile);
    if (trace_material_owners)
    {
        LogKnifeRefreshGeneratorState(
            *diagnostic_knife_request,
            offsets,
            L"before");
        LogLiveKnifeMaterialOwners(
            g_hook_state.weapon_skin_refresh,
            offsets,
            L"before",
            diagnostic_knife_request->desired_signature ^ 0x4D41544F574E4552ull);
    }

    // C_CSWeaponBase::m_bVisualsDataSet is the formal cache-valid bit for the
    // private material-generation payload at +0x1848..+0x18E8.  The v0.2.0
    // helper clears the render custom-material vectors, but current CS2 will
    // rebuild the same cached payload unless this bit and its reload epoch are
    // invalidated before the helper runs. Do this for every accepted weapon
    // request so standard finishes also rebuild without an attribute-vector
    // gate patch.
    bool weapon_visuals_invalidation_failed = false;
    bool knife_generator_payload_reset_failed = false;
    for (const auto& request : candidate_requests)
    {
        weapon_visuals_invalidation_failed =
            !TryInvalidateWeaponVisualsData(
                request.entity_index,
                request.econ_entity,
                offsets,
                request.desired_signature,
                request.profile.xuid) ||
            weapon_visuals_invalidation_failed;

        if (IsExplicitVanillaKnifeFinishProfile(request.profile))
        {
            knife_generator_payload_reset_failed =
                !TryResetExplicitVanillaKnifeGeneratorPayload(request, offsets) ||
                knife_generator_payload_reset_failed;
        }

        auto* refresh_item_view =
            request.refresh_item_view != nullptr
                ? request.refresh_item_view
                : request.item_view;
        if (IsExplicitVanillaKnifeFinishProfile(request.profile) &&
            refresh_item_view != nullptr &&
            offsets.item_view_restore_custom_material_after_precache != 0)
        {
            bool before_restore_custom_material = false;
            bool after_restore_custom_material = true;
            const auto before_read = SafeReadField(
                refresh_item_view,
                offsets.item_view_restore_custom_material_after_precache,
                before_restore_custom_material);
            const auto written = before_read && SafeWriteField(
                refresh_item_view,
                offsets.item_view_restore_custom_material_after_precache,
                false);
            const auto verified = written && SafeReadField(
                refresh_item_view,
                offsets.item_view_restore_custom_material_after_precache,
                after_restore_custom_material) &&
                !after_restore_custom_material;

            std::wstringstream stream;
            stream << L"Knife refresh disabled stale custom-material restore for XUID "
                << request.profile.xuid
                << L": entity=" << request.entity_index
                << L", item_view=" << FormatPointer(refresh_item_view)
                << L", before=" << (before_restore_custom_material ? 1 : 0)
                << L", after=" << (after_restore_custom_material ? 1 : 0)
                << L", verified=" << (verified ? 1 : 0) << L".";
            LogProfileDiagnosticOnce(
                request.desired_signature ^ 0x4E4F524553544F52ull,
                stream.str());
        }
    }

    bool knife_default_material_rebind_failed = false;
    std::vector<ExplicitVanillaKnifeMeshRestoreSnapshot>
        captured_vanilla_knife_mesh_restores;
    if (has_explicit_vanilla_pass)
    {
        for (const auto& request : candidate_requests)
        {
            if (!IsExplicitVanillaKnifeFinishProfile(request.profile))
            {
                continue;
            }

            ExplicitVanillaKnifeMeshRestoreSnapshot captured_mesh_restore;
            const auto default_materials_rebound =
                TryRebindExplicitVanillaKnifeDefaultMaterials(
                    request,
                    offsets,
                    g_hook_state.weapon_skin_refresh,
                    &captured_mesh_restore);
            if (captured_mesh_restore.active)
            {
                captured_vanilla_knife_mesh_restores.push_back(
                    std::move(captured_mesh_restore));
            }
            knife_default_material_rebind_failed =
                !default_materials_rebound ||
                knife_default_material_rebind_failed;
        }
    }

    // Mark the process-global helper consumed before entering client.dll. If
    // the native call faults or fails to return, retrying it would be even less
    // safe. This flag is deliberately not cleared by Update, config changes,
    // watched-player switches, or demo seeks.
    g_hook_state.weapon_skin_refresh_attempted_since_rearm.store(
        true,
        std::memory_order_release);
    auto refresh_result = refresh_issue.empty()
        ? TryCallWeaponSkinRefresh(
              active_refresh_binding,
              candidate_requests,
              refresh_issue)
        : WeaponSkinRefreshCallResult::PatchFailed;

    // The helper can submit the old composite to the spectator first-person
    // renderer after the pre-refresh owner clear.  Rebind the unchanged VMDL
    // once after every native refresh pass, then replay the captured stock
    // material assignments against the newly resolved model objects.  This is
    // part of the manual Update transaction, not a per-frame or weapon-switch
    // path, so it cannot reintroduce the former knife-switch rebuild loop.
    if (refresh_result == WeaponSkinRefreshCallResult::Succeeded &&
        has_explicit_vanilla_pass)
    {
        for (const auto& request : candidate_requests)
        {
            if (!IsExplicitVanillaKnifeFinishProfile(request.profile))
            {
                continue;
            }

            knife_default_material_rebind_failed =
                !TryRebindExplicitVanillaKnifeModelResource(request, offsets) ||
                knife_default_material_rebind_failed;
        }
    }

    if (refresh_result == WeaponSkinRefreshCallResult::Succeeded)
    {
        for (const auto& captured_restore : captured_vanilla_knife_mesh_restores)
        {
            knife_default_material_rebind_failed =
                !TryApplyCapturedExplicitVanillaKnifeMeshBaseMaterials(
                    captured_restore,
                    L"after all native skin-refresh passes") ||
                knife_default_material_rebind_failed;
        }
    }

    if (refresh_result == WeaponSkinRefreshCallResult::Succeeded &&
        trace_material_owners)
    {
        LogKnifeRefreshGeneratorState(
            *diagnostic_knife_request,
            offsets,
            L"after");
        LogLiveKnifeMaterialOwners(
            g_hook_state.weapon_skin_refresh,
            offsets,
            L"after",
            diagnostic_knife_request->desired_signature ^ 0x4D41544F574E4552ull);
    }

    if (refresh_result != WeaponSkinRefreshCallResult::Succeeded)
    {
        for (auto& attachment : attachments)
        {
            RestoreTemporaryWeaponRefreshAttributes(attachment);
        }

        if (watched_knife_profile != nullptr)
        {
            std::wstringstream stream;
            stream << L"Refresh helper call failed: result=" << static_cast<int>(refresh_result);
            if (!refresh_issue.empty())
            {
                stream << L", issue=" << refresh_issue;
            }
            TraceWatchedKnifeDiagnostic(*watched_knife_profile, stream.str());
        }
        if (!refresh_issue.empty())
        {
            nskinzcs2::Logger::Warn(refresh_issue);
        }
        g_hook_state.pending_knife_post_refresh_verification = {};
        return false;
    }

    bool verification_failed =
        weapon_visuals_invalidation_failed ||
        knife_generator_payload_reset_failed ||
        knife_default_material_rebind_failed;
    for (const auto& request : candidate_requests)
    {
        if (IsStandardWeaponProfile(request.profile) &&
            !VerifyStandardWeaponAttributes(
                request.refresh_item_view != nullptr ? request.refresh_item_view : request.item_view,
                offsets, BuildWeaponRefreshAttributesImpl(request.profile,
                    request.keychain_profile.has_value() ? &*request.keychain_profile : nullptr)))
        {
            verification_failed = true;
            LogProfileDiagnosticOnce(request.desired_signature ^ 0x535444504F535446ull,
                L"Standard-weapon attribute verification failed after native refresh; not recording refresh success.");
        }
    }
    if (watched_knife_profile != nullptr &&
        g_hook_state.pending_knife_post_refresh_verification.active &&
        g_hook_state.pending_knife_post_refresh_verification.xuid == watched_knife_profile->xuid)
    {
        std::wstring verification_issue;
        const auto verification_passed =
            TryProcessKnifePostRefreshVerification(
                offsets,
                g_hook_state.pending_knife_post_refresh_verification,
                &verification_issue);
        if (!verification_passed && watched_knife_profile != nullptr)
        {
            verification_failed = true;
            std::wstringstream verification_stream;
            verification_stream << L"Refresh helper verification failed: xuid="
                << watched_knife_profile->xuid;
            if (!verification_issue.empty())
            {
                verification_stream << L", issue=" << verification_issue;
            }
            TraceWatchedKnifeDiagnostic(*watched_knife_profile, verification_stream.str());
        }
    }

    if (nskinzcs2::runtime::ShouldConsumeKnifeRefreshHelperEpoch(
            dispatched_knife_request,
            refresh_result == WeaponSkinRefreshCallResult::Succeeded))
    {
        ConsumeKnifeRefreshHelperEpoch();
    }

    if (!verification_failed)
    {
        for (const auto& request : candidate_requests)
        {
            RememberAppliedSignature(
                g_hook_state.refreshed_weapon_signatures,
                request.entity_index,
                request.desired_signature);
        }
    }

    for (auto& attachment : attachments)
    {
        if (promoted_item_views.find(attachment.item_view) != promoted_item_views.end())
        {
            if (!PromoteTemporaryWeaponRefreshAttachmentToRuntimeOwned(
                    attachment,
                    attachment.restore_on_abandon_when_promoted))
            {
                nskinzcs2::Logger::Warn(
                    L"Knife refresh crash guard failed to promote a temporary attribute attachment; "
                    L"leaving the installed payload live until the next runtime reset.");
                attachment.allocated_block = nullptr;
                attachment = {};
            }
            continue;
        }

        RestoreTemporaryWeaponRefreshAttributes(attachment);
    }

    for (const auto& request : candidate_requests)
    {
        if (ShouldTraceWatchedKnifeDiagnostic(request.profile))
        {
            std::wstringstream stream;
            stream << L"Refresh helper thread returned after queued request: entity=" << request.entity_index
                << L", econ=" << FormatPointer(request.econ_entity)
                << L", item_view=" << FormatPointer(request.item_view)
                << L", refresh_item_view="
                << FormatPointer(request.refresh_item_view != nullptr ? request.refresh_item_view : request.item_view)
                << L", target=" << WeaponSkinRefreshTargetText(request.target)
                << L", paint=" << request.profile.paint_kit
                << L", seed=" << request.profile.seed
                << L", wear=" << request.profile.wear
                << L", stattrak=" << request.profile.stat_trak;
            TraceWatchedKnifeDiagnostic(request.profile, stream.str());
        }

        const auto effective_refresh_item_view =
            request.refresh_item_view != nullptr ? request.refresh_item_view : request.item_view;
        const auto promoted_runtime_owned =
            promoted_item_views.find(effective_refresh_item_view) != promoted_item_views.end();
        const auto cleanup_signature = request.desired_signature ^ 0x7340ull;
        std::wstringstream cleanup_stream;
        if (promoted_runtime_owned)
        {
            if (request.keychain_profile.has_value() && UsesTemporaryWorldWeaponRefreshModel(request.profile))
            {
                ScheduleRuntimeOwnedKeychainAttributeBindingRelease(effective_refresh_item_view);
            }

            if (UsesTemporaryWorldWeaponRefreshModel(request.profile))
            {
                cleanup_stream << L"Standard weapon refresh retained the paint attribute payload in runtime-owned";
                cleanup_stream << L" storage on world weapon entity " << request.entity_index
                    << L" for deferred render material consumption.";
            }
            else if (IsExplicitVanillaKnifeFinishProfile(request.profile))
            {
                cleanup_stream << L"Explicit vanilla knife refresh retained its in-place paint=0 overlay";
                cleanup_stream << L" on world weapon entity " << request.entity_index
                    << L" for deferred render material consumption.";
            }
            else
            {
                cleanup_stream << L"Knife refresh crash guard deferred temporary attribute restore";
                cleanup_stream << L" until runtime reset for world weapon entity " << request.entity_index << L".";
            }
        }
        else if (IsStandardWeaponProfile(request.profile))
        {
            cleanup_stream << L"Refresh retained synchronized scalar attributes in the original engine-owned vectors"
                << L" on world weapon entity " << request.entity_index << L"; no vector replacement or restore.";
        }
        else
        {
            cleanup_stream << L"Refresh cleanup restored attribute vector";
            cleanup_stream << L" on world weapon entity " << request.entity_index << L".";
        }
        LogProfileDiagnosticOnce(cleanup_signature, cleanup_stream.str());

        if (request.target == nskinzcs2::runtime::WeaponSkinRefreshTarget::CanonicalItemView)
        {
            const auto diagnostic_signature = request.desired_signature ^ 0x7320ull;
            std::wstringstream stream;
            stream << L"Refresh helper returned after canonical carrier request on entity "
                << request.entity_index << L".";
            LogProfileDiagnosticOnce(diagnostic_signature, stream.str());
        }
        else if (request.target == nskinzcs2::runtime::WeaponSkinRefreshTarget::PrimaryItemView)
        {
            const auto diagnostic_signature = request.desired_signature ^ 0x7310ull;
            std::wstringstream stream;
            if (UsesTemporaryWorldWeaponRefreshModel(request.profile))
            {
                stream << L"Refresh helper returned after world weapon request on entity "
                    << request.entity_index << L".";
            }
            else
            {
                stream << L"Refresh helper returned after weapon request on entity "
                    << request.entity_index << L".";
            }
            LogProfileDiagnosticOnce(diagnostic_signature, stream.str());
        }
        else if (request.target == nskinzcs2::runtime::WeaponSkinRefreshTarget::ExactHudItemView)
        {
            const auto diagnostic_signature = request.desired_signature ^ 0x7300ull;
            std::wstringstream stream;
            stream << L"Refresh helper returned after HUD weapon request on entity "
                << request.entity_index << L".";
            LogProfileDiagnosticOnce(diagnostic_signature, stream.str());
        }
    }

    g_hook_state.pending_knife_post_refresh_verification = {};

    return !verification_failed;
}

bool ApplyExistingItemAttributes(
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::CosmeticProfile& profile,
    const nskinzcs2::model::KeychainProfile* keychain_profile = nullptr)
{
    if (item_view == nullptr || !ProfileNeedsDynamicAttributeWrites(profile, keychain_profile))
    {
        return true;
    }

    const auto desired_attributes = BuildWeaponRefreshAttributesImpl(profile, keychain_profile);
    if (desired_attributes.empty())
    {
        return true;
    }

    if (!ShouldAllowDirectAttributeListWrites(offsets))
    {
        if (IsKnifeProfile(profile))
        {
            LogKnifeAttributeListMutationSuppressed(profile, item_view);
        }
        return true;
    }

    const auto allow_attribute_list_vector_mutation =
        nskinzcs2::runtime::ShouldAllowAttributeListVectorMutationForProfile(profile);
    for (const auto& [definition_index, value] : desired_attributes)
    {
        if (allow_attribute_list_vector_mutation)
        {
            TryUpdateExistingAttributeValue(item_view, offsets, definition_index, value);
        }
        else if (IsKnifeProfile(profile) && definition_index == kAttributePaintKit)
        {
            TryWriteKnifePaintAttributeInPlaceOnly(item_view, offsets, value);
        }
        else
        {
            TryUpdateExistingAttributeValueInPlaceOnly(item_view, offsets, definition_index, value);
        }
    }

    const auto verified_attributes = VerifyAttributeValues(item_view, offsets, desired_attributes);
    if (!IsKnifeProfile(profile))
    {
        return verified_attributes;
    }

    if (verified_attributes)
    {
        return true;
    }

    if (!allow_attribute_list_vector_mutation)
    {
        LogKnifeAttributeListMutationSuppressed(profile, item_view);
        return true;
    }

    if (!nskinzcs2::runtime::ShouldInstallRuntimeOwnedAttributeListForProfile(profile))
    {
        LogKnifeAttributeListMutationSuppressed(profile, item_view);
        return true;
    }

    const auto static_list_ready =
        VerifyAttributeValuesInList(item_view, offsets.item_view_attribute_list, offsets, desired_attributes);
    const auto install_into_static =
        !static_list_ready &&
        offsets.item_view_attribute_list != 0 &&
        TryInstallRuntimeOwnedAttributeList(
            item_view,
            offsets.item_view_attribute_list,
            offsets,
            desired_attributes);

    if (static_list_ready || install_into_static)
    {
        return VerifyAttributeValues(item_view, offsets, desired_attributes);
    }

    const auto install_into_dynamic =
        !verified_attributes &&
        offsets.item_view_dynamic_attribute_list != 0 &&
        TryInstallRuntimeOwnedAttributeList(
            item_view,
            offsets.item_view_dynamic_attribute_list,
            offsets,
            desired_attributes);

    return verified_attributes ||
        (install_into_dynamic && VerifyAttributeValues(item_view, offsets, desired_attributes));
}

bool ApplyWeaponKeychainModuleFields(
    void* keychain_module_entity,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::KeychainProfile* keychain_profile)
{
    if (keychain_module_entity == nullptr || keychain_profile == nullptr)
    {
        return true;
    }

    bool success = true;
    if (offsets.weapon_keychain_def_id != 0)
    {
        const auto keychain_def_id = static_cast<std::uint32_t>(std::max(0, keychain_profile->keychain_kit));
        success = SafeWriteField(keychain_module_entity, offsets.weapon_keychain_def_id, keychain_def_id) && success;
    }

    if (offsets.weapon_keychain_seed != 0)
    {
        success =
            SafeWriteField(keychain_module_entity, offsets.weapon_keychain_seed, static_cast<std::uint32_t>(0)) &&
            success;
    }

    return success;
}

bool TryRefreshKeychainModuleVisualState(
    const std::vector<void*>& entity_cache,
    const int keychain_module_entity_index,
    void* keychain_module_entity,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t desired_signature,
    const wchar_t* reason)
{
    if (keychain_module_entity == nullptr)
    {
        return false;
    }

    std::uintptr_t model_state_address = 0;
    if (!TryResolveEntityModelStateAddress(keychain_module_entity, offsets, model_state_address) ||
        model_state_address == 0)
    {
        std::wstringstream stream;
        stream << L"Keychain module visual refresh skipped before touching the model: entity="
            << keychain_module_entity_index
            << L", reason=" << (reason != nullptr ? reason : L"unknown")
            << L", issue=model_state_unresolved";
        WarnOnceForRuntimeSignature(desired_signature ^ 0x4B435646ull, stream.str());
        return false;
    }

    std::uint64_t before_model_handle = 0;
    const auto before_model_handle_valid =
        TryReadEntityModelHandle(keychain_module_entity, offsets, before_model_handle) &&
        before_model_handle != 0;
    std::uint64_t before_model_name_token = 0;
    const auto before_model_name_token_valid =
        TryReadEntityModelNameToken(keychain_module_entity, offsets, before_model_name_token) &&
        before_model_name_token != 0;
    std::string before_model_name;
    const auto before_model_name_valid =
        TryReadEntityModelNameString(keychain_module_entity, offsets, before_model_name);

    int desired_keychain_kit = 0;
    if (offsets.weapon_keychain_def_id == 0 ||
        !SafeReadField(keychain_module_entity, offsets.weapon_keychain_def_id, desired_keychain_kit) ||
        desired_keychain_kit <= 0)
    {
        std::wstringstream stream;
        stream << L"Keychain module visual refresh skipped before touching the model: entity="
            << keychain_module_entity_index
            << L", reason=" << (reason != nullptr ? reason : L"unknown")
            << L", issue=keychain_def_id_unreadable"
            << L", live_model="
            << (before_model_name_valid ? NarrowToWide(before_model_name) : L"<unreadable>");
        WarnOnceForRuntimeSignature(desired_signature ^ 0x4B435646ull, stream.str());
        return false;
    }

    const auto catalog_snapshot = g_hook_state.app_state != nullptr
        ? g_hook_state.app_state->SnapshotCatalogShared()
        : std::make_shared<const nskinzcs2::model::Catalog>();
    const auto& catalog = *catalog_snapshot;

    const auto desired_model_name = TryResolveKeychainModuleModelName(catalog, desired_keychain_kit);
    if (!desired_model_name.has_value())
    {
        std::wstringstream stream;
        stream << L"Keychain module visual refresh skipped: entity="
            << keychain_module_entity_index
            << L", reason=" << (reason != nullptr ? reason : L"unknown")
            << L", issue=explicit_target_model_path_unavailable"
            << L", keychain_kit=" << desired_keychain_kit
            << L", live_model="
            << (before_model_name_valid ? NarrowToWide(before_model_name) : L"<unreadable>")
            << L", model_handle_readable=" << (before_model_handle_valid ? 1 : 0)
            << L", model_name_token_readable=" << (before_model_name_token_valid ? 1 : 0);
        WarnOnceForRuntimeSignature(
            desired_signature ^
                (static_cast<std::uint64_t>(static_cast<std::uint32_t>(desired_keychain_kit)) << 24) ^
                0x4B435648ull,
            stream.str());
        return false;
    }

    if (before_model_name_valid &&
        ModelIdentityPathMatches(before_model_name, *desired_model_name))
    {
        return true;
    }

    const auto wrote_visual_state =
        TryWriteKnifeDirectRenderModelState(
            entity_cache,
            keychain_module_entity_index,
            keychain_module_entity,
            offsets,
            *desired_model_name,
            desired_signature ^
                (static_cast<std::uint64_t>(static_cast<std::uint32_t>(desired_keychain_kit)) << 24) ^
                0x4B43564Cull,
            L"keychain_module",
            0);

    std::uint64_t after_model_handle = 0;
    std::string after_model_name;
    const auto after_model_handle_valid =
        TryReadEntityModelHandle(keychain_module_entity, offsets, after_model_handle);
    const auto after_model_name_valid =
        TryReadEntityModelNameString(keychain_module_entity, offsets, after_model_name);

    if (wrote_visual_state &&
        after_model_name_valid &&
        ModelIdentityPathMatches(after_model_name, *desired_model_name))
    {
        std::wstringstream stream;
        stream << L"Keychain module visual refresh applied: entity="
            << keychain_module_entity_index
            << L", reason=" << (reason != nullptr ? reason : L"unknown")
            << L", keychain_kit=" << desired_keychain_kit
            << L", desired_model=" << NarrowToWide(*desired_model_name)
            << L", live_model=" << NarrowToWide(after_model_name)
            << L", model_handle_readable=" << (after_model_handle_valid ? 1 : 0);
        LogProfileDiagnosticOnce(
            desired_signature ^
                (static_cast<std::uint64_t>(static_cast<std::uint32_t>(desired_keychain_kit)) << 24) ^
                0x4B435649ull,
            stream.str());
        return true;
    }

    std::wstringstream stream;
    stream << L"Keychain module visual refresh failed: entity="
        << keychain_module_entity_index
        << L", reason=" << (reason != nullptr ? reason : L"unknown")
        << L", issue=model_state_write_unverified"
        << L", keychain_kit=" << desired_keychain_kit
        << L", desired_model=" << NarrowToWide(*desired_model_name)
        << L", live_model="
        << (after_model_name_valid
                ? NarrowToWide(after_model_name)
                : (before_model_name_valid ? NarrowToWide(before_model_name) : L"<unreadable>"))
        << L", model_handle_readable=" << (after_model_handle_valid ? 1 : 0)
        << L", model_name_token_readable=" << (before_model_name_token_valid ? 1 : 0)
        << L", write_result=" << (wrote_visual_state ? 1 : 0);
    WarnOnceForRuntimeSignature(
        desired_signature ^
            (static_cast<std::uint64_t>(static_cast<std::uint32_t>(desired_keychain_kit)) << 24) ^
            0x4B43564Aull,
        stream.str());

    return false;
}

std::vector<std::pair<std::uint16_t, float>> BuildDesiredKeychainAttributes(
    const nskinzcs2::model::KeychainProfile* keychain_profile)
{
    if (keychain_profile == nullptr)
    {
        return {};
    }

    nskinzcs2::model::CosmeticProfile empty_profile;
    return BuildWeaponRefreshAttributesImpl(empty_profile, keychain_profile);
}

bool ApplyPersistentKeychainAttributeToItemView(
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::KeychainProfile* keychain_profile)
{
    if (item_view == nullptr || keychain_profile == nullptr)
    {
        return true;
    }

    const auto desired_keychain_kit = std::max(0, keychain_profile->keychain_kit);
    const auto desired_attributes = BuildDesiredKeychainAttributes(keychain_profile);
    if (desired_attributes.empty())
    {
        return true;
    }

    const auto diagnostic_signature =
        static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(item_view)) ^
        (static_cast<std::uint64_t>(desired_keychain_kit) << 16) ^
        0x4B434859ull;

    if (VerifyAttributeValues(item_view, offsets, desired_attributes))
    {
        return true;
    }

    if (!ShouldAllowDirectAttributeListWrites(offsets))
    {
        bool installed = false;
        if (offsets.item_view_dynamic_attribute_list != 0)
        {
            installed =
                TryInstallRuntimeOwnedAttributeList(
                    item_view,
                    offsets.item_view_dynamic_attribute_list,
                    offsets,
                    desired_attributes) ||
                installed;
        }

        if (!installed && offsets.item_view_attribute_list != 0)
        {
            installed =
                TryInstallRuntimeOwnedAttributeList(
                    item_view,
                    offsets.item_view_attribute_list,
                    offsets,
                    desired_attributes) ||
                installed;
        }

        if (VerifyAttributeValues(item_view, offsets, desired_attributes))
        {
            LogProfileDiagnosticOnce(
                diagnostic_signature,
                L"Persistent keychain attribute fell back to a runtime-owned attribute list install.");
            return true;
        }

        std::wstringstream stream;
        stream << L"Persistent keychain attribute could not be verified before refresh helper dispatch: item_view="
            << FormatPointer(item_view)
            << L", keychain_kit=" << desired_keychain_kit
            << L", runtime_owned_install_attempted=" << (installed ? 1 : 0)
            << L". Continuing so refresh-helper promotion can keep the keychain attribute block live.";
        LogProfileDiagnosticOnce(diagnostic_signature, stream.str());
        return true;
    }

    std::vector<std::uint16_t> failed_definition_indices;
    failed_definition_indices.reserve(desired_attributes.size());
    for (const auto& [definition_index, value] : desired_attributes)
    {
        if (!TryUpdateExistingAttributeValue(item_view, offsets, definition_index, value))
        {
            failed_definition_indices.push_back(definition_index);
        }
    }

    if (!failed_definition_indices.empty())
    {
        std::wstringstream stream;
        stream << L"Persistent keychain attribute update failed: item_view=" << FormatPointer(item_view)
            << L", keychain_kit=" << desired_keychain_kit
            << L", failed_definition_indices=";
        for (std::size_t index = 0; index < failed_definition_indices.size(); ++index)
        {
            if (index != 0)
            {
                stream << L",";
            }
            stream << failed_definition_indices[index];
        }
        LogProfileDiagnosticOnce(diagnostic_signature, stream.str());
        return false;
    }

    const auto verified = VerifyAttributeValues(item_view, offsets, desired_attributes);
    if (!verified)
    {
        std::wstringstream stream;
        stream << L"Persistent keychain attribute verification failed after direct write: item_view="
            << FormatPointer(item_view)
            << L", keychain_kit=" << desired_keychain_kit;
        LogProfileDiagnosticOnce(diagnostic_signature ^ 0x11ull, stream.str());
    }
    return verified;
}

bool TryReadLiveKeychainItemViewState(
    void* item_view,
    const ClientSchemaOffsets& offsets,
    std::uint32_t& keychain_def_id,
    std::uint32_t& keychain_seed)
{
    keychain_def_id = 0;
    keychain_seed = 0;

    if (item_view == nullptr)
    {
        return false;
    }

    bool success = false;

    float raw_keychain_def_id = 0.0f;
    if (TryReadAttributeValue(item_view, offsets, kAttributeKeychainId, raw_keychain_def_id))
    {
        if (std::isfinite(raw_keychain_def_id))
        {
            keychain_def_id = static_cast<std::uint32_t>(
                std::max(0, static_cast<int>(std::lround(raw_keychain_def_id))));
        }
        success = true;
    }

    float raw_keychain_seed = 0.0f;
    if (TryReadAttributeValue(item_view, offsets, kAttributeKeychainSeed, raw_keychain_seed))
    {
        if (std::isfinite(raw_keychain_seed))
        {
            keychain_seed = static_cast<std::uint32_t>(
                std::max(0, static_cast<int>(std::lround(raw_keychain_seed))));
        }
        success = true;
    }

    return success;
}

bool ApplyKeychainStateToWeaponItemView(
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::KeychainProfile* keychain_profile,
    const bool restore_runtime_owned_binding_on_clear,
    std::uint32_t& live_keychain_def_id,
    std::uint32_t& live_keychain_seed)
{
    live_keychain_def_id = 0;
    live_keychain_seed = 0;

    if (item_view == nullptr)
    {
        return false;
    }

    const auto desired_keychain_kit =
        keychain_profile != nullptr ? std::max(0, keychain_profile->keychain_kit) : 0;

    bool success = true;
    if (desired_keychain_kit <= 0)
    {
        if (restore_runtime_owned_binding_on_clear && HasRuntimeOwnedAttributeListBinding(item_view))
        {
            ReleaseRuntimeOwnedAttributeListBindingForItemView(
                item_view,
                AttributeBindingReleaseMode::RestoreOriginal);
        }
        else if (keychain_profile != nullptr)
        {
            success = ApplyPersistentKeychainAttributeToItemView(item_view, offsets, keychain_profile);
        }
    }
    else if (keychain_profile != nullptr)
    {
        success = ApplyPersistentKeychainAttributeToItemView(item_view, offsets, keychain_profile);
    }

    const auto has_live_item_view_keychain =
        TryReadLiveKeychainItemViewState(item_view, offsets, live_keychain_def_id, live_keychain_seed);
    if (desired_keychain_kit <= 0)
    {
        return success && (!has_live_item_view_keychain || live_keychain_def_id == 0u);
    }

    return success &&
        has_live_item_view_keychain &&
        live_keychain_def_id == static_cast<std::uint32_t>(desired_keychain_kit) &&
        live_keychain_seed == 0u;
}

bool DoesWeaponKeychainModuleMatch(
    void* keychain_module_entity,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::KeychainProfile* keychain_profile)
{
    if (keychain_module_entity == nullptr || keychain_profile == nullptr)
    {
        return true;
    }

    if (offsets.weapon_keychain_def_id != 0)
    {
        std::uint32_t actual_keychain_def_id = 0;
        if (!SafeReadField(keychain_module_entity, offsets.weapon_keychain_def_id, actual_keychain_def_id) ||
            actual_keychain_def_id != static_cast<std::uint32_t>(std::max(0, keychain_profile->keychain_kit)))
        {
            return false;
        }
    }

    if (offsets.weapon_keychain_seed != 0)
    {
        std::uint32_t actual_keychain_seed = 0;
        if (!SafeReadField(keychain_module_entity, offsets.weapon_keychain_seed, actual_keychain_seed) ||
            actual_keychain_seed != 0u)
        {
            return false;
        }
    }

    return true;
}

bool RuntimeEntityRttiContainsToken(const void* entity, const wchar_t* token)
{
    if (entity == nullptr || token == nullptr || *token == L'\0')
    {
        return false;
    }

    return BuildRuntimeEntityRttiDescriptor(entity).find(token) != std::wstring::npos;
}

bool IsLikelyKeychainModuleEntityCandidate(
    void* candidate,
    const ClientSchemaOffsets& offsets,
    std::uint32_t* current_keychain_def_id = nullptr,
    std::uint32_t* current_keychain_seed = nullptr)
{
    if (candidate == nullptr)
    {
        return false;
    }

    std::uint32_t live_keychain_def_id = 0;
    std::uint32_t live_keychain_seed = 0;
    const auto live_keychain_state_readable =
        TryReadLiveKeychainModuleState(
            candidate,
            offsets,
            live_keychain_def_id,
            live_keychain_seed);
    if (!live_keychain_state_readable)
    {
        return false;
    }

    if (current_keychain_def_id != nullptr)
    {
        *current_keychain_def_id = live_keychain_def_id;
    }
    if (current_keychain_seed != nullptr)
    {
        *current_keychain_seed = live_keychain_seed;
    }

    if (RuntimeEntityRttiContainsToken(candidate, L"KeychainModule") ||
        RuntimeEntityRttiContainsToken(candidate, L"Keychain"))
    {
        return true;
    }

    auto* candidate_item_view = ResolveWeaponItemView(candidate, offsets);
    int candidate_definition_index = 0;
    const auto candidate_looks_like_weapon_or_wearable =
        candidate_item_view != nullptr &&
        TryReadItemDefinitionIndex(candidate_item_view, offsets, candidate_definition_index) &&
        candidate_definition_index > 0;
    return !candidate_looks_like_weapon_or_wearable;
}

bool TryResolveWeaponKeychainModuleEntity(
    const std::vector<void*>& entity_cache,
    const RenderedWorldWeaponTrace& trace,
    const ClientSchemaOffsets& offsets,
    void*& keychain_module_entity,
    int& keychain_module_entity_index)
{
    keychain_module_entity = nullptr;
    keychain_module_entity_index = -1;

    if (trace.owned_weapon_entity == nullptr && entity_cache.empty())
    {
        return false;
    }

    std::array<int, 4> related_entity_indices {
        trace.owned_weapon_entity_index,
        trace.explicit_owner_child_entity_index,
        trace.scene_owner_entity_index,
        trace.hud_weapon_entity_index,
    };
    std::array<void*, 4> related_entities {
        trace.owned_weapon_entity,
        trace.explicit_owner_child_entity,
        trace.scene_owner_entity,
        trace.hud_weapon_entity,
    };
    std::array<std::uint32_t, 4> related_handles {
        trace.owned_weapon_handle,
        trace.active_weapon_handle,
        trace.pawn_handle,
        trace.owned_weapon_owner_handle,
    };

    auto handle_matches_related_entity =
        [&related_entity_indices](const std::uint32_t handle)
        {
            if (handle == kInvalidEntityHandle)
            {
                return false;
            }

            const auto entity_index = HandleToEntityIndex(handle);
            return std::find(related_entity_indices.begin(), related_entity_indices.end(), entity_index) !=
                related_entity_indices.end();
        };
    auto handle_matches_related_handle =
        [&related_handles](const std::uint32_t handle)
        {
            if (handle == kInvalidEntityHandle)
            {
                return false;
            }

            return std::find(related_handles.begin(), related_handles.end(), handle) !=
                related_handles.end();
        };
    auto pointer_matches_related_entity =
        [&related_entities](void* candidate)
        {
            return candidate != nullptr &&
                std::find(related_entities.begin(), related_entities.end(), candidate) !=
                related_entities.end();
        };
    auto index_matches_related_entity =
        [&related_entity_indices](const int entity_index)
        {
            return entity_index >= 0 &&
                std::find(related_entity_indices.begin(), related_entity_indices.end(), entity_index) !=
                related_entity_indices.end();
        };

    struct KeychainModuleAttachmentMatch
    {
        bool owner_entity = false;
        bool old_move_parent = false;
        bool viewmodel_attachment = false;
        bool old_providee = false;
        bool scene_owner = false;

        [[nodiscard]] bool Any() const noexcept
        {
            return owner_entity || old_move_parent || viewmodel_attachment || old_providee || scene_owner;
        }
    };
    struct KeychainModuleCandidateHint
    {
        bool trace_scene_owner = false;
        bool trace_explicit_child = false;
        bool trace_hud = false;
        bool scene_child_owner = false;
        int scene_depth = 0;
    };
    struct KeychainModuleCandidateEvaluation
    {
        int entity_index = -1;
        void* entity = nullptr;
        std::uint32_t keychain_def_id = 0;
        std::uint32_t keychain_seed = 0;
        KeychainModuleAttachmentMatch attachment_match {};
        KeychainModuleCandidateHint hint {};
        bool has_keychain_rtti = false;
        bool model_name_has_keychain_token = false;
        bool accepted = false;
        int score = std::numeric_limits<int>::min();
        std::string model_name;
        std::wstring rtti;
    };

    const auto resolve_attachment_match =
        [&](void* candidate)
        {
            KeychainModuleAttachmentMatch match {};
            if (candidate == nullptr)
            {
                return match;
            }

            if (offsets.base_owner_entity != 0)
            {
                std::uint32_t owner_handle = kInvalidEntityHandle;
                if (SafeReadField(candidate, offsets.base_owner_entity, owner_handle) &&
                    (owner_handle == trace.owned_weapon_handle ||
                     handle_matches_related_handle(owner_handle) ||
                     handle_matches_related_entity(owner_handle)))
                {
                    match.owner_entity = true;
                }
            }

            if (offsets.base_old_move_parent != 0)
            {
                std::uint32_t old_move_parent_handle = kInvalidEntityHandle;
                if (SafeReadField(candidate, offsets.base_old_move_parent, old_move_parent_handle) &&
                    (old_move_parent_handle == trace.owned_weapon_handle ||
                     handle_matches_related_handle(old_move_parent_handle) ||
                     handle_matches_related_entity(old_move_parent_handle)))
                {
                    match.old_move_parent = true;
                }
            }

            if (offsets.econ_entity_viewmodel_attachment != 0)
            {
                std::uint32_t viewmodel_attachment_handle = kInvalidEntityHandle;
                if (SafeReadField(candidate, offsets.econ_entity_viewmodel_attachment, viewmodel_attachment_handle) &&
                    (viewmodel_attachment_handle == trace.owned_weapon_handle ||
                     handle_matches_related_handle(viewmodel_attachment_handle) ||
                     handle_matches_related_entity(viewmodel_attachment_handle)))
                {
                    match.viewmodel_attachment = true;
                }
            }

            if (offsets.econ_entity_old_providee != 0)
            {
                std::uint32_t providee_handle = kInvalidEntityHandle;
                if (SafeReadField(candidate, offsets.econ_entity_old_providee, providee_handle) &&
                    (providee_handle == trace.owned_weapon_handle ||
                     handle_matches_related_handle(providee_handle) ||
                     handle_matches_related_entity(providee_handle)))
                {
                    match.old_providee = true;
                }
            }

            if (offsets.base_entity_game_scene_node != 0 &&
                offsets.game_scene_node_owner != 0)
            {
                void* scene_node = nullptr;
                void* scene_owner_entity = nullptr;
                if (SafeReadField(candidate, offsets.base_entity_game_scene_node, scene_node) &&
                    scene_node != nullptr &&
                    SafeReadField(scene_node, offsets.game_scene_node_owner, scene_owner_entity) &&
                    scene_owner_entity != nullptr)
                {
                    const auto scene_owner_index =
                        ResolveEntityIndexFromPointer(entity_cache, scene_owner_entity);
                    if (pointer_matches_related_entity(scene_owner_entity) ||
                        index_matches_related_entity(scene_owner_index))
                    {
                        match.scene_owner = true;
                    }
                }
            }

            return match;
        };
    auto describe_candidate =
        [&](const KeychainModuleCandidateEvaluation& evaluation)
        {
            std::wstringstream stream;
            stream << L"candidate{entity=" << evaluation.entity_index
                << L", ptr=" << FormatPointer(evaluation.entity)
                << L", score=" << evaluation.score
                << L", accepted=" << (evaluation.accepted ? 1 : 0)
                << L", def_id=" << evaluation.keychain_def_id
                << L", seed=" << evaluation.keychain_seed
                << L", owner=" << (evaluation.attachment_match.owner_entity ? 1 : 0)
                << L", old_parent=" << (evaluation.attachment_match.old_move_parent ? 1 : 0)
                << L", viewmodel=" << (evaluation.attachment_match.viewmodel_attachment ? 1 : 0)
                << L", providee=" << (evaluation.attachment_match.old_providee ? 1 : 0)
                << L", scene_owner=" << (evaluation.attachment_match.scene_owner ? 1 : 0)
                << L", trace_scene=" << (evaluation.hint.trace_scene_owner ? 1 : 0)
                << L", trace_explicit=" << (evaluation.hint.trace_explicit_child ? 1 : 0)
                << L", trace_hud=" << (evaluation.hint.trace_hud ? 1 : 0)
                << L", scene_child_owner=" << (evaluation.hint.scene_child_owner ? 1 : 0)
                << L", scene_depth=" << evaluation.hint.scene_depth
                << L", has_keychain_rtti=" << (evaluation.has_keychain_rtti ? 1 : 0)
                << L", model_name_keychain=" << (evaluation.model_name_has_keychain_token ? 1 : 0);
            if (!evaluation.model_name.empty())
            {
                stream << L", model_name=" << NarrowToWide(evaluation.model_name);
            }
            if (!evaluation.rtti.empty())
            {
                stream << L", rtti=" << evaluation.rtti;
            }
            stream << L"}";
            return stream.str();
        };

    KeychainModuleCandidateEvaluation best_candidate {};
    std::vector<KeychainModuleCandidateEvaluation> near_miss_candidates;
    near_miss_candidates.reserve(3);

    const auto remember_near_miss =
        [&](const KeychainModuleCandidateEvaluation& evaluation)
        {
            if (evaluation.entity == nullptr || evaluation.score <= 0)
            {
                return;
            }

            for (auto& existing : near_miss_candidates)
            {
                if (existing.entity == evaluation.entity)
                {
                    if (evaluation.score > existing.score)
                    {
                        existing = evaluation;
                    }
                    std::sort(
                        near_miss_candidates.begin(),
                        near_miss_candidates.end(),
                        [](const auto& left, const auto& right)
                        {
                            return left.score > right.score;
                        });
                    return;
                }
            }

            near_miss_candidates.push_back(evaluation);
            std::sort(
                near_miss_candidates.begin(),
                near_miss_candidates.end(),
                [](const auto& left, const auto& right)
                {
                    return left.score > right.score;
                });
            if (near_miss_candidates.size() > 3)
            {
                near_miss_candidates.resize(3);
            }
        };

    const auto consider_candidate =
        [&](const int candidate_index, void* candidate, const KeychainModuleCandidateHint hint)
        {
            if (candidate == nullptr)
            {
                return;
            }

            KeychainModuleCandidateEvaluation evaluation {};
            evaluation.entity_index =
                candidate_index >= 0
                    ? candidate_index
                    : ResolveEntityIndexFromPointer(entity_cache, candidate);
            if (evaluation.entity_index < 0)
            {
                evaluation.entity_index = BuildSyntheticEntityIndex(candidate, 0x4B434D44u);
            }
            evaluation.entity = candidate;
            evaluation.hint = hint;

            if (!IsLikelyKeychainModuleEntityCandidate(
                    candidate,
                    offsets,
                    &evaluation.keychain_def_id,
                    &evaluation.keychain_seed))
            {
                return;
            }

            evaluation.has_keychain_rtti =
                RuntimeEntityRttiContainsToken(candidate, L"KeychainModule") ||
                RuntimeEntityRttiContainsToken(candidate, L"Keychain") ||
                RuntimeEntityRttiContainsToken(candidate, L"Charm");
            evaluation.rtti = BuildRuntimeEntityRttiDescriptor(candidate);
            TryReadEntityModelNameString(candidate, offsets, evaluation.model_name);
            evaluation.model_name_has_keychain_token =
                ContainsAsciiInsensitive(evaluation.model_name, "keychain") ||
                ContainsAsciiInsensitive(evaluation.model_name, "charm");
            evaluation.attachment_match = resolve_attachment_match(candidate);

            const auto strong_relation =
                evaluation.attachment_match.owner_entity ||
                evaluation.attachment_match.old_move_parent ||
                evaluation.attachment_match.scene_owner ||
                evaluation.hint.trace_scene_owner ||
                evaluation.hint.trace_explicit_child ||
                evaluation.hint.scene_child_owner;
            const auto soft_relation =
                evaluation.attachment_match.viewmodel_attachment ||
                evaluation.attachment_match.old_providee ||
                evaluation.hint.trace_hud;

            evaluation.score = 0;
            if (evaluation.has_keychain_rtti)
            {
                evaluation.score += 80;
            }
            if (evaluation.model_name_has_keychain_token)
            {
                evaluation.score += 30;
            }
            if (evaluation.keychain_def_id != 0)
            {
                evaluation.score += 20;
            }
            if (evaluation.attachment_match.owner_entity)
            {
                evaluation.score += 45;
            }
            if (evaluation.attachment_match.old_move_parent)
            {
                evaluation.score += 40;
            }
            if (evaluation.attachment_match.scene_owner)
            {
                evaluation.score += 35;
            }
            if (evaluation.attachment_match.viewmodel_attachment)
            {
                evaluation.score += 18;
            }
            if (evaluation.attachment_match.old_providee)
            {
                evaluation.score += 18;
            }
            if (evaluation.hint.trace_explicit_child)
            {
                evaluation.score += 18;
            }
            if (evaluation.hint.trace_scene_owner)
            {
                evaluation.score += 14;
            }
            if (evaluation.hint.trace_hud)
            {
                evaluation.score += 8;
            }
            if (evaluation.hint.scene_child_owner)
            {
                evaluation.score += std::max(8, 28 - std::min(evaluation.hint.scene_depth, 6) * 2);
            }
            if (evaluation.attachment_match.owner_entity && evaluation.attachment_match.old_move_parent)
            {
                evaluation.score += 15;
            }
            if (evaluation.has_keychain_rtti)
            {
                evaluation.accepted =
                    strong_relation ||
                    soft_relation ||
                    evaluation.keychain_def_id != 0;
            }
            else if (evaluation.model_name_has_keychain_token)
            {
                evaluation.accepted =
                    strong_relation ||
                    (soft_relation && evaluation.keychain_def_id != 0);
            }
            else
            {
                evaluation.accepted =
                    evaluation.keychain_def_id != 0 &&
                    strong_relation &&
                    (evaluation.attachment_match.owner_entity ||
                     evaluation.attachment_match.old_move_parent ||
                     evaluation.attachment_match.scene_owner ||
                     evaluation.hint.scene_child_owner);
            }

            if (evaluation.accepted &&
                (best_candidate.entity == nullptr || evaluation.score > best_candidate.score))
            {
                best_candidate = evaluation;
            }
            else
            {
                remember_near_miss(evaluation);
            }
        };

    consider_candidate(
        trace.explicit_owner_child_entity_index,
        trace.explicit_owner_child_entity,
        KeychainModuleCandidateHint {.trace_explicit_child = true, .scene_depth = 1});
    consider_candidate(
        trace.scene_owner_entity_index,
        trace.scene_owner_entity,
        KeychainModuleCandidateHint {.trace_scene_owner = true});
    consider_candidate(
        trace.hud_weapon_entity_index,
        trace.hud_weapon_entity,
        KeychainModuleCandidateHint {.trace_hud = true});

    int scanned_scene_child_owner_candidates = 0;
    if (trace.owned_weapon_entity != nullptr &&
        offsets.base_entity_game_scene_node != 0 &&
        offsets.game_scene_node_child != 0 &&
        offsets.game_scene_node_next_sibling != 0 &&
        offsets.game_scene_node_owner != 0)
    {
        void* weapon_scene_node = nullptr;
        if (SafeReadField(trace.owned_weapon_entity, offsets.base_entity_game_scene_node, weapon_scene_node) &&
            weapon_scene_node != nullptr)
        {
            void* first_child_scene_node = nullptr;
            if (SafeReadField(weapon_scene_node, offsets.game_scene_node_child, first_child_scene_node) &&
                first_child_scene_node != nullptr)
            {
                struct PendingSceneNode
                {
                    void* scene_node = nullptr;
                    int depth = 0;
                };

                std::vector<PendingSceneNode> pending_scene_nodes;
                pending_scene_nodes.reserve(16);
                pending_scene_nodes.push_back({first_child_scene_node, 1});
                std::unordered_set<void*> visited_scene_nodes;
                visited_scene_nodes.reserve(32);
                visited_scene_nodes.insert(weapon_scene_node);

                while (!pending_scene_nodes.empty() && scanned_scene_child_owner_candidates < 64)
                {
                    const auto pending = pending_scene_nodes.back();
                    pending_scene_nodes.pop_back();
                    if (pending.scene_node == nullptr ||
                        !visited_scene_nodes.insert(pending.scene_node).second)
                    {
                        continue;
                    }

                    ++scanned_scene_child_owner_candidates;

                    if (pending.depth < 8)
                    {
                        void* nested_child_scene_node = nullptr;
                        if (SafeReadField(pending.scene_node, offsets.game_scene_node_child, nested_child_scene_node) &&
                            nested_child_scene_node != nullptr)
                        {
                            pending_scene_nodes.push_back({nested_child_scene_node, pending.depth + 1});
                        }
                    }

                    void* next_sibling_scene_node = nullptr;
                    if (SafeReadField(
                            pending.scene_node,
                            offsets.game_scene_node_next_sibling,
                            next_sibling_scene_node) &&
                        next_sibling_scene_node != nullptr)
                    {
                        pending_scene_nodes.push_back({next_sibling_scene_node, pending.depth});
                    }

                    void* owner_entity = nullptr;
                    if (!SafeReadField(pending.scene_node, offsets.game_scene_node_owner, owner_entity) ||
                        owner_entity == nullptr)
                    {
                        continue;
                    }

                    auto owner_entity_index = ResolveEntityIndexFromPointer(entity_cache, owner_entity);
                    if (owner_entity_index < 0)
                    {
                        owner_entity_index = BuildSyntheticEntityIndex(owner_entity, 0x4B435343u);
                    }

                    consider_candidate(
                        owner_entity_index,
                        owner_entity,
                        KeychainModuleCandidateHint {
                            .scene_child_owner = true,
                            .scene_depth = pending.depth});
                }
            }
        }
    }

    for (std::size_t index = 0; index < entity_cache.size(); ++index)
    {
        auto* candidate = entity_cache[index];
        if (candidate == nullptr || candidate == trace.owned_weapon_entity)
        {
            continue;
        }

        consider_candidate(static_cast<int>(index), candidate, {});
    }

    if (best_candidate.entity != nullptr)
    {
        keychain_module_entity = best_candidate.entity;
        keychain_module_entity_index = best_candidate.entity_index;

        if (best_candidate.hint.scene_child_owner ||
            best_candidate.attachment_match.scene_owner ||
            (!best_candidate.attachment_match.owner_entity &&
             !best_candidate.attachment_match.old_move_parent))
        {
            const auto resolution_signature =
                trace.xuid ^
                (static_cast<std::uint64_t>(
                     static_cast<std::uint32_t>(std::max(0, trace.owned_weapon_entity_index)))
                 << 32) ^
                0x4B43524C56454E54ull;
            std::wstringstream stream;
            stream << L"Resolved keychain module candidate for weapon trace {"
                << DescribeRenderedWorldWeaponTrace(trace)
                << L"} using "
                << describe_candidate(best_candidate)
                << L", scanned_scene_child_candidates=" << scanned_scene_child_owner_candidates;
            LogProfileDiagnosticOnce(resolution_signature, stream.str());
        }
        return true;
    }

    if (!near_miss_candidates.empty())
    {
        const auto failure_signature =
            trace.xuid ^
            (static_cast<std::uint64_t>(
                 static_cast<std::uint32_t>(std::max(0, trace.owned_weapon_entity_index)))
             << 32) ^
            0x4B434E4F4D415443ull;
        std::wstringstream stream;
        stream << L"Keychain module resolution failed for weapon trace {"
            << DescribeRenderedWorldWeaponTrace(trace)
            << L"}; scanned_scene_child_candidates=" << scanned_scene_child_owner_candidates
            << L", near_misses=";
        for (std::size_t index = 0; index < near_miss_candidates.size(); ++index)
        {
            if (index != 0)
            {
                stream << L" | ";
            }
            stream << describe_candidate(near_miss_candidates[index]);
        }
        LogProfileDiagnosticOnce(failure_signature, stream.str());
    }

    return false;
}

bool DoesDurableStandardWeaponCarrierStateMatchProfile(
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::CosmeticProfile& profile,
    const int current_definition_index,
    const nskinzcs2::model::KeychainProfile* keychain_profile = nullptr)
{
    if (!IsStandardWeaponProfile(profile) || item_view == nullptr)
    {
        return false;
    }

    int actual_definition_index = 0;
    if (!TryReadItemDefinitionIndex(item_view, offsets, actual_definition_index) ||
        actual_definition_index != current_definition_index)
    {
        return false;
    }

    const auto desired_attributes = BuildWeaponRefreshAttributesImpl(profile, keychain_profile);
    return !desired_attributes.empty() &&
        VerifyStandardWeaponAttributes(item_view, offsets, desired_attributes) &&
        VerifyAttributeValues(item_view, offsets, desired_attributes);
}

bool DoesAppliedEconItemMatchProfile(
    void* econ_entity,
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::CosmeticProfile& profile,
    const std::uint64_t xuid,
    const int current_definition_index,
    const bool allow_definition_override = true,
    const bool allow_knife_definition_override = false,
    const bool require_legacy_activation_writes = true,
    const nskinzcs2::model::KeychainProfile* keychain_profile = nullptr,
    void* keychain_module_entity = nullptr)
{
    if (item_view == nullptr)
    {
        return false;
    }

    const auto keychain_only_apply = IsKeychainOnlyApplyRequest(profile, keychain_profile);
    const auto should_validate_extended_item_view = ShouldApplyExtendedItemViewWrites(profile);
    const auto uses_temporary_world_refresh_model = UsesTemporaryWorldWeaponRefreshModel(profile);
    const auto should_expect_definition_override =
        ShouldApplyDefinitionOverrideWrites(profile) &&
        allow_definition_override &&
        profile.override_item != 0 &&
        (allow_knife_definition_override || !IsKnifeOverrideRequest(profile));
    const auto expected_definition_index = static_cast<int>(
        should_expect_definition_override ? profile.override_item : current_definition_index);
    const auto expected_wear =
        IsStandardWeaponProfile(profile)
            ? nskinzcs2::model::NormalizeCosmeticWear(profile.wear)
            : profile.wear;

    int actual_definition_index = 0;
    if (!TryReadItemDefinitionIndex(item_view, offsets, actual_definition_index) ||
        actual_definition_index != expected_definition_index)
    {
        return false;
    }

    if (keychain_only_apply)
    {
        return VerifyAttributeValues(item_view, offsets, BuildWeaponRefreshAttributesImpl(profile, keychain_profile));
    }


    if (ProfileHasExplicitPaintIntent(profile) && offsets.item_view_disallow_soc != 0)
    {
        bool actual_disallow_soc = false;
        if (!SafeReadField(item_view, offsets.item_view_disallow_soc, actual_disallow_soc) ||
            !actual_disallow_soc)
        {
            return false;
        }
    }

    if (profile.explicit_vanilla_finish &&
        offsets.item_view_restore_custom_material_after_precache != 0)
    {
        bool actual_restore_custom_material = true;
        if (!SafeReadField(
                item_view,
                offsets.item_view_restore_custom_material_after_precache,
                actual_restore_custom_material) ||
            actual_restore_custom_material)
        {
            return false;
        }
    }

    if (should_validate_extended_item_view)
    {
        std::uint32_t actual_item_id_high = 0;
        if (!SafeReadField(item_view, offsets.item_view_item_id_high, actual_item_id_high) ||
            actual_item_id_high != 0xFFFFFFFFu)
        {
            return false;
        }

        std::uint32_t actual_account_id = 0;
        if (!SafeReadField(item_view, offsets.item_view_account_id, actual_account_id) ||
            actual_account_id != AccountIdFromXuid(xuid))
        {
            return false;
        }

        if (require_legacy_activation_writes && offsets.item_view_item_id_low != 0)
        {
            std::uint32_t actual_item_id_low = 0;
            const auto expected_item_id_low =
                (IsStandardWeaponProfile(profile) ||
                 (IsKnifeProfile(profile) && ProfileHasExplicitPaintIntent(profile)))
                    ? nskinzcs2::runtime::BuildStandardWeaponMaterialCacheKey(
                          profile,
                          xuid,
                          current_definition_index)
                    : 0xFFFFFFFFu;
            if (!SafeReadField(item_view, offsets.item_view_item_id_low, actual_item_id_low) ||
                actual_item_id_low != expected_item_id_low)
            {
                return false;
            }
        }

        if (require_legacy_activation_writes && offsets.item_view_initialized != 0)
        {
            bool actual_initialized = false;
            if (!SafeReadField(item_view, offsets.item_view_initialized, actual_initialized) ||
                !actual_initialized)
            {
                return false;
            }
        }

        if (offsets.item_view_entity_quality != 0)
        {
            std::uint8_t actual_quality = 0;
            if (!SafeReadField(item_view, offsets.item_view_entity_quality, actual_quality) ||
                static_cast<int>(actual_quality) != profile.quality)
            {
                return false;
            }
        }

        if (ShouldWriteCustomNameFields(profile))
        {
            std::string actual_custom_name;
            if (!SafeReadFixedString(item_view, offsets.item_view_custom_name, 161, actual_custom_name) ||
                actual_custom_name != profile.custom_name)
            {
                return false;
            }

            if (offsets.item_view_custom_name_override != 0)
            {
                std::string actual_custom_name_override;
                if (!SafeReadFixedString(item_view, offsets.item_view_custom_name_override, 161, actual_custom_name_override) ||
                    actual_custom_name_override != profile.custom_name)
                {
                    return false;
                }
            }
        }
    }

    if (econ_entity != nullptr)
    {
        if (ProfileHasExplicitPaintIntent(profile))
        {
            int actual_fallback_paint_kit = 0;
            if (!SafeReadField(econ_entity, offsets.econ_entity_fallback_paint_kit, actual_fallback_paint_kit) ||
                actual_fallback_paint_kit != profile.paint_kit)
            {
                return false;
            }

            // Registration metadata belongs to the engine's live item-provider
            // index.  It is deliberately not part of cosmetic verification:
            // changing those fields without calling the matching engine
            // unregister routine can leave the same item view linked twice in
            // the registered-item hash table.
        }

        const auto xuid_parts = SplitXuid(xuid);

        if (offsets.econ_entity_original_owner_xuid_low != 0)
        {
            std::uint32_t owner_xuid_low = 0;
            if (!SafeReadField(econ_entity, offsets.econ_entity_original_owner_xuid_low, owner_xuid_low) ||
                owner_xuid_low != xuid_parts.first)
            {
                return false;
            }
        }

        if (offsets.econ_entity_original_owner_xuid_high != 0)
        {
            std::uint32_t owner_xuid_high = 0;
            if (!SafeReadField(econ_entity, offsets.econ_entity_original_owner_xuid_high, owner_xuid_high) ||
                owner_xuid_high != xuid_parts.second)
            {
                return false;
            }
        }

        if (ProfileHasExplicitPaintIntent(profile))
        {
            int actual_fallback_seed = 0;
            if (!SafeReadField(econ_entity, offsets.econ_entity_fallback_seed, actual_fallback_seed) ||
                actual_fallback_seed != profile.seed)
            {
                return false;
            }

            float actual_fallback_wear = nskinzcs2::model::kMinimumCosmeticWear;
            if (!SafeReadField(econ_entity, offsets.econ_entity_fallback_wear, actual_fallback_wear) ||
                !nskinzcs2::model::CosmeticWearMatchesExactly(actual_fallback_wear, expected_wear))
            {
                return false;
            }
        }

        int actual_fallback_stat_trak = 0;
        if (!SafeReadField(econ_entity, offsets.econ_entity_fallback_stat_trak, actual_fallback_stat_trak) ||
            actual_fallback_stat_trak != profile.stat_trak)
        {
            return false;
        }

        if (require_legacy_activation_writes && offsets.econ_entity_initialized != 0)
        {
            bool actual_initialized = false;
            if (!SafeReadField(econ_entity, offsets.econ_entity_initialized, actual_initialized) ||
                !actual_initialized)
            {
                return false;
            }
        }
    }

    static_cast<void>(DoesWeaponKeychainModuleMatch(keychain_module_entity, offsets, keychain_profile));

    if (uses_temporary_world_refresh_model)
    {
        return VerifyStandardWeaponAttributes(
            item_view, offsets, BuildWeaponRefreshAttributesImpl(profile, keychain_profile));
    }

    if (keychain_profile != nullptr &&
        !VerifyAttributeValues(
            item_view,
            offsets,
            BuildWeaponRefreshAttributesImpl(profile, keychain_profile)))
    {
        return false;
    }

    return true;
}

bool ValidateStandardWeaponPaintForApply(
    const nskinzcs2::model::CosmeticProfile& profile, const int current_definition_index)
{
    if (!IsStandardWeaponProfile(profile)) { return true; }
    const auto catalog = g_hook_state.app_state != nullptr
        ? g_hook_state.app_state->SnapshotCatalogShared() : nullptr;
    const auto compatibility = nskinzcs2::CatalogBuilder::CheckWeaponPaintCompatibility(
        catalog.get(), current_definition_index, profile.paint_kit);
    if (compatibility == nskinzcs2::WeaponPaintCompatibility::Compatible) { return true; }
    std::wstringstream stream;
    stream << L"Rejected weapon finish before any appearance writes: definition=" << current_definition_index
        << L", paint=" << profile.paint_kit << L", xuid=" << profile.xuid
        << L", reason=" << (compatibility == nskinzcs2::WeaponPaintCompatibility::Unknown
            ? L"weapon-paint compatibility data unavailable" : L"paint is not compatible with this weapon")
        << L". Select a compatible finish; no automatic vanilla conversion.";
    LogProfileDiagnosticOnce(BuildProfileApplySignature(
        profile, profile.xuid, current_definition_index, 0x5041494E54434F4Dull), stream.str());
    return false;
}

bool ApplyProfileToEconItem(
    void* econ_entity,
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::CosmeticProfile& profile,
    const std::uint64_t xuid,
    const int current_definition_index,
    const bool allow_definition_override = true,
    const bool allow_knife_definition_override = false,
    const bool write_legacy_activation_writes = true,
    const nskinzcs2::model::KeychainProfile* keychain_profile = nullptr,
    void* keychain_module_entity = nullptr)
{
    if (item_view == nullptr || !ValidateStandardWeaponPaintForApply(profile, current_definition_index))
    {
        return false;
    }

    const auto keychain_only_apply = IsKeychainOnlyApplyRequest(profile, keychain_profile);
    const auto demo_keychain_module_only_apply =
        keychain_only_apply &&
        g_hook_state.demo_playing.load(std::memory_order_acquire);
    if (keychain_only_apply)
    {
        const auto module_fields_applied =
            ApplyWeaponKeychainModuleFields(keychain_module_entity, offsets, keychain_profile);
        static_cast<void>(module_fields_applied);
        bool success = true;
        success = ApplyExistingItemAttributes(item_view, offsets, profile, keychain_profile) && success;
        if (keychain_profile != nullptr && !demo_keychain_module_only_apply)
        {
            std::uint32_t live_item_view_keychain_def_id = 0;
            std::uint32_t live_item_view_keychain_seed = 0;
            success =
                ApplyKeychainStateToWeaponItemView(
                    item_view,
                    offsets,
                    keychain_profile,
                    false,
                    live_item_view_keychain_def_id,
                    live_item_view_keychain_seed) &&
                success;
        }
        return success;
    }

    const auto should_apply_extended_item_view = ShouldApplyExtendedItemViewWrites(profile);
    const auto should_write_definition_override =
        ShouldApplyDefinitionOverrideWrites(profile) &&
        allow_definition_override &&
        profile.override_item != 0 &&
        (allow_knife_definition_override || !IsKnifeOverrideRequest(profile));
    const auto should_sync_definition_index =
        ShouldApplyDefinitionOverrideWrites(profile) &&
        offsets.item_view_definition_index != 0;
    const auto uses_temporary_world_refresh_model = UsesTemporaryWorldWeaponRefreshModel(profile);
    const auto final_definition_index = static_cast<std::uint16_t>(
        should_write_definition_override ? profile.override_item : current_definition_index);
    const auto quality = static_cast<std::uint8_t>(std::clamp(profile.quality, 0, 255));
    const auto item_id_high = static_cast<std::uint32_t>(0xFFFFFFFFu);
    const auto item_id_low =
        (IsStandardWeaponProfile(profile) ||
         (IsKnifeProfile(profile) && ProfileHasExplicitPaintIntent(profile)))
            ? nskinzcs2::runtime::BuildStandardWeaponMaterialCacheKey(
                  profile,
                  xuid,
                  current_definition_index)
            : static_cast<std::uint32_t>(0xFFFFFFFFu);
    const auto account_id = AccountIdFromXuid(xuid);
    const auto xuid_parts = SplitXuid(xuid);
    const auto effective_wear =
        IsStandardWeaponProfile(profile)
            ? nskinzcs2::model::NormalizeCosmeticWear(profile.wear)
            : profile.wear;

    if (IsStandardWeaponProfile(profile))
    {
        std::size_t changed_slots = 0;
        const auto synchronized = SynchronizeStandardWeaponAttributes(
            item_view, offsets, BuildWeaponRefreshAttributesImpl(profile, keychain_profile), changed_slots);
        if (!synchronized || changed_slots != 0)
        {
            std::wstringstream stream;
            stream << L"Standard-weapon in-place attribute synchronization: xuid=" << xuid
                << L", definition=" << current_definition_index << L", paint=" << profile.paint_kit
                << L", changed_slots=" << changed_slots << L", verified=" << (synchronized ? 1 : 0)
                << L", vector_replacement=0, registration_metadata_writes=0.";
            LogProfileDiagnosticOnce(BuildProfileApplySignature(
                profile, xuid, current_definition_index, synchronized ? 0x53544453594E434Full : 0x53544453594E4346ull), stream.str());
        }
        if (!synchronized)
        {
            return false;
        }
    }

    bool success = true;
    if (econ_entity != nullptr)
    {
        if (ProfileHasExplicitPaintIntent(profile))
        {
            success = success && SafeWriteField(econ_entity, offsets.econ_entity_fallback_paint_kit, profile.paint_kit);

            // Preserve the live attribute-container registration identity.
            // Directly zeroing provider_token / registered_as_item_id does not
            // unlink the node from the engine's registered-item hash table and
            // can create a cyclic chain on the next material lookup.
        }
        if (offsets.econ_entity_original_owner_xuid_low != 0)
        {
            success = success && SafeWriteField(econ_entity, offsets.econ_entity_original_owner_xuid_low, xuid_parts.first);
        }

        if (offsets.econ_entity_original_owner_xuid_high != 0)
        {
            success = success && SafeWriteField(econ_entity, offsets.econ_entity_original_owner_xuid_high, xuid_parts.second);
        }

        if (ProfileHasExplicitPaintIntent(profile))
        {
            success = success && SafeWriteField(econ_entity, offsets.econ_entity_fallback_seed, profile.seed);
            success = success && SafeWriteField(econ_entity, offsets.econ_entity_fallback_wear, effective_wear);
        }
        success = success && SafeWriteField(econ_entity, offsets.econ_entity_fallback_stat_trak, profile.stat_trak);
        if (write_legacy_activation_writes && offsets.econ_entity_initialized != 0)
        {
            success = success && SafeWriteField(econ_entity, offsets.econ_entity_initialized, true);
        }

        if (IsKnifeProfile(profile) &&
            ProfileHasExplicitPaintIntent(profile) &&
            offsets.weapon_clear_weapon_identifying_ugc != 0)
        {
            success = success && SafeWriteField(
                econ_entity,
                offsets.weapon_clear_weapon_identifying_ugc,
                false);
        }

        if (IsExplicitVanillaKnifeFinishProfile(profile))
        {
            std::uint32_t previous_material_group = 0;
            const auto material_group_reset =
                TryResetEntityMaterialGroupToDefault(
                    econ_entity,
                    offsets,
                    previous_material_group);
            std::wstringstream stream;
            stream << L"Explicit vanilla knife material-group reset: entity="
                << FormatPointer(econ_entity)
                << L", previous_token=0x" << std::hex << std::uppercase
                << previous_material_group << std::dec << std::nouppercase
                << L", reset=" << (material_group_reset ? 1 : 0) << L".";
            LogProfileDiagnosticOnce(
                BuildProfileApplySignature(
                    profile,
                    xuid,
                    current_definition_index,
                    0x56414E4D41544752ull),
                stream.str());
        }

        const auto module_fields_applied =
            ApplyWeaponKeychainModuleFields(keychain_module_entity, offsets, keychain_profile);
        static_cast<void>(module_fields_applied);
    }

    if (should_apply_extended_item_view)
    {
        if (!uses_temporary_world_refresh_model)
        {
            success = ApplyExistingItemAttributes(item_view, offsets, profile, keychain_profile) && success;
        }
        else if (keychain_profile != nullptr)
        {
            success = ApplyPersistentKeychainAttributeToItemView(item_view, offsets, keychain_profile) && success;
        }
        if (should_sync_definition_index)
        {
            success = success && SafeWriteField(item_view, offsets.item_view_definition_index, final_definition_index);
        }

        if (uses_temporary_world_refresh_model && offsets.item_view_item_id_high != 0)
        {
            std::uint32_t current_item_id_high = 0;
            if (SafeReadField(item_view, offsets.item_view_item_id_high, current_item_id_high) &&
                StandardWeaponNeedsItemIdHighResetImpl(current_item_id_high, uses_temporary_world_refresh_model))
            {
                success = success &&
                    SafeWriteField(item_view, offsets.item_view_item_id_high, static_cast<std::uint32_t>(0));
            }
        }

        success = success && SafeWriteField(item_view, offsets.item_view_item_id_high, item_id_high);
        if (offsets.item_view_entity_quality != 0)
        {
            success = success && SafeWriteField(item_view, offsets.item_view_entity_quality, quality);
        }

        if (write_legacy_activation_writes && offsets.item_view_item_id_low != 0)
        {
            success = success && SafeWriteField(item_view, offsets.item_view_item_id_low, item_id_low);
        }
        success = success && SafeWriteField(item_view, offsets.item_view_account_id, account_id);
        if (ProfileHasExplicitPaintIntent(profile) && offsets.item_view_disallow_soc != 0)
        {
            // A demo item can keep resolving its original SOC-backed visuals
            // after fallback fields change. Explicit cosmetic intent must
            // detach this client item view from that provider so paint=0 uses
            // the model's stock material and positive paints cannot flicker
            // back to the recorded inventory finish.
            success = success && SafeWriteField(item_view, offsets.item_view_disallow_soc, true);
        }
        if (profile.explicit_vanilla_finish &&
            offsets.item_view_restore_custom_material_after_precache != 0)
        {
            success = success && SafeWriteField(
                item_view,
                offsets.item_view_restore_custom_material_after_precache,
                false);
        }
        if (write_legacy_activation_writes && offsets.item_view_initialized != 0)
        {
            success = success && SafeWriteField(item_view, offsets.item_view_initialized, true);
        }
    }

    if (ShouldWriteCustomNameFields(profile))
    {
        success = success && SafeWriteFixedString(item_view, offsets.item_view_custom_name, 161, profile.custom_name);

        if (offsets.item_view_custom_name_override != 0)
        {
            success = success && SafeWriteFixedString(item_view, offsets.item_view_custom_name_override, 161, profile.custom_name);
        }
    }

    return success;
}

bool TryApplyWeaponEntityProfile(
    const int entity_index,
    void* econ_entity,
    void* item_view,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::CosmeticProfile& profile,
    const std::uint64_t xuid,
    const int current_definition_index,
    const std::uint64_t desired_signature,
    const bool allow_knife_definition_override,
    const bool write_legacy_activation_writes,
    const nskinzcs2::runtime::WeaponSkinRefreshTarget refresh_target,
    void* refresh_item_view,
    std::unordered_set<int>& applied_entity_indices,
    int& applied_weapon_writes,
    std::vector<PendingWeaponRefreshRequest>* pending_refresh_requests,
    const nskinzcs2::model::KeychainProfile* keychain_profile)
{
    // Validate imported configs before the cached-success and refresh fast paths.
    if (!ValidateStandardWeaponPaintForApply(profile, current_definition_index)) { return false; }
    if (applied_entity_indices.find(entity_index) != applied_entity_indices.end())
    {
        return false;
    }

    if (IsStandardWeaponProfile(profile) &&
        !TryTrackStandardWeaponAppearanceEpoch(entity_index, econ_entity, nullptr, nullptr, offsets))
    {
        LogProfileDiagnosticOnce(desired_signature ^ 0x53544445504F4348ull,
            L"Standard-weapon appearance pending: carrier generation could not be verified; no writes dispatched.");
        return false;
    }

    const auto needs_refresh =
        pending_refresh_requests != nullptr &&
        IsMaterialRefreshTarget(refresh_target) &&
        (refresh_item_view != nullptr ? refresh_item_view : item_view) != nullptr &&
        NeedsWeaponSkinRefresh(profile, keychain_profile) &&
        !HasAppliedSignature(
            g_hook_state.refreshed_weapon_signatures,
            entity_index,
            desired_signature);
    const auto has_applied_signature =
        HasAppliedSignature(g_hook_state.applied_weapon_signatures, entity_index, desired_signature);
    void* effective_refresh_item_view = refresh_item_view != nullptr ? refresh_item_view : item_view;
    auto queue_refresh_request =
        [&](const bool from_cached_match)
        {
            pending_refresh_requests->push_back(
                {entity_index,
                 econ_entity,
                 item_view,
                 effective_refresh_item_view,
                 profile,
                 desired_signature,
                 refresh_target,
                 false,
                 keychain_profile != nullptr ? std::optional<nskinzcs2::model::KeychainProfile> {*keychain_profile}
                                             : std::nullopt});

            if (ShouldTraceWatchedKnifeDiagnostic(profile))
            {
                std::wstringstream stream;
                stream << L"Queued refresh request from weapon apply path: entity=" << entity_index
                    << L", econ=" << FormatPointer(econ_entity)
                    << L", item_view=" << FormatPointer(item_view)
                    << L", refresh_item_view=" << FormatPointer(effective_refresh_item_view)
                    << L", target=" << WeaponSkinRefreshTargetText(refresh_target)
                    << L", material_target=" << (IsMaterialRefreshTarget(refresh_target) ? 1 : 0)
                    << L", from_cached_match=" << (from_cached_match ? 1 : 0)
                    << L", queue_size=" << pending_refresh_requests->size()
                    << L", paint=" << profile.paint_kit
                    << L", seed=" << profile.seed
                    << L", wear=" << profile.wear
                    << L", stattrak=" << profile.stat_trak;
                TraceWatchedKnifeDiagnostic(profile, stream.str());
            }
        };
    if (has_applied_signature &&
        IsStandardWeaponProfile(profile) &&
        HasAppliedSignature(
            g_hook_state.refreshed_weapon_signatures,
            entity_index,
            desired_signature) &&
        DoesDurableStandardWeaponCarrierStateMatchProfile(
            item_view,
            offsets,
            profile,
            current_definition_index,
            keychain_profile))
    {
        // Demo/network replication is allowed to restore item_id_low,
        // initialized, quality, account and fallback scalar fields after the
        // material helper has consumed our runtime-owned attribute vector.
        // Those volatile fields are not a reason to invalidate the completed
        // material or dispatch the helper again.
        return false;
    }

    if (has_applied_signature &&
        DoesAppliedEconItemMatchProfile(
            econ_entity,
            item_view,
            offsets,
            profile,
            xuid,
            current_definition_index,
            true,
            allow_knife_definition_override,
            write_legacy_activation_writes,
            keychain_profile))
    {
        if (needs_refresh)
        {
            queue_refresh_request(true);
        }
        return false;
    }

    if (!ApplyProfileToEconItem(
            econ_entity,
            item_view,
            offsets,
            profile,
            xuid,
            current_definition_index,
            true,
            allow_knife_definition_override,
            write_legacy_activation_writes,
            keychain_profile))
    {
        return false;
    }

    // Scalar/demo drift is not material invalidation. The completed signature
    // belongs to the last successful refresh, not the latest field write.
    // A new desired signature or a structural runtime reset still refreshes.

    RememberAppliedSignature(g_hook_state.applied_weapon_signatures, entity_index, desired_signature);
    applied_entity_indices.insert(entity_index);
    if (needs_refresh)
    {
        queue_refresh_request(false);
    }
    if (!UsesTemporaryWorldWeaponRefreshModel(profile))
    {
        if (refresh_target == nskinzcs2::runtime::WeaponSkinRefreshTarget::CanonicalItemView)
        {
            LogCanonicalWeaponApplyReadbackOnce(entity_index, econ_entity, item_view, offsets, desired_signature);
        }
        else if (refresh_target == nskinzcs2::runtime::WeaponSkinRefreshTarget::ExactHudItemView)
        {
            LogHudWeaponApplyReadbackOnce(entity_index, econ_entity, item_view, offsets, desired_signature);
        }
        else
        {
            LogWeaponApplyReadbackOnce(entity_index, econ_entity, item_view, offsets, desired_signature);
        }
    }
    ++applied_weapon_writes;
    return true;
}

bool TryApplyWeaponLinkedHandle(
    void* entity_list,
    void* parent_weapon_entity,
    const int parent_entity_index,
    const std::ptrdiff_t handle_offset,
    const ClientSchemaOffsets& offsets,
    const nskinzcs2::model::CosmeticProfile& profile,
    const std::uint64_t xuid,
    const int fallback_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    const std::uint64_t target_tag,
    const bool allow_knife_definition_override,
    std::unordered_set<int>& applied_entity_indices,
    int& applied_weapon_writes,
    std::vector<PendingWeaponRefreshRequest>* pending_refresh_requests,
    const nskinzcs2::model::KeychainProfile* keychain_profile)
{
    if (entity_list == nullptr || parent_weapon_entity == nullptr || handle_offset == 0)
    {
        return false;
    }

    auto trace_linked_failure =
        [&](const wchar_t* reason,
            const std::uint32_t handle_value,
            const int candidate_entity_index,
            void* candidate_entity,
            void* candidate_item_view)
        {
            if (!ShouldTraceWatchedKnifeDiagnostic(profile))
            {
                return;
            }

            std::wstringstream stream;
            stream << L"Linked weapon path failed: source=" << WeaponLinkTargetTagText(target_tag)
                << L", parent_entity=" << parent_entity_index
                << L", handle_offset=0x" << std::hex << static_cast<std::uint64_t>(handle_offset)
                << L", handle=0x" << handle_value
                << std::dec
                << L", linked_entity=" << candidate_entity_index
                << L", linked_entity_ptr=" << FormatPointer(candidate_entity)
                << L", linked_item_view=" << FormatPointer(candidate_item_view)
                << L", reason=" << reason;
            TraceWatchedKnifeDiagnostic(profile, stream.str());
        };

    std::uint32_t linked_handle = kInvalidEntityHandle;
    if (!SafeReadField(parent_weapon_entity, handle_offset, linked_handle))
    {
        trace_linked_failure(L"linked handle read failed", linked_handle, -1, nullptr, nullptr);
        return false;
    }

    const auto linked_entity_index = HandleToEntityIndex(linked_handle);
    if (linked_entity_index < 0 || linked_entity_index == parent_entity_index)
    {
        trace_linked_failure(
            L"linked handle resolved to an invalid entity index",
            linked_handle,
            linked_entity_index,
            nullptr,
            nullptr);
        return false;
    }

    void* linked_entity = nullptr;
    if (!TryGetEntityFromIndex(entity_list, linked_entity_index, linked_entity) || linked_entity == nullptr)
    {
        trace_linked_failure(L"linked entity lookup failed", linked_handle, linked_entity_index, linked_entity, nullptr);
        return false;
    }

    void* direct_linked_item_view = ResolveWeaponItemView(linked_entity, offsets);
    ResolvedLinkedWeaponItemView linked_resolution {};
    if (!TryResolveValidatedLinkedWeaponItemView(
            linked_entity,
            linked_entity_index,
            offsets,
            xuid,
            fallback_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            linked_resolution))
    {
        trace_linked_failure(
            L"linked item view did not validate as the same weapon family",
            linked_handle,
            linked_entity_index,
            linked_entity,
            direct_linked_item_view);
        const auto warning_signature =
            BuildProfileApplySignature(
                profile,
                xuid,
                fallback_definition_index,
                target_tag ^ 0x4000ull,
                keychain_profile);
        std::wstringstream warning_stream;
        warning_stream << L"Skipped unsafe linked weapon entity " << linked_entity_index
            << L" while applying XUID " << xuid
            << L": linked item view did not validate as the same weapon family.";
        WarnOnceForRuntimeSignature(warning_signature, warning_stream.str());
        return false;
    }

    const auto heuristic_linked_profile =
        linked_resolution.used_heuristic ? BuildHeuristicLinkedWeaponProfile(profile) : nskinzcs2::model::CosmeticProfile {};
    const auto& linked_profile = linked_resolution.used_heuristic ? heuristic_linked_profile : profile;
    void* apply_econ_entity = linked_resolution.used_heuristic ? nullptr : linked_entity;
    void* linked_item_view = linked_resolution.item_view;
    const auto linked_definition_index = linked_resolution.definition_index;
    const auto linked_signature =
        BuildProfileApplySignature(
            linked_profile,
            xuid,
            linked_definition_index,
            target_tag,
            keychain_profile);
    const auto preferred_refresh_target =
        target_tag == kTargetTagWeaponViewModel
        ? (linked_resolution.used_heuristic
               ? nskinzcs2::runtime::WeaponSkinRefreshTarget::HeuristicViewModelItemView
               : nskinzcs2::runtime::WeaponSkinRefreshTarget::ViewModelItemView)
        : (linked_resolution.used_heuristic
               ? nskinzcs2::runtime::WeaponSkinRefreshTarget::HeuristicProvideeItemView
               : nskinzcs2::runtime::WeaponSkinRefreshTarget::ProvideeItemView);
    const auto resolved_refresh_target = ResolveLinkedWeaponRefreshTargetImpl(profile, preferred_refresh_target);
    void* refresh_item_view = linked_item_view;
    if ((resolved_refresh_target == nskinzcs2::runtime::WeaponSkinRefreshTarget::ViewModelItemView ||
         resolved_refresh_target == nskinzcs2::runtime::WeaponSkinRefreshTarget::HeuristicViewModelItemView) &&
        (preferred_refresh_target == nskinzcs2::runtime::WeaponSkinRefreshTarget::ProvideeItemView ||
         preferred_refresh_target == nskinzcs2::runtime::WeaponSkinRefreshTarget::HeuristicProvideeItemView) &&
        offsets.econ_entity_viewmodel_attachment != 0)
    {
        std::uint32_t refresh_handle = kInvalidEntityHandle;
        if (SafeReadField(parent_weapon_entity, offsets.econ_entity_viewmodel_attachment, refresh_handle))
        {
            const auto refresh_entity_index = HandleToEntityIndex(refresh_handle);
            if (refresh_entity_index >= 0 && refresh_entity_index != parent_entity_index)
            {
                void* refresh_entity = nullptr;
                if (TryGetEntityFromIndex(entity_list, refresh_entity_index, refresh_entity) && refresh_entity != nullptr)
                {
                    ResolvedLinkedWeaponItemView refresh_resolution {};
                    if (TryResolveValidatedLinkedWeaponItemView(
                            refresh_entity,
                            refresh_entity_index,
                            offsets,
                            xuid,
                            fallback_definition_index,
                            known_definition_indices,
                            knife_definition_indices,
                            glove_definition_indices,
                            refresh_resolution))
                    {
                        refresh_item_view = refresh_resolution.item_view;
                    }
                }
            }
        }
    }
    if (ShouldTraceWatchedKnifeDiagnostic(profile))
    {
        std::wstringstream stream;
        stream << L"Linked weapon path resolved: source=" << WeaponLinkTargetTagText(target_tag)
            << L", parent_entity=" << parent_entity_index
            << L", linked_entity=" << linked_entity_index
            << L", linked_entity_ptr=" << FormatPointer(linked_entity)
            << L", linked_item_view=" << FormatPointer(linked_item_view)
            << L", apply_econ_entity=" << FormatPointer(apply_econ_entity)
            << L", refresh_item_view=" << FormatPointer(refresh_item_view)
            << L", linked_definition=" << linked_definition_index
            << L", preferred_target=" << WeaponSkinRefreshTargetText(preferred_refresh_target)
            << L", resolved_target=" << WeaponSkinRefreshTargetText(resolved_refresh_target)
            << L", material_target=" << (IsMaterialRefreshTarget(resolved_refresh_target) ? 1 : 0)
            << L", heuristic=" << (linked_resolution.used_heuristic ? 1 : 0);
        if (linked_resolution.used_heuristic)
        {
            stream << L", heuristic_source_offset=0x"
                << std::hex << static_cast<std::uint64_t>(linked_resolution.heuristic.source_offset)
                << std::dec
                << L", heuristic_via_pointer=" << (linked_resolution.heuristic.via_pointer ? 1 : 0);
        }
        TraceWatchedKnifeDiagnostic(profile, stream.str());
    }

    return TryApplyWeaponEntityProfile(
        linked_entity_index,
        apply_econ_entity,
        linked_item_view,
        offsets,
        linked_profile,
        xuid,
        linked_definition_index,
        linked_signature,
        allow_knife_definition_override,
        false,
        resolved_refresh_target,
        refresh_item_view,
        applied_entity_indices,
        applied_weapon_writes,
        pending_refresh_requests,
        keychain_profile);
}

bool TryResolveValidatedWeaponLinkedCandidate(
    void* entity_list,
    void* parent_weapon_entity,
    const int parent_entity_index,
    const std::ptrdiff_t handle_offset,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int fallback_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    const nskinzcs2::runtime::CanonicalWeaponCarrierKind kind,
    WeaponCarrierCandidate& candidate)
{
    candidate = {};
    candidate.kind = kind;

    if (entity_list == nullptr || parent_weapon_entity == nullptr || handle_offset == 0)
    {
        return false;
    }

    std::uint32_t linked_handle = kInvalidEntityHandle;
    if (!SafeReadField(parent_weapon_entity, handle_offset, linked_handle))
    {
        return false;
    }

    const auto linked_entity_index = HandleToEntityIndex(linked_handle);
    if (linked_entity_index < 0 || linked_entity_index == parent_entity_index)
    {
        return false;
    }

    void* linked_entity = nullptr;
    if (!TryGetEntityFromIndex(entity_list, linked_entity_index, linked_entity) || linked_entity == nullptr)
    {
        return false;
    }

    ResolvedLinkedWeaponItemView linked_resolution {};
    if (!TryResolveValidatedLinkedWeaponItemView(
            linked_entity,
            linked_entity_index,
            offsets,
            xuid,
            fallback_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            linked_resolution))
    {
        return false;
    }

    candidate.entity_index = linked_resolution.entity_index;
    candidate.entity = linked_resolution.entity;
    candidate.item_view = linked_resolution.item_view;
    candidate.definition_index = linked_resolution.definition_index;
    if (kind == nskinzcs2::runtime::CanonicalWeaponCarrierKind::Providee &&
        ShouldLogWatchedKnifeAnimationTrace(xuid))
    {
        const auto signature =
            xuid ^
            (static_cast<std::uint64_t>(
                 static_cast<std::uint32_t>(parent_entity_index >= 0 ? parent_entity_index : 0))
             << 32) ^
            static_cast<std::uint64_t>(
                static_cast<std::uint32_t>(
                    linked_resolution.entity_index >= 0 ? linked_resolution.entity_index : 0)) ^
            0x5052564F4C445331ull;
        std::string model_name;
        TryReadEntityModelNameString(linked_entity, offsets, model_name);
        const auto model_kind = ClassifyKnifeFirstPersonRenderableModel(linked_entity, offsets);
        const auto* model_kind_text =
            model_kind == KnifeFirstPersonRenderableModelKind::WeaponLike
                ? L"weapon"
                : model_kind == KnifeFirstPersonRenderableModelKind::CharacterLike
                    ? L"character"
                    : L"unknown";
        auto* entity_item_view = ResolveWeaponItemView(linked_entity, offsets);
        std::wstringstream stream;
        stream << L"Knife canonical providee source: parent_entity=" << parent_entity_index
            << L", old_providee_handle=0x" << std::hex << std::uppercase << linked_handle
            << std::dec << std::nouppercase
            << L", linked_entity=" << linked_entity_index
            << L", resolved_entity=" << linked_resolution.entity_index
            << L", used_heuristic=" << (linked_resolution.used_heuristic ? 1 : 0)
            << L", resolved_item_view=" << FormatPointer(linked_resolution.item_view)
            << L", entity_item_view=" << FormatPointer(entity_item_view)
            << L", shared_item_view="
            << ((entity_item_view != nullptr && entity_item_view == linked_resolution.item_view) ? 1 : 0)
            << L", definition=" << linked_resolution.definition_index
            << L", model_kind=" << model_kind_text;
        if (!model_name.empty())
        {
            stream << L", model_name=" << NarrowToWide(model_name);
        }
        LogProfileDiagnosticOnce(signature, stream.str());
    }
    return true;
}

const wchar_t* CanonicalWeaponCarrierKindToString(
    const nskinzcs2::runtime::CanonicalWeaponCarrierKind kind) noexcept
{
    using nskinzcs2::runtime::CanonicalWeaponCarrierKind;

    switch (kind)
    {
    case CanonicalWeaponCarrierKind::World:
        return L"world";
    case CanonicalWeaponCarrierKind::Hud:
        return L"hud";
    case CanonicalWeaponCarrierKind::ViewModel:
        return L"viewmodel";
    case CanonicalWeaponCarrierKind::Providee:
        return L"providee";
    case CanonicalWeaponCarrierKind::None:
    default:
        return L"none";
    }
}

bool TryResolveCanonicalWeaponCarrier(
    void* entity_list,
    const std::vector<void*>& entity_cache,
    const RuntimePlayerBinding& player_binding,
    const int world_weapon_entity_index,
    void* world_weapon_entity,
    void* world_item_view,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t xuid,
    const int current_definition_index,
    const std::unordered_set<int>& known_definition_indices,
    const std::unordered_set<int>& knife_definition_indices,
    const std::unordered_set<int>& glove_definition_indices,
    CanonicalWeaponCarrierBinding& binding)
{
    binding = {};

    if (entity_list == nullptr ||
        world_weapon_entity == nullptr ||
        world_item_view == nullptr ||
        world_weapon_entity_index < 0)
    {
        return false;
    }

    binding.world.kind = nskinzcs2::runtime::CanonicalWeaponCarrierKind::World;
    binding.world.entity_index = world_weapon_entity_index;
    binding.world.entity = world_weapon_entity;
    binding.world.item_view = world_item_view;
    binding.world.definition_index = current_definition_index;
    binding.candidate_world_entity = world_weapon_entity;

    int hud_weapon_entity_index = -1;
    void* hud_weapon_entity = nullptr;
    if (TryResolveHudWeaponEntity(
            entity_list,
            entity_cache,
            player_binding,
            world_weapon_entity_index,
            offsets,
            hud_weapon_entity_index,
            hud_weapon_entity))
    {
        binding.hud.kind = nskinzcs2::runtime::CanonicalWeaponCarrierKind::Hud;
        binding.hud.entity_index = hud_weapon_entity_index;
        binding.hud.entity = hud_weapon_entity;
        binding.hud.item_view = ResolveWeaponItemView(hud_weapon_entity, offsets);
        binding.hud.definition_index = current_definition_index;
        binding.candidate_hud_entity = hud_weapon_entity;
        if (binding.hud.item_view == nullptr)
        {
            binding.hud = {};
            binding.candidate_hud_entity = nullptr;
        }
    }

    TryResolveValidatedWeaponLinkedCandidate(
        entity_list,
        world_weapon_entity,
        world_weapon_entity_index,
        offsets.econ_entity_viewmodel_attachment,
        offsets,
        xuid,
        current_definition_index,
        known_definition_indices,
        knife_definition_indices,
        glove_definition_indices,
        nskinzcs2::runtime::CanonicalWeaponCarrierKind::ViewModel,
        binding.viewmodel);
    TryResolveValidatedWeaponLinkedCandidate(
        entity_list,
        world_weapon_entity,
        world_weapon_entity_index,
        offsets.econ_entity_old_providee,
        offsets,
        xuid,
        current_definition_index,
        known_definition_indices,
        knife_definition_indices,
        glove_definition_indices,
        nskinzcs2::runtime::CanonicalWeaponCarrierKind::Providee,
        binding.providee);

    nskinzcs2::runtime::CanonicalWeaponCarrierDecisionInputs inputs {};
    inputs.world_valid = binding.world.IsValid();
    inputs.hud_valid = binding.hud.IsValid();
    inputs.viewmodel_valid = binding.viewmodel.IsValid();
    inputs.providee_valid = binding.providee.IsValid();
    inputs.world_hud_shared =
        inputs.world_valid && inputs.hud_valid && binding.world.item_view == binding.hud.item_view;
    inputs.world_viewmodel_shared =
        inputs.world_valid && inputs.viewmodel_valid && binding.world.item_view == binding.viewmodel.item_view;
    inputs.world_providee_shared =
        inputs.world_valid && inputs.providee_valid && binding.world.item_view == binding.providee.item_view;
    inputs.hud_viewmodel_shared =
        inputs.hud_valid && inputs.viewmodel_valid && binding.hud.item_view == binding.viewmodel.item_view;
    inputs.hud_providee_shared =
        inputs.hud_valid && inputs.providee_valid && binding.hud.item_view == binding.providee.item_view;
    inputs.viewmodel_providee_shared =
        inputs.viewmodel_valid && inputs.providee_valid && binding.viewmodel.item_view == binding.providee.item_view;

    binding.item_view_shared = CanonicalWeaponCarrierDecisionIsSharedImpl(inputs);
    binding.kind = ResolveCanonicalWeaponCarrierKindImpl(inputs);

    const WeaponCarrierCandidate* selected_candidate = nullptr;
    if (binding.world.IsValid())
    {
        binding.kind = nskinzcs2::runtime::CanonicalWeaponCarrierKind::World;
        selected_candidate = &binding.world;
    }
    else
    {
        selected_candidate =
            [&binding]() -> const WeaponCarrierCandidate*
            {
                using nskinzcs2::runtime::CanonicalWeaponCarrierKind;

                switch (binding.kind)
                {
                case CanonicalWeaponCarrierKind::World:
                    return binding.world.IsValid() ? &binding.world : nullptr;
                case CanonicalWeaponCarrierKind::Hud:
                    return binding.hud.IsValid() ? &binding.hud : nullptr;
                case CanonicalWeaponCarrierKind::ViewModel:
                    return binding.viewmodel.IsValid() ? &binding.viewmodel : nullptr;
                case CanonicalWeaponCarrierKind::Providee:
                    return binding.providee.IsValid() ? &binding.providee : nullptr;
                case CanonicalWeaponCarrierKind::None:
                default:
                    return nullptr;
                }
            }();
    }

    if (selected_candidate == nullptr)
    {
        return false;
    }

    binding.canonical_item_view = selected_candidate->item_view;
    binding.canonical_owner_entity = selected_candidate->entity;
    binding.canonical_owner_entity_index = selected_candidate->entity_index;
    return true;
}

bool TryApplyCanonicalWeaponMeshMasks(
    const CanonicalWeaponCarrierBinding& binding,
    const ClientSchemaOffsets& offsets,
    const std::uint64_t mesh_group_mask,
    const std::uint64_t desired_signature)
{
    if (!binding.IsResolved())
    {
        return false;
    }

    bool applied = false;
    std::unordered_set<int> applied_entity_indices;
    applied_entity_indices.reserve(4);

    const auto apply_candidate =
        [&](const WeaponCarrierCandidate& candidate)
        {
            if (!candidate.IsValid() ||
                candidate.item_view != binding.canonical_item_view ||
                !applied_entity_indices.insert(candidate.entity_index).second)
            {
                return;
            }

            applied =
                TryApplyWeaponMeshGroupMask(
                    candidate.entity_index,
                    candidate.entity,
                    offsets,
                    mesh_group_mask,
                    desired_signature) ||
                applied;
        };

    apply_candidate(binding.world);
    apply_candidate(binding.hud);
    apply_candidate(binding.viewmodel);
    apply_candidate(binding.providee);
    return applied;
}

