void CopyFixedCString(char* destination, const std::size_t capacity, const char* source) noexcept
{
    if (destination == nullptr || capacity == 0)
    {
        return;
    }

    destination[0] = '\0';
    if (source == nullptr)
    {
        return;
    }

    std::size_t index = 0;
    for (; index + 1 < capacity && source[index] != '\0'; ++index)
    {
        destination[index] = source[index];
    }

    destination[index] = '\0';
}

bool TryCopyReadableAnsiPreviewNoexcept(
    const char* source,
    char* destination,
    const std::size_t capacity) noexcept
{
    if (source == nullptr ||
        reinterpret_cast<std::uintptr_t>(source) < 0x10000 ||
        destination == nullptr ||
        capacity < 2)
    {
        if (destination != nullptr && capacity > 0)
        {
            destination[0] = '\0';
        }
        return false;
    }

    std::size_t index = 0;
    bool saw_printable = false;
    __try
    {
        for (; index + 1 < capacity; ++index)
        {
            const auto ch = static_cast<unsigned char>(source[index]);
            if (ch == '\0')
            {
                break;
            }

            if ((ch < 32 || ch > 126) && ch != '\t' && ch != '\r' && ch != '\n')
            {
                destination[0] = '\0';
                return false;
            }

            if (ch >= 32 && ch <= 126)
            {
                saw_printable = true;
            }

            destination[index] = static_cast<char>(ch);
        }
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        destination[0] = '\0';
        return false;
    }

    destination[index] = '\0';
    return saw_printable && index > 0;
}

bool TryReadPointerValueNoexcept(const void* address, std::uintptr_t& value) noexcept
{
    value = 0;
    if (address == nullptr || reinterpret_cast<std::uintptr_t>(address) < 0x10000)
    {
        return false;
    }

    __try
    {
        value = *static_cast<const std::uintptr_t*>(address);
        return value >= 0x10000;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        value = 0;
        return false;
    }
}

