void NoteResourceHandleQueryLiveEntry(const std::size_t hook_index) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    probe.total_entered_count.fetch_add(1, std::memory_order_relaxed);
    if (hook_index < probe.entered_counts.size())
    {
        probe.entered_counts[hook_index].fetch_add(1, std::memory_order_relaxed);
    }
}

bool TryCommitResourceHandleQueryCarrierCapture(
    const std::size_t hook_index,
    void* this_ptr,
    const char* path,
    const std::uint64_t arg3,
    const std::uint64_t arg4,
    const ResourceHandleQueryCarrierCaptureKind capture_kind,
    const char* carrier_label,
    const char* preview) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    std::uint32_t expected = kResourceHandleQueryCarrierCaptureNone;
    if (!probe.capture_state.compare_exchange_strong(
            expected,
            kResourceHandleQueryCarrierCaptureWriting,
            std::memory_order_acq_rel))
    {
        return false;
    }

    probe.capture_kind = capture_kind;
    probe.capture_hook_index = static_cast<std::uint32_t>(hook_index);
    probe.capture_this_ptr = reinterpret_cast<std::uintptr_t>(this_ptr);
    probe.capture_arg2_ptr = reinterpret_cast<std::uintptr_t>(path);
    probe.capture_arg3 = arg3;
    probe.capture_arg4 = arg4;
    CopyFixedCString(
        probe.capture_carrier.data(),
        probe.capture_carrier.size(),
        carrier_label);
    CopyFixedCString(
        probe.capture_preview.data(),
        probe.capture_preview.size(),
        preview);
    probe.capture_state.store(
        kResourceHandleQueryCarrierCapturePending,
        std::memory_order_release);
    return true;
}

void TryProbeResourceHandleQueryCarrier(
    const std::size_t hook_index,
    void* this_ptr,
    const char* path,
    const std::uint64_t arg3,
    const std::uint64_t arg4) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    if (probe.capture_state.load(std::memory_order_acquire) !=
        kResourceHandleQueryCarrierCaptureNone)
    {
        return;
    }

    std::uint32_t budget_remaining = probe.probe_budget_remaining.load(std::memory_order_relaxed);
    while (budget_remaining > 0 &&
           !probe.probe_budget_remaining.compare_exchange_weak(
               budget_remaining,
               budget_remaining - 1,
               std::memory_order_acq_rel))
    {
    }

    if (budget_remaining == 0)
    {
        return;
    }

    char preview[kResourceHandleQueryCarrierPreviewCapacity] {};
    const auto try_capture_preview =
        [&](const char* carrier_label, const char* candidate) noexcept
        {
            return TryCopyReadableAnsiPreviewNoexcept(candidate, preview, sizeof(preview)) &&
                IsInterestingResourceHandleQueryCarrierPreview(preview) &&
                TryCommitResourceHandleQueryCarrierCapture(
                    hook_index,
                    this_ptr,
                    path,
                    arg3,
                    arg4,
                    ResourceHandleQueryCarrierCaptureKind::TextPreview,
                    carrier_label,
                    preview);
        };

    if (try_capture_preview("arg2", path))
    {
        return;
    }

    if (try_capture_preview(
            "arg3",
            reinterpret_cast<const char*>(static_cast<std::uintptr_t>(arg3))))
    {
        return;
    }

    if (try_capture_preview(
            "arg4",
            reinterpret_cast<const char*>(static_cast<std::uintptr_t>(arg4))))
    {
        return;
    }

    std::uintptr_t indirect_pointer = 0;
    if (TryReadPointerValueNoexcept(
            reinterpret_cast<const void*>(static_cast<std::uintptr_t>(arg3)),
            indirect_pointer) &&
        try_capture_preview("arg3*", reinterpret_cast<const char*>(indirect_pointer)))
    {
        return;
    }

    indirect_pointer = 0;
    if (TryReadPointerValueNoexcept(
            reinterpret_cast<const void*>(static_cast<std::uintptr_t>(arg4)),
            indirect_pointer) &&
        try_capture_preview("arg4*", reinterpret_cast<const char*>(indirect_pointer)))
    {
        return;
    }

    if (budget_remaining == 1)
    {
        TryCommitResourceHandleQueryCarrierCapture(
            hook_index,
            this_ptr,
            path,
            arg3,
            arg4,
            ResourceHandleQueryCarrierCaptureKind::RawSnapshot,
            "no_ascii_carrier",
            "no readable knife/.vmdl carrier in first probe window");
    }
}

