bool LooksLikeRuntimeRttiObjectPointer(const void* object) noexcept
{
    if (object == nullptr ||
        reinterpret_cast<std::uintptr_t>(object) < kMinUserModePointer ||
        !IsReadablePointer(object))
    {
        return false;
    }

    void** vtable = nullptr;
    return SafeReadValue(object, vtable) &&
        vtable != nullptr &&
        reinterpret_cast<std::uintptr_t>(vtable) >= kMinUserModePointer;
}

bool TryQueryCommittedReadableRegion(
    const void* pointer,
    MEMORY_BASIC_INFORMATION& memory_info) noexcept
{
    memory_info = {};
    if (pointer == nullptr ||
        reinterpret_cast<std::uintptr_t>(pointer) < kMinUserModePointer ||
        VirtualQuery(pointer, &memory_info, sizeof(memory_info)) != sizeof(memory_info) ||
        memory_info.State != MEM_COMMIT ||
        (memory_info.Protect & PAGE_GUARD) != 0)
    {
        return false;
    }

    const auto protection = memory_info.Protect & 0xFFu;
    return protection != PAGE_NOACCESS;
}

