bool IsSceneSystemModuleHandle(const HMODULE module) noexcept
{
    if (module == nullptr)
    {
        return false;
    }

    const auto module_name = GetModuleFileNameOnly(module);
    return !module_name.empty() &&
        _wcsicmp(module_name.c_str(), L"scenesystem.dll") == 0;
}

