bool IsResourceHandleQuerySceneSemanticNoiseObject(const void* object) noexcept
{
    if (object == nullptr ||
        reinterpret_cast<std::uintptr_t>(object) < kMinUserModePointer ||
        !IsReadablePointer(object))
    {
        return false;
    }

    void** vtable = nullptr;
    if (!SafeReadValue(object, vtable) || vtable == nullptr)
    {
        return false;
    }

    if (IsSceneSystemModuleHandle(GetModuleFromAddress(vtable)))
    {
        return true;
    }

    void* locator = nullptr;
    return SafeReadValue(vtable - 1, locator) &&
        locator != nullptr &&
        IsSceneSystemModuleHandle(GetModuleFromAddress(locator));
}

