std::uint32_t ScoreResourceHandleQuerySemanticSample(const char* sample) noexcept
{
    if (!LooksLikeInterestingResourceHandleQuerySemanticSample(sample))
    {
        return 0;
    }

    std::uint32_t score = 1;
    if (std::strstr(sample, "weapon_knife") != nullptr)
    {
        score += 40;
    }
    if (std::strstr(sample, "knife_butterfly") != nullptr ||
        std::strstr(sample, "knife_karambit") != nullptr)
    {
        score += 32;
    }
    if (std::strstr(sample, "weapons/models/") != nullptr)
    {
        score += 18;
    }
    if (std::strstr(sample, ".vmdl") != nullptr ||
        std::strstr(sample, ".vmdl_c") != nullptr)
    {
        score += 16;
    }
    if (std::strstr(sample, "knife") != nullptr)
    {
        score += 12;
    }
    if (std::strstr(sample, "weapon") != nullptr)
    {
        score += 8;
    }
    if (std::strstr(sample, "model") != nullptr)
    {
        score += 4;
    }
    if (std::strstr(sample, "Target") != nullptr ||
        std::strstr(sample, "content") != nullptr)
    {
        score += 3;
    }
    return score;
}

bool TryCaptureInterestingResourceHandleQuerySemanticWindowSample(
    const void* base,
    const std::size_t window_bytes,
    char* out,
    const std::size_t out_size,
    std::size_t& out_offset,
    std::uint32_t& out_score) noexcept
{
    out_offset = 0;
    out_score = 0;
    if (out == nullptr || out_size < 8)
    {
        return false;
    }
    out[0] = '\0';

    if (base == nullptr ||
        reinterpret_cast<std::uintptr_t>(base) < kMinUserModePointer ||
        !IsReadablePointer(base) ||
        window_bytes < 8)
    {
        return false;
    }

    constexpr std::size_t kSemanticWindowBufferSize = 0xC0;
    std::array<char, kSemanticWindowBufferSize> bytes {};
    const auto byte_count = std::min(window_bytes, bytes.size());
    if (byte_count < 8 || !SafeReadBytes(base, bytes.data(), byte_count))
    {
        return false;
    }

    std::uint32_t best_score = 0;
    std::size_t best_offset = 0;
    std::array<char, kResourceHandleQueryUpstreamProbeSampleCapacity> best_sample {};
    for (std::size_t start = 0; start + 4 < byte_count; ++start)
    {
        const auto first_byte = static_cast<unsigned char>(bytes[start]);
        if (first_byte < 0x20u || first_byte > 0x7Eu)
        {
            continue;
        }

        std::array<char, kResourceHandleQueryUpstreamProbeSampleCapacity> sample {};
        bool saw_printable = false;
        bool saw_alphanumeric = false;
        std::size_t length = 0;
        for (; length + 1 < sample.size() && start + length < byte_count; ++length)
        {
            const auto byte = static_cast<unsigned char>(bytes[start + length]);
            if (byte == 0)
            {
                break;
            }
            if (byte < 0x20u || byte > 0x7Eu)
            {
                length = 0;
                break;
            }

            sample[length] = static_cast<char>(byte);
            saw_printable = true;
            if ((byte >= '0' && byte <= '9') ||
                (byte >= 'A' && byte <= 'Z') ||
                (byte >= 'a' && byte <= 'z'))
            {
                saw_alphanumeric = true;
            }
        }

        if (!saw_printable || !saw_alphanumeric || length < 4)
        {
            continue;
        }

        sample[length] = '\0';
        const auto score = ScoreResourceHandleQuerySemanticSample(sample.data());
        if (score <= best_score)
        {
            continue;
        }

        best_score = score;
        best_offset = start;
        best_sample = sample;
    }

    if (best_score == 0)
    {
        return false;
    }

    CopyFixedCString(out, out_size, best_sample.data());
    out_offset = best_offset;
    out_score = best_score;
    return true;
}

std::uint32_t ScoreResourceHandleQuerySemanticRootLabel(const std::wstring& label) noexcept
{
    if (label.empty())
    {
        return 0;
    }

    std::uint32_t score = 0;
    if (label.find(L"source_world_token") != std::wstring::npos ||
        label.find(L"source_view_token") != std::wstring::npos)
    {
        score += 56;
    }
    if (label.find(L"donor_world_token") != std::wstring::npos ||
        label.find(L"donor_view_token") != std::wstring::npos)
    {
        score += 52;
    }
    if (label.find(L"resolved_target_world_handle") != std::wstring::npos ||
        label.find(L"resolved_target_view_handle") != std::wstring::npos)
    {
        score += 44;
    }
    if (label.find(L"source_world_handle") != std::wstring::npos ||
        label.find(L"source_view_handle") != std::wstring::npos)
    {
        score += 40;
    }
    if (label.find(L"donor_world_handle") != std::wstring::npos ||
        label.find(L"donor_view_handle") != std::wstring::npos)
    {
        score += 36;
    }
    if (label.find(L"upstream_focus_field") != std::wstring::npos)
    {
        score += 12;
    }
    else if (label.find(L"upstream_focus_base") != std::wstring::npos)
    {
        score += 4;
    }
    else if (label.find(L"upstream_focus") != std::wstring::npos)
    {
        score += 8;
    }
    if (label.find(L"[*+") != std::wstring::npos)
    {
        score += 8;
    }
    if (label.find(L"token") != std::wstring::npos)
    {
        score += 8;
    }
    if (label.find(L"live_rs_this") != std::wstring::npos)
    {
        score += 4;
    }
    if (label.find(L"[0x30]") != std::wstring::npos)
    {
        score += 8;
    }
    if (label.find(L"[0x38]") != std::wstring::npos)
    {
        score += 6;
    }
    if (label.find(L"[0x8]") != std::wstring::npos)
    {
        score += 4;
    }
    return score;
}

std::uint16_t ScoreResourceHandleQueryPointerOnlyCandidate(const void* candidate) noexcept
{
    if (candidate == nullptr ||
        reinterpret_cast<std::uintptr_t>(candidate) < kMinUserModePointer ||
        !IsReadablePointer(candidate) ||
        IsExecutablePointer(candidate))
    {
        return 0;
    }

    MEMORY_BASIC_INFORMATION region_info {};
    if (!TryQueryCommittedReadableRegion(candidate, region_info))
    {
        return 0;
    }

    int score = 2;
    if (region_info.Type == MEM_PRIVATE)
    {
        score += 8;
    }
    else if (region_info.Type == MEM_MAPPED)
    {
        score += 4;
    }
    else if (region_info.Type == MEM_IMAGE)
    {
        score += 1;
    }

    const auto candidate_value = reinterpret_cast<std::uintptr_t>(candidate);
    std::uint64_t raw_header = 0;
    if (SafeReadValue(candidate, raw_header))
    {
        if (raw_header == candidate_value)
        {
            score -= 8;
        }
        else if (raw_header >= kMinUserModePointer)
        {
            const auto* header_pointer =
                reinterpret_cast<const void*>(static_cast<std::uintptr_t>(raw_header));
            if (IsExecutablePointer(header_pointer))
            {
                score += 1;
            }
            else if (IsReadablePointer(header_pointer))
            {
                MEMORY_BASIC_INFORMATION header_region {};
                if (TryQueryCommittedReadableRegion(header_pointer, header_region))
                {
                    if (header_region.Type == MEM_PRIVATE)
                    {
                        score += 4;
                    }
                    else if (header_region.Type == MEM_MAPPED)
                    {
                        score += 2;
                    }
                }
            }
        }
    }

    std::uint32_t readable_child_count = 0;
    std::uint32_t private_child_count = 0;
    std::uint32_t noisy_child_count = 0;
    std::uint32_t ascii_child_count = 0;
    std::uint32_t resource_child_count = 0;
    std::uint32_t scene_inline_count = 0;
    std::uint32_t scene_child_count = 0;
    for (const auto offset : kResourceHandleQueryUpstreamFocusOffsets)
    {
        std::uint64_t raw_value = 0;
        const auto* field_address =
            reinterpret_cast<const std::uint8_t*>(candidate) + offset;
        char inline_sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
        if (TryCaptureAsciiSampleNoexcept(
                reinterpret_cast<const char*>(field_address),
                inline_sample,
                std::size(inline_sample)) &&
            IsResourceHandleQuerySceneSemanticNoiseText(inline_sample))
        {
            ++scene_inline_count;
        }

        if (!SafeReadValue(field_address, raw_value) ||
            raw_value < kMinUserModePointer ||
            raw_value == candidate_value)
        {
            continue;
        }

        const auto* pointed =
            reinterpret_cast<const void*>(static_cast<std::uintptr_t>(raw_value));
        if (!IsReadablePointer(pointed))
        {
            continue;
        }

        ++readable_child_count;
        if (IsExecutablePointer(pointed))
        {
            score -= 1;
            continue;
        }

        const auto scene_semantic_child =
            IsResourceHandleQuerySceneSemanticNoiseObject(pointed);

        MEMORY_BASIC_INFORMATION child_region {};
        if (TryQueryCommittedReadableRegion(pointed, child_region))
        {
            if (child_region.Type == MEM_PRIVATE)
            {
                score += 4;
                ++private_child_count;
            }
            else if (child_region.Type == MEM_MAPPED)
            {
                score += 2;
            }
            else if (child_region.Type == MEM_IMAGE)
            {
                score += 1;
            }
        }

        char child_sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
        if (TryCaptureAsciiSampleNoexcept(
                reinterpret_cast<const char*>(pointed),
                child_sample,
                std::size(child_sample)))
        {
            ++ascii_child_count;
            if (LooksLikeResourceSample(child_sample))
            {
                score += 10;
                ++resource_child_count;
            }
            else if (IsNoisyResourceHandleQueryUpstreamSample(child_sample) ||
                IsNoisyResourceHandleQueryPointerOnlyChildSample(child_sample))
            {
                ++noisy_child_count;
                score -= 2;
            }
            else
            {
                score += 1;
            }
        }
        else if (LooksLikeRuntimeRttiObjectPointer(pointed))
        {
            score += 2;
        }

        if (scene_semantic_child)
        {
            ++scene_child_count;
            ++noisy_child_count;
            score -= 8;
        }
    }

    if (readable_child_count == 0)
    {
        score -= 6;
    }
    if (private_child_count == 0 && region_info.Type != MEM_PRIVATE)
    {
        score -= 3;
    }
    if (resource_child_count == 0 &&
        private_child_count == 0 &&
        noisy_child_count >= ascii_child_count &&
        noisy_child_count != 0)
    {
        score -= 4;
    }
    if (scene_inline_count != 0)
    {
        score -= std::min<int>(8, static_cast<int>(scene_inline_count) * 2);
    }
    if (scene_child_count != 0)
    {
        score -= std::min<int>(16, static_cast<int>(scene_child_count) * 6);
    }

    if (score <= 0)
    {
        return 0;
    }

    return static_cast<std::uint16_t>(std::min(score, 0xFFFF));
}

void SnapshotResourceHandleQueryResultShape(
    const std::uint64_t result_handle,
    ResourceHandleQueryResultShapeKind& out_shape_kind,
    std::uint8_t& out_payload_mask,
    std::uint64_t& out_qword0,
    std::uint64_t& out_qword8,
    std::uint64_t& out_qword10) noexcept
{
    out_shape_kind = ResourceHandleQueryResultShapeKind::Unknown;
    out_payload_mask = 0;
    out_qword0 = 0;
    out_qword8 = 0;
    out_qword10 = 0;

    if (result_handle == 0)
    {
        out_shape_kind = ResourceHandleQueryResultShapeKind::Zero;
        return;
    }

    const auto result_pointer =
        reinterpret_cast<const void*>(static_cast<std::uintptr_t>(result_handle));
    if (IsExecutablePointer(result_pointer))
    {
        out_shape_kind = ResourceHandleQueryResultShapeKind::ExecutablePointer;
        return;
    }

    if (IsReadablePointer(result_pointer))
    {
        out_shape_kind = ResourceHandleQueryResultShapeKind::ReadableDataPointer;

        if (SafeReadValue(result_pointer, out_qword0))
        {
            out_payload_mask |= 0x1u;
        }

        if (SafeReadValue(
                reinterpret_cast<const std::uint8_t*>(result_pointer) + 0x8,
                out_qword8))
        {
            out_payload_mask |= 0x2u;
        }

        if (SafeReadValue(
                reinterpret_cast<const std::uint8_t*>(result_pointer) + 0x10,
                out_qword10))
        {
            out_payload_mask |= 0x4u;
        }
        return;
    }

    out_shape_kind =
        result_handle <= 0xFFFFFFFFull
            ? ResourceHandleQueryResultShapeKind::LowScalar
            : ResourceHandleQueryResultShapeKind::NonReadablePointer;
}

bool IsResourceHandleQueryPrimaryCaller(const void* address) noexcept
{
    if (address == nullptr)
    {
        return false;
    }

    const auto module = GetModuleFromAddress(address);
    if (module == nullptr)
    {
        return false;
    }

    const auto module_name = GetModuleFileNameOnly(module);
    if (_wcsicmp(module_name.c_str(), L"engine2.dll") != 0)
    {
        return false;
    }

    const auto module_span = GetModuleSpan(module);
    if (!module_span.has_value() || !PointerInModule(*module_span, address))
    {
        return false;
    }

    return IsExecutablePointer(address);
}

bool TryStepUnwindContextForResourceHandleQuery(CONTEXT& context) noexcept
{
    if (context.Rip < kMinUserModePointer || context.Rsp < kMinUserModePointer)
    {
        return false;
    }

    const auto previous_rip = context.Rip;
    const auto previous_rsp = context.Rsp;

    __try
    {
        DWORD64 image_base = 0;
        const auto runtime_function =
            RtlLookupFunctionEntry(context.Rip, &image_base, nullptr);
        if (runtime_function != nullptr)
        {
            PVOID handler_data = nullptr;
            DWORD64 establisher_frame = 0;
            KNONVOLATILE_CONTEXT_POINTERS context_pointers {};
            RtlVirtualUnwind(
                UNW_FLAG_NHANDLER,
                image_base,
                context.Rip,
                runtime_function,
                &context,
                &handler_data,
                &establisher_frame,
                &context_pointers);
        }
        else
        {
            DWORD64 return_address = 0;
            if (!SafeReadValue(reinterpret_cast<const void*>(context.Rsp), return_address) ||
                return_address < kMinUserModePointer)
            {
                return false;
            }

            context.Rip = return_address;
            context.Rsp += sizeof(DWORD64);
        }
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }

    if (context.Rip < kMinUserModePointer ||
        context.Rsp < kMinUserModePointer ||
        (context.Rip == previous_rip && context.Rsp == previous_rsp))
    {
        return false;
    }

    return true;
}

bool TryCaptureResourceHandleQueryCallerRegisterSeed(
    const std::uintptr_t caller_return_address,
    ResourceHandleQueryCallerRegisterSeed& out_seed) noexcept
{
    out_seed = {};
    if (!IsResourceHandleQueryPrimaryCaller(
            reinterpret_cast<const void*>(caller_return_address)))
    {
        return false;
    }

    CONTEXT context {};
    RtlCaptureContext(&context);

    for (std::uint32_t attempt = 0; attempt < 96; ++attempt)
    {
        if (!TryStepUnwindContextForResourceHandleQuery(context))
        {
            break;
        }

        if (context.Rip != caller_return_address)
        {
            continue;
        }

        out_seed.valid = true;
        out_seed.rip = static_cast<std::uintptr_t>(context.Rip);
        out_seed.rsp = static_cast<std::uintptr_t>(context.Rsp);
        out_seed.rbx = static_cast<std::uintptr_t>(context.Rbx);
        out_seed.rbp = static_cast<std::uintptr_t>(context.Rbp);
        out_seed.rsi = static_cast<std::uintptr_t>(context.Rsi);
        out_seed.rdi = static_cast<std::uintptr_t>(context.Rdi);
        out_seed.r12 = static_cast<std::uintptr_t>(context.R12);
        out_seed.r13 = static_cast<std::uintptr_t>(context.R13);
        out_seed.r14 = static_cast<std::uintptr_t>(context.R14);
        out_seed.r15 = static_cast<std::uintptr_t>(context.R15);
        return true;
    }

    return false;
}

std::uint32_t CaptureResourceHandleQueryPrimaryCallerChain(
    std::array<std::uintptr_t, kResourceHandleQueryCallerChainCapacity>& out_frames) noexcept
{
    out_frames.fill(0);

    CONTEXT context {};
    RtlCaptureContext(&context);

    const HMODULE self_module =
        GetModuleFromAddress(reinterpret_cast<const void*>(&CaptureResourceHandleQueryPrimaryCallerChain));
    bool chain_started = false;
    std::uint32_t count = 0;
    for (std::uint32_t attempt = 0; attempt < 96 && count < out_frames.size(); ++attempt)
    {
        if (!TryStepUnwindContextForResourceHandleQuery(context))
        {
            break;
        }

        const auto* frame = reinterpret_cast<const void*>(context.Rip);
        if (reinterpret_cast<std::uintptr_t>(frame) < kMinUserModePointer)
        {
            break;
        }

        if (GetModuleFromAddress(frame) == self_module)
        {
            continue;
        }

        if (!chain_started)
        {
            if (!IsResourceHandleQueryPrimaryCaller(frame))
            {
                continue;
            }

            chain_started = true;
        }

        const auto frame_value = reinterpret_cast<std::uintptr_t>(frame);
        if (count > 0 && out_frames[count - 1] == frame_value)
        {
            continue;
        }

        out_frames[count++] = frame_value;
    }

    return count;
}

void TryCaptureResourceHandleQueryPrimaryCallerChain(
    const std::uintptr_t caller_return_address) noexcept
{
    if (!IsResourceHandleQueryPrimaryCaller(reinterpret_cast<const void*>(caller_return_address)))
    {
        return;
    }

    auto& probe = g_hook_state.resource_handle_query_live_probe;
    std::uint32_t expected = kResourceHandleQueryCarrierCaptureNone;
    if (!probe.caller_chain_capture_state.compare_exchange_strong(
            expected,
            kResourceHandleQueryCarrierCaptureWriting,
            std::memory_order_acq_rel))
    {
        return;
    }

    probe.caller_chain_trigger_return_address = caller_return_address;
    probe.caller_chain_frame_count =
        CaptureResourceHandleQueryPrimaryCallerChain(probe.caller_chain_frames);
    probe.caller_chain_capture_state.store(
        kResourceHandleQueryCarrierCapturePending,
        std::memory_order_release);
}

bool TryCaptureAsciiSampleNoexcept(
    const char* address,
    char* out,
    const std::size_t out_size) noexcept
{
    if (out == nullptr || out_size < 8 || address == nullptr)
    {
        return false;
    }

    out[0] = '\0';
    if (reinterpret_cast<std::uintptr_t>(address) < kMinUserModePointer ||
        !IsReadablePointer(address))
    {
        return false;
    }

    bool saw_printable = false;
    bool saw_alphanumeric = false;
    std::size_t length = 0;
    for (; length + 1 < out_size; ++length)
    {
        char value = '\0';
        if (!SafeReadValue(address + length, value))
        {
            out[0] = '\0';
            return false;
        }

        if (value == '\0')
        {
            break;
        }

        const auto byte = static_cast<unsigned char>(value);
        if (byte < 0x20u || byte > 0x7Eu)
        {
            out[0] = '\0';
            return false;
        }

        out[length] = value;
        saw_printable = true;
        if ((byte >= '0' && byte <= '9') ||
            (byte >= 'A' && byte <= 'Z') ||
            (byte >= 'a' && byte <= 'z'))
        {
            saw_alphanumeric = true;
        }
    }

    if (!saw_printable || !saw_alphanumeric || length < 4)
    {
        out[0] = '\0';
        return false;
    }

    out[length] = '\0';
    return true;
}

bool LooksLikeResourceSample(const char* sample) noexcept
{
    if (sample == nullptr || sample[0] == '\0')
    {
        return false;
    }

    return std::strstr(sample, ".vmdl") != nullptr ||
        std::strstr(sample, ".vmdl_c") != nullptr ||
        std::strstr(sample, "models/") != nullptr ||
        std::strstr(sample, "weapons/") != nullptr ||
        std::strstr(sample, "materials/") != nullptr ||
        std::strstr(sample, "knife") != nullptr;
}

bool IsNoisyResourceHandleQueryUpstreamSample(const char* sample) noexcept
{
    if (sample == nullptr || sample[0] == '\0')
    {
        return true;
    }

    return std::strstr(sample, "CreateStringTable") != nullptr ||
        std::strstr(sample, "StringTable") != nullptr ||
        std::strstr(sample, "ProfileStorage") != nullptr ||
        std::strstr(sample, "StorageAvailable") != nullptr ||
        std::strstr(sample, "CSplitScreenService") != nullptr ||
        std::strstr(sample, "CInputService") != nullptr ||
        std::strcmp(sample, "engine2") == 0 ||
        std::strstr(sample, "varint") != nullptr ||
        std::strstr(sample, "Event") != nullptr ||
        IsResourceHandleQuerySceneSemanticNoiseText(sample);
}

bool TryVisitResourceHandleQueryUpstreamProbePointer(
    ResourceHandleQueryUpstreamProbeScratch& scratch,
    const void* pointer) noexcept
{
    if (pointer == nullptr)
    {
        return false;
    }

    const auto pointer_value = reinterpret_cast<std::uintptr_t>(pointer);
    if (pointer_value < kMinUserModePointer)
    {
        return false;
    }

    for (std::size_t index = 0; index < scratch.visited_count; ++index)
    {
        if (scratch.visited[index] == pointer)
        {
            return false;
        }
    }

    if (scratch.visited_count >= scratch.visited.size())
    {
        return false;
    }

    scratch.visited[scratch.visited_count++] = pointer;
    return true;
}

void TryAppendResourceHandleQueryUpstreamProbeSample(
    const char* label,
    const char* sample,
    const bool resource_like,
    const std::uintptr_t pointer_value,
    const std::uint16_t pointer_score,
    const ResourceHandleQueryUpstreamProbeSampleKind sample_kind) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    if (label == nullptr || sample == nullptr)
    {
        return;
    }

    const auto write_index = probe.upstream_probe_sample_count;
    if (write_index >= probe.upstream_probe_samples.size())
    {
        return;
    }

    auto& destination = probe.upstream_probe_samples[write_index];
    CopyFixedCString(destination.label.data(), destination.label.size(), label);
    CopyFixedCString(destination.sample.data(), destination.sample.size(), sample);
    destination.pointer_value = pointer_value;
    destination.pointer_score = pointer_score;
    destination.sample_kind = static_cast<std::uint8_t>(sample_kind);
    destination.resource_like = resource_like;
    probe.upstream_probe_sample_count =
        static_cast<std::uint32_t>(write_index + 1);
}

void CaptureResourceHandleQueryUpstreamFocusField(
    ResourceHandleQueryUpstreamFocusField& destination,
    const void* base,
    const std::size_t offset) noexcept
{
    destination = {};
    destination.offset = static_cast<std::uint32_t>(offset);
    if (base == nullptr)
    {
        return;
    }

    const auto* field_address =
        reinterpret_cast<const std::uint8_t*>(base) + offset;
    if (SafeReadValue(field_address, destination.raw_value))
    {
        destination.flags |= kResourceHandleQueryUpstreamFocusFieldFlagRawValid;
    }

    char sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
    if (TryCaptureAsciiSampleNoexcept(
            reinterpret_cast<const char*>(field_address),
            sample,
            std::size(sample)))
    {
        CopyFixedCString(
            destination.inline_sample.data(),
            destination.inline_sample.size(),
            sample);
        destination.flags |= kResourceHandleQueryUpstreamFocusFieldFlagInlineSample;
    }

    if ((destination.flags & kResourceHandleQueryUpstreamFocusFieldFlagRawValid) == 0 ||
        destination.raw_value < kMinUserModePointer)
    {
        return;
    }

    const auto* pointed =
        reinterpret_cast<const void*>(static_cast<std::uintptr_t>(destination.raw_value));
    if (IsReadablePointer(pointed))
    {
        destination.flags |= kResourceHandleQueryUpstreamFocusFieldFlagReadablePtr;
        if (!IsExecutablePointer(pointed))
        {
            destination.pointer_score = ScoreResourceHandleQueryPointerOnlyCandidate(pointed);
        }
    }
    if (IsExecutablePointer(pointed))
    {
        destination.flags |= kResourceHandleQueryUpstreamFocusFieldFlagExecutablePtr;
    }

    if (TryCaptureAsciiSampleNoexcept(
            reinterpret_cast<const char*>(pointed),
            sample,
            std::size(sample)))
    {
        CopyFixedCString(
            destination.pointed_sample.data(),
            destination.pointed_sample.size(),
            sample);
        destination.flags |= kResourceHandleQueryUpstreamFocusFieldFlagPointedSample;
    }
}

void TryCaptureResourceHandleQueryUpstreamFocus(
    const char* base_label,
    const char* hit_label,
    const char* hit_sample,
    const void* base,
    const std::size_t hit_offset,
    const std::uint16_t focus_score) noexcept
{
    const auto effective_focus_score =
        LooksLikeResourceSample(hit_sample)
            ? std::max<std::uint16_t>(
                  focus_score,
                  kResourceHandleQueryUpstreamPointerOnlyFocusMinScore)
            : focus_score;
    if (base == nullptr ||
        reinterpret_cast<std::uintptr_t>(base) < kMinUserModePointer ||
        !IsReadablePointer(base) ||
        effective_focus_score < kResourceHandleQueryUpstreamPointerOnlyFocusMinScore)
    {
        return;
    }

    auto& probe = g_hook_state.resource_handle_query_live_probe;
    for (;;)
    {
        const auto state =
            probe.upstream_focus_capture_state.load(std::memory_order_acquire);
        if (state == kResourceHandleQueryCarrierCaptureWriting)
        {
            return;
        }

        if (state != kResourceHandleQueryCarrierCaptureNone &&
            effective_focus_score <
                static_cast<std::uint16_t>(
                    probe.upstream_focus_score +
                    kResourceHandleQueryUpstreamPointerOnlyFocusUpgradeMargin))
        {
            return;
        }

        auto expected = state;
        if (probe.upstream_focus_capture_state.compare_exchange_strong(
                expected,
                kResourceHandleQueryCarrierCaptureWriting,
                std::memory_order_acq_rel))
        {
            break;
        }
    }

    probe.upstream_focus_base_ptr = reinterpret_cast<std::uintptr_t>(base);
    probe.upstream_focus_score = effective_focus_score;
    probe.upstream_focus_hit_offset = static_cast<std::uint32_t>(hit_offset);
    probe.upstream_focus_field_count = 0;
    probe.upstream_focus_base_label = {};
    probe.upstream_focus_hit_label = {};
    probe.upstream_focus_hit_sample = {};
    probe.upstream_focus_fields = {};
    CopyFixedCString(
        probe.upstream_focus_base_label.data(),
        probe.upstream_focus_base_label.size(),
        base_label);
    CopyFixedCString(
        probe.upstream_focus_hit_label.data(),
        probe.upstream_focus_hit_label.size(),
        hit_label);
    CopyFixedCString(
        probe.upstream_focus_hit_sample.data(),
        probe.upstream_focus_hit_sample.size(),
        hit_sample);

    const auto field_count =
        std::min(probe.upstream_focus_fields.size(), kResourceHandleQueryUpstreamFocusOffsets.size());
    for (std::size_t index = 0; index < field_count; ++index)
    {
        CaptureResourceHandleQueryUpstreamFocusField(
            probe.upstream_focus_fields[index],
            base,
            kResourceHandleQueryUpstreamFocusOffsets[index]);
    }
    probe.upstream_focus_field_count = static_cast<std::uint32_t>(field_count);
    probe.upstream_focus_capture_state.store(
        kResourceHandleQueryCarrierCapturePending,
        std::memory_order_release);
}

void LogResourceHandleQueryTokenRelationFor(
    const wchar_t* token_label,
    const std::uint64_t token_value,
    const ResourceHandleQueryLiveProbeState& probe) noexcept
{
    std::wstringstream summary_stream;
    summary_stream << L"Query live token relation[" << (token_label != nullptr ? token_label : L"?")
        << L"]: token=0x" << std::hex << std::uppercase << token_value
        << std::dec << std::nouppercase;

    const auto focus_base = probe.upstream_focus_base_ptr;
    if (focus_base >= kMinUserModePointer)
    {
        summary_stream << L", focus_base=" << FormatPointer(reinterpret_cast<void*>(focus_base))
            << L", focus_hit=" << NarrowToWide(std::string(probe.upstream_focus_hit_sample.data()));
    }
    else
    {
        summary_stream << L", focus_base=<none>";
    }

    if (token_value < kMinUserModePointer)
    {
        summary_stream << L", token_kind=low_scalar";
        nskinzcs2::Logger::Info(summary_stream.str());
        return;
    }

    auto* token_ptr =
        reinterpret_cast<const void*>(static_cast<std::uintptr_t>(token_value));
    summary_stream << L", token_region=" << DescribeReadableMemoryRegion(token_ptr, 16);
    if (focus_base >= kMinUserModePointer)
    {
        summary_stream << L", focus_region="
            << DescribeReadableMemoryRegion(reinterpret_cast<void*>(focus_base), 16);

        const auto delta =
            focus_base >= token_value
                ? static_cast<std::uint64_t>(focus_base - token_value)
                : static_cast<std::uint64_t>(token_value - focus_base);
        summary_stream << L", focus_delta=0x" << std::hex << std::uppercase << delta
            << std::dec << std::nouppercase;

        MEMORY_BASIC_INFORMATION token_info {};
        MEMORY_BASIC_INFORMATION focus_info {};
        const auto token_query_ok =
            VirtualQuery(token_ptr, &token_info, sizeof(token_info)) == sizeof(token_info);
        const auto focus_query_ok =
            VirtualQuery(reinterpret_cast<void*>(focus_base), &focus_info, sizeof(focus_info)) ==
            sizeof(focus_info);
        if (token_query_ok && focus_query_ok)
        {
            summary_stream << L", same_alloc="
                << (token_info.AllocationBase == focus_info.AllocationBase ? 1 : 0)
                << L", same_region_base="
                << (token_info.BaseAddress == focus_info.BaseAddress ? 1 : 0);
        }
    }
    nskinzcs2::Logger::Info(summary_stream.str());

    constexpr std::array<std::size_t, 6> kTokenFieldOffsets {{
        0x00, 0x08, 0x10, 0x18, 0x20, 0x28,
    }};
    for (const auto offset : kTokenFieldOffsets)
    {
        const auto* field_address =
            reinterpret_cast<const std::uint8_t*>(token_ptr) + offset;
        std::uint64_t raw_value = 0;
        const auto raw_valid = SafeReadValue(field_address, raw_value);
        char inline_sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
        char pointed_sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
        const auto inline_valid =
            TryCaptureAsciiSampleNoexcept(
                reinterpret_cast<const char*>(field_address),
                inline_sample,
                std::size(inline_sample));
        const auto pointed_valid =
            raw_valid &&
            raw_value >= kMinUserModePointer &&
            TryCaptureAsciiSampleNoexcept(
                reinterpret_cast<const char*>(static_cast<std::uintptr_t>(raw_value)),
                pointed_sample,
                std::size(pointed_sample));

        std::wstringstream field_stream;
        field_stream << L"Query live token relation[" << (token_label != nullptr ? token_label : L"?")
            << L"] field[0x" << std::hex << std::uppercase << offset
            << std::dec << std::nouppercase << L"]: raw=";
        if (raw_valid)
        {
            field_stream << L"0x" << std::hex << std::uppercase << raw_value
                << std::dec << std::nouppercase;
            if (raw_value >= kMinUserModePointer)
            {
                field_stream << L", owner="
                    << FormatModuleOwnerWithOffset(
                        reinterpret_cast<void*>(static_cast<std::uintptr_t>(raw_value)));
            }
            else
            {
                field_stream << L", owner=<low_scalar>";
            }
        }
        else
        {
            field_stream << L"<unreadable>";
        }

        if (inline_valid)
        {
            field_stream << L", inline=" << NarrowToWide(std::string(inline_sample));
        }
        if (pointed_valid)
        {
            field_stream << L", pointed=" << NarrowToWide(std::string(pointed_sample));
        }
        nskinzcs2::Logger::Info(field_stream.str());
    }
}

std::uint32_t SelectPreferredResourceHandleQueryRelationSamples(
    const std::array<std::uint32_t, kResourceHandleQueryResultSampleSummaryCount>& hook_indices,
    const std::array<std::uintptr_t, kResourceHandleQueryResultSampleSummaryCount>& caller_return_addresses,
    const std::uint32_t summary_end,
    const std::uint32_t rs_hook_index,
    std::array<std::uint32_t, kResourceHandleQueryResultSampleSummaryCount>& selected_indices,
    bool& primary_only) noexcept
{
    selected_indices.fill(0);
    primary_only = false;

    std::uint32_t selected_count = 0;
    for (std::uint32_t index = 0; index < summary_end; ++index)
    {
        if (hook_indices[index] != rs_hook_index ||
            !IsResourceHandleQueryPrimaryCaller(reinterpret_cast<const void*>(caller_return_addresses[index])))
        {
            continue;
        }

        selected_indices[selected_count++] = index;
    }

    if (selected_count != 0)
    {
        primary_only = true;
        return selected_count;
    }

    for (std::uint32_t index = 0; index < summary_end; ++index)
    {
        if (hook_indices[index] != rs_hook_index)
        {
            continue;
        }

        selected_indices[selected_count++] = index;
    }

    return selected_count;
}

void TryLogResourceHandleQueryTokenScalarRelation(
    const std::array<std::uint32_t, kResourceHandleQueryResultSampleSummaryCount>& hook_indices,
    const std::array<std::uintptr_t, kResourceHandleQueryResultSampleSummaryCount>& caller_return_addresses,
    const std::array<std::uintptr_t, kResourceHandleQueryResultSampleSummaryCount>& arg2_ptrs,
    const std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount>& arg3_values,
    const std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount>& arg4_values,
    const std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount>& handles,
    const std::uint32_t summary_end,
    const std::uint64_t source_world_token_snapshot,
    const std::uint64_t source_view_token_snapshot,
    const std::uint64_t donor_world_token_snapshot,
    const std::uint64_t donor_view_token_snapshot) noexcept
{
    if (summary_end == 0)
    {
        return;
    }

    const auto rs_hook_index_raw =
        ResourceHandleQueryHookIndex(ResourceHandleQueryInterfaceKind::ResourceSystem);
    if (rs_hook_index_raw == kInvalidResourceHandleQuerySlot)
    {
        return;
    }
    const auto rs_hook_index = static_cast<std::uint32_t>(rs_hook_index_raw);

    std::array<std::uint32_t, kResourceHandleQueryResultSampleSummaryCount> selected_indices {};
    bool primary_only = false;
    const auto selected_count = SelectPreferredResourceHandleQueryRelationSamples(
        hook_indices,
        caller_return_addresses,
        summary_end,
        rs_hook_index,
        selected_indices,
        primary_only);
    if (selected_count == 0)
    {
        return;
    }

    struct TokenCandidate
    {
        const wchar_t* label = nullptr;
        std::uint64_t value = 0;
        std::array<char, 96> preview {};
        bool preview_valid = false;
    };

    std::array<TokenCandidate, 4> unique_tokens {};
    std::size_t unique_token_count = 0;
    const std::array<std::pair<const wchar_t*, std::uint64_t>, 4> raw_tokens {{
        {L"source_world", source_world_token_snapshot},
        {L"source_view", source_view_token_snapshot},
        {L"donor_world", donor_world_token_snapshot},
        {L"donor_view", donor_view_token_snapshot},
    }};
    for (const auto& raw_token : raw_tokens)
    {
        if (raw_token.second < kMinUserModePointer)
        {
            continue;
        }

        bool duplicate = false;
        for (std::size_t existing = 0; existing < unique_token_count; ++existing)
        {
            if (unique_tokens[existing].value == raw_token.second)
            {
                duplicate = true;
                break;
            }
        }
        if (duplicate || unique_token_count >= unique_tokens.size())
        {
            continue;
        }

        auto& token = unique_tokens[unique_token_count];
        token.label = raw_token.first;
        token.value = raw_token.second;
        token.preview_valid = TryCaptureAsciiSampleNoexcept(
            reinterpret_cast<const char*>(static_cast<std::uintptr_t>(raw_token.second)),
            token.preview.data(),
            token.preview.size());
        ++unique_token_count;
    }

    if (unique_token_count == 0)
    {
        return;
    }

    auto& probe = g_hook_state.resource_handle_query_live_probe;
    std::uint32_t expected = kResourceHandleQueryCarrierCaptureNone;
    if (!probe.upstream_token_scalar_relation_capture_state.compare_exchange_strong(
            expected,
            kResourceHandleQueryCarrierCaptureWriting,
            std::memory_order_acq_rel))
    {
        return;
    }

    std::wstringstream entered_stream;
    entered_stream << L"Query live token scalar relation: entered, unique_tokens="
        << unique_token_count
        << L", summary_end=" << selected_count
        << L", sample_filter=" << (primary_only ? L"primary_only" : L"all_rs");
    nskinzcs2::Logger::Info(entered_stream.str());

    constexpr std::array<std::ptrdiff_t, 8> kPrefixOffsets {{
        -0x20, -0x1C, -0x18, -0x14, -0x10, -0x0C, -0x08, -0x04,
    }};

    for (std::size_t token_index = 0; token_index < unique_token_count; ++token_index)
    {
        const auto& token = unique_tokens[token_index];
        std::wstringstream summary_stream;
        summary_stream << L"Query live token scalar relation["
            << (token.label != nullptr ? token.label : L"?")
            << L"]: token=0x" << std::hex << std::uppercase << token.value
            << std::dec << std::nouppercase
            << L", preview_state=" << (token.preview_valid ? L"sampled" : L"unavailable")
            << L", preview=";
        if (token.preview_valid)
        {
            summary_stream << NarrowToWide(std::string(token.preview.data()));
        }
        else
        {
            summary_stream << L"<preview_unavailable>";
        }
        summary_stream
            << L", rs_samples=";

        bool first_sample = true;
        for (std::uint32_t selected = 0; selected < selected_count; ++selected)
        {
            const auto index = selected_indices[selected];

            if (!first_sample)
            {
                summary_stream << L" | ";
            }
            first_sample = false;
            summary_stream << L"s" << index
                << L":result=0x" << std::hex << std::uppercase << handles[index]
                << L",arg2=0x" << arg2_ptrs[index]
                << L",arg3=0x" << arg3_values[index]
                << L",arg4=0x" << arg4_values[index]
                << std::dec << std::nouppercase;
        }
        nskinzcs2::Logger::Info(summary_stream.str());

        bool any_match = false;
        for (const auto offset : kPrefixOffsets)
        {
            const auto* field_address =
                reinterpret_cast<const std::uint8_t*>(static_cast<std::uintptr_t>(token.value)) + offset;
            std::uint32_t raw32 = 0;
            if (!SafeReadValue(field_address, raw32))
            {
                continue;
            }

            std::wstringstream matches_stream;
            bool found_match = false;
            const auto append_match =
                [&](const wchar_t* text, const std::uint32_t sample_index)
                {
                    if (found_match)
                    {
                        matches_stream << L"|";
                    }
                    found_match = true;
                    matches_stream << text << L"[s" << sample_index << L"]";
                };

            for (std::uint32_t selected = 0; selected < selected_count; ++selected)
            {
                const auto index = selected_indices[selected];

                if (handles[index] <= 0xFFFFFFFFull &&
                    raw32 == static_cast<std::uint32_t>(handles[index]))
                {
                    append_match(L"result", index);
                }
                if (arg2_ptrs[index] <= 0xFFFFFFFFull &&
                    raw32 == static_cast<std::uint32_t>(arg2_ptrs[index]))
                {
                    append_match(L"arg2", index);
                }
                if (arg3_values[index] <= 0xFFFFFFFFull &&
                    raw32 == static_cast<std::uint32_t>(arg3_values[index]))
                {
                    append_match(L"arg3", index);
                }
                if (arg4_values[index] <= 0xFFFFFFFFull &&
                    raw32 == static_cast<std::uint32_t>(arg4_values[index]))
                {
                    append_match(L"arg4", index);
                }
            }

            if (!found_match)
            {
                continue;
            }

            any_match = true;
            std::wstringstream detail_stream;
            detail_stream << L"Query live token scalar relation["
                << (token.label != nullptr ? token.label : L"?")
                << L"] prefix[0x"
                << std::hex << std::uppercase
                << (offset < 0 ? static_cast<std::uint32_t>(-offset) : static_cast<std::uint32_t>(offset))
                << std::dec << std::nouppercase
                << L",sign=" << (offset < 0 ? L"-" : L"+")
                << L"]: raw32=0x" << std::hex << std::uppercase << raw32
                << std::dec << std::nouppercase
                << L", matches=" << matches_stream.str();
            nskinzcs2::Logger::Info(detail_stream.str());
        }

        if (!any_match)
        {
            std::wstringstream miss_stream;
            miss_stream << L"Query live token scalar relation["
                << (token.label != nullptr ? token.label : L"?")
                << L"]: no_prefix_scalar_match_against_live_rs_samples";
            nskinzcs2::Logger::Info(miss_stream.str());
        }
    }

    probe.upstream_token_scalar_relation_capture_state.store(
        kResourceHandleQueryCarrierCaptureLogged,
        std::memory_order_release);
}

void AppendResourceHandleQueryLowScalarUsage(
    std::array<std::uint32_t, 16>& values,
    std::array<std::wstring, 16>& usages,
    std::size_t& value_count,
    const std::uint64_t raw_value,
    const std::wstring& usage)
{
    if (usage.empty() || raw_value == 0 || raw_value > 0xFFFFFFFFull)
    {
        return;
    }

    const auto value = static_cast<std::uint32_t>(raw_value);
    for (std::size_t index = 0; index < value_count; ++index)
    {
        if (values[index] != value)
        {
            continue;
        }

        if (!usages[index].empty())
        {
            usages[index] += L"|";
        }
        usages[index] += usage;
        return;
    }

    if (value_count >= values.size())
    {
        return;
    }

    values[value_count] = value;
    usages[value_count] = usage;
    ++value_count;
}

