template <std::size_t N>
void AppendResourceHandleQueryUpstreamFocusFieldCarriers(
    std::array<std::uintptr_t, N>& values,
    std::array<std::wstring, N>& labels,
    std::size_t& value_count) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    const auto field_count = std::min<std::uint32_t>(
        probe.upstream_focus_field_count,
        static_cast<std::uint32_t>(probe.upstream_focus_fields.size()));
    for (std::uint32_t index = 0; index < field_count && value_count < values.size(); ++index)
    {
        const auto& field = probe.upstream_focus_fields[index];
        if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagReadablePtr) == 0 ||
            field.raw_value < kMinUserModePointer ||
            (field.flags & kResourceHandleQueryUpstreamFocusFieldFlagExecutablePtr) != 0 ||
            field.pointer_score < kResourceHandleQueryUpstreamPointerOnlySampleMinScore)
        {
            continue;
        }

        std::wstringstream label_stream;
        label_stream << L"upstream_focus_field[0x"
            << std::hex << std::uppercase << field.offset
            << std::dec << std::nouppercase << L"]";
        const auto label = label_stream.str();
        AppendResourceHandleQueryCarrierPointer(
            values,
            labels,
            value_count,
            field.raw_value,
            label.c_str());
    }
}

template <std::size_t N>
void AppendResourceHandleQueryCarrierReadablePointerFields(
    std::array<std::uintptr_t, N>& values,
    std::array<std::wstring, N>& labels,
    std::size_t& value_count,
    const std::uintptr_t carrier_value,
    const std::wstring& carrier_label,
    const std::size_t per_carrier_budget) noexcept
{
    if (carrier_value < kMinUserModePointer || carrier_label.empty() || per_carrier_budget == 0)
    {
        return;
    }

    constexpr std::array<std::size_t, 12> kDerivedPointerOffsets {{
        0x00, 0x08, 0x10, 0x18, 0x20, 0x28, 0x30, 0x38, 0x40, 0x48, 0x50, 0x58,
    }};

    struct ScoredCarrierField
    {
        std::size_t offset = 0;
        std::uintptr_t value = 0;
        std::uint16_t score = 0;
    };

    std::array<ScoredCarrierField, 12> best_fields {};
    std::size_t best_count = 0;
    for (const auto offset : kDerivedPointerOffsets)
    {
        if (value_count >= values.size())
        {
            break;
        }

        std::uint64_t raw_value = 0;
        const auto* field_address =
            reinterpret_cast<const void*>(carrier_value + static_cast<std::uintptr_t>(offset));
        if (!SafeReadValue(field_address, raw_value) || raw_value < kMinUserModePointer)
        {
            continue;
        }

        const auto nested_value = static_cast<std::uintptr_t>(raw_value);
        if (nested_value == carrier_value ||
            !IsReadablePointer(reinterpret_cast<const void*>(nested_value)))
        {
            continue;
        }

        const auto pointer_score =
            ScoreResourceHandleQueryPointerOnlyCandidate(
                reinterpret_cast<const void*>(nested_value));
        if (pointer_score < kResourceHandleQueryUpstreamPointerOnlySampleMinScore)
        {
            continue;
        }

        std::size_t insert_at = best_count;
        while (insert_at > 0 && best_fields[insert_at - 1].score < pointer_score)
        {
            if (insert_at < best_fields.size())
            {
                best_fields[insert_at] = best_fields[insert_at - 1];
            }
            --insert_at;
        }

        if (insert_at >= per_carrier_budget)
        {
            continue;
        }

        best_fields[insert_at] = {offset, nested_value, pointer_score};
        if (best_count < best_fields.size())
        {
            ++best_count;
        }

        if (best_count > per_carrier_budget)
        {
            best_count = per_carrier_budget;
        }
    }

    const auto append_count = std::min(best_count, per_carrier_budget);
    for (std::size_t index = 0; index < append_count && value_count < values.size(); ++index)
    {
        const auto& field = best_fields[index];
        std::wstringstream label_stream;
        label_stream << carrier_label
            << L"[*+0x" << std::hex << std::uppercase << field.offset
            << std::dec << std::nouppercase << L"]";
        const auto label = label_stream.str();
        AppendResourceHandleQueryCarrierPointer(
            values,
            labels,
            value_count,
            field.value,
            label.c_str());
    }
}

template <std::size_t N>
void TryLogResourceHandleQuerySemanticCarrierDrilldown(
    const std::array<std::uintptr_t, N>& carrier_values,
    const std::array<std::wstring, N>& carrier_labels,
    const std::size_t carrier_count) noexcept
{
    struct RootCandidate
    {
        std::uintptr_t value = 0;
        std::size_t carrier_index = 0;
        std::uint16_t pointer_score = 0;
        std::uint32_t label_score = 0;
    };

    std::array<RootCandidate, kResourceHandleQuerySemanticDrilldownRootBudget> roots {};
    std::size_t root_count = 0;
    for (std::size_t carrier_index = 0; carrier_index < carrier_count; ++carrier_index)
    {
        const auto carrier_value = carrier_values[carrier_index];
        if (carrier_value < kMinUserModePointer)
        {
            continue;
        }

        const auto pointer_score =
            ScoreResourceHandleQueryPointerOnlyCandidate(
                reinterpret_cast<const void*>(carrier_value));
        if (pointer_score < kResourceHandleQueryUpstreamPointerOnlyFocusMinScore)
        {
            continue;
        }

        const auto label_score =
            ScoreResourceHandleQuerySemanticRootLabel(carrier_labels[carrier_index]);
        if (label_score == 0)
        {
            continue;
        }

        bool duplicate = false;
        for (std::size_t existing = 0; existing < root_count; ++existing)
        {
            if (roots[existing].value == carrier_value)
            {
                duplicate = true;
                break;
            }
        }
        if (duplicate)
        {
            continue;
        }

        std::size_t insert_at = root_count;
        while (insert_at > 0)
        {
            const auto& previous = roots[insert_at - 1];
            if (previous.label_score > label_score ||
                (previous.label_score == label_score &&
                    previous.pointer_score >= pointer_score))
            {
                break;
            }

            if (insert_at < roots.size())
            {
                roots[insert_at] = previous;
            }
            --insert_at;
        }

        if (insert_at >= roots.size())
        {
            continue;
        }

        roots[insert_at] = {carrier_value, carrier_index, pointer_score, label_score};
        if (root_count < roots.size())
        {
            ++root_count;
        }
    }

    if (root_count == 0)
    {
        return;
    }

    struct DrillNode
    {
        std::uintptr_t value = 0;
        std::wstring label;
        std::uint16_t pointer_score = 0;
        std::size_t depth = 0;
    };

    std::size_t total_logs = 0;
    for (std::size_t root_index = 0;
         root_index < root_count && total_logs < kResourceHandleQuerySemanticDrilldownLogBudget;
         ++root_index)
    {
        const auto& root = roots[root_index];
        const auto& root_label = carrier_labels[root.carrier_index];
        std::wstringstream root_stream;
        root_stream << L"Query live semantic drilldown root[" << root_label
            << L"]: ptr=" << FormatPointer(reinterpret_cast<void*>(root.value))
            << L", score=" << root.pointer_score
            << L", label_score=" << root.label_score
            << L", owner=" << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(root.value))
            << L", region=" << DescribeReadableMemoryRegion(reinterpret_cast<void*>(root.value), 24);
        nskinzcs2::Logger::Info(root_stream.str());

        std::array<DrillNode, kResourceHandleQuerySemanticDrilldownNodeBudget> queue {};
        std::array<std::uintptr_t, kResourceHandleQuerySemanticDrilldownNodeBudget> visited {};
        std::size_t visited_count = 0;
        std::size_t queue_read = 0;
        std::size_t queue_write = 0;
        queue[queue_write++] = {root.value, root_label, root.pointer_score, 0};
        visited[visited_count++] = root.value;

        while (queue_read < queue_write &&
            total_logs < kResourceHandleQuerySemanticDrilldownLogBudget)
        {
            const auto node = queue[queue_read++];
            if (node.value < kMinUserModePointer)
            {
                continue;
            }

            char node_window_sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
            std::size_t node_window_offset = 0;
            std::uint32_t node_window_score = 0;
            if (TryCaptureInterestingResourceHandleQuerySemanticWindowSample(
                    reinterpret_cast<const void*>(node.value),
                    kResourceHandleQuerySemanticDrilldownNodeWindowBytes,
                    node_window_sample,
                    std::size(node_window_sample),
                    node_window_offset,
                    node_window_score))
            {
                std::wstringstream node_stream;
                node_stream << L"Query live semantic drilldown[" << node.label
                    << L"]: kind=node_window, sample="
                    << NarrowToWide(std::string(node_window_sample))
                    << L", node=" << FormatPointer(reinterpret_cast<void*>(node.value))
                    << L", depth=" << node.depth
                    << L", offset=0x" << std::hex << std::uppercase << node_window_offset
                    << std::dec << std::nouppercase
                    << L", score=" << node_window_score;
                nskinzcs2::Logger::Info(node_stream.str());
                ++total_logs;
                if (total_logs >= kResourceHandleQuerySemanticDrilldownLogBudget)
                {
                    break;
                }
            }

            for (const auto offset : kResourceHandleQueryUpstreamFocusOffsets)
            {
                if (total_logs >= kResourceHandleQuerySemanticDrilldownLogBudget)
                {
                    break;
                }

                const auto* field_address =
                    reinterpret_cast<const std::uint8_t*>(node.value) + offset;

                char inline_sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
                if (TryCaptureAsciiSampleNoexcept(
                        reinterpret_cast<const char*>(field_address),
                        inline_sample,
                        std::size(inline_sample)) &&
                    LooksLikeInterestingResourceHandleQuerySemanticSample(inline_sample))
                {
                    std::wstringstream field_stream;
                    field_stream << L"Query live semantic drilldown[" << node.label
                        << L"] field[0x" << std::hex << std::uppercase << offset
                        << std::dec << std::nouppercase
                        << L"]: kind=inline, sample="
                        << NarrowToWide(std::string(inline_sample))
                        << L", node=" << FormatPointer(reinterpret_cast<void*>(node.value))
                        << L", depth=" << node.depth;
                    nskinzcs2::Logger::Info(field_stream.str());
                    ++total_logs;
                    if (total_logs >= kResourceHandleQuerySemanticDrilldownLogBudget)
                    {
                        break;
                    }
                }

                std::uint64_t raw_value = 0;
                if (!SafeReadValue(field_address, raw_value) || raw_value < kMinUserModePointer)
                {
                    continue;
                }

                const auto pointed_value = static_cast<std::uintptr_t>(raw_value);
                const auto* pointed =
                    reinterpret_cast<const void*>(pointed_value);
                if (!IsReadablePointer(pointed))
                {
                    continue;
                }

                char pointed_sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
                if (TryCaptureAsciiSampleNoexcept(
                        reinterpret_cast<const char*>(pointed),
                        pointed_sample,
                        std::size(pointed_sample)) &&
                    LooksLikeInterestingResourceHandleQuerySemanticSample(pointed_sample))
                {
                    const auto pointed_sample_score =
                        ScoreResourceHandleQuerySemanticSample(pointed_sample);
                    std::wstringstream field_stream;
                    field_stream << L"Query live semantic drilldown[" << node.label
                        << L"] field[0x" << std::hex << std::uppercase << offset
                        << std::dec << std::nouppercase
                        << L"]: kind=pointed, ptr=" << FormatPointer(reinterpret_cast<void*>(pointed_value))
                        << L", sample=" << NarrowToWide(std::string(pointed_sample))
                        << L", owner=" << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(pointed_value))
                        << L", depth=" << node.depth
                        << L", ptr_score="
                        << ScoreResourceHandleQueryPointerOnlyCandidate(pointed)
                        << L", sample_score=" << pointed_sample_score;
                    nskinzcs2::Logger::Info(field_stream.str());
                    ++total_logs;
                    if (total_logs >= kResourceHandleQuerySemanticDrilldownLogBudget)
                    {
                        break;
                    }
                }

                char pointed_window_sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
                std::size_t pointed_window_offset = 0;
                std::uint32_t pointed_window_score = 0;
                if (TryCaptureInterestingResourceHandleQuerySemanticWindowSample(
                        pointed,
                        kResourceHandleQuerySemanticDrilldownPointedWindowBytes,
                        pointed_window_sample,
                        std::size(pointed_window_sample),
                        pointed_window_offset,
                        pointed_window_score))
                {
                    const auto exact_pointed_score =
                        ScoreResourceHandleQuerySemanticSample(pointed_sample);
                    if (pointed_window_score > exact_pointed_score ||
                        std::strcmp(pointed_window_sample, pointed_sample) != 0)
                    {
                        std::wstringstream field_stream;
                        field_stream << L"Query live semantic drilldown[" << node.label
                            << L"] field[0x" << std::hex << std::uppercase << offset
                            << std::dec << std::nouppercase
                            << L"]: kind=pointed_window, ptr="
                            << FormatPointer(reinterpret_cast<void*>(pointed_value))
                            << L", sample=" << NarrowToWide(std::string(pointed_window_sample))
                            << L", owner=" << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(pointed_value))
                            << L", depth=" << node.depth
                            << L", window_offset=0x" << std::hex << std::uppercase
                            << pointed_window_offset
                            << std::dec << std::nouppercase
                            << L", ptr_score="
                            << ScoreResourceHandleQueryPointerOnlyCandidate(pointed)
                            << L", sample_score=" << pointed_window_score;
                        nskinzcs2::Logger::Info(field_stream.str());
                        ++total_logs;
                        if (total_logs >= kResourceHandleQuerySemanticDrilldownLogBudget)
                        {
                            break;
                        }
                    }
                }

                if (node.depth + 1 >= kResourceHandleQuerySemanticDrilldownDepth ||
                    queue_write >= queue.size() ||
                    IsExecutablePointer(pointed))
                {
                    continue;
                }

                const auto child_score =
                    ScoreResourceHandleQueryPointerOnlyCandidate(pointed);
                if (child_score < kResourceHandleQueryUpstreamPointerOnlyFocusMinScore)
                {
                    continue;
                }

                bool seen = false;
                for (std::size_t visited_index = 0; visited_index < visited_count; ++visited_index)
                {
                    if (visited[visited_index] == pointed_value)
                    {
                        seen = true;
                        break;
                    }
                }
                if (seen || visited_count >= visited.size())
                {
                    continue;
                }

                std::wstringstream child_label_stream;
                child_label_stream << node.label
                    << L"[*+0x" << std::hex << std::uppercase << offset
                    << std::dec << std::nouppercase << L"]";
                queue[queue_write++] = {
                    pointed_value,
                    child_label_stream.str(),
                    child_score,
                    node.depth + 1};
                visited[visited_count++] = pointed_value;
            }
        }
    }
}

bool IsResourceHandleQuerySharedParentInterestingLabel(const std::wstring& label) noexcept
{
    if (label.empty())
    {
        return false;
    }

    const auto family_mask =
        (label.find(L"source_") != std::wstring::npos ? 0x1u : 0u) |
        (label.find(L"donor_") != std::wstring::npos ? 0x2u : 0u) |
        (label.find(L"target_") != std::wstring::npos ? 0x4u : 0u);
    return family_mask != 0 && label.find(L"handle") != std::wstring::npos;
}

std::uint32_t ResourceHandleQuerySharedParentFamilyMask(const std::wstring& label) noexcept
{
    std::uint32_t family_mask = 0;
    if (label.find(L"source_") != std::wstring::npos)
    {
        family_mask |= 0x1u;
    }
    if (label.find(L"donor_") != std::wstring::npos)
    {
        family_mask |= 0x2u;
    }
    if (label.find(L"target_") != std::wstring::npos)
    {
        family_mask |= 0x4u;
    }
    if (label.find(L"upstream_") != std::wstring::npos ||
        label.find(L"live_rs_this") != std::wstring::npos)
    {
        family_mask |= 0x8u;
    }
    return family_mask;
}

std::wstring BuildResourceHandleQuerySharedParentFamilyText(const std::uint32_t family_mask)
{
    std::wstring text;
    const auto append = [&](const wchar_t* label)
    {
        if (label == nullptr)
        {
            return;
        }

        if (!text.empty())
        {
            text += L"|";
        }
        text += label;
    };

    if ((family_mask & 0x1u) != 0)
    {
        append(L"source");
    }
    if ((family_mask & 0x2u) != 0)
    {
        append(L"donor");
    }
    if ((family_mask & 0x4u) != 0)
    {
        append(L"target");
    }
    if ((family_mask & 0x8u) != 0)
    {
        append(L"upstream");
    }

    return !text.empty() ? text : L"unknown";
}

bool TryResolveResourceHandleQuerySharedParentObjectBase(
    const std::uintptr_t reference_address,
    std::uintptr_t& out_parent_base,
    std::size_t& out_child_offset,
    std::uintptr_t& out_vtable) noexcept
{
    out_parent_base = 0;
    out_child_offset = 0;
    out_vtable = 0;
    if (reference_address < kMinUserModePointer)
    {
        return false;
    }

    constexpr std::size_t kParentBacktrackBytes = 0x80u;
    for (std::size_t backtrack = 0; backtrack <= kParentBacktrackBytes; backtrack += sizeof(void*))
    {
        if (reference_address < backtrack)
        {
            break;
        }

        const auto candidate_base = reference_address - backtrack;
        const auto* candidate_object = reinterpret_cast<const void*>(candidate_base);
        if (!LooksLikeRuntimeRttiObjectPointer(candidate_object) ||
            IsResourceHandleQuerySceneSemanticNoiseObject(candidate_object))
        {
            continue;
        }

        void** vtable = nullptr;
        if (!SafeReadValue(candidate_object, vtable) || vtable == nullptr)
        {
            continue;
        }

        out_parent_base = candidate_base;
        out_child_offset = backtrack;
        out_vtable = reinterpret_cast<std::uintptr_t>(vtable);
        return true;
    }

    return false;
}

template <std::size_t ScalarN, std::size_t CarrierN>
void TryLogResourceHandleQuerySharedParentRelation(
    const std::array<std::uint32_t, ScalarN>& scalar_values,
    const std::array<std::wstring, ScalarN>& scalar_usages,
    const std::size_t scalar_count,
    const std::array<std::uintptr_t, CarrierN>& carrier_values,
    const std::array<std::wstring, CarrierN>& carrier_labels,
    const std::size_t carrier_count) noexcept
{
    if (scalar_count == 0 || carrier_count == 0)
    {
        return;
    }

    struct RootCandidate
    {
        std::uintptr_t value = 0;
        std::size_t carrier_index = 0;
        std::uint16_t pointer_score = 0;
        std::uint32_t label_score = 0;
        std::uint32_t family_mask = 0;
    };

    constexpr std::size_t kRootBudget = 6u;
    std::array<RootCandidate, kRootBudget> roots {};
    std::size_t root_count = 0;
    bool used_strict_roots = false;
    const auto try_select_roots =
        [&](const bool strict_labels) noexcept
        {
            roots = {};
            root_count = 0;

            for (std::size_t carrier_index = 0; carrier_index < carrier_count; ++carrier_index)
            {
                const auto carrier_value = carrier_values[carrier_index];
                if (carrier_value < kMinUserModePointer)
                {
                    continue;
                }

                const auto& carrier_label = carrier_labels[carrier_index];
                if (strict_labels &&
                    !IsResourceHandleQuerySharedParentInterestingLabel(carrier_label))
                {
                    continue;
                }

                const auto family_mask =
                    ResourceHandleQuerySharedParentFamilyMask(carrier_label);
                if (family_mask == 0)
                {
                    continue;
                }

                const auto pointer_score =
                    ScoreResourceHandleQueryPointerOnlyCandidate(
                        reinterpret_cast<const void*>(carrier_value));
                if (pointer_score < kResourceHandleQueryUpstreamPointerOnlyFocusMinScore)
                {
                    continue;
                }

                const auto label_score =
                    ScoreResourceHandleQuerySemanticRootLabel(carrier_label);
                if (label_score == 0)
                {
                    continue;
                }

                bool duplicate = false;
                for (std::size_t existing = 0; existing < root_count; ++existing)
                {
                    if (roots[existing].value == carrier_value)
                    {
                        duplicate = true;
                        break;
                    }
                }
                if (duplicate)
                {
                    continue;
                }

                std::size_t insert_at = root_count;
                while (insert_at > 0)
                {
                    const auto& previous = roots[insert_at - 1];
                    if (previous.label_score > label_score ||
                        (previous.label_score == label_score &&
                            previous.pointer_score >= pointer_score))
                    {
                        break;
                    }

                    if (insert_at < roots.size())
                    {
                        roots[insert_at] = previous;
                    }
                    --insert_at;
                }

                if (insert_at >= roots.size())
                {
                    continue;
                }

                roots[insert_at] = {
                    carrier_value,
                    carrier_index,
                    pointer_score,
                    label_score,
                    family_mask};
                if (root_count < roots.size())
                {
                    ++root_count;
                }
            }

            return root_count != 0;
        };

    used_strict_roots = try_select_roots(true);
    if (root_count == 0)
    {
        used_strict_roots = false;
        if (!try_select_roots(false))
        {
            return;
        }
    }

    auto& probe = g_hook_state.resource_handle_query_live_probe;
    std::uint32_t expected = kResourceHandleQueryCarrierCaptureNone;
    if (!probe.upstream_shared_parent_capture_state.compare_exchange_strong(
            expected,
            kResourceHandleQueryCarrierCaptureWriting,
            std::memory_order_acq_rel))
    {
        return;
    }

    const auto finalize_capture = [&]() noexcept
    {
        probe.upstream_shared_parent_capture_state.store(
            kResourceHandleQueryCarrierCaptureLogged,
            std::memory_order_release);
    };

    std::wstringstream entered_stream;
    entered_stream << L"Query live shared-parent relation: entered, unique_scalars="
        << scalar_count
        << L", roots=" << static_cast<std::uint32_t>(root_count)
        << L", carriers=" << static_cast<std::uint32_t>(carrier_count)
        << L", root_filter=" << (used_strict_roots ? L"handle_only" : L"family_fallback")
        << L", values=";
    for (std::size_t index = 0; index < scalar_count; ++index)
    {
        if (index != 0)
        {
            entered_stream << L" | ";
        }
        entered_stream << L"0x" << std::hex << std::uppercase << scalar_values[index]
            << std::dec << std::nouppercase
            << L"=" << scalar_usages[index];
    }
    nskinzcs2::Logger::Info(entered_stream.str());

    struct ParentCandidate
    {
        std::size_t carrier_index = 0;
        std::uint32_t family_mask = 0;
        std::uintptr_t reference_address = 0;
        std::uintptr_t parent_base = 0;
        std::uintptr_t vtable = 0;
        std::size_t child_offset = 0;
        const wchar_t* reference_window = nullptr;
        bool resolved_parent = false;
        std::size_t scalar_match_count = 0;
        std::array<std::uint16_t, 4> scalar_indices {};
        std::array<std::ptrdiff_t, 4> scalar_offsets {};
        bool semantic_valid = false;
        std::array<char, kResourceHandleQueryUpstreamProbeSampleCapacity> semantic_sample {};
        std::size_t semantic_offset = 0;
        std::uint32_t semantic_score = 0;
    };

    constexpr std::uintptr_t kRootLocalWindowBefore = 0x100u;
    constexpr std::uintptr_t kRootLocalWindowAfter = 0x100u;
    constexpr std::size_t kRootRegionHeadWindowBytes = 0x300u;
    constexpr std::size_t kRootAllocationHeadWindowBytes = 0x300u;
    constexpr std::uintptr_t kParentScalarWindowBefore = 0x80u;
    constexpr std::uintptr_t kParentScalarWindowAfter = 0x180u;
    constexpr std::size_t kParentSemanticWindowBytes = 0xA0u;
    constexpr std::size_t kParentCandidateBudget = 20u;
    constexpr std::size_t kParentCandidatesPerRootBudget = 6u;

    std::array<ParentCandidate, kParentCandidateBudget> parent_candidates {};
    std::size_t parent_candidate_count = 0;
    std::size_t total_scalar_match_count = 0;

    const auto add_parent_candidate =
        [&](const RootCandidate& root,
            const std::uintptr_t reference_address,
            const wchar_t* reference_window) noexcept
        {
            if (reference_address < kMinUserModePointer ||
                parent_candidate_count >= parent_candidates.size())
            {
                return false;
            }

            for (std::size_t existing = 0; existing < parent_candidate_count; ++existing)
            {
                if (parent_candidates[existing].carrier_index == root.carrier_index &&
                    parent_candidates[existing].reference_address == reference_address)
                {
                    return false;
                }
            }

            ParentCandidate candidate {};
            candidate.carrier_index = root.carrier_index;
            candidate.family_mask = root.family_mask;
            candidate.reference_address = reference_address;
            candidate.reference_window = reference_window;
            candidate.resolved_parent =
                TryResolveResourceHandleQuerySharedParentObjectBase(
                    reference_address,
                    candidate.parent_base,
                    candidate.child_offset,
                    candidate.vtable);
            if (!candidate.resolved_parent)
            {
                candidate.parent_base = reference_address;
                candidate.child_offset = 0;
                candidate.vtable = 0;
            }

            MEMORY_BASIC_INFORMATION parent_info {};
            if (!TryQueryCommittedReadableRegion(
                    reinterpret_cast<const void*>(candidate.parent_base),
                    parent_info))
            {
                return false;
            }

            const auto region_start =
                reinterpret_cast<std::uintptr_t>(parent_info.BaseAddress);
            const auto region_end = region_start + parent_info.RegionSize;
            if (region_end <= region_start)
            {
                return false;
            }

            const auto scalar_scan_start =
                candidate.resolved_parent
                    ? std::max(region_start, candidate.parent_base)
                    : std::max(
                          region_start,
                          reference_address > kParentScalarWindowBefore
                              ? reference_address - kParentScalarWindowBefore
                              : region_start);
            const auto scalar_scan_end =
                candidate.resolved_parent
                    ? std::min(
                          region_end,
                          candidate.parent_base +
                              static_cast<std::uintptr_t>(kParentScalarWindowAfter))
                    : std::min(
                          region_end,
                          reference_address +
                              static_cast<std::uintptr_t>(kParentScalarWindowAfter));

            std::array<bool, ScalarN> scalar_seen {};
            for (auto address = scalar_scan_start;
                 address + sizeof(std::uint32_t) <= scalar_scan_end;
                 ++address)
            {
                std::uint32_t raw32 = 0;
                if (!SafeReadValue(reinterpret_cast<const void*>(address), raw32))
                {
                    continue;
                }

                for (std::size_t scalar_index = 0; scalar_index < scalar_count; ++scalar_index)
                {
                    if (scalar_seen[scalar_index] || raw32 != scalar_values[scalar_index])
                    {
                        continue;
                    }

                    scalar_seen[scalar_index] = true;
                    ++total_scalar_match_count;
                    if (candidate.scalar_match_count < candidate.scalar_indices.size())
                    {
                        candidate.scalar_indices[candidate.scalar_match_count] =
                            static_cast<std::uint16_t>(scalar_index);
                        candidate.scalar_offsets[candidate.scalar_match_count] =
                            static_cast<std::ptrdiff_t>(address) -
                            static_cast<std::ptrdiff_t>(candidate.parent_base);
                        ++candidate.scalar_match_count;
                    }
                }
            }

            candidate.semantic_valid =
                TryCaptureInterestingResourceHandleQuerySemanticWindowSample(
                    reinterpret_cast<const void*>(candidate.parent_base),
                    kParentSemanticWindowBytes,
                    candidate.semantic_sample.data(),
                    candidate.semantic_sample.size(),
                    candidate.semantic_offset,
                    candidate.semantic_score);

            if (!candidate.resolved_parent &&
                candidate.scalar_match_count == 0 &&
                !candidate.semantic_valid)
            {
                return false;
            }

            parent_candidates[parent_candidate_count++] = candidate;
            return true;
        };

    for (std::size_t root_index = 0; root_index < root_count; ++root_index)
    {
        const auto& root = roots[root_index];
        const auto* root_ptr = reinterpret_cast<const void*>(root.value);

        std::wstringstream root_stream;
        root_stream << L"Query live shared-parent root[" << carrier_labels[root.carrier_index]
            << L"]: ptr=" << FormatPointer(const_cast<void*>(root_ptr))
            << L", family="
            << BuildResourceHandleQuerySharedParentFamilyText(root.family_mask)
            << L", score=" << root.pointer_score
            << L", label_score=" << root.label_score
            << L", owner=" << FormatModuleOwnerWithOffset(const_cast<void*>(root_ptr))
            << L", region=" << DescribeReadableMemoryRegion(root_ptr, 24);
        nskinzcs2::Logger::Info(root_stream.str());

        MEMORY_BASIC_INFORMATION root_info {};
        if (!TryQueryCommittedReadableRegion(root_ptr, root_info))
        {
            continue;
        }

        const auto region_start = reinterpret_cast<std::uintptr_t>(root_info.BaseAddress);
        const auto region_end = region_start + root_info.RegionSize;
        if (region_end <= region_start)
        {
            continue;
        }

        std::size_t root_candidate_count = 0;
        const auto scan_reference_window =
            [&](const wchar_t* window_label,
                std::uintptr_t window_start,
                std::uintptr_t window_end) noexcept
            {
                if (window_label == nullptr ||
                    window_start >= window_end ||
                    root_candidate_count >= kParentCandidatesPerRootBudget ||
                    parent_candidate_count >= parent_candidates.size())
                {
                    return;
                }

                auto address =
                    (window_start + sizeof(std::uintptr_t) - 1) &
                    ~(static_cast<std::uintptr_t>(sizeof(std::uintptr_t) - 1));
                for (; address + sizeof(std::uintptr_t) <= window_end; address += sizeof(std::uintptr_t))
                {
                    std::uintptr_t raw_pointer = 0;
                    if (!SafeReadValue(reinterpret_cast<const void*>(address), raw_pointer) ||
                        raw_pointer != root.value)
                    {
                        continue;
                    }

                    if (add_parent_candidate(root, address, window_label))
                    {
                        ++root_candidate_count;
                        if (root_candidate_count >= kParentCandidatesPerRootBudget ||
                            parent_candidate_count >= parent_candidates.size())
                        {
                            return;
                        }
                    }
                }
            };

        const auto local_start =
            std::max(region_start, root.value > kRootLocalWindowBefore
                ? root.value - kRootLocalWindowBefore
                : region_start);
        const auto local_end =
            std::min(region_end, root.value + kRootLocalWindowAfter);
        scan_reference_window(L"local", local_start, local_end);

        const auto region_head_end =
            std::min(region_end, region_start + static_cast<std::uintptr_t>(kRootRegionHeadWindowBytes));
        if (region_head_end > region_start)
        {
            scan_reference_window(L"region_head", region_start, region_head_end);
        }

        MEMORY_BASIC_INFORMATION allocation_info {};
        if (root_info.AllocationBase != nullptr &&
            TryQueryCommittedReadableRegion(root_info.AllocationBase, allocation_info))
        {
            const auto allocation_start =
                reinterpret_cast<std::uintptr_t>(allocation_info.BaseAddress);
            const auto allocation_end = allocation_start + allocation_info.RegionSize;
            const auto allocation_head_end =
                std::min(
                    allocation_end,
                    allocation_start + static_cast<std::uintptr_t>(kRootAllocationHeadWindowBytes));
            if (allocation_head_end > allocation_start)
            {
                scan_reference_window(L"allocation_head", allocation_start, allocation_head_end);
            }
        }
    }

    struct TemplateGroup
    {
        std::uintptr_t vtable = 0;
        std::size_t child_offset = 0;
        std::uint32_t family_mask = 0;
        std::size_t candidate_count = 0;
        std::array<bool, ScalarN> scalar_hits {};
        std::uintptr_t exemplar_parent = 0;
    };

    std::array<TemplateGroup, kParentCandidateBudget> template_groups {};
    std::size_t template_group_count = 0;
    const auto add_to_template_group =
        [&](const ParentCandidate& candidate) noexcept
        {
            if (!candidate.resolved_parent ||
                candidate.vtable < kMinUserModePointer)
            {
                return;
            }

            std::size_t group_index = template_group_count;
            for (std::size_t existing = 0; existing < template_group_count; ++existing)
            {
                if (template_groups[existing].vtable == candidate.vtable &&
                    template_groups[existing].child_offset == candidate.child_offset)
                {
                    group_index = existing;
                    break;
                }
            }

            if (group_index == template_group_count)
            {
                if (template_group_count >= template_groups.size())
                {
                    return;
                }

                template_groups[group_index].vtable = candidate.vtable;
                template_groups[group_index].child_offset = candidate.child_offset;
                template_groups[group_index].exemplar_parent = candidate.parent_base;
                ++template_group_count;
            }

            auto& group = template_groups[group_index];
            group.family_mask |= candidate.family_mask;
            ++group.candidate_count;
            for (std::size_t scalar_match = 0;
                 scalar_match < candidate.scalar_match_count;
                 ++scalar_match)
            {
                const auto scalar_index = candidate.scalar_indices[scalar_match];
                if (scalar_index < scalar_count)
                {
                    group.scalar_hits[scalar_index] = true;
                }
            }
        };

    for (std::size_t candidate_index = 0;
         candidate_index < parent_candidate_count;
         ++candidate_index)
    {
        add_to_template_group(parent_candidates[candidate_index]);
    }

    for (std::size_t candidate_index = 0;
         candidate_index < parent_candidate_count;
         ++candidate_index)
    {
        const auto& candidate = parent_candidates[candidate_index];
        std::wstringstream candidate_stream;
        candidate_stream << L"Query live shared-parent candidate["
            << carrier_labels[candidate.carrier_index]
            << L"]: ref="
            << FormatPointer(reinterpret_cast<void*>(candidate.reference_address))
            << L", window="
            << (candidate.reference_window != nullptr ? candidate.reference_window : L"unknown")
            << L", parent=" << FormatPointer(reinterpret_cast<void*>(candidate.parent_base))
            << L", resolved=" << (candidate.resolved_parent ? 1 : 0)
            << L", child_offset=0x" << std::hex << std::uppercase << candidate.child_offset
            << std::dec << std::nouppercase
            << L", family="
            << BuildResourceHandleQuerySharedParentFamilyText(candidate.family_mask)
            << L", owner="
            << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(candidate.parent_base))
            << L", rtti="
            << (candidate.resolved_parent
                    ? BuildRuntimeEntityRttiDescriptor(
                          reinterpret_cast<void*>(candidate.parent_base))
                    : std::wstring(L"unresolved"))
            << L", region="
            << DescribeReadableMemoryRegion(reinterpret_cast<void*>(candidate.parent_base), 24)
            << L", scalar_hits=";
        if (candidate.scalar_match_count == 0)
        {
            candidate_stream << L"none";
        }
        else
        {
            for (std::size_t scalar_match = 0;
                 scalar_match < candidate.scalar_match_count;
                 ++scalar_match)
            {
                if (scalar_match != 0)
                {
                    candidate_stream << L" | ";
                }

                const auto scalar_index = candidate.scalar_indices[scalar_match];
                const auto offset = candidate.scalar_offsets[scalar_match];
                candidate_stream << scalar_usages[scalar_index] << L"@";
                if (offset >= 0)
                {
                    candidate_stream << L"+0x";
                }
                else
                {
                    candidate_stream << L"-0x";
                }
                candidate_stream << std::hex << std::uppercase
                    << (offset >= 0
                            ? static_cast<std::uint64_t>(offset)
                            : static_cast<std::uint64_t>(-offset))
                    << std::dec << std::nouppercase;
            }
        }

        if (candidate.vtable >= kMinUserModePointer)
        {
            candidate_stream << L", vtable="
                << FormatPointer(reinterpret_cast<void*>(candidate.vtable))
                << L", vtable_owner="
                << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(candidate.vtable));
        }
        if (candidate.semantic_valid)
        {
            candidate_stream << L", semantic="
                << NarrowToWide(std::string(candidate.semantic_sample.data()))
                << L", semantic_offset=0x" << std::hex << std::uppercase
                << candidate.semantic_offset
                << std::dec << std::nouppercase
                << L", semantic_score=" << candidate.semantic_score;
        }
        nskinzcs2::Logger::Info(candidate_stream.str());
    }

    std::size_t shared_template_count = 0;
    for (std::size_t group_index = 0; group_index < template_group_count; ++group_index)
    {
        const auto& group = template_groups[group_index];
        const auto cross_family_mask = group.family_mask & 0x7u;
        const auto has_cross_family =
            cross_family_mask == 0x3u ||
            cross_family_mask == 0x5u ||
            cross_family_mask == 0x6u ||
            cross_family_mask == 0x7u;
        if (group.candidate_count < 2 || !has_cross_family)
        {
            continue;
        }

        ++shared_template_count;
        std::wstringstream group_stream;
        group_stream << L"Query live shared-parent template: family="
            << BuildResourceHandleQuerySharedParentFamilyText(group.family_mask)
            << L", candidates=" << static_cast<std::uint32_t>(group.candidate_count)
            << L", child_offset=0x" << std::hex << std::uppercase << group.child_offset
            << std::dec << std::nouppercase
            << L", vtable=" << FormatPointer(reinterpret_cast<void*>(group.vtable))
            << L", vtable_owner="
            << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(group.vtable))
            << L", exemplar_parent="
            << FormatPointer(reinterpret_cast<void*>(group.exemplar_parent))
            << L", exemplar_rtti="
            << BuildRuntimeEntityRttiDescriptor(reinterpret_cast<void*>(group.exemplar_parent))
            << L", scalar_hits=";
        bool wrote_scalar = false;
        for (std::size_t scalar_index = 0; scalar_index < scalar_count; ++scalar_index)
        {
            if (!group.scalar_hits[scalar_index])
            {
                continue;
            }

            if (wrote_scalar)
            {
                group_stream << L" | ";
            }
            group_stream << scalar_usages[scalar_index];
            wrote_scalar = true;
        }
        if (!wrote_scalar)
        {
            group_stream << L"none";
        }
        nskinzcs2::Logger::Info(group_stream.str());
    }

    if (parent_candidate_count == 0)
    {
        nskinzcs2::Logger::Info(
            L"Query live shared-parent relation: no_parent_reference_match_in_local_or_head_windows");
        finalize_capture();
        return;
    }

    if (total_scalar_match_count == 0 && shared_template_count == 0)
    {
        std::wstringstream summary_stream;
        summary_stream << L"Query live shared-parent relation: parent_candidates="
            << static_cast<std::uint32_t>(parent_candidate_count)
            << L", but no scalar-attached or cross-family template candidate yet";
        nskinzcs2::Logger::Info(summary_stream.str());
    }
    else if (total_scalar_match_count == 0)
    {
        std::wstringstream summary_stream;
        summary_stream << L"Query live shared-parent relation: shared_templates="
            << static_cast<std::uint32_t>(shared_template_count)
            << L", but low scalars are not attached to those parent candidates yet";
        nskinzcs2::Logger::Info(summary_stream.str());
    }

    finalize_capture();
}

void TryLogResourceHandleQueryLowScalarCarrierRelation(
    const std::array<std::uint32_t, kResourceHandleQueryResultSampleSummaryCount>& hook_indices,
    const std::array<std::uintptr_t, kResourceHandleQueryResultSampleSummaryCount>& caller_return_addresses,
    const std::array<std::uintptr_t, kResourceHandleQueryResultSampleSummaryCount>& arg2_ptrs,
    const std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount>& arg3_values,
    const std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount>& arg4_values,
    const std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount>& handles,
    const std::uint32_t summary_end,
    const std::uint64_t source_world_token_snapshot,
    const std::uint64_t source_view_token_snapshot,
    const std::uint64_t donor_world_token_snapshot,
    const std::uint64_t donor_view_token_snapshot)
{
    if (summary_end == 0)
    {
        return;
    }

    const auto rs_hook_index_raw =
        ResourceHandleQueryHookIndex(ResourceHandleQueryInterfaceKind::ResourceSystem);
    if (rs_hook_index_raw == kInvalidResourceHandleQuerySlot)
    {
        return;
    }
    const auto rs_hook_index = static_cast<std::uint32_t>(rs_hook_index_raw);

    std::array<std::uint32_t, kResourceHandleQueryResultSampleSummaryCount> selected_indices {};
    bool primary_only = false;
    const auto selected_count = SelectPreferredResourceHandleQueryRelationSamples(
        hook_indices,
        caller_return_addresses,
        summary_end,
        rs_hook_index,
        selected_indices,
        primary_only);
    if (selected_count == 0)
    {
        return;
    }

    std::array<std::uint32_t, 16> scalar_values {};
    std::array<std::wstring, 16> scalar_usages {};
    std::size_t scalar_count = 0;
    for (std::uint32_t selected = 0; selected < selected_count; ++selected)
    {
        const auto index = selected_indices[selected];

        {
            std::wstringstream usage;
            usage << L"result[s" << index << L"]";
            AppendResourceHandleQueryLowScalarUsage(
                scalar_values,
                scalar_usages,
                scalar_count,
                handles[index],
                usage.str());
        }
        {
            std::wstringstream usage;
            usage << L"arg2[s" << index << L"]";
            AppendResourceHandleQueryLowScalarUsage(
                scalar_values,
                scalar_usages,
                scalar_count,
                arg2_ptrs[index],
                usage.str());
        }
        {
            std::wstringstream usage;
            usage << L"arg3[s" << index << L"]";
            AppendResourceHandleQueryLowScalarUsage(
                scalar_values,
                scalar_usages,
                scalar_count,
                arg3_values[index],
                usage.str());
        }
        {
            std::wstringstream usage;
            usage << L"arg4[s" << index << L"]";
            AppendResourceHandleQueryLowScalarUsage(
                scalar_values,
                scalar_usages,
                scalar_count,
                arg4_values[index],
                usage.str());
        }
    }

    if (scalar_count == 0)
    {
        return;
    }

    auto& probe = g_hook_state.resource_handle_query_live_probe;
    const auto source_world_handle_snapshot =
        probe.handle_snapshot_source_world.load(std::memory_order_acquire);
    const auto source_view_handle_snapshot =
        probe.handle_snapshot_source_view.load(std::memory_order_acquire);
    const auto donor_world_handle_snapshot =
        probe.handle_snapshot_donor_world.load(std::memory_order_acquire);
    const auto donor_view_handle_snapshot =
        probe.handle_snapshot_donor_view.load(std::memory_order_acquire);
    const auto target_world_handle_snapshot =
        probe.handle_snapshot_target_world.load(std::memory_order_acquire);
    const auto target_view_handle_snapshot =
        probe.handle_snapshot_target_view.load(std::memory_order_acquire);

    std::array<std::uintptr_t, 24> carrier_values {};
    std::array<std::wstring, 24> carrier_labels {};
    std::size_t carrier_count = 0;
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        source_world_token_snapshot,
        L"source_world_token");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        source_view_token_snapshot,
        L"source_view_token");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        donor_world_token_snapshot,
        L"donor_world_token");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        donor_view_token_snapshot,
        L"donor_view_token");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        source_world_handle_snapshot,
        L"source_world_handle");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        source_view_handle_snapshot,
        L"source_view_handle");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        donor_world_handle_snapshot,
        L"donor_world_handle");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        donor_view_handle_snapshot,
        L"donor_view_handle");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        target_world_handle_snapshot,
        L"resolved_target_world_handle");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        target_view_handle_snapshot,
        L"resolved_target_view_handle");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        probe.capture_this_ptr,
        L"live_rs_this");
    AppendResourceHandleQueryCarrierPointer(
        carrier_values,
        carrier_labels,
        carrier_count,
        probe.upstream_focus_base_ptr,
        L"upstream_focus_base");
    AppendResourceHandleQueryUpstreamFocusFieldCarriers(
        carrier_values,
        carrier_labels,
        carrier_count);

    if (carrier_count == 0)
    {
        return;
    }

    const auto root_carrier_count = carrier_count;
    constexpr std::size_t kDerivedCarrierPerRootBudget = 4u;
    for (std::size_t carrier_index = 0;
         carrier_index < root_carrier_count && carrier_count < carrier_values.size();
         ++carrier_index)
    {
        AppendResourceHandleQueryCarrierReadablePointerFields(
            carrier_values,
            carrier_labels,
            carrier_count,
            carrier_values[carrier_index],
            carrier_labels[carrier_index],
            kDerivedCarrierPerRootBudget);
    }

    std::uint32_t expected = kResourceHandleQueryCarrierCaptureNone;
    if (!probe.upstream_low_scalar_carrier_capture_state.compare_exchange_strong(
            expected,
            kResourceHandleQueryCarrierCaptureWriting,
            std::memory_order_acq_rel))
    {
        return;
    }

    std::wstringstream entered_stream;
    entered_stream << L"Query live low-scalar carrier relation: entered, unique_scalars="
        << scalar_count
        << L", root_carriers=" << static_cast<std::uint32_t>(root_carrier_count)
        << L", carriers=" << static_cast<std::uint32_t>(carrier_count)
        << L", summary_end=" << selected_count
        << L", sample_filter=" << (primary_only ? L"primary_only" : L"all_rs")
        << L", values=";
    for (std::size_t index = 0; index < scalar_count; ++index)
    {
        if (index != 0)
        {
            entered_stream << L" | ";
        }
        entered_stream << L"0x" << std::hex << std::uppercase << scalar_values[index]
            << std::dec << std::nouppercase
            << L"=" << scalar_usages[index];
    }
    nskinzcs2::Logger::Info(entered_stream.str());

    constexpr std::uintptr_t kCarrierLocalWindowBefore = 0x80u;
    constexpr std::uintptr_t kCarrierLocalWindowAfter = 0x180u;
    constexpr std::size_t kCarrierRegionHeadWindowBytes = 0x200u;
    constexpr std::size_t kCarrierMatchLogBudget = 24u;
    constexpr std::size_t kCarrierMatchPerPointerBudget = 8u;

    std::size_t total_match_count = 0;
    for (std::size_t carrier_index = 0;
         carrier_index < carrier_count && total_match_count < kCarrierMatchLogBudget;
         ++carrier_index)
    {
        const auto carrier_value = carrier_values[carrier_index];
        const auto* carrier_ptr = reinterpret_cast<const void*>(carrier_value);

        std::wstringstream carrier_stream;
        carrier_stream << L"Query live low-scalar carrier[" << carrier_labels[carrier_index]
            << L"]: ptr=" << FormatPointer(const_cast<void*>(carrier_ptr))
            << L", owner=" << FormatModuleOwnerWithOffset(const_cast<void*>(carrier_ptr))
            << L", region=" << DescribeReadableMemoryRegion(carrier_ptr, 24);
        nskinzcs2::Logger::Info(carrier_stream.str());

        MEMORY_BASIC_INFORMATION mbi {};
        if (VirtualQuery(carrier_ptr, &mbi, sizeof(mbi)) != sizeof(mbi))
        {
            continue;
        }

        const auto region_start = reinterpret_cast<std::uintptr_t>(mbi.BaseAddress);
        const auto region_end = region_start + mbi.RegionSize;
        if (region_end <= region_start)
        {
            continue;
        }

        std::array<bool, 16> scalar_matched {};
        std::size_t carrier_match_count = 0;
        const auto scan_window =
            [&](const wchar_t* window_label,
                std::uintptr_t window_start,
                std::uintptr_t window_end)
            {
                if (window_label == nullptr ||
                    window_start >= window_end ||
                    window_end <= window_start ||
                    carrier_match_count >= kCarrierMatchPerPointerBudget ||
                    total_match_count >= kCarrierMatchLogBudget)
                {
                    return;
                }

                for (auto address = window_start;
                     address + sizeof(std::uint32_t) <= window_end;
                     ++address)
                {
                    std::uint32_t raw32 = 0;
                    if (!SafeReadValue(reinterpret_cast<const void*>(address), raw32))
                    {
                        continue;
                    }

                    for (std::size_t scalar_index = 0; scalar_index < scalar_count; ++scalar_index)
                    {
                        if (scalar_matched[scalar_index] || raw32 != scalar_values[scalar_index])
                        {
                            continue;
                        }

                        scalar_matched[scalar_index] = true;
                        ++carrier_match_count;
                        ++total_match_count;

                        const auto delta =
                            address >= carrier_value
                                ? static_cast<std::uint64_t>(address - carrier_value)
                                : static_cast<std::uint64_t>(carrier_value - address);

                        std::wstringstream match_stream;
                        match_stream << L"Query live low-scalar carrier match["
                            << carrier_labels[carrier_index]
                            << L"]: scalar=0x" << std::hex << std::uppercase << raw32
                            << std::dec << std::nouppercase
                            << L", usage=" << scalar_usages[scalar_index]
                            << L", window=" << window_label
                            << L", address=" << FormatPointer(reinterpret_cast<void*>(address))
                            << L", owner="
                            << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(address))
                            << L", carrier_delta="
                            << (address >= carrier_value ? L"+" : L"-")
                            << L"0x" << std::hex << std::uppercase << delta
                            << std::dec << std::nouppercase;
                        nskinzcs2::Logger::Info(match_stream.str());

                        if (carrier_match_count >= kCarrierMatchPerPointerBudget ||
                            total_match_count >= kCarrierMatchLogBudget)
                        {
                            return;
                        }
                    }
                }
            };

        const auto local_start =
            std::max(region_start, carrier_value > kCarrierLocalWindowBefore
                ? carrier_value - kCarrierLocalWindowBefore
                : region_start);
        const auto local_end =
            std::min(region_end, carrier_value + kCarrierLocalWindowAfter);
        scan_window(L"local", local_start, local_end);

        const auto region_head_end =
            std::min(region_end, region_start + static_cast<std::uintptr_t>(kCarrierRegionHeadWindowBytes));
        if (region_head_end > region_start)
        {
            scan_window(L"region_head", region_start, region_head_end);
        }
    }

    if (total_match_count == 0)
    {
        nskinzcs2::Logger::Info(
            L"Query live low-scalar carrier relation: no_window_scalar_match_against_root_or_derived_carriers");
    }

    TryLogResourceHandleQuerySemanticCarrierDrilldown(
        carrier_values,
        carrier_labels,
        carrier_count);

    TryLogResourceHandleQuerySharedParentRelation(
        scalar_values,
        scalar_usages,
        scalar_count,
        carrier_values,
        carrier_labels,
        carrier_count);

    probe.upstream_low_scalar_carrier_capture_state.store(
        kResourceHandleQueryCarrierCaptureLogged,
        std::memory_order_release);
}

struct QuerySlotDetourResolution
{
    bool matched = false;
    bool slot_matches_patch = false;
    bool current_matches_replacement = false;
    std::size_t hook_index = kInvalidResourceHandleQuerySlot;
    ResourceHandleQueryInterfaceKind interface_kind = ResourceHandleQueryInterfaceKind::None;
    std::size_t query_slot = kInvalidResourceHandleQuerySlot;
    void* current_target = nullptr;
    void* replacement_target = nullptr;
    void* original_target = nullptr;
};

bool TryResolveKnifeModelPathSwapQuerySlotDetourLocked(
    const void* slot_address,
    const void* current_target,
    QuerySlotDetourResolution& out) noexcept
{
    out = {};

    auto* current_target_mutable = const_cast<void*>(current_target);
    auto* current_body = current_target_mutable != nullptr
        ? FollowJumpStubs(current_target_mutable)
        : nullptr;
    const auto* normalized_current =
        current_body != nullptr
            ? current_body
            : current_target_mutable;

    for (std::size_t index = 0; index < g_hook_state.knife_model_path_swap_query_hooks.size(); ++index)
    {
        const auto& hook_target = g_hook_state.knife_model_path_swap_query_hooks[index];
        if (!hook_target.valid ||
            !hook_target.patch.installed ||
            hook_target.patch.slot == nullptr ||
            hook_target.patch.replacement == nullptr ||
            hook_target.patch.original == nullptr)
        {
            continue;
        }

        const auto slot_matches =
            reinterpret_cast<const void*>(hook_target.patch.slot) == slot_address;

        auto* replacement_body = FollowJumpStubs(hook_target.patch.replacement);
        const auto* normalized_replacement =
            replacement_body != nullptr
                ? replacement_body
                : hook_target.patch.replacement;

        const auto current_matches_replacement =
            current_target_mutable == hook_target.patch.replacement ||
            (normalized_current != nullptr &&
                normalized_replacement != nullptr &&
                normalized_current == normalized_replacement);

        if (!slot_matches && !current_matches_replacement)
        {
            continue;
        }

        out.matched = true;
        out.slot_matches_patch = slot_matches;
        out.current_matches_replacement = current_matches_replacement;
        out.hook_index = index;
        out.interface_kind = hook_target.interface_kind;
        out.query_slot = hook_target.slot;
        out.current_target = current_target_mutable;
        out.replacement_target = hook_target.patch.replacement;
        out.original_target = hook_target.patch.original;
        return true;
    }

    return false;
}

template <std::size_t ScalarN>
void TryLogResourceHandleQueryRenderingSessionDescriptorRelation(
    const std::size_t descriptor_record_index,
    const std::size_t descriptor_field_offset,
    const void* session_ptr,
    const std::array<std::uint32_t, ScalarN>& scalar_values,
    const std::array<std::wstring, ScalarN>& scalar_usages,
    const std::size_t scalar_count,
    std::size_t& io_detail_log_count,
    const std::size_t detail_log_budget) noexcept
{
    if (session_ptr == nullptr ||
        scalar_count == 0 ||
        io_detail_log_count >= detail_log_budget ||
        reinterpret_cast<std::uintptr_t>(session_ptr) < kMinUserModePointer ||
        !IsReadablePointer(session_ptr))
    {
        return;
    }

    auto& probe = g_hook_state.resource_handle_query_live_probe;

    constexpr std::size_t kSessionSnapshotBudget = 12u;
    std::array<std::uint64_t, kSessionSnapshotBudget> snapshot_values {};
    std::array<std::wstring, kSessionSnapshotBudget> snapshot_usages {};
    std::size_t snapshot_count = 0;
    const auto append_snapshot =
        [&](const wchar_t* label, const std::uint64_t value)
        {
            if (label == nullptr || label[0] == L'\0')
            {
                return;
            }

            AppendResourceHandleQueryQwordUsage(
                snapshot_values,
                snapshot_usages,
                snapshot_count,
                value,
                label);
        };

    append_snapshot(
        L"source_world_handle",
        probe.handle_snapshot_source_world.load(std::memory_order_acquire));
    append_snapshot(
        L"source_view_handle",
        probe.handle_snapshot_source_view.load(std::memory_order_acquire));
    append_snapshot(
        L"donor_world_handle",
        probe.handle_snapshot_donor_world.load(std::memory_order_acquire));
    append_snapshot(
        L"donor_view_handle",
        probe.handle_snapshot_donor_view.load(std::memory_order_acquire));
    append_snapshot(
        L"target_world_handle",
        probe.handle_snapshot_target_world.load(std::memory_order_acquire));
    append_snapshot(
        L"target_view_handle",
        probe.handle_snapshot_target_view.load(std::memory_order_acquire));
    append_snapshot(
        L"source_world_token",
        probe.token_snapshot_source_world.load(std::memory_order_acquire));
    append_snapshot(
        L"source_view_token",
        probe.token_snapshot_source_view.load(std::memory_order_acquire));
    append_snapshot(
        L"donor_world_token",
        probe.token_snapshot_donor_world.load(std::memory_order_acquire));
    append_snapshot(
        L"donor_view_token",
        probe.token_snapshot_donor_view.load(std::memory_order_acquire));

    std::wstringstream entered_stream;
    entered_stream << L"Query live rendering-session relation: record["
        << descriptor_record_index
        << L"] field[+0x" << std::hex << std::uppercase << descriptor_field_offset
        << std::dec << std::nouppercase
        << L"], session=" << FormatPointer(const_cast<void*>(session_ptr))
        << L", owner=" << FormatModuleOwnerWithOffset(const_cast<void*>(session_ptr))
        << L", rtti=" << BuildRuntimeEntityRttiDescriptor(session_ptr)
        << L", scalar_count=" << scalar_count
        << L", snapshot_count=" << snapshot_count;
    nskinzcs2::Logger::Info(entered_stream.str());
    ++io_detail_log_count;
    if (io_detail_log_count >= detail_log_budget)
    {
        return;
    }

    struct SessionNodeCandidate
    {
        std::uintptr_t value = 0;
        std::size_t depth = 0;
        std::uint16_t pointer_score = 0;
        std::array<char, 64> label {};
        bool semantic_valid = false;
        std::array<char, kResourceHandleQueryUpstreamProbeSampleCapacity> semantic_sample {};
        std::size_t semantic_offset = 0;
        std::uint32_t semantic_score = 0;
        bool rtti_valid = false;
        std::wstring rtti {};
        std::size_t scalar_hit_count = 0;
        std::array<std::uint16_t, 4> scalar_hit_indices {};
        std::array<std::ptrdiff_t, 4> scalar_hit_offsets {};
        std::size_t snapshot_hit_count = 0;
        std::array<std::uint16_t, 4> snapshot_hit_indices {};
        std::array<std::ptrdiff_t, 4> snapshot_hit_offsets {};
        std::uint32_t interest_score = 0;
    };

    constexpr std::size_t kSessionNodeBudget = 16u;
    constexpr std::size_t kSessionRootChildBudget = 6u;
    constexpr std::size_t kSessionNestedChildBudget = 8u;
    constexpr std::size_t kSessionNestedPerRootBudget = 2u;
    constexpr std::size_t kSessionRootFieldBytes = 0x100u;
    constexpr std::size_t kSessionNestedFieldBytes = 0x60u;
    constexpr std::uintptr_t kSessionNodeWindowBefore = 0x20u;
    constexpr std::uintptr_t kSessionNodeWindowAfter = 0xC0u;
    constexpr std::uintptr_t kSessionRootWindowAfter = 0x100u;

    std::array<SessionNodeCandidate, kSessionNodeBudget> nodes {};
    std::size_t node_count = 0;

    const auto append_unique_node =
        [&](const std::uintptr_t value, const char* label, const std::size_t depth) noexcept
        {
            if (value < kMinUserModePointer ||
                label == nullptr ||
                label[0] == '\0' ||
                !IsReadablePointer(reinterpret_cast<const void*>(value)) ||
                IsExecutablePointer(reinterpret_cast<const void*>(value)))
            {
                return false;
            }

            for (std::size_t index = 0; index < node_count; ++index)
            {
                if (nodes[index].value == value)
                {
                    return false;
                }
            }

            if (node_count >= nodes.size())
            {
                return false;
            }

            auto& node = nodes[node_count++];
            node.value = value;
            node.depth = depth;
            node.pointer_score =
                ScoreResourceHandleQueryPointerOnlyCandidate(reinterpret_cast<const void*>(value));
            CopyFixedCString(node.label.data(), node.label.size(), label);
            return true;
        };

    append_unique_node(reinterpret_cast<std::uintptr_t>(session_ptr), "session", 0);

    std::size_t root_child_count = 0;
    std::size_t nested_child_count = 0;
    for (std::size_t offset = 0;
         offset < kSessionRootFieldBytes &&
         node_count < nodes.size() &&
         root_child_count < kSessionRootChildBudget;
         offset += sizeof(void*))
    {
        std::uint64_t raw_value = 0;
        if (!SafeReadValue(
                reinterpret_cast<const std::uint8_t*>(session_ptr) + offset,
                raw_value) ||
            raw_value < kMinUserModePointer)
        {
            continue;
        }

        const auto field_value = static_cast<std::uintptr_t>(raw_value);
        const auto* field_ptr = reinterpret_cast<const void*>(field_value);
        if (!IsReadablePointer(field_ptr) || IsExecutablePointer(field_ptr))
        {
            continue;
        }

        const auto field_score = ScoreResourceHandleQueryPointerOnlyCandidate(field_ptr);
        if (field_score < kResourceHandleQueryUpstreamPointerOnlySampleMinScore &&
            !LooksLikeRuntimeRttiObjectPointer(field_ptr))
        {
            continue;
        }

        char root_label[64] {};
        sprintf_s(root_label, "session[*+0x%02zX]", offset);
        if (!append_unique_node(field_value, root_label, 1))
        {
            continue;
        }

        ++root_child_count;
        std::size_t nested_for_root_count = 0;
        for (std::size_t nested_offset = 0;
             nested_offset < kSessionNestedFieldBytes &&
             node_count < nodes.size() &&
             nested_child_count < kSessionNestedChildBudget &&
             nested_for_root_count < kSessionNestedPerRootBudget;
             nested_offset += sizeof(void*))
        {
            std::uint64_t nested_raw_value = 0;
            if (!SafeReadValue(
                    reinterpret_cast<const std::uint8_t*>(field_ptr) + nested_offset,
                    nested_raw_value) ||
                nested_raw_value < kMinUserModePointer)
            {
                continue;
            }

            const auto nested_value = static_cast<std::uintptr_t>(nested_raw_value);
            const auto* nested_ptr = reinterpret_cast<const void*>(nested_value);
            if (!IsReadablePointer(nested_ptr) ||
                IsExecutablePointer(nested_ptr) ||
                nested_value == field_value ||
                nested_value == reinterpret_cast<std::uintptr_t>(session_ptr))
            {
                continue;
            }

            const auto nested_score =
                ScoreResourceHandleQueryPointerOnlyCandidate(nested_ptr);
            if (nested_score < kResourceHandleQueryUpstreamPointerOnlySampleMinScore &&
                !LooksLikeRuntimeRttiObjectPointer(nested_ptr))
            {
                continue;
            }

            char nested_label[64] {};
            sprintf_s(
                nested_label,
                "session[*+0x%02zX][*+0x%02zX]",
                offset,
                nested_offset);
            if (!append_unique_node(nested_value, nested_label, 2))
            {
                continue;
            }

            ++nested_child_count;
            ++nested_for_root_count;
        }
    }

    std::size_t matched_node_count = 0;
    std::array<std::size_t, kSessionNodeBudget> ordered_indices {};
    std::size_t ordered_count = 0;
    std::size_t best_focus_index = kInvalidResourceHandleQuerySlot;
    std::uint32_t best_focus_score = 0;

    for (std::size_t node_index = 0; node_index < node_count; ++node_index)
    {
        auto& node = nodes[node_index];
        const auto* node_ptr = reinterpret_cast<const void*>(node.value);
        if (!IsReadablePointer(node_ptr))
        {
            continue;
        }

        MEMORY_BASIC_INFORMATION node_region_info {};
        if (!TryQueryCommittedReadableRegion(node_ptr, node_region_info))
        {
            continue;
        }

        const auto region_start =
            reinterpret_cast<std::uintptr_t>(node_region_info.BaseAddress);
        const auto region_end = region_start + node_region_info.RegionSize;
        if (region_end <= region_start)
        {
            continue;
        }

        const auto window_before =
            node.depth == 0 ? static_cast<std::uintptr_t>(0u) : kSessionNodeWindowBefore;
        const auto window_after =
            node.depth == 0 ? kSessionRootWindowAfter : kSessionNodeWindowAfter;
        const auto scan_start = std::max(
            region_start,
            node.value > window_before ? node.value - window_before : region_start);
        const auto scan_end =
            std::min(region_end, node.value + window_after);
        if (scan_end <= scan_start)
        {
            continue;
        }

        std::array<bool, ScalarN> scalar_seen {};
        for (auto address = scan_start;
             address + sizeof(std::uint32_t) <= scan_end;
             ++address)
        {
            std::uint32_t raw32 = 0;
            if (!SafeReadValue(reinterpret_cast<const void*>(address), raw32))
            {
                continue;
            }

            for (std::size_t scalar_index = 0; scalar_index < scalar_count; ++scalar_index)
            {
                if (scalar_seen[scalar_index] || raw32 != scalar_values[scalar_index])
                {
                    continue;
                }

                scalar_seen[scalar_index] = true;
                if (node.scalar_hit_count < node.scalar_hit_indices.size())
                {
                    node.scalar_hit_indices[node.scalar_hit_count] =
                        static_cast<std::uint16_t>(scalar_index);
                    node.scalar_hit_offsets[node.scalar_hit_count] =
                        static_cast<std::ptrdiff_t>(address) -
                        static_cast<std::ptrdiff_t>(node.value);
                    ++node.scalar_hit_count;
                }
            }
        }

        std::array<bool, kSessionSnapshotBudget> snapshot_seen {};
        for (auto address = scan_start;
             address + sizeof(std::uint64_t) <= scan_end;
             ++address)
        {
            std::uint64_t raw64 = 0;
            if (!SafeReadValue(reinterpret_cast<const void*>(address), raw64))
            {
                continue;
            }

            for (std::size_t snapshot_index = 0;
                 snapshot_index < snapshot_count;
                 ++snapshot_index)
            {
                if (snapshot_seen[snapshot_index] || raw64 != snapshot_values[snapshot_index])
                {
                    continue;
                }

                snapshot_seen[snapshot_index] = true;
                if (node.snapshot_hit_count < node.snapshot_hit_indices.size())
                {
                    node.snapshot_hit_indices[node.snapshot_hit_count] =
                        static_cast<std::uint16_t>(snapshot_index);
                    node.snapshot_hit_offsets[node.snapshot_hit_count] =
                        static_cast<std::ptrdiff_t>(address) -
                        static_cast<std::ptrdiff_t>(node.value);
                    ++node.snapshot_hit_count;
                }
            }
        }

        node.semantic_valid =
            TryCaptureInterestingResourceHandleQuerySemanticWindowSample(
                node_ptr,
                node.depth == 0 ? kSessionRootWindowAfter : kSessionNodeWindowAfter,
                node.semantic_sample.data(),
                node.semantic_sample.size(),
                node.semantic_offset,
                node.semantic_score);
        if (LooksLikeRuntimeRttiObjectPointer(node_ptr))
        {
            node.rtti_valid = true;
            node.rtti = BuildRuntimeEntityRttiDescriptor(node_ptr);
        }

        node.interest_score =
            static_cast<std::uint32_t>(node.pointer_score) +
            static_cast<std::uint32_t>(node.scalar_hit_count * 64u) +
            static_cast<std::uint32_t>(node.snapshot_hit_count * 96u) +
            (node.semantic_valid ? node.semantic_score : 0u);
        if (node.rtti_valid &&
            node.rtti.find(L"CRenderingWorldSession") != std::wstring::npos)
        {
            node.interest_score += 24u;
        }

        const auto node_has_match =
            node.scalar_hit_count != 0 || node.snapshot_hit_count != 0;
        if (node_has_match)
        {
            ++matched_node_count;
            if (node.interest_score > best_focus_score)
            {
                best_focus_score = node.interest_score;
                best_focus_index = node_index;
            }
        }

        const auto should_log =
            node_has_match ||
            (node.depth != 0 && node.rtti_valid) ||
            (node.depth != 0 && node.semantic_valid && node.semantic_score >= 20);
        if (!should_log)
        {
            continue;
        }

        std::size_t insert_at = ordered_count;
        while (insert_at > 0)
        {
            const auto previous_index = ordered_indices[insert_at - 1];
            if (nodes[previous_index].interest_score >= node.interest_score)
            {
                break;
            }

            if (insert_at < ordered_indices.size())
            {
                ordered_indices[insert_at] = previous_index;
            }
            --insert_at;
        }

        if (insert_at >= ordered_indices.size())
        {
            continue;
        }

        ordered_indices[insert_at] = node_index;
        if (ordered_count < ordered_indices.size())
        {
            ++ordered_count;
        }
    }

    constexpr std::size_t kSessionNodeLogBudget = 8u;
    const auto append_hit_list =
        [](std::wstringstream& stream,
            const std::size_t hit_count,
            const auto& indices,
            const auto& offsets,
            const auto& usages) noexcept
        {
            if (hit_count == 0)
            {
                stream << L"none";
                return;
            }

            for (std::size_t hit_index = 0; hit_index < hit_count; ++hit_index)
            {
                if (hit_index != 0)
                {
                    stream << L" | ";
                }

                const auto usage_index = indices[hit_index];
                const auto offset = offsets[hit_index];
                stream << usages[usage_index] << L"@";
                if (offset >= 0)
                {
                    stream << L"+0x";
                }
                else
                {
                    stream << L"-0x";
                }
                stream << std::hex << std::uppercase
                    << (offset >= 0
                            ? static_cast<std::uint64_t>(offset)
                            : static_cast<std::uint64_t>(-offset))
                    << std::dec << std::nouppercase;
            }
        };

    std::size_t logged_nodes = 0;
    for (std::size_t ordered_index = 0;
         ordered_index < ordered_count &&
         logged_nodes < kSessionNodeLogBudget &&
         io_detail_log_count < detail_log_budget;
         ++ordered_index)
    {
        const auto& node = nodes[ordered_indices[ordered_index]];
        std::wstringstream node_stream;
        node_stream << L"Query live rendering-session node["
            << NarrowToWide(std::string(node.label.data()))
            << L"]: ptr=" << FormatPointer(reinterpret_cast<void*>(node.value))
            << L", depth=" << node.depth
            << L", score=" << node.pointer_score
            << L", owner=" << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(node.value))
            << L", scalar_hits=";
        append_hit_list(
            node_stream,
            node.scalar_hit_count,
            node.scalar_hit_indices,
            node.scalar_hit_offsets,
            scalar_usages);
        node_stream << L", snapshot_hits=";
        append_hit_list(
            node_stream,
            node.snapshot_hit_count,
            node.snapshot_hit_indices,
            node.snapshot_hit_offsets,
            snapshot_usages);
        if (node.rtti_valid)
        {
            node_stream << L", rtti=" << node.rtti;
        }
        if (node.semantic_valid)
        {
            node_stream << L", semantic="
                << NarrowToWide(std::string(node.semantic_sample.data()))
                << L", semantic_offset=0x" << std::hex << std::uppercase
                << node.semantic_offset
                << std::dec << std::nouppercase
                << L", semantic_score=" << node.semantic_score;
        }
        nskinzcs2::Logger::Info(node_stream.str());
        ++io_detail_log_count;
        ++logged_nodes;
    }

    if (best_focus_index != kInvalidResourceHandleQuerySlot)
    {
        const auto& focus_node = nodes[best_focus_index];
        TryCaptureResourceHandleQueryUpstreamFocus(
            "rendering_session",
            focus_node.label.data(),
            focus_node.semantic_valid
                ? focus_node.semantic_sample.data()
                : (focus_node.snapshot_hit_count != 0 ? "snapshot_attached" : "scalar_attached"),
            reinterpret_cast<const void*>(focus_node.value),
            0,
            static_cast<std::uint16_t>(std::max<std::uint32_t>(
                focus_node.pointer_score,
                kResourceHandleQueryUpstreamPointerOnlyFocusMinScore)));
    }

    if (io_detail_log_count < detail_log_budget)
    {
        std::wstringstream summary_stream;
        summary_stream << L"Query live rendering-session relation: candidates="
            << static_cast<std::uint32_t>(node_count)
            << L", matched_nodes=" << static_cast<std::uint32_t>(matched_node_count)
            << L", focus=";
        if (best_focus_index != kInvalidResourceHandleQuerySlot)
        {
            summary_stream << NarrowToWide(std::string(nodes[best_focus_index].label.data()));
        }
        else
        {
            summary_stream << L"<none>";
        }
        nskinzcs2::Logger::Info(summary_stream.str());
        ++io_detail_log_count;
    }
}

void TryLogResourceHandleQueryCallerDescriptorRelation(
    const std::array<std::uint32_t, kResourceHandleQueryResultSampleSummaryCount>& hook_indices,
    const std::array<std::uintptr_t, kResourceHandleQueryResultSampleSummaryCount>& caller_return_addresses,
    const std::array<std::uintptr_t, kResourceHandleQueryResultSampleSummaryCount>& arg2_ptrs,
    const std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount>& arg3_values,
    const std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount>& arg4_values,
    const std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount>& handles,
    const std::array<ResourceHandleQueryCallerRegisterSeed, kResourceHandleQueryResultSampleSummaryCount>&
        caller_register_seeds,
    const std::uint32_t summary_end) noexcept
{
    if (summary_end == 0)
    {
        return;
    }

    const auto rs_hook_index_raw =
        ResourceHandleQueryHookIndex(ResourceHandleQueryInterfaceKind::ResourceSystem);
    if (rs_hook_index_raw == kInvalidResourceHandleQuerySlot)
    {
        return;
    }
    const auto rs_hook_index = static_cast<std::uint32_t>(rs_hook_index_raw);

    std::array<std::uint32_t, kResourceHandleQueryResultSampleSummaryCount> primary_indices {};
    std::uint32_t primary_count = 0;
    for (std::uint32_t index = 0; index < summary_end; ++index)
    {
        if (hook_indices[index] != rs_hook_index ||
            !IsResourceHandleQueryPrimaryCaller(reinterpret_cast<const void*>(caller_return_addresses[index])))
        {
            continue;
        }

        primary_indices[primary_count++] = index;
    }

    if (primary_count == 0)
    {
        return;
    }

    auto& probe = g_hook_state.resource_handle_query_live_probe;
    std::uint32_t expected = kResourceHandleQueryCarrierCaptureNone;
    if (!probe.upstream_caller_descriptor_capture_state.compare_exchange_strong(
            expected,
            kResourceHandleQueryCarrierCaptureWriting,
            std::memory_order_acq_rel))
    {
        return;
    }

    const auto finalize_capture = [&]() noexcept
    {
        probe.upstream_caller_descriptor_capture_state.store(
            kResourceHandleQueryCarrierCaptureLogged,
            std::memory_order_release);
    };

    constexpr std::uintptr_t kCallerDescriptorTailWindowBytes = 0x280u;
    constexpr std::uintptr_t kCallerDescriptorLookaheadBytes = 0x40u;
    constexpr std::size_t kCallerDescriptorTargetSampleWindowBytes = 0xC0u;
    constexpr std::size_t kCallerDescriptorRefBudget = 10u;
    constexpr std::size_t kCallerDescriptorDetailBudget = 520u;
    constexpr std::size_t kCallerDescriptorScalarMatchBudget = 4u;

    std::array<std::uint32_t, 16> scalar_values {};
    std::array<std::wstring, 16> scalar_usages {};
    std::size_t scalar_count = 0;
    for (std::uint32_t selected = 0; selected < primary_count; ++selected)
    {
        const auto index = primary_indices[selected];

        {
            std::wstringstream usage;
            usage << L"result[s" << index << L"]";
            AppendResourceHandleQueryLowScalarUsage(
                scalar_values,
                scalar_usages,
                scalar_count,
                handles[index],
                usage.str());
        }
        {
            std::wstringstream usage;
            usage << L"arg2[s" << index << L"]";
            AppendResourceHandleQueryLowScalarUsage(
                scalar_values,
                scalar_usages,
                scalar_count,
                arg2_ptrs[index],
                usage.str());
        }
        {
            std::wstringstream usage;
            usage << L"arg3[s" << index << L"]";
            AppendResourceHandleQueryLowScalarUsage(
                scalar_values,
                scalar_usages,
                scalar_count,
                arg3_values[index],
                usage.str());
        }
        {
            std::wstringstream usage;
            usage << L"arg4[s" << index << L"]";
            AppendResourceHandleQueryLowScalarUsage(
                scalar_values,
                scalar_usages,
                scalar_count,
                arg4_values[index],
                usage.str());
        }
    }

    const auto focus_index = primary_indices[0];
    const auto caller_return_address = caller_return_addresses[focus_index];
    const auto focus_live_seed = caller_register_seeds[focus_index];
    void* function_start = nullptr;
    const auto has_function_start =
        TryResolveContainingFunctionStart(
            reinterpret_cast<const void*>(caller_return_address),
            function_start);

    std::wstringstream entered_stream;
    entered_stream << L"Query live caller-descriptor relation: entered, primary_samples="
        << primary_count
        << L", focus_sample=s" << focus_index
        << L", caller="
        << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(caller_return_address))
        << L", fn=";
    if (has_function_start && function_start != nullptr)
    {
        entered_stream << FormatModuleOwnerWithOffset(function_start);
    }
    else
    {
        entered_stream << L"<unresolved>";
    }
    entered_stream << L", result=0x" << std::hex << std::uppercase << handles[focus_index]
        << L", arg2=0x" << arg2_ptrs[focus_index]
        << L", arg3=0x" << arg3_values[focus_index]
        << L", arg4=0x" << arg4_values[focus_index]
        << std::dec << std::nouppercase
        << L", scalar_count=" << scalar_count;
    if (focus_live_seed.valid)
    {
        entered_stream << L", seed_rbp="
            << FormatPointer(reinterpret_cast<void*>(focus_live_seed.rbp))
            << L", seed_rsp="
            << FormatPointer(reinterpret_cast<void*>(focus_live_seed.rsp))
            << L", seed_r15="
            << FormatPointer(reinterpret_cast<void*>(focus_live_seed.r15));
    }
    nskinzcs2::Logger::Info(entered_stream.str());

    if (!has_function_start || function_start == nullptr)
    {
        nskinzcs2::Logger::Info(
            L"Query live caller-descriptor relation: primary caller function start unresolved");
        finalize_capture();
        return;
    }

    MEMORY_BASIC_INFORMATION caller_region_info {};
    if (!TryQueryCommittedReadableRegion(
            reinterpret_cast<const void*>(caller_return_address),
            caller_region_info))
    {
        nskinzcs2::Logger::Info(
            L"Query live caller-descriptor relation: caller return address is unreadable");
        finalize_capture();
        return;
    }

    const auto region_start =
        reinterpret_cast<std::uintptr_t>(caller_region_info.BaseAddress);
    const auto region_end = region_start + caller_region_info.RegionSize;
    if (region_end <= region_start)
    {
        nskinzcs2::Logger::Info(
            L"Query live caller-descriptor relation: caller region bounds were invalid");
        finalize_capture();
        return;
    }

    const auto function_start_address =
        reinterpret_cast<std::uintptr_t>(function_start);
    auto scan_start = std::max(region_start, function_start_address);
    if (caller_return_address > scan_start &&
        caller_return_address - scan_start > kCallerDescriptorTailWindowBytes)
    {
        scan_start = caller_return_address - kCallerDescriptorTailWindowBytes;
    }

    const auto scan_end = std::min<std::uintptr_t>(
        region_end,
        caller_return_address + kCallerDescriptorLookaheadBytes);
    if (scan_end <= scan_start)
    {
        nskinzcs2::Logger::Info(
            L"Query live caller-descriptor relation: scan window collapsed near primary caller");
        finalize_capture();
        return;
    }

    std::wstringstream window_stream;
    window_stream << L"Query live caller-descriptor relation: window="
        << FormatPointer(reinterpret_cast<void*>(scan_start))
        << L".."
        << FormatPointer(reinterpret_cast<void*>(scan_end))
        << L", span=0x" << std::hex << std::uppercase
        << static_cast<std::uint64_t>(scan_end - scan_start)
        << std::dec << std::nouppercase
        << L", mode="
        << (scan_start == function_start_address ? L"fn_start_to_caller" : L"tail_window");
    nskinzcs2::Logger::Info(window_stream.str());

    std::size_t ref_log_count = 0;
    std::size_t detail_log_count = 0;
    std::size_t rip_ref_count = 0;
    std::size_t call_ref_count = 0;
    std::size_t jmp_ref_count = 0;
    std::size_t immediate_match_count = 0;

    enum class CallerDescriptorReferenceKind
    {
        RipMem,
        CallRel,
        JmpRel,
    };

    struct CallerDescriptorRefCandidate
    {
        CallerDescriptorReferenceKind kind = CallerDescriptorReferenceKind::RipMem;
        std::uintptr_t instruction_address = 0;
        std::uintptr_t target_address = 0;
    };

    constexpr std::size_t kCallerDescriptorRipCandidateBudget = 48u;
    constexpr std::size_t kCallerDescriptorBranchCandidateBudget = 8u;
    std::array<CallerDescriptorRefCandidate, kCallerDescriptorRipCandidateBudget> rip_candidates {};
    std::array<CallerDescriptorRefCandidate, kCallerDescriptorBranchCandidateBudget> call_candidates {};
    std::array<CallerDescriptorRefCandidate, kCallerDescriptorBranchCandidateBudget> jmp_candidates {};
    std::size_t rip_candidate_count = 0;
    std::size_t call_candidate_count = 0;
    std::size_t jmp_candidate_count = 0;

    const auto append_unique_candidate =
        [](auto& candidates,
            std::size_t& candidate_count,
            const CallerDescriptorRefCandidate& candidate) noexcept
        {
            for (std::size_t index = 0; index < candidate_count; ++index)
            {
                if (candidates[index].kind == candidate.kind &&
                    candidates[index].target_address == candidate.target_address)
                {
                    return false;
                }
            }

            if (candidate_count >= candidates.size())
            {
                return false;
            }

            candidates[candidate_count++] = candidate;
            return true;
        };

    const auto build_scalar_usage_text =
        [&](const std::uint32_t raw32)
        {
            std::wstring usage_text;
            for (std::size_t scalar_index = 0; scalar_index < scalar_count; ++scalar_index)
            {
                if (scalar_values[scalar_index] != raw32)
                {
                    continue;
                }

                if (!usage_text.empty())
                {
                    usage_text += L"|";
                }
                usage_text += scalar_usages[scalar_index];
            }
            return usage_text;
        };

    constexpr std::array<const wchar_t*, 16> kCallerDescriptorGprNames {{
        L"rax", L"rcx", L"rdx", L"rbx", L"rsp", L"rbp", L"rsi", L"rdi",
        L"r8", L"r9", L"r10", L"r11", L"r12", L"r13", L"r14", L"r15",
    }};
    const auto caller_descriptor_reg_name =
        [&](const std::uint32_t reg_index) noexcept
        {
            return reg_index < kCallerDescriptorGprNames.size()
                ? kCallerDescriptorGprNames[reg_index]
                : L"?";
        };
    const auto decode_modrm_reg_index =
        [](const hde64s& decoded) noexcept
        {
            return static_cast<std::uint32_t>(decoded.modrm_reg + (decoded.rex_r ? 8u : 0u));
        };
    const auto decode_modrm_rm_index =
        [](const hde64s& decoded) noexcept
        {
            return static_cast<std::uint32_t>(decoded.modrm_rm + (decoded.rex_b ? 8u : 0u));
        };
    const auto resolve_memory_operand_base =
        [](const hde64s& decoded,
            std::uint32_t& out_base_reg,
            bool& out_is_rip_relative) noexcept
        {
            out_base_reg = 0;
            out_is_rip_relative = false;

            if ((decoded.flags & F_SIB) != 0 && decoded.modrm_rm == 4)
            {
                if (decoded.sib_index != 4 || decoded.rex_x != 0)
                {
                    return false;
                }

                if (decoded.modrm_mod == 0 && decoded.sib_base == 5)
                {
                    return false;
                }

                out_base_reg = static_cast<std::uint32_t>(
                    decoded.sib_base + (decoded.rex_b ? 8u : 0u));
                return true;
            }

            if (decoded.modrm_mod == 0 && decoded.modrm_rm == 5)
            {
                out_is_rip_relative = true;
                return true;
            }

            out_base_reg =
                static_cast<std::uint32_t>(decoded.modrm_rm + (decoded.rex_b ? 8u : 0u));
            return true;
        };

    const auto resolve_relative_target =
        [](const std::uintptr_t instruction_address,
            const hde64s& decoded,
            std::uintptr_t& out_target) noexcept
        {
            std::intptr_t displacement = 0;
            if ((decoded.flags & F_IMM32) != 0)
            {
                displacement = static_cast<std::int32_t>(decoded.imm.imm32);
            }
            else if ((decoded.flags & F_IMM16) != 0)
            {
                displacement = static_cast<std::int16_t>(decoded.imm.imm16);
            }
            else if ((decoded.flags & F_IMM8) != 0)
            {
                displacement = static_cast<std::int8_t>(decoded.imm.imm8);
            }
            else
            {
                return false;
            }

            const auto base =
                static_cast<std::intptr_t>(instruction_address) +
                static_cast<std::intptr_t>(decoded.len);
            out_target = static_cast<std::uintptr_t>(base + displacement);
            return true;
        };

    struct CallerDescriptorTrackedRegister
    {
        bool known = false;
        std::uintptr_t value = 0;
    };

    struct CallerDescriptorMemoryOperand
    {
        std::uint8_t segment_prefix = 0;
        bool rip_relative = false;
        bool has_base = false;
        std::uint32_t base_reg = 0;
        bool has_index = false;
        std::uint32_t index_reg = 0;
        std::uint32_t scale = 1;
        std::intptr_t displacement = 0;
    };

    const auto read_modrm_displacement =
        [](const hde64s& decoded, std::intptr_t& out_displacement) noexcept
        {
            out_displacement = 0;
            if (decoded.modrm_mod == 1 && (decoded.flags & F_DISP8) != 0)
            {
                out_displacement = static_cast<std::int8_t>(decoded.disp.disp8);
                return true;
            }
            if (decoded.modrm_mod == 2 && (decoded.flags & F_DISP32) != 0)
            {
                out_displacement = static_cast<std::int32_t>(decoded.disp.disp32);
                return true;
            }
            if (decoded.modrm_mod == 0 && decoded.modrm_rm == 5 && (decoded.flags & F_DISP32) != 0)
            {
                out_displacement = static_cast<std::int32_t>(decoded.disp.disp32);
                return true;
            }
            if (decoded.modrm_mod == 0 &&
                (decoded.flags & F_SIB) != 0 &&
                decoded.modrm_rm == 4 &&
                decoded.sib_base == 5 &&
                (decoded.flags & F_DISP32) != 0)
            {
                out_displacement = static_cast<std::int32_t>(decoded.disp.disp32);
                return true;
            }
            return decoded.modrm_mod == 0;
        };

    const auto append_disp_text =
        [](std::wstringstream& stream, const std::intptr_t displacement) noexcept
        {
            stream << (displacement >= 0 ? L"+" : L"-")
                << L"0x" << std::hex << std::uppercase
                << static_cast<std::uint64_t>(
                       displacement >= 0
                           ? displacement
                           : -displacement)
                << std::dec << std::nouppercase;
        };

    const auto decode_memory_operand =
        [&](const hde64s& decoded,
            CallerDescriptorMemoryOperand& out_operand) noexcept
        {
            out_operand = {};
            if ((decoded.flags & F_MODRM) == 0 || decoded.modrm_mod == 3)
            {
                return false;
            }

            if (!read_modrm_displacement(decoded, out_operand.displacement))
            {
                return false;
            }
            out_operand.segment_prefix = decoded.p_seg;

            if ((decoded.flags & F_SIB) != 0 && decoded.modrm_rm == 4)
            {
                out_operand.scale = 1u << decoded.sib_scale;

                if (!(decoded.modrm_mod == 0 && decoded.sib_base == 5))
                {
                    out_operand.has_base = true;
                    out_operand.base_reg = static_cast<std::uint32_t>(
                        decoded.sib_base + (decoded.rex_b ? 8u : 0u));
                }

                if (!(decoded.sib_index == 4 && decoded.rex_x == 0))
                {
                    out_operand.has_index = true;
                    out_operand.index_reg = static_cast<std::uint32_t>(
                        decoded.sib_index + (decoded.rex_x ? 8u : 0u));
                }
                return true;
            }

            if (decoded.modrm_mod == 0 && decoded.modrm_rm == 5)
            {
                out_operand.rip_relative = true;
                return true;
            }

            out_operand.has_base = true;
            out_operand.base_reg = static_cast<std::uint32_t>(
                decoded.modrm_rm + (decoded.rex_b ? 8u : 0u));
            return true;
        };

    const auto append_memory_operand_text =
        [&](std::wstringstream& stream,
            const CallerDescriptorMemoryOperand& operand) noexcept
        {
            if (operand.segment_prefix == PREFIX_SEGMENT_GS)
            {
                stream << L"gs:";
            }
            stream << L"[";

            bool has_component = false;
            if (operand.rip_relative)
            {
                stream << L"rip";
                has_component = true;
            }
            if (operand.has_base)
            {
                if (has_component)
                {
                    stream << L"+";
                }
                stream << caller_descriptor_reg_name(operand.base_reg);
                has_component = true;
            }
            if (operand.has_index)
            {
                if (has_component)
                {
                    stream << L"+";
                }
                stream << caller_descriptor_reg_name(operand.index_reg);
                if (operand.scale > 1)
                {
                    stream << L"*" << operand.scale;
                }
                has_component = true;
            }
            if (!has_component)
            {
                stream << L"0";
            }
            if (operand.displacement != 0 ||
                (!operand.rip_relative && !operand.has_base && !operand.has_index))
            {
                append_disp_text(stream, operand.displacement);
            }
            stream << L"]";
        };

    const auto resolve_segment_base =
        [](const std::uint8_t segment_prefix,
            std::intptr_t& out_segment_base) noexcept
        {
            out_segment_base = 0;
            switch (segment_prefix)
            {
            case 0:
            case PREFIX_SEGMENT_CS:
            case PREFIX_SEGMENT_SS:
            case PREFIX_SEGMENT_DS:
            case PREFIX_SEGMENT_ES:
                return true;
            case PREFIX_SEGMENT_GS:
                out_segment_base = static_cast<std::intptr_t>(__readgsqword(0x30));
                return out_segment_base != 0;
            default:
                return false;
            }
        };

    const auto try_resolve_effective_address =
        [&](const std::uintptr_t instruction_address,
            const hde64s& decoded,
            const auto& registers,
            std::uintptr_t& out_address,
            CallerDescriptorMemoryOperand* out_operand = nullptr) noexcept
        {
            CallerDescriptorMemoryOperand operand {};
            if (!decode_memory_operand(decoded, operand))
            {
                return false;
            }
            if (out_operand != nullptr)
            {
                *out_operand = operand;
            }

            std::intptr_t total = operand.displacement;
            std::intptr_t segment_base = 0;
            if (!resolve_segment_base(operand.segment_prefix, segment_base))
            {
                return false;
            }
            total += segment_base;
            if (operand.rip_relative)
            {
                total +=
                    static_cast<std::intptr_t>(instruction_address) +
                    static_cast<std::intptr_t>(decoded.len);
            }

            if (operand.has_base)
            {
                if (operand.base_reg >= registers.size() ||
                    !registers[operand.base_reg].known)
                {
                    return false;
                }
                total +=
                    static_cast<std::intptr_t>(registers[operand.base_reg].value);
            }

            if (operand.has_index)
            {
                if (operand.index_reg >= registers.size() ||
                    !registers[operand.index_reg].known)
                {
                    return false;
                }
                total +=
                    static_cast<std::intptr_t>(registers[operand.index_reg].value) *
                    static_cast<std::intptr_t>(operand.scale);
            }

            out_address = static_cast<std::uintptr_t>(total);
            return true;
        };

    const auto sign_extend_u32_to_ptr =
        [](const std::uint32_t value) noexcept
        {
            return static_cast<std::uintptr_t>(
                static_cast<std::intptr_t>(static_cast<std::int32_t>(value)));
        };

    const auto resolve_gpr_memory_load_width =
        [](const hde64s& decoded) noexcept -> std::size_t
        {
            if (decoded.rex_w != 0)
            {
                return sizeof(std::uint64_t);
            }
            if ((decoded.flags & F_PREFIX_66) != 0)
            {
                return sizeof(std::uint16_t);
            }
            return sizeof(std::uint32_t);
        };

    const auto read_integer_width_zero_extended =
        [](const void* address,
            const std::size_t width,
            std::uint64_t& out_value) noexcept
        {
            out_value = 0;
            switch (width)
            {
            case sizeof(std::uint8_t):
            {
                std::uint8_t value = 0;
                if (!SafeReadValue(address, value))
                {
                    return false;
                }
                out_value = value;
                return true;
            }
            case sizeof(std::uint16_t):
            {
                std::uint16_t value = 0;
                if (!SafeReadValue(address, value))
                {
                    return false;
                }
                out_value = value;
                return true;
            }
            case sizeof(std::uint32_t):
            {
                std::uint32_t value = 0;
                if (!SafeReadValue(address, value))
                {
                    return false;
                }
                out_value = value;
                return true;
            }
            case sizeof(std::uint64_t):
                return SafeReadValue(address, out_value);
            default:
                return false;
            }
        };

    const auto seed_preserved_registers_from_live_sample =
        [&](std::array<CallerDescriptorTrackedRegister, 16>& registers,
            const bool overwrite_known) noexcept
        {
            if (!focus_live_seed.valid)
            {
                return;
            }

            const auto seed_register =
                [&](const std::uint32_t reg_index,
                    const std::uintptr_t value) noexcept
                {
                    if (reg_index >= registers.size() || value == 0)
                    {
                        return;
                    }

                    if (!overwrite_known && registers[reg_index].known)
                    {
                        return;
                    }

                    registers[reg_index].known = true;
                    registers[reg_index].value = value;
                };

            seed_register(3u, focus_live_seed.rbx);
            seed_register(4u, focus_live_seed.rsp);
            seed_register(5u, focus_live_seed.rbp);
            seed_register(6u, focus_live_seed.rsi);
            seed_register(7u, focus_live_seed.rdi);
            seed_register(12u, focus_live_seed.r12);
            seed_register(13u, focus_live_seed.r13);
            seed_register(14u, focus_live_seed.r14);
            seed_register(15u, focus_live_seed.r15);
        };

    enum class CallerDescriptorDirectChaseTargetClass
    {
        None,
        Tier0Sidecar,
        SceneSystemMainline,
    };

    const auto classify_direct_chase_target =
        [&](void* target) noexcept
        {
            if (target == nullptr || !IsExecutablePointer(target))
            {
                return CallerDescriptorDirectChaseTargetClass::None;
            }

            const auto module = GetModuleFromAddress(target);
            if (IsSceneSystemModuleHandle(module))
            {
                return CallerDescriptorDirectChaseTargetClass::SceneSystemMainline;
            }
            if (IsTier0ModuleHandle(module))
            {
                return CallerDescriptorDirectChaseTargetClass::Tier0Sidecar;
            }
            return CallerDescriptorDirectChaseTargetClass::None;
        };

    const auto should_log_direct_chase_target =
        [&](void* target) noexcept
        {
            return classify_direct_chase_target(target) !=
                CallerDescriptorDirectChaseTargetClass::None;
        };

    constexpr std::size_t kSceneSystemChasedFlowInstructionBudget = 64u;
    constexpr std::size_t kTier0ChasedFlowInstructionBudget = 24u;
    constexpr std::size_t kSceneSystemChasedFlowRecursionBudget = 6u;
    constexpr std::size_t kTier0ChasedFlowRecursionBudget = 2u;
    constexpr std::array<std::pair<std::size_t, std::size_t>, 4>
        kSceneSystemFocusedBranchTargets {{
            {0x10F4C0u, 0x10F515u},
            {0x10F53Cu, 0x10F68Cu},
            {0x10F68Cu, 0x10F6C0u},
            {0x10F68Cu, 0x10F7BDu},
        }};

    const auto log_direct_chase_target_flow =
        [&](const auto& self,
            const wchar_t* phase_label,
            const std::size_t ref_index,
            const std::size_t parent_step,
            const std::size_t call_step,
            void* target,
            const std::array<CallerDescriptorTrackedRegister, 16>& seed_registers,
            const std::size_t chase_depth) noexcept
        {
            if (detail_log_count >= kCallerDescriptorDetailBudget ||
                target == nullptr ||
                !IsExecutablePointer(target))
            {
                return;
            }

            void* chased_target = target;
            if (void* body = FollowJumpStubs(target);
                body != nullptr &&
                body != target &&
                IsExecutablePointer(body))
            {
                chased_target = body;
            }

            const auto chase_target_class = classify_direct_chase_target(chased_target);
            if (chase_target_class == CallerDescriptorDirectChaseTargetClass::None)
            {
                return;
            }

            const auto chase_instruction_budget =
                chase_target_class ==
                        CallerDescriptorDirectChaseTargetClass::SceneSystemMainline
                    ? kSceneSystemChasedFlowInstructionBudget
                    : kTier0ChasedFlowInstructionBudget;
            const auto chase_recursion_budget =
                chase_target_class ==
                        CallerDescriptorDirectChaseTargetClass::SceneSystemMainline
                    ? kSceneSystemChasedFlowRecursionBudget
                    : kTier0ChasedFlowRecursionBudget;
            if (chase_depth > chase_recursion_budget)
            {
                return;
            }

            std::array<std::uint8_t, 16> entry_bytes {};
            if (SafeReadBytes(chased_target, entry_bytes.data(), entry_bytes.size()))
            {
                std::wstringstream entry_stream;
                entry_stream << L"Query live caller-descriptor chased-entry["
                    << ref_index
                    << L":" << parent_step
                    << L":" << call_step
                    << L"]: phase=" << (phase_label != nullptr ? phase_label : L"?")
                    << L", route="
                    << (chase_target_class ==
                            CallerDescriptorDirectChaseTargetClass::SceneSystemMainline
                        ? L"mainline_scene"
                        : L"sidecar_tier0")
                    << L", depth=" << chase_depth
                    << L", target=" << FormatPointer(target)
                    << L", target_owner=" << FormatModuleOwnerWithOffset(target);
                if (chased_target != target)
                {
                    entry_stream << L", body=" << FormatPointer(chased_target)
                        << L", body_owner="
                        << FormatModuleOwnerWithOffset(chased_target);
                }
                entry_stream << L", entry_bytes="
                    << FormatByteSequence(entry_bytes.data(), entry_bytes.size());
                nskinzcs2::Logger::Info(entry_stream.str());
                ++detail_log_count;
                if (detail_log_count >= kCallerDescriptorDetailBudget)
                {
                    return;
                }
            }

            std::array<CallerDescriptorTrackedRegister, 16> tracked_registers =
                seed_registers;
            std::array<std::uintptr_t, 24> chase_carrier_values {};
            std::array<std::wstring, 24> chase_carrier_labels {};
            std::size_t chase_carrier_count = 0;
            {
                auto& probe = g_hook_state.resource_handle_query_live_probe;
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.handle_snapshot_source_world.load(std::memory_order_acquire),
                    L"source_world_handle");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.handle_snapshot_source_view.load(std::memory_order_acquire),
                    L"source_view_handle");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.handle_snapshot_donor_world.load(std::memory_order_acquire),
                    L"donor_world_handle");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.handle_snapshot_donor_view.load(std::memory_order_acquire),
                    L"donor_view_handle");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.handle_snapshot_target_world.load(std::memory_order_acquire),
                    L"resolved_target_world_handle");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.handle_snapshot_target_view.load(std::memory_order_acquire),
                    L"resolved_target_view_handle");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.token_snapshot_source_world.load(std::memory_order_acquire),
                    L"source_world_token");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.token_snapshot_source_view.load(std::memory_order_acquire),
                    L"source_view_token");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.token_snapshot_donor_world.load(std::memory_order_acquire),
                    L"donor_world_token");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.token_snapshot_donor_view.load(std::memory_order_acquire),
                    L"donor_view_token");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.capture_this_ptr,
                    L"live_rs_this");
                AppendResourceHandleQueryCarrierPointer(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count,
                    probe.upstream_focus_base_ptr,
                    L"upstream_focus_base");
                AppendResourceHandleQueryUpstreamFocusFieldCarriers(
                    chase_carrier_values,
                    chase_carrier_labels,
                    chase_carrier_count);
            }
            const auto is_scene_system_offset =
                [](void* address, const std::size_t expected_offset) noexcept
                {
                    if (address == nullptr)
                    {
                        return false;
                    }

                    const auto module = GetModuleFromAddress(address);
                    if (!IsSceneSystemModuleHandle(module))
                    {
                        return false;
                    }

                    const auto module_span = GetModuleSpan(module);
                    if (!module_span.has_value() ||
                        !PointerInModule(*module_span, address))
                    {
                        return false;
                    }

                    const auto offset =
                        reinterpret_cast<std::uintptr_t>(address) -
                        reinterpret_cast<std::uintptr_t>(module_span->base);
                    return offset == expected_offset;
                };
            const auto append_chase_carrier_match =
                [&](std::wstringstream& stream,
                    const std::uintptr_t value,
                    const wchar_t* field_label) noexcept
                {
                    if (field_label == nullptr ||
                        field_label[0] == L'\0' ||
                        value < kMinUserModePointer)
                    {
                        return;
                    }

                    std::wstring matched_labels;
                    for (std::size_t carrier_index = 0;
                         carrier_index < chase_carrier_count;
                         ++carrier_index)
                    {
                        if (chase_carrier_values[carrier_index] != value)
                        {
                            continue;
                        }

                        if (!matched_labels.empty())
                        {
                            matched_labels += L"|";
                        }
                        matched_labels += chase_carrier_labels[carrier_index];
                    }

                    if (!matched_labels.empty())
                    {
                        stream << L", " << field_label << L"_match=" << matched_labels;
                    }

                    if (!IsReadablePointer(reinterpret_cast<const void*>(value)) ||
                        IsExecutablePointer(reinterpret_cast<const void*>(value)))
                    {
                        return;
                    }

                    MEMORY_BASIC_INFORMATION memory_info {};
                    if (VirtualQuery(
                            reinterpret_cast<const void*>(value),
                            &memory_info,
                            sizeof(memory_info)) != sizeof(memory_info) ||
                        (memory_info.Type != MEM_PRIVATE &&
                            memory_info.Type != MEM_MAPPED))
                    {
                        return;
                    }

                    constexpr std::size_t kWrappedProbeLimit = 0x80u;
                    constexpr std::size_t kWrappedProbeStride = 0x4u;
                    std::wstring wrapped_labels;
                    for (std::size_t offset = 0;
                         offset <= kWrappedProbeLimit;
                         offset += kWrappedProbeStride)
                    {
                        std::uint64_t nested_value = 0;
                        if (!SafeReadValue(
                                reinterpret_cast<const void*>(value + offset),
                                nested_value))
                        {
                            continue;
                        }

                        for (std::size_t carrier_index = 0;
                             carrier_index < chase_carrier_count;
                             ++carrier_index)
                        {
                            if (chase_carrier_values[carrier_index] !=
                                static_cast<std::uintptr_t>(nested_value))
                            {
                                continue;
                            }

                            if (!wrapped_labels.empty())
                            {
                                wrapped_labels += L"|";
                            }

                            std::wstringstream label_stream;
                            label_stream << chase_carrier_labels[carrier_index]
                                << L"@+0x" << std::hex << std::uppercase
                                << offset << std::dec << std::nouppercase;
                            wrapped_labels += label_stream.str();
                        }
                    }

                    if (!wrapped_labels.empty())
                    {
                        stream << L", " << field_label
                            << L"_wrapped_match=" << wrapped_labels;
                    }
                };
            const auto maybe_recurse_chase_target =
                [&](void* next_target) noexcept
                {
                    if (next_target == nullptr)
                    {
                        return;
                    }

                    void* next_body = next_target;
                    if (void* body = FollowJumpStubs(next_target);
                        body != nullptr &&
                        body != next_target &&
                        IsExecutablePointer(body))
                    {
                        next_body = body;
                    }

                    const auto next_target_class =
                        classify_direct_chase_target(next_body);
                    if (next_body == chased_target ||
                        next_target_class ==
                            CallerDescriptorDirectChaseTargetClass::None)
                    {
                        return;
                    }

                    const bool same_target_class =
                        next_target_class == chase_target_class;
                    const bool allow_cross_route =
                        chase_target_class ==
                            CallerDescriptorDirectChaseTargetClass::SceneSystemMainline &&
                        next_target_class ==
                            CallerDescriptorDirectChaseTargetClass::Tier0Sidecar;
                    if (!same_target_class && !allow_cross_route)
                    {
                        return;
                    }
                    if (same_target_class && chase_depth >= chase_recursion_budget)
                    {
                        return;
                    }

                    const auto next_depth =
                        same_target_class ? (chase_depth + 1u) : 0u;

                    self(
                        self,
                        phase_label,
                        ref_index,
                        parent_step,
                        call_step,
                        next_target,
                        tracked_registers,
                        next_depth);
                };
            const auto should_follow_scene_branch_target =
                [&](void* next_target) noexcept
                {
                    if (chase_target_class !=
                        CallerDescriptorDirectChaseTargetClass::SceneSystemMainline)
                    {
                        return false;
                    }

                    for (const auto& focused_target : kSceneSystemFocusedBranchTargets)
                    {
                        if (is_scene_system_offset(chased_target, focused_target.first) &&
                            is_scene_system_offset(next_target, focused_target.second))
                        {
                            return true;
                        }
                    }

                    return false;
                };
            const auto invalidate_volatile_registers_after_call =
                [&]() noexcept
                {
                    constexpr std::array<std::uint32_t, 7> kVolatileRegisters {{
                        0u, 1u, 2u, 8u, 9u, 10u, 11u,
                    }};
                    for (const auto reg_index : kVolatileRegisters)
                    {
                        if (reg_index >= tracked_registers.size())
                        {
                            continue;
                        }

                        tracked_registers[reg_index].known = false;
                        tracked_registers[reg_index].value = 0;
                    }
                };
            std::uintptr_t chase_cursor =
                reinterpret_cast<std::uintptr_t>(chased_target);
            for (std::size_t chase_step = 0;
                 chase_step < chase_instruction_budget &&
                 detail_log_count < kCallerDescriptorDetailBudget;
                 ++chase_step)
            {
                hde64s chase_decoded {};
                const auto chase_length =
                    static_cast<std::size_t>(
                        hde64_disasm(
                            reinterpret_cast<const void*>(chase_cursor),
                            &chase_decoded));
                if (chase_length == 0 ||
                    chase_decoded.len == 0 ||
                    (chase_decoded.flags & F_ERROR) != 0)
                {
                    break;
                }

                std::array<std::uint8_t, 16> raw_bytes {};
                SafeReadBytes(
                    reinterpret_cast<const void*>(chase_cursor),
                    raw_bytes.data(),
                    std::min(raw_bytes.size(), chase_length));

                const auto begin_stream =
                    [&]() noexcept
                    {
                        std::wstringstream stream;
                        stream << L"Query live caller-descriptor chased-flow["
                            << ref_index
                            << L":" << parent_step
                            << L":" << call_step
                            << L":" << chase_step
                            << L"]: phase="
                            << (phase_label != nullptr ? phase_label : L"?")
                            << L", depth=" << chase_depth
                            << L", insn="
                            << FormatModuleOwnerWithOffset(
                                   reinterpret_cast<void*>(chase_cursor))
                            << L", bytes="
                            << FormatByteSequence(
                                   raw_bytes.data(),
                                   std::min(raw_bytes.size(), chase_length));
                        return stream;
                    };

                bool logged = false;
                bool stop_after_instruction = false;

                if ((chase_decoded.flags & F_MODRM) != 0 &&
                    (chase_decoded.opcode == 0x8B ||
                        chase_decoded.opcode == 0x89))
                {
                    const auto reg_index = decode_modrm_reg_index(chase_decoded);
                    const auto rm_index = decode_modrm_rm_index(chase_decoded);
                    if (chase_decoded.modrm_mod == 3)
                    {
                        auto stream = begin_stream();
                                if (chase_decoded.opcode == 0x8B)
                                {
                                    stream << L", op=mov_reg_reg, dst="
                                        << caller_descriptor_reg_name(reg_index)
                                        << L", src="
                                << caller_descriptor_reg_name(rm_index);
                            if (reg_index < tracked_registers.size() &&
                                rm_index < tracked_registers.size())
                            {
                                tracked_registers[reg_index] =
                                    tracked_registers[rm_index];
                                if (tracked_registers[rm_index].known)
                                {
                                    stream << L", value="
                                        << FormatPointer(
                                               reinterpret_cast<void*>(
                                                   tracked_registers[rm_index].value));
                                    append_chase_carrier_match(
                                        stream,
                                        tracked_registers[rm_index].value,
                                        L"value");
                                }
                            }
                        }
                        else
                        {
                            stream << L", op=mov_reg_reg, dst="
                                << caller_descriptor_reg_name(rm_index)
                                << L", src="
                                << caller_descriptor_reg_name(reg_index);
                            if (reg_index < tracked_registers.size() &&
                                rm_index < tracked_registers.size())
                            {
                                tracked_registers[rm_index] =
                                    tracked_registers[reg_index];
                                if (tracked_registers[reg_index].known)
                                {
                                    stream << L", value="
                                        << FormatPointer(
                                               reinterpret_cast<void*>(
                                                   tracked_registers[reg_index].value));
                                    append_chase_carrier_match(
                                        stream,
                                        tracked_registers[reg_index].value,
                                        L"value");
                                }
                            }
                        }
                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                    }
                    else
                    {
                        CallerDescriptorMemoryOperand operand {};
                        if (decode_memory_operand(chase_decoded, operand))
                        {
                            auto stream = begin_stream();
                            if (chase_decoded.opcode == 0x8B)
                            {
                                stream << L", op=mov_reg_mem, dst="
                                    << caller_descriptor_reg_name(reg_index)
                                    << L", src=";
                                append_memory_operand_text(stream, operand);
                            }
                            else
                            {
                                stream << L", op=mov_mem_reg, dst=";
                                append_memory_operand_text(stream, operand);
                                stream << L", src="
                                    << caller_descriptor_reg_name(reg_index);
                            }

                            std::uintptr_t address = 0;
                            const auto address_known =
                                try_resolve_effective_address(
                                    chase_cursor,
                                    chase_decoded,
                                    tracked_registers,
                                    address,
                                    &operand);

                            if (address_known)
                            {
                                stream << L", address="
                                    << FormatPointer(
                                           reinterpret_cast<void*>(address));
                                append_chase_carrier_match(
                                    stream,
                                    address,
                                    L"address");
                                if (chase_decoded.opcode == 0x8B)
                                {
                                    std::uint64_t loaded_value = 0;
                                    const auto loaded_ok =
                                        read_integer_width_zero_extended(
                                            reinterpret_cast<const void*>(address),
                                            resolve_gpr_memory_load_width(chase_decoded),
                                            loaded_value);
                                    if (reg_index < tracked_registers.size())
                                    {
                                        tracked_registers[reg_index].known = loaded_ok;
                                        tracked_registers[reg_index].value =
                                            static_cast<std::uintptr_t>(loaded_value);
                                    }
                                    if (loaded_ok)
                                    {
                                        stream << L", loaded="
                                            << FormatPointer(
                                                   reinterpret_cast<void*>(
                                                       static_cast<std::uintptr_t>(loaded_value)))
                                            << L", loaded_owner="
                                            << FormatModuleOwnerWithOffset(
                                                   reinterpret_cast<void*>(
                                                       static_cast<std::uintptr_t>(loaded_value)));
                                        append_chase_carrier_match(
                                            stream,
                                            static_cast<std::uintptr_t>(loaded_value),
                                            L"loaded");
                                    }
                                    else
                                    {
                                        stream << L", loaded=<unreadable>";
                                    }
                                }
                                else if (reg_index < tracked_registers.size() &&
                                    tracked_registers[reg_index].known)
                                {
                                    stream << L", stored="
                                        << FormatPointer(
                                               reinterpret_cast<void*>(
                                                   tracked_registers[reg_index].value));
                                    append_chase_carrier_match(
                                        stream,
                                        tracked_registers[reg_index].value,
                                        L"stored");
                                }
                            }
                            else if (!operand.rip_relative)
                            {
                                stream << L", base_value=<unknown>";
                            }

                            nskinzcs2::Logger::Info(stream.str());
                            ++detail_log_count;
                            logged = true;
                        }
                    }
                }
                else if ((chase_decoded.flags & F_MODRM) != 0 &&
                    chase_decoded.opcode == 0x0F &&
                    (chase_decoded.opcode2 == 0xB6 ||
                        chase_decoded.opcode2 == 0xB7))
                {
                    const auto dst_reg = decode_modrm_reg_index(chase_decoded);
                    const auto src_reg = decode_modrm_rm_index(chase_decoded);
                    const auto value_mask =
                        chase_decoded.opcode2 == 0xB6 ? 0xFFull : 0xFFFFull;
                    if (chase_decoded.modrm_mod == 3)
                    {
                        auto stream = begin_stream();
                        stream << L", op=movzx_reg_reg, dst="
                            << caller_descriptor_reg_name(dst_reg)
                            << L", src="
                            << caller_descriptor_reg_name(src_reg);
                        if (dst_reg < tracked_registers.size() &&
                            src_reg < tracked_registers.size() &&
                            tracked_registers[src_reg].known)
                        {
                            tracked_registers[dst_reg].known = true;
                            tracked_registers[dst_reg].value =
                                static_cast<std::uintptr_t>(
                                    tracked_registers[src_reg].value & value_mask);
                            stream << L", value="
                                << FormatPointer(
                                       reinterpret_cast<void*>(
                                           tracked_registers[dst_reg].value));
                            append_chase_carrier_match(
                                stream,
                                tracked_registers[dst_reg].value,
                                L"value");
                        }
                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                    }
                    else
                    {
                        CallerDescriptorMemoryOperand operand {};
                        if (decode_memory_operand(chase_decoded, operand))
                        {
                            auto stream = begin_stream();
                            stream << L", op=movzx_reg_mem, dst="
                                << caller_descriptor_reg_name(dst_reg)
                                << L", src=";
                            append_memory_operand_text(stream, operand);

                            std::uintptr_t address = 0;
                            const auto address_known =
                                try_resolve_effective_address(
                                    chase_cursor,
                                    chase_decoded,
                                    tracked_registers,
                                    address,
                                    &operand);

                            if (address_known)
                            {
                                stream << L", address="
                                    << FormatPointer(
                                           reinterpret_cast<void*>(address));
                                std::uint16_t loaded_value = 0;
                                bool loaded_ok = false;
                                if (chase_decoded.opcode2 == 0xB6)
                                {
                                    std::uint8_t byte_value = 0;
                                    loaded_ok = SafeReadValue(
                                        reinterpret_cast<const void*>(address),
                                        byte_value);
                                    loaded_value = byte_value;
                                }
                                else
                                {
                                    loaded_ok = SafeReadValue(
                                        reinterpret_cast<const void*>(address),
                                        loaded_value);
                                }
                                if (dst_reg < tracked_registers.size())
                                {
                                    tracked_registers[dst_reg].known = loaded_ok;
                                    tracked_registers[dst_reg].value =
                                        static_cast<std::uintptr_t>(loaded_value);
                                }
                                if (loaded_ok)
                                {
                                    stream << L", loaded=0x"
                                        << std::hex << std::uppercase
                                        << static_cast<std::uint64_t>(loaded_value)
                                        << std::dec << std::nouppercase;
                                }
                                else
                                {
                                    stream << L", loaded=<unreadable>";
                                }
                            }
                            else if (!operand.rip_relative)
                            {
                                stream << L", base_value=<unknown>";
                            }

                            nskinzcs2::Logger::Info(stream.str());
                            ++detail_log_count;
                            logged = true;
                        }
                    }
                }
                else if ((chase_decoded.flags & F_MODRM) != 0 &&
                    chase_decoded.opcode == 0x63)
                {
                    const auto dst_reg = decode_modrm_reg_index(chase_decoded);
                    if (chase_decoded.modrm_mod == 3)
                    {
                        const auto src_reg = decode_modrm_rm_index(chase_decoded);
                        auto stream = begin_stream();
                        stream << L", op=movsxd_reg_reg, dst="
                            << caller_descriptor_reg_name(dst_reg)
                            << L", src=" << caller_descriptor_reg_name(src_reg);
                        if (dst_reg < tracked_registers.size() &&
                            src_reg < tracked_registers.size() &&
                            tracked_registers[src_reg].known)
                        {
                            tracked_registers[dst_reg].known = true;
                            tracked_registers[dst_reg].value =
                                sign_extend_u32_to_ptr(
                                    static_cast<std::uint32_t>(
                                        tracked_registers[src_reg].value));
                            stream << L", value="
                                << FormatPointer(
                                       reinterpret_cast<void*>(
                                           tracked_registers[dst_reg].value));
                            append_chase_carrier_match(
                                stream,
                                tracked_registers[dst_reg].value,
                                L"value");
                        }
                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                    }
                    else
                    {
                        CallerDescriptorMemoryOperand operand {};
                        std::uintptr_t address = 0;
                        const auto address_known =
                            try_resolve_effective_address(
                                chase_cursor,
                                chase_decoded,
                                tracked_registers,
                                address,
                                &operand);

                        auto stream = begin_stream();
                        stream << L", op=movsxd_reg_mem, dst="
                            << caller_descriptor_reg_name(dst_reg)
                            << L", src=";
                        append_memory_operand_text(stream, operand);

                        if (address_known)
                        {
                            stream << L", address="
                                << FormatPointer(reinterpret_cast<void*>(address));
                            append_chase_carrier_match(stream, address, L"address");

                            std::uint32_t loaded_value = 0;
                            const auto loaded_ok = SafeReadValue(
                                reinterpret_cast<const void*>(address),
                                loaded_value);
                            if (dst_reg < tracked_registers.size())
                            {
                                tracked_registers[dst_reg].known = loaded_ok;
                                tracked_registers[dst_reg].value =
                                    loaded_ok
                                        ? sign_extend_u32_to_ptr(loaded_value)
                                        : 0;
                            }
                            if (loaded_ok)
                            {
                                stream << L", loaded=0x"
                                    << std::hex << std::uppercase
                                    << static_cast<std::uint64_t>(loaded_value)
                                    << std::dec << std::nouppercase
                                    << L", value="
                                    << FormatPointer(
                                           reinterpret_cast<void*>(
                                               tracked_registers[dst_reg].value));
                                append_chase_carrier_match(
                                    stream,
                                    tracked_registers[dst_reg].value,
                                    L"value");
                            }
                            else
                            {
                                stream << L", loaded=<unreadable>";
                            }
                        }
                        else
                        {
                            stream << L", base_value=<unknown>";
                            if (dst_reg < tracked_registers.size())
                            {
                                tracked_registers[dst_reg].known = false;
                                tracked_registers[dst_reg].value = 0;
                            }
                        }

                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                    }
                }
                else if ((chase_decoded.flags & F_MODRM) != 0 &&
                    (chase_decoded.opcode == 0x01 ||
                        chase_decoded.opcode == 0x03) &&
                    chase_decoded.modrm_mod == 3)
                {
                    const auto dst_reg =
                        chase_decoded.opcode == 0x03
                            ? decode_modrm_reg_index(chase_decoded)
                            : decode_modrm_rm_index(chase_decoded);
                    const auto src_reg =
                        chase_decoded.opcode == 0x03
                            ? decode_modrm_rm_index(chase_decoded)
                            : decode_modrm_reg_index(chase_decoded);

                    auto stream = begin_stream();
                    stream << L", op=add_reg_reg, dst="
                        << caller_descriptor_reg_name(dst_reg)
                        << L", src=" << caller_descriptor_reg_name(src_reg);
                    if (dst_reg < tracked_registers.size() &&
                        src_reg < tracked_registers.size() &&
                        tracked_registers[dst_reg].known &&
                        tracked_registers[src_reg].known)
                    {
                        tracked_registers[dst_reg].value =
                            static_cast<std::uintptr_t>(
                                static_cast<std::intptr_t>(
                                    tracked_registers[dst_reg].value) +
                                static_cast<std::intptr_t>(
                                    tracked_registers[src_reg].value));
                        stream << L", value="
                            << FormatPointer(
                                   reinterpret_cast<void*>(
                                       tracked_registers[dst_reg].value));
                        append_chase_carrier_match(
                            stream,
                            tracked_registers[dst_reg].value,
                            L"value");
                    }
                    else if (dst_reg < tracked_registers.size())
                    {
                        tracked_registers[dst_reg].known = false;
                        tracked_registers[dst_reg].value = 0;
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                    logged = true;
                }
                else if (chase_decoded.opcode == 0x98 && chase_decoded.rex_w != 0)
                {
                    auto stream = begin_stream();
                    stream << L", op=cdqe";
                    if (tracked_registers[0].known)
                    {
                        tracked_registers[0].value =
                            sign_extend_u32_to_ptr(
                                static_cast<std::uint32_t>(
                                    tracked_registers[0].value));
                        stream << L", value="
                            << FormatPointer(
                                   reinterpret_cast<void*>(tracked_registers[0].value));
                        append_chase_carrier_match(
                            stream,
                            tracked_registers[0].value,
                            L"value");
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                    logged = true;
                }
                else if ((chase_decoded.opcode >= 0xB8 &&
                    chase_decoded.opcode <= 0xBF))
                {
                    const auto reg_index =
                        static_cast<std::uint32_t>(
                            chase_decoded.opcode - 0xB8u +
                            (chase_decoded.rex_b ? 8u : 0u));
                    std::uint64_t immediate_value = 0;
                    if ((chase_decoded.flags & F_IMM64) != 0)
                    {
                        immediate_value = chase_decoded.imm.imm64;
                    }
                    else if ((chase_decoded.flags & F_IMM32) != 0)
                    {
                        immediate_value = chase_decoded.imm.imm32;
                    }
                    else if ((chase_decoded.flags & F_IMM16) != 0)
                    {
                        immediate_value = chase_decoded.imm.imm16;
                    }
                    else if ((chase_decoded.flags & F_IMM8) != 0)
                    {
                        immediate_value = chase_decoded.imm.imm8;
                    }

                    if (reg_index < tracked_registers.size())
                    {
                        tracked_registers[reg_index].known = true;
                        tracked_registers[reg_index].value =
                            static_cast<std::uintptr_t>(immediate_value);
                    }

                    auto stream = begin_stream();
                    stream << L", op=mov_reg_imm, dst="
                        << caller_descriptor_reg_name(reg_index)
                        << L", imm=0x" << std::hex << std::uppercase
                        << immediate_value << std::dec << std::nouppercase;
                    append_chase_carrier_match(
                        stream,
                        static_cast<std::uintptr_t>(immediate_value),
                        L"imm");
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                    logged = true;
                }
                else if ((chase_decoded.flags & F_MODRM) != 0 &&
                    (chase_decoded.opcode == 0x31 ||
                        chase_decoded.opcode == 0x33) &&
                    chase_decoded.modrm_mod == 3)
                {
                    const auto dst_reg =
                        chase_decoded.opcode == 0x33
                            ? decode_modrm_reg_index(chase_decoded)
                            : decode_modrm_rm_index(chase_decoded);
                    const auto src_reg =
                        chase_decoded.opcode == 0x33
                            ? decode_modrm_rm_index(chase_decoded)
                            : decode_modrm_reg_index(chase_decoded);

                    auto stream = begin_stream();
                    stream << L", op=xor_reg_reg, dst="
                        << caller_descriptor_reg_name(dst_reg)
                        << L", src=" << caller_descriptor_reg_name(src_reg);
                    if (dst_reg < tracked_registers.size() &&
                        src_reg < tracked_registers.size() &&
                        tracked_registers[dst_reg].known &&
                        tracked_registers[src_reg].known)
                    {
                        tracked_registers[dst_reg].known = true;
                        tracked_registers[dst_reg].value =
                            tracked_registers[dst_reg].value ^
                            tracked_registers[src_reg].value;
                    }
                    if (dst_reg == src_reg && dst_reg < tracked_registers.size())
                    {
                        tracked_registers[dst_reg].known = true;
                        tracked_registers[dst_reg].value = 0;
                    }
                    if (dst_reg < tracked_registers.size() &&
                        tracked_registers[dst_reg].known)
                    {
                        stream << L", value="
                            << FormatPointer(
                                   reinterpret_cast<void*>(
                                       tracked_registers[dst_reg].value));
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                    logged = true;
                }
                else if (chase_decoded.opcode >= 0x50 &&
                    chase_decoded.opcode <= 0x5F)
                {
                    const bool is_pop = chase_decoded.opcode >= 0x58;
                    const auto base_opcode = is_pop ? 0x58u : 0x50u;
                    const auto reg_index =
                        static_cast<std::uint32_t>(
                            chase_decoded.opcode - base_opcode +
                            (chase_decoded.rex_b ? 8u : 0u));
                    auto stream = begin_stream();
                    stream << L", op="
                        << (is_pop ? L"pop_reg" : L"push_reg")
                        << L", reg=" << caller_descriptor_reg_name(reg_index);
                    if (tracked_registers[4].known)
                    {
                        const auto stack_pointer = tracked_registers[4].value;
                        if (is_pop && reg_index < tracked_registers.size())
                        {
                            std::uint64_t popped_value = 0;
                            const auto popped_ok = SafeReadValue(
                                reinterpret_cast<const void*>(stack_pointer),
                                popped_value);
                            tracked_registers[reg_index].known = popped_ok;
                            tracked_registers[reg_index].value =
                                popped_ok
                                    ? static_cast<std::uintptr_t>(popped_value)
                                    : 0;
                            if (popped_ok)
                            {
                                stream << L", reg_value="
                                    << FormatPointer(
                                           reinterpret_cast<void*>(
                                               tracked_registers[reg_index].value));
                                append_chase_carrier_match(
                                    stream,
                                    tracked_registers[reg_index].value,
                                    L"reg_value");
                            }
                            else
                            {
                                stream << L", reg_value=<unreadable>";
                            }
                        }
                        else if (reg_index < tracked_registers.size() &&
                            tracked_registers[reg_index].known)
                        {
                            stream << L", reg_value="
                                << FormatPointer(
                                       reinterpret_cast<void*>(
                                           tracked_registers[reg_index].value));
                            append_chase_carrier_match(
                                stream,
                                tracked_registers[reg_index].value,
                                L"reg_value");
                        }

                        tracked_registers[4].value =
                            is_pop
                                ? tracked_registers[4].value + 8u
                                : tracked_registers[4].value - 8u;
                        stream << L", rsp_after="
                            << FormatPointer(
                                   reinterpret_cast<void*>(
                                       tracked_registers[4].value));
                    }
                    else if (is_pop && reg_index < tracked_registers.size())
                    {
                        tracked_registers[reg_index].known = false;
                        tracked_registers[reg_index].value = 0;
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                    logged = true;
                }
                else if ((chase_decoded.flags & F_MODRM) != 0 &&
                    chase_decoded.opcode == 0x8D &&
                    chase_decoded.modrm_mod != 3)
                {
                    const auto dst_reg = decode_modrm_reg_index(chase_decoded);
                    CallerDescriptorMemoryOperand operand {};
                    if (decode_memory_operand(chase_decoded, operand))
                    {
                        auto stream = begin_stream();
                        stream << L", op=lea, dst="
                            << caller_descriptor_reg_name(dst_reg)
                            << L", src=";
                        append_memory_operand_text(stream, operand);

                        std::uintptr_t effective_address = 0;
                        const auto address_known =
                            try_resolve_effective_address(
                                chase_cursor,
                                chase_decoded,
                                tracked_registers,
                                effective_address,
                                &operand);

                        if (dst_reg < tracked_registers.size())
                        {
                            tracked_registers[dst_reg].known = address_known;
                            tracked_registers[dst_reg].value = effective_address;
                        }

                        if (address_known)
                        {
                            stream << L", value="
                                << FormatPointer(
                                       reinterpret_cast<void*>(effective_address))
                                << L", value_owner="
                                << FormatModuleOwnerWithOffset(
                                       reinterpret_cast<void*>(effective_address));
                            append_chase_carrier_match(
                                stream,
                                effective_address,
                                L"value");
                        }
                        else
                        {
                            stream << L", base_value=<unknown>";
                        }

                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                    }
                }
                else if ((chase_decoded.flags & F_MODRM) != 0 &&
                    chase_decoded.opcode == 0x85 &&
                    chase_decoded.modrm_mod == 3)
                {
                    const auto lhs_reg = decode_modrm_rm_index(chase_decoded);
                    const auto rhs_reg = decode_modrm_reg_index(chase_decoded);
                    auto stream = begin_stream();
                    stream << L", op=test_reg_reg, lhs="
                        << caller_descriptor_reg_name(lhs_reg)
                        << L", rhs=" << caller_descriptor_reg_name(rhs_reg);
                    if (lhs_reg < tracked_registers.size() &&
                        tracked_registers[lhs_reg].known)
                    {
                        stream << L", lhs_value="
                            << FormatPointer(
                                   reinterpret_cast<void*>(
                                       tracked_registers[lhs_reg].value));
                        append_chase_carrier_match(
                            stream,
                            tracked_registers[lhs_reg].value,
                            L"lhs_value");
                    }
                    if (rhs_reg < tracked_registers.size() &&
                        tracked_registers[rhs_reg].known)
                    {
                        stream << L", rhs_value="
                            << FormatPointer(
                                   reinterpret_cast<void*>(
                                       tracked_registers[rhs_reg].value));
                        append_chase_carrier_match(
                            stream,
                            tracked_registers[rhs_reg].value,
                            L"rhs_value");
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                    logged = true;
                }
                else if ((chase_decoded.flags & F_MODRM) != 0 &&
                    chase_decoded.opcode == 0x2B &&
                    chase_decoded.modrm_mod != 3)
                {
                    const auto dst_reg = decode_modrm_reg_index(chase_decoded);
                    CallerDescriptorMemoryOperand operand {};
                    if (decode_memory_operand(chase_decoded, operand))
                    {
                        auto stream = begin_stream();
                        stream << L", op=sub_reg_mem, dst="
                            << caller_descriptor_reg_name(dst_reg)
                            << L", src=";
                        append_memory_operand_text(stream, operand);

                        std::uintptr_t address = 0;
                        const auto address_known =
                            try_resolve_effective_address(
                                chase_cursor,
                                chase_decoded,
                                tracked_registers,
                                address,
                                &operand);

                        if (address_known)
                        {
                            stream << L", address="
                                << FormatPointer(reinterpret_cast<void*>(address));
                            append_chase_carrier_match(stream, address, L"address");

                            std::uint32_t loaded_value = 0;
                            if (SafeReadValue(
                                    reinterpret_cast<const void*>(address),
                                    loaded_value))
                            {
                                stream << L", loaded=0x"
                                    << std::hex << std::uppercase
                                    << static_cast<std::uint64_t>(loaded_value)
                                    << std::dec << std::nouppercase;
                                if (dst_reg < tracked_registers.size() &&
                                    tracked_registers[dst_reg].known)
                                {
                                    tracked_registers[dst_reg].value =
                                        static_cast<std::uintptr_t>(
                                            static_cast<std::uint32_t>(
                                                tracked_registers[dst_reg].value) -
                                            loaded_value);
                                    stream << L", result="
                                        << FormatPointer(
                                               reinterpret_cast<void*>(
                                                   tracked_registers[dst_reg].value));
                                }
                            }
                            else
                            {
                                stream << L", loaded=<unreadable>";
                            }
                        }
                        else if (!operand.rip_relative)
                        {
                            stream << L", base_value=<unknown>";
                        }

                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                    }
                }
                else if ((chase_decoded.flags & F_MODRM) != 0 &&
                    (chase_decoded.opcode == 0x39 ||
                        chase_decoded.opcode == 0x3B))
                {
                    const auto reg_index = decode_modrm_reg_index(chase_decoded);
                    const auto rm_index = decode_modrm_rm_index(chase_decoded);
                    auto stream = begin_stream();
                    if (chase_decoded.modrm_mod == 3)
                    {
                        stream << L", op=cmp_reg_reg, lhs="
                            << caller_descriptor_reg_name(
                                   chase_decoded.opcode == 0x3B ? reg_index : rm_index)
                            << L", rhs="
                            << caller_descriptor_reg_name(
                                   chase_decoded.opcode == 0x3B ? rm_index : reg_index);
                    }
                    else
                    {
                        CallerDescriptorMemoryOperand operand {};
                        if (decode_memory_operand(chase_decoded, operand))
                        {
                            stream << L", op=cmp_"
                                << (chase_decoded.opcode == 0x3B ? L"reg_mem" : L"mem_reg");
                            if (chase_decoded.opcode == 0x3B)
                            {
                                stream << L", lhs="
                                    << caller_descriptor_reg_name(reg_index)
                                    << L", rhs=";
                            }
                            else
                            {
                                stream << L", lhs=";
                            }
                            append_memory_operand_text(stream, operand);
                            if (chase_decoded.opcode == 0x39)
                            {
                                stream << L", rhs="
                                    << caller_descriptor_reg_name(reg_index);
                            }

                            std::uintptr_t address = 0;
                            const auto address_known =
                                try_resolve_effective_address(
                                    chase_cursor,
                                    chase_decoded,
                                    tracked_registers,
                                    address,
                                    &operand);

                            if (address_known)
                            {
                                stream << L", address="
                                    << FormatPointer(reinterpret_cast<void*>(address));
                                append_chase_carrier_match(stream, address, L"address");
                                std::uint32_t loaded_value = 0;
                                if (SafeReadValue(
                                        reinterpret_cast<const void*>(address),
                                        loaded_value))
                                {
                                    stream << L", mem32=0x"
                                        << std::hex << std::uppercase
                                        << static_cast<std::uint64_t>(loaded_value)
                                        << std::dec << std::nouppercase;
                                }
                                else
                                {
                                    stream << L", mem32=<unreadable>";
                                }
                            }
                            else if (!operand.rip_relative)
                            {
                                stream << L", base_value=<unknown>";
                            }

                            if (reg_index < tracked_registers.size() &&
                                tracked_registers[reg_index].known)
                            {
                                stream << L", reg_value="
                                    << FormatPointer(
                                           reinterpret_cast<void*>(
                                               tracked_registers[reg_index].value));
                                append_chase_carrier_match(
                                    stream,
                                    tracked_registers[reg_index].value,
                                    L"reg_value");
                            }
                        }
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                    logged = true;
                }
                else if ((chase_decoded.flags & F_MODRM) != 0 &&
                    (chase_decoded.opcode == 0x81 ||
                        chase_decoded.opcode == 0x83) &&
                    chase_decoded.modrm_mod == 3 &&
                    (chase_decoded.modrm_reg == 0 ||
                        chase_decoded.modrm_reg == 5 ||
                        chase_decoded.modrm_reg == 7))
                {
                    const auto reg_index = decode_modrm_rm_index(chase_decoded);
                    std::intptr_t immediate = 0;
                    if ((chase_decoded.flags & F_IMM32) != 0)
                    {
                        immediate =
                            static_cast<std::int32_t>(chase_decoded.imm.imm32);
                    }
                    else if ((chase_decoded.flags & F_IMM8) != 0)
                    {
                        immediate =
                            static_cast<std::int8_t>(chase_decoded.imm.imm8);
                    }

                    auto stream = begin_stream();
                    const auto operation =
                        chase_decoded.modrm_reg == 0
                            ? L"add_reg_imm"
                            : (chase_decoded.modrm_reg == 5
                                ? L"sub_reg_imm"
                                : L"cmp_reg_imm");
                    stream << L", op=" << operation << L", reg="
                        << caller_descriptor_reg_name(reg_index)
                        << L", imm";
                    append_disp_text(stream, immediate);
                    if (reg_index < tracked_registers.size() &&
                        tracked_registers[reg_index].known)
                    {
                        if (chase_decoded.modrm_reg == 0)
                        {
                            tracked_registers[reg_index].value =
                                static_cast<std::uintptr_t>(
                                    static_cast<std::intptr_t>(
                                        tracked_registers[reg_index].value) +
                                    immediate);
                        }
                        else if (chase_decoded.modrm_reg == 5)
                        {
                            tracked_registers[reg_index].value =
                                static_cast<std::uintptr_t>(
                                    static_cast<std::intptr_t>(
                                        tracked_registers[reg_index].value) -
                                    immediate);
                        }
                        stream << L", reg_value="
                            << FormatPointer(
                                   reinterpret_cast<void*>(
                                       tracked_registers[reg_index].value));
                        append_chase_carrier_match(
                            stream,
                            tracked_registers[reg_index].value,
                            L"reg_value");
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                    logged = true;
                }
                else if (chase_decoded.opcode == 0xE8 ||
                    chase_decoded.opcode == 0xE9 ||
                    chase_decoded.opcode == 0xEB ||
                    (chase_decoded.opcode >= 0x70 &&
                        chase_decoded.opcode <= 0x7F) ||
                    (chase_decoded.opcode == 0x0F &&
                        chase_decoded.opcode2 >= 0x80 &&
                        chase_decoded.opcode2 <= 0x8F))
                {
                    std::uintptr_t branch_target = 0;
                    if (resolve_relative_target(
                            chase_cursor,
                            chase_decoded,
                            branch_target))
                    {
                        auto stream = begin_stream();
                        if (chase_decoded.opcode == 0xE8)
                        {
                            stream << L", op=call_rel";
                        }
                        else if (chase_decoded.opcode == 0xE9 ||
                            chase_decoded.opcode == 0xEB)
                        {
                            stream << L", op=jmp_rel";
                            stop_after_instruction = true;
                        }
                        else
                        {
                            stream << L", op=jcc_rel";
                        }
                        stream << L", target="
                            << FormatPointer(reinterpret_cast<void*>(branch_target))
                            << L", target_owner="
                            << FormatModuleOwnerWithOffset(
                                   reinterpret_cast<void*>(branch_target));
                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                        if (chase_decoded.opcode == 0xE8 ||
                            chase_decoded.opcode == 0xE9 ||
                            chase_decoded.opcode == 0xEB)
                        {
                            maybe_recurse_chase_target(
                                reinterpret_cast<void*>(branch_target));
                        }
                        else if (should_follow_scene_branch_target(
                                     reinterpret_cast<void*>(branch_target)))
                        {
                            maybe_recurse_chase_target(
                                reinterpret_cast<void*>(branch_target));
                        }
                        if (chase_decoded.opcode == 0xE8)
                        {
                            invalidate_volatile_registers_after_call();
                        }
                    }
                }
                else if ((chase_decoded.flags & F_MODRM) != 0 &&
                    chase_decoded.opcode == 0xFF &&
                    chase_decoded.modrm_reg == 2)
                {
                    CallerDescriptorMemoryOperand operand {};
                    if (decode_memory_operand(chase_decoded, operand))
                    {
                        auto stream = begin_stream();
                        stream << L", op=call_indirect, src=";
                        append_memory_operand_text(stream, operand);

                        std::uintptr_t slot_address = 0;
                        const auto slot_address_known =
                            try_resolve_effective_address(
                                chase_cursor,
                                chase_decoded,
                                tracked_registers,
                                slot_address,
                                &operand);
                        void* resolved_target = nullptr;
                        if (slot_address_known)
                        {
                            std::uint64_t target_value = 0;
                            const auto target_ok = SafeReadValue(
                                reinterpret_cast<const void*>(slot_address),
                                target_value);
                            stream << L", slot_address="
                                << FormatPointer(
                                       reinterpret_cast<void*>(slot_address));
                            if (target_ok)
                            {
                                resolved_target =
                                    reinterpret_cast<void*>(
                                        static_cast<std::uintptr_t>(target_value));
                                stream << L", target="
                                    << FormatPointer(
                                           resolved_target)
                                    << L", target_owner="
                                    << FormatModuleOwnerWithOffset(
                                           resolved_target);
                            }
                            else
                            {
                                stream << L", target=<unreadable>";
                            }
                        }
                        else if (!operand.rip_relative)
                        {
                            stream << L", base_value=<unknown>";
                        }
                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                        maybe_recurse_chase_target(resolved_target);
                        invalidate_volatile_registers_after_call();
                    }
                }

                if (!logged)
                {
                    auto stream = begin_stream();
                    stream << L", op=raw";
                    if ((chase_decoded.flags & F_MODRM) != 0)
                    {
                        stream << L", reg="
                            << caller_descriptor_reg_name(
                                   decode_modrm_reg_index(chase_decoded))
                            << L", rm="
                            << caller_descriptor_reg_name(
                                   decode_modrm_rm_index(chase_decoded))
                            << L", mod="
                            << static_cast<std::uint32_t>(chase_decoded.modrm_mod);
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                }

                chase_cursor += std::max<std::size_t>(1, chase_length);
                if (stop_after_instruction)
                {
                    break;
                }
            }
        };

    const auto log_primary_caller_return_flow =
        [&](const std::size_t ref_index,
            const std::size_t parent_step,
            const std::uintptr_t start_cursor,
            const std::array<CallerDescriptorTrackedRegister, 16>& pre_call_registers) noexcept
        {
            if (detail_log_count >= kCallerDescriptorDetailBudget)
            {
                return;
            }

            constexpr std::size_t kPostCallInstructionBudget = 12u;
            std::array<CallerDescriptorTrackedRegister, 16> post_call_registers {};
            constexpr std::array<std::uint32_t, 9> kPreservedRegisters {{
                3u, 4u, 5u, 6u, 7u, 12u, 13u, 14u, 15u,
            }};
            for (const auto reg_index : kPreservedRegisters)
            {
                if (reg_index >= pre_call_registers.size())
                {
                    continue;
                }

                post_call_registers[reg_index] = pre_call_registers[reg_index];
            }
            seed_preserved_registers_from_live_sample(post_call_registers, false);
            post_call_registers[0].known = true;
            post_call_registers[0].value =
                static_cast<std::uintptr_t>(handles[focus_index]);

            std::uintptr_t cursor = start_cursor;
            for (std::size_t step = 0;
                 step < kPostCallInstructionBudget &&
                 detail_log_count < kCallerDescriptorDetailBudget;
                 ++step)
            {
                hde64s decoded {};
                const auto length =
                    static_cast<std::size_t>(
                        hde64_disasm(reinterpret_cast<const void*>(cursor), &decoded));
                if (length == 0 || decoded.len == 0 || (decoded.flags & F_ERROR) != 0)
                {
                    break;
                }

                std::array<std::uint8_t, 16> raw_bytes {};
                SafeReadBytes(
                    reinterpret_cast<const void*>(cursor),
                    raw_bytes.data(),
                    std::min(raw_bytes.size(), length));

                const auto begin_stream =
                    [&]() noexcept
                    {
                        std::wstringstream stream;
                        stream << L"Query live caller-descriptor return-flow["
                            << ref_index
                            << L":" << parent_step
                            << L":" << step
                            << L"]: insn="
                            << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(cursor))
                            << L", bytes="
                            << FormatByteSequence(raw_bytes.data(), std::min(raw_bytes.size(), length));
                        return stream;
                    };

                bool logged = false;
                bool stop_after_instruction = false;

                if ((decoded.flags & F_MODRM) != 0 &&
                    (decoded.opcode == 0x8B || decoded.opcode == 0x89))
                {
                    const auto reg_index = decode_modrm_reg_index(decoded);
                    const auto rm_index = decode_modrm_rm_index(decoded);
                    if (decoded.modrm_mod == 3)
                    {
                        auto stream = begin_stream();
                        if (decoded.opcode == 0x8B)
                        {
                            stream << L", op=mov_reg_reg, dst="
                                << caller_descriptor_reg_name(reg_index)
                                << L", src=" << caller_descriptor_reg_name(rm_index);
                            if (reg_index < post_call_registers.size() &&
                                rm_index < post_call_registers.size())
                            {
                                post_call_registers[reg_index] = post_call_registers[rm_index];
                                if (post_call_registers[rm_index].known)
                                {
                                    stream << L", value="
                                        << FormatPointer(
                                               reinterpret_cast<void*>(
                                                   post_call_registers[rm_index].value));
                                    if (post_call_registers[rm_index].value <= 0xFFFFFFFFull)
                                    {
                                        const auto usage_text =
                                            build_scalar_usage_text(
                                                static_cast<std::uint32_t>(
                                                    post_call_registers[rm_index].value));
                                        if (!usage_text.empty())
                                        {
                                            stream << L", scalar_usage=" << usage_text;
                                        }
                                    }
                                }
                            }
                        }
                        else
                        {
                            stream << L", op=mov_reg_reg, dst="
                                << caller_descriptor_reg_name(rm_index)
                                << L", src=" << caller_descriptor_reg_name(reg_index);
                            if (reg_index < post_call_registers.size() &&
                                rm_index < post_call_registers.size())
                            {
                                post_call_registers[rm_index] = post_call_registers[reg_index];
                                if (post_call_registers[reg_index].known)
                                {
                                    stream << L", value="
                                        << FormatPointer(
                                               reinterpret_cast<void*>(
                                                   post_call_registers[reg_index].value));
                                    if (post_call_registers[reg_index].value <= 0xFFFFFFFFull)
                                    {
                                        const auto usage_text =
                                            build_scalar_usage_text(
                                                static_cast<std::uint32_t>(
                                                    post_call_registers[reg_index].value));
                                        if (!usage_text.empty())
                                        {
                                            stream << L", scalar_usage=" << usage_text;
                                        }
                                    }
                                }
                            }
                        }
                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                    }
                    else
                    {
                        CallerDescriptorMemoryOperand operand {};
                        if (decode_memory_operand(decoded, operand))
                        {
                            auto stream = begin_stream();
                            if (decoded.opcode == 0x8B)
                            {
                                stream << L", op=mov_reg_mem, dst="
                                    << caller_descriptor_reg_name(reg_index)
                                    << L", src=";
                                append_memory_operand_text(stream, operand);
                            }
                            else
                            {
                                stream << L", op=mov_mem_reg, dst=";
                                append_memory_operand_text(stream, operand);
                                stream << L", src=" << caller_descriptor_reg_name(reg_index);
                            }

                            std::uintptr_t address = 0;
                            const auto address_known =
                                try_resolve_effective_address(
                                    cursor,
                                    decoded,
                                    post_call_registers,
                                    address,
                                    &operand);

                            if (address_known)
                            {
                                stream << L", address="
                                    << FormatPointer(reinterpret_cast<void*>(address));
                                if (decoded.opcode == 0x8B)
                                {
                                    std::uint64_t loaded_value = 0;
                                    const auto loaded_ok =
                                        read_integer_width_zero_extended(
                                            reinterpret_cast<const void*>(address),
                                            resolve_gpr_memory_load_width(decoded),
                                            loaded_value);
                                    if (reg_index < post_call_registers.size())
                                    {
                                        post_call_registers[reg_index].known = loaded_ok;
                                        post_call_registers[reg_index].value =
                                            static_cast<std::uintptr_t>(loaded_value);
                                    }
                                    if (loaded_ok)
                                    {
                                        stream << L", loaded="
                                            << FormatPointer(
                                                   reinterpret_cast<void*>(
                                                       static_cast<std::uintptr_t>(loaded_value)))
                                            << L", loaded_owner="
                                            << FormatModuleOwnerWithOffset(
                                                   reinterpret_cast<void*>(
                                                       static_cast<std::uintptr_t>(loaded_value)));
                                        if (loaded_value <= 0xFFFFFFFFull)
                                        {
                                            const auto usage_text =
                                                build_scalar_usage_text(
                                                    static_cast<std::uint32_t>(loaded_value));
                                            if (!usage_text.empty())
                                            {
                                                stream << L", scalar_usage=" << usage_text;
                                            }
                                        }
                                    }
                                    else
                                    {
                                        stream << L", loaded=<unreadable>";
                                    }
                                }
                                else if (reg_index < post_call_registers.size() &&
                                         post_call_registers[reg_index].known)
                                {
                                    const auto stored_value =
                                        post_call_registers[reg_index].value;
                                    stream << L", stored="
                                        << FormatPointer(reinterpret_cast<void*>(stored_value));
                                    if (stored_value <= 0xFFFFFFFFull)
                                    {
                                        const auto usage_text =
                                            build_scalar_usage_text(
                                                static_cast<std::uint32_t>(stored_value));
                                        if (!usage_text.empty())
                                        {
                                            stream << L", scalar_usage=" << usage_text;
                                        }
                                    }
                                }
                            }
                            else if (!operand.rip_relative)
                            {
                                stream << L", base_value=<unknown>";
                            }

                            nskinzcs2::Logger::Info(stream.str());
                            ++detail_log_count;
                            logged = true;
                        }
                    }
                }
                else if ((decoded.flags & F_MODRM) != 0 &&
                         decoded.opcode == 0x8D &&
                         decoded.modrm_mod != 3)
                {
                    const auto dst_reg = decode_modrm_reg_index(decoded);
                    CallerDescriptorMemoryOperand operand {};
                    if (decode_memory_operand(decoded, operand))
                    {
                        auto stream = begin_stream();
                        stream << L", op=lea, dst=" << caller_descriptor_reg_name(dst_reg)
                            << L", src=";
                        append_memory_operand_text(stream, operand);

                        std::uintptr_t effective_address = 0;
                        const auto address_known =
                            try_resolve_effective_address(
                                cursor,
                                decoded,
                                post_call_registers,
                                effective_address,
                                &operand);

                        if (dst_reg < post_call_registers.size())
                        {
                            post_call_registers[dst_reg].known = address_known;
                            post_call_registers[dst_reg].value = effective_address;
                        }

                        if (address_known)
                        {
                            stream << L", value="
                                << FormatPointer(reinterpret_cast<void*>(effective_address))
                                << L", value_owner="
                                << FormatModuleOwnerWithOffset(
                                       reinterpret_cast<void*>(effective_address));
                        }
                        else
                        {
                            stream << L", base_value=<unknown>";
                        }

                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                    }
                }
                else if ((decoded.flags & F_MODRM) != 0 &&
                         decoded.opcode == 0x85 &&
                         decoded.modrm_mod == 3)
                {
                    const auto lhs_reg = decode_modrm_rm_index(decoded);
                    const auto rhs_reg = decode_modrm_reg_index(decoded);
                    auto stream = begin_stream();
                    stream << L", op=test_reg_reg, lhs="
                        << caller_descriptor_reg_name(lhs_reg)
                        << L", rhs=" << caller_descriptor_reg_name(rhs_reg);
                    if (lhs_reg < post_call_registers.size() &&
                        post_call_registers[lhs_reg].known)
                    {
                        stream << L", lhs_value="
                            << FormatPointer(
                                   reinterpret_cast<void*>(post_call_registers[lhs_reg].value));
                    }
                    if (rhs_reg < post_call_registers.size() &&
                        post_call_registers[rhs_reg].known)
                    {
                        stream << L", rhs_value="
                            << FormatPointer(
                                   reinterpret_cast<void*>(post_call_registers[rhs_reg].value));
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                    logged = true;
                }
                else if ((decoded.flags & F_MODRM) != 0 &&
                         (decoded.opcode == 0x81 || decoded.opcode == 0x83) &&
                         decoded.modrm_mod == 3 &&
                         decoded.modrm_reg == 7)
                {
                    const auto reg_index = decode_modrm_rm_index(decoded);
                    std::uint64_t immediate = 0;
                    if ((decoded.flags & F_IMM32) != 0)
                    {
                        immediate = decoded.imm.imm32;
                    }
                    else if ((decoded.flags & F_IMM8) != 0)
                    {
                        immediate = decoded.imm.imm8;
                    }

                    auto stream = begin_stream();
                    stream << L", op=cmp_reg_imm, reg="
                        << caller_descriptor_reg_name(reg_index)
                        << L", imm=0x" << std::hex << std::uppercase << immediate
                        << std::dec << std::nouppercase;
                    if (reg_index < post_call_registers.size() &&
                        post_call_registers[reg_index].known)
                    {
                        stream << L", reg_value="
                            << FormatPointer(
                                   reinterpret_cast<void*>(post_call_registers[reg_index].value));
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                    logged = true;
                }
                else if (decoded.opcode == 0xE8 ||
                         decoded.opcode == 0xE9 ||
                         decoded.opcode == 0xEB ||
                         (decoded.opcode >= 0x70 && decoded.opcode <= 0x7F) ||
                         (decoded.opcode == 0x0F &&
                          decoded.opcode2 >= 0x80 &&
                          decoded.opcode2 <= 0x8F))
                {
                    std::uintptr_t branch_target = 0;
                    if (resolve_relative_target(cursor, decoded, branch_target))
                    {
                        auto stream = begin_stream();
                        if (decoded.opcode == 0xE8)
                        {
                            stream << L", op=call_rel";
                            stop_after_instruction = true;
                        }
                        else if (decoded.opcode == 0xE9 || decoded.opcode == 0xEB)
                        {
                            stream << L", op=jmp_rel";
                            stop_after_instruction = true;
                        }
                        else
                        {
                            stream << L", op=jcc_rel";
                        }
                        stream << L", target=" << FormatPointer(reinterpret_cast<void*>(branch_target))
                            << L", target_owner="
                            << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(branch_target));
                        nskinzcs2::Logger::Info(stream.str());
                        ++detail_log_count;
                        logged = true;
                    }
                }
                else if ((decoded.flags & F_MODRM) != 0 &&
                         (decoded.flags & F_SIB) == 0 &&
                         decoded.opcode == 0xFF &&
                         decoded.modrm_reg == 2)
                {
                    const auto base_reg = decode_modrm_rm_index(decoded);
                    std::intptr_t displacement = 0;
                    if (read_modrm_displacement(decoded, displacement))
                    {
                        const auto is_rip_relative =
                            decoded.modrm_mod == 0 && decoded.modrm_rm == 5;
                        auto stream = begin_stream();
                        stream << L", op=call_indirect, src=["
                            << (is_rip_relative
                                    ? L"rip"
                                    : caller_descriptor_reg_name(base_reg));
                        append_disp_text(stream, displacement);
                        stream << L"]";

                        std::uintptr_t slot_address = 0;
                        bool slot_address_known = false;
                        if (is_rip_relative)
                        {
                            slot_address =
                                static_cast<std::uintptr_t>(
                                    static_cast<std::intptr_t>(cursor) +
                                    static_cast<std::intptr_t>(decoded.len) +
                                    displacement);
                            slot_address_known = true;
                        }
                        else if (base_reg < post_call_registers.size() &&
                                 post_call_registers[base_reg].known)
                        {
                            slot_address =
                                static_cast<std::uintptr_t>(
                                    static_cast<std::intptr_t>(
                                        post_call_registers[base_reg].value) +
                                    displacement);
                            slot_address_known = true;
                        }

                        if (slot_address_known)
                        {
                            std::uint64_t target = 0;
                            const auto target_ok = SafeReadValue(
                                reinterpret_cast<const void*>(slot_address),
                                target);
                            void* target_ptr = nullptr;
                            stream << L", slot_address="
                                << FormatPointer(reinterpret_cast<void*>(slot_address));
                            if (target_ok)
                            {
                                target_ptr = reinterpret_cast<void*>(
                                    static_cast<std::uintptr_t>(target));
                                stream << L", target="
                                    << FormatPointer(
                                           target_ptr)
                                    << L", target_owner="
                                    << FormatModuleOwnerWithOffset(target_ptr);
                            }
                            else
                            {
                                stream << L", target=<unreadable>";
                            }
                            nskinzcs2::Logger::Info(stream.str());
                            ++detail_log_count;
                            logged = true;
                            if (target_ptr != nullptr)
                            {
                                log_direct_chase_target_flow(
                                    log_direct_chase_target_flow,
                                    L"return",
                                    ref_index,
                                    parent_step,
                                    step,
                                    target_ptr,
                                    post_call_registers,
                                    0u);
                            }
                        }
                        else if (!is_rip_relative)
                        {
                            stream << L", base_value=<unknown>";
                            nskinzcs2::Logger::Info(stream.str());
                            ++detail_log_count;
                            logged = true;
                        }
                        stop_after_instruction = true;
                    }
                }

                if (!logged)
                {
                    auto stream = begin_stream();
                    stream << L", op=raw";
                    if ((decoded.flags & F_MODRM) != 0)
                    {
                        stream << L", reg="
                            << caller_descriptor_reg_name(decode_modrm_reg_index(decoded))
                            << L", rm="
                            << caller_descriptor_reg_name(decode_modrm_rm_index(decoded))
                            << L", mod=" << static_cast<std::uint32_t>(decoded.modrm_mod);
                    }
                    nskinzcs2::Logger::Info(stream.str());
                    ++detail_log_count;
                }

                cursor += std::max<std::size_t>(1, length);
                if (stop_after_instruction)
                {
                    break;
                }
            }
        };

    const auto log_target_details =
        [&](const CallerDescriptorRefCandidate& candidate)
        {
            if (ref_log_count >= kCallerDescriptorRefBudget)
            {
                return;
            }

            const auto kind =
                candidate.kind == CallerDescriptorReferenceKind::CallRel
                    ? L"call_rel"
                    : (candidate.kind == CallerDescriptorReferenceKind::JmpRel
                        ? L"jmp_rel"
                        : L"rip_mem");
            const auto instruction_address = candidate.instruction_address;
            const auto target_address = candidate.target_address;
            const auto ref_index = ref_log_count++;
            const auto* target_ptr = reinterpret_cast<const void*>(target_address);
            const auto target_readable =
                target_address >= kMinUserModePointer &&
                IsReadablePointer(target_ptr);
            const auto target_executable =
                target_address >= kMinUserModePointer &&
                IsExecutablePointer(target_ptr);

            std::wstringstream ref_stream;
            ref_stream << L"Query live caller-descriptor ref[" << ref_index << L"]: kind="
                << (kind != nullptr ? kind : L"?")
                << L", insn="
                << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(instruction_address))
                << L", target=" << FormatPointer(reinterpret_cast<void*>(target_address));
            if (target_address >= kMinUserModePointer)
            {
                ref_stream << L", owner="
                    << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(target_address));
            }
            if (target_readable && !target_executable)
            {
                ref_stream << L", region="
                    << DescribeReadableMemoryRegion(
                           reinterpret_cast<void*>(target_address),
                           24);
            }
            if (target_executable)
            {
                void* target_function_start = nullptr;
                if (TryResolveContainingFunctionStart(target_ptr, target_function_start) &&
                    target_function_start != nullptr)
                {
                    ref_stream << L", fn="
                        << FormatModuleOwnerWithOffset(target_function_start);
                }
            }
            nskinzcs2::Logger::Info(ref_stream.str());

            if (!target_readable || detail_log_count >= kCallerDescriptorDetailBudget)
            {
                return;
            }

            if (target_executable)
            {
                std::array<std::uint8_t, 16> entry_bytes {};
                if (SafeReadBytes(target_ptr, entry_bytes.data(), entry_bytes.size()))
                {
                    std::wstringstream callee_stream;
                    callee_stream << L"Query live caller-descriptor callee[" << ref_index
                        << L"]: entry_bytes=";
                    for (std::size_t index = 0; index < entry_bytes.size(); ++index)
                    {
                        if (index != 0)
                        {
                            callee_stream << L" ";
                        }
                        callee_stream << std::hex << std::uppercase
                            << std::setw(2) << std::setfill(L'0')
                            << static_cast<std::uint32_t>(entry_bytes[index]);
                    }
                    callee_stream << std::dec << std::nouppercase
                        << std::setfill(L' ');
                    nskinzcs2::Logger::Info(callee_stream.str());
                    ++detail_log_count;
                }

                std::array<CallerDescriptorTrackedRegister, 16> tracked_registers {};
                constexpr std::size_t kExecutableFlowInstructionBudget = 6u;
                std::uintptr_t flow_cursor = target_address;
                for (std::size_t step = 0;
                     step < kExecutableFlowInstructionBudget &&
                     detail_log_count < kCallerDescriptorDetailBudget;
                     ++step)
                {
                    hde64s flow_decoded {};
                    const auto flow_length =
                        static_cast<std::size_t>(
                            hde64_disasm(reinterpret_cast<const void*>(flow_cursor), &flow_decoded));
                    if (flow_length == 0 ||
                        flow_decoded.len == 0 ||
                        (flow_decoded.flags & F_ERROR) != 0)
                    {
                        break;
                    }

                    if ((flow_decoded.flags & F_MODRM) != 0 &&
                        flow_decoded.opcode == 0x8B &&
                        flow_decoded.modrm_mod != 3)
                    {
                        const auto dst_reg = decode_modrm_reg_index(flow_decoded);
                        CallerDescriptorMemoryOperand operand {};
                        if (decode_memory_operand(flow_decoded, operand))
                        {
                            std::uintptr_t source_address = 0;
                            const auto address_known =
                                try_resolve_effective_address(
                                    flow_cursor,
                                    flow_decoded,
                                    tracked_registers,
                                    source_address,
                                    &operand);
                            std::uint64_t loaded_value = 0;
                            const auto loaded_ok =
                                address_known &&
                                read_integer_width_zero_extended(
                                    reinterpret_cast<const void*>(source_address),
                                    resolve_gpr_memory_load_width(flow_decoded),
                                    loaded_value);
                            if (dst_reg < tracked_registers.size())
                            {
                                tracked_registers[dst_reg].known = loaded_ok;
                                tracked_registers[dst_reg].value =
                                    static_cast<std::uintptr_t>(loaded_value);
                            }

                            const auto simple_base_only =
                                !operand.rip_relative &&
                                operand.segment_prefix == 0 &&
                                operand.has_base &&
                                !operand.has_index &&
                                operand.displacement == 0;

                            std::wstringstream flow_stream;
                            flow_stream << L"Query live caller-descriptor flow[" << ref_index
                                << L":" << step
                                << L"]: op="
                                << (operand.rip_relative
                                        ? L"mov_rip_mem"
                                        : (simple_base_only ? L"mov_reg_ptr" : L"mov_reg_mem"))
                                << L", dst=" << caller_descriptor_reg_name(dst_reg);
                            if (operand.rip_relative)
                            {
                                flow_stream << L", insn="
                                    << FormatModuleOwnerWithOffset(
                                           reinterpret_cast<void*>(flow_cursor));
                                if (address_known)
                                {
                                    flow_stream << L", cell="
                                        << FormatPointer(reinterpret_cast<void*>(source_address))
                                        << L", cell_owner="
                                        << FormatModuleOwnerWithOffset(
                                               reinterpret_cast<void*>(source_address));
                                }
                            }
                            else if (simple_base_only)
                            {
                                flow_stream << L", src=["
                                    << caller_descriptor_reg_name(operand.base_reg)
                                    << L"]";
                                if (operand.base_reg < tracked_registers.size() &&
                                    tracked_registers[operand.base_reg].known)
                                {
                                    flow_stream << L", src_value="
                                        << FormatPointer(
                                               reinterpret_cast<void*>(
                                                   tracked_registers[operand.base_reg].value));
                                }
                            }
                            else
                            {
                                flow_stream << L", src=";
                                append_memory_operand_text(flow_stream, operand);
                            }

                            if (!simple_base_only && !operand.rip_relative)
                            {
                                if (address_known)
                                {
                                    flow_stream << L", address="
                                        << FormatPointer(reinterpret_cast<void*>(source_address));
                                }
                                else
                                {
                                    flow_stream << L", base_value=<unknown>";
                                }
                            }

                            if (loaded_ok)
                            {
                                flow_stream << L", loaded="
                                    << FormatPointer(
                                           reinterpret_cast<void*>(
                                               static_cast<std::uintptr_t>(loaded_value)))
                                    << L", loaded_owner="
                                    << FormatModuleOwnerWithOffset(
                                           reinterpret_cast<void*>(
                                               static_cast<std::uintptr_t>(loaded_value)));
                                const auto* loaded_ptr =
                                    reinterpret_cast<const void*>(
                                        static_cast<std::uintptr_t>(loaded_value));
                                if (loaded_value >= kMinUserModePointer &&
                                    IsReadablePointer(loaded_ptr))
                                {
                                    flow_stream << L", loaded_region="
                                        << DescribeReadableMemoryRegion(
                                               const_cast<void*>(loaded_ptr),
                                               24);
                                    if (LooksLikeRuntimeRttiObjectPointer(loaded_ptr))
                                    {
                                        flow_stream << L", loaded_rtti="
                                            << BuildRuntimeEntityRttiDescriptor(loaded_ptr);
                                    }
                                }
                            }
                            else if (address_known)
                            {
                                flow_stream << L", loaded=<unreadable>";
                            }
                            nskinzcs2::Logger::Info(flow_stream.str());
                            ++detail_log_count;
                        }
                    }
                    else if ((flow_decoded.flags & F_MODRM) != 0 &&
                             (flow_decoded.flags & F_SIB) == 0 &&
                             flow_decoded.opcode == 0xFF &&
                             flow_decoded.modrm_reg == 2)
                    {
                        const auto base_reg = decode_modrm_rm_index(flow_decoded);
                        const auto is_rip_relative =
                            flow_decoded.modrm_mod == 0 && flow_decoded.modrm_rm == 5;
                        std::intptr_t slot_displacement = 0;
                        if ((flow_decoded.flags & F_DISP32) != 0)
                        {
                            slot_displacement =
                                static_cast<std::int32_t>(flow_decoded.disp.disp32);
                        }
                        else if ((flow_decoded.flags & F_DISP8) != 0)
                        {
                            slot_displacement =
                                static_cast<std::int8_t>(flow_decoded.disp.disp8);
                        }

                        std::uintptr_t base_value = 0;
                        bool base_value_known = false;
                        std::uintptr_t slot_address = 0;
                        bool slot_address_known = false;
                        if (is_rip_relative)
                        {
                            slot_address =
                                static_cast<std::uintptr_t>(
                                    static_cast<std::intptr_t>(flow_cursor) +
                                    static_cast<std::intptr_t>(flow_decoded.len) +
                                    slot_displacement);
                            slot_address_known = true;
                        }
                        else if (base_reg < tracked_registers.size() &&
                                 tracked_registers[base_reg].known)
                        {
                            base_value = tracked_registers[base_reg].value;
                            base_value_known = true;
                            slot_address =
                                static_cast<std::uintptr_t>(
                                    static_cast<std::intptr_t>(base_value) + slot_displacement);
                            slot_address_known = true;
                        }

                        if (slot_address_known)
                        {
                            std::uint64_t resolved_target = 0;
                            const auto resolved_ok = SafeReadValue(
                                reinterpret_cast<const void*>(slot_address),
                                resolved_target);
                            const auto append_target_summary =
                                [](std::wstringstream& stream,
                                    const wchar_t* label,
                                    void* target) noexcept
                                {
                                    stream << L", " << label << L"="
                                        << FormatPointer(target);
                                    if (target == nullptr)
                                    {
                                        return;
                                    }

                                    stream << L", " << label << L"_owner="
                                        << FormatModuleOwnerWithOffset(target);

                                    if (!IsExecutablePointer(target))
                                    {
                                        return;
                                    }

                                    void* function_start = nullptr;
                                    if (TryResolveContainingFunctionStart(target, function_start) &&
                                        function_start != nullptr)
                                    {
                                        stream << L", " << label << L"_fn="
                                            << FormatModuleOwnerWithOffset(function_start);
                                    }

                                    if (auto* body = FollowJumpStubs(target);
                                        body != nullptr && body != target)
                                    {
                                        stream << L", " << label << L"_body="
                                            << FormatPointer(body)
                                            << L", " << label << L"_body_owner="
                                            << FormatModuleOwnerWithOffset(body);
                                    }
                                };
                            const auto log_original_target_flow =
                                [&](const std::size_t parent_step,
                                    void* original_target,
                                    const std::uintptr_t seed_rcx) noexcept
                                {
                                    if (original_target == nullptr ||
                                        !IsExecutablePointer(original_target) ||
                                        detail_log_count >= kCallerDescriptorDetailBudget)
                                    {
                                        return;
                                    }

                                    std::array<std::uint8_t, 16> original_entry_bytes {};
                                    if (SafeReadBytes(
                                            original_target,
                                            original_entry_bytes.data(),
                                            original_entry_bytes.size()))
                                    {
                                        std::wstringstream entry_stream;
                                        entry_stream << L"Query live caller-descriptor original-entry["
                                            << ref_index
                                            << L":" << parent_step
                                            << L"]: entry_bytes="
                                            << FormatByteSequence(
                                                   original_entry_bytes.data(),
                                                   original_entry_bytes.size());
                                        nskinzcs2::Logger::Info(entry_stream.str());
                                        ++detail_log_count;
                                        if (detail_log_count >= kCallerDescriptorDetailBudget)
                                        {
                                            return;
                                        }
                                    }

                                    struct SecondaryTrackedRegister
                                    {
                                        bool known = false;
                                        std::uintptr_t value = 0;
                                    };

                                    std::array<SecondaryTrackedRegister, 16> secondary_registers {};
                                    const auto seed_secondary_register =
                                        [&](const std::uint32_t reg_index,
                                            const std::uintptr_t reg_value) noexcept
                                        {
                                            if (reg_index >= secondary_registers.size() ||
                                                reg_value == 0)
                                            {
                                                return;
                                            }

                                            secondary_registers[reg_index].known = true;
                                            secondary_registers[reg_index].value = reg_value;
                                        };

                                    seed_secondary_register(1, seed_rcx);
                                    seed_secondary_register(
                                        2,
                                        static_cast<std::uintptr_t>(arg2_ptrs[focus_index]));
                                    seed_secondary_register(
                                        8,
                                        static_cast<std::uintptr_t>(arg3_values[focus_index]));
                                    seed_secondary_register(
                                        9,
                                        static_cast<std::uintptr_t>(arg4_values[focus_index]));

                                    constexpr std::size_t kOriginalFlowInstructionBudget = 6u;
                                    std::uintptr_t original_cursor =
                                        reinterpret_cast<std::uintptr_t>(original_target);
                                    for (std::size_t original_step = 0;
                                         original_step < kOriginalFlowInstructionBudget &&
                                         detail_log_count < kCallerDescriptorDetailBudget;
                                         ++original_step)
                                    {
                                        hde64s original_decoded {};
                                        const auto original_length =
                                            static_cast<std::size_t>(
                                                hde64_disasm(
                                                    reinterpret_cast<const void*>(original_cursor),
                                                    &original_decoded));
                                        if (original_length == 0 ||
                                            original_decoded.len == 0 ||
                                            (original_decoded.flags & F_ERROR) != 0)
                                        {
                                            break;
                                        }

                                        auto begin_original_flow_stream =
                                            [&]() noexcept
                                            {
                                                std::wstringstream stream;
                                                stream << L"Query live caller-descriptor original-flow["
                                                    << ref_index
                                                    << L":" << parent_step
                                                    << L":" << original_step
                                                    << L"]: ";
                                                return stream;
                                            };

                                        if ((original_decoded.flags & F_MODRM) != 0 &&
                                            original_decoded.opcode == 0x8B &&
                                            original_decoded.modrm_mod != 3)
                                        {
                                            const auto dst_reg = decode_modrm_reg_index(original_decoded);
                                            CallerDescriptorMemoryOperand operand {};
                                            if (decode_memory_operand(original_decoded, operand))
                                            {
                                                std::uintptr_t source_address = 0;
                                                const auto address_known =
                                                    try_resolve_effective_address(
                                                        original_cursor,
                                                        original_decoded,
                                                        secondary_registers,
                                                        source_address,
                                                        &operand);
                                                std::uint64_t loaded_value = 0;
                                                const auto loaded_ok =
                                                    address_known &&
                                                    read_integer_width_zero_extended(
                                                        reinterpret_cast<const void*>(source_address),
                                                        resolve_gpr_memory_load_width(original_decoded),
                                                        loaded_value);
                                                if (dst_reg < secondary_registers.size())
                                                {
                                                    secondary_registers[dst_reg].known = loaded_ok;
                                                    secondary_registers[dst_reg].value =
                                                        static_cast<std::uintptr_t>(loaded_value);
                                                }

                                                const auto simple_base_only =
                                                    !operand.rip_relative &&
                                                    operand.segment_prefix == 0 &&
                                                    operand.has_base &&
                                                    !operand.has_index &&
                                                    operand.displacement == 0;

                                                auto flow_stream = begin_original_flow_stream();
                                                flow_stream << L"op="
                                                    << (operand.rip_relative
                                                            ? L"mov_rip_mem"
                                                            : (simple_base_only
                                                                    ? L"mov_reg_ptr"
                                                                    : L"mov_reg_mem"))
                                                    << L", dst="
                                                    << caller_descriptor_reg_name(dst_reg);
                                                if (operand.rip_relative)
                                                {
                                                    flow_stream << L", insn="
                                                        << FormatModuleOwnerWithOffset(
                                                               reinterpret_cast<void*>(original_cursor));
                                                    if (address_known)
                                                    {
                                                        flow_stream << L", cell="
                                                            << FormatPointer(
                                                                   reinterpret_cast<void*>(source_address))
                                                            << L", cell_owner="
                                                            << FormatModuleOwnerWithOffset(
                                                                   reinterpret_cast<void*>(source_address));
                                                    }
                                                }
                                                else if (simple_base_only)
                                                {
                                                    flow_stream << L", src=["
                                                        << caller_descriptor_reg_name(operand.base_reg)
                                                        << L"]";
                                                    if (operand.base_reg < secondary_registers.size() &&
                                                        secondary_registers[operand.base_reg].known)
                                                    {
                                                        flow_stream << L", src_value="
                                                            << FormatPointer(
                                                                   reinterpret_cast<void*>(
                                                                       secondary_registers
                                                                           [operand.base_reg]
                                                                               .value));
                                                    }
                                                }
                                                else
                                                {
                                                    flow_stream << L", src=";
                                                    append_memory_operand_text(flow_stream, operand);
                                                }

                                                if (!simple_base_only && !operand.rip_relative)
                                                {
                                                    if (address_known)
                                                    {
                                                        flow_stream << L", address="
                                                            << FormatPointer(
                                                                   reinterpret_cast<void*>(source_address));
                                                    }
                                                    else
                                                    {
                                                        flow_stream << L", base_value=<unknown>";
                                                    }
                                                }

                                                if (loaded_ok)
                                                {
                                                    flow_stream << L", loaded="
                                                        << FormatPointer(
                                                               reinterpret_cast<void*>(
                                                                   static_cast<std::uintptr_t>(
                                                                       loaded_value)))
                                                        << L", loaded_owner="
                                                        << FormatModuleOwnerWithOffset(
                                                               reinterpret_cast<void*>(
                                                                   static_cast<std::uintptr_t>(
                                                                       loaded_value)));
                                                }
                                                else if (address_known)
                                                {
                                                    flow_stream << L", loaded=<unreadable>";
                                                }
                                                nskinzcs2::Logger::Info(flow_stream.str());
                                                ++detail_log_count;
                                            }
                                        }
                                        else if ((original_decoded.flags & F_MODRM) != 0 &&
                                                 (original_decoded.flags & F_SIB) == 0 &&
                                                 original_decoded.opcode == 0x8D &&
                                                 original_decoded.modrm_mod == 0 &&
                                                 original_decoded.modrm_rm == 5 &&
                                                 (original_decoded.flags & F_DISP32) != 0)
                                        {
                                            const auto dst_reg = decode_modrm_reg_index(original_decoded);
                                            const auto address_base =
                                                static_cast<std::intptr_t>(original_cursor) +
                                                static_cast<std::intptr_t>(original_decoded.len);
                                            const auto effective_address =
                                                static_cast<std::uintptr_t>(
                                                    address_base +
                                                    static_cast<std::int32_t>(original_decoded.disp.disp32));
                                            if (dst_reg < secondary_registers.size())
                                            {
                                                secondary_registers[dst_reg].known = true;
                                                secondary_registers[dst_reg].value = effective_address;
                                            }

                                            auto flow_stream = begin_original_flow_stream();
                                            flow_stream << L"op=lea_rip, dst="
                                                << caller_descriptor_reg_name(dst_reg)
                                                << L", insn="
                                                << FormatModuleOwnerWithOffset(
                                                       reinterpret_cast<void*>(original_cursor))
                                                << L", addr="
                                                << FormatPointer(reinterpret_cast<void*>(effective_address))
                                                << L", addr_owner="
                                                << FormatModuleOwnerWithOffset(
                                                       reinterpret_cast<void*>(effective_address));
                                            nskinzcs2::Logger::Info(flow_stream.str());
                                            ++detail_log_count;
                                        }
                                        else if ((original_decoded.flags & F_MODRM) != 0 &&
                                                 (original_decoded.flags & F_SIB) == 0 &&
                                                 original_decoded.opcode == 0xFF &&
                                                 original_decoded.modrm_reg == 2)
                                        {
                                            const auto base_reg = decode_modrm_rm_index(original_decoded);
                                            const auto is_rip_relative =
                                                original_decoded.modrm_mod == 0 &&
                                                original_decoded.modrm_rm == 5;
                                            std::intptr_t slot_displacement = 0;
                                            if ((original_decoded.flags & F_DISP32) != 0)
                                            {
                                                slot_displacement =
                                                    static_cast<std::int32_t>(
                                                        original_decoded.disp.disp32);
                                            }
                                            else if ((original_decoded.flags & F_DISP8) != 0)
                                            {
                                                slot_displacement =
                                                    static_cast<std::int8_t>(
                                                        original_decoded.disp.disp8);
                                            }

                                            std::uintptr_t base_value = 0;
                                            bool base_value_known = false;
                                            std::uintptr_t slot_pointer = 0;
                                            bool slot_pointer_known = false;
                                            if (is_rip_relative)
                                            {
                                                slot_pointer =
                                                    static_cast<std::uintptr_t>(
                                                        static_cast<std::intptr_t>(original_cursor) +
                                                        static_cast<std::intptr_t>(original_decoded.len) +
                                                        slot_displacement);
                                                slot_pointer_known = true;
                                            }
                                            else if (base_reg < secondary_registers.size() &&
                                                     secondary_registers[base_reg].known)
                                            {
                                                base_value = secondary_registers[base_reg].value;
                                                base_value_known = true;
                                                slot_pointer =
                                                    static_cast<std::uintptr_t>(
                                                        static_cast<std::intptr_t>(base_value) +
                                                        slot_displacement);
                                                slot_pointer_known = true;
                                            }

                                            if (slot_pointer_known)
                                            {
                                                std::uint64_t indirect_target = 0;
                                                const auto indirect_ok = SafeReadValue(
                                                    reinterpret_cast<const void*>(slot_pointer),
                                                    indirect_target);

                                                auto flow_stream = begin_original_flow_stream();
                                                flow_stream << L"op=call_indirect, base="
                                                    << (is_rip_relative
                                                            ? L"rip"
                                                            : caller_descriptor_reg_name(base_reg));
                                                if (base_value_known)
                                                {
                                                    flow_stream << L", base_value="
                                                        << FormatPointer(reinterpret_cast<void*>(base_value));
                                                }
                                                flow_stream
                                                    << L", slot="
                                                    << (slot_displacement >= 0 ? L"+" : L"-")
                                                    << L"0x" << std::hex << std::uppercase
                                                    << static_cast<std::uint64_t>(
                                                           slot_displacement >= 0
                                                               ? slot_displacement
                                                               : -slot_displacement)
                                                    << std::dec << std::nouppercase
                                                    << L", slot_address="
                                                    << FormatPointer(
                                                           reinterpret_cast<void*>(slot_pointer));
                                                if (indirect_ok)
                                                {
                                                    append_target_summary(
                                                        flow_stream,
                                                        L"target",
                                                        reinterpret_cast<void*>(
                                                            static_cast<std::uintptr_t>(indirect_target)));
                                                }
                                                else
                                                {
                                                    flow_stream << L", target=<unreadable>";
                                                }
                                                nskinzcs2::Logger::Info(flow_stream.str());
                                                ++detail_log_count;
                                            }
                                        }
                                        else if (original_decoded.opcode == 0xE8 ||
                                                 original_decoded.opcode == 0xE9 ||
                                                 original_decoded.opcode == 0xEB)
                                        {
                                            std::uintptr_t branch_target = 0;
                                            if (resolve_relative_target(
                                                    original_cursor,
                                                    original_decoded,
                                                    branch_target))
                                            {
                                                auto flow_stream = begin_original_flow_stream();
                                                flow_stream << L"op="
                                                    << (original_decoded.opcode == 0xE8
                                                            ? L"call_rel"
                                                            : L"jmp_rel")
                                                    << L", insn="
                                                    << FormatModuleOwnerWithOffset(
                                                           reinterpret_cast<void*>(original_cursor))
                                                    << L", target="
                                                    << FormatPointer(
                                                           reinterpret_cast<void*>(branch_target));
                                                append_target_summary(
                                                    flow_stream,
                                                    L"target",
                                                    reinterpret_cast<void*>(branch_target));
                                                nskinzcs2::Logger::Info(flow_stream.str());
                                                ++detail_log_count;
                                            }
                                        }

                                        original_cursor += std::max<std::size_t>(1, original_length);
                                    }
                                };

                            std::wstringstream flow_stream;
                            flow_stream << L"Query live caller-descriptor flow[" << ref_index
                                << L":" << step
                                << L"]: op=call_indirect, base="
                                << (is_rip_relative
                                        ? L"rip"
                                        : caller_descriptor_reg_name(base_reg));
                            if (base_value_known)
                            {
                                flow_stream << L", base_value="
                                    << FormatPointer(reinterpret_cast<void*>(base_value));
                            }
                            flow_stream
                                << L", slot="
                                << (slot_displacement >= 0 ? L"+" : L"-")
                                << L"0x" << std::hex << std::uppercase
                                << static_cast<std::uint64_t>(
                                       slot_displacement >= 0
                                           ? slot_displacement
                                           : -slot_displacement)
                                << std::dec << std::nouppercase
                                << L", slot_address="
                                << FormatPointer(reinterpret_cast<void*>(slot_address));
                            if (resolved_ok)
                            {
                                const auto current_target_ptr =
                                    reinterpret_cast<void*>(
                                         static_cast<std::uintptr_t>(resolved_target));
                                flow_stream << L", resolved_target="
                                    << FormatPointer(current_target_ptr);
                                append_target_summary(
                                    flow_stream,
                                    L"slot_current",
                                    current_target_ptr);

                                QuerySlotDetourResolution detour_resolution {};
                                if (TryResolveKnifeModelPathSwapQuerySlotDetourLocked(
                                        reinterpret_cast<void*>(slot_address),
                                        current_target_ptr,
                                        detour_resolution) &&
                                    detour_resolution.matched)
                                {
                                    flow_stream << L", slot_detoured=1"
                                        << L", hook_index=" << detour_resolution.hook_index
                                        << L", hook_iface="
                                        << ResourceHandleQueryInterfaceKindText(
                                               detour_resolution.interface_kind)
                                        << L", hook_slot=";
                                    if (detour_resolution.query_slot == kInvalidResourceHandleQuerySlot)
                                    {
                                        flow_stream << L"?";
                                    }
                                    else
                                    {
                                        flow_stream << detour_resolution.query_slot;
                                    }

                                    flow_stream << L", slot_matches_patch="
                                        << (detour_resolution.slot_matches_patch ? 1 : 0)
                                        << L", current_matches_replacement="
                                        << (detour_resolution.current_matches_replacement ? 1 : 0);
                                    append_target_summary(
                                        flow_stream,
                                        L"slot_replacement",
                                        detour_resolution.replacement_target);
                                    append_target_summary(
                                        flow_stream,
                                        L"slot_original",
                                        detour_resolution.original_target);
                                    log_original_target_flow(
                                        step,
                                        detour_resolution.original_target,
                                        tracked_registers[1].known
                                            ? tracked_registers[1].value
                                            : 0);
                                }
                            }
                            else
                            {
                                flow_stream << L", resolved_target=<unreadable>";
                            }

                            if (tracked_registers[1].known &&
                                tracked_registers[1].value >= kMinUserModePointer)
                            {
                                const auto* this_ptr =
                                    reinterpret_cast<const void*>(tracked_registers[1].value);
                                flow_stream << L", rcx="
                                    << FormatPointer(
                                           reinterpret_cast<void*>(tracked_registers[1].value))
                                    << L", rcx_owner="
                                    << FormatModuleOwnerWithOffset(
                                           reinterpret_cast<void*>(tracked_registers[1].value));
                                if (IsReadablePointer(this_ptr) &&
                                    LooksLikeRuntimeRttiObjectPointer(this_ptr))
                                {
                                    flow_stream << L", rcx_rtti="
                                        << BuildRuntimeEntityRttiDescriptor(this_ptr);
                                }
                            }

                            nskinzcs2::Logger::Info(flow_stream.str());
                            ++detail_log_count;

                            log_primary_caller_return_flow(
                                ref_index,
                                step,
                                flow_cursor + std::max<std::size_t>(1, flow_length),
                                tracked_registers);
                        }
                    }

                    flow_cursor += std::max<std::size_t>(1, flow_length);
                }
                return;
            }

            if (candidate.kind == CallerDescriptorReferenceKind::RipMem)
            {
                std::uint32_t field0 = 0;
                std::uint32_t field4 = 0;
                std::uint32_t field8 = 0;
                std::uint32_t fieldC = 0;
                std::uint64_t field10 = 0;
                std::uint64_t field18 = 0;
                const auto field0_ok = SafeReadValue(target_ptr, field0);
                const auto field4_ok = SafeReadValue(
                    reinterpret_cast<const std::uint8_t*>(target_ptr) + 0x4,
                    field4);
                const auto field8_ok = SafeReadValue(
                    reinterpret_cast<const std::uint8_t*>(target_ptr) + 0x8,
                    field8);
                const auto fieldC_ok = SafeReadValue(
                    reinterpret_cast<const std::uint8_t*>(target_ptr) + 0xC,
                    fieldC);
                const auto field10_ok = SafeReadValue(
                    reinterpret_cast<const std::uint8_t*>(target_ptr) + 0x10,
                    field10);
                const auto field18_ok = SafeReadValue(
                    reinterpret_cast<const std::uint8_t*>(target_ptr) + 0x18,
                    field18);

                std::wstringstream record_stream;
                record_stream << L"Query live caller-descriptor record[" << ref_index << L"]:";
                const auto append_dword_field =
                    [&](const std::size_t offset, const bool valid, const std::uint32_t raw_value)
                    {
                        record_stream << L" dword+0x" << std::hex << std::uppercase << offset
                            << std::dec << std::nouppercase << L"=";
                        if (!valid)
                        {
                            record_stream << L"<unreadable>";
                            return;
                        }

                        record_stream << L"0x" << std::hex << std::uppercase << raw_value
                            << std::dec << std::nouppercase;
                        const auto usage_text = build_scalar_usage_text(raw_value);
                        if (!usage_text.empty())
                        {
                            record_stream << L"(" << usage_text << L")";
                        }
                    };
                append_dword_field(0x0, field0_ok, field0);
                append_dword_field(0x4, field4_ok, field4);
                append_dword_field(0x8, field8_ok, field8);
                append_dword_field(0xC, fieldC_ok, fieldC);

                const auto append_qword_field =
                    [&](const std::size_t offset, const bool valid, const std::uint64_t raw_value)
                    {
                        record_stream << L" qword+0x" << std::hex << std::uppercase << offset
                            << std::dec << std::nouppercase << L"=";
                        if (!valid)
                        {
                            record_stream << L"<unreadable>";
                            return;
                        }

                        record_stream << L"0x" << std::hex << std::uppercase << raw_value
                            << std::dec << std::nouppercase;
                    };
                append_qword_field(0x10, field10_ok, field10);
                append_qword_field(0x18, field18_ok, field18);
                nskinzcs2::Logger::Info(record_stream.str());
                ++detail_log_count;

                const auto log_pointer_field =
                    [&](const std::size_t offset,
                        const std::uint64_t raw_value,
                        const wchar_t* role_label)
                    {
                        if (detail_log_count >= kCallerDescriptorDetailBudget ||
                            raw_value < kMinUserModePointer)
                        {
                            return;
                        }

                        const auto* field_ptr =
                            reinterpret_cast<const void*>(static_cast<std::uintptr_t>(raw_value));
                        std::wstringstream field_stream;
                        field_stream << L"Query live caller-descriptor record[" << ref_index
                            << L"] field[+0x" << std::hex << std::uppercase << offset
                            << std::dec << std::nouppercase
                            << L"]: role=" << (role_label != nullptr ? role_label : L"?")
                            << L", ptr=" << FormatPointer(const_cast<void*>(field_ptr))
                            << L", owner="
                            << FormatModuleOwnerWithOffset(const_cast<void*>(field_ptr));

                        if (IsExecutablePointer(field_ptr))
                        {
                            void* field_function_start = nullptr;
                            if (TryResolveContainingFunctionStart(field_ptr, field_function_start) &&
                                field_function_start != nullptr)
                            {
                                field_stream << L", fn="
                                    << FormatModuleOwnerWithOffset(field_function_start);
                            }
                        }
                        else if (IsReadablePointer(field_ptr))
                        {
                            field_stream << L", score="
                                << ScoreResourceHandleQueryPointerOnlyCandidate(field_ptr)
                                << L", region="
                                << DescribeReadableMemoryRegion(const_cast<void*>(field_ptr), 24);

                            char pointed_sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
                            std::size_t pointed_window_offset = 0;
                            std::uint32_t pointed_window_score = 0;
                            if (TryCaptureAsciiSampleNoexcept(
                                    reinterpret_cast<const char*>(field_ptr),
                                    pointed_sample,
                                    std::size(pointed_sample)))
                            {
                                field_stream << L", sample="
                                    << NarrowToWide(std::string(pointed_sample));
                            }
                            else if (TryCaptureInterestingResourceHandleQuerySemanticWindowSample(
                                         field_ptr,
                                         0x80u,
                                         pointed_sample,
                                         std::size(pointed_sample),
                                         pointed_window_offset,
                                         pointed_window_score))
                            {
                                field_stream << L", window_sample="
                                    << NarrowToWide(std::string(pointed_sample))
                                    << L", window_offset=0x" << std::hex << std::uppercase
                                    << pointed_window_offset
                                    << std::dec << std::nouppercase
                                    << L", window_score=" << pointed_window_score;
                            }

                            if (LooksLikeRuntimeRttiObjectPointer(field_ptr))
                            {
                                const auto rtti = BuildRuntimeEntityRttiDescriptor(field_ptr);
                                field_stream << L", rtti=" << rtti;
                                if (rtti.find(L"CRenderingWorldSession") != std::wstring::npos)
                                {
                                    field_stream << L", session_candidate=1";
                                }
                            }
                        }

                        nskinzcs2::Logger::Info(field_stream.str());
                        ++detail_log_count;

                        if (detail_log_count < kCallerDescriptorDetailBudget &&
                            LooksLikeRuntimeRttiObjectPointer(field_ptr))
                        {
                            const auto rtti = BuildRuntimeEntityRttiDescriptor(field_ptr);
                            if (rtti.find(L"CRenderingWorldSession") != std::wstring::npos)
                            {
                                TryLogResourceHandleQueryRenderingSessionDescriptorRelation(
                                    ref_index,
                                    offset,
                                    field_ptr,
                                    scalar_values,
                                    scalar_usages,
                                    scalar_count,
                                    detail_log_count,
                                    kCallerDescriptorDetailBudget);
                            }
                        }
                    };

                if (field10_ok)
                {
                    log_pointer_field(0x10, field10, L"descriptor_ptr0");
                }
                if (field18_ok)
                {
                    log_pointer_field(0x18, field18, L"descriptor_ptr1");
                }
            }

            if (scalar_count == 0 || detail_log_count >= kCallerDescriptorDetailBudget)
            {
                return;
            }

            MEMORY_BASIC_INFORMATION target_region_info {};
            if (!TryQueryCommittedReadableRegion(target_ptr, target_region_info))
            {
                return;
            }

            const auto target_region_start =
                reinterpret_cast<std::uintptr_t>(target_region_info.BaseAddress);
            const auto target_region_end =
                target_region_start + target_region_info.RegionSize;
            if (target_region_end <= target_region_start)
            {
                return;
            }

            const auto local_start = std::max(
                target_region_start,
                target_address > static_cast<std::uintptr_t>(0x40u)
                    ? target_address - static_cast<std::uintptr_t>(0x40u)
                    : target_region_start);
            const auto local_end = std::min<std::uintptr_t>(
                target_region_end,
                target_address + kCallerDescriptorTargetSampleWindowBytes);
            std::size_t local_match_count = 0;
            for (auto address = local_start;
                 address + sizeof(std::uint32_t) <= local_end &&
                 local_match_count < kCallerDescriptorScalarMatchBudget &&
                 detail_log_count < kCallerDescriptorDetailBudget;
                 ++address)
            {
                std::uint32_t raw32 = 0;
                if (!SafeReadValue(reinterpret_cast<const void*>(address), raw32))
                {
                    continue;
                }

                for (std::size_t scalar_index = 0; scalar_index < scalar_count; ++scalar_index)
                {
                    if (raw32 != scalar_values[scalar_index])
                    {
                        continue;
                    }

                    const auto delta =
                        address >= target_address
                            ? static_cast<std::uint64_t>(address - target_address)
                            : static_cast<std::uint64_t>(target_address - address);
                    std::wstringstream scalar_stream;
                    scalar_stream << L"Query live caller-descriptor scalar[" << ref_index
                        << L"]: value=0x" << std::hex << std::uppercase << raw32
                        << std::dec << std::nouppercase
                        << L", usage=" << scalar_usages[scalar_index]
                        << L", address="
                        << FormatPointer(reinterpret_cast<void*>(address))
                        << L", owner="
                        << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(address))
                        << L", target_delta="
                        << (address >= target_address ? L"+" : L"-")
                        << L"0x" << std::hex << std::uppercase << delta
                        << std::dec << std::nouppercase;
                    nskinzcs2::Logger::Info(scalar_stream.str());
                    ++local_match_count;
                    ++detail_log_count;
                    break;
                }
            }
        };

    for (auto cursor = scan_start; cursor < scan_end;)
    {
        hde64s decoded {};
        const auto length =
            static_cast<std::size_t>(
                hde64_disasm(reinterpret_cast<const void*>(cursor), &decoded));
        if (length == 0 || decoded.len == 0 || (decoded.flags & F_ERROR) != 0)
        {
            ++cursor;
            continue;
        }

        if ((decoded.flags & F_MODRM) != 0 &&
            decoded.modrm_mod == 0 &&
            decoded.modrm_rm == 5 &&
            (decoded.flags & F_DISP32) != 0)
        {
            ++rip_ref_count;
            const auto base =
                static_cast<std::intptr_t>(cursor) +
                static_cast<std::intptr_t>(decoded.len);
            const auto target_address =
                static_cast<std::uintptr_t>(
                    base + static_cast<std::int32_t>(decoded.disp.disp32));
            append_unique_candidate(
                rip_candidates,
                rip_candidate_count,
                {CallerDescriptorReferenceKind::RipMem, cursor, target_address});
        }

        if ((decoded.flags & F_RELATIVE) != 0)
        {
            std::uintptr_t target_address = 0;
            if (resolve_relative_target(cursor, decoded, target_address))
            {
                if (decoded.opcode == 0xE8)
                {
                    ++call_ref_count;
                    append_unique_candidate(
                        call_candidates,
                        call_candidate_count,
                        {CallerDescriptorReferenceKind::CallRel, cursor, target_address});
                }
                else if (decoded.opcode == 0xE9 || decoded.opcode == 0xEB)
                {
                    ++jmp_ref_count;
                    append_unique_candidate(
                        jmp_candidates,
                        jmp_candidate_count,
                        {CallerDescriptorReferenceKind::JmpRel, cursor, target_address});
                }
            }
        }

        const auto skip_immediate_match =
            (decoded.flags & F_RELATIVE) != 0 &&
            (decoded.opcode == 0xE8 || decoded.opcode == 0xE9 || decoded.opcode == 0xEB);
        if (!skip_immediate_match &&
            scalar_count != 0 &&
            detail_log_count < kCallerDescriptorDetailBudget)
        {
            std::uint64_t immediate_value = 0;
            std::uint32_t immediate_bits = 0;
            std::wstring matched_usage;
            if ((decoded.flags & F_IMM64) != 0)
            {
                immediate_value = decoded.imm.imm64;
                immediate_bits = 64;
            }
            else if ((decoded.flags & F_IMM32) != 0)
            {
                immediate_value = decoded.imm.imm32;
                immediate_bits = 32;
            }
            else if ((decoded.flags & F_IMM16) != 0)
            {
                immediate_value = decoded.imm.imm16;
                immediate_bits = 16;
            }
            else if ((decoded.flags & F_IMM8) != 0)
            {
                immediate_value = decoded.imm.imm8;
                immediate_bits = 8;
            }

            if (immediate_bits != 0)
            {
                for (std::size_t scalar_index = 0; scalar_index < scalar_count; ++scalar_index)
                {
                    const auto scalar_value = scalar_values[scalar_index];
                    bool matched = false;
                    if (immediate_bits == 64)
                    {
                        matched = immediate_value == scalar_value;
                    }
                    else if (immediate_bits == 32)
                    {
                        matched = immediate_value == scalar_value;
                    }
                    else if (immediate_bits == 16)
                    {
                        matched =
                            scalar_value <= 0xFFFFu &&
                            immediate_value == static_cast<std::uint16_t>(scalar_value);
                    }
                    else if (immediate_bits == 8)
                    {
                        matched =
                            scalar_value <= 0xFFu &&
                            immediate_value == static_cast<std::uint8_t>(scalar_value);
                    }

                    if (!matched)
                    {
                        continue;
                    }

                    if (!matched_usage.empty())
                    {
                        matched_usage += L"|";
                    }
                    matched_usage += scalar_usages[scalar_index];
                }
            }

            if (!matched_usage.empty())
            {
                std::wstringstream immediate_stream;
                immediate_stream << L"Query live caller-descriptor immediate["
                    << immediate_match_count
                    << L"]: insn="
                    << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(cursor))
                    << L", bits=" << immediate_bits
                    << L", value=0x" << std::hex << std::uppercase << immediate_value
                    << std::dec << std::nouppercase
                    << L", matches=" << matched_usage;
                nskinzcs2::Logger::Info(immediate_stream.str());
                ++immediate_match_count;
                ++detail_log_count;
            }
        }

        cursor += std::max<std::size_t>(1, length);
    }

    for (std::size_t index = 0;
         index < call_candidate_count && ref_log_count < kCallerDescriptorRefBudget;
         ++index)
    {
        log_target_details(call_candidates[index]);
    }
    for (std::size_t index = 0;
         index < jmp_candidate_count && ref_log_count < kCallerDescriptorRefBudget;
         ++index)
    {
        log_target_details(jmp_candidates[index]);
    }
    for (std::size_t index = 0;
         index < rip_candidate_count && ref_log_count < kCallerDescriptorRefBudget;
         ++index)
    {
        log_target_details(rip_candidates[index]);
    }

    std::wstringstream summary_stream;
    summary_stream << L"Query live caller-descriptor relation: refs={rip:"
        << rip_ref_count
        << L",call:" << call_ref_count
        << L",jmp:" << jmp_ref_count
        << L",imm:" << immediate_match_count
        << L"}, logged_refs=" << ref_log_count;
    nskinzcs2::Logger::Info(summary_stream.str());

    if (rip_ref_count == 0)
    {
        nskinzcs2::Logger::Info(
            L"Query live caller-descriptor relation: no_rip_relative_descriptor_candidate_near_primary_caller");
    }

    finalize_capture();
}

bool TryCaptureResourceHandleQueryUpstreamProbeCandidate(
    const char* label,
    const void* candidate,
    ResourceHandleQueryUpstreamProbeScratch& scratch,
    const bool allow_pointer_only,
    ResourceHandleQueryUpstreamProbeSampleKind* appended_kind = nullptr) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    if (appended_kind != nullptr)
    {
        *appended_kind = ResourceHandleQueryUpstreamProbeSampleKind::None;
    }

    if (label == nullptr || candidate == nullptr ||
        scratch.found_resource_like ||
        probe.upstream_probe_sample_count >= probe.upstream_probe_samples.size())
    {
        return false;
    }

    char sample[kResourceHandleQueryUpstreamProbeSampleCapacity] {};
    const auto pointer_value = reinterpret_cast<std::uintptr_t>(candidate);
    const auto ascii_sample_ok =
        TryCaptureAsciiSampleNoexcept(
            reinterpret_cast<const char*>(candidate),
            sample,
            std::size(sample));

    bool resource_like = false;
    const char* sample_text = nullptr;
    auto sample_kind = ResourceHandleQueryUpstreamProbeSampleKind::None;
    std::uint16_t pointer_score = 0;
    if (ascii_sample_ok)
    {
        resource_like = LooksLikeResourceSample(sample);
        sample_text = sample;
        sample_kind = ResourceHandleQueryUpstreamProbeSampleKind::AsciiPreview;
    }
    else if (allow_pointer_only &&
             pointer_value >= kMinUserModePointer &&
             !IsExecutablePointer(candidate))
    {
        pointer_score = ScoreResourceHandleQueryPointerOnlyCandidate(candidate);
        if (pointer_score < kResourceHandleQueryUpstreamPointerOnlySampleMinScore)
        {
            return false;
        }
        sample_text = kResourceHandleQueryUpstreamPointerOnlySample;
        sample_kind = ResourceHandleQueryUpstreamProbeSampleKind::PointerOnly;
    }
    else
    {
        return false;
    }

    const auto frame_index =
        std::min<std::size_t>(scratch.current_frame_index, scratch.frame_sample_counts.size() - 1);
    if (!resource_like)
    {
        if (sample_kind == ResourceHandleQueryUpstreamProbeSampleKind::AsciiPreview &&
            IsNoisyResourceHandleQueryUpstreamSample(sample))
        {
            return false;
        }

        const auto non_resource_limit =
            frame_index == 0
                ? kResourceHandleQueryUpstreamProbeMaxNonResourceSamplesFrame0
                : kResourceHandleQueryUpstreamProbeMaxNonResourceSamplesOtherFrames;
        if (scratch.frame_non_resource_counts[frame_index] >= non_resource_limit ||
            scratch.frame_sample_counts[frame_index] >=
                kResourceHandleQueryUpstreamProbeMaxSamplesPerFrame)
        {
            return false;
        }
    }
    else if (scratch.frame_sample_counts[frame_index] >=
        kResourceHandleQueryUpstreamProbeMaxSamplesPerFrame)
    {
        return false;
    }

    TryAppendResourceHandleQueryUpstreamProbeSample(
        label,
        sample_text,
        resource_like,
        pointer_value,
        pointer_score,
        sample_kind);
    ++scratch.frame_sample_counts[frame_index];
    if (!resource_like)
    {
        ++scratch.frame_non_resource_counts[frame_index];
    }
    if (resource_like)
    {
        scratch.found_resource_like = true;
    }

    if (appended_kind != nullptr)
    {
        *appended_kind = sample_kind;
    }

    return true;
}

void TryCaptureResourceHandleQueryUpstreamProbeObject(
    const char* label,
    const void* base,
    ResourceHandleQueryUpstreamProbeScratch& scratch,
    const std::size_t depth) noexcept;

void TryCaptureResourceHandleQueryUpstreamProbePointerField(
    const char* label,
    const void* base,
    const std::size_t offset,
    ResourceHandleQueryUpstreamProbeScratch& scratch,
    const std::size_t depth) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    if (label == nullptr || base == nullptr ||
        scratch.found_resource_like ||
        depth >= kResourceHandleQueryUpstreamProbeMaxDepth ||
        !IsReadablePointer(base))
    {
        return;
    }

    const void* nested = nullptr;
    if (!SafeReadValue(reinterpret_cast<const std::uint8_t*>(base) + offset, nested) ||
        nested == nullptr ||
        nested == base)
    {
        return;
    }

    const auto nested_value = reinterpret_cast<std::uintptr_t>(nested);
    if (nested_value < kMinUserModePointer)
    {
        return;
    }

    char field_label[kResourceHandleQueryUpstreamProbeLabelCapacity] {};
    sprintf_s(field_label, "%s[*+0x%02zX]", label, offset);
    const auto previous_sample_count = probe.upstream_probe_sample_count;
    ResourceHandleQueryUpstreamProbeSampleKind appended_kind =
        ResourceHandleQueryUpstreamProbeSampleKind::None;
    TryCaptureResourceHandleQueryUpstreamProbeCandidate(
        field_label,
        nested,
        scratch,
        true,
        &appended_kind);
    if (appended_kind == ResourceHandleQueryUpstreamProbeSampleKind::PointerOnly &&
        probe.upstream_probe_sample_count > previous_sample_count &&
        probe.upstream_probe_sample_count > 0)
    {
        const auto& last_sample =
            probe.upstream_probe_samples[probe.upstream_probe_sample_count - 1];
        if (std::strcmp(last_sample.label.data(), field_label) == 0)
        {
            TryCaptureResourceHandleQueryUpstreamFocus(
                field_label,
                field_label,
                last_sample.sample.data(),
                nested,
                0,
                last_sample.pointer_score);
        }
    }
    if (scratch.found_resource_like ||
        depth + 1 >= kResourceHandleQueryUpstreamProbeMaxDepth)
    {
        return;
    }

    TryCaptureResourceHandleQueryUpstreamProbeObject(
        field_label,
        nested,
        scratch,
        depth + 1);
}

void TryCaptureResourceHandleQueryUpstreamProbeInlineField(
    const char* label,
    const void* base,
    const std::size_t offset,
    ResourceHandleQueryUpstreamProbeScratch& scratch) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    if (label == nullptr || base == nullptr || scratch.found_resource_like || !IsReadablePointer(base))
    {
        return;
    }

    char field_label[kResourceHandleQueryUpstreamProbeLabelCapacity] {};
    sprintf_s(field_label, "%s{+0x%02zX}", label, offset);
    const auto previous_sample_count = probe.upstream_probe_sample_count;
    const auto previous_found = scratch.found_resource_like;
    TryCaptureResourceHandleQueryUpstreamProbeCandidate(
        field_label,
        reinterpret_cast<const std::uint8_t*>(base) + offset,
        scratch,
        false);
    if (!previous_found &&
        scratch.found_resource_like &&
        probe.upstream_probe_sample_count > previous_sample_count &&
        probe.upstream_probe_sample_count > 0)
    {
        const auto& last_sample =
            probe.upstream_probe_samples[probe.upstream_probe_sample_count - 1];
        if (last_sample.resource_like &&
            std::strcmp(last_sample.label.data(), field_label) == 0)
        {
            TryCaptureResourceHandleQueryUpstreamFocus(
                label,
                field_label,
                last_sample.sample.data(),
                base,
                offset,
                last_sample.pointer_score);
        }
    }
}

void TryCaptureResourceHandleQueryUpstreamProbeObject(
    const char* label,
    const void* base,
    ResourceHandleQueryUpstreamProbeScratch& scratch,
    const std::size_t depth) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    if (label == nullptr || base == nullptr ||
        depth >= kResourceHandleQueryUpstreamProbeMaxDepth ||
        scratch.found_resource_like ||
        probe.upstream_probe_sample_count >= probe.upstream_probe_samples.size())
    {
        return;
    }

    if (!IsReadablePointer(base) ||
        !TryVisitResourceHandleQueryUpstreamProbePointer(scratch, base))
    {
        return;
    }

    const auto previous_sample_count = probe.upstream_probe_sample_count;
    ResourceHandleQueryUpstreamProbeSampleKind appended_kind =
        ResourceHandleQueryUpstreamProbeSampleKind::None;
    TryCaptureResourceHandleQueryUpstreamProbeCandidate(
        label,
        base,
        scratch,
        true,
        &appended_kind);
    if (appended_kind == ResourceHandleQueryUpstreamProbeSampleKind::PointerOnly &&
        probe.upstream_probe_sample_count > previous_sample_count &&
        probe.upstream_probe_sample_count > 0)
    {
        const auto& last_sample =
            probe.upstream_probe_samples[probe.upstream_probe_sample_count - 1];
        if (std::strcmp(last_sample.label.data(), label) == 0)
        {
            TryCaptureResourceHandleQueryUpstreamFocus(
                label,
                label,
                last_sample.sample.data(),
                base,
                0,
                last_sample.pointer_score);
        }
    }
    if (scratch.found_resource_like ||
        probe.upstream_probe_sample_count >= probe.upstream_probe_samples.size())
    {
        return;
    }

    for (const auto offset : kResourceHandleQueryUpstreamProbeOffsets)
    {
        if (scratch.found_resource_like ||
            probe.upstream_probe_sample_count >= probe.upstream_probe_samples.size())
        {
            break;
        }

        TryCaptureResourceHandleQueryUpstreamProbeInlineField(label, base, offset, scratch);
        if (scratch.found_resource_like ||
            probe.upstream_probe_sample_count >= probe.upstream_probe_samples.size())
        {
            break;
        }

        TryCaptureResourceHandleQueryUpstreamProbePointerField(
            label,
            base,
            offset,
            scratch,
            depth);
    }
}

void TryCaptureResourceHandleQueryUpstreamProbeStackPointerSlot(
    const char* prefix,
    const std::uintptr_t rsp,
    const std::size_t offset,
    ResourceHandleQueryUpstreamProbeScratch& scratch) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    if (prefix == nullptr || rsp < kMinUserModePointer ||
        scratch.found_resource_like ||
        probe.upstream_probe_sample_count >= probe.upstream_probe_samples.size())
    {
        return;
    }

    const auto slot_address =
        reinterpret_cast<const void*>(rsp + offset);
    if (!IsReadablePointer(slot_address))
    {
        return;
    }

    const void* pointer_value = nullptr;
    if (!SafeReadValue(slot_address, pointer_value) || pointer_value == nullptr)
    {
        return;
    }

    char label[kResourceHandleQueryUpstreamProbeLabelCapacity] {};
    sprintf_s(label, "%s[+0x%02zX]", prefix, offset);
    const auto previous_sample_count = probe.upstream_probe_sample_count;
    ResourceHandleQueryUpstreamProbeSampleKind appended_kind =
        ResourceHandleQueryUpstreamProbeSampleKind::None;
    TryCaptureResourceHandleQueryUpstreamProbeCandidate(
        label,
        pointer_value,
        scratch,
        true,
        &appended_kind);
    if (appended_kind == ResourceHandleQueryUpstreamProbeSampleKind::PointerOnly &&
        probe.upstream_probe_sample_count > previous_sample_count &&
        probe.upstream_probe_sample_count > 0)
    {
        const auto& last_sample =
            probe.upstream_probe_samples[probe.upstream_probe_sample_count - 1];
        if (std::strcmp(last_sample.label.data(), label) == 0)
        {
            TryCaptureResourceHandleQueryUpstreamFocus(
                label,
                label,
                last_sample.sample.data(),
                pointer_value,
                0,
                last_sample.pointer_score);
        }
    }
    if (scratch.found_resource_like)
    {
        return;
    }

    TryCaptureResourceHandleQueryUpstreamProbeObject(label, pointer_value, scratch, 0);
}

void TryCaptureResourceHandleQueryUpstreamProbe(
    const std::uintptr_t caller_return_address) noexcept
{
    if (!IsResourceHandleQueryPrimaryCaller(reinterpret_cast<const void*>(caller_return_address)))
    {
        return;
    }

    auto& probe = g_hook_state.resource_handle_query_live_probe;
    std::uint32_t expected = kResourceHandleQueryCarrierCaptureNone;
    if (!probe.upstream_probe_capture_state.compare_exchange_strong(
            expected,
            kResourceHandleQueryCarrierCaptureWriting,
            std::memory_order_acq_rel))
    {
        return;
    }

    probe.upstream_probe_trigger_return_address = caller_return_address;
    probe.upstream_probe_rsp = 0;
    probe.upstream_probe_sample_count = 0;
    probe.upstream_probe_samples = {};

    CONTEXT context {};
    RtlCaptureContext(&context);
    probe.upstream_probe_rsp = context.Rsp;

    ResourceHandleQueryUpstreamProbeScratch scratch {};
    const HMODULE self_module =
        GetModuleFromAddress(reinterpret_cast<const void*>(&TryCaptureResourceHandleQueryUpstreamProbe));
    bool chain_started = false;
    std::uint32_t frame_depth = 0;

    for (std::uint32_t attempt = 0;
         attempt < 96 && frame_depth < kResourceHandleQueryUpstreamProbeMaxDepth;
         ++attempt)
    {
        if (!TryStepUnwindContextForResourceHandleQuery(context))
        {
            break;
        }

        const auto* frame = reinterpret_cast<const void*>(context.Rip);
        if (reinterpret_cast<std::uintptr_t>(frame) < kMinUserModePointer)
        {
            break;
        }

        if (GetModuleFromAddress(frame) == self_module)
        {
            continue;
        }

        if (!chain_started)
        {
            if (!IsResourceHandleQueryPrimaryCaller(frame))
            {
                continue;
            }

            chain_started = true;
        }

        scratch.current_frame_index = frame_depth;
        char prefix[32] {};
        sprintf_s(prefix, "frame%u_rsp", frame_depth);
        for (const auto offset : kResourceHandleQueryUpstreamStackPointerOffsets)
        {
            if (scratch.found_resource_like ||
                probe.upstream_probe_sample_count >= probe.upstream_probe_samples.size())
            {
                break;
            }

            TryCaptureResourceHandleQueryUpstreamProbeStackPointerSlot(
                prefix,
                context.Rsp,
                offset,
                scratch);
        }

        ++frame_depth;
    }

    probe.upstream_probe_capture_state.store(
        kResourceHandleQueryCarrierCapturePending,
        std::memory_order_release);
}

void FlushResourceHandleQueryLiveProbeTelemetry()
{
    if (g_hook_state.demo_playing.load(std::memory_order_acquire))
    {
        return;
    }

    auto& probe = g_hook_state.resource_handle_query_live_probe;
    const auto current_source_world_token =
        g_hook_state.knife_model_path_swap_state.source_world_token;
    const auto current_source_view_token =
        g_hook_state.knife_model_path_swap_state.source_view_token;
    const auto current_donor_world_token =
        g_hook_state.knife_model_path_swap_state.bridge_world_donor_token;
    const auto current_donor_view_token =
        g_hook_state.knife_model_path_swap_state.bridge_view_donor_token;
    if (current_source_world_token != 0)
    {
        probe.token_snapshot_source_world.store(current_source_world_token, std::memory_order_release);
    }
    if (current_source_view_token != 0)
    {
        probe.token_snapshot_source_view.store(current_source_view_token, std::memory_order_release);
    }
    if (current_donor_world_token != 0)
    {
        probe.token_snapshot_donor_world.store(current_donor_world_token, std::memory_order_release);
    }
    if (current_donor_view_token != 0)
    {
        probe.token_snapshot_donor_view.store(current_donor_view_token, std::memory_order_release);
    }
    const auto source_world_token_snapshot =
        probe.token_snapshot_source_world.load(std::memory_order_acquire);
    const auto source_view_token_snapshot =
        probe.token_snapshot_source_view.load(std::memory_order_acquire);
    const auto donor_world_token_snapshot =
        probe.token_snapshot_donor_world.load(std::memory_order_acquire);
    const auto donor_view_token_snapshot =
        probe.token_snapshot_donor_view.load(std::memory_order_acquire);

    if (probe.total_entered_count.load(std::memory_order_acquire) > 0)
    {
        std::uint32_t expected = 0;
        if (probe.first_entry_logged.compare_exchange_strong(
                expected,
                1,
                std::memory_order_acq_rel))
        {
            std::wstringstream stream;
            stream << L"Query live probe observed first detour entry: RHU_entered="
                << probe.entered_counts[0].load(std::memory_order_relaxed)
                << L", RS_entered="
                << probe.entered_counts[1].load(std::memory_order_relaxed);
            nskinzcs2::Logger::Info(stream.str());
        }
    }

    if (probe.capture_state.load(std::memory_order_acquire) ==
        kResourceHandleQueryCarrierCapturePending)
    {
        const auto hook_index = static_cast<std::size_t>(probe.capture_hook_index);
        const KnifeModelPathSwapQueryHookTarget* hook_target =
            hook_index < g_hook_state.knife_model_path_swap_query_hooks.size()
                ? &g_hook_state.knife_model_path_swap_query_hooks[hook_index]
                : nullptr;
        const auto interface_kind =
            hook_target != nullptr
                ? hook_target->interface_kind
                : ResourceHandleQueryInterfaceKind::None;
        const auto slot =
            hook_target != nullptr
                ? hook_target->slot
                : kInvalidResourceHandleQuerySlot;

        std::wstringstream stream;
        stream << L"Query live carrier probe: iface="
            << ResourceHandleQueryInterfaceKindText(interface_kind)
            << L", slot=";
        if (slot == kInvalidResourceHandleQuerySlot)
        {
            stream << L"?";
        }
        else
        {
            stream << slot;
        }

        stream << L", carrier="
            << NarrowToWide(std::string(probe.capture_carrier.data()))
            << L", this=" << FormatPointer(reinterpret_cast<void*>(probe.capture_this_ptr))
            << L", arg2=" << FormatPointer(reinterpret_cast<void*>(probe.capture_arg2_ptr))
            << L", arg3=" << FormatPointer(reinterpret_cast<void*>(probe.capture_arg3))
            << L", arg4=" << FormatPointer(reinterpret_cast<void*>(probe.capture_arg4))
            << L", RHU_entered="
            << probe.entered_counts[0].load(std::memory_order_relaxed)
            << L", RS_entered="
            << probe.entered_counts[1].load(std::memory_order_relaxed)
            << L", preview="
            << NarrowToWide(std::string(probe.capture_preview.data()));
        nskinzcs2::Logger::Info(stream.str());

        probe.capture_state.store(
            kResourceHandleQueryCarrierCaptureLogged,
            std::memory_order_release);
    }

    if (probe.caller_chain_capture_state.load(std::memory_order_acquire) ==
        kResourceHandleQueryCarrierCapturePending)
    {
        std::wstringstream summary_stream;
        summary_stream << L"Query live primary caller chain: trigger="
            << FormatModuleOwnerWithOffset(
                reinterpret_cast<void*>(probe.caller_chain_trigger_return_address))
            << L", frame_count=" << probe.caller_chain_frame_count;
        nskinzcs2::Logger::Info(summary_stream.str());

        const auto frame_count = std::min<std::uint32_t>(
            probe.caller_chain_frame_count,
            static_cast<std::uint32_t>(probe.caller_chain_frames.size()));
        for (std::uint32_t index = 0; index < frame_count; ++index)
        {
            void* function_start = nullptr;
            const auto* frame =
                reinterpret_cast<void*>(probe.caller_chain_frames[index]);
            const auto has_function_start =
                TryResolveContainingFunctionStart(frame, function_start);

            std::wstringstream frame_stream;
            frame_stream << L"Query live primary caller chain[" << index << L"]: frame="
                << FormatModuleOwnerWithOffset(frame)
                << L", fn=";
            if (has_function_start && function_start != nullptr)
            {
                frame_stream << FormatModuleOwnerWithOffset(function_start);
            }
            else
            {
                frame_stream << L"<unresolved>";
            }

            nskinzcs2::Logger::Info(frame_stream.str());
        }

        probe.caller_chain_capture_state.store(
            kResourceHandleQueryCarrierCaptureLogged,
            std::memory_order_release);
    }

    if (probe.upstream_probe_capture_state.load(std::memory_order_acquire) ==
        kResourceHandleQueryCarrierCapturePending)
    {
        std::wstringstream summary_stream;
        summary_stream << L"Query live upstream probe: trigger="
            << FormatModuleOwnerWithOffset(
                reinterpret_cast<void*>(probe.upstream_probe_trigger_return_address))
            << L", rsp=" << FormatPointer(reinterpret_cast<void*>(probe.upstream_probe_rsp))
            << L", samples=" << probe.upstream_probe_sample_count;
        nskinzcs2::Logger::Info(summary_stream.str());

        const auto sample_count = std::min<std::uint32_t>(
            probe.upstream_probe_sample_count,
            static_cast<std::uint32_t>(probe.upstream_probe_samples.size()));
        for (std::uint32_t index = 0; index < sample_count; ++index)
        {
            const auto& sample = probe.upstream_probe_samples[index];
            const auto pointer_value = sample.pointer_value;
            const auto sample_kind =
                static_cast<ResourceHandleQueryUpstreamProbeSampleKind>(sample.sample_kind);
            std::wstringstream sample_stream;
            sample_stream << L"Query live upstream sample[" << index << L"]: label="
                << NarrowToWide(std::string(sample.label.data()))
                << L", kind=" << ResourceHandleQueryUpstreamProbeSampleKindText(sample_kind)
                << L", resource_like=" << (sample.resource_like ? 1 : 0)
                << L", ptr=" << FormatPointer(reinterpret_cast<void*>(pointer_value));
            if (pointer_value >= kMinUserModePointer)
            {
                sample_stream << L", owner="
                    << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(pointer_value));
            }
            if (sample_kind == ResourceHandleQueryUpstreamProbeSampleKind::PointerOnly &&
                pointer_value >= kMinUserModePointer)
            {
                sample_stream << L", score=" << sample.pointer_score;
                sample_stream << L", region="
                    << DescribeReadableMemoryRegion(reinterpret_cast<void*>(pointer_value), 24);
                if (LooksLikeRuntimeRttiObjectPointer(reinterpret_cast<void*>(pointer_value)))
                {
                    sample_stream << L", rtti="
                        << BuildRuntimeEntityRttiDescriptor(reinterpret_cast<void*>(pointer_value));
                }
            }
            sample_stream
                << L", sample=" << NarrowToWide(std::string(sample.sample.data()));
            nskinzcs2::Logger::Info(sample_stream.str());
        }

        if (sample_count == 0)
        {
            nskinzcs2::Logger::Info(
                L"Query live upstream sample: no_readable_ascii_carrier_found_in_primary_caller_stack_window");
        }

        probe.upstream_probe_capture_state.store(
            kResourceHandleQueryCarrierCaptureLogged,
            std::memory_order_release);
    }

    if (probe.upstream_focus_capture_state.load(std::memory_order_acquire) ==
        kResourceHandleQueryCarrierCapturePending)
    {
        std::wstringstream summary_stream;
        summary_stream << L"Query live upstream focus: base_label="
            << NarrowToWide(std::string(probe.upstream_focus_base_label.data()))
            << L", base=" << FormatPointer(reinterpret_cast<void*>(probe.upstream_focus_base_ptr))
            << L", score=" << probe.upstream_focus_score
            << L", base_owner="
            << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(probe.upstream_focus_base_ptr))
            << L", base_region="
            << DescribeReadableMemoryRegion(reinterpret_cast<void*>(probe.upstream_focus_base_ptr), 24)
            << L", hit_label="
            << NarrowToWide(std::string(probe.upstream_focus_hit_label.data()))
            << L", hit_offset=0x" << std::hex << std::uppercase
            << probe.upstream_focus_hit_offset
            << std::dec << std::nouppercase
            << L", hit_sample="
            << NarrowToWide(std::string(probe.upstream_focus_hit_sample.data()));
        if (LooksLikeRuntimeRttiObjectPointer(reinterpret_cast<void*>(probe.upstream_focus_base_ptr)))
        {
            summary_stream << L", base_rtti="
                << BuildRuntimeEntityRttiDescriptor(reinterpret_cast<void*>(probe.upstream_focus_base_ptr));
        }
        nskinzcs2::Logger::Info(summary_stream.str());

        const auto field_count = std::min<std::uint32_t>(
            probe.upstream_focus_field_count,
            static_cast<std::uint32_t>(probe.upstream_focus_fields.size()));
        for (std::uint32_t index = 0; index < field_count; ++index)
        {
            const auto& field = probe.upstream_focus_fields[index];
            std::wstringstream field_stream;
            field_stream << L"Query live upstream focus field[0x"
                << std::hex << std::uppercase << field.offset
                << std::dec << std::nouppercase << L"]: raw=";
            if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagRawValid) != 0)
            {
                field_stream << L"0x" << std::hex << std::uppercase << field.raw_value
                    << std::dec << std::nouppercase;
                if (field.raw_value >= kMinUserModePointer)
                {
                    field_stream << L", owner="
                        << FormatModuleOwnerWithOffset(
                            reinterpret_cast<void*>(static_cast<std::uintptr_t>(field.raw_value)));
                }
                else
                {
                    field_stream << L", owner=<low_scalar>";
                }
            }
            else
            {
                field_stream << L"<unreadable>";
            }

            field_stream << L", flags=";
            bool first_flag = true;
            const auto append_flag =
                [&](const wchar_t* text)
                {
                    if (!first_flag)
                    {
                        field_stream << L"|";
                    }
                    first_flag = false;
                    field_stream << text;
                };
            if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagReadablePtr) != 0)
            {
                append_flag(L"readable_ptr");
            }
            if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagExecutablePtr) != 0)
            {
                append_flag(L"executable_ptr");
            }
            if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagInlineSample) != 0)
            {
                append_flag(L"inline_sample");
            }
            if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagPointedSample) != 0)
            {
                append_flag(L"pointed_sample");
            }
            if (first_flag)
            {
                field_stream << L"<none>";
            }

            if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagInlineSample) != 0)
            {
                field_stream << L", inline="
                    << NarrowToWide(std::string(field.inline_sample.data()));
            }
            if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagPointedSample) != 0)
            {
                field_stream << L", pointed="
                    << NarrowToWide(std::string(field.pointed_sample.data()));
            }
            if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagReadablePtr) != 0 &&
                field.raw_value >= kMinUserModePointer)
            {
                if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagExecutablePtr) == 0)
                {
                    field_stream << L", score=" << field.pointer_score;
                }
                field_stream << L", region="
                    << DescribeReadableMemoryRegion(
                           reinterpret_cast<void*>(static_cast<std::uintptr_t>(field.raw_value)),
                           16);
                if ((field.flags & kResourceHandleQueryUpstreamFocusFieldFlagExecutablePtr) == 0 &&
                    LooksLikeRuntimeRttiObjectPointer(
                        reinterpret_cast<void*>(static_cast<std::uintptr_t>(field.raw_value))))
                {
                    field_stream << L", rtti="
                        << BuildRuntimeEntityRttiDescriptor(
                               reinterpret_cast<void*>(static_cast<std::uintptr_t>(field.raw_value)));
                }
            }

            nskinzcs2::Logger::Info(field_stream.str());
        }

        probe.upstream_focus_capture_state.store(
            kResourceHandleQueryCarrierCaptureLogged,
            std::memory_order_release);
    }

    if (probe.upstream_token_relation_capture_state.load(std::memory_order_acquire) ==
        kResourceHandleQueryCarrierCaptureNone)
    {
        if (source_world_token_snapshot != 0 ||
            source_view_token_snapshot != 0 ||
            donor_world_token_snapshot != 0 ||
            donor_view_token_snapshot != 0)
        {
            std::uint32_t expected = kResourceHandleQueryCarrierCaptureNone;
            if (probe.upstream_token_relation_capture_state.compare_exchange_strong(
                    expected,
                    kResourceHandleQueryCarrierCaptureWriting,
                    std::memory_order_acq_rel))
            {
                if (source_world_token_snapshot != 0)
                {
                    LogResourceHandleQueryTokenRelationFor(
                        L"source_world",
                        source_world_token_snapshot,
                        probe);
                }
                if (source_view_token_snapshot != 0)
                {
                    LogResourceHandleQueryTokenRelationFor(
                        L"source_view",
                        source_view_token_snapshot,
                        probe);
                }
                if (donor_world_token_snapshot != 0)
                {
                    LogResourceHandleQueryTokenRelationFor(
                        L"donor_world",
                        donor_world_token_snapshot,
                        probe);
                }
                if (donor_view_token_snapshot != 0)
                {
                    LogResourceHandleQueryTokenRelationFor(
                        L"donor_view",
                        donor_view_token_snapshot,
                        probe);
                }

                probe.upstream_token_relation_capture_state.store(
                    kResourceHandleQueryCarrierCaptureLogged,
                    std::memory_order_release);
            }
        }
    }

    const auto sample_count =
        probe.result_sample_count.load(std::memory_order_acquire);
    const auto summary_logged =
        probe.result_sample_summary_logged.load(std::memory_order_acquire);
    const auto entered_total =
        probe.total_entered_count.load(std::memory_order_acquire);
    const auto token_scalar_capture_state =
        probe.upstream_token_scalar_relation_capture_state.load(std::memory_order_acquire);
    const auto low_scalar_carrier_capture_state =
        probe.upstream_low_scalar_carrier_capture_state.load(std::memory_order_acquire);
    const auto source_world_handle_snapshot =
        probe.handle_snapshot_source_world.load(std::memory_order_acquire);
    const auto source_view_handle_snapshot =
        probe.handle_snapshot_source_view.load(std::memory_order_acquire);
    const auto donor_world_handle_snapshot =
        probe.handle_snapshot_donor_world.load(std::memory_order_acquire);
    const auto donor_view_handle_snapshot =
        probe.handle_snapshot_donor_view.load(std::memory_order_acquire);
    const auto target_world_handle_snapshot =
        probe.handle_snapshot_target_world.load(std::memory_order_acquire);
    const auto target_view_handle_snapshot =
        probe.handle_snapshot_target_view.load(std::memory_order_acquire);
    const auto bridge_snapshot_ready =
        source_world_token_snapshot != 0 ||
        source_view_token_snapshot != 0 ||
        donor_world_token_snapshot != 0 ||
        donor_view_token_snapshot != 0 ||
        source_world_handle_snapshot != 0 ||
        source_view_handle_snapshot != 0 ||
        donor_world_handle_snapshot != 0 ||
        donor_view_handle_snapshot != 0 ||
        target_world_handle_snapshot != 0 ||
        target_view_handle_snapshot != 0;
    const auto token_scalar_ready =
        token_scalar_capture_state == kResourceHandleQueryCarrierCaptureNone &&
        (source_world_token_snapshot != 0 ||
         source_view_token_snapshot != 0 ||
         donor_world_token_snapshot != 0 ||
         donor_view_token_snapshot != 0);
    const auto low_scalar_carrier_ready =
        low_scalar_carrier_capture_state == kResourceHandleQueryCarrierCaptureNone &&
        bridge_snapshot_ready &&
        summary_logged >= 2;
    if (sample_count == 0)
    {
        if (summary_logged == 0 &&
            entered_total >= kResourceHandleQueryResultSampleNoDataEntryThreshold)
        {
            std::uint32_t expected_summary = 0;
            if (probe.result_sample_summary_logged.compare_exchange_strong(
                    expected_summary,
                    1,
                    std::memory_order_acq_rel))
            {
                std::wstringstream stream;
                stream << L"Query live result relation sample: no_result_samples_after_entries, RHU_entered="
                    << probe.entered_counts[0].load(std::memory_order_relaxed)
                    << L", RS_entered="
                    << probe.entered_counts[1].load(std::memory_order_relaxed);
                nskinzcs2::Logger::Info(stream.str());
            }
        }
        return;
    }

    if (summary_logged == 2 && !token_scalar_ready && !low_scalar_carrier_ready)
    {
        return;
    }

    std::uint32_t expected_lock = 0;
    if (!probe.result_sample_write_lock.compare_exchange_strong(
            expected_lock,
            1,
            std::memory_order_acq_rel))
    {
        return;
    }

    std::array<std::uint32_t, kResourceHandleQueryResultSampleSummaryCount> hook_indices {};
    std::array<std::uintptr_t, kResourceHandleQueryResultSampleSummaryCount> caller_return_addresses {};
    std::array<std::uintptr_t, kResourceHandleQueryResultSampleSummaryCount> arg2_ptrs {};
    std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount> arg3_values {};
    std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount> arg4_values {};
    std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount> handles {};
    std::array<std::uint8_t, kResourceHandleQueryResultSampleSummaryCount> shape_kinds {};
    std::array<std::uint8_t, kResourceHandleQueryResultSampleSummaryCount> payload_masks {};
    std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount> payload_qword0 {};
    std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount> payload_qword8 {};
    std::array<std::uint64_t, kResourceHandleQueryResultSampleSummaryCount> payload_qword10 {};
    const auto end_index = std::min(
        probe.result_sample_count.load(std::memory_order_relaxed),
        static_cast<std::uint32_t>(probe.result_sample_handles.size()));
    const auto summary_end = std::min(
        end_index,
        static_cast<std::uint32_t>(kResourceHandleQueryResultSampleSummaryCount));
    for (std::uint32_t index = 0; index < summary_end; ++index)
    {
        hook_indices[index] = probe.result_sample_hook_indices[index];
        caller_return_addresses[index] =
            probe.result_sample_caller_return_addresses[index];
        arg2_ptrs[index] = probe.result_sample_arg2_ptrs[index];
        arg3_values[index] = probe.result_sample_arg3_values[index];
        arg4_values[index] = probe.result_sample_arg4_values[index];
        handles[index] = probe.result_sample_handles[index];
        shape_kinds[index] = probe.result_sample_shape_kinds[index];
        payload_masks[index] = probe.result_sample_payload_masks[index];
        payload_qword0[index] = probe.result_sample_payload_qword0[index];
        payload_qword8[index] = probe.result_sample_payload_qword8[index];
        payload_qword10[index] = probe.result_sample_payload_qword10[index];
    }
    probe.result_sample_logged_count.store(end_index, std::memory_order_release);
    probe.result_sample_write_lock.store(0, std::memory_order_release);

    bool should_log_result_summary = false;
    if (summary_logged != 2)
    {
        auto expected_summary =
            probe.result_sample_summary_logged.load(std::memory_order_acquire);
        while (expected_summary != 2 &&
               !probe.result_sample_summary_logged.compare_exchange_weak(
                   expected_summary,
                   2,
                   std::memory_order_acq_rel))
        {
        }
        should_log_result_summary = expected_summary != 2;
    }

    if (should_log_result_summary)
    {
        std::uint32_t source_hits = 0;
        std::uint32_t target_hits = 0;
        std::uint32_t zero_hits = 0;
        std::uint32_t other_hits = 0;
        std::wstringstream sample_stream;
        sample_stream << L"Query live result relation sample: sampled="
            << summary_end
            << L", RHU_entered="
            << probe.entered_counts[0].load(std::memory_order_relaxed)
            << L", RS_entered="
            << probe.entered_counts[1].load(std::memory_order_relaxed);

        for (std::uint32_t index = 0; index < summary_end; ++index)
        {
            const auto sample_hook_index = static_cast<std::size_t>(hook_indices[index]);
            const KnifeModelPathSwapQueryHookTarget* sample_hook_target =
                sample_hook_index < g_hook_state.knife_model_path_swap_query_hooks.size()
                    ? &g_hook_state.knife_model_path_swap_query_hooks[sample_hook_index]
                    : nullptr;
            const auto sample_interface_kind =
                sample_hook_target != nullptr
                    ? sample_hook_target->interface_kind
                    : ResourceHandleQueryInterfaceKind::None;
            const auto sample_query_slot =
                sample_hook_target != nullptr
                    ? sample_hook_target->slot
                    : kInvalidResourceHandleQuerySlot;
            const wchar_t* sample_relation = L"other";
            if (handles[index] == 0)
            {
                sample_relation = L"zero";
                ++zero_hits;
            }
            else if (sample_hook_target != nullptr &&
                handles[index] == sample_hook_target->calibrated_source_handle)
            {
                sample_relation = L"calibrated_source";
                ++source_hits;
            }
            else if (sample_hook_target != nullptr &&
                handles[index] == sample_hook_target->calibrated_target_handle)
            {
                sample_relation = L"calibrated_target";
                ++target_hits;
            }
            else
            {
                ++other_hits;
            }

            sample_stream << L", s" << index << L"=";
            if (sample_query_slot == kInvalidResourceHandleQuerySlot)
            {
                sample_stream << L"?";
            }
            else
            {
                sample_stream << sample_query_slot;
            }
            sample_stream << L"/"
                << ResourceHandleQueryInterfaceKindText(sample_interface_kind)
                << L"/0x" << std::hex << std::uppercase << handles[index]
                << std::dec << std::nouppercase
                << L"(" << sample_relation << L")"
                << L"@arg2=" << FormatPointer(reinterpret_cast<void*>(arg2_ptrs[index]))
                << L",arg3=" << FormatPointer(reinterpret_cast<void*>(arg3_values[index]))
                << L",arg4=" << FormatPointer(reinterpret_cast<void*>(arg4_values[index]));
        }

        sample_stream << L", counts=source:" << source_hits
            << L", target:" << target_hits
            << L", zero:" << zero_hits
            << L", other:" << other_hits;
        nskinzcs2::Logger::Info(sample_stream.str());

        for (std::uint32_t index = 0; index < summary_end; ++index)
        {
            const auto sample_hook_index = static_cast<std::size_t>(hook_indices[index]);
            const KnifeModelPathSwapQueryHookTarget* sample_hook_target =
                sample_hook_index < g_hook_state.knife_model_path_swap_query_hooks.size()
                    ? &g_hook_state.knife_model_path_swap_query_hooks[sample_hook_index]
                    : nullptr;
            const auto sample_interface_kind =
                sample_hook_target != nullptr
                    ? sample_hook_target->interface_kind
                    : ResourceHandleQueryInterfaceKind::None;
            const auto sample_query_slot =
                sample_hook_target != nullptr
                    ? sample_hook_target->slot
                    : kInvalidResourceHandleQuerySlot;

            std::wstringstream detail_stream;
            detail_stream << L"Query live result shape sample[" << index << L"]: iface="
                << ResourceHandleQueryInterfaceKindText(sample_interface_kind)
                << L", slot=";
            if (sample_query_slot == kInvalidResourceHandleQuerySlot)
            {
                detail_stream << L"?";
            }
            else
            {
                detail_stream << sample_query_slot;
            }

            detail_stream << L", caller="
                << FormatModuleOwnerWithOffset(
                    reinterpret_cast<void*>(caller_return_addresses[index]))
                << L", result=" << FormatPointer(reinterpret_cast<void*>(handles[index]))
                << L", result_owner="
                << FormatModuleOwnerWithOffset(reinterpret_cast<void*>(handles[index]))
                << L", shape="
                << ResourceHandleQueryResultShapeKindText(
                    static_cast<ResourceHandleQueryResultShapeKind>(shape_kinds[index]))
                << L", arg2=" << FormatPointer(reinterpret_cast<void*>(arg2_ptrs[index]))
                << L", arg3=" << FormatPointer(reinterpret_cast<void*>(arg3_values[index]))
                << L", arg4=" << FormatPointer(reinterpret_cast<void*>(arg4_values[index]))
                << L", payload=";

            if (payload_masks[index] == 0)
            {
                detail_stream << L"<none>";
            }
            else
            {
                bool first_payload = true;
                const auto append_payload =
                    [&](const wchar_t* label, const std::uint64_t value)
                    {
                        if (!first_payload)
                        {
                            detail_stream << L",";
                        }
                        first_payload = false;
                        detail_stream << label
                            << L"=0x" << std::hex << std::uppercase << value
                            << std::dec << std::nouppercase;
                    };

                if ((payload_masks[index] & 0x1u) != 0)
                {
                    append_payload(L"[0]", payload_qword0[index]);
                }
                if ((payload_masks[index] & 0x2u) != 0)
                {
                    append_payload(L"[8]", payload_qword8[index]);
                }
                if ((payload_masks[index] & 0x4u) != 0)
                {
                    append_payload(L"[10]", payload_qword10[index]);
                }
            }

            nskinzcs2::Logger::Info(detail_stream.str());
        }
    }

    if (token_scalar_ready)
    {
        static std::atomic_uint32_t s_token_scalar_relation_before_logged {0};
        static std::atomic_uint32_t s_token_scalar_relation_after_logged {0};

        std::uint32_t expected_before_log = 0;
        if (s_token_scalar_relation_before_logged.compare_exchange_strong(
                expected_before_log,
                1,
                std::memory_order_acq_rel))
        {
            std::wstringstream before_stream;
            before_stream << L"Query live token scalar relation callsite: before"
                << L", summary_end=" << summary_end
                << L", result_sample_count="
                << probe.result_sample_count.load(std::memory_order_relaxed)
                << L", token_relation_state="
                << probe.upstream_token_relation_capture_state.load(std::memory_order_relaxed)
                << L", token_scalar_state="
                << probe.upstream_token_scalar_relation_capture_state.load(std::memory_order_relaxed)
                << L", source_world_token=0x" << std::hex << std::uppercase
                << source_world_token_snapshot
                << L", source_view_token=0x"
                << source_view_token_snapshot
                << L", donor_world_token=0x"
                << donor_world_token_snapshot
                << L", donor_view_token=0x"
                << donor_view_token_snapshot
                << std::dec << std::nouppercase;
            nskinzcs2::Logger::Info(before_stream.str());
        }

        TryLogResourceHandleQueryTokenScalarRelation(
            hook_indices,
            caller_return_addresses,
            arg2_ptrs,
            arg3_values,
            arg4_values,
            handles,
            summary_end,
            source_world_token_snapshot,
            source_view_token_snapshot,
            donor_world_token_snapshot,
            donor_view_token_snapshot);

        std::uint32_t expected_after_log = 0;
        if (s_token_scalar_relation_after_logged.compare_exchange_strong(
                expected_after_log,
                1,
                std::memory_order_acq_rel))
        {
            std::wstringstream after_stream;
            after_stream << L"Query live token scalar relation callsite: after"
                << L", token_scalar_state="
                << probe.upstream_token_scalar_relation_capture_state.load(std::memory_order_relaxed)
                << L", result_sample_summary_logged="
                << probe.result_sample_summary_logged.load(std::memory_order_relaxed);
            nskinzcs2::Logger::Info(after_stream.str());
        }
    }

    TryLogResourceHandleQueryLowScalarCarrierRelation(
        hook_indices,
        caller_return_addresses,
        arg2_ptrs,
        arg3_values,
        arg4_values,
        handles,
        summary_end,
        source_world_token_snapshot,
        source_view_token_snapshot,
        donor_world_token_snapshot,
        donor_view_token_snapshot);
}

void TrySampleResourceHandleQueryResult(
    const std::size_t hook_index,
    const char* path,
    const std::uint64_t arg3,
    const std::uint64_t arg4,
    const std::uint64_t result_handle,
    const std::uintptr_t caller_return_address) noexcept
{
    auto& probe = g_hook_state.resource_handle_query_live_probe;
    const auto sample_count = probe.result_sample_count.load(std::memory_order_relaxed);
    if (sample_count >= probe.result_sample_handles.size())
    {
        return;
    }

    std::uint32_t expected_lock = 0;
    if (!probe.result_sample_write_lock.compare_exchange_strong(
            expected_lock,
            1,
            std::memory_order_acq_rel))
    {
        return;
    }

    const auto write_index = probe.result_sample_count.load(std::memory_order_relaxed);
    if (write_index < probe.result_sample_handles.size())
    {
        ResourceHandleQueryResultShapeKind shape_kind =
            ResourceHandleQueryResultShapeKind::Unknown;
        std::uint8_t payload_mask = 0;
        std::uint64_t payload_qword0 = 0;
        std::uint64_t payload_qword8 = 0;
        std::uint64_t payload_qword10 = 0;
        SnapshotResourceHandleQueryResultShape(
            result_handle,
            shape_kind,
            payload_mask,
            payload_qword0,
            payload_qword8,
            payload_qword10);
        if (shape_kind == ResourceHandleQueryResultShapeKind::LowScalar)
        {
            TryCaptureResourceHandleQueryPrimaryCallerChain(caller_return_address);
            TryCaptureResourceHandleQueryUpstreamProbe(caller_return_address);
        }

        ResourceHandleQueryCallerRegisterSeed caller_register_seed {};
        if (shape_kind == ResourceHandleQueryResultShapeKind::LowScalar)
        {
            TryCaptureResourceHandleQueryCallerRegisterSeed(
                caller_return_address,
                caller_register_seed);
        }

        probe.result_sample_hook_indices[write_index] = static_cast<std::uint32_t>(hook_index);
        probe.result_sample_caller_return_addresses[write_index] = caller_return_address;
        probe.result_sample_arg2_ptrs[write_index] = reinterpret_cast<std::uintptr_t>(path);
        probe.result_sample_arg3_values[write_index] = arg3;
        probe.result_sample_arg4_values[write_index] = arg4;
        probe.result_sample_handles[write_index] = result_handle;
        probe.result_sample_shape_kinds[write_index] =
            static_cast<std::uint8_t>(shape_kind);
        probe.result_sample_payload_masks[write_index] = payload_mask;
        probe.result_sample_payload_qword0[write_index] = payload_qword0;
        probe.result_sample_payload_qword8[write_index] = payload_qword8;
        probe.result_sample_payload_qword10[write_index] = payload_qword10;
        probe.result_sample_caller_register_seeds[write_index] = caller_register_seed;
        probe.result_sample_count.store(write_index + 1, std::memory_order_release);
    }

    probe.result_sample_write_lock.store(0, std::memory_order_release);
}

bool TryContainsSubstringNoexcept(const char* haystack, const char* needle) noexcept
{
    if (haystack == nullptr || needle == nullptr || needle[0] == '\0')
    {
        return false;
    }

    __try
    {
        return strstr(haystack, needle) != nullptr;
    }
    __except (EXCEPTION_EXECUTE_HANDLER)
    {
        return false;
    }
}

bool TryResolveKnifeModelPathSwapRedirectPath(
    const char* path,
    const std::uint64_t arg3,
    const std::uint64_t arg4,
    const KnifeModelPathSwapState& swap_state,
    const char*& redirect_path,
    const char*& bucket_label,
    const wchar_t*& matched_input_label) noexcept
{
    redirect_path = nullptr;
    bucket_label = nullptr;
    matched_input_label = L"none";
    const auto effective_world_source_path =
        ResolveKnifeModelPathSwapEffectiveSourcePath(
            swap_state,
            KnifeModelPathSwapHandleBucket::World);
    const auto effective_view_source_path =
        ResolveKnifeModelPathSwapEffectiveSourcePath(
            swap_state,
            KnifeModelPathSwapHandleBucket::View);

    const auto try_match_candidate =
        [&](const char* candidate, const wchar_t* input_label, const bool allow_indirect) noexcept
        {
            const auto try_match_resolved_candidate =
                [&](const char* resolved_candidate, const wchar_t* resolved_label) noexcept
                {
                    if (resolved_candidate == nullptr ||
                        reinterpret_cast<std::uintptr_t>(resolved_candidate) < 0x10000)
                    {
                        return false;
                    }

                    char preview[kResourceHandleQueryMissTelemetryPreviewCapacity] {};
                    if (!TryCopyReadableAnsiPreviewNoexcept(
                            resolved_candidate,
                            preview,
                            sizeof(preview)))
                    {
                        return false;
                    }

                    const std::string normalized_preview =
                        NormalizeResourcePath(std::string {preview});
                    const auto compiled_variant =
                        EndsWithInsensitive(normalized_preview, ".vmdl_c");

                    if (KnifeModelPathMatchesExpectedPath(
                            normalized_preview,
                            effective_world_source_path))
                    {
                        redirect_path = ResolveKnifeModelPathSwapBucketPath(
                            swap_state,
                            KnifeModelPathSwapHandleBucket::World,
                            true,
                            compiled_variant);
                        bucket_label = "world";
                        matched_input_label = resolved_label;
                        return redirect_path != nullptr;
                    }

                    if (KnifeModelPathMatchesExpectedPath(
                            normalized_preview,
                            effective_view_source_path))
                    {
                        redirect_path = ResolveKnifeModelPathSwapBucketPath(
                            swap_state,
                            KnifeModelPathSwapHandleBucket::View,
                            true,
                            compiled_variant);
                        bucket_label = "view";
                        matched_input_label = resolved_label;
                        return redirect_path != nullptr;
                    }

                    return false;
                };

            if (try_match_resolved_candidate(candidate, input_label))
            {
                return true;
            }

            if (!allow_indirect)
            {
                return false;
            }

            std::uintptr_t indirect_pointer = 0;
            if (!TryReadPointerValueNoexcept(candidate, indirect_pointer) ||
                indirect_pointer < 0x10000)
            {
                return false;
            }

            const auto* indirect_label =
                std::wcscmp(input_label, L"arg2") == 0
                    ? L"arg2*"
                    : std::wcscmp(input_label, L"arg3") == 0
                        ? L"arg3*"
                        : std::wcscmp(input_label, L"arg4") == 0
                            ? L"arg4*"
                            : input_label;
            return try_match_resolved_candidate(
                reinterpret_cast<const char*>(indirect_pointer),
                indirect_label);
        };

    if (try_match_candidate(path, L"arg2", true))
    {
        return true;
    }

    if (try_match_candidate(
            reinterpret_cast<const char*>(static_cast<std::uintptr_t>(arg3)),
            L"arg3",
            true))
    {
        return true;
    }

    if (try_match_candidate(
            reinterpret_cast<const char*>(static_cast<std::uintptr_t>(arg4)),
            L"arg4",
            true))
    {
        return true;
    }

    return false;
}

const char* ResolveKnifeModelPathSwapReplayPathCandidate(
    const char* path) noexcept
{
    if (path != nullptr &&
        reinterpret_cast<std::uintptr_t>(path) >= 0x10000)
    {
        char preview[kResourceHandleQueryMissTelemetryPreviewCapacity] {};
        if (TryCopyReadableAnsiPreviewNoexcept(path, preview, sizeof(preview)))
        {
            return path;
        }

        std::uintptr_t indirect_pointer = 0;
        if (TryReadPointerValueNoexcept(path, indirect_pointer) &&
            indirect_pointer >= 0x10000)
        {
            const auto* indirect_path =
                reinterpret_cast<const char*>(indirect_pointer);
            if (TryCopyReadableAnsiPreviewNoexcept(
                    indirect_path,
                    preview,
                    sizeof(preview)))
            {
                return indirect_path;
            }
        }
    }

    return path;
}

KnifeModelPathSwapQueryHookTarget::Fn ResolveKnifeModelPathSwapQueryOriginal(
    const std::size_t hook_index) noexcept
{
    return hook_index < g_hook_state.knife_model_path_swap_query_hooks.size()
        ? g_hook_state.knife_model_path_swap_query_hooks[hook_index].original
        : nullptr;
}

const KnifeModelPathSwapHandleRedirect* FindKnifeModelPathSwapHandleRedirectInTable(
    const std::array<KnifeModelPathSwapHandleRedirect, kKnifeModelPathSwapHandleRedirectCapacity>&
        redirects,
    const std::size_t redirect_count,
    const std::uint64_t handle_value) noexcept
{
    if (handle_value == 0)
    {
        return nullptr;
    }

    const auto clamped_count = std::min(redirect_count, redirects.size());
    for (std::size_t index = 0; index < clamped_count; ++index)
    {
        const auto& redirect = redirects[index];
        if (redirect.source_handle == handle_value &&
            redirect.target_handle != 0 &&
            redirect.target_handle != handle_value)
        {
            return &redirect;
        }
    }

    return nullptr;
}

