bool nskinzcs2::runtime::KnifeRefreshHelperPolicyArmsOnRebuildReason(
    const KnifeRefreshHelperPolicy policy,
    const RuntimeRebuildReason reason) noexcept
{
    switch (policy)
    {
    case KnifeRefreshHelperPolicy::ManualOnly:
        return reason == RuntimeRebuildReason::ManualRefresh ||
            reason == RuntimeRebuildReason::ConfigChanged;
    case KnifeRefreshHelperPolicy::ManualOrSeekOnly:
        break;
    case KnifeRefreshHelperPolicy::Disabled:
    default:
        return false;
    }

    switch (reason)
    {
    case RuntimeRebuildReason::ManualRefresh:
    case RuntimeRebuildReason::DemoSeek:
    case RuntimeRebuildReason::FullUpdate:
        return true;
    case RuntimeRebuildReason::ConfigChanged:
    case RuntimeRebuildReason::PauseResume:
    case RuntimeRebuildReason::WatchedPlayerSwitch:
    case RuntimeRebuildReason::EntityListChanged:
    case RuntimeRebuildReason::None:
    default:
        return false;
    }
}

bool nskinzcs2::runtime::ShouldPreserveWeaponAppearanceSignaturesOnRebuildReason(
    const RuntimeRebuildReason reason) noexcept
{
    // Pause/resume and spectator-target transitions rebuild only the runtime
    // discovery cache. Source 2 keeps the same econ entities and their applied
    // material state alive, so forgetting the verified signatures here made
    // every later knife draw invoke the expensive material helper again.
    // Each fast path still verifies definition and attributes before trusting
    // these signatures. Seeks/full updates/entity-list changes may replace the
    // entities and therefore must invalidate them.
    // A manual Update may be a no-op (the user presses Update without changing
    // the profile). Keep the verified signatures so that path validates the
    // live fields and does not rebind the same model resource a second time.
    // A genuinely changed profile has a different desired signature and still
    // takes the full apply path.
    return reason == RuntimeRebuildReason::ManualRefresh ||
        reason == RuntimeRebuildReason::PauseResume ||
        reason == RuntimeRebuildReason::WatchedPlayerSwitch;
}

bool nskinzcs2::runtime::ShouldAllowWeaponRefreshHelperDispatch(
    const bool knife_request,
    const KnifeRefreshHelperPolicy policy,
    const bool knife_epoch_armed) noexcept
{
    if (!knife_request)
    {
        return true;
    }

    switch (policy)
    {
    case KnifeRefreshHelperPolicy::ManualOnly:
    case KnifeRefreshHelperPolicy::ManualOrSeekOnly:
        return knife_epoch_armed;
    case KnifeRefreshHelperPolicy::Disabled:
    default:
        return false;
    }
}

