nskinzcs2::runtime::KnifePersistentOwnerReacquireProbeResult
nskinzcs2::runtime::ProbeKnifePersistentOwnerReacquireForTests(
    const nskinzcs2::runtime::KnifePersistentOwnerReacquireProbeInput& input) noexcept
{
    KnifePersistentOwnerReacquireProbeResult result {};
    PendingKnifeFirstPersonReacquire pending {};
    int confirm_hits = 0;

    const auto first_decision =
        AdvancePendingKnifeFirstPersonReacquire(
            pending,
            input.xuid,
            input.world_entity_index,
            input.candidate_entity_index,
            input.candidate_definition_index,
            input.candidate_owner_kind,
            input.first_observation_frame,
            confirm_hits);
    result.first_pending = first_decision == KnifePersistentOwnerReacquireDecision::Pending;
    result.first_promoted = first_decision == KnifePersistentOwnerReacquireDecision::Confirmed;
    result.first_confirm_hits = confirm_hits;

    const auto second_decision =
        AdvancePendingKnifeFirstPersonReacquire(
            pending,
            input.xuid,
            input.world_entity_index,
            input.candidate_entity_index,
            input.candidate_definition_index,
            input.candidate_owner_kind,
            input.second_observation_frame,
            confirm_hits);
    result.second_pending = second_decision == KnifePersistentOwnerReacquireDecision::Pending;
    result.second_promoted = second_decision == KnifePersistentOwnerReacquireDecision::Confirmed;
    result.second_confirm_hits = confirm_hits;

    if (result.second_promoted)
    {
        result.first_person_entity_index = input.candidate_entity_index;
        result.animation_entity_index = input.candidate_entity_index;
        result.direct_render_source = false;
        result.render_only = false;
        result.owner_kind = input.candidate_owner_kind;
    }

    return result;
}

