std::uint64_t nskinzcs2::runtime::ProbeResolveWatchedKnifeTargetXuidForTests(
    const bool observer_resolved,
    const bool observer_chain_present,
    const std::uint64_t observer_target_xuid,
    const bool bridge_resolved,
    const std::uint64_t bridge_xuid,
    const std::uint64_t heuristic_watched_xuid) noexcept
{
    ObserverTargetResolution resolution {};
    resolution.state =
        observer_resolved
            ? ObserverTargetResolutionState::Resolved
            : observer_chain_present
                ? ObserverTargetResolutionState::Invalid
                : ObserverTargetResolutionState::Missing;
    resolution.target_xuid = observer_target_xuid;
    resolution.target_pawn_entity_index = observer_resolved ? 1 : -1;
    HeuristicXuidBridgeResolution bridge_resolution {};
    if (bridge_resolved)
    {
        bridge_resolution.state = HeuristicXuidBridgeState::DirectControllerScan;
        bridge_resolution.source = L"test_bridge";
        bridge_resolution.xuid = bridge_xuid;
        bridge_resolution.controller_entity_index = 7;
        bridge_resolution.pawn_entity_index = 11;
        bridge_resolution.pawn_entity = reinterpret_cast<void*>(1);
    }
    return ResolveWatchedXuidFromObserverOrBridge(
               resolution,
               bridge_resolution,
               heuristic_watched_xuid)
        .watched_xuid;
}
