std::vector<std::string> nskinzcs2::RuntimeController::BuildVersionCandidates(
    const std::string& prefix,
    const int min_value,
    const int max_value,
    const std::vector<std::string>& exact)
{
    std::vector<std::string> versions = exact;
    versions.reserve(versions.size() + static_cast<std::size_t>(max_value - min_value + 1));

    for (int value = max_value; value >= min_value; --value)
    {
        std::ostringstream stream;
        stream << prefix << std::setw(3) << std::setfill('0') << value;
        versions.push_back(stream.str());
    }

    return versions;
}

std::vector<std::string> nskinzcs2::RuntimeController::FilterVersionCandidates(
    const std::vector<std::string>& discovered_names,
    const std::string& prefix,
    const int min_value,
    const int max_value)
{
    std::vector<std::string> filtered;

    for (const auto& name : discovered_names)
    {
        if (name.rfind(prefix, 0) != 0)
        {
            continue;
        }

        const auto suffix = name.substr(prefix.size());
        if (suffix.empty() || !std::all_of(suffix.begin(), suffix.end(), [](const unsigned char ch) { return std::isdigit(ch) != 0; }))
        {
            continue;
        }

        const auto number = std::stoi(suffix);
        if (min_value <= number && number <= max_value)
        {
            filtered.push_back(name);
        }
    }

    std::sort(
        filtered.begin(),
        filtered.end(),
        [](const std::string& lhs, const std::string& rhs)
        {
            return lhs > rhs;
        });

    return filtered;
}

nskinzcs2::RuntimeController::RuntimeController(AppState& state, HMODULE module_instance)
    : state_(state)
    , module_instance_(module_instance)
{
    if (IsCs2Process(CurrentProcessPath()) && IsHlaeLoaded())
    {
        std::wstringstream event_name;
        event_name << L"Local\\nSkinzCS2.ManualRefresh." << GetCurrentProcessId();
        automation_refresh_event_ = CreateEventW(
            nullptr,
            FALSE,
            FALSE,
            event_name.str().c_str());
        if (automation_refresh_event_ != nullptr)
        {
            Logger::Info(L"Local HLAE regression refresh event enabled: " + event_name.str() + L".");
        }
        else
        {
            Logger::Warn(L"Local HLAE regression refresh event could not be created.");
        }

        std::wstringstream command_event_name;
        command_event_name << L"Local\\nSkinzCS2.DemoCommand." << GetCurrentProcessId();
        automation_demo_command_event_ = CreateEventW(
            nullptr,
            FALSE,
            FALSE,
            command_event_name.str().c_str());
        if (automation_demo_command_event_ != nullptr)
        {
            Logger::Info(
                L"Local demo command event enabled: " + command_event_name.str() +
                L" (sidecar: nSkinzCS2.demo-command.txt).");
        }
        else
        {
            Logger::Warn(L"Local demo command event could not be created.");
        }
    }
}

nskinzcs2::RuntimeController::~RuntimeController()
{
    Stop();
    if (automation_refresh_event_ != nullptr)
    {
        CloseHandle(automation_refresh_event_);
        automation_refresh_event_ = nullptr;
    }
    if (automation_demo_command_event_ != nullptr)
    {
        CloseHandle(automation_demo_command_event_);
        automation_demo_command_event_ = nullptr;
    }
}

void nskinzcs2::RuntimeController::Start()
{
    if (worker_.joinable())
    {
        return;
    }

    g_hook_state.app_state = &state_;
    g_hook_state.runtime_faulted.store(false);
    g_hook_state.weapon_skin_refresh_ready.store(false);
    g_hook_state.weapon_skin_refresh_state.store(nskinzcs2::runtime::WeaponSkinRefreshState::Disabled);
    g_hook_state.knife_refresh_helper_policy.store(kDefaultKnifeRefreshHelperPolicy);
    g_hook_state.knife_refresh_helper_epoch_generation.store(0);
    ClearKnifeRefreshHelperEpoch();
    g_hook_state.weapon_skin_refresh_attempted_since_rearm.store(false);
    g_hook_state.weapon_skin_refresh_unavailable_logged.store(false);
    g_hook_state.weapon_skin_refresh_fault_logged.store(false);
    g_hook_state.weapon_skin_refresh_rearm_logged.store(false);
    stop_requested_.store(false);
    global_swapper_early_attempted_.store(false);
    global_swapper_early_reason_.clear();
    global_swapper_early_route_.clear();
    hook_attempted_.store(false);
    hook_installed_.store(false);
    hook_activation_requested_.store(false);
    logged_unavailable_refresh_.store(false);
    worker_ = std::thread(&RuntimeController::WorkerLoop, this);
}

void nskinzcs2::RuntimeController::Stop()
{
    Logger::Info(L"Runtime stop requested.");
    stop_requested_.store(true);
    if (worker_.joinable())
    {
        worker_.join();
    }
    Logger::Info(L"Runtime stop: worker joined.");

    RunRuntimeCleanupSequence(L"Runtime stop cleanup", false, false);
    global_swapper_early_attempted_.store(false);
    global_swapper_early_reason_.clear();
    global_swapper_early_route_.clear();
    hook_attempted_.store(false);
    hook_installed_.store(false);
    hook_activation_requested_.store(false);
    logged_unavailable_refresh_.store(false);
    g_hook_state.app_state = nullptr;
    Logger::Info(L"Runtime stop completed.");
}

std::wstring nskinzcs2::RuntimeController::CurrentProcessPath()
{
    std::wstring buffer(MAX_PATH, L'\0');
    const auto length = GetModuleFileNameW(nullptr, buffer.data(), static_cast<DWORD>(buffer.size()));
    buffer.resize(length);
    return buffer;
}

bool nskinzcs2::RuntimeController::IsCs2Process(const std::wstring& process_path)
{
    const auto file_name = FileNameFromPath(process_path);
    return _wcsicmp(file_name.c_str(), L"cs2.exe") == 0;
}

bool nskinzcs2::RuntimeController::IsHlaeLoaded()
{
    return GetHlaeSource2Module() != nullptr ||
        GetModuleHandleW(L"AfxHookSource.dll") != nullptr;
}

std::vector<std::string> nskinzcs2::RuntimeController::EnumerateInterfaceNames(const wchar_t* module_name)
{
    return EnumerateInterfacesFromModule(GetModuleHandleW(module_name), module_name);
}

void* nskinzcs2::RuntimeController::ResolveCreateInterface(
    const wchar_t* module_name,
    const std::vector<std::string>& versions,
    std::string& out_version)
{
    const auto module = GetModuleHandleW(module_name);
    if (!module)
    {
        return nullptr;
    }

    const auto create_interface = reinterpret_cast<CreateInterfaceFn>(GetProcAddress(module, "CreateInterface"));
    if (!create_interface)
    {
        return nullptr;
    }

    for (const auto& version : versions)
    {
        if (void* pointer = create_interface(version.c_str(), nullptr))
        {
            out_version = version;
            return pointer;
        }
    }

    return nullptr;
}

std::wstring nskinzcs2::RuntimeController::ToWide(const std::string& value)
{
    return NarrowToWide(value);
}

nskinzcs2::runtime::Status nskinzcs2::RuntimeController::BuildStatusSkeleton()
{
    runtime::Status status;
    status.availability = runtime::Availability::Unknown;
    status.detail = L"Bootstrapping runtime.";
    return status;
}

void nskinzcs2::RuntimeController::WorkerLoop()
{
    __try
    {
        WorkerLoopImpl();
    }
    __except (LogStructuredThreadException(L"Runtime worker", GetExceptionInformation()))
    {
        ReportWorkerThreadFailure(L"Runtime worker raised a structured exception and was disabled.");
    }
}

void nskinzcs2::RuntimeController::WorkerLoopImpl()
{
    try
    {
        Logger::Info(L"Runtime worker started.");

        while (!stop_requested_.load() && !state_.ShutdownRequested())
        {
            Logger::FlushDeferred();
            FlushRuntimePerformanceTelemetry();
            if (automation_refresh_event_ != nullptr &&
                WaitForSingleObject(automation_refresh_event_, 0) == WAIT_OBJECT_0)
            {
                std::wstring module_path(MAX_PATH, L'\0');
                const auto module_path_length = GetModuleFileNameW(
                    module_instance_,
                    module_path.data(),
                    static_cast<DWORD>(module_path.size()));
                module_path.resize(module_path_length);
                const auto config_path =
                    std::filesystem::path(module_path).parent_path() /
                    L"nSkinzCS2.json";
                state_.ReplaceConfig(nskinzcs2::ConfigStore::Load(config_path));
                state_.RequestManualRefresh();
                Logger::Info(
                    L"Runtime reloaded nSkinzCS2.json and queued Update from the isolated UI/regression event.");
            }

            if (automation_demo_command_event_ != nullptr &&
                WaitForSingleObject(automation_demo_command_event_, 0) == WAIT_OBJECT_0)
            {
                std::wstring module_path(MAX_PATH, L'\0');
                const auto module_path_length = GetModuleFileNameW(
                    module_instance_,
                    module_path.data(),
                    static_cast<DWORD>(module_path.size()));
                module_path.resize(module_path_length);
                const auto command_path =
                    std::filesystem::path(module_path).parent_path() /
                    L"nSkinzCS2.demo-command.txt";
                std::ifstream command_stream(command_path);
                std::string command_text;
                if (command_stream && std::getline(command_stream, command_text))
                {
                    if (!command_text.empty() && command_text.back() == '\r')
                    {
                        command_text.pop_back();
                    }
                    {
                        std::lock_guard<std::mutex> lock(g_hook_state.local_demo_command_mutex);
                        g_hook_state.local_demo_command = command_text;
                    }
                    g_hook_state.local_demo_command_requested.store(
                        true,
                        std::memory_order_release);
                    Logger::Info(
                        L"Queued local demo command for the next FRAME_RENDER_PASS: " +
                        NarrowToWide(command_text));
                }
                else
                {
                    Logger::Warn(
                        L"Local demo command event fired, but the sidecar could not be read: " +
                        command_path.wstring());
                }
            }

            auto status = BuildStatusSkeleton();
            status.process_path = CurrentProcessPath();
            status.process_detected = IsCs2Process(status.process_path);
            g_hook_state.demo_keychain_authoritative_xuid.store(0, std::memory_order_release);

            if (!status.process_detected)
            {
                status.availability = runtime::Availability::MissingProcess;
                status.last_error = L"Current process is not cs2.exe.";
                status.detail = L"nSkinzCS2 stays inactive unless loaded inside CS2.";
                state_.UpdateStatus(status);
                std::this_thread::sleep_for(std::chrono::milliseconds(250));
                continue;
            }

            status.hlae_detected = IsHlaeLoaded();
            if (!status.hlae_detected)
            {
                status.availability = runtime::Availability::MissingHlae;
                status.last_error = L"HLAE Source 2 hook module was not detected.";
                status.detail = L"Expected AfxHookSource2.dll to be present after mirv_loadlibrary.";
                state_.UpdateStatus(status);
                std::this_thread::sleep_for(std::chrono::milliseconds(250));
                continue;
            }

            ConsumeDemoKeychainRefresh(status);
            ConsumeManualRefresh(status);
            if (!hook_installed_.load() && !hook_activation_requested_.load())
            {
                status.availability = runtime::Availability::MissingHook;
                status.last_error.clear();
                status.detail = L"Safe startup mode: runtime hook is idle until you press Update in the nSkinzCS2 window.";
                status.diagnostics.push_back(
                    BuildKnifeModelAndFinishRuntimePathText() +
                    L" | " +
                    BuildResourceHandleQueryRuntimeText() +
                    L".");
                status.diagnostics.push_back(BuildGlobalResourceSwapperRuntimeText(false) + L".");
                status.diagnostics.push_back(L"Automatic Source2Client hook attach is disabled for stability.");
                status.diagnostics.push_back(L"Press Update after the demo is loaded if you want to attach the runtime.");
                LogStatusIfChanged(status);
                state_.UpdateStatus(status);
                std::this_thread::sleep_for(std::chrono::milliseconds(250));
                continue;
            }

            const auto bindings = TryResolveBindings(status);
            const bool all_interfaces_resolved = !bindings.AnyMissing();
            const bool query_runtime_viable =
                bindings.resource_system.address != nullptr &&
                bindings.engine_to_client.address != nullptr &&
                (hook_installed_.load() || bindings.source2_client.address != nullptr);
            const bool degraded_query_runtime = !all_interfaces_resolved && query_runtime_viable;
            status.interfaces_resolved = all_interfaces_resolved || query_runtime_viable;
            if (!status.interfaces_resolved)
            {
                status.availability = runtime::Availability::MissingInterfaces;
                LogStatusIfChanged(status);
                state_.UpdateStatus(status);
                std::this_thread::sleep_for(std::chrono::milliseconds(250));
                continue;
            }

            if (degraded_query_runtime)
            {
                if (status.last_error == L"One or more Source 2 interfaces could not be resolved via CreateInterface.")
                {
                    status.last_error.clear();
                }
                status.diagnostics.push_back(
                    L"Degraded Query runtime mode: continuing with ResourceSystem plus cached frame-stage/runtime state while non-critical interfaces remain unresolved.");
            }

            g_hook_state.resource_system_interface = bindings.resource_system.address;
            g_hook_state.resource_handle_utils_interface = bindings.resource_handle_utils.address;
            SyncResourceHandleQueryBindings();

            if (carrier_probe_requested_.exchange(false))
            {
                TryRunManualCarrierOnlyProbe(bindings, status);
            }

            if (TryInstallRuntimeHook(status))
            {
                hook_activation_requested_.store(false);
                status.hook_installed = true;
                if (!degraded_query_runtime)
                {
                    status.diagnostics.push_back(
                        L"CEconWearable factory discovery uses two matching FRAME_RENDER_PASS observations of the formal CGameEntitySystem CreateEntityByName/class-lookup chain, cross-checked against the unique Schema reflection identity. Runtime-created wearables additionally require the verified CEconWearable definition-refresh thunk before model initialization; background factory scans remain disabled.");
                }
                else
                {
                    status.diagnostics.push_back(
                        L"Degraded Query runtime mode paused non-essential wearable/factory refresh helpers.");
                }
                AppendHookTelemetry(status);
                AdvanceKnifeModelPathSwapQueryMainChain(
                    status.demo_playing,
                    status.frame_callbacks_active,
                    status);
                FlushResourceHandleQueryLiveProbeTelemetry();
                if (status.demo_guard_passed && status.schema_bound && status.entity_system_bound)
                {
                    status.availability = runtime::Availability::Ready;
                }
                else
                {
                    status.availability = runtime::Availability::HookedPendingDemoGuard;
                }
            }
            else
            {
                status.hook_installed = false;
                status.availability = runtime::Availability::MissingHook;
                if (hook_activation_requested_.exchange(false))
                {
                    hook_attempted_.store(false);
                    status.diagnostics.push_back(L"Hook attach attempt failed and was disarmed. Press Update to retry.");
                }
            }

            LogStatusIfChanged(status);
            state_.UpdateStatus(status);
            std::this_thread::sleep_for(std::chrono::milliseconds(250));
        }

        Logger::FlushDeferred();
        FlushRuntimePerformanceTelemetry();
        Logger::Info(L"Runtime worker stopped.");
    }
    catch (const std::exception& exception)
    {
        (void)exception;
        ReportWorkerThreadFailure(L"Runtime worker raised a C++ exception and was disabled.");
    }
    catch (...)
    {
        ReportWorkerThreadFailure(L"Runtime worker raised an unknown C++ exception and was disabled.");
    }
}

void nskinzcs2::RuntimeController::ReportWorkerThreadFailure(const wchar_t* message)
{
    Logger::Error(message);

    RunRuntimeCleanupSequence(L"Runtime fault cleanup", true, true);
    hook_installed_.store(false);
    global_swapper_early_attempted_.store(false);
    global_swapper_early_reason_.clear();
    global_swapper_early_route_.clear();
    hook_attempted_.store(false);
    hook_activation_requested_.store(false);

    runtime::Status status;
    status.availability = runtime::Availability::MissingHook;
    status.process_detected = true;
    status.hlae_detected = IsHlaeLoaded();
    status.last_error = message;
    status.detail = L"nSkinzCS2 disabled its runtime worker after a fatal thread fault to keep CS2 alive.";
    status.diagnostics.push_back(L"All installed runtime hooks were removed after the worker fault.");
    state_.UpdateStatus(std::move(status));
}

void nskinzcs2::RuntimeController::TryInstallGlobalResourceSwapperEarly()
{
    if (global_swapper_early_attempted_.exchange(true))
    {
        return;
    }

    global_swapper_early_reason_ = L"forensic_disabled";
    global_swapper_early_route_ = L"off";
}

nskinzcs2::RuntimeController::Bindings nskinzcs2::RuntimeController::TryResolveBindings(runtime::Status& status)
{
    Bindings bindings;

    auto add_module_interfaces =
        [&bindings, &status](const wchar_t* module_name)
        {
            ModuleInterfaces module_interfaces;
            module_interfaces.module_name = module_name;
            module_interfaces.names = EnumerateInterfaceNames(module_name);

            if (!module_interfaces.names.empty())
            {
                status.interface_registry_enumerated = true;
                std::wstringstream line;
                line << module_name << L": " << JoinInterfaceSummary(module_interfaces.names, 8);
                status.diagnostics.push_back(line.str());
            }

            bindings.interface_dump.push_back(std::move(module_interfaces));
        };

    add_module_interfaces(L"client.dll");
    add_module_interfaces(L"engine2.dll");
    add_module_interfaces(L"inputsystem.dll");
    add_module_interfaces(L"schemasystem.dll");
    add_module_interfaces(L"localize.dll");
    add_module_interfaces(L"scenesystem.dll");
    add_module_interfaces(L"resourcesystem.dll");
    add_module_interfaces(L"filesystem_stdio.dll");

    const auto& client_interfaces = bindings.interface_dump[0].names;
    const auto& engine_interfaces = bindings.interface_dump[1].names;
    const auto& input_interfaces = bindings.interface_dump[2].names;
    const auto& schema_interfaces = bindings.interface_dump[3].names;
    const auto& localize_interfaces = bindings.interface_dump[4].names;
    const auto& scene_interfaces = bindings.interface_dump[5].names;
    const auto& resource_interfaces = bindings.interface_dump[6].names;
    const auto& filesystem_interfaces = bindings.interface_dump[7].names;

    auto source2_client_versions = FilterVersionCandidates(client_interfaces, "Source2Client", 1, 64);
    if (source2_client_versions.empty())
    {
        source2_client_versions = BuildVersionCandidates(
            "Source2Client", 1, 64, {nskinzcs2::compatibility::kSource2ClientInterface});
    }

    auto engine_versions = FilterVersionCandidates(engine_interfaces, "Source2EngineToClient", 1, 32);
    if (engine_versions.empty())
    {
        engine_versions = BuildVersionCandidates("Source2EngineToClient", 1, 32);
    }

    auto input_versions = FilterVersionCandidates(input_interfaces, "InputSystemVersion", 1, 16);
    if (input_versions.empty())
    {
        input_versions = BuildVersionCandidates("InputSystemVersion", 1, 16);
    }

    auto schema_versions = FilterVersionCandidates(schema_interfaces, "SchemaSystem_", 1, 16);
    if (schema_versions.empty())
    {
        schema_versions = BuildVersionCandidates("SchemaSystem_", 1, 16);
    }

    auto localize_versions = FilterVersionCandidates(localize_interfaces, "Localize_", 1, 16);
    if (localize_versions.empty())
    {
        localize_versions = BuildVersionCandidates("Localize_", 1, 16);
    }

    auto engine_cvar_versions = FilterVersionCandidates(engine_interfaces, "VEngineCvar", 1, 16);
    if (engine_cvar_versions.empty())
    {
        engine_cvar_versions = BuildVersionCandidates("VEngineCvar", 1, 16, {"VEngineCvar007"});
    }

    auto game_ui_service_versions = FilterVersionCandidates(engine_interfaces, "GameUIService_", 1, 16);
    if (game_ui_service_versions.empty())
    {
        game_ui_service_versions = BuildVersionCandidates("GameUIService_", 1, 16, {"GameUIService_001"});
    }

    auto scene_system_versions = FilterVersionCandidates(scene_interfaces, "SceneSystem_", 1, 16);
    if (scene_system_versions.empty())
    {
        scene_system_versions = BuildVersionCandidates("SceneSystem_", 1, 16, {"SceneSystem_002"});
    }

    auto resource_system_versions = FilterVersionCandidates(resource_interfaces, "ResourceSystem", 1, 64);
    if (resource_system_versions.empty())
    {
        resource_system_versions = BuildVersionCandidates(
            "ResourceSystem", 1, 64, {nskinzcs2::compatibility::kResourceSystemInterface});
    }

    auto resource_handle_utils_versions = FilterVersionCandidates(resource_interfaces, "ResourceHandleUtils", 1, 64);
    if (resource_handle_utils_versions.empty())
    {
        resource_handle_utils_versions =
            BuildVersionCandidates("ResourceHandleUtils", 1, 64, {"ResourceHandleUtils001"});
        const auto underscored_resource_handle_utils_versions =
            BuildVersionCandidates("ResourceHandleUtils_", 1, 64, {"ResourceHandleUtils_001"});
        for (const auto& version : underscored_resource_handle_utils_versions)
        {
            if (std::find(
                    resource_handle_utils_versions.begin(),
                    resource_handle_utils_versions.end(),
                    version) == resource_handle_utils_versions.end())
            {
                resource_handle_utils_versions.push_back(version);
            }
        }
    }

    auto file_system_versions = FilterVersionCandidates(filesystem_interfaces, "VFileSystem", 1, 64);
    if (file_system_versions.empty())
    {
        file_system_versions = BuildVersionCandidates(
            "VFileSystem", 1, 64, {nskinzcs2::compatibility::kFileSystemInterface});
    }

    LogFileSystemInterfaceCandidatesFromFactory(
        L"Update/CreateInterface",
        ResolveModuleCreateInterfaceFactory(L"filesystem_stdio.dll"),
        file_system_versions);
    if (g_hook_state.connect_app_system_factory != nullptr)
    {
        LogFileSystemInterfaceCandidatesFromFactory(
            L"Update/ConnectFactory",
            g_hook_state.connect_app_system_factory,
            file_system_versions);
    }

    bindings.source2_client.module_name = L"client.dll";
    bindings.source2_client.address = ResolveCreateInterface(
        bindings.source2_client.module_name.c_str(),
        source2_client_versions,
        bindings.source2_client.version);

    bindings.engine_to_client.module_name = L"engine2.dll";
    bindings.engine_to_client.address = ResolveCreateInterface(
        bindings.engine_to_client.module_name.c_str(),
        engine_versions,
        bindings.engine_to_client.version);

    bindings.engine_cvar.module_name = L"tier0.dll";
    bindings.engine_cvar.address = ResolveCreateInterface(
        bindings.engine_cvar.module_name.c_str(),
        engine_cvar_versions,
        bindings.engine_cvar.version);
    if (bindings.engine_cvar.address == nullptr)
    {
        // Current CS2 builds publish VEngineCvar007 from tier0.dll. Keep the
        // historical engine2.dll route as a compatibility fallback for older
        // builds and forks which still expose the interface there.
        bindings.engine_cvar.module_name = L"engine2.dll";
        bindings.engine_cvar.address = ResolveCreateInterface(
            bindings.engine_cvar.module_name.c_str(),
            engine_cvar_versions,
            bindings.engine_cvar.version);
    }

    bindings.game_ui_service.module_name = L"engine2.dll";
    bindings.game_ui_service.address = ResolveCreateInterface(
        bindings.game_ui_service.module_name.c_str(),
        game_ui_service_versions,
        bindings.game_ui_service.version);

    bindings.scene_system.module_name = L"scenesystem.dll";
    bindings.scene_system.address = ResolveCreateInterface(
        bindings.scene_system.module_name.c_str(),
        scene_system_versions,
        bindings.scene_system.version);

    bindings.resource_system.module_name = L"resourcesystem.dll";
    bindings.resource_system.address = ResolveCreateInterface(
        bindings.resource_system.module_name.c_str(),
        resource_system_versions,
        bindings.resource_system.version);

    bindings.resource_handle_utils.module_name = L"resourcesystem.dll";
    bindings.resource_handle_utils.address = ResolveCreateInterface(
        bindings.resource_handle_utils.module_name.c_str(),
        resource_handle_utils_versions,
        bindings.resource_handle_utils.version);
    {
        std::wstringstream issue_stream;
        if (bindings.resource_handle_utils.address != nullptr)
        {
            issue_stream << L"ResourceHandleUtils resolved: version="
                << ToWide(bindings.resource_handle_utils.version)
                << L", address=" << FormatPointer(bindings.resource_handle_utils.address);
        }
        else
        {
            issue_stream << L"ResourceHandleUtils unresolved in resourcesystem.dll: candidates="
                << JoinInterfaceSummary(resource_handle_utils_versions, 10);
            if (!resource_interfaces.empty())
            {
                issue_stream << L", discovered="
                    << JoinInterfaceSummary(resource_interfaces, 10);
            }
        }

        static std::wstring s_last_resource_handle_utils_issue;
        const auto issue = issue_stream.str();
        if (s_last_resource_handle_utils_issue != issue)
        {
            s_last_resource_handle_utils_issue = issue;
            status.diagnostics.push_back(issue);
            nskinzcs2::Logger::Info(issue);
        }
    }

    bindings.file_system.module_name = L"filesystem_stdio.dll";
    bindings.file_system.address = ResolveCreateInterface(
        bindings.file_system.module_name.c_str(),
        file_system_versions,
        bindings.file_system.version);
    if (bindings.file_system.address != nullptr)
    {
        LogFileSystemInterfaceCandidateIdentity(
            L"Update/Selected",
            {bindings.file_system.version},
            bindings.file_system.address);
    }

    bindings.input_system.module_name = L"inputsystem.dll";
    bindings.input_system.address = ResolveCreateInterface(
        bindings.input_system.module_name.c_str(),
        input_versions,
        bindings.input_system.version);

    bindings.schema_system.module_name = L"schemasystem.dll";
    bindings.schema_system.address = ResolveCreateInterface(
        bindings.schema_system.module_name.c_str(),
        schema_versions,
        bindings.schema_system.version);

    bindings.localize.module_name = L"localize.dll";
    bindings.localize.address = ResolveCreateInterface(
        bindings.localize.module_name.c_str(),
        localize_versions,
        bindings.localize.version);

    std::wstringstream detail;
    detail << L"Interfaces:"
        << L" client=" << (bindings.source2_client.address ? ToWide(bindings.source2_client.version) : L"missing")
        << L", engine=" << (bindings.engine_to_client.address ? ToWide(bindings.engine_to_client.version) : L"missing")
        << L", cvar=" << (bindings.engine_cvar.address ? ToWide(bindings.engine_cvar.version) : L"missing")
        << L", gameui=" << (bindings.game_ui_service.address ? ToWide(bindings.game_ui_service.version) : L"missing")
        << L", scene=" << (bindings.scene_system.address ? ToWide(bindings.scene_system.version) : L"missing")
        << L", resource=" << (bindings.resource_system.address ? ToWide(bindings.resource_system.version) : L"missing")
        << L", resource_utils=" << (bindings.resource_handle_utils.address ? ToWide(bindings.resource_handle_utils.version) : L"missing")
        << L", fs=" << (bindings.file_system.address ? ToWide(bindings.file_system.version) : L"missing")
        << L", input=" << (bindings.input_system.address ? ToWide(bindings.input_system.version) : L"missing")
        << L", schema=" << (bindings.schema_system.address ? ToWide(bindings.schema_system.version) : L"missing")
        << L", localize=" << (bindings.localize.address ? ToWide(bindings.localize.version) : L"missing");
    status.detail = detail.str();

    if (bindings.AnyMissing())
    {
        status.last_error = L"One or more Source 2 interfaces could not be resolved via CreateInterface.";
    }

    if (status.interface_registry_enumerated)
    {
        status.diagnostics.push_back(L"Runtime interface names were discovered from CreateInterface registration lists.");
    }
    else
    {
        status.diagnostics.push_back(L"Interface registry enumeration failed; runtime is using generated version candidates.");
    }

    return bindings;
}

bool nskinzcs2::RuntimeController::TryInstallRuntimeHook(runtime::Status& status)
{
    if (hook_installed_.load())
    {
        status.detail = L"Source2Client vtable hooks are already installed.";
        return true;
    }

    if (!hook_attempted_.exchange(true))
    {
        Logger::Info(
            L"Installing Source2Client002 FrameStageNotify hook for HLAE 2.191.1 using validated vtable index " +
            std::to_wstring(nskinzcs2::compatibility::kFrameStageNotifyVtableIndex) + L".");
    }

    const auto bindings = TryResolveBindings(status);
    if (bindings.source2_client.address == nullptr)
    {
        status.last_error = L"Source2Client interface became unavailable before hook install.";
        return false;
    }

    void* validated_frame_stage_target = nullptr;
    std::wstring validation_issue;
    if (!TryGetValidatedInterfaceVtableEntry(
            bindings.source2_client.address,
            nskinzcs2::compatibility::kFrameStageNotifyVtableIndex,
            GetModuleHandleW(L"client.dll"),
            validated_frame_stage_target,
            validation_issue))
    {
        status.last_error = L"FrameStageNotify target validation failed before hook install.";
        status.detail = L"Source2Client was resolved, but vtable[36] did not validate as a safe client.dll code pointer.";
        if (!validation_issue.empty())
        {
            status.diagnostics.push_back(validation_issue);
        }
        return false;
    }

    if (!validation_issue.empty())
    {
        status.diagnostics.push_back(validation_issue);
    }

    status.diagnostics.push_back(
        L"Validated Source2Client::FrameStageNotify target at " + FormatPointer(validated_frame_stage_target) + L".");

    if (g_hook_state.engine_to_client == nullptr)
    {
        g_hook_state.engine_to_client = bindings.engine_to_client.address;
    }
    if (g_hook_state.engine_cvar == nullptr)
    {
        g_hook_state.engine_cvar = bindings.engine_cvar.address;
    }

    const auto previous_source2_client_interface = g_hook_state.source2_client_interface.load();
    if (previous_source2_client_interface == nullptr)
    {
        g_hook_state.source2_client_interface.store(bindings.source2_client.address);
        InvalidateCachedWearableFactoryResolutionForProviderChange();
    }
    else if (previous_source2_client_interface != bindings.source2_client.address)
    {
        g_hook_state.source2_client_interface.store(bindings.source2_client.address);
        InvalidateCachedWearableFactoryResolutionForProviderChange();
    }

    if (g_hook_state.game_ui_service == nullptr)
    {
        g_hook_state.game_ui_service = bindings.game_ui_service.address;
    }

    if (g_hook_state.schema_system_interface == nullptr)
    {
        g_hook_state.schema_system_interface = bindings.schema_system.address;
    }

    status.diagnostics.push_back(BuildGlobalResourceSwapperRuntimeText(false) + L".");

    if (!g_hook_state.frame_stage_hook_installed.load())
    {
        if (g_hook_state.frame_stage_patch.Install(
                bindings.source2_client.address,
                nskinzcs2::compatibility::kFrameStageNotifyVtableIndex,
                reinterpret_cast<void*>(&HookedClientFrameStageNotify)))
        {
            g_hook_state.original_frame_stage_notify =
                reinterpret_cast<HookState::ClientFrameStageNotifyFn>(g_hook_state.frame_stage_patch.original);
            g_hook_state.frame_stage_hook_installed.store(true);
            hook_installed_.store(true);
            status.diagnostics.push_back(
                L"Hooked Source2Client::FrameStageNotify via vtable[36] at " + FormatPointer(g_hook_state.frame_stage_patch.original) + L".");
        }
    }

    if (!g_hook_state.frame_stage_hook_installed.load())
    {
        status.last_error = L"Failed to patch Source2Client vtable[36] for FrameStageNotify.";
        status.detail = L"Source2Client was resolved, but the frame-stage hook could not be installed.";
        return false;
    }

    status.last_error.clear();
    status.detail = L"Source2Client frame hook is active. Connect hook stays disabled for stability.";
    return true;
}

bool nskinzcs2::RuntimeController::TryRunManualCarrierOnlyProbe(
    const Bindings& bindings,
    runtime::Status& status)
{
    status.diagnostics.push_back(L"Carrier-only diagnostic probe is running without applying cosmetic writes.");

    if (bindings.engine_to_client.address != nullptr && g_hook_state.engine_to_client == nullptr)
    {
        g_hook_state.engine_to_client = bindings.engine_to_client.address;
    }
    if (bindings.engine_cvar.address != nullptr && g_hook_state.engine_cvar == nullptr)
    {
        g_hook_state.engine_cvar = bindings.engine_cvar.address;
    }
    if (bindings.game_ui_service.address != nullptr && g_hook_state.game_ui_service == nullptr)
    {
        g_hook_state.game_ui_service = bindings.game_ui_service.address;
    }
    if (bindings.schema_system.address != nullptr && g_hook_state.schema_system_interface == nullptr)
    {
        g_hook_state.schema_system_interface = bindings.schema_system.address;
    }

    if (!g_hook_state.schema_ready.load())
    {
        ClientSchemaOffsets offsets;
        if (TryResolveSchemaOffsets(GetModuleHandleW(L"schemasystem.dll"), g_hook_state.schema_system_interface, offsets))
        {
            g_hook_state.schema_offsets = offsets;
            g_hook_state.schema_ready.store(true);
            if (!g_hook_state.schema_logged.exchange(true))
            {
                std::wstringstream stream;
                stream << L"Bound client.dll schema offsets through Source 2 schema reflection"
                    << L": m_hMyWearables=0x" << std::hex << std::uppercase
                    << static_cast<std::uint64_t>(offsets.combat_character_my_wearables)
                    << L", vector_operation="
                    << FormatPointer(reinterpret_cast<void*>(offsets.combat_character_my_wearables_operation))
                    << std::dec << std::nouppercase
                    << L", element_size=" << offsets.combat_character_my_wearables_element_size
                    << L", storage_size=" << offsets.combat_character_my_wearables_storage_size
                    << L", append_ready="
                    << (offsets.combat_character_my_wearables_operation != nullptr &&
                        offsets.combat_character_my_wearables_element_size == sizeof(std::uint32_t) &&
                        offsets.combat_character_my_wearables_storage_size == 0x18 ? 1 : 0)
                    << L".";
                nskinzcs2::Logger::Info(stream.str());
            }
        }
    }

    if (!g_hook_state.entity_system_ready.load())
    {
        EntitySystemBindings entity_system_bindings;
        if (TryResolveEntitySystemBindings(GetModuleHandleW(L"client.dll"), entity_system_bindings))
        {
            g_hook_state.entity_system = entity_system_bindings;
            g_hook_state.entity_system_ready.store(true);
            if (!g_hook_state.entity_system_logged.exchange(true))
            {
                nskinzcs2::Logger::Info(
                    L"Bound client entity system at " + FormatPointer(entity_system_bindings.entity_list_storage) +
                    L" with GetEntityFromIndex=" +
                    FormatPointer(reinterpret_cast<void*>(entity_system_bindings.get_entity_from_index)) + L".");
            }
        }
    }

    if (!g_hook_state.schema_ready.load() || !g_hook_state.entity_system_ready.load())
    {
        status.diagnostics.push_back(L"Carrier-only diagnostic probe skipped: schema/entity bindings are not ready.");
        return false;
    }

    bool demo_playing = false;
    bool demo_paused = false;
    int demo_tick = -1;
    std::wstring level_name;
    std::wstring issue;
    if (!TryResolveEngineState(demo_playing, demo_paused, demo_tick, level_name, issue))
    {
        status.diagnostics.push_back(
            L"Carrier-only diagnostic probe skipped: " +
            (!issue.empty() ? issue : L"engine state could not be resolved."));
        return false;
    }

    if (!demo_playing)
    {
        status.diagnostics.push_back(L"Carrier-only diagnostic probe skipped: demo playback is not active.");
        return false;
    }

    void* entity_list = nullptr;
    if (g_hook_state.entity_system.entity_list_storage == nullptr ||
        !SafeReadValue(g_hook_state.entity_system.entity_list_storage, entity_list) ||
        entity_list == nullptr)
    {
        status.diagnostics.push_back(
            L"Carrier-only diagnostic probe skipped: client entity system storage resolved, but the live entity list is null.");
        return false;
    }

    const auto config = state_.SnapshotConfig();
    const auto catalog = state_.SnapshotCatalog();
    std::unordered_set<std::uint64_t> target_xuids;
    std::unordered_map<std::uint32_t, std::uint64_t> target_xuids_by_account;
    for (const auto& profile : config.profiles)
    {
        if (!profile.enabled || profile.xuid == 0 || profile.base_item == 5028)
        {
            continue;
        }

        target_xuids.insert(profile.xuid);
        target_xuids_by_account[AccountIdFromXuid(profile.xuid)] = profile.xuid;
    }
    for (const auto& profile : config.knife_profiles)
    {
        if (!profile.enabled || profile.xuid == 0)
        {
            continue;
        }

        target_xuids.insert(profile.xuid);
        target_xuids_by_account[AccountIdFromXuid(profile.xuid)] = profile.xuid;
    }
    for (const auto& profile : config.glove_profiles)
    {
        if (!profile.enabled || profile.xuid == 0)
        {
            continue;
        }

        target_xuids.insert(profile.xuid);
        target_xuids_by_account[AccountIdFromXuid(profile.xuid)] = profile.xuid;
    }

    if (target_xuids.empty())
    {
        status.diagnostics.push_back(L"Carrier-only diagnostic probe skipped: no enabled XUID-targeted profiles are active.");
        return false;
    }

    std::unordered_set<int> knife_definition_indices;
    std::unordered_set<int> glove_definition_indices;
    std::unordered_set<int> known_definition_indices;
    knife_definition_indices.reserve(catalog.knife_items.size());
    glove_definition_indices.reserve(catalog.glove_items.size());
    known_definition_indices.reserve(
        catalog.base_items.size() +
        catalog.knife_items.size() +
        catalog.glove_items.size());

    for (const auto& item : catalog.base_items)
    {
        if (item.id > 0)
        {
            known_definition_indices.insert(item.id);
        }
    }
    for (const auto& item : catalog.knife_items)
    {
        if (item.id > 0)
        {
            knife_definition_indices.insert(item.id);
            known_definition_indices.insert(item.id);
        }
    }
    for (const auto& item : catalog.glove_items)
    {
        if (item.id > 0)
        {
            glove_definition_indices.insert(item.id);
            known_definition_indices.insert(item.id);
        }
    }

    std::wstring ceiling_issue;
    const auto highest_live_entity_index = ResolveDynamicEntityScanUpperBound(entity_list, ceiling_issue);
    if (highest_live_entity_index < 0)
    {
        status.diagnostics.push_back(
            L"Carrier-only diagnostic probe skipped: " +
            (!ceiling_issue.empty() ? ceiling_issue : L"live entity ceiling scan failed."));
        return false;
    }

    g_hook_state.highest_live_entity_index.store(highest_live_entity_index);

    std::vector<void*> entity_cache(static_cast<std::size_t>(highest_live_entity_index + 1), nullptr);
    for (int entity_index = 0; entity_index <= highest_live_entity_index; ++entity_index)
    {
        void* entity = nullptr;
        if (!TryGetEntityFromIndex(entity_list, entity_index, entity))
        {
            status.diagnostics.push_back(
                L"Carrier-only diagnostic probe skipped: GetEntityFromIndex raised while populating the entity cache.");
            return false;
        }

        entity_cache[static_cast<std::size_t>(entity_index)] = entity;
    }

    std::unordered_map<int, std::uint64_t> pawn_xuids;
    std::unordered_map<int, std::uint32_t> pawn_handles;
    std::unordered_map<int, int> pawn_controller_indices;
    std::unordered_map<int, ObservedPawnRuntimeInfo> pawn_runtime;
    pawn_xuids.reserve(64);
    pawn_handles.reserve(64);
    pawn_controller_indices.reserve(64);
    pawn_runtime.reserve(64);

    for (int entity_index = 0; entity_index <= highest_live_entity_index; ++entity_index)
    {
        void* entity = entity_cache[static_cast<std::size_t>(entity_index)];
        if (entity == nullptr)
        {
            continue;
        }

        std::uint64_t xuid = 0;
        std::uint32_t pawn_handle = kInvalidEntityHandle;
        if (!SafeReadField(entity, g_hook_state.schema_offsets.controller_steam_id, xuid) ||
            !LooksLikeSteamXuid(xuid) ||
            !SafeReadField(entity, g_hook_state.schema_offsets.controller_pawn, pawn_handle) ||
            !IsPlausibleEntityHandle(pawn_handle))
        {
            continue;
        }

        const auto pawn_entity_index = HandleToEntityIndex(pawn_handle);
        if (pawn_entity_index < 0 || pawn_entity_index > highest_live_entity_index)
        {
            continue;
        }

        void* pawn_entity = entity_cache[static_cast<std::size_t>(pawn_entity_index)];
        if (pawn_entity == nullptr)
        {
            continue;
        }

        std::uint32_t controller_handle = kInvalidEntityHandle;
        if (SafeReadField(pawn_entity, g_hook_state.schema_offsets.pawn_controller, controller_handle) &&
            HandleToEntityIndex(controller_handle) != entity_index)
        {
            continue;
        }

        pawn_xuids[pawn_entity_index] = xuid;
        pawn_handles[pawn_entity_index] = pawn_handle;
        pawn_controller_indices[pawn_entity_index] = entity_index;
    }

    for (const auto& [pawn_entity_index, xuid] : pawn_xuids)
    {
        if (target_xuids.find(xuid) == target_xuids.end())
        {
            continue;
        }

        void* pawn_entity = entity_cache[static_cast<std::size_t>(pawn_entity_index)];
        if (pawn_entity == nullptr)
        {
            continue;
        }

        auto& pawn_info = pawn_runtime[pawn_entity_index];
        pawn_info.pawn_entity_index = pawn_entity_index;
        if (const auto controller_entity_index = pawn_controller_indices.find(pawn_entity_index);
            controller_entity_index != pawn_controller_indices.end())
        {
            pawn_info.controller_entity_index = controller_entity_index->second;
            pawn_info.controller_entity =
                entity_cache[static_cast<std::size_t>(controller_entity_index->second)];
        }
        pawn_info.entity = pawn_entity;
        pawn_info.xuid = xuid;
        if (const auto pawn_handle = pawn_handles.find(pawn_entity_index); pawn_handle != pawn_handles.end())
        {
            pawn_info.pawn_handle = pawn_handle->second;
        }
        PopulateObservedPawnRuntimeInfo(
            entity_list,
            entity_cache,
            g_hook_state.schema_offsets,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            pawn_info);
    }

    const auto preferred_knife_target_xuid = ResolvePreferredKnifeTargetXuid(config, pawn_xuids);
    const auto heuristic_watched_xuid = ResolveWatchedXuid(
        entity_list,
        pawn_xuids,
        target_xuids_by_account,
        entity_cache,
        knife_definition_indices,
        preferred_knife_target_xuid,
        g_hook_state.schema_offsets);
    const auto observer_resolution =
        ResolveObserverFirstWatchedTarget(
            entity_list,
            entity_cache,
            pawn_xuids,
            knife_definition_indices,
            glove_definition_indices,
            g_hook_state.schema_offsets);
    const auto observer_real_viewmodel_resolution =
        ResolveObserverFirstRealViewmodel(
            entity_list,
            entity_cache,
            observer_resolution,
            g_hook_state.schema_offsets);
    const auto bridge_resolution =
        ResolveHeuristicXuidBridge(
            entity_list,
            entity_cache,
            pawn_runtime,
            observer_resolution,
            heuristic_watched_xuid,
            g_hook_state.schema_offsets,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices);
    const auto bridge_real_viewmodel_resolution =
        ResolveHeuristicXuidBridgeRealViewmodel(
            entity_list,
            entity_cache,
            bridge_resolution,
            g_hook_state.schema_offsets);
    const auto watched_resolution =
        ResolveWatchedXuidFromObserverOrBridge(
            observer_resolution,
            bridge_resolution,
            heuristic_watched_xuid);
    const auto watched_xuid = watched_resolution.watched_xuid;
    g_hook_state.watched_xuid.store(watched_xuid);
    const auto emit_watched_knife_deep_trace =
        g_hook_state.runtime_trace_polls_remaining.load() > 0 ||
        g_hook_state.frame_stage_trace_callbacks_remaining.load() > 0;
    g_hook_state.runtime_trace_polls_remaining.store(
        kEnableAutomaticWatchedKnifeTracingOnUpdate
            ? std::max(1, g_hook_state.runtime_trace_polls_remaining.load())
            : 0);
    g_hook_state.frame_stage_trace_callbacks_remaining.store(
        kEnableAutomaticWatchedKnifeTracingOnUpdate ? 0 : 0);
    if (emit_watched_knife_deep_trace)
    {
        LogObserverFirstWatchedKnifeTrace(
            observer_resolution,
            observer_real_viewmodel_resolution,
            bridge_resolution,
            bridge_real_viewmodel_resolution,
            heuristic_watched_xuid,
            watched_resolution);
        LogControllerObserverRawScan(
            entity_list,
            entity_cache,
            g_hook_state.schema_offsets,
            observer_resolution,
            heuristic_watched_xuid,
            watched_resolution);
        LogObserverPawnRelayTrace(
            entity_list,
            entity_cache,
            pawn_xuids,
            g_hook_state.schema_offsets,
            observer_resolution,
            watched_resolution);
        LogBridgedPawnViewmodelDeepTrace(
            entity_list,
            entity_cache,
            pawn_xuids,
            pawn_runtime,
            g_hook_state.schema_offsets,
            bridge_resolution,
            bridge_real_viewmodel_resolution,
            watched_resolution);
    }

    if (watched_xuid == 0)
    {
        status.diagnostics.push_back(L"Carrier-only diagnostic probe skipped: no watched knife target resolved.");
        return false;
    }

    std::unordered_map<std::uint64_t, RuntimePlayerBinding> players_by_xuid;
    players_by_xuid.reserve(pawn_runtime.size());
    for (const auto& [pawn_entity_index, pawn_info] : pawn_runtime)
    {
        auto& binding = players_by_xuid[pawn_info.xuid];
        binding.xuid = pawn_info.xuid;
        binding.pawn_entity_index = pawn_entity_index;
        binding.pawn_entity = pawn_info.entity;
        binding.controller_entity_index = pawn_info.controller_entity_index;
        binding.controller_entity = pawn_info.controller_entity;
        binding.pawn_handle = pawn_info.pawn_handle;
        binding.active_weapon_handle = pawn_info.active_weapon_handle;
        binding.active_weapon_entity_index = pawn_info.active_weapon_entity_index;
        binding.active_weapon_definition_index = pawn_info.active_weapon_definition_index;
        binding.active_weapon_is_knife = pawn_info.active_weapon_is_knife;
        binding.health = pawn_info.health;
        binding.health_readable = pawn_info.health_readable;
        binding.pawn_alive = pawn_info.pawn_alive;
        binding.pawn_is_observer = pawn_info.pawn_is_observer;
        binding.pawn_class_name = pawn_info.pawn_class_name;

        binding.owned_weapon_entity_indices.clear();
        binding.owned_weapon_handles_by_entity_index.clear();
        binding.owned_weapon_entity_indices.reserve(pawn_info.owned_weapon_handles.size() + 1);
        binding.owned_weapon_handles_by_entity_index.reserve(pawn_info.owned_weapon_handles.size() + 1);
        for (const auto handle : pawn_info.owned_weapon_handles)
        {
            const auto entity_index = HandleToEntityIndex(handle);
            if (entity_index < 0 || entity_index > highest_live_entity_index)
            {
                continue;
            }

            auto* entity = entity_cache[static_cast<std::size_t>(entity_index)];
            if (entity == nullptr)
            {
                continue;
            }

            if (std::find(
                    binding.owned_weapon_entity_indices.begin(),
                    binding.owned_weapon_entity_indices.end(),
                    entity_index) == binding.owned_weapon_entity_indices.end())
            {
                binding.owned_weapon_entity_indices.push_back(entity_index);
            }
            binding.owned_weapon_handles_by_entity_index[entity_index] = handle;

            auto& weapon_binding = binding.weapons_by_entity_index[entity_index];
            weapon_binding.world_entity_index = entity_index;

            auto* weapon_item_view = ResolveWeaponItemView(entity, g_hook_state.schema_offsets);
            if (weapon_item_view != nullptr)
            {
                TryReadItemDefinitionIndex(
                    weapon_item_view,
                    g_hook_state.schema_offsets,
                    weapon_binding.world_definition_index);
            }

            std::uint32_t viewmodel_handle = kInvalidEntityHandle;
            if (g_hook_state.schema_offsets.econ_entity_viewmodel_attachment != 0 &&
                SafeReadField(entity, g_hook_state.schema_offsets.econ_entity_viewmodel_attachment, viewmodel_handle))
            {
                weapon_binding.viewmodel_entity_index = HandleToEntityIndex(viewmodel_handle);
            }

            std::uint32_t providee_handle = kInvalidEntityHandle;
            if (g_hook_state.schema_offsets.econ_entity_old_providee != 0 &&
                SafeReadField(entity, g_hook_state.schema_offsets.econ_entity_old_providee, providee_handle))
            {
                weapon_binding.providee_entity_index = HandleToEntityIndex(providee_handle);
            }
        }

        if (binding.active_weapon_entity_index >= 0 &&
            std::find(
                binding.owned_weapon_entity_indices.begin(),
                binding.owned_weapon_entity_indices.end(),
                binding.active_weapon_entity_index) == binding.owned_weapon_entity_indices.end())
        {
            binding.owned_weapon_entity_indices.push_back(binding.active_weapon_entity_index);
        }
        if (binding.active_weapon_entity_index >= 0 &&
            binding.active_weapon_handle != kInvalidEntityHandle)
        {
            binding.owned_weapon_handles_by_entity_index[binding.active_weapon_entity_index] =
                binding.active_weapon_handle;
        }
    }

    const auto watched_player = players_by_xuid.find(watched_xuid);
    if (watched_player == players_by_xuid.end())
    {
        status.diagnostics.push_back(L"Carrier-only diagnostic probe skipped: watched player binding was not built.");
        return false;
    }

    const auto& player_binding = watched_player->second;
    const auto watched_entity_index = player_binding.active_weapon_entity_index;
    if (watched_entity_index < 0 || watched_entity_index > highest_live_entity_index)
    {
        status.diagnostics.push_back(L"Carrier-only diagnostic probe skipped: watched active weapon handle is invalid.");
        return false;
    }

    void* watched_entity = entity_cache[static_cast<std::size_t>(watched_entity_index)];
    if (watched_entity == nullptr)
    {
        status.diagnostics.push_back(L"Carrier-only diagnostic probe skipped: watched active weapon entity is null.");
        return false;
    }

    void* watched_item_view = ResolveWeaponItemView(watched_entity, g_hook_state.schema_offsets);
    int watched_definition_index = 0;
    if (watched_item_view == nullptr ||
        !TryReadItemDefinitionIndex(watched_item_view, g_hook_state.schema_offsets, watched_definition_index) ||
        !IsKnownDefinitionIndex(watched_definition_index, known_definition_indices) ||
        NormalizeBaseItem(watched_definition_index, knife_definition_indices, glove_definition_indices) != 42)
    {
        status.diagnostics.push_back(L"Carrier-only diagnostic probe skipped: watched active weapon is not a knife.");
        return false;
    }

    std::wstringstream start_stream;
    start_stream << L"Running carrier-only watched knife diagnostic probe for XUID " << watched_xuid
        << L": world_entity=" << watched_entity_index
        << L", definition=" << watched_definition_index
        << L", highest_live_entity_index=" << highest_live_entity_index
        << L", demo_tick=" << demo_tick
        << L", level=" << level_name;
    nskinzcs2::Logger::Info(start_stream.str());

    const auto context =
        ResolveKnifeRuntimeContext(
            entity_list,
            entity_cache,
            player_binding,
            watched_entity_index,
            watched_entity,
            watched_item_view,
            g_hook_state.schema_offsets,
            watched_xuid,
            watched_xuid,
            watched_definition_index,
            known_definition_indices,
            knife_definition_indices,
            glove_definition_indices,
            demo_playing,
            g_hook_state.schema_ready.load(),
            g_hook_state.entity_system_ready.load(),
            &observer_resolution,
            &bridge_resolution);

    std::wstringstream summary_stream;
    summary_stream << L"Carrier-only watched knife diagnostic probe completed for XUID " << watched_xuid
        << L": world_entity=" << context.world_entity_index
        << L", owner_kind="
        << nskinzcs2::runtime::KnifeFirstPersonOwnerKindText(context.first_person_owner_kind)
        << L", direct_render_entity=" << context.direct_first_person_render_entity_index
        << L", direct_render_valid=" << (context.direct_first_person_render_valid ? 1 : 0)
        << L", direct_render_only=" << (context.direct_first_person_render_only ? 1 : 0)
        << L", first_person_source_valid=" << (context.first_person_source_valid ? 1 : 0);
    nskinzcs2::Logger::Info(summary_stream.str());

    status.watched_xuid = watched_xuid;
    status.highest_entity_index = highest_live_entity_index;
    status.demo_playing = demo_playing;
    status.demo_paused = demo_paused;
    status.demo_tick = demo_tick;
    status.level_name = level_name;
    status.diagnostics.push_back(L"Carrier-only diagnostic probe completed; inspect the watched knife log lines for carrier resolution.");
    return true;
}

void nskinzcs2::RuntimeController::ConsumeDemoKeychainRefresh(runtime::Status& status)
{
    if (!state_.ConsumeDemoKeychainRefreshRequest())
    {
        return;
    }

    if (!hook_installed_.load())
    {
        hook_activation_requested_.store(true);
        carrier_probe_requested_.store(false);
        g_hook_state.manual_refresh_requested.store(true);
        g_hook_state.resource_handle_query_earliest_safe_tick.store(GetTickCount64() + 1500);
        status.last_error.clear();
        status.diagnostics.push_back(
            L"Demo keychain refresh requested before the runtime hook was attached, so a one-shot manual refresh was armed instead.");
        Logger::Info(
            L"Demo keychain refresh requested before the runtime hook was attached; escalating to a one-shot manual refresh.");
        return;
    }

    g_hook_state.next_runtime_poll_millis.store(0, std::memory_order_release);
    status.diagnostics.push_back(
        L"Demo keychain refresh requested. The next runtime poll will rescan the current demo weapon without a full rebuild.");
    Logger::Info(
        L"Demo keychain refresh requested. The next runtime poll will rescan the current demo weapon without a full rebuild.");
}

void nskinzcs2::RuntimeController::ConsumeManualRefresh(runtime::Status& status)
{
    if (!state_.ConsumeManualRefreshRequest())
    {
        return;
    }

    if (!hook_installed_.load())
    {
        hook_activation_requested_.store(true);
        carrier_probe_requested_.store(false);
        g_hook_state.manual_refresh_requested.store(true);
        g_hook_state.resource_handle_query_earliest_safe_tick.store(GetTickCount64() + 1500);
        status.last_error.clear();
        status.diagnostics.push_back(
            L"Manual refresh requested. Runtime hook attach is armed and one refresh pass will run after the hook comes online.");
        Logger::Info(
            L"Manual refresh requested. Runtime hook attach is armed and one refresh pass will run after the hook comes online.");
        return;
    }

    if (hook_installed_.load())
    {
        carrier_probe_requested_.store(false);
        g_hook_state.manual_refresh_requested.store(true);
        g_hook_state.resource_handle_query_earliest_safe_tick.store(GetTickCount64() + 1500);
        Logger::Info(L"Manual refresh requested. The next render-pass callback will rescan demo and entity runtime state.");
        return;
    }

    if (!logged_unavailable_refresh_.exchange(true))
    {
        Logger::Warn(L"Manual refresh requested while runtime hook is unavailable.");
    }

    status.last_error = L"Update requested, but runtime mutation hook is unavailable for this build.";
    status.diagnostics.push_back(L"Manual refresh was requested before the frame/update hook became available.");
}

void nskinzcs2::RuntimeController::AppendHookTelemetry(runtime::Status& status) const
{
    const auto knife_refresh_policy = g_hook_state.knife_refresh_helper_policy.load();
    const auto knife_refresh_epoch_armed = KnifeRefreshHelperEpochArmed();
    const auto demo_keychain_state = SnapshotDemoKeychainControllerState();
    status.hook_installed = g_hook_state.frame_stage_hook_installed.load();
    status.frame_callbacks_active = g_hook_state.frame_seen.load();
    status.frame_callback_count = g_hook_state.frame_callback_count.load();
    status.last_frame_stage = g_hook_state.last_frame_stage.load();
    status.demo_playing = g_hook_state.demo_playing.load();
    status.demo_paused = g_hook_state.demo_paused.load();
    status.demo_tick = g_hook_state.demo_tick.load();
    status.schema_bound = g_hook_state.schema_ready.load();
    status.entity_system_bound = g_hook_state.entity_system_ready.load();
    status.client_entity_factory_requested = g_hook_state.client_entity_factory_requested.load();
    status.client_entity_factory_resolved = g_hook_state.client_entity_factory_ready.load();
    status.viewmodel_factory_discovery_ran = g_hook_state.viewmodel_factory_discovery_ran.load();
    status.viewmodel_factory_observed = g_hook_state.viewmodel_factory_observed.load();
    status.knife_animation_hook_resolved = g_hook_state.knife_animation_hook_ready.load();
    status.knife_model_override_ready = g_hook_state.knife_model_override_ready.load();
    status.stable_wearable_bound = g_hook_state.stable_wearable_bound.load();
    status.runtime_created_wearable_bound = g_hook_state.runtime_created_wearable_bound.load();
    status.glove_pawn_fallback_bound = g_hook_state.glove_pawn_fallback_bound.load();
    status.knife_viewmodel_sync_ready = g_hook_state.knife_viewmodel_sync_ready.load();
    status.runtime_rebuilding = g_hook_state.runtime_rebuilding.load();
    status.watched_xuid = g_hook_state.watched_xuid.load();
    status.probed_xuid = 0;
    status.demo_keychain_authoritative_xuid = 0;
    status.demo_keychain_state = demo_keychain_state.state;
    status.demo_keychain_create_disabled = demo_keychain_state.session_create_disabled;
    status.demo_keychain_owner_xuid = demo_keychain_state.owner_xuid;
    status.demo_console_capture_ready = false;
    status.demo_console_query_inflight = false;
    status.demo_keychain_weapon_entity_index = demo_keychain_state.weapon_entity_index;
    status.demo_keychain_base_item = demo_keychain_state.base_item;
    status.demo_keychain_module_entity_index = demo_keychain_state.keychain_module_entity_index;
    status.demo_keychain_live_def_id = static_cast<int>(demo_keychain_state.live_keychain_kit);
    status.demo_keychain_stable_frame_count = static_cast<int>(demo_keychain_state.stable_frame_count);
    status.demo_console_player_count = 0;
    status.highest_entity_index = g_hook_state.highest_live_entity_index.load();
    status.player_controller_count = g_hook_state.player_controller_count.load();
    status.player_pawn_count = g_hook_state.player_pawn_count.load();
    status.preview_character_count = g_hook_state.preview_character_count.load();
    status.active_weapon_count = g_hook_state.active_weapon_count.load();
    status.owned_weapon_count = g_hook_state.owned_weapon_count.load();
    status.enabled_profile_count = g_hook_state.enabled_profile_count.load();
    status.matched_profile_count = g_hook_state.matched_profile_count.load();
    status.applied_weapon_count = g_hook_state.applied_weapon_count.load();
    status.applied_glove_count = g_hook_state.applied_glove_count.load();
    status.skipped_knife_override_count = g_hook_state.skipped_knife_override_count.load();
    status.knife_runtime_path = SnapshotKnifeRuntimePathText();
    status.knife_runtime_reason = SnapshotKnifeRuntimeReasonText();
    status.weapon_skin_refresh_state = g_hook_state.weapon_skin_refresh_state.load();
    status.level_name = SnapshotLevelName();
    status.rebuild_reason = g_hook_state.last_rebuild_reason;
    status.demo_keychain_profile_name = NarrowToWide(demo_keychain_state.matched_profile_name);
    status.demo_keychain_issue = demo_keychain_state.last_issue;
    status.demo_console_detail.clear();
    status.demo_console_issue.clear();
    status.demo_guard_passed =
        status.demo_playing || HasResourceHandleQueryLiveLevelContext(status);

    if (g_hook_state.connect_hook_installed.load())
    {
        status.diagnostics.push_back(L"Source2Client::Connect hook is installed.");
    }

    if (g_hook_state.frame_stage_hook_installed.load())
    {
        status.diagnostics.push_back(L"Source2Client::FrameStageNotify hook is installed.");
    }

    if (!status.level_name.empty())
    {
        status.diagnostics.push_back(L"Level: " + status.level_name);
    }

    const auto runtime_issue = SnapshotRuntimeIssue();
    if (!runtime_issue.empty())
    {
        status.diagnostics.push_back(runtime_issue);
    }

    if (status.runtime_rebuilding && !status.rebuild_reason.empty())
    {
        status.diagnostics.push_back(status.rebuild_reason);
    }

    if (status.schema_bound)
    {
        status.diagnostics.push_back(L"Client schema reflection is bound.");
    }
    else
    {
        status.diagnostics.push_back(L"Client schema reflection is pending.");
    }

    if (status.entity_system_bound)
    {
        status.diagnostics.push_back(L"Client entity system scan is bound.");
    }
    else
    {
        status.diagnostics.push_back(L"Client entity system scan is pending.");
    }

    if (status.client_entity_factory_requested && status.client_entity_factory_resolved)
    {
        status.diagnostics.push_back(L"Wearable client entity factory path resolved.");
    }
    else if (status.client_entity_factory_requested)
    {
        status.diagnostics.push_back(
            L"wearable_factory_unavailable: the legacy CEconWearable compatibility fallback is unavailable until two matching FRAME_RENDER_PASS validations succeed; the current pawn m_EconGloves reapply path remains independent.");
    }

    if (status.viewmodel_factory_discovery_ran)
    {
        status.diagnostics.push_back(
            status.viewmodel_factory_observed
                ? L"Viewmodel/weapon client classes observed without a live first-person carrier instance."
                : L"Viewmodel/weapon client class discovery ran with no factory evidence.");
    }

    if (status.stable_wearable_bound)
    {
        status.diagnostics.push_back(L"Stable wearable bound");
    }

    if (status.runtime_created_wearable_bound)
    {
        status.diagnostics.push_back(L"Runtime-created wearable bound");
    }

    if (status.knife_viewmodel_sync_ready)
    {
        status.diagnostics.push_back(L"Knife world/viewmodel sync ready");
    }
    if (!status.knife_runtime_path.empty())
    {
        status.diagnostics.push_back(status.knife_runtime_path);
    }
    if (!status.knife_runtime_reason.empty())
    {
        status.diagnostics.push_back(status.knife_runtime_reason);
    }

    if (knife_refresh_policy == runtime::KnifeRefreshHelperPolicy::Disabled)
    {
        status.diagnostics.push_back(
            L"Crash guard: knife auto material refresh helper is disabled; finish-field writes remain enabled.");
    }
    else if (knife_refresh_policy == runtime::KnifeRefreshHelperPolicy::ManualOnly)
    {
        status.diagnostics.push_back(
            L"Crash guard: knife material refresh helper only runs once after Update.");
        status.diagnostics.push_back(
            knife_refresh_epoch_armed
                ? std::wstring(L"Knife refresh helper window is armed once for the current Update rebuild: ") +
                    DescribeKnifeRefreshHelperWindowState()
                : std::wstring(L"Knife refresh helper window is idle until Update: ") +
                    DescribeKnifeRefreshHelperWindowState());
    }
    else
    {
        status.diagnostics.push_back(
            L"Crash guard: knife material refresh helper only runs after Update or seek/full update.");
        status.diagnostics.push_back(
            knife_refresh_epoch_armed
                ? std::wstring(L"Knife refresh helper window is armed once for the current rebuild: ") +
                    DescribeKnifeRefreshHelperWindowState()
                : std::wstring(L"Knife refresh helper window is idle: ") +
                    DescribeKnifeRefreshHelperWindowState());
    }
    status.diagnostics.push_back(
        L"Crash guard: knife attribute-list vector growth and runtime-owned installs are disabled; fallback/in-place writes only.");

    if (status.demo_playing)
    {
        std::wstringstream demo_line;
        demo_line << L"Demo state: playing, tick=" << status.demo_tick;
        if (status.demo_paused)
        {
            demo_line << L", paused";
        }
        status.diagnostics.push_back(demo_line.str());
    }
    else
    {
        status.diagnostics.push_back(
            HasResourceHandleQueryLiveLevelContext(status)
                ? L"Demo state: engine demo flag is off; stable level context is present."
                : L"Demo state: waiting for playback.");
    }

    {
        std::wstringstream profile_line;
        profile_line << L"Profiles: enabled=" << status.enabled_profile_count;
        status.diagnostics.push_back(profile_line.str());
    }

    if (status.player_controller_count > 0 || status.player_pawn_count > 0 || status.preview_character_count > 0)
    {
        std::wstringstream entity_line;
        entity_line << L"Players: controllers=" << status.player_controller_count
            << L", pawns=" << status.player_pawn_count
            << L", previews=" << status.preview_character_count
            << L", active weapons=" << status.active_weapon_count
            << L", owned weapons=" << status.owned_weapon_count
            << L", matches=" << status.matched_profile_count
            << L", applied weapons=" << status.applied_weapon_count
            << L", applied gloves=" << status.applied_glove_count;
        status.diagnostics.push_back(entity_line.str());
    }

    AppendWeaponAppearanceTelemetry(status.diagnostics);

    if (!status.frame_callbacks_active)
    {
        status.detail = L"FrameStageNotify hook is installed, waiting for the first callback.";
        return;
    }

    if (g_hook_state.runtime_faulted.load())
    {
        const auto fault_message = runtime_issue.empty()
            ? std::wstring(L"Runtime disabled after internal exception. Use Update to retry, or unload/reload the DLL and inspect nSkinzCS2.log.")
            : runtime_issue;
        if (runtime_issue.empty())
        {
            status.diagnostics.push_back(fault_message);
        }

        status.detail = fault_message;
        status.last_error = fault_message;
        status.diagnostics.push_back(L"Runtime exception latch is active.");
        return;
    }

    if (!status.demo_playing &&
        !HasResourceHandleQueryLiveLevelContext(status))
    {
        status.detail =
            L"Source2Client frame hook is active. Waiting for demo playback or a stable level context before cosmetics are applied.";
        status.last_error.clear();
        return;
    }

    if (!status.schema_bound || !status.entity_system_bound)
    {
        status.detail = L"Demo playback detected. Binding Source 2 schema reflection and client entity access.";
        status.last_error = runtime_issue;
        return;
    }

    std::vector<std::wstring> detail_lines;
    if (status.runtime_rebuilding && !status.rebuild_reason.empty())
    {
        detail_lines.push_back(status.rebuild_reason);
    }
    if (status.stable_wearable_bound)
    {
        detail_lines.push_back(L"Stable wearable bound");
    }
    if (status.runtime_created_wearable_bound)
    {
        detail_lines.push_back(L"Runtime-created wearable bound");
    }
    if (status.knife_viewmodel_sync_ready)
    {
        detail_lines.push_back(L"Knife world/viewmodel sync ready");
    }
    if (!status.knife_runtime_path.empty())
    {
        detail_lines.push_back(status.knife_runtime_path);
    }
    if (!status.knife_runtime_reason.empty())
    {
        detail_lines.push_back(status.knife_runtime_reason);
    }
    if (status.viewmodel_factory_discovery_ran)
    {
        detail_lines.push_back(
            status.viewmodel_factory_observed
                ? L"Viewmodel/weapon client classes observed without a live instance"
                : L"Viewmodel/weapon factory evidence not observed");
    }
    if (knife_refresh_policy == runtime::KnifeRefreshHelperPolicy::Disabled)
    {
        detail_lines.push_back(L"Knife auto refresh helper disabled by crash guard");
    }
    else if (knife_refresh_policy == runtime::KnifeRefreshHelperPolicy::ManualOnly)
    {
        detail_lines.push_back(
            knife_refresh_epoch_armed
                ? L"Knife refresh helper armed for current Update window"
                : L"Knife refresh helper waiting for Update window");
    }
    else
    {
        detail_lines.push_back(
            knife_refresh_epoch_armed
                ? L"Knife refresh helper armed for current Update/seek window"
                : L"Knife refresh helper waiting for Update/seek window");
    }
    detail_lines.push_back(L"Knife attribute-list vector mutation disabled by crash guard");
    if (status.client_entity_factory_requested && !status.client_entity_factory_resolved)
    {
        detail_lines.push_back(
            L"wearable_factory_unavailable: waiting for validated CEconWearable factory");
    }
    if (detail_lines.empty())
    {
        detail_lines.push_back(L"Demo playback detected. Weapon world/viewmodel bindings are active.");
    }

    std::wstringstream detail;
    for (std::size_t index = 0; index < detail_lines.size(); ++index)
    {
        if (index != 0)
        {
            detail << L" | ";
        }
        detail << detail_lines[index];
    }
    status.detail = detail.str();
    status.last_error.clear();
}

void nskinzcs2::RuntimeController::LogStatusIfChanged(const runtime::Status& status)
{
    std::wstringstream stream;
    stream << static_cast<int>(status.availability) << L'|'
        << static_cast<int>(status.weapon_skin_refresh_state) << L'|'
        << status.detail << L'|'
        << status.last_error << L'|'
        << status.process_detected << L'|'
        << status.hlae_detected << L'|'
        << status.interfaces_resolved << L'|'
        << status.hook_installed << L'|'
        << status.frame_callbacks_active << L'|'
        << status.demo_playing << L'|'
        << status.demo_paused << L'|'
        << status.schema_bound << L'|'
        << status.entity_system_bound << L'|'
        << status.client_entity_factory_resolved << L'|'
        << status.viewmodel_factory_discovery_ran << L'|'
        << status.viewmodel_factory_observed << L'|'
        << status.knife_animation_hook_resolved << L'|'
        << status.stable_wearable_bound << L'|'
        << status.runtime_created_wearable_bound << L'|'
        << status.knife_viewmodel_sync_ready << L'|'
        << status.runtime_rebuilding << L'|'
        << status.watched_xuid << L'|'
        << status.probed_xuid << L'|'
        << status.highest_entity_index << L'|'
        << status.rebuild_reason << L'|'
        << status.level_name << L'|'
        << status.player_controller_count << L'|'
        << status.player_pawn_count << L'|'
        << status.preview_character_count << L'|'
        << status.active_weapon_count << L'|'
        << status.owned_weapon_count << L'|'
        << status.enabled_profile_count << L'|'
        << status.matched_profile_count << L'|'
        << status.applied_weapon_count << L'|'
        << status.applied_glove_count << L'|'
        << status.skipped_knife_override_count << L'|'
        << status.knife_runtime_path << L'|'
        << status.knife_runtime_reason;

    const auto current = stream.str();
    if (current == last_logged_status_)
    {
        return;
    }

    last_logged_status_ = current;

    Logger::Info(L"Runtime status: " + status.detail);
    if (!status.last_error.empty())
    {
        Logger::Warn(L"Runtime last error: " + status.last_error);
    }

    for (const auto& line : status.diagnostics)
    {
        if (line.rfind(L"Demo state: playing, tick=", 0) == 0)
        {
            continue;
        }

        Logger::Info(L"Runtime diagnostic: " + line);
    }
}

