nskinzcs2::runtime::GloveWearableCandidateProbeResult nskinzcs2::runtime::ProbeGloveWearableCandidateRankingForTests(
    const GloveWearableCandidateProbeInput& input) noexcept
{
    WearableGloveCandidate candidate {};
    switch (input.stage)
    {
    case GloveWearableCandidateProbeStage::PawnWearableHandles:
        candidate.stage = WearableGloveCandidateStage::PawnWearableHandles;
        break;
    case GloveWearableCandidateProbeStage::OwnedLiveEntities:
        candidate.stage = WearableGloveCandidateStage::OwnedLiveEntities;
        break;
    case GloveWearableCandidateProbeStage::LooseGloveRenderables:
        candidate.stage = WearableGloveCandidateStage::LooseGloveRenderables;
        break;
    }

    candidate.has_item_view = input.has_item_view;
    candidate.item_view = input.has_item_view ? reinterpret_cast<void*>(0x1) : nullptr;
    candidate.exact_glove_definition = input.exact_glove_definition;
    candidate.has_non_glove_definition = input.has_non_glove_definition;
    candidate.owner_matches_pawn = input.owner_matches_pawn;
    candidate.owner_matches_xuid = input.owner_matches_xuid;
    candidate.account_matches_xuid = input.account_matches_xuid;
    candidate.glove_renderable = input.glove_renderable;
    candidate.evaluation = EvaluateWearableGloveCandidate(candidate);

    GloveWearableCandidateProbeResult result {};
    result.accepted = candidate.evaluation.accepted;
    result.score = candidate.evaluation.score;
    result.selection_reason = candidate.evaluation.selection_reason;
    result.rejection_reason = candidate.evaluation.rejection_reason;
    return result;
}

nskinzcs2::runtime::DataFirstClientClassNodeProbeResult nskinzcs2::runtime::ProbeWearableClientClassNodeInferenceForTests(
    void* module_base,
    const std::size_t module_size,
    const char* expected_name) noexcept
{
    DataFirstClientClassNodeProbeResult result {};
    if (module_base == nullptr || module_size == 0 || expected_name == nullptr || *expected_name == '\0')
    {
        result.failure_reason = L"Test probe requires a non-null module buffer and expected name.";
        return result;
    }

    ModuleSpan synthetic_module {};
    synthetic_module.base = static_cast<std::uint8_t*>(module_base);
    synthetic_module.size = module_size;
    const std::vector<ModuleSpan> trusted_modules {synthetic_module};

    const auto names = FindAsciiStringOccurrencesInModules(trusted_modules, expected_name, 16);
    if (names.empty())
    {
        result.failure_reason = L"Expected name string was not found in the synthetic module.";
        return result;
    }

    WearableClientClassFieldProbe best_probe {};
    bool found_probe = false;
    std::wstring first_issue;
    std::size_t total_reference_count = 0;
    std::size_t readable_node_count = 0;
    std::size_t infer_attempt_count = 0;
    for (const auto* name_address : names)
    {
        const auto references = FindPointerReferencesInModules(trusted_modules, name_address, 64);
        total_reference_count += references.size();
        const auto* expected_name_pointer = static_cast<const char*>(name_address);
        for (auto* reference : references)
        {
            const auto reference_address = reinterpret_cast<std::uintptr_t>(reference);
            for (const auto name_offset : kClientClassFieldOffsetCandidates)
            {
                if (reference_address < name_offset)
                {
                    continue;
                }

                auto* node = reference - name_offset;
                if (!IsReadableClientClassNodePointer(trusted_modules, node))
                {
                    continue;
                }
                ++readable_node_count;

                for (const auto create_offset : kClientClassFieldOffsetCandidates)
                {
                    if (create_offset == name_offset)
                    {
                        continue;
                    }

                    for (const auto next_offset : kClientClassFieldOffsetCandidates)
                    {
                        if (next_offset == name_offset || next_offset == create_offset)
                        {
                            continue;
                        }

                        WearableClientClassFieldProbe probe {};
                        std::wstring candidate_issue;
                        ++infer_attempt_count;
                        if (!TryInferWearableClientClassNodeFields(
                                nullptr,
                                trusted_modules,
                                node,
                                expected_name_pointer,
                                create_offset,
                                name_offset,
                                next_offset,
                                probe,
                                &candidate_issue,
                                &synthetic_module,
                                false))
                        {
                            if (first_issue.empty() && !candidate_issue.empty())
                            {
                                first_issue = std::move(candidate_issue);
                            }
                            continue;
                        }

                        if (!found_probe || IsPreferredWearableClientClassFieldProbe(probe, best_probe))
                        {
                            best_probe = probe;
                            found_probe = true;
                        }
                    }
                }
            }
        }
    }

    if (!found_probe)
    {
        if (!first_issue.empty())
        {
            std::wstringstream stream;
            stream << L"Synthetic data-first scan found " << names.size()
                << L" name literal(s), " << total_reference_count
                << L" pointer reference(s), " << readable_node_count
                << L" readable node candidate(s), and " << infer_attempt_count
                << L" infer attempt(s). First rejection: " << first_issue;
            result.failure_reason = stream.str();
        }
        else
        {
            std::wstringstream stream;
            stream << L"Synthetic data-first scan found " << names.size()
                << L" name literal(s), " << total_reference_count
                << L" pointer reference(s), " << readable_node_count
                << L" readable node candidate(s), and " << infer_attempt_count
                << L" infer attempt(s), but did not infer a usable client class node layout.";
            result.failure_reason = stream.str();
        }
        return result;
    }

    result.success = true;
    result.client_class = best_probe.client_class;
    result.raw_create_target = best_probe.raw_create_target;
    result.create_fn_offset = best_probe.create_offset;
    result.name_offset = best_probe.name_offset;
    result.next_offset = best_probe.next_offset;
    result.chain_length = best_probe.chain_length;
    result.create_field_resolution = best_probe.create_field_resolution;
    result.resolution_method = L"data_first_test";
    return result;
}

nskinzcs2::runtime::KnifeCarrierDiscoveryDecisionProbeResult nskinzcs2::runtime::ProbeKnifeCarrierDiscoveryDecisionForTests(
    const KnifeCarrierDiscoveryDecisionProbeInput& input) noexcept
{
    KnifeCarrierDiscoveryDecisionProbeResult result {};
    result.carrier_result = ResolveKnifeCarrierDiscoveryResult(
        input.complete_candidate_found,
        input.related_incomplete_candidate_found);

    if (result.carrier_result == nskinzcs2::runtime::KnifeCarrierDiscoveryResult::RealCarrierFound)
    {
        result.factory_feasibility = nskinzcs2::runtime::KnifeCarrierFactoryFeasibility::Unknown;
        result.no_exposed_non_synthetic_render_owner = false;
        return result;
    }

    ClientClassDiscoverySummary discovery_summary {};
    discovery_summary.viewmodel_factory_observed = input.factory_observed;
    result.factory_feasibility = ResolveKnifeCarrierFactoryFeasibility(discovery_summary);
    result.no_exposed_non_synthetic_render_owner = true;
    return result;
}

nskinzcs2::runtime::KnifeCarrierPromotionProbeResult nskinzcs2::runtime::ProbeResolveKnifeCarrierPromotionForTests(
    const KnifeCarrierPromotionProbeInput& input) noexcept
{
    const auto decision =
        ResolveKnifeCarrierPromotionDecision(
            input.safe_linked_item_view,
            input.world_owned_proxy,
            input.direct_viewmodel_attachment,
            input.reverse_viewmodel_attachment,
            input.owner_chain_matches_player,
            input.exact_render_object_entity,
            input.exact_render_object_alias,
            input.shell_direct_viewmodel_attachment,
            input.shell_reverse_viewmodel_attachment,
            input.shell_owner_chain_matches_player,
            input.shell_relation_to_render_object,
            input.world_neighborhood_match,
            input.shell_world_neighborhood_match);
    KnifeCarrierPromotionProbeResult result {};
    result.promotable_relation = decision.promotable_relation;
    result.discovery_relevant = decision.discovery_relevant;
    result.accept_writable_carrier = decision.accept_writable_carrier;
    return result;
}

nskinzcs2::runtime::ClientClassDescriptorProbeResult nskinzcs2::runtime::ProbeClientClassDescriptorClassificationForTests(
    const char* class_name,
    const bool trusted_create) noexcept
{
    const auto descriptor = ClassifyClientClassDescriptor(
        class_name != nullptr ? class_name : "",
        nullptr,
        trusted_create ? reinterpret_cast<void*>(0x1) : nullptr,
        trusted_create);

    ClientClassDescriptorProbeResult result {};
    result.viewmodel_like = descriptor.viewmodel_like;
    result.weapon_like = descriptor.weapon_like;
    result.econ_like = descriptor.econ_like;
    result.factory_observed =
        descriptor.trusted_module &&
        (descriptor.viewmodel_like || descriptor.weapon_like);
    return result;
}

nskinzcs2::runtime::KnifeViewmodelAbsenceAuditResult nskinzcs2::runtime::ProbeClassifyKnifeViewmodelAbsenceAuditForTests(
    const bool field_present,
    const std::uint32_t raw_handle,
    const bool raw_entity_visible,
    const bool handle_entity_synthetic,
    const bool shared_with_render_object,
    const bool handle_entity_weapon_like,
    const bool handle_entity_item_view_safe,
    const int reverse_viewmodel_ref_count) noexcept
{
    KnifeViewmodelAbsenceAudit audit {};
    audit.ran = true;
    audit.field_present = field_present;
    audit.raw_handle = raw_handle;
    audit.raw_entity_visible = raw_entity_visible;
    audit.handle_entity_synthetic = handle_entity_synthetic;
    audit.shared_with_render_object = shared_with_render_object;
    audit.handle_entity_weapon_like = handle_entity_weapon_like;
    audit.handle_entity_has_item_view =
        raw_entity_visible &&
        (handle_entity_weapon_like ||
         handle_entity_item_view_safe ||
         shared_with_render_object ||
         reverse_viewmodel_ref_count != 0);
    audit.handle_entity_item_view_safe = handle_entity_item_view_safe;
    audit.reverse_viewmodel_ref_count = reverse_viewmodel_ref_count;
    audit.handle_entity_shell_like =
        audit.raw_entity_visible &&
        (audit.handle_entity_weapon_like ||
         audit.handle_entity_has_item_view ||
         audit.shared_with_render_object ||
         audit.reverse_viewmodel_ref_count != 0);
    return ClassifyKnifeViewmodelAbsenceAudit(audit);
}

